-- =============================================================================
-- 400 — LE CATALOGUE DES CONTRÔLES BLANCS : 3e (allemand, anglais, arts-plastiques, emc, espagnol)
--
-- 399 sujets écrits d'avance et relus : pour chaque fiche, un sujet
-- Facile, un Moyen, un Difficile, chacun avec son barème sur 20 et son corrigé
-- type (`contenu.corrige`, jamais envoyé à l'élève avant sa copie). L'IA ne fait
-- plus que les corriger ; elle ne rédige que « Un autre sujet ».
--
-- ⚠️ FICHIER GÉNÉRÉ — ne pas éditer à la main. Source : contenu/controles/.
--    Regénérer : node node_modules/jiti/lib/jiti-cli.mjs scripts/controles-sql.ts --num 400 --niveau 3e --matieres allemand,anglais,arts-plastiques,emc,espagnol
--
--   allemand.02r                 18 sujets · 6 fiches
--   allemand.05a                 45 sujets · 15 fiches
--   allemand.05r                 45 sujets · 15 fiches
--   allemand.m1                  27 sujets · 9 fiches
--   anglais.02r                  33 sujets · 11 fiches
--   anglais.03r2                  6 sujets · 2 fiches
--   anglais.03ra                 42 sujets · 14 fiches
--   anglais.03rb                 42 sujets · 14 fiches
--   arts-plastiques.08            9 sujets · 3 fiches
--   emc.08r                      30 sujets · 10 fiches
--   espagnol.02r                 12 sujets · 4 fiches
--   espagnol.04a                 45 sujets · 15 fiches
--   espagnol.04r                 45 sujets · 15 fiches
--
-- L'identifiant d'un sujet est dérivé de (fiche, niveau) : rejouer la migration
-- met le sujet à jour au lieu de le dupliquer. Une fiche absente est sautée.
--
-- PRÉREQUIS : 360 puis 364. Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

INSERT INTO public.chapter_exercices
  (id, chapter_id, style, contenu, difficulte, origine, created_by)
SELECT
  md5('exercice-catalogue:' || v.chapter_id::text || ':' || v.difficulte::text)::uuid,
  v.chapter_id,
  v.style,
  v.contenu,
  v.difficulte,
  'catalogue',
  NULL
FROM (VALUES
  ('4b75b12e-6b58-576e-8a78-c2843ce7bf9e'::uuid, 1, 'traduction', $exo${"titre":"Conjuguer au présent","consigne":"Conjugue chaque verbe au présent, à la personne demandée, puis réponds à la question.","enonce":"**1. Conjugue** au présent :\n\na) *spielen* (du)\nb) *arbeiten* (er)\nc) *heißen* (du)\nd) *fahren* (er)\ne) *lesen* (du)\nf) *geben* (sie, elle)\ng) *sammeln* (ich)\nh) *finden* (ihr)\n\n**2.** Le changement de voyelle d’un verbe fort (*fahren → fährt*) touche-t-il aussi *wir* et *sie* (ils) ? Donne un exemple.","bareme":[{"critere":"Terminaisons régulières justes : spielst","points":2},{"critere":"Aménagements justes : arbeitet, heißt, sammle, findet","points":8},{"critere":"Verbes forts justes : fährt, liest, gibt","points":6},{"critere":"Réponse : changement aux 2e et 3e personnes du singulier seulement, avec exemple","points":4}],"dureeMin":7,"corrige":"**1.**\na) *du spielst*\nb) *er arbeitet* (radical en -t : on intercale un e)\nc) *du heißt* (radical en -ß : le -st perd son s)\nd) *er fährt* (verbe fort a → ä)\ne) *du liest* (e → ie ; radical en -s : -st perd son s)\nf) *sie gibt* (e → i)\ng) *ich sammle* (radical en -el : le e tombe à la 1re personne)\nh) *ihr findet* (radical en -d : on intercale un e)\n\n**2.** Non : le changement de voyelle ne touche que les **2e et 3e personnes du singulier**. Exemple : *du fährst, er fährt*, mais *wir fahren, sie fahren*."}$exo$::jsonb),
  ('4b75b12e-6b58-576e-8a78-c2843ce7bf9e'::uuid, 2, 'traduction', $exo${"titre":"Lena se présente","consigne":"Complète la présentation de Lena au présent, puis traduis les deux phrases.","enonce":"**Situation.** Lena écrit à sa correspondante française.\n\n> Ich (1. heißen) Lena. Ich (2. lernen) seit drei Jahren Französisch. Mein Bruder Paul (3. lesen) jeden Abend und er (4. sprechen) gut Englisch. Meine Schwester (5. arbeiten) in Köln. Morgen (6. fahren) wir nach Berlin. Und du? (7. Schlafen) du am Wochenende lange?\n\n1. Écris les **sept verbes** conjugués.\n2. **Traduis** en allemand :\na) J’apprends l’allemand depuis deux ans.\nb) Demain, je vais à Munich (en train).\n3. Pourquoi n’utilise-t-on pas le futur dans la phrase b) ?","bareme":[{"critere":"Les sept formes justes : heiße, lerne, liest, spricht, arbeitet, fahren, Schläfst","points":10},{"critere":"Traduction a) au présent avec seit : Ich lerne seit zwei Jahren Deutsch","points":4},{"critere":"Traduction b) au présent, verbe en 2e position : Morgen fahre ich nach München","points":3},{"critere":"Explication : l’adverbe de temps suffit à dire l’avenir","points":3}],"dureeMin":10,"corrige":"**1.**\n1) *heiße*\n2) *lerne* (présent avec *seit*)\n3) *liest* (e → ie)\n4) *spricht* (e → i)\n5) *arbeitet* (e intercalé)\n6) *fahren* (pluriel : pas de changement de voyelle)\n7) *Schläfst* (a → ä)\n\n**2.**\na) *Ich lerne seit zwei Jahren Deutsch.* — avec *seit*, l’allemand emploie le **présent**, comme le français ; le parfait serait une faute.\nb) *Morgen fahre ich nach München.* — le verbe reste en **2e position**, le sujet passe derrière.\n\n**3.** Avec un adverbe de temps (*morgen*), le **présent suffit** à exprimer l’avenir et c’est la tournure la plus naturelle ; le futur en *werden* ne sert que sans repère temporel ou pour insister."}$exo$::jsonb),
  ('4b75b12e-6b58-576e-8a78-c2843ce7bf9e'::uuid, 3, 'traduction', $exo${"titre":"Le courriel plein de fautes","consigne":"Corrige chaque faute en expliquant la règle, puis rédige un court message en allemand.","enonce":"**Document.** Courriel de Hugo, élève de 3e, à son correspondant.\n\n> Hallo Jonas! Ich habe seit zwei Jahren Deutsch gelernt. Mein Vater fahrt jeden Tag nach Paris. Du arbeitst viel, oder? Du heißst Jonas Müller, richtig? Meine Freunde und ich fähren oft ans Meer. Morgen ich spiele Fußball.\n\n1. Hugo a fait **six fautes**, une par phrase après *Hallo Jonas!*. Recopie chaque phrase **corrigée**.\n2. Pour chaque faute, **nomme la règle** en quelques mots.\n3. **Production** (5 lignes environ) : présente-toi à Jonas. Utilise au moins un verbe fort à la 2e ou 3e personne, une phrase avec *seit* et une phrase qui parle de demain au présent.","bareme":[{"critere":"Les six phrases corrigées : lerne seit, fährt, arbeitest, heißt, fahren, Morgen spiele ich","points":6},{"critere":"Règles nommées : seit + présent, verbe fort, e intercalé, s supprimé, pluriel sans inflexion, verbe en 2e position","points":6},{"critere":"Production : terminaisons et verbes forts justes","points":4},{"critere":"Production : seit + présent et avenir au présent avec adverbe, verbe en 2e position","points":4}],"dureeMin":17,"corrige":"**1 et 2.**\n- *Ich **lerne** seit zwei Jahren Deutsch.* — avec *seit*, on emploie le **présent**, pas le parfait.\n- *Mein Vater **fährt** jeden Tag nach Paris.* — *fahren* est un verbe fort : a → ä aux 2e et 3e personnes du singulier.\n- *Du **arbeitest** viel, oder?* — radical en -t : on intercale un **e**.\n- *Du **heißt** Jonas Müller, richtig?* — radical en -ß : le -st perd son **s**.\n- *Meine Freunde und ich **fahren** oft ans Meer.* — sujet *wir* : le changement de voyelle ne touche **pas** le pluriel.\n- ***Morgen spiele ich** Fußball.* — le verbe conjugué est en **2e position** ; l’adverbe de temps suffit à dire l’avenir.\n\n**3.** Exemple : *Hallo Jonas! Ich heiße Hugo und ich lerne seit vier Jahren Deutsch. Mein Bruder liest viel und er spricht Spanisch. Meine Mutter fährt jeden Tag zur Arbeit. Morgen spiele ich Tennis.* Le correcteur vérifie les terminaisons, un verbe fort bien conjugué, *seit* + présent et un avenir au présent avec le verbe en 2e position."}$exo$::jsonb),
  ('ef0289ad-13b1-53f9-9766-e3dc59375a88'::uuid, 1, 'traduction', $exo${"titre":"Les formes du prétérit","consigne":"Donne la forme du prétérit, puis indique la famille de chaque verbe.","enonce":"**1. Mets au prétérit** :\n\na) *spielen* (ich)\nb) *gehen* (er)\nc) *kommen* (sie, elle)\nd) *sein* (ich)\ne) *haben* (er)\nf) *können* (wir)\ng) *bringen* (er)\nh) *nehmen* (ich)\n\n**2.** Pour *spielen*, *gehen* et *bringen*, indique la **famille** (faible, fort, mixte) et explique comment se forme leur prétérit.","bareme":[{"critere":"Les huit formes justes : spielte, ging, kam, war, hatte, konnten, brachte, nahm","points":12},{"critere":"Familles justes : spielen faible, gehen fort, bringen mixte","points":4},{"critere":"Formation expliquée : -te ; voyelle changée sans terminaison ; radical modifié + -te","points":4}],"dureeMin":7,"corrige":"**1.**\na) *ich spielte*\nb) *er ging*\nc) *sie kam*\nd) *ich war*\ne) *er hatte*\nf) *wir konnten* (modal : pas d’inflexion au prétérit)\ng) *er brachte*\nh) *ich nahm*\n\nAux 1re et 3e personnes du singulier, les formes sont identiques (*ich ging / er ging*).\n\n**2.**\n- *spielen* : verbe **faible** → radical + **-te** + terminaisons (*spielte*).\n- *gehen* : verbe **fort** → voyelle changée, **aucune terminaison** aux 1re et 3e personnes (*ging*).\n- *bringen* : verbe **mixte** → radical modifié + terminaisons faibles (*brachte*)."}$exo$::jsonb),
  ('ef0289ad-13b1-53f9-9766-e3dc59375a88'::uuid, 2, 'traduction', $exo${"titre":"Le samedi de Max","consigne":"Réécris le récit au prétérit, complète la phrase au plus-que-parfait, puis explique ton choix.","enonce":"**Situation.** Pour le journal du collège, tu dois raconter le samedi de Max. Voici tes notes, au présent :\n\n> Am Samstag geht Max in die Stadt. Er sieht seinen Freund Tim. Sie trinken einen Kaffee und sprechen lange. Dann kauft Max ein Buch. Am Abend schreibt er seiner Oma. Er ist sehr zufrieden.\n\n1. **Réécris** le récit au **prétérit**.\n2. Complète au plus-que-parfait : *Nachdem Max das Buch gekauft (…), ging er nach Hause.*\n3. Pourquoi faut-il employer le prétérit, et non le parfait, dans un article de journal ?","bareme":[{"critere":"Formes fortes justes : ging, sah, tranken, sprachen, schrieb, war","points":9},{"critere":"Forme faible juste : kaufte ; terminaisons du pluriel justes","points":3},{"critere":"Plus-que-parfait juste : hatte","points":3},{"critere":"Explication : prétérit = temps du récit écrit ; parfait = oral et lettre","points":5}],"dureeMin":11,"corrige":"**1.** *Am Samstag **ging** Max in die Stadt. Er **sah** seinen Freund Tim. Sie **tranken** einen Kaffee und **sprachen** lange. Dann **kaufte** Max ein Buch. Am Abend **schrieb** er seiner Oma. Er **war** sehr zufrieden.*\n\n- *gehen → ging*, *sehen → sah*, *trinken → trank* (pluriel *tranken*), *sprechen → sprach* (*sprachen*), *schreiben → schrieb* : verbes forts.\n- *kaufen → kaufte* : verbe faible.\n- *sein → war*.\n\n**2.** *Nachdem Max das Buch gekauft **hatte**, ging er nach Hause.* — prétérit de *haben* + participe II : l’achat est **antérieur** au retour.\n\n**3.** Un article de journal est un **texte narratif écrit** : on y raconte au **prétérit**. Le parfait est le passé de l’oral et de la lettre ; mélanger les deux dans un même récit fait désordre."}$exo$::jsonb),
  ('ef0289ad-13b1-53f9-9766-e3dc59375a88'::uuid, 3, 'traduction', $exo${"titre":"Une journée d’hiver","consigne":"Conjugue le récit, traduis, puis justifie les choix de temps avec les règles du cours.","enonce":"**Document.** Début d’une nouvelle, verbes à l’infinitif.\n\n> Es (1. sein) kalt. Anna (2. bleiben) zu Hause und (3. schreiben) einen Brief. Nachdem sie den Brief geschrieben (4. haben), (5. gehen) sie zur Post. Dort (6. finden) sie ihren Freund Paul. Er (7. wollen) einen Kaffee trinken. Sie (8. trinken) zusammen einen Kaffee und (9. denken) an die Ferien.\n\n1. Conjugue les **neuf verbes** : prétérit partout, plus-que-parfait pour (4).\n2. **Traduis** en allemand, pour la suite de la nouvelle : *Il faisait nuit et Anna était fatiguée. Elle ne pouvait pas dormir.*\n3. Pourquoi l’imparfait français devient-il ici un prétérit ? Aurait-on dit la même chose dans un dialogue ?\n4. À l’oral, Anna dit *Ich bin müde gewesen*. Est-ce faux ? Que dirait-on plutôt ?","bareme":[{"critere":"Formes justes : war, blieb, schrieb, ging, fand, wollte, tranken, dachten","points":6},{"critere":"Plus-que-parfait juste (hatte) et antériorité expliquée","points":3},{"critere":"Traduction juste : Es war dunkel (Nacht) und Anna war müde. Sie konnte nicht schlafen","points":5},{"critere":"Règle de registre : prétérit dans un récit écrit, parfait dans un dialogue","points":4},{"critere":"Ich war müde, ce que tout le monde dit (sein survit au prétérit à l’oral)","points":2}],"dureeMin":17,"corrige":"**1.** *Es **war** kalt. Anna **blieb** zu Hause und **schrieb** einen Brief. Nachdem sie den Brief geschrieben **hatte**, **ging** sie zur Post. Dort **fand** sie ihren Freund Paul. Er **wollte** einen Kaffee trinken. Sie **tranken** zusammen einen Kaffee und **dachten** an die Ferien.*\n\n(*denken → dachte* est un verbe mixte ; *wollen → wollte* un modal ; le plus-que-parfait *hatte geschrieben* marque ce qui s’est passé **avant** le départ pour la poste.)\n\n**2.** *Es war Nacht (Es war dunkel) und Anna war müde. Sie konnte nicht schlafen.* — *sein → war*, *können → konnte*.\n\n**3.** L’allemand oppose parfait et prétérit par le **registre**, pas par l’aspect : dans un **récit écrit**, tout passé se dit au prétérit, y compris ce que le français met à l’imparfait. Dans un **dialogue**, on aurait employé le **parfait** (sauf pour *sein, haben, werden* et les modaux).\n\n**4.** Ce n’est pas faux, mais tout le monde dit ***Ich war müde*** : *sein*, *haben*, *werden* et les modaux restent au prétérit même à l’oral."}$exo$::jsonb),
  ('7435e27a-38d0-58f2-9f8f-342b80bf673d'::uuid, 1, 'traduction', $exo${"titre":"Participes et auxiliaires","consigne":"Forme le participe II de chaque verbe, puis choisis l’auxiliaire.","enonce":"**1. Donne le participe II** :\n\na) *spielen* · b) *machen* · c) *sehen* · d) *fahren* · e) *studieren* · f) *besuchen* · g) *einkaufen* · h) *aufstehen*\n\n**2. Choisis l’auxiliaire** (*haben* ou *sein*) et complète :\n\na) Ich … nach Hause gegangen.\nb) Wir … Pizza gegessen.\nc) Er … sofort eingeschlafen.\nd) Sie … zu Hause geblieben.\ne) Ihr … Fußball gespielt.\nf) Was … passiert?","bareme":[{"critere":"Participes justes : gespielt, gemacht, gesehen, gefahren, studiert, besucht, eingekauft, aufgestanden","points":10},{"critere":"Auxiliaires justes : bin, haben, ist, ist, habt, ist","points":10}],"dureeMin":8,"corrige":"**1.**\na) *gespielt* · b) *gemacht* (faibles : ge- + radical + -t)\nc) *gesehen* · d) *gefahren* (forts : ge- + radical + -en)\ne) *studiert* (en -ieren : pas de ge-)\nf) *besucht* (préverbe inséparable : pas de ge-)\ng) *eingekauft* · h) *aufgestanden* (préverbe séparable : le ge- s’intercale)\n\n**2.**\na) Ich **bin** nach Hause gegangen. (déplacement)\nb) Wir **haben** Pizza gegessen.\nc) Er **ist** sofort eingeschlafen. (changement d’état)\nd) Sie **ist** (ou **sind**) zu Hause geblieben. (*bleiben* prend sein)\ne) Ihr **habt** Fußball gespielt.\nf) Was **ist** passiert? (*passieren* prend sein)"}$exo$::jsonb),
  ('7435e27a-38d0-58f2-9f8f-342b80bf673d'::uuid, 2, 'traduction', $exo${"titre":"Le week-end de Jonas","consigne":"Mets le message de Jonas au parfait, en respectant l’ordre des mots, puis complète la subordonnée.","enonce":"**Situation.** Jonas raconte son week-end à son ami Ben, dans un message. Ses notes sont au présent :\n\n> Am Samstag stehe ich um 9 Uhr auf. Dann fahre ich mit dem Zug nach Hamburg. Dort besuche ich meine Oma. Wir essen Kuchen und spielen Karten. Am Abend bleibe ich bei ihr.\n\n1. **Réécris** le message au **parfait**.\n2. Complète au parfait : *Ich bin müde, weil ich viel (lernen).*\n3. Pourquoi Jonas raconte-t-il au parfait et pas au prétérit ?","bareme":[{"critere":"Auxiliaires justes : bin aufgestanden, bin gefahren, bin geblieben ; habe besucht, haben gegessen/gespielt","points":8},{"critere":"Participes justes (aufgestanden, gefahren, besucht, gegessen, gespielt, geblieben)","points":5},{"critere":"Participe en fin de phrase, auxiliaire en 2e position ; subordonnée : gelernt habe","points":4},{"critere":"Explication : le parfait est le passé de la conversation et du message","points":3}],"dureeMin":11,"corrige":"**1.** *Am Samstag **bin** ich um 9 Uhr **aufgestanden**. Dann **bin** ich mit dem Zug nach Hamburg **gefahren**. Dort **habe** ich meine Oma **besucht**. Wir **haben** Kuchen **gegessen** und Karten **gespielt**. Am Abend **bin** ich bei ihr **geblieben**.*\n\n- *aufstehen* (changement d’état), *fahren* (déplacement), *bleiben* → **sein**.\n- *besuchen* : inséparable, pas de ge- ; *aufstehen* : séparable, ge- intercalé.\n- Auxiliaire en **2e position**, participe **à la fin**.\n\n**2.** *Ich bin müde, weil ich viel **gelernt habe**.* — en subordonnée, l’auxiliaire va **à la toute fin**, après le participe.\n\n**3.** Un message à un ami, c’est de la **conversation** écrite : on raconte au **parfait**. Le prétérit est le temps du récit écrit (roman, presse)."}$exo$::jsonb),
  ('7435e27a-38d0-58f2-9f8f-342b80bf673d'::uuid, 3, 'traduction', $exo${"titre":"La copie à corriger","consigne":"Repère les phrases fausses et corrige-les en citant la règle, puis traduis et explique.","enonce":"**Document.** Sept phrases tirées de la copie de Léo.\n\n> a) Ich habe nach Berlin gefahren.\n> b) Er hat mit seiner Oma getelefoniert.\n> c) Wir haben im Supermarkt geeinkauft.\n> d) Ich habe das Auto in die Garage gefahren.\n> e) Ich bin müde, weil ich habe den ganzen Tag gearbeitet.\n> f) Was ist gestern passiert?\n> g) Sie hat früh eingeschlafen.\n\n1. **Deux** phrases sont justes : lesquelles ? Justifie.\n2. **Corrige** les cinq autres en citant la règle.\n3. **Traduis**, pour un message à un ami : *Hier, je suis resté à la maison et j’ai lu un livre. Ma sœur s’est endormie tôt.*\n4. *Il pleuvait* se traduit-il de la même façon dans un dialogue et dans un roman ? Explique.","bareme":[{"critere":"Phrases justes identifiées (d et f) et justifiées : emploi transitif ; passieren prend sein","points":4},{"critere":"Corrections : bin gefahren, telefoniert, eingekauft, gearbeitet habe, ist eingeschlafen","points":6},{"critere":"Traduction juste : bin geblieben, habe gelesen, ist eingeschlafen, participes en fin","points":6},{"critere":"Registre expliqué : parfait dans un dialogue, prétérit dans un roman","points":4}],"dureeMin":17,"corrige":"**1.** **d)** est juste : *fahren* est employé **transitivement** (il a un complément, *das Auto*), il prend donc **haben**. **f)** est juste : *passieren* fait partie des six verbes à part qui prennent **sein**.\n\n**2.**\na) *Ich **bin** nach Berlin gefahren.* — déplacement d’un point à un autre : **sein**.\nb) *Er hat mit seiner Oma **telefoniert**.* — verbe en -ieren : **pas de ge-**.\nc) *Wir haben im Supermarkt **eingekauft**.* — préverbe séparable : le ge- **s’intercale**.\ne) *…, weil ich den ganzen Tag **gearbeitet habe**.* — en subordonnée, l’auxiliaire va **à la toute fin**.\ng) *Sie **ist** früh eingeschlafen.* — changement d’état : **sein**.\n\n**3.** *Gestern bin ich zu Hause geblieben und habe ein Buch gelesen. Meine Schwester ist früh eingeschlafen.* — *bleiben* et *einschlafen* prennent sein ; *lesen* (fort) donne *gelesen*.\n\n**4.** Non. L’allemand distingue parfait et prétérit par le **registre** : dans un **dialogue**, *Es hat geregnet* (parfait) ; dans un **roman**, *Es regnete* (prétérit). Le français, lui, oppose imparfait et passé composé par l’**aspect**."}$exo$::jsonb),
  ('a82490ac-3425-5595-91bb-714161fb7cdf'::uuid, 1, 'traduction', $exo${"titre":"Werden au futur","consigne":"Mets les phrases au Futur I, puis indique ce qu’exprime werden dans chaque phrase de la partie 2.","enonce":"**1. Mets au Futur I** :\n\na) Ich helfe dir.\nb) Du kommst nicht.\nc) Er schreibt einen Brief.\nd) Wir spielen Fußball.\ne) Ihr lernt viel.\nf) Sie (ils) fahren nach Wien.\n\n**2.** Que signifie *werden* dans chaque phrase : « devenir », futur ou passif ?\n\na) *Er wird Arzt.*\nb) *Das Haus wird gebaut.*\nc) *Er wird kommen.*","bareme":[{"critere":"Formes de werden justes : werde, wirst, wird, werden, werdet, werden","points":6},{"critere":"Infinitif placé en fin de phrase dans les six phrases","points":6},{"critere":"Les trois valeurs identifiées d’après ce qui suit werden","points":8}],"dureeMin":7,"corrige":"**1.**\na) *Ich **werde** dir **helfen**.*\nb) *Du **wirst** nicht **kommen**.*\nc) *Er **wird** einen Brief **schreiben**.*\nd) *Wir **werden** Fußball **spielen**.*\ne) *Ihr **werdet** viel **lernen**.*\nf) *Sie **werden** nach Wien **fahren**.*\n\n*werden* conjugué en 2e position, **infinitif à la fin**.\n\n**2.** C’est ce qui **suit** *werden* qui tranche :\na) un **nom** → « **devenir** » : il devient médecin.\nb) un **participe II** → **passif** : la maison est construite.\nc) un **infinitif** → **futur** : il viendra."}$exo$::jsonb),
  ('a82490ac-3425-5595-91bb-714161fb7cdf'::uuid, 2, 'traduction', $exo${"titre":"Les projets d’Emma","consigne":"Choisis entre présent et futur, justifie, puis traite la subordonnée et la supposition.","enonce":"**Situation.** Emma écrit à son amie Clara.\n\n> a) Morgen (fahren) ich nach Hamburg.\n> b) Keine Sorge, ich (helfen) dir! (une promesse, sans repère de temps)\n> c) Die Prüfung (sein) nicht einfach. (une prédiction)\n> d) Nächste Woche (schreiben) ich die Mathearbeit.\n\n1. Pour chaque phrase, choisis **présent** ou **Futur I**, conjugue et justifie.\n2. Complète au futur : *Ich hoffe, dass Tim (kommen).*\n3. Clara répond : *« Tim antwortet nicht. Er wird wohl krank sein. »* Traduis la seconde phrase et explique le piège.","bareme":[{"critere":"a) fahre et d) schreibe au présent, justifiés par l’adverbe de temps","points":5},{"critere":"b) werde helfen et c) wird sein au futur, justifiés (promesse, prédiction)","points":5},{"critere":"Subordonnée juste : dass Tim kommen wird (werden à la fin)","points":4},{"critere":"Supposition traduite : Il doit être malade ; ce n’est pas un futur","points":6}],"dureeMin":11,"corrige":"**1.**\na) *Morgen **fahre** ich nach Hamburg.* — **présent** : l’adverbe *morgen* suffit à dire l’avenir.\nb) *Ich **werde** dir **helfen**!* — **futur** : une promesse, sans repère de temps.\nc) *Die Prüfung **wird** nicht einfach **sein**.* — **futur** : une prédiction.\nd) *Nächste Woche **schreibe** ich die Mathearbeit.* — **présent** : *nächste Woche* précise l’avenir.\n(Le futur en a et d n’est pas faux, seulement plus lourd.)\n\n**2.** *Ich hoffe, dass Tim kommen **wird**.* — en subordonnée, les deux morceaux se rejoignent à la fin et c’est *werden* qui ferme.\n\n**3.** *« Il **doit** être malade. »* Ce futur renforcé par *wohl* exprime une **hypothèse sur le présent**, pas l’avenir ; traduire « il sera malade » est un contresens."}$exo$::jsonb),
  ('a82490ac-3425-5595-91bb-714161fb7cdf'::uuid, 3, 'traduction', $exo${"titre":"Les mille visages de werden","consigne":"Analyse et traduis chaque phrase, transforme la subordonnée, puis rédige tes projets.","enonce":"**1. Analyse et traduis** : pour chaque phrase, dis ce qu’exprime *werden* (devenir, futur, passif, supposition, insistance), puis traduis.\n\na) *Sie wird Lehrerin.*\nb) *Die Stadt wird renoviert.*\nc) *Er wird wohl zu Hause sein.*\nd) *Er wird es vergessen haben.*\ne) *Du wirst jetzt aufräumen!*\nf) *Das wird nicht einfach sein.*\n\n**2. Transforme** en subordonnée introduite par *dass* : *Ich glaube: Er wird morgen kommen.*\n\n**3. Production** (5 lignes environ) : écris tes projets pour les prochaines vacances. Emploie au moins **deux** fois le présent avec un adverbe de temps, et **deux** fois le Futur I (une promesse, une prédiction).","bareme":[{"critere":"Valeurs identifiées d’après ce qui suit werden (devenir, passif, supposition, Futur II, insistance, prédiction)","points":6},{"critere":"Traductions justes, sans contresens sur c) et d)","points":5},{"critere":"Subordonnée juste : dass er morgen kommen wird","points":3},{"critere":"Production : présent avec adverbe et Futur I bien formé (werden + infinitif final)","points":6}],"dureeMin":17,"corrige":"**1.**\na) Nom après *werden* → **devenir** : *Elle devient professeure.*\nb) Participe II → **passif** : *La ville est rénovée.*\nc) Futur + *wohl* → **supposition** sur le présent : *Il doit être à la maison.*\nd) Futur II → **supposition** sur le passé : *Il a dû l’oublier.*\ne) Futur → **insistance**, presque une menace : *Tu vas ranger, maintenant !*\nf) Futur → **prédiction** : *Ça ne sera pas facile.*\n\n**2.** *Ich glaube, dass er morgen kommen **wird**.* — *werden* conjugué ferme la subordonnée, après l’infinitif.\n\n**3.** Exemple : *Nächsten Sommer fahre ich nach Österreich. Am ersten Tag besuche ich Wien. Ich werde dir jeden Tag schreiben, versprochen! Das wird bestimmt toll sein.* Le correcteur vérifie le présent avec *nächsten Sommer, morgen…*, le verbe en 2e position, et deux Futur I justes (*werde… schreiben*, *wird… sein*), infinitif en fin de phrase."}$exo$::jsonb),
  ('8ddb8658-38c9-5fad-bcfd-9f0a258ecbec'::uuid, 1, 'traduction', $exo${"titre":"Donner un ordre à chacun","consigne":"Forme l’impératif demandé, sans oublier le pronom quand il le faut.","enonce":"**1. Forme l’impératif** de *kommen* pour **du**, **ihr** et **Sie**.\n\n**2. Forme l’impératif** pour **du** :\n\na) *geben* (mir das Buch)\nb) *fahren* (langsam)\nc) *arbeiten* (mehr)\nd) *lesen* (den Text)\ne) *nehmen* (den Bus)\n\n**3.** Donne l’impératif de *sein* (*ruhig sein*) pour **du**, **ihr** et **Sie**.","bareme":[{"critere":"kommen juste : Komm! Kommt! Kommen Sie!","points":5},{"critere":"Formes du juste : Gib! Fahr! Arbeite! Lies! Nimm!","points":10},{"critere":"sein juste : Sei ruhig! Seid ruhig! Seien Sie ruhig!","points":5}],"dureeMin":7,"corrige":"**1.** *Komm!* (du : radical, sans terminaison ni pronom) · *Kommt!* (ihr : forme du présent, sans pronom) · *Kommen Sie!* (Sie : infinitif + pronom).\n\n**2.**\na) *Gib mir das Buch!* — l’alternance e → i se **garde**.\nb) *Fahr langsam!* — l’alternance a → ä se **perd** (pas « Fähr »).\nc) *Arbeite mehr!* — le -e final est **obligatoire** après -t.\nd) *Lies den Text!* — e → ie gardé.\ne) *Nimm den Bus!* — e → i gardé.\n\n**3.** *Sei ruhig!* · *Seid ruhig!* · *Seien Sie ruhig!* — *sein* est à part."}$exo$::jsonb),
  ('8ddb8658-38c9-5fad-bcfd-9f0a258ecbec'::uuid, 2, 'traduction', $exo${"titre":"Le départ en classe verte","consigne":"Transforme chaque consigne en impératif, à la personne indiquée, en ajoutant bitte quand c’est demandé.","enonce":"**Situation.** Le jour du départ en classe verte, Frau Keller, la professeure, et les élèves se donnent des consignes.\n\n1. À ton camarade Paul (**du**) :\na) *aufstehen* (+ bitte)\nb) *mich heute Abend anrufen*\nc) *langsam fahren* (à vélo)\n\n2. À toute la classe (**ihr**) :\nd) *leise sein*\ne) *die Koffer nehmen*\n\n3. À Frau Keller (**Sie**) :\nf) *die Tür zumachen* (+ bitte)\n\n4. À tout le groupe, toi compris (**wir**) :\ng) *gehen*\n\n5. Où se place le préverbe séparable à l’impératif ? Appuie-toi sur a), b) et f).","bareme":[{"critere":"Formes du justes : Steh bitte auf! Ruf mich heute Abend an! Fahr langsam!","points":6},{"critere":"Formes ihr justes : Seid leise! Nehmt die Koffer!","points":4},{"critere":"Formes Sie et wir justes : Machen Sie bitte die Tür zu! Gehen wir!","points":4},{"critere":"Règle : verbe en 1re position, préverbe séparable rejeté à la fin","points":6}],"dureeMin":11,"corrige":"**1.**\na) *Steh bitte auf!*\nb) *Ruf mich heute Abend an!*\nc) *Fahr langsam!* (a → ä se perd)\n\n**2.**\nd) *Seid leise!* (*sein* est à part)\ne) *Nehmt die Koffer!* (forme du présent, sans pronom)\n\n**3.**\nf) *Machen Sie bitte die Tür zu!* (infinitif + *Sie*)\n\n**4.**\ng) *Gehen wir!* (« allons-y »)\n\n**5.** Le verbe **ouvre** la phrase, en première position, et le préverbe séparable (*auf*, *an*, *zu*) part **à la fin** de la phrase. *bitte* se place juste après le verbe (ou le pronom *Sie*)."}$exo$::jsonb),
  ('8ddb8658-38c9-5fad-bcfd-9f0a258ecbec'::uuid, 3, 'traduction', $exo${"titre":"Ordres secs, ordres polis","consigne":"Adoucis, corrige et analyse les ordres, en justifiant avec les règles du cours.","enonce":"**Document 1.** Mot laissé par Anna à son frère Tom :\n\n> Mach das Fenster zu! Räum dein Zimmer auf! Gib mir mein Buch!\n\n**Document 2.** Cinq ordres écrits par un élève :\n\n> a) Fähr langsam! · b) Gebe mir das! · c) Arbeit! · d) Kommst du! · e) Sei ruhig, Herr Braun!\n\n1. Tom trouve le mot d’Anna **hostile**. Explique pourquoi, puis **réécris-le** avec *bitte*, *mal* ou *doch* (une particule différente par phrase).\n2. **Corrige** les cinq ordres du document 2 en expliquant chaque faute.\n3. Anna veut demander à sa voisine, Frau Schulz, de l’aider, le plus poliment possible. Écris la phrase.\n4. Quel est le registre de *Nicht rauchen!* et de *Du wirst jetzt lernen!* ?","bareme":[{"critere":"Explication : sans particules un impératif paraît sec ; trois phrases adoucies justes","points":5},{"critere":"Corrections : Fahr! Gib mir das! Arbeite! Komm! Seien Sie ruhig, Herr Braun!","points":7},{"critere":"Demande très polie juste : Könnten Sie mir helfen?","points":4},{"critere":"Registres : infinitif = panneaux, consignes ; futur = menaçant","points":4}],"dureeMin":16,"corrige":"**1.** Sans les petits mots *bitte, mal, doch*, un impératif allemand paraît **sec**, parfois hostile. Réécriture possible : *Mach bitte das Fenster zu! Räum doch dein Zimmer auf! Gib mir mal mein Buch!* — *bitte* ajoute la politesse, *doch* l’insistance amicale, *mal* la légèreté.\n\n**2.**\na) ***Fahr** langsam!* — l’alternance a → ä se **perd** à l’impératif.\nb) ***Gib** mir das!* — l’alternance e → i se **garde**.\nc) ***Arbeite**!* — -e final **obligatoire** après -t.\nd) ***Komm**!* — pour *du* : radical sans terminaison, **sans pronom**.\ne) ***Seien Sie** ruhig, Herr Braun!* — on vouvoie un adulte : forme *Sie*, avec le pronom ; *sein* est à part.\n\n**3.** *Könnten Sie mir bitte helfen, Frau Schulz?* — la question au **subjonctif II** est le registre **très poli**.\n\n**4.** *Nicht rauchen!* : l’infinitif seul, registre des **panneaux et consignes**. *Du wirst jetzt lernen!* : le futur, registre **menaçant**."}$exo$::jsonb),
  ('acebc17f-d953-5af6-8129-008553b71d05'::uuid, 1, 'traduction', $exo${"titre":"Wäre, hätte, würde","consigne":"Donne la forme de subjonctif II, puis mets les phrases au subjonctif II.","enonce":"**1. Donne le subjonctif II** (1re personne du singulier) de :\n\na) *sein* · b) *haben* · c) *können* · d) *müssen* · e) *wissen* · f) *mögen* · g) *werden*\n\n**2. Mets au subjonctif II** avec *würde* + infinitif :\n\na) Ich fahre gern nach Berlin.\nb) Wir spielen gern Tennis.\n\n**3.** À partir de quel temps se forment les formes simples ? Donne un exemple.","bareme":[{"critere":"Les sept formes justes : wäre, hätte, könnte, müsste, wüsste, möchte, würde","points":10},{"critere":"würde + infinitif final juste dans les deux phrases","points":6},{"critere":"Formation expliquée : prétérit + inflexion + -e, avec exemple","points":4}],"dureeMin":7,"corrige":"**1.**\na) *wäre* · b) *hätte* · c) *könnte* · d) *müsste* · e) *wüsste* · f) *möchte* · g) *würde*\n\n**2.**\na) *Ich **würde** gern nach Berlin **fahren**.*\nb) *Wir **würden** gern Tennis **spielen**.*\n*würde* est la construction **par défaut** pour la plupart des verbes ; l’infinitif va à la fin.\n\n**3.** Les formes simples se forment sur le **prétérit**, avec **inflexion** et un *-e* : *war → wäre*, *hatte → hätte*, *konnte → könnte*."}$exo$::jsonb),
  ('acebc17f-d953-5af6-8129-008553b71d05'::uuid, 2, 'traduction', $exo${"titre":"Au café, et si…","consigne":"Rends les demandes polies, puis transforme les faits en hypothèses irréelles.","enonce":"**Situation.** Au café, à Munich, Jules parle trop sèchement au serveur.\n\n1. Rends chaque phrase **polie** avec le subjonctif II :\na) *Ich will einen Kaffee.*\nb) *Können Sie mir helfen?*\nc) *Ich will zahlen.*\n\n2. En sortant, Jules se plaint. **Transforme** chaque paire de phrases en une hypothèse irréelle avec *wenn* :\nd) *Ich habe keine Zeit. Ich komme nicht mit.*\ne) *Das Wetter ist schlecht. Wir gehen nicht schwimmen.*\nf) *Ich habe kein Geld. Ich kaufe das Fahrrad nicht.*\n\n3. Pourquoi *Ich will einen Kaffee* est-il maladroit ?","bareme":[{"critere":"Demandes polies : Ich hätte gern einen Kaffee ; Könnten Sie mir helfen? ; Ich möchte bitte zahlen","points":6},{"critere":"Subordonnées justes : wenn + subjonctif II, verbe à la fin (hätte, wäre)","points":5},{"critere":"Principales justes : würde + infinitif, verbe en tête après la subordonnée","points":5},{"critere":"Explication : le présent de wollen sonne comme un ordre","points":4}],"dureeMin":11,"corrige":"**1.**\na) *Ich **hätte** gern einen Kaffee.* (ou *Ich **möchte** einen Kaffee.*)\nb) ***Könnten** Sie mir helfen?*\nc) *Ich **möchte** bitte zahlen.*\nPour la politesse, on préfère la **forme simple**.\n\n**2.**\nd) *Wenn ich Zeit **hätte**, **würde** ich **mitkommen**.*\ne) *Wenn das Wetter schön **wäre**, **würden** wir schwimmen **gehen**.* (ou *nicht schlecht wäre*)\nf) *Wenn ich Geld **hätte**, **würde** ich das Fahrrad **kaufen**.*\nDans la subordonnée, le verbe conjugué est **à la fin** ; la principale commence par le verbe (*würde*).\n\n**3.** *Ich will einen Kaffee* sonne comme un **ordre** ; *Ich hätte gern einen Kaffee* comme une **demande**. Le subjonctif II est la forme quotidienne de la politesse."}$exo$::jsonb),
  ('acebc17f-d953-5af6-8129-008553b71d05'::uuid, 3, 'traduction', $exo${"titre":"Si j’avais une année libre","consigne":"Transforme, complète, identifie les modes, puis rédige un paragraphe à l’irréel.","enonce":"**1. Supprime** *wenn* dans ces phrases, sans changer leur sens :\na) *Wenn ich Zeit hätte, würde ich kommen.*\nb) *Wenn das Wetter schön wäre, würden wir wandern.*\n\n**2. Complète** avec le subjonctif II :\nc) *Er tut so, als ob er alles (wissen).*\nd) *Sie spricht, als ob sie Deutsche (sein).*\ne) Ton ami est toujours fatigué. Donne-lui un **conseil** : *Du (sollen) mehr schlafen.*\n\n**3.** Dans un journal, tu lis : *Der Minister sagte, er sei krank.* Quel est le mode de *sei* ? À quoi sert-il ?\n\n**4. Production** (5 lignes environ) : *Wenn ich ein Jahr frei hätte…* Raconte ce que tu ferais. Emploie au moins **quatre** subjonctifs II (dont une forme simple et *würde*) et une phrase sans *wenn*.","bareme":[{"critere":"Phrases sans wenn justes : Hätte ich Zeit, würde ich kommen ; Wäre das Wetter schön, würden wir wandern","points":4},{"critere":"Formes justes : wüsste, wäre, solltest","points":4},{"critere":"Subjonctif I reconnu : discours indirect de la presse","points":3},{"critere":"Production : quatre subjonctifs II justes (forme simple et würde), verbe à la fin après wenn","points":6},{"critere":"Production : une phrase sans wenn, verbe en première place","points":3}],"dureeMin":17,"corrige":"**1.**\na) ***Hätte** ich Zeit, würde ich kommen.*\nb) ***Wäre** das Wetter schön, würden wir wandern.*\nQuand *wenn* disparaît, le verbe prend la **première place** : tournure élégante, valorisée à l’écrit.\n\n**2.**\nc) *…, als ob er alles **wüsste**.* — après *als ob*, le subjonctif II est de règle.\nd) *…, als ob sie Deutsche **wäre**.*\ne) *Du **solltest** mehr schlafen.* — *solltest* exprime le **conseil**.\n\n**3.** *sei* est un **subjonctif I** : il sert au **discours indirect de la presse** (on rapporte les paroles du ministre sans les prendre à son compte). Il suffit de le reconnaître.\n\n**4.** Exemple : *Wenn ich ein Jahr frei hätte, würde ich um die Welt reisen. Ich würde zuerst nach Kanada fliegen. Dort könnte ich Englisch lernen. Hätte ich genug Geld, würde ich auch Japan besuchen. Das wäre toll!* Le correcteur vérifie au moins une forme simple (*hätte, wäre, könnte…*), *würde* + infinitif final, le verbe à la fin après *wenn*, et une phrase sans *wenn* avec le verbe en tête."}$exo$::jsonb),
  ('d4002fe0-91d7-56ae-b36b-981cef0e2b98'::uuid, 1, 'traduction', $exo${"titre":"Cinq phrases à ponctuer","consigne":"Recopie chaque phrase en plaçant les virgules là où l'allemand les exige, puis réponds à la question 2.","enonce":"**1. Recopie en ajoutant les virgules nécessaires.**\n\n1. Ich weiß dass du morgen kommst.\n2. Er ist müde aber glücklich.\n3. Ich kaufe Brot Milch und Käse.\n4. Sie lernt Deutsch um in Wien zu studieren.\n5. Das Buch das ich lese ist spannend.\n\n**2.** Dans la phrase 3, explique en une phrase pourquoi on ne met pas de virgule devant *und*.","bareme":[{"critere":"Virgules justes devant dass, aber et um… zu (phrases 1, 2, 4)","points":9},{"critere":"Relative enchâssée encadrée de deux virgules (phrase 5)","points":4},{"critere":"Énumération de la phrase 3 sans virgule devant und","points":3},{"critere":"Explication juste de l'absence de virgule devant und","points":4}],"dureeMin":6,"corrige":"**1. Phrases corrigées**\n\n1. *Ich weiß, dass du morgen kommst.* — virgule obligatoire devant une subordonnée.\n2. *Er ist müde, aber glücklich.* — virgule devant *aber*.\n3. *Ich kaufe Brot, Milch und Käse.* — virgule entre Brot et Milch, **pas** devant *und*.\n4. *Sie lernt Deutsch, um in Wien zu studieren.* — le groupe *um… zu* exige la virgule.\n5. *Das Buch, das ich lese, ist spannend.* — la relative enchâssée est encadrée des **deux** côtés.\n\n**2.** En allemand, la virgule marque une frontière grammaticale : *und* relie deux éléments de même rang dans une énumération, et en principe on ne met pas de virgule devant *und* (ni devant *oder*)."}$exo$::jsonb),
  ('d4002fe0-91d7-56ae-b36b-981cef0e2b98'::uuid, 2, 'traduction', $exo${"titre":"Le message de Léa à corriger","consigne":"Léa a écrit ce message sans respecter l'orthographe allemande. Recopie-le en corrigeant les majuscules, la ponctuation, les guillemets et les s / ß, puis réponds à la question 2.","enonce":"**1. Recopie le texte corrigé.**\n\n> gestern habe ich im park meinen freund tom getroffen. er sagt „ich komme morgen mit.“ ich hoffe dass er pünktlich ist. wir wollen die strasse entlang bis zum fluß laufen.\n\n**2.** Explique en français pourquoi on écrit *Straße* avec ß, mais *Fluss* avec ss.","bareme":[{"critere":"Majuscules aux noms communs (Park, Freund, Straße, Fluss) et en début de phrase","points":6},{"critere":"Deux-points avant le discours direct et guillemets allemands conservés","points":4},{"critere":"Virgule devant la subordonnée en dass","points":3},{"critere":"Graphies Straße et Fluss corrigées","points":3},{"critere":"Explication juste : ß après voyelle longue, ss après voyelle brève","points":4}],"dureeMin":10,"corrige":"**1. Texte corrigé**\n\n> *Gestern habe ich im Park meinen Freund Tom getroffen. Er sagt: „Ich komme morgen mit.“ Ich hoffe, dass er pünktlich ist. Wir wollen die Straße entlang bis zum Fluss laufen.*\n\nPoints attendus :\n- Majuscule à **tous** les noms communs : *Park*, *Freund*, *Straße*, *Fluss* (et bien sûr au prénom *Tom* et en début de phrase : *Gestern*, *Er*, *Ich*, *Wir*).\n- Deux-points avant le discours direct (*Er sagt:*), guillemets ouverts en bas et fermés en haut, et majuscule au début de la parole rapportée (*Ich komme…*).\n- Virgule obligatoire devant *dass*.\n\n**2.** On écrit **ß** après une voyelle longue ou une diphtongue : le *a* de *Straße* est long. On écrit **ss** après une voyelle brève : le *u* de *Fluss* est bref. *Fluß* est donc une faute (ancienne orthographe)."}$exo$::jsonb),
  ('d4002fe0-91d7-56ae-b36b-981cef0e2b98'::uuid, 3, 'traduction', $exo${"titre":"Thème : ponctuer et écrire juste","consigne":"Traduis les quatre phrases en allemand en respectant la ponctuation et les majuscules allemandes, puis réponds à la question 2.","enonce":"**1. Traduis en allemand.**\n\n1. Il dit : « Je sais qu'elle vient. »\n2. Madame Weber, je vous remercie.\n3. La ville que je visite est belle mais chère.\n4. J'apprends l'allemand pour lire des livres.\n\n*Aide : danken + datif ; besuchen = visiter ; schön = beau ; teuer = cher ; das Buch, die Bücher.*\n\n**2.** Quelle est la différence de sens entre *Können Sie mir helfen?* et *Können sie mir helfen?* Explique pourquoi.","bareme":[{"critere":"Virgules justes : dass, relative enchâssée, aber, um… zu","points":6},{"critere":"Deux-points et guillemets allemands au discours direct","points":3},{"critere":"Majuscules : noms communs, Ihnen de politesse","points":4},{"critere":"Ordre des mots et formes verbales corrects","points":3},{"critere":"Explication de la différence Sie / sie","points":4}],"dureeMin":15,"corrige":"**1. Traduction modèle**\n\n1. *Er sagt: „Ich weiß, dass sie kommt.“*\n2. *Frau Weber, ich danke Ihnen.*\n3. *Die Stadt, die ich besuche, ist schön, aber teuer.*\n4. *Ich lerne Deutsch, um Bücher zu lesen.*\n\nPoints attendus :\n- Phrase 1 : deux-points avant la parole, guillemets „…“, virgule devant *dass*, *sie* (elle) en minuscule.\n- Phrase 2 : *danken* régit le datif : *Ihnen*, avec **majuscule** car c'est le vouvoiement.\n- Phrase 3 : relative encadrée de deux virgules, verbe *besuche* à la fin de la relative, virgule devant *aber*.\n- Phrase 4 : virgule devant *um… zu*, infinitif avec *zu* en fin de phrase.\n\n**2.** *Können Sie mir helfen?* = « Pouvez-vous m'aider ? » (vouvoiement, une personne à qui l'on parle). *Können sie mir helfen?* = « Peuvent-ils (ou peuvent-elles) m'aider ? ». À l'écrit, seule la majuscule distingue le *Sie* de politesse du *sie* de la 3e personne : l'oublier change le destinataire de la phrase."}$exo$::jsonb),
  ('207ad1d8-f8be-5943-84f5-61eaa5344b1d'::uuid, 1, 'traduction', $exo${"titre":"Changer le début de la phrase","consigne":"Réécris chaque phrase en la commençant par l'élément en gras. Attention à la place du verbe conjugué.","enonce":"**Réécris en commençant par l'élément en gras.**\n\n1. Ich fahre **morgen** nach Berlin.\n2. Wir spielen **am Samstag** Fußball.\n3. Er hat **gestern** einen Film gesehen.\n4. Ich stehe **um sieben Uhr** auf.\n5. Meine Schwester muss **heute Abend** arbeiten.","bareme":[{"critere":"Verbe conjugué en deuxième position et sujet placé derrière (inversion)","points":12},{"critere":"Second morceau du verbe (participe, infinitif, préverbe) laissé en fin de phrase","points":8}],"dureeMin":6,"corrige":"**Phrases attendues**\n\n1. *Morgen fahre ich nach Berlin.*\n2. *Am Samstag spielen wir Fußball.*\n3. *Gestern hat er einen Film gesehen.*\n4. *Um sieben Uhr stehe ich auf.*\n5. *Heute Abend muss meine Schwester arbeiten.*\n\nPoints attendus :\n- Règle V2 : le verbe conjugué reste le **deuxième groupe**. Dès qu'un autre élément que le sujet ouvre la phrase, le sujet passe **derrière** le verbe (inversion). *Morgen ich fahre…* est faux.\n- Parenthèse verbale : *gesehen* (participe), *auf* (préverbe) et *arbeiten* (infinitif après le modal) restent à la toute fin."}$exo$::jsonb),
  ('207ad1d8-f8be-5943-84f5-61eaa5344b1d'::uuid, 2, 'traduction', $exo${"titre":"Cinq phrases à traduire dans le bon ordre","consigne":"Traduis en allemand. Soigne la place du verbe et l'ordre des compléments.","enonce":"**Traduis en allemand.**\n\n1. Demain, je dois travailler.\n2. Hier, Paul a acheté un vélo.\n3. Je donne le livre à l'enfant.\n4. Je le donne à l'enfant.\n5. Nous allons demain en train à Munich.\n\n*Aide : kaufen (gekauft) ; das Fahrrad ; das Buch ; das Kind ; fahren ; mit dem Zug ; München.*","bareme":[{"critere":"Verbe en deuxième position et inversion après Morgen / Gestern","points":6},{"critere":"Infinitif et participe rejetés en fin de phrase","points":5},{"critere":"Ordre datif puis accusatif, et pronom es placé devant le datif","points":5},{"critere":"Ordre temps, manière, lieu (TeKaMoLo) dans la phrase 5","points":4}],"dureeMin":10,"corrige":"**Traduction modèle**\n\n1. *Morgen muss ich arbeiten.*\n2. *Gestern hat Paul ein Fahrrad gekauft.*\n3. *Ich gebe dem Kind das Buch.*\n4. *Ich gebe es dem Kind.*\n5. *Wir fahren morgen mit dem Zug nach München.*\n\nPoints attendus :\n- 1 et 2 : l'adverbe de temps occupe la première place, le verbe conjugué suit, puis le sujet (inversion). L'infinitif *arbeiten* et le participe *gekauft* ferment la phrase.\n- 3 : deux groupes nominaux → **datif puis accusatif** (*dem Kind das Buch*).\n- 4 : l'accusatif est un **pronom** → il passe devant (*es dem Kind*). *Ich gebe dem Kind es* est faux.\n- 5 : TeKaMoLo : temps (*morgen*), manière (*mit dem Zug*), lieu (*nach München*)."}$exo$::jsonb),
  ('207ad1d8-f8be-5943-84f5-61eaa5344b1d'::uuid, 3, 'traduction', $exo${"titre":"Le week-end de Jonas","consigne":"À partir des notes, écris un petit texte de cinq phrases au présent, sauf une phrase au parfait. Au moins trois phrases doivent commencer par un autre élément que le sujet. Puis réponds à la question 2.","enonce":"**1. Rédige le texte à partir de ces notes.**\n\n- samedi : se lever à 8 heures (*aufstehen*)\n- ensuite : prendre le train pour Hambourg avec sa sœur\n- là-bas : devoir acheter un cadeau pour sa grand-mère (*müssen*)\n- dimanche : visiter le port — **au parfait** (*den Hafen besuchen*)\n- le soir : rentrer à la maison (*zurückkommen, nach Hause*)\n\n**2.** Choisis une de tes phrases qui commence par un complément de temps et explique en français la règle de la place du verbe qu'elle applique.","bareme":[{"critere":"Verbe conjugué en deuxième position dans chaque phrase, avec inversion","points":6},{"critere":"Parenthèse verbale : préverbe, infinitif du modal et participe en fin de phrase","points":6},{"critere":"Ordre des compléments (temps, manière, lieu) respecté","points":3},{"critere":"Explication juste de la règle V2 et de l'inversion","points":5}],"dureeMin":16,"corrige":"**1. Texte modèle**\n\n*Am Samstag steht Jonas um acht Uhr auf. Dann fährt er mit seiner Schwester mit dem Zug nach Hamburg. Dort muss er ein Geschenk für seine Großmutter kaufen. Am Sonntag hat er den Hafen besucht. Am Abend kommt er nach Hause zurück.*\n\nPoints attendus :\n- Chaque phrase ouverte par *Am Samstag*, *Dann*, *Dort*, *Am Sonntag*, *Am Abend* : verbe en 2e position, sujet **derrière**.\n- Préverbes *auf* et *zurück* en fin de phrase ; *kaufen* après le modal *muss* en fin de phrase ; participe *besucht* en fin de phrase après *hat*.\n- Compléments dans l'ordre temps → manière → lieu : *mit dem Zug nach Hamburg*.\n- Toute formulation équivalente correcte est acceptée (ex. *nimmt den Zug nach Hamburg*).\n\n**2.** Exemple : *Am Sonntag hat er den Hafen besucht.* Dans une déclarative, le verbe conjugué occupe toujours la deuxième place (le deuxième **groupe**, pas le deuxième mot). Comme le complément de temps *Am Sonntag* occupe la première place, le sujet *er* passe derrière le verbe : c'est l'inversion. Le participe *besucht* ferme la phrase."}$exo$::jsonb),
  ('e1175a92-f062-5eef-b96e-27f9e4ce6cf0'::uuid, 1, 'traduction', $exo${"titre":"Trouver la bonne question","consigne":"Écris la question qui correspond à chaque réponse. La partie en gras est ce que l'on demande ; pour la phrase 1, pose une question fermée.","enonce":"**Écris la question (tutoie la personne).**\n\n1. Ja, ich komme morgen.\n2. Ich wohne **in Köln**.\n3. Ich fahre **nach Wien**.\n4. **Mein Bruder** ruft an.\n5. Ich sehe **den Lehrer**.","bareme":[{"critere":"Mot interrogatif juste (wo, wohin, wer, wen)","points":10},{"critere":"Place du verbe : 1re position (question fermée), 2e après le mot en w-","points":6},{"critere":"Conjugaison à la 2e personne et point d'interrogation","points":4}],"dureeMin":7,"corrige":"**Questions attendues**\n\n1. *Kommst du morgen?* — question fermée : verbe en **première** position.\n2. *Wo wohnst du?* — *wo* : le lieu où l'on est, **sans** mouvement.\n3. *Wohin fährst du?* — *wohin* : la destination, **avec** mouvement.\n4. *Wer ruft an?* — *wer* : qui (sujet, nominatif).\n5. *Wen siehst du?* — *wen* : qui (COD, accusatif de *wer*).\n\nPoints attendus : dans les questions ouvertes, le verbe reste en deuxième position, juste après le mot interrogatif ; *wer* se décline (*wen* à l'accusatif) ; ne pas confondre *wo* et *wohin*."}$exo$::jsonb),
  ('e1175a92-f062-5eef-b96e-27f9e4ce6cf0'::uuid, 2, 'traduction', $exo${"titre":"Des questions indirectes","consigne":"Transforme chaque question directe en question indirecte avec l'amorce donnée, puis réponds à la question 2.","enonce":"**1. Transforme en question indirecte.**\n\n1. Kommt Lisa heute? → *Ich frage mich, …*\n2. Wann beginnt der Film? → *Weißt du, …*\n3. Warum lernst du Deutsch? → *Sag mir, …*\n4. Wo wohnt dein Onkel? → *Ich weiß nicht, …*\n\n**2.** Pourquoi serait-il faux d'écrire *Ich frage mich, wenn Lisa heute kommt* ?","bareme":[{"critere":"Choix de ob pour la question fermée, mot en w- conservé ailleurs","points":6},{"critere":"Verbe conjugué rejeté à la fin de la subordonnée","points":8},{"critere":"Virgules et ponctuation finale correctes","points":3},{"critere":"Explication de l'opposition ob / wenn","points":3}],"dureeMin":10,"corrige":"**1. Phrases attendues**\n\n1. *Ich frage mich, ob Lisa heute kommt.*\n2. *Weißt du, wann der Film beginnt?*\n3. *Sag mir, warum du Deutsch lernst.*\n4. *Ich weiß nicht, wo dein Onkel wohnt.*\n\nPoints attendus :\n- La question indirecte est une subordonnée : virgule devant, et verbe conjugué **à la fin** (*kommt*, *beginnt*, *lernst*, *wohnt*).\n- Sans mot interrogatif (question fermée), on emploie *ob*.\n- Le point d'interrogation disparaît, sauf quand la principale elle-même est une question (phrase 2 : *Weißt du…?*).\n\n**2.** Le « si » d'une question indirecte exprime une **alternative** (oui ou non) : il se traduit par *ob*. *Wenn* introduit une **condition** ou un **moment** ; l'employer ici serait une faute de sens."}$exo$::jsonb),
  ('e1175a92-f062-5eef-b96e-27f9e4ce6cf0'::uuid, 3, 'traduction', $exo${"titre":"Dialogue avant le concert","consigne":"Traduis ce dialogue en allemand (thème), puis réponds à la question 2.","enonce":"**1. Traduis en allemand.**\n\n— Tu ne viens pas au concert ?\n— Si ! Mais je ne sais pas quand il commence.\n— À huit heures. À qui penses-tu ?\n— À Mia. Et toi, à quoi penses-tu ?\n— Aux vacances !\n\n*Aide : mitkommen ; zum Konzert ; beginnen ; denken an + accusatif ; die Ferien (pluriel).*\n\n**2.** Explique en français pourquoi on répond *Doch!* à la première question, et pourquoi on dit *an wen* pour Mia mais *woran* pour les vacances.","bareme":[{"critere":"Doch employé pour contredire la question négative","points":3},{"critere":"Question indirecte avec wann et verbe en fin de subordonnée","points":5},{"critere":"An wen pour une personne, woran pour une chose","points":5},{"critere":"Place du verbe dans les questions fermées et ouvertes","points":4},{"critere":"Explication juste de doch et de wo(r) + préposition","points":3}],"dureeMin":15,"corrige":"**1. Traduction modèle**\n\n— *Kommst du nicht zum Konzert mit?* (ou *Du kommst nicht mit zum Konzert?*)\n— *Doch! Aber ich weiß nicht, wann es beginnt.*\n— *Um acht Uhr. An wen denkst du?*\n— *An Mia. Und woran denkst du?*\n— *An die Ferien!*\n\nPoints attendus :\n- *Doch!* et non *Ja!* pour dire « si ».\n- *…, wann es beginnt* : virgule, verbe à la fin ; *es* reprend *das Konzert* (neutre).\n- *An wen denkst du?* (personne : préposition + *wen*) ; *Woran denkst du?* (chose : *wo(r)-* soudé à la préposition).\n- Question ouverte : verbe en 2e position après le mot interrogatif.\n\n**2.** Face à une question **négative**, *ja* est impossible : pour contredire la négation, l'allemand répond *doch* (comme « si » en français). Pour interroger sur une **chose**, l'allemand soude *wo(r)-* et la préposition (*woran*) ; pour une **personne**, il garde la préposition suivie de *wen* ou *wem* (*an wen*)."}$exo$::jsonb),
  ('ef7cf249-6775-5a8f-9bf4-723c10a95419'::uuid, 1, 'traduction', $exo${"titre":"Nicht ou kein ?","consigne":"Mets chaque phrase à la forme négative en choisissant entre nicht et kein.","enonce":"**Mets à la forme négative.**\n\n1. Ich habe ein Fahrrad.\n2. Ich kenne den Mann.\n3. Er trinkt Kaffee.\n4. Das Buch ist interessant.\n5. Wir haben Freunde in Berlin.\n6. Ich gehe ins Kino.","bareme":[{"critere":"Choix juste entre nicht et kein pour chaque phrase","points":10},{"critere":"Déclinaison de kein (keinen, keine au pluriel)","points":4},{"critere":"Place de nicht (après le COD défini, devant l'attribut et le lieu)","points":6}],"dureeMin":7,"corrige":"**Phrases attendues**\n\n1. *Ich habe kein Fahrrad.* — nom précédé de *ein* → *kein*.\n2. *Ich kenne den Mann nicht.* — article défini → *nicht*, placé **après** le COD défini.\n3. *Er trinkt keinen Kaffee.* — nom sans article → *kein*, décliné à l'accusatif masculin : *keinen*.\n4. *Das Buch ist nicht interessant.* — on nie l'attribut : *nicht* **devant** lui.\n5. *Wir haben keine Freunde in Berlin.* — pluriel sans article → *keine* (kein a un pluriel).\n6. *Ich gehe nicht ins Kino.* — lieu directionnel : *nicht* **devant**.\n\nRègle : *kein* devant un nom précédé de *ein* ou sans article ; *nicht* devant un article défini, un possessif, un verbe, un adjectif."}$exo$::jsonb),
  ('ef7cf249-6775-5a8f-9bf4-723c10a95419'::uuid, 2, 'traduction', $exo${"titre":"Cinq négations à traduire","consigne":"Traduis en allemand, puis réponds à la question 2.","enonce":"**1. Traduis en allemand.**\n\n1. Je ne l'ai pas vu hier. (*le* = un homme)\n2. Il ne travaille plus.\n3. Je ne pars pas demain, mais aujourd'hui.\n4. Personne ne vient.\n5. Je ne vois rien.\n\n*Aide : sehen (gesehen) ; arbeiten ; fahren ; kommen.*\n\n**2.** Un élève écrit *Ich sehe nicht nichts*. Explique en français pourquoi c'est faux.","bareme":[{"critere":"Mots négatifs justes : nicht mehr, niemand, nichts","points":6},{"critere":"Place de nicht : devant le participe, devant le mot nié","points":6},{"critere":"Rectification avec sondern","points":4},{"critere":"Explication : une seule négation suffit en allemand","points":4}],"dureeMin":10,"corrige":"**1. Traduction modèle**\n\n1. *Ich habe ihn gestern nicht gesehen.* — négation de toute la phrase : *nicht* le plus à droite possible, devant le participe.\n2. *Er arbeitet nicht mehr.* — « ne… plus » = *nicht mehr*.\n3. *Ich fahre nicht morgen, sondern heute.* — on nie un seul mot : *nicht* **devant** *morgen* ; après une négation, on rectifie avec *sondern* (pas *aber*).\n4. *Niemand kommt.*\n5. *Ich sehe nichts.*\n\n**2.** En allemand, deux négations ne s'additionnent pas pour renforcer : **une seule suffit**. *Nichts* porte déjà la négation (« rien »), il ne faut donc pas ajouter *nicht*. La phrase juste est *Ich sehe nichts*."}$exo$::jsonb),
  ('ef7cf249-6775-5a8f-9bf4-723c10a95419'::uuid, 3, 'traduction', $exo${"titre":"Paul répond non à tout","consigne":"Paul est de mauvaise humeur : il répond non à toutes les questions de sa mère. Écris ses réponses en phrases complètes, puis réponds à la question 2.","enonce":"**1. Écris les réponses négatives de Paul.**\n\n1. Hast du einen Hund gesehen?\n2. Hast du deine Hausaufgaben gemacht?\n3. Ist dein Freund nett?\n4. Fährst du nach Berlin? — *Paul rectifie : il va à Hambourg.*\n5. Wohnst du noch in Köln?\n6. Kommt jemand mit?\n\n**2.** Justifie en français ton choix entre *nicht* et *kein* dans les réponses 1 et 2.","bareme":[{"critere":"Choix nicht / kein juste et kein décliné (keinen)","points":6},{"critere":"Place de nicht : après le COD défini, devant l'attribut et le lieu","points":5},{"critere":"Emploi de sondern, nicht mehr et niemand","points":5},{"critere":"Justification juste des réponses 1 et 2","points":4}],"dureeMin":15,"corrige":"**1. Réponses modèles**\n\n1. *Nein, ich habe keinen Hund gesehen.*\n2. *Nein, ich habe meine Hausaufgaben nicht gemacht.*\n3. *Nein, er ist nicht nett.*\n4. *Nein, ich fahre nicht nach Berlin, sondern nach Hamburg.*\n5. *Nein, ich wohne nicht mehr in Köln.*\n6. *Nein, niemand kommt mit.*\n\nPoints attendus :\n- 1 : *einen Hund* → *keinen Hund* (accusatif masculin).\n- 2 : COD avec possessif → *nicht*, placé après le COD et devant le participe *gemacht*.\n- 3 : *nicht* devant l'attribut.\n- 4 : *nicht* devant le lieu directionnel, rectification par *sondern*.\n- 5 : « ne… plus » = *nicht mehr*. 6 : *niemand*, sans autre négation.\n\n**2.** Réponse 1 : le nom est précédé de l'article indéfini *einen* → on nie avec *kein*, qui se décline comme *ein* (*keinen*). Réponse 2 : le nom est précédé d'un possessif (*meine*) → on nie avec *nicht*, jamais avec *kein*."}$exo$::jsonb),
  ('11c68cd1-ea30-5b98-85e0-3c026b8989a2'::uuid, 1, 'traduction', $exo${"titre":"Relier deux phrases","consigne":"Relie les deux phrases avec la conjonction donnée. Attention à la place du verbe.","enonce":"**Relie avec la conjonction entre parenthèses.**\n\n1. Ich bleibe zu Hause. Ich bin krank. (*weil*)\n2. Ich weiß. Er kommt morgen. (*dass*)\n3. Sie geht spazieren. Es regnet. (*obwohl*)\n4. Er ruft an. Er hat Zeit. (*wenn*)","bareme":[{"critere":"Verbe conjugué rejeté à la fin de chaque subordonnée","points":12},{"critere":"Virgule devant la subordonnée","points":4},{"critere":"Reste de la phrase et sujet correctement placés","points":4}],"dureeMin":6,"corrige":"**Phrases attendues**\n\n1. *Ich bleibe zu Hause, weil ich krank bin.*\n2. *Ich weiß, dass er morgen kommt.*\n3. *Sie geht spazieren, obwohl es regnet.*\n4. *Er ruft an, wenn er Zeit hat.*\n\nPoints attendus : une subordonnée se reconnaît à la conjonction en tête et au **verbe conjugué à la toute fin** (*bin*, *kommt*, *regnet*, *hat*). La virgule devant la subordonnée est obligatoire. Le sujet suit directement la conjonction (*weil ich…*, *dass er…*). *Ich bleibe zu Hause, weil ich bin krank* est la faute à éviter."}$exo$::jsonb),
  ('11c68cd1-ea30-5b98-85e0-3c026b8989a2'::uuid, 2, 'traduction', $exo${"titre":"Quand, parce que : quatre traductions","consigne":"Traduis en allemand. Soigne le choix de la conjonction et la place des verbes.","enonce":"**Traduis en allemand.**\n\n1. Quand j'étais petit, j'habitais à Munich.\n2. Je reste à la maison parce que je dois travailler.\n3. Il est fatigué parce qu'il a travaillé.\n4. Quand il pleut, je lis.\n\n*Aide : klein ; wohnen (prétérit wohnte) ; München ; zu Hause bleiben ; müde ; regnen ; lesen (er liest).*","bareme":[{"critere":"Choix de als pour un fait unique du passé, wenn pour la répétition","points":5},{"critere":"Verbe final en subordonnée, modal et auxiliaire en dernier","points":6},{"critere":"Subordonnée en tête : verbe de la principale juste après la virgule","points":6},{"critere":"Virgules correctes","points":3}],"dureeMin":10,"corrige":"**Traduction modèle**\n\n1. *Als ich klein war, wohnte ich in München.* (*habe ich in München gewohnt* accepté)\n2. *Ich bleibe zu Hause, weil ich arbeiten muss.*\n3. *Er ist müde, weil er gearbeitet hat.*\n4. *Wenn es regnet, lese ich.*\n\nPoints attendus :\n- 1 : « quand » pour une période **unique** du passé → *als*, jamais *wann* ni *wenn*.\n- 4 : « quand » au présent, à valeur répétée → *wenn*.\n- 2 : avec un modal, c'est le **modal conjugué** qui ferme la subordonnée, après l'infinitif (*arbeiten muss*).\n- 3 : au temps composé, l'**auxiliaire** ferme la subordonnée, après le participe (*gearbeitet hat*).\n- 1 et 4 : la subordonnée en tête occupe la première position ; le verbe de la principale suit **immédiatement** la virgule (*wohnte ich*, *lese ich*)."}$exo$::jsonb),
  ('11c68cd1-ea30-5b98-85e0-3c026b8989a2'::uuid, 3, 'traduction', $exo${"titre":"Pourquoi j'apprends l'allemand","consigne":"Écris à ton correspondant un message de six phrases pour lui expliquer pourquoi tu apprends l'allemand. Emploie weil, denn, dass, obwohl et damit, et place au moins une subordonnée en tête de phrase. Puis réponds à la question 2.","enonce":"**1. Rédige ton message (six phrases).**\n\nIdées possibles : étudier plus tard en Allemagne, ce que disent tes parents de l'allemand, la grammaire difficile mais le cours agréable, lire des livres en allemand, un professeur qui parle lentement, une visite de ton correspondant l'été prochain.\n\n**2.** Choisis une de tes phrases avec *weil* et une avec *denn*. Explique en français la différence de construction entre les deux.","bareme":[{"critere":"Cinq conjonctions employées avec le bon sens","points":5},{"critere":"Verbe conjugué à la fin après weil, dass, obwohl, damit","points":6},{"critere":"Subordonnée en tête suivie du verbe de la principale","points":3},{"critere":"Ordre normal conservé après denn","points":3},{"critere":"Explication juste de la différence weil / denn","points":3}],"dureeMin":18,"corrige":"**1. Message modèle**\n\n*Ich lerne Deutsch, weil ich später in Berlin studieren möchte. Mein Vater sagt, dass Deutsch in Europa sehr wichtig ist. Obwohl die Grammatik schwer ist, macht mir der Unterricht Spaß. Ich lese auch deutsche Bücher, denn ich will meinen Wortschatz verbessern. Meine Lehrerin spricht langsam, damit wir alles verstehen. Wenn du mich im Sommer besuchst, können wir zusammen Deutsch sprechen.*\n\nPoints attendus :\n- Verbe (ou modal) conjugué à la fin après *weil*, *dass*, *obwohl*, *damit*, *wenn* : *möchte*, *ist*, *verstehen*, *besuchst*.\n- *Obwohl…* et *Wenn…* en tête : le verbe de la principale suit la virgule (*macht mir*, *können wir*).\n- *denn* : ordre normal, verbe en 2e position (*denn ich will…*).\n- *damit* (but avec un autre sujet), *obwohl* (concession) employés avec le bon sens. Toute production correcte et variée est acceptée.\n\n**2.** *weil* est une conjonction de **subordination** : elle envoie le verbe conjugué à la fin (*weil ich… studieren möchte*). *denn* est une conjonction de **coordination** : elle ne touche pas à l'ordre des mots, le verbe reste en deuxième position (*denn ich will…*). Le sens (la cause) est le même."}$exo$::jsonb),
  ('e7990467-27c6-5852-a4fe-951d3d10117e'::uuid, 1, 'traduction', $exo${"titre":"Le bon pronom relatif","consigne":"Complète chaque phrase avec le pronom relatif qui convient, puis justifie les phrases 2 et 4.","enonce":"**1. Complète avec le pronom relatif.**\n\n1. Der Mann, ___ dort steht, ist mein Onkel.\n2. Die Frau, ___ ich helfe, ist alt.\n3. Das Buch, ___ ich lese, ist spannend.\n4. Die Kinder, mit ___ ich spiele, sind nett.\n5. Der Junge, ___ Vater Arzt ist, heißt Tim.\n6. Die Stadt, ___ ich besuche, ist schön.\n\n**2.** Justifie en une phrase chacun le pronom des phrases 2 et 4 (genre et cas).","bareme":[{"critere":"Genre et nombre repris de l'antécédent","points":6},{"critere":"Cas donné par la fonction dans la relative (dont der, denen, dessen)","points":10},{"critere":"Justification juste des phrases 2 et 4","points":4}],"dureeMin":7,"corrige":"**1. Réponses**\n\n1. *der* — masculin, sujet → nominatif.\n2. *der* — féminin, complément de *helfen* qui régit le **datif** → *der*.\n3. *das* — neutre, COD → accusatif *das*.\n4. *denen* — pluriel, après *mit* qui régit le datif → datif pluriel *denen*.\n5. *dessen* — masculin, complément du nom *Vater* → génitif *dessen*, sans article devant *Vater*.\n6. *die* — féminin, COD → accusatif *die*.\n\n**2.** Phrase 2 : *Frau* est féminin (genre venu d'avant), et dans la relative le pronom est complément de *helfen*, qui régit le datif (cas venu d'après) → *der*. Phrase 4 : *Kinder* est au pluriel, et la préposition *mit* impose le datif → *denen*, l'une des trois formes qui diffèrent de l'article."}$exo$::jsonb),
  ('e7990467-27c6-5852-a4fe-951d3d10117e'::uuid, 2, 'traduction', $exo${"titre":"Deux phrases, une relative","consigne":"Relie chaque paire de phrases par une subordonnée relative.","enonce":"**Relie par une relative.**\n\n1. Das ist der Film. Ich habe den Film gestern gesehen.\n2. Ich kenne die Lehrerin. Sie wohnt in unserer Straße.\n3. Hier ist mein Freund. Ich fahre mit ihm nach Wien.\n4. Das ist die Frau. Ihr Auto ist kaputt.\n5. Du sagst alles. Das ist richtig. → commence par *Alles, …*","bareme":[{"critere":"Pronom relatif juste (den, die, dem, deren, was)","points":8},{"critere":"Préposition placée devant le relatif","points":3},{"critere":"Verbe conjugué à la fin de la relative","points":5},{"critere":"Virgules obligatoires autour de la relative","points":4}],"dureeMin":10,"corrige":"**Phrases attendues**\n\n1. *Das ist der Film, den ich gestern gesehen habe.* — masculin, COD → *den* ; l'auxiliaire *habe* ferme la relative.\n2. *Ich kenne die Lehrerin, die in unserer Straße wohnt.* — féminin, sujet → *die*.\n3. *Hier ist mein Freund, mit dem ich nach Wien fahre.* — la préposition reste **devant** le relatif et commande le datif.\n4. *Das ist die Frau, deren Auto kaputt ist.* — génitif féminin *deren*, sans article devant *Auto*.\n5. *Alles, was du sagst, ist richtig.* — après *alles*, le relatif est *was*, jamais *das*.\n\nDans toutes les phrases : virgules obligatoires, verbe conjugué **à la fin** de la relative."}$exo$::jsonb),
  ('e7990467-27c6-5852-a4fe-951d3d10117e'::uuid, 3, 'traduction', $exo${"titre":"Lukas et son club de football","consigne":"Traduis le texte en allemand (thème), puis réponds à la question 2.","enonce":"**1. Traduis en allemand.**\n\n> Lukas est un garçon qui habite à Hambourg. Le club dans lequel il joue au football est connu. Son entraîneur, à qui il fait confiance, est sévère. La fille dont le frère joue aussi s'appelle Emma. Lukas gagne souvent, ce qui plaît à ses parents.\n\n*Aide : der Verein ; der Trainer ; vertrauen + datif ; streng ; das Mädchen ; gewinnen ; gefallen + datif ; bekannt.*\n\n**2.** Explique en français pourquoi on écrit *dessen* (et non *deren*) devant *Bruder*, et *dem* devant *er vertraut*.","bareme":[{"critere":"Pronoms relatifs justes : der, in dem, dem, dessen","points":6},{"critere":"Relatif was après une phrase entière","points":3},{"critere":"Verbe à la fin de chaque relative et virgules","points":5},{"critere":"Vocabulaire et reste de la phrase corrects","points":2},{"critere":"Justification de dessen et de dem","points":4}],"dureeMin":16,"corrige":"**1. Traduction modèle**\n\n> *Lukas ist ein Junge, der in Hamburg wohnt. Der Verein, in dem er Fußball spielt, ist bekannt. Sein Trainer, dem er vertraut, ist streng. Das Mädchen, dessen Bruder auch spielt, heißt Emma. Lukas gewinnt oft, was seinen Eltern gefällt.*\n\nPoints attendus :\n- *der* : masculin (Junge), sujet → nominatif.\n- *in dem* : la préposition reste devant le relatif ; *in* + datif (lieu où l'on est).\n- *dem* : masculin (Trainer), complément de *vertrauen* qui régit le datif.\n- *dessen* : génitif, sans article devant *Bruder*.\n- *was* : le relatif reprend toute la phrase précédente.\n- Chaque relative : virgules et verbe conjugué à la fin (*wohnt*, *spielt*, *vertraut*, *spielt*, *gefällt*). Relative enchâssée encadrée de deux virgules.\n\n**2.** Le pronom prend le **genre de l'antécédent** : *Mädchen* est **neutre** (diminutif en -chen), donc génitif neutre *dessen* ; *deren* serait féminin ou pluriel. Pour *dem* : l'antécédent *Trainer* est masculin, et dans la relative le pronom est complément de *vertrauen*, qui régit le datif → *dem*."}$exo$::jsonb),
  ('4cbcec13-85fc-58b3-a2bc-f580a95120d6'::uuid, 1, 'traduction', $exo${"titre":"Passer au passif","consigne":"Mets chaque phrase au passif présent. Garde l'agent quand il est nommé.","enonce":"**Mets au passif présent.**\n\n1. Man baut ein Haus.\n2. Der Lehrer korrigiert die Hefte.\n3. Man repariert das Auto.\n4. Die Mutter kocht die Suppe.\n\n*Rappel : le COD de la phrase active devient le sujet de la phrase passive.*","bareme":[{"critere":"werden conjugué et accordé au nouveau sujet (wird, werden)","points":8},{"critere":"Participe II rejeté en fin de phrase","points":6},{"critere":"Agent introduit par von + datif (vom Lehrer, von der Mutter)","points":6}],"dureeMin":7,"corrige":"**Phrases attendues**\n\n1. *Ein Haus wird gebaut.*\n2. *Die Hefte werden vom Lehrer korrigiert.*\n3. *Das Auto wird repariert.*\n4. *Die Suppe wird von der Mutter gekocht.*\n\nPoints attendus :\n- Le passif d'action se construit avec **werden** (jamais *sein*) + participe II à la fin.\n- *werden* s'accorde avec le nouveau sujet : *die Hefte* est pluriel → *werden*.\n- *man* disparaît : pas d'agent. Une personne agent est introduite par *von* + datif : *vom Lehrer* (von dem), *von der Mutter*.\n- Participes : *gebaut*, *korrigiert*, *repariert* (verbes en -ieren, sans ge-), *gekocht*."}$exo$::jsonb),
  ('4cbcec13-85fc-58b3-a2bc-f580a95120d6'::uuid, 2, 'traduction', $exo${"titre":"Le passif à tous les temps","consigne":"Réponds aux quatre questions.","enonce":"1. Mets *Das Haus wird gebaut* au **prétérit**, puis au **parfait**.\n2. Mets *Der Brief wird geschrieben* au **parfait**.\n3. Traduis : « Le travail doit être fait aujourd'hui. » (*die Arbeit, machen*)\n4. Explique en français la différence de sens entre *Die Tür wird geschlossen* et *Die Tür ist geschlossen*.","bareme":[{"critere":"Prétérit du passif avec wurde","points":4},{"critere":"Parfait du passif avec ist + participe + worden","points":6},{"critere":"Passif avec modal : muss + participe + werden","points":5},{"critere":"Distinction juste entre passif d'action et passif d'état","points":5}],"dureeMin":10,"corrige":"1. Prétérit : *Das Haus wurde gebaut.* Parfait : *Das Haus ist gebaut worden.*\n2. *Der Brief ist geschrieben worden.*\n3. *Die Arbeit muss heute gemacht werden.* — le modal se conjugue, le passif passe à l'infinitif (*gemacht werden*).\n4. *Die Tür wird geschlossen* = passif d'**action** : quelqu'un est en train de fermer la porte (le film). *Die Tür ist geschlossen* = passif d'**état** : la porte est fermée, c'est un résultat acquis (la photo).\n\nPoint essentiel : au parfait du passif, le participe de *werden* perd son ge- : **worden**. *geworden* est réservé au verbe *werden* au sens de « devenir » (*Er ist Arzt geworden*). L'auxiliaire du parfait passif est toujours *sein* (*ist… worden*)."}$exo$::jsonb),
  ('4cbcec13-85fc-58b3-a2bc-f580a95120d6'::uuid, 3, 'traduction', $exo${"titre":"L'histoire d'un pont","consigne":"Traduis ce petit article en allemand en employant le passif, puis réponds à la question 2.","enonce":"**1. Traduis en allemand.**\n\n> Le pont de la ville a été construit en 1890. En 2020, il a été détruit par une tempête. Aujourd'hui, il est reconstruit par une entreprise allemande. Il doit être terminé en 2027. Ici, on travaille jour et nuit.\n\n*Aide : die Brücke (féminin) ; bauen ; zerstören ; der Sturm ; die Firma ; wieder aufbauen (wieder aufgebaut) ; fertigstellen (fertiggestellt) ; Tag und Nacht. Pour « on travaille », utilise le passif impersonnel.*\n\n**2.** Réécris la dernière phrase avec *man*, puis explique pourquoi tu as employé *durch* pour la tempête et *von* pour l'entreprise.","bareme":[{"critere":"Temps du passif justes : wurde / ist … worden, wird + participe","points":6},{"critere":"Passif avec modal : muss … fertiggestellt werden","points":3},{"critere":"Passif impersonnel : Hier wird … gearbeitet","points":3},{"critere":"Agent : durch + accusatif et von + datif","points":4},{"critere":"Phrase avec man et explication von / durch","points":4}],"dureeMin":16,"corrige":"**1. Traduction modèle**\n\n> *Die Brücke der Stadt wurde 1890 gebaut. 2020 ist sie durch einen Sturm zerstört worden. Heute wird sie von einer deutschen Firma wieder aufgebaut. Sie muss 2027 fertiggestellt werden. Hier wird Tag und Nacht gearbeitet.*\n\nPoints attendus :\n- *wurde gebaut* (prétérit) ou *ist gebaut worden* (parfait) acceptés pour les deux premières phrases ; au parfait : **worden**, jamais *geworden*.\n- *sie* reprend *die Brücke* (féminin).\n- *wird… wieder aufgebaut* : présent du passif, participe en fin de phrase.\n- *muss… fertiggestellt werden* : modal + infinitif passif.\n- *Hier wird… gearbeitet* : passif impersonnel d'un verbe sans COD.\n- Une date seule s'emploie sans préposition (*1890*, *2020*) ; *im Jahr 1890* accepté.\n\n**2.** *Hier arbeitet man Tag und Nacht.* (ou *Man arbeitet hier Tag und Nacht.*)\n*von* + datif introduit une personne ou une force qui agit : l'entreprise fait le travail. *durch* + accusatif introduit un **moyen** ou un intermédiaire, comme un phénomène naturel (*durch ein Erdbeben*, *durch einen Sturm*)."}$exo$::jsonb),
  ('a1ca1f57-7faa-533b-b303-0f23562e46f0'::uuid, 1, 'traduction', $exo${"titre":"Avec ou sans zu ?","consigne":"Complète avec zu quand il le faut, ou écris l'infinitif entre parenthèses à la bonne forme.","enonce":"**Complète (mets un tiret si zu est impossible).**\n\n1. Ich versuche, pünktlich ___ sein.\n2. Ich kann gut ___ schwimmen.\n3. Er hat keine Lust, ins Kino ___ gehen.\n4. Wir gehen heute ___ schwimmen.\n5. Es ist wichtig, früh ___ (*aufstehen*).\n6. Vergiss nicht, Brot ___ (*einkaufen*).","bareme":[{"critere":"zu présent après versuchen, Lust haben, es ist wichtig, vergessen","points":8},{"critere":"Pas de zu après un modal et un verbe de mouvement","points":6},{"critere":"zu intercalé en un seul mot : aufzustehen, einzukaufen","points":6}],"dureeMin":6,"corrige":"**Réponses**\n\n1. *Ich versuche, pünktlich zu sein.* — *versuchen* appelle *zu*.\n2. *Ich kann gut schwimmen.* — **pas** de *zu* après un modal.\n3. *Er hat keine Lust, ins Kino zu gehen.* — *Lust haben* appelle *zu*.\n4. *Wir gehen heute schwimmen.* — **pas** de *zu* après un verbe de mouvement.\n5. *Es ist wichtig, früh aufzustehen.* — avec un préverbe séparable, *zu* s'intercale entre le préverbe et le radical, en **un seul mot**.\n6. *Vergiss nicht, Brot einzukaufen.* — même règle : *einzukaufen*.\n\nÀ retenir : *zu* se place juste devant l'infinitif, en fin de groupe ; les modaux, *sehen*, *hören*, *lassen* et les verbes de mouvement le refusent."}$exo$::jsonb),
  ('a1ca1f57-7faa-533b-b303-0f23562e46f0'::uuid, 2, 'traduction', $exo${"titre":"But, privation, substitution","consigne":"Relie chaque paire de phrases avec um… zu, damit, ohne… zu ou statt… zu, selon l'indication.","enonce":"**Relie les phrases.**\n\n1. Ich spare Geld. Ich will ein Fahrrad kaufen. (*but*)\n2. Ich erkläre es dir. Du verstehst es. (*but*)\n3. Er geht weg. Er sagt nichts. (*privation : « sans »*)\n4. Sie sieht fern. Sie sollte arbeiten. (*substitution : « au lieu de »*)\n5. Ich stehe früh auf. Ich rufe meine Oma an. (*but*)","bareme":[{"critere":"Choix du bon outil pour chaque phrase","points":6},{"critere":"damit quand le sujet change (phrase 2) avec verbe final","points":5},{"critere":"zu bien placé, dont anzurufen en un seul mot","points":5},{"critere":"Virgule obligatoire devant chaque groupe","points":4}],"dureeMin":11,"corrige":"**Phrases attendues**\n\n1. *Ich spare Geld, um ein Fahrrad zu kaufen.*\n2. *Ich erkläre es dir, damit du es verstehst.*\n3. *Er geht weg, ohne etwas zu sagen.*\n4. *Sie sieht fern, statt zu arbeiten.* (*anstatt* accepté)\n5. *Ich stehe früh auf, um meine Oma anzurufen.*\n\nPoints attendus :\n- *um… zu* exige que les deux propositions aient le **même sujet** (phrases 1 et 5).\n- Phrase 2 : le sujet change (*ich* / *du*) → *damit*, subordonnée avec le verbe à la fin (*verstehst*).\n- Phrase 3 : « ne rien dire » → *ohne etwas zu sagen* (« sans rien dire »).\n- Phrase 5 : *anrufen* est séparable → *anzurufen*.\n- Virgule obligatoire devant *um… zu*, *ohne… zu*, *statt… zu* et *damit*. Le groupe infinitif n'a jamais de sujet propre."}$exo$::jsonb),
  ('a1ca1f57-7faa-533b-b303-0f23562e46f0'::uuid, 3, 'traduction', $exo${"titre":"Thème : six groupes infinitifs","consigne":"Traduis les six phrases en allemand, puis réponds à la question 2.","enonce":"**1. Traduis en allemand.**\n\n1. J'ai beaucoup à faire.\n2. Ce travail doit être fait aujourd'hui. (*utilise sein + zu*)\n3. Il est parti sans fermer la porte.\n4. J'apprends l'allemand pour pouvoir parler avec ma correspondante.\n5. Mes parents travaillent pour que nous puissions partir en vacances.\n6. J'ai envie d'aller nager.\n\n*Aide : tun ; die Arbeit ; gehen (ist gegangen) ; die Tür schließen ; die Brieffreundin ; in Urlaub fahren ; Lust haben ; schwimmen gehen.*\n\n**2.** Explique en français pourquoi tu as employé *um… zu* dans la phrase 4 et *damit* dans la phrase 5.","bareme":[{"critere":"haben + zu et sein + zu justes (phrases 1 et 2)","points":4},{"critere":"ohne… zu et Lust haben… zu construits correctement","points":4},{"critere":"um… zu avec modal et damit avec verbe final","points":5},{"critere":"Virgules et place de zu","points":3},{"critere":"Explication juste um… zu / damit (même sujet ou non)","points":4}],"dureeMin":16,"corrige":"**1. Traduction modèle**\n\n1. *Ich habe viel zu tun.* — *haben* + *zu* : valeur active (avoir à faire).\n2. *Diese Arbeit ist heute zu machen.* — *sein* + *zu* : valeur passive (doit être fait).\n3. *Er ist gegangen, ohne die Tür zu schließen.*\n4. *Ich lerne Deutsch, um mit meiner Brieffreundin sprechen zu können.*\n5. *Meine Eltern arbeiten, damit wir in Urlaub fahren können.*\n6. *Ich habe Lust, schwimmen zu gehen.*\n\nPoints attendus : virgule devant *ohne… zu*, *um… zu*, *damit* ; *zu* juste devant le dernier infinitif (*sprechen zu können*, *schwimmen zu gehen*) ; dans la phrase 5, le modal *können* ferme la subordonnée.\n\n**2.** Phrase 4 : le sujet est le même dans les deux propositions (*ich* apprend, *ich* veux parler) → groupe infinitif *um… zu*. Phrase 5 : le sujet change (*meine Eltern* travaillent, *wir* partons) → *um… zu* est impossible, il faut une subordonnée avec *damit* et un sujet exprimé."}$exo$::jsonb),
  ('f5d1d5c8-3cf2-5b7e-be2f-45f044b72e95'::uuid, 1, 'traduction', $exo${"titre":"Der, die ou das ?","consigne":"Donne l'article défini et l'article indéfini de chaque nom, puis justifie trois de tes réponses par un repère de genre.","enonce":"**1. Donne l'article défini et l'article indéfini (nominatif singulier).**\n\nMädchen · Zeitung · Montag · Freiheit · Lehrer · Essen · Frühling · Päckchen\n\n**2.** Pour *Mädchen*, *Zeitung* et *Montag*, donne en une phrase le repère qui permet de trouver le genre.","bareme":[{"critere":"Articles définis justes (der, die, das)","points":8},{"critere":"Articles indéfinis justes (ein, eine)","points":4},{"critere":"Repères de genre justes pour les trois noms","points":8}],"dureeMin":7,"corrige":"**1. Réponses**\n\n- *das Mädchen / ein Mädchen*\n- *die Zeitung / eine Zeitung*\n- *der Montag / ein Montag*\n- *die Freiheit / eine Freiheit*\n- *der Lehrer / ein Lehrer*\n- *das Essen / ein Essen*\n- *der Frühling / ein Frühling*\n- *das Päckchen / ein Päckchen*\n\n**2.** Repères :\n- *Mädchen* : tous les diminutifs en *-chen* et *-lein* sont **neutres** — la grammaire l'emporte sur le sens (même chose pour *Päckchen*).\n- *Zeitung* : les noms en *-ung* sont **féminins** (comme ceux en *-heit* : *Freiheit*).\n- *Montag* : les jours, mois et saisons sont **masculins** (comme *Frühling*, qui se termine aussi en *-ling*).\nAutres repères acceptés : *Lehrer* en *-er* masculin ; *Essen* infinitif substantivé neutre."}$exo$::jsonb),
  ('f5d1d5c8-3cf2-5b7e-be2f-45f044b72e95'::uuid, 2, 'traduction', $exo${"titre":"Article ou pas d'article ?","consigne":"Complète le texte avec l'article qui convient, ou avec Ø quand il n'en faut pas. Puis réponds à la question 2.","enonce":"**1. Complète le texte.**\n\n> Mein Vater ist ___ Lehrer. ___ Schule, in der er arbeitet, ist groß. Am Morgen trinkt er ___ Kaffee. ___ Mädchen neben ihm ist meine Schwester. Sie hat ___ Katze. ___ Katze heißt Mimi. Im Sommer fahren wir nach ___ Deutschland. Im Garten spielen ___ Kinder.\n\n*(Kinder : des enfants, sens indéfini.)*\n\n**2.** Dans *Das ist meine Schwester*, *das* est-il un article ? Explique.","bareme":[{"critere":"Genres justes des articles (Die Schule, Das Mädchen, eine / Die Katze)","points":6},{"critere":"Absence d'article : métier, matière, nom de pays","points":6},{"critere":"Pas d'article indéfini au pluriel","points":3},{"critere":"Explication de das démonstratif invariable","points":5}],"dureeMin":10,"corrige":"**1. Texte complété**\n\n> *Mein Vater ist Ø Lehrer. Die Schule, in der er arbeitet, ist groß. Am Morgen trinkt er Ø Kaffee. Das Mädchen neben ihm ist meine Schwester. Sie hat eine Katze. Die Katze heißt Mimi. Im Sommer fahren wir nach Ø Deutschland. Im Garten spielen Ø Kinder.*\n\nPoints attendus :\n- Métier après *sein* : pas d'article (*Er ist Lehrer*).\n- Nom de matière : pas d'article (*Kaffee*, « du café »).\n- La plupart des noms de pays : pas d'article (*nach Deutschland*).\n- *ein* n'a **pas de pluriel** : « des enfants » = *Kinder*.\n- *das Mädchen* est neutre (-chen) ; *die Schule*, *die Katze* féminins.\n\n**2.** Non : dans *Das ist meine Schwester*, *das* est un **démonstratif invariable** (« ça, c'est ma sœur »). Il ne s'accorde à rien, même si *Schwester* est féminin ; un article serait suivi d'un nom qu'il détermine."}$exo$::jsonb),
  ('f5d1d5c8-3cf2-5b7e-be2f-45f044b72e95'::uuid, 3, 'traduction', $exo${"titre":"Thème : genres et pièges","consigne":"Traduis les phrases en allemand, puis justifie trois de tes choix.","enonce":"**1. Traduis en allemand.**\n\n1. La jeune fille est ma cousine.\n2. Elle est étudiante.\n3. Le soleil brille, la lune est invisible.\n4. Une journée à Berlin coûte cher.\n5. Des enfants jouent dans la rue.\n6. Ça, c'est la solution !\n\n*Aide : Mädchen ; die Cousine ; die Studentin ; Sonne ; Mond ; scheinen ; unsichtbar ; Tag ; teuer sein ; auf der Straße ; Lösung.*\n\n**2.** Justifie en français : l'article de *Mädchen*, l'absence d'article devant *Studentin*, et l'article de *Lösung*.","bareme":[{"critere":"Genres justes : das Mädchen, die Sonne, der Mond, die Lösung","points":6},{"critere":"Absence d'article : métier après sein, indéfini pluriel","points":4},{"critere":"Das démonstratif invariable et ein Tag","points":3},{"critere":"Phrases correctes (verbe, accord, ordre)","points":2},{"critere":"Trois justifications justes","points":5}],"dureeMin":15,"corrige":"**1. Traduction modèle**\n\n1. *Das Mädchen ist meine Cousine.*\n2. *Sie ist Studentin.*\n3. *Die Sonne scheint, der Mond ist unsichtbar.*\n4. *Ein Tag in Berlin ist teuer.*\n5. *Kinder spielen auf der Straße.*\n6. *Das ist die Lösung!*\n\nPoints attendus :\n- *die Sonne* (le soleil) et *der Mond* (la lune) : genres inverses du français.\n- *Sie ist Studentin* : pas d'article devant un métier ou un statut après *sein*.\n- « Des enfants » : pas d'article indéfini au pluriel.\n- *Das ist…* : démonstratif invariable.\n- *Sie* reprend *das Mädchen* : accepté aussi, car il s'agit d'une personne ; *es* est grammaticalement possible.\n\n**2.** *das Mädchen* : tous les diminutifs en *-chen* sont neutres. *Studentin* : après *sein*, un métier ou un statut s'emploie sans article (« elle est **une** étudiante » ne se dit pas). *die Lösung* : les noms en *-ung* sont féminins."}$exo$::jsonb),
  ('dd419f5e-9d57-5cb8-b619-439a87c6f6ef'::uuid, 1, 'traduction', $exo${"titre":"Le bon cas, la bonne forme","consigne":"Complète avec la forme correcte du déterminant entre parenthèses.","enonce":"**Complète.**\n\n1. Ich sehe ___ (der) Mann.\n2. Ich helfe ___ (die) Frau.\n3. Ich gebe ___ (das) Kind ein Buch.\n4. Er kauft ___ (ein) Hund.\n5. Das ist das Auto ___ (der) Vater___.\n6. Wir spielen mit ___ (die, pluriel) Kinder___.","bareme":[{"critere":"Accusatifs justes (den, einen)","points":5},{"critere":"Datifs justes (der, dem, den)","points":8},{"critere":"Génitif des Vaters avec -s","points":4},{"critere":"-n du datif pluriel : Kindern","points":3}],"dureeMin":7,"corrige":"**Réponses**\n\n1. *Ich sehe den Mann.* — COD masculin → accusatif *den*.\n2. *Ich helfe der Frau.* — *helfen* : datif féminin *der*.\n3. *Ich gebe dem Kind ein Buch.* — COI neutre → datif *dem*.\n4. *Er kauft einen Hund.* — COD masculin → *einen*.\n5. *Das ist das Auto des Vaters.* — complément du nom → génitif *des*, et le nom masculin prend *-s*.\n6. *Wir spielen mit den Kindern.* — *mit* + datif ; au datif pluriel, l'article est *den* **et** le nom prend *-n*.\n\nRappel : le masculin est le seul genre qui change entre nominatif et accusatif (*der → den*, *ein → einen*)."}$exo$::jsonb),
  ('dd419f5e-9d57-5cb8-b619-439a87c6f6ef'::uuid, 2, 'traduction', $exo${"titre":"Possessifs et déterminants en der-","consigne":"Complète chaque phrase, puis indique le cas du groupe complété et sa fonction.","enonce":"**Complète, puis donne le cas et la fonction.**\n\n1. Ich besuche ___ (mein) Großvater.\n2. Ich schenke ___ (meine) Mutter Blumen.\n3. ___ (dieser) Film gefällt mir.\n4. Kennst du ___ (diese) Frau?\n5. ___ (jeder) Kind bekommt ein Geschenk.\n6. Ich spreche mit ___ (unsere, pluriel) Nachbarn.","bareme":[{"critere":"Formes justes des six déterminants","points":10},{"critere":"Cas et fonction correctement identifiés","points":6},{"critere":"Orthographe des terminaisons et des noms","points":4}],"dureeMin":11,"corrige":"**Réponses**\n\n1. *meinen Großvater* — accusatif, COD de *besuchen* ; le possessif se décline comme *ein* : *meinen*.\n2. *meiner Mutter* — datif, COI (on offre **à** sa mère).\n3. *Dieser Film* — nominatif, sujet de *gefällt*.\n4. *diese Frau* — accusatif, COD ; au féminin, accusatif = nominatif.\n5. *Jedes Kind* — nominatif, sujet ; *jeder* prend les terminaisons de l'article défini (*das* → *jedes*).\n6. *unseren Nachbarn* — datif pluriel après *mit* ; *unser* garde son e.\n\nRappel : *kein* et les possessifs se déclinent comme *ein* ; *dieser*, *jeder*, *welcher* comme l'article défini."}$exo$::jsonb),
  ('dd419f5e-9d57-5cb8-b619-439a87c6f6ef'::uuid, 3, 'traduction', $exo${"titre":"Thème : les quatre cas en action","consigne":"Traduis les cinq phrases en allemand, puis indique le cas de chaque groupe nominal souligné.","enonce":"**1. Traduis en allemand.**\n\n1. Le frère de **mon amie** offre un livre à **son père**.\n2. Je n'ai pas de **voiture**.\n3. Nous parlons avec **les voisins**.\n4. **Chaque élève** connaît **ce professeur**.\n5. La maison de **la famille** est grande.\n\n*Aide : die Freundin ; schenken ; sein Vater ; das Auto ; der Nachbar (pluriel die Nachbarn) ; der Schüler ; der Lehrer ; die Familie.*\n\n**2.** Donne le cas des sept groupes en gras et justifie-le par leur fonction.","bareme":[{"critere":"Nominatifs et accusatifs justes (kein Auto, diesen Lehrer)","points":4},{"critere":"Datifs justes (seinem Vater, den Nachbarn)","points":5},{"critere":"Génitifs justes (meiner Freundin, der Familie)","points":5},{"critere":"Déterminants en der- et kein bien déclinés","points":3},{"critere":"Cas identifiés et justifiés par la fonction","points":3}],"dureeMin":16,"corrige":"**1. Traduction modèle**\n\n1. *Der Bruder meiner Freundin schenkt seinem Vater ein Buch.*\n2. *Ich habe kein Auto.*\n3. *Wir sprechen mit den Nachbarn.*\n4. *Jeder Schüler kennt diesen Lehrer.*\n5. *Das Haus der Familie ist groß.*\n\n**2. Cas des groupes en gras**\n- *meiner Freundin* : **génitif** féminin, complément du nom *Bruder*.\n- *seinem Vater* : **datif**, COI de *schenken*.\n- *kein Auto* : **accusatif** neutre, COD (même forme qu'au nominatif).\n- *den Nachbarn* : **datif pluriel** après *mit* (le nom a déjà son -n).\n- *Jeder Schüler* : **nominatif**, sujet.\n- *diesen Lehrer* : **accusatif** masculin, COD — *dieser* prend les terminaisons de l'article.\n- *der Familie* : **génitif** féminin, complément du nom *Haus* ; au féminin, pas de marque sur le nom."}$exo$::jsonb),
  ('6d1e356d-e3b5-53e1-8df6-26207dcbff12'::uuid, 1, 'traduction', $exo${"titre":"Remplacer par un pronom","consigne":"Remplace le groupe en gras par le pronom personnel qui convient.","enonce":"**Remplace le groupe en gras par un pronom.**\n\n1. **Der Tisch** ist alt.\n2. Ich sehe **den Lehrer**.\n3. Ich helfe **meiner Schwester**.\n4. **Die Lampe** ist neu.\n5. Wir danken **den Eltern**.\n6. Ich kaufe **das Buch**.","bareme":[{"critere":"Genre grammatical conservé (er pour der Tisch, sie pour die Lampe)","points":8},{"critere":"Cas juste : ihn, ihr, ihnen, es","points":8},{"critere":"Phrases correctement recopiées (majuscule, ordre)","points":4}],"dureeMin":6,"corrige":"**Réponses**\n\n1. *Er ist alt.* — *der Tisch* est masculin → *er*, même pour un objet.\n2. *Ich sehe ihn.* — masculin, COD → accusatif *ihn*.\n3. *Ich helfe ihr.* — féminin, *helfen* régit le datif → *ihr*.\n4. *Sie ist neu.* — *die Lampe* est féminin → *sie*.\n5. *Wir danken ihnen.* — pluriel, *danken* régit le datif → *ihnen*.\n6. *Ich kaufe es.* — neutre, COD → *es*.\n\nRègle : le pronom garde le **genre grammatical** du nom et prend le **cas** de sa fonction. Traduire mécaniquement une chose par *es* est une faute : en allemand, une table est « il »."}$exo$::jsonb),
  ('6d1e356d-e3b5-53e1-8df6-26207dcbff12'::uuid, 2, 'traduction', $exo${"titre":"Deux pronoms dans la phrase","consigne":"Remplace les deux compléments par des pronoms (phrases 1 à 3), puis traduis les phrases 4 et 5.","enonce":"**Remplace les deux compléments par des pronoms.**\n\n1. Ich gebe dem Kind das Buch.\n2. Er schenkt seiner Mutter die Blumen.\n3. Wir zeigen den Gästen das Haus.\n\n**Traduis.**\n\n4. Hier, mon père m'a appelé. (*commence par Gestern ; anrufen*)\n5. Je vous remercie, Monsieur Braun. (*vouvoiement ; danken + datif*)","bareme":[{"critere":"Formes des pronoms justes (es, ihm, sie, ihr, ihnen, mich)","points":6},{"critere":"Ordre des deux pronoms : accusatif puis datif","points":6},{"critere":"Pronom placé juste après le verbe, avant le sujet nominal","points":4},{"critere":"Ihnen de politesse avec majuscule","points":4}],"dureeMin":10,"corrige":"1. *Ich gebe es ihm.*\n2. *Er schenkt sie ihr.*\n3. *Wir zeigen es ihnen.*\n4. *Gestern hat mich mein Vater angerufen.*\n5. *Ich danke Ihnen, Herr Braun.*\n\nPoints attendus :\n- Avec deux groupes nominaux, l'ordre est datif puis accusatif ; avec deux **pronoms**, c'est **accusatif puis datif** : *es ihm*, *sie ihr*, *es ihnen*. *Ich gebe ihm es* est faux.\n- *das Buch* → *es* ; *die Blumen* (pluriel) → *sie* ; *seiner Mutter* → *ihr* ; *den Gästen* → *ihnen*.\n- Phrase 4 : les pronoms remontent juste après le verbe conjugué ; en cas d'inversion, le pronom *mich* peut précéder le sujet nominal *mein Vater*.\n- Phrase 5 : *Sie* de politesse → datif *Ihnen*, toujours avec majuscule."}$exo$::jsonb),
  ('6d1e356d-e3b5-53e1-8df6-26207dcbff12'::uuid, 3, 'traduction', $exo${"titre":"Une lettre à Anna","consigne":"Traduis la lettre en allemand, puis réponds à la question 2.","enonce":"**1. Traduis en allemand.**\n\n> Chère Anna, merci pour ta lettre ! Je l'ai lue hier. Mon frère te salue. Il a un nouveau vélo : il est rouge. Mes parents t'invitent : tu peux venir chez nous en été. Est-ce que tu veux leur écrire ?\n\n*Aide : Liebe Anna ; danke für + accusatif ; der Brief ; lesen (gelesen) ; grüßen ; ein neues Fahrrad ; einladen (séparable) ; zu uns ; im Sommer ; schreiben + datif.*\n\n**2.** Explique en français pourquoi « je **l'**ai lue » se traduit par *ihn* et « **il** est rouge » par *es*.","bareme":[{"critere":"Pronoms reprenant le genre du nom : ihn (Brief), es (Fahrrad)","points":5},{"critere":"Cas justes : dich, ihnen, uns","points":5},{"critere":"Place des pronoms et du préverbe ein en fin de phrase","points":3},{"critere":"Phrases correctes (verbes, possessifs, ponctuation)","points":3},{"critere":"Explication juste du choix ihn / es","points":4}],"dureeMin":16,"corrige":"**1. Traduction modèle**\n\n> *Liebe Anna, danke für deinen Brief! Ich habe ihn gestern gelesen. Mein Bruder grüßt dich. Er hat ein neues Fahrrad: Es ist rot. Meine Eltern laden dich ein: Du kannst im Sommer zu uns kommen. Willst du ihnen schreiben?*\n\nPoints attendus :\n- *deinen Brief* : *für* + accusatif, masculin.\n- *ihn* : reprend *der Brief* (masculin), COD → accusatif.\n- *dich* : COD de *grüßen* et de *einladen* ; le préverbe *ein* ferme la phrase.\n- *es* : reprend *das Fahrrad* (neutre), sujet.\n- *ihnen* : datif pluriel (« à eux »), COI de *schreiben* ; minuscule, car ce n'est pas le vouvoiement.\n- Majuscule au début de la phrase après les deux-points (*Es ist rot*, *Du kannst*) acceptée ou minuscule tolérée.\n\n**2.** Le pronom allemand garde le **genre grammatical** du nom qu'il remplace, pas celui du français. *Der Brief* (la lettre) est masculin : on le reprend par *ihn* à l'accusatif. *Das Fahrrad* (le vélo) est neutre : on le reprend par *es*."}$exo$::jsonb),
  ('233e32f0-3d00-5436-8186-f3679bbb5338'::uuid, 1, 'traduction', $exo${"titre":"Dieser, et das ou dass","consigne":"Complète les phrases 1 à 5 avec la bonne forme de dieser, puis les phrases 6 et 7 avec das ou dass.","enonce":"**Complète avec dieser à la bonne forme.**\n\n1. ___ Mann ist mein Nachbar.\n2. Ich kenne ___ Frau nicht.\n3. Ich wohne in ___ Haus.\n4. Kaufst du ___ Rock? (*der Rock*)\n5. Das Auto ___ Mannes ist neu.\n\n**Complète avec das ou dass.**\n\n6. Ich glaube, ___ er kommt.\n7. ___ ist mein Bruder.","bareme":[{"critere":"Formes de dieser justes selon genre et cas","points":12},{"critere":"Choix juste entre das et dass","points":8}],"dureeMin":6,"corrige":"**Réponses**\n\n1. *Dieser Mann* — nominatif masculin.\n2. *diese Frau* — accusatif féminin.\n3. *in diesem Haus* — datif neutre (lieu où l'on est).\n4. *diesen Rock* — accusatif masculin.\n5. *dieses Mannes* — génitif masculin.\n6. *Ich glaube, dass er kommt.* — conjonction qui introduit une subordonnée.\n7. *Das ist mein Bruder.* — démonstratif invariable.\n\nPoints attendus : *dieser* se décline comme l'article défini (*der → dieser*, *den → diesen*, *dem → diesem*, *des → dieses*). Test pour *das* / *dass* : si l'on peut remplacer par *dieses*, c'est *das* avec un seul s ; sinon, c'est la conjonction *dass*."}$exo$::jsonb),
  ('233e32f0-3d00-5436-8186-f3679bbb5338'::uuid, 2, 'traduction', $exo${"titre":"Celui-là, le même","consigne":"Réponds aux cinq questions.","enonce":"**Complète la réponse avec le démonstratif accentué.**\n\n1. — Kennst du Peter? — Ja, ___ kenne ich gut!\n2. — Magst du die Lehrerin? — Ja, ___ mag ich.\n3. — Hilfst du den Nachbarn? — Ja, ___ helfe ich gern.\n\n4. Réécris pour dire clairement qu'il s'agit du frère **de Paul** : *Ich traf Paul und seinen Bruder.*\n5. Traduis : « Nous habitons dans la même maison. » et « Elle a la même robe que moi. » Explique en une phrase pourquoi tu n'emploies pas le même mot.","bareme":[{"critere":"Démonstratifs accentués justes (den, die, denen)","points":6},{"critere":"Emploi de dessen pour lever l'ambiguïté","points":4},{"critere":"derselbe décliné et der gleiche employés à bon escient","points":6},{"critere":"Explication juste : identique ou semblable","points":4}],"dureeMin":10,"corrige":"1. *Den kenne ich gut!* — masculin, COD → *den*.\n2. *Die mag ich.* — féminin, COD → *die*.\n3. *Denen helfe ich gern.* — pluriel, *helfen* + datif → *denen* (forme propre au démonstratif).\n4. *Ich traf Paul und dessen Bruder.* — *dessen* désigne sans équivoque le frère de Paul (*seinen* pouvait renvoyer au sujet).\n5. *Wir wohnen in demselben Haus.* / *Sie hat das gleiche Kleid wie ich.*\n\nExplication : *derselbe* désigne un objet **identique**, unique (une seule maison) ; *der gleiche* désigne un objet **semblable** (deux robes pareilles). Dans *derselbe*, les deux morceaux se déclinent : *dem-* comme l'article (datif après *in*), *-selben* comme un adjectif faible."}$exo$::jsonb),
  ('233e32f0-3d00-5436-8186-f3679bbb5338'::uuid, 3, 'traduction', $exo${"titre":"Dialogue dans la cour","consigne":"Traduis ce dialogue en allemand en employant les démonstratifs, puis réponds à la question 2.","enonce":"**1. Traduis en allemand.**\n\n— Tu vois ce garçon ?\n— Celui-là ? Je le connais : c'est le frère de Lisa.\n— Et la jeune fille à côté de lui ?\n— Celle-là, je ne la connais pas. Mais Lisa et sa sœur (la sœur de Lisa) habitent dans la même rue que moi.\n— Ce sont mes amies !\n\n*Aide : der Junge (accusatif den Jungen) ; das Mädchen ; neben + datif ; die Straße ; die Freundin.*\n\n**2.** Explique en français ton choix de *das* pour « celle-là » et de *deren* pour « sa sœur ».","bareme":[{"critere":"dieser et démonstratifs accentués justes (diesen, den, das)","points":5},{"critere":"deren pour lever l'ambiguïté sur la sœur","points":3},{"critere":"derselben Straße décliné au datif","points":3},{"critere":"Das sind … : verbe accordé avec ce qui suit","points":3},{"critere":"Justification de das et de deren","points":6}],"dureeMin":16,"corrige":"**1. Traduction modèle**\n\n— *Siehst du diesen Jungen?*\n— *Den da? Den kenne ich: Das ist der Bruder von Lisa.* (*Lisas Bruder* accepté)\n— *Und das Mädchen neben ihm?*\n— *Das kenne ich nicht. Aber Lisa und deren Schwester wohnen in derselben Straße wie ich.*\n— *Das sind meine Freundinnen!*\n\nPoints attendus :\n- *diesen Jungen* : accusatif masculin ; *Den* : démonstratif accentué, masculin accusatif.\n- *Das ist…* et *Das sind…* : *das* invariable, le verbe s'accorde avec ce qui suit (*sind* devant un pluriel).\n- *in derselben Straße* : lieu où l'on est → datif, *der-* + *-selben*.\n- *neben ihm* : datif (localisation).\n\n**2.** *Das* : le démonstratif reprend le genre du nom ; *Mädchen* est **neutre**, donc *das* à l'accusatif, même s'il s'agit d'une fille. *deren* : génitif féminin du démonstratif, il renvoie sans équivoque à Lisa ; *ihre Schwester* serait possible mais moins précis dans une phrase à plusieurs personnes. C'est un usage soigné, apprécié à l'écrit."}$exo$::jsonb),
  ('f04b8338-b125-5b3b-9800-005d4202fbc1'::uuid, 1, 'traduction', $exo${"titre":"Huit pluriels","consigne":"Donne le pluriel de chaque nom avec son article, puis indique pour trois d'entre eux le schéma de pluriel.","enonce":"**1. Donne le pluriel avec l'article.**\n\nder Tag · das Kind · die Frau · der Lehrer · das Auto · die Lehrerin · der Sohn · das Buch\n\n**2.** Pour *Frau*, *Lehrer* et *Auto*, nomme le schéma de pluriel (terminaison ajoutée ou absence de terminaison).","bareme":[{"critere":"Huit pluriels justes, Umlaut compris","points":14},{"critere":"Article die au pluriel pour tous les noms","points":2},{"critere":"Schémas justes pour les trois noms","points":4}],"dureeMin":6,"corrige":"**1. Pluriels**\n\n- *die Tage* (-e)\n- *die Kinder* (-er)\n- *die Frauen* (-en)\n- *die Lehrer* (aucune terminaison)\n- *die Autos* (-s)\n- *die Lehrerinnen* (-nen : le n est doublé)\n- *die Söhne* (-e avec Umlaut)\n- *die Bücher* (-er avec Umlaut)\n\nAu pluriel, l'article défini est **die** pour les trois genres.\n\n**2.** *Frau* : schéma en **-(e)n**, celui de presque tous les féminins, sans inflexion. *Lehrer* : **aucune terminaison** (masculin en -er). *Auto* : **-s**, schéma des emprunts et abréviations."}$exo$::jsonb),
  ('f04b8338-b125-5b3b-9800-005d4202fbc1'::uuid, 2, 'traduction', $exo${"titre":"Tout au pluriel","consigne":"Mets chaque phrase entièrement au pluriel (sujet, verbe et complément).","enonce":"**Mets au pluriel.**\n\n1. Das Kind spielt mit dem Ball.\n2. Die Zeitung liegt auf dem Tisch.\n3. Der Lehrer spricht mit der Schülerin.\n4. Das Auto steht vor dem Haus.\n\n*Aide : der Ball → die Bälle ; der Tisch → die Tische ; das Haus → die Häuser ; die Schülerin → die Schülerinnen.*","bareme":[{"critere":"Pluriels des noms justes","points":8},{"critere":"-n du datif pluriel ajouté, sauf après -s (Autos)","points":6},{"critere":"Verbes accordés et articles die / den justes","points":6}],"dureeMin":11,"corrige":"**Phrases attendues**\n\n1. *Die Kinder spielen mit den Bällen.*\n2. *Die Zeitungen liegen auf den Tischen.*\n3. *Die Lehrer sprechen mit den Schülerinnen.*\n4. *Die Autos stehen vor den Häusern.*\n\nPoints attendus :\n- Sujets au pluriel avec *die* : *Kinder*, *Zeitungen*, *Lehrer* (sans terminaison), *Autos*.\n- Verbes à la 3e personne du pluriel : *spielen*, *liegen*, *sprechen*, *stehen*.\n- Datif pluriel : article *den*, et le nom prend **-n** s'il n'en a pas déjà un : *Bällen*, *Tischen*, *Häusern* ; *Schülerinnen* et *Zeitungen* finissent déjà par n.\n- Exception : pas de -n après un pluriel en -s (*mit den Autos*)."}$exo$::jsonb),
  ('f04b8338-b125-5b3b-9800-005d4202fbc1'::uuid, 3, 'traduction', $exo${"titre":"Thème : singuliers et pluriels trompeurs","consigne":"Traduis les phrases en allemand, puis explique trois pièges.","enonce":"**1. Traduis en allemand.**\n\n1. Mon père porte des lunettes.\n2. Les enfants jouent avec les chats des voisins.\n3. La police arrive avec deux voitures.\n4. Les fruits sont frais.\n5. Les gens sont gentils.\n\n*Aide : tragen ; die Katze ; der Nachbar (pluriel die Nachbarn) ; kommen ; das Auto ; frisch ; nett.*\n\n**2.** Explique en français les trois pièges des phrases 1, 3 et 4.","bareme":[{"critere":"eine Brille et das Obst au singulier, verbe accordé","points":5},{"critere":"Pluriels justes : Kinder, Katzen, Nachbarn, Autos, Leute","points":5},{"critere":"Datif pluriel et génitif pluriel corrects","points":4},{"critere":"Explication des trois pièges","points":6}],"dureeMin":15,"corrige":"**1. Traduction modèle**\n\n1. *Mein Vater trägt eine Brille.*\n2. *Die Kinder spielen mit den Katzen der Nachbarn.*\n3. *Die Polizei kommt mit zwei Autos.*\n4. *Das Obst ist frisch.*\n5. *Die Leute sind nett.*\n\nPoints attendus :\n- *mit den Katzen* : datif pluriel (le nom finit déjà par n) ; *der Nachbarn* : génitif pluriel (article *der*).\n- *die Leute* n'existe qu'au pluriel : verbe *sind*.\n- *die Polizei* est un singulier : verbe *kommt*.\n\n**2. Les pièges**\n- Phrase 1 : l'allemand met au **singulier** ce que le français met au pluriel : « des lunettes » = *eine Brille*.\n- Phrase 3 : *Autos* est un pluriel en -s : au datif pluriel, il ne prend **pas** de -n (*mit zwei Autos*).\n- Phrase 4 : *das Obst* n'existe qu'au singulier : « les fruits sont » → *das Obst ist*."}$exo$::jsonb),
  ('e2dc63c4-553b-5b46-a015-12ae322b4366'::uuid, 1, 'traduction', $exo${"titre":"L'attribut ne bouge pas","consigne":"Corrige l'erreur de chaque phrase, puis réponds à la question 2.","enonce":"**1. Corrige chaque phrase.**\n\n1. Die Frau ist alte.\n2. Das Wetter ist schönes.\n3. Die Kinder sind müden.\n4. Das Haus wird großes.\n5. Er singt schöne.\n\n**2.** Dans *Ein alter Mann ist gekommen* et *Der Mann ist alt*, pourquoi l'adjectif n'a-t-il pas la même forme ?","bareme":[{"critere":"Cinq phrases corrigées avec l'adjectif à sa forme nue","points":12},{"critere":"Explication juste : épithète déclinée, attribut invariable","points":8}],"dureeMin":6,"corrige":"**1. Phrases corrigées**\n\n1. *Die Frau ist alt.*\n2. *Das Wetter ist schön.*\n3. *Die Kinder sind müde.* (*müde* se termine déjà par e : c'est sa forme nue)\n4. *Das Haus wird groß.*\n5. *Er singt schön.* — ici, *schön* est un **adverbe** : l'allemand n'a pas de terminaison d'adverbe, le mot reste invariable.\n\nAprès *sein*, *werden* et *bleiben*, l'adjectif attribut reste à sa forme nue : ni -e, ni -er, rien.\n\n**2.** Tout dépend de la **place** de l'adjectif. Dans *Ein alter Mann*, il est **épithète** (devant le nom) : il se décline toujours. Dans *Der Mann ist alt*, il est **attribut** (après le verbe *sein*) : il ne se décline jamais."}$exo$::jsonb),
  ('e2dc63c4-553b-5b46-a015-12ae322b4366'::uuid, 2, 'traduction', $exo${"titre":"Thème : attributs et adverbes","consigne":"Traduis les cinq phrases en allemand.","enonce":"**Traduis en allemand.**\n\n1. La maison est grande et belle.\n2. Ma sœur devient impatiente.\n3. Il chante bien.\n4. Je trouve ce film intéressant.\n5. Le train est plus rapide que la voiture.\n\n*Aide : das Haus ; ungeduldig ; singen ; schön ; der Film ; interessant ; der Zug ; schnell ; das Auto.*","bareme":[{"critere":"Adjectifs attributs invariables après sein et werden","points":8},{"critere":"Adverbe invariable (schön ou gut)","points":3},{"critere":"finden + COD + attribut invariable","points":4},{"critere":"Comparatif en -er suivi de als","points":5}],"dureeMin":10,"corrige":"**Traduction modèle**\n\n1. *Das Haus ist groß und schön.*\n2. *Meine Schwester wird ungeduldig.*\n3. *Er singt schön.* (*gut* accepté)\n4. *Ich finde diesen Film interessant.*\n5. *Der Zug ist schneller als das Auto.*\n\nPoints attendus :\n- Phrases 1 et 2 : l'attribut ne s'accorde pas, même au féminin (*ungeduldig*, pas *ungeduldige*).\n- Phrase 3 : l'allemand n'a pas de terminaison d'adverbe comme -ment : le même mot sert d'adjectif et d'adverbe.\n- Phrase 4 : *finden* + COD appelle un attribut, invariable ; *diesen Film* à l'accusatif.\n- Phrase 5 : la terminaison -er est la marque du **comparatif**, pas un accord ; « que » = *als*."}$exo$::jsonb),
  ('e2dc63c4-553b-5b46-a015-12ae322b4366'::uuid, 3, 'traduction', $exo${"titre":"Le portrait de Klara","consigne":"À partir de la fiche, écris le portrait de Klara en six phrases. Emploie les adjectifs comme attributs (après sein, werden, bleiben) et au moins un comparatif. Puis réponds à la question 2.","enonce":"**1. Écris le portrait (six phrases).**\n\n**Fiche de Klara**\n- ta meilleure amie, 15 ans\n- grande et sportive\n- parfois impatiente\n- reste calme pendant les examens\n- chante bien\n- plus rapide que son frère\n\n*Aide : groß ; sportlich ; ungeduldig ; ruhig ; die Prüfung ; singen ; schnell ; der Bruder.*\n\n**2.** Un camarade écrit *Klara ist große*. Explique-lui son erreur en français.","bareme":[{"critere":"Attributs invariables après sein et bleiben","points":7},{"critere":"Adverbe invariable pour chanter","points":2},{"critere":"Comparatif avec als correct","points":3},{"critere":"Phrases correctes : verbe en 2e position, inversion","points":4},{"critere":"Explication juste de l'erreur","points":4}],"dureeMin":15,"corrige":"**1. Portrait modèle**\n\n*Meine beste Freundin heißt Klara. Sie ist fünfzehn Jahre alt. Sie ist groß und sportlich. Manchmal ist sie ungeduldig, aber in den Prüfungen bleibt sie ruhig. Sie singt schön. Sie ist schneller als ihr Bruder.*\n\nPoints attendus :\n- *groß*, *sportlich*, *ungeduldig*, *ruhig* : attributs après *sein* ou *bleiben* → forme nue, sans terminaison.\n- *singt schön* (ou *gut*) : adverbe invariable.\n- *schneller als* : comparatif en -er + *als*.\n- Inversion après *Manchmal* et *in den Prüfungen* (verbe en 2e position).\n- *Meine beste Freundin* : épithète déclinée devant le nom, acceptée.\n\n**2.** Après *sein*, l'adjectif est **attribut** : il ne se décline jamais, même quand le sujet est féminin. Il faut écrire *Klara ist groß*. La terminaison n'apparaît que si l'adjectif est placé **devant** le nom (*eine große Freundin*)."}$exo$::jsonb),
  ('62ec0fde-c670-5dbe-a47c-453fdbb92daf'::uuid, 1, 'traduction', $exo${"titre":"Les terminaisons de l'épithète","consigne":"Complète la terminaison de chaque adjectif.","enonce":"**Complète la terminaison (nominatif sauf indication).**\n\n1. der alt__ Mann\n2. ein alt__ Mann\n3. ein alt__ Haus\n4. mit dem neu__ Auto\n5. kalt__ Kaffee (sans déterminant)\n6. eine schön__ Blume\n\n*Rappel : der Mann, das Haus, das Auto, der Kaffee, die Blume.*","bareme":[{"critere":"Déclinaison faible après der / dem (-e, -en)","points":6},{"critere":"Déclinaison mixte après ein / eine (-er, -es, -e)","points":8},{"critere":"Déclinaison forte sans déterminant (-er)","points":6}],"dureeMin":7,"corrige":"**Réponses**\n\n1. *der alte Mann* — faible : *der* marque déjà le cas → -e.\n2. *ein alter Mann* — mixte : *ein* ne marque pas le masculin → l'adjectif prend -er.\n3. *ein altes Haus* — mixte : *ein* ne marque pas le neutre → -es.\n4. *mit dem neuen Auto* — faible au datif → -en.\n5. *kalter Kaffee* — forte : aucun déterminant, l'adjectif prend la marque de l'article (*der* → -er).\n6. *eine schöne Blume* — *eine* marque déjà le féminin → terminaison faible -e.\n\nPrincipe : la marque du cas apparaît **une fois** dans le groupe ; si le déterminant la porte, l'adjectif se contente de -e ou -en."}$exo$::jsonb),
  ('62ec0fde-c670-5dbe-a47c-453fdbb92daf'::uuid, 2, 'traduction', $exo${"titre":"Le nouvel ami","consigne":"Complète les terminaisons du texte, puis justifie deux de tes choix.","enonce":"**1. Complète les terminaisons.**\n\n> Ich habe einen neu__ Freund. Er wohnt in einem groß__ Haus mit einem schön__ Garten. Sein klein__ Bruder spielt mit einem rot__ Ball. Er hat ein teu__ Fahrrad (*teuer*). Morgen fahren wir mit dem neu__ Zug nach Berlin.\n\n*Rappel : der Freund, das Haus, der Garten, der Bruder, der Ball, das Fahrrad, der Zug.*\n\n**2.** Justifie en français la terminaison de *klein__ Bruder* et celle de *teu__ Fahrrad*.","bareme":[{"critere":"Terminaisons -en justes à l'accusatif et au datif","points":8},{"critere":"Nominatif masculin après sein : kleiner","points":3},{"critere":"Forme teures, sans le e de teuer","points":3},{"critere":"Faible après dem : neuen","points":3},{"critere":"Deux justifications justes","points":3}],"dureeMin":11,"corrige":"**1. Texte complété**\n\n> *Ich habe einen neuen Freund. Er wohnt in einem großen Haus mit einem schönen Garten. Sein kleiner Bruder spielt mit einem roten Ball. Er hat ein teures Fahrrad. Morgen fahren wir mit dem neuen Zug nach Berlin.*\n\nPoints attendus :\n- *einen neuen* (accusatif masculin), *einem großen*, *einem schönen*, *einem roten* (datif) : le déterminant marque le cas → -en.\n- *dem neuen Zug* : déclinaison faible au datif → -en.\n\n**2.** *kleiner Bruder* : *Bruder* est masculin et sujet (nominatif) ; le possessif *sein* se décline comme *ein* et ne marque rien au nominatif masculin → l'adjectif prend la marque -er. *teures Fahrrad* : *Fahrrad* est neutre, COD (accusatif) ; *ein* ne marque pas le neutre → -es ; et *teuer* perd son e devant la terminaison : *teures*, jamais *teueres*."}$exo$::jsonb),
  ('62ec0fde-c670-5dbe-a47c-453fdbb92daf'::uuid, 3, 'traduction', $exo${"titre":"Thème : le vieil homme de la montagne","consigne":"Traduis le texte en allemand, puis explique ta méthode pour deux groupes nominaux.","enonce":"**1. Traduis en allemand.**\n\n> Un vieil homme habite dans une petite maison au pied d'une haute montagne. Il boit du café froid et mange du bon pain. Sa fille porte une robe rose. Le vieil homme aime les longues promenades.\n\n*Aide : alt ; klein ; am Fuß + génitif ; hoch ; der Berg ; kalt ; gut ; das Brot ; die Tochter ; tragen ; rosa ; das Kleid ; lang ; der Spaziergang (pluriel die Spaziergänge) ; lieben.*\n\n**2.** Explique en français comment tu as trouvé la terminaison de *kalt…* devant *Kaffee* et la forme de *hoch* devant *Berg*.","bareme":[{"critere":"Déclinaisons mixte et faible justes (alter, kleinen, alte)","points":5},{"critere":"Déclinaison forte sans déterminant (kalten, gutes, lange)","points":5},{"critere":"Irréguliers et invariables : hohen, rosa","points":4},{"critere":"Méthode expliquée : cas et genre, puis déterminant","points":6}],"dureeMin":18,"corrige":"**1. Traduction modèle**\n\n> *Ein alter Mann wohnt in einem kleinen Haus am Fuß eines hohen Berges. Er trinkt kalten Kaffee und isst gutes Brot. Seine Tochter trägt ein rosa Kleid. Der alte Mann liebt lange Spaziergänge.*\n\nPoints attendus :\n- *ein alter Mann* (nominatif, mixte) ; *einem kleinen Haus* (datif) ; *eines hohen Berges* (génitif) ; *der alte Mann* (faible).\n- *kalten Kaffee*, *gutes Brot*, *lange Spaziergänge* : aucun déterminant → déclinaison forte, terminaisons de l'article défini (*den*, *das*, *die*).\n- *hoch* perd son c : *hohen*.\n- *rosa* est invariable : *ein rosa Kleid*.\n- *an einem hohen Berg* accepté pour « au pied de ».\n\n**2.** Méthode : repérer d'abord le **cas et le genre**, puis regarder le déterminant. *Kaffee* est masculin, COD → accusatif ; il n'y a aucun déterminant, donc l'adjectif porte la marque de l'article *den* → *kalten*. *Berg* est masculin, au génitif après *eines*, qui marque déjà le cas → terminaison -en ; et *hoch* perd son c devant une terminaison → *hohen*."}$exo$::jsonb),
  ('309ddd5f-f462-5553-86b3-4dd17ce4a56f'::uuid, 1, 'traduction', $exo${"titre":"Sein ou ihr ?","consigne":"Complète chaque phrase avec le possessif qui convient, bien décliné, puis réponds à la question 2 en français.","enonce":"**1. Complète avec le possessif.**\n\n1. Anna besucht ___ Großmutter. *(sa grand-mère, à elle)*\n2. Peter ruft ___ Vater an. *(son père, à lui — accusatif)*\n3. Das Kind spielt mit ___ Hund. *(son chien — datif)*\n4. Wir fahren mit ___ Auto. *(notre voiture — datif, das Auto)*\n5. Die Kinder und ___ Eltern kommen heute. *(leurs parents)*\n6. Herr Klein, ist das ___ Buch? *(votre livre, politesse)*\n\n**2.** Explique en une ou deux phrases pourquoi on écrit *ihre* dans la phrase 1 et *seinen* dans la phrase 2.","bareme":[{"critere":"Radical juste selon le possesseur : ihr- (1, 5), sein- (2, 3), unser- (4), Ihr- avec majuscule (6)","points":8},{"critere":"Terminaisons justes selon l'objet possédé : ihre, seinen, seinem, unserem, ihre, Ihr","points":8},{"critere":"Explication : radical commandé par le possesseur, terminaison par le genre et le cas du nom","points":4}],"dureeMin":6,"corrige":"**1.**\n1. Anna besucht **ihre** Großmutter. — possesseur féminin (Anna) → *ihr-* ; *Großmutter* féminin → *-e*.\n2. Peter ruft **seinen** Vater an. — possesseur masculin → *sein-* ; *Vater* masculin à l'accusatif → *-en*.\n3. Das Kind spielt mit **seinem** Hund. — *Kind* est neutre → *sein-* ; *mit* + datif masculin → *-em*.\n4. Wir fahren mit **unserem** Auto. — *unser* garde son e ; datif neutre → *-em*.\n5. Die Kinder und **ihre** Eltern kommen heute. — *ihr* = leur ; pluriel nominatif → *-e*.\n6. Herr Klein, ist das **Ihr** Buch? — vouvoiement → *Ihr* avec majuscule ; *Buch* neutre nominatif → pas de terminaison.\n\n**2.** Le **radical** dépend du **possesseur** : Anna est une femme → *ihr-*, Peter est un homme → *sein-*. La **terminaison** dépend du **nom possédé** : *Großmutter* est féminin → *ihre* ; *Vater* est masculin et COD (accusatif) → *seinen*. Le possessif se décline comme *ein* / *kein*."}$exo$::jsonb),
  ('309ddd5f-f462-5553-86b3-4dd17ce4a56f'::uuid, 2, 'traduction', $exo${"titre":"Léna présente sa famille","consigne":"Léna prépare une présentation de sa famille pour son correspondant allemand. Traduis ses phrases en allemand, puis réponds à la question 2.","enonce":"**1. Traduis en allemand.**\n\n1. Mon frère et sa copine habitent à Berlin.\n2. Ma sœur aime son chat.\n3. Nos voisins et leur fils viennent ce soir.\n4. Les enfants, où est votre professeur ?\n5. Les enfants, j'ai vu votre mère.\n6. Le matin, je me lave les mains.\n\n*Aide : die Freundin = la copine ; die Katze = le chat ; der Nachbar, die Nachbarn = le voisin ; der Sohn = le fils ; der Lehrer = le professeur ; ich habe … gesehen = j'ai vu ; heute Abend = ce soir ; morgens = le matin ; waschen = laver.*\n\n**2.** Dans les phrases 4 et 5, le possessif change de forme. Explique pourquoi.","bareme":[{"critere":"Radical sein- / ihr- choisi selon le possesseur (phrases 1, 2, 3)","points":6},{"critere":"Terminaisons justes selon le genre et le cas : seine, ihre, ihr Sohn, euer, eure","points":6},{"critere":"Phrase 6 construite avec le datif et l'article : mir die Hände","points":4},{"critere":"Explication : euer devient eur- devant une terminaison","points":4}],"dureeMin":10,"corrige":"**1. Traduction modèle**\n\n1. *Mein Bruder und **seine** Freundin wohnen in Berlin.* — possesseur masculin → *sein-* ; *Freundin* féminin → *-e*.\n2. *Meine Schwester liebt **ihre** Katze.* — possesseur féminin → *ihr-* ; *Katze* féminin accusatif → *-e*.\n3. *Unsere Nachbarn und **ihr** Sohn kommen heute Abend.* — *ihr* = leur ; *Sohn* masculin nominatif → pas de terminaison.\n4. *Kinder, wo ist **euer** Lehrer?* — *euer* sans terminaison (masculin nominatif).\n5. *Kinder, ich habe **eure** Mutter gesehen.* — *Mutter* féminin → terminaison *-e* → *eure*.\n6. *Morgens wasche ich **mir die** Hände.* (ou *Ich wasche mir morgens die Hände.*) — avec les parties du corps, l'allemand emploie l'article + un datif, pas le possessif.\n\n**2.** *euer* perd son second e dès qu'il reçoit une terminaison : *euer Lehrer* (pas de terminaison) mais *eure Mutter*, *euren Vater*. À l'inverse, *unser* garde son e : *unsere Nachbarn*."}$exo$::jsonb),
  ('309ddd5f-f462-5553-86b3-4dd17ce4a56f'::uuid, 3, 'traduction', $exo${"titre":"Le texte de Sophie à corriger","consigne":"Lis le texte de Sophie, corrige ses fautes en justifiant, puis traduis les phrases de la question 3.","enonce":"**Document — Sophie parle de son frère Paul**\n\n> Mein Bruder Paul hat einen Hund. Ihr Hund heißt Rex. Paul spielt jeden Tag mit sein Hund. Nach dem Spiel wasche ich meine Hände. Meine Eltern und ihre Freunde kommen am Samstag. „Ist das dein Ball?“ – „Nein, das ist nicht mein, das ist Pauls Ball.“\n\n1. Le texte contient **quatre** fautes sur le possessif. Relève-les, corrige-les et justifie chaque correction.\n2. Un camarade pense que *ihre Freunde* est aussi une faute. A-t-il raison ? Explique.\n3. Traduis en allemand :\n   - a. Julia et son frère aiment leur chien.\n   - b. — À qui est ce livre ? — C'est le mien.\n\n*Aide : der Ball ; das Buch ; lieben = aimer.*","bareme":[{"critere":"Les quatre fautes relevées et corrigées : Sein Hund, seinem Hund, mir die Hände, meiner","points":8},{"critere":"Justifications : possesseur, datif après mit, tournure article + datif, possessif employé seul","points":4},{"critere":"ihre Freunde reconnu correct : ihr = leur, pluriel","points":3},{"critere":"Traductions justes : ihr Bruder, ihren Hund, Wessen, meins","points":5}],"dureeMin":16,"corrige":"**1. Les quatre fautes**\n- *Ihr Hund* → **Sein Hund** : le possesseur est Paul, un homme → radical *sein-*.\n- *mit sein Hund* → **mit seinem Hund** : *mit* impose le datif ; *Hund* masculin → *-em*.\n- *wasche ich meine Hände* → **wasche ich mir die Hände** : avec les parties du corps, l'allemand n'emploie pas le possessif mais l'article + un pronom au datif.\n- *das ist nicht mein* → **das ist nicht meiner** : employé seul, le possessif prend les terminaisons de l'article défini ; *Ball* est masculin (*der*) → *meiner*.\n\n**2.** Non. *ihre Freunde* est correct : *ihr* signifie ici **leur** (les amis de mes parents), et *Freunde* est un pluriel → terminaison *-e*.\n\n**3.**\n- a. *Julia und **ihr** Bruder lieben **ihren** Hund.* — Julia est une femme → *ihr Bruder* ; « leur chien » → *ihr-*, *Hund* masculin accusatif → *ihren*.\n- b. *— **Wessen** Buch ist das? — Das ist **meins** (meines).* — *Buch* neutre (*das*) → possessif seul *mein(e)s*."}$exo$::jsonb),
  ('56ad254e-04ec-5598-b077-c62d23ba04f6'::uuid, 1, 'traduction', $exo${"titre":"À qui est-ce ?","consigne":"Transforme chaque groupe avec von en génitif, puis réponds à la question 2 par une phrase complète.","enonce":"**1. Transforme au génitif.** Utilise le génitif saxon pour les noms propres, le génitif ordinaire pour les autres.\n\n1. das Auto von Peter\n2. das Fahrrad von Anna\n3. das Haus von dem Vater\n4. die Tasche von der Lehrerin\n5. das Zimmer von dem Kind\n6. die Spielsachen von den Kindern\n\n**2.** Pose la question qui correspond à « à qui est ce cahier ? » en allemand, puis réponds que c'est le cahier de Maria. *(das Heft = le cahier)*","bareme":[{"critere":"Génitif saxon sans article ni apostrophe : Peters Auto, Annas Fahrrad","points":5},{"critere":"Masculin et neutre : des + nom en -(e)s (des Vaters, des Kindes)","points":6},{"critere":"Féminin et pluriel : der sans marque sur le nom (der Lehrerin, der Kinder)","points":5},{"critere":"Question avec Wessen et réponse Marias Heft","points":4}],"dureeMin":6,"corrige":"**1.**\n1. **Peters Auto** — nom propre placé devant, -s sans apostrophe, aucun article.\n2. **Annas Fahrrad**\n3. **das Haus des Vaters** — masculin : article *des*, le nom prend *-s*.\n4. **die Tasche der Lehrerin** — féminin : article *der*, aucune marque sur le nom.\n5. **das Zimmer des Kindes** — neutre : *des*, le nom prend *-es* (ou *des Kinds*, plus rare).\n6. **die Spielsachen der Kinder** — pluriel : *der*, aucune marque.\n\n**2.** *Wessen Heft ist das?* — *Das ist **Marias** Heft.* (*Wessen?* = de qui ?, la question du génitif.)"}$exo$::jsonb),
  ('56ad254e-04ec-5598-b077-c62d23ba04f6'::uuid, 2, 'traduction', $exo${"titre":"Les vacances de Tom","consigne":"Complète le récit de Tom avec la préposition qui convient et l'article au génitif, puis traduis les groupes de la question 2.","enonce":"**1. Complète avec *wegen, trotz, während* ou *statt*, et l'article au génitif.**\n\n1. ___ d__ Ferien fahre ich nach Hamburg. *(pendant)*\n2. ___ d__ Regens spielen wir Fußball. *(malgré)*\n3. ___ d__ Sturms bleibt das Museum geschlossen. *(à cause de — der Sturm)*\n4. ___ ein__ Kaffees trinke ich einen Tee. *(au lieu de)*\n5. Das Haus mein__ Großmutter liegt außerhalb d__ Stadt.\n\n**2.** Traduis chaque groupe de deux façons : **a.** le vélo de Lisa ; **b.** la voiture de mon père. Pour chaque groupe, indique laquelle des deux formes est la plus soignée, à l'écrit.","bareme":[{"critere":"Prépositions justes : Während, Trotz, Wegen, Statt","points":6},{"critere":"Articles et noms au génitif justes : der Ferien, des Regens, des Sturms, eines Kaffees, meiner, der Stadt","points":6},{"critere":"Deux traductions justes de chaque groupe (génitif et von + datif)","points":5},{"critere":"Registre identifié : le génitif est plus soigné que von + datif","points":3}],"dureeMin":10,"corrige":"**1.**\n1. **Während der** Ferien fahre ich nach Hamburg. — *Ferien* est un pluriel → *der*.\n2. **Trotz des** Regens spielen wir Fußball. — masculin → *des Regens*.\n3. **Wegen des** Sturms bleibt das Museum geschlossen.\n4. **Statt eines** Kaffees trinke ich einen Tee. — masculin → *eines*, nom en *-s*.\n5. Das Haus **meiner** Großmutter liegt außerhalb **der** Stadt. — féminin → *meiner*, *der*.\n\n**2.**\n- a. *Lisas Fahrrad* (génitif saxon, courant pour un nom propre) / *das Fahrrad von Lisa* (oral, plus relâché). La forme la plus soignée : **Lisas Fahrrad**.\n- b. *das Auto meines Vaters* (génitif ordinaire) / *das Auto von meinem Vater* (von + datif). La forme la plus soignée : **das Auto meines Vaters**.\n\nLe génitif recule à l'oral mais reste la marque d'un écrit soigné ; *von* + datif est la tournure parlée."}$exo$::jsonb),
  ('56ad254e-04ec-5598-b077-c62d23ba04f6'::uuid, 3, 'traduction', $exo${"titre":"Réécrire en allemand soigné","consigne":"Réécris le texte de Lena dans un allemand écrit soigné, explique tes choix, puis écris trois phrases à ton sujet.","enonce":"**Document — Le message de Lena, écrit comme on parle**\n\n> Wegen dem Regen feiern wir im Haus von meiner Tante. Das Geschenk von meinem Bruder ist toll. Trotz dem Wetter kommen alle Freunde von Lena. Das Auto von Paul steht vor der Tür.\n\n1. Réécris les quatre phrases en remplaçant chaque tournure orale par le **génitif** (génitif ordinaire ou génitif saxon selon le cas).\n2. Explique pourquoi un correcteur remarque ces transformations.\n3. Écris **trois phrases** sur ta vie (école, loisirs, famille) : une avec *während*, une avec *wegen*, une avec un génitif saxon.\n\n*Aide : das Wetter = le temps ; das Geschenk = le cadeau.*","bareme":[{"critere":"Prépositions wegen et trotz suivies du génitif : des Regens, des Wetters","points":6},{"critere":"Compléments du nom au génitif : meiner Tante, meines Bruders, Lenas Freunde, Pauls Auto","points":6},{"critere":"Explication : le génitif marque un niveau de langue écrit et soigné","points":3},{"critere":"Trois phrases correctes avec während, wegen et un génitif saxon","points":5}],"dureeMin":15,"corrige":"**1. Texte réécrit**\n\n> *Wegen **des Regens** feiern wir im Haus **meiner Tante**. Das Geschenk **meines Bruders** ist toll. Trotz **des Wetters** kommen alle **Freunde Lenas** (ou : **Lenas Freunde**). **Pauls Auto** steht vor der Tür.*\n\n- *wegen* et *trotz* régissent le génitif à l'écrit : *des Regens*, *des Wetters* (masculin / neutre → *des* + *-s*).\n- *meiner Tante* : féminin → *meiner*, sans marque sur le nom.\n- *meines Bruders* : masculin → *meines*, nom en *-s*.\n- Noms propres : génitif saxon devant le nom, sans article ni apostrophe (*Pauls Auto*, *Lenas Freunde*).\n\n**2.** Le génitif recule dans l'allemand parlé (on dit *wegen dem*, *von meinem*), mais il reste un **marqueur de niveau de langue** : à l'écrit, il montre qu'on maîtrise la langue soignée.\n\n**3. Exemple de réponse**\n- *Während der Woche habe ich viel Arbeit.*\n- *Wegen des Tests lerne ich heute Abend.*\n- *Am Samstag spiele ich mit Maxims Ball.*\n\nToute phrase correcte avec *während* + génitif, *wegen* + génitif et un nom propre + *-s* devant le nom est acceptée."}$exo$::jsonb),
  ('767d36b0-23c9-5d5a-a234-49c83e6b76a9'::uuid, 1, 'traduction', $exo${"titre":"Plus grand, plus vieux, meilleur","consigne":"Complète chaque phrase avec le comparatif de l'adjectif entre parenthèses, puis corrige la phrase de la question 2.","enonce":"**1. Complète.**\n\n1. Berlin ist ___ als München. *(groß)*\n2. Mein Bruder ist ___ als ich. *(alt)*\n3. Das Buch ist ___ als der Film. *(interessant)*\n4. Heute ist es ___ als gestern. *(warm)*\n5. Mein Deutsch ist ___ als mein Englisch. *(gut)*\n6. Ich trinke ___ Tee als Kaffee. *(gern)*\n7. Anna ist so ___ wie Lisa. *(groß)*\n\n**2.** Corrige la phrase suivante et explique ta correction : *Tom ist größer wie Paul.*","bareme":[{"critere":"Comparatifs réguliers en -er avec Umlaut : größer, älter, interessanter, wärmer","points":8},{"critere":"Irréguliers justes : besser, lieber","points":4},{"critere":"als après un comparatif, so… wie pour l'égalité, faute de la question 2 corrigée et expliquée","points":8}],"dureeMin":6,"corrige":"**1.**\n1. Berlin ist **größer** als München.\n2. Mein Bruder ist **älter** als ich.\n3. Das Buch ist **interessanter** als der Film. — adjectif long, mais toujours *-er*, jamais « mehr interessant ».\n4. Heute ist es **wärmer** als gestern.\n5. Mein Deutsch ist **besser** als mein Englisch. — *gut → besser*.\n6. Ich trinke **lieber** Tee als Kaffee. — *gern → lieber* : je préfère le thé au café.\n7. Anna ist so **groß** wie Lisa. — égalité : l'adjectif ne change pas.\n\n**2.** *Tom ist größer **als** Paul.* Après un comparatif, le second terme est introduit par **als** ; *wie* ne s'emploie qu'après *so* (égalité)."}$exo$::jsonb),
  ('767d36b0-23c9-5d5a-a234-49c83e6b76a9'::uuid, 2, 'traduction', $exo${"titre":"Deux vélos à comparer","consigne":"Noah hésite entre deux vélos. À partir du tableau, écris les phrases demandées en allemand.","enonce":"**Document — Les deux vélos**\n\n| | Rad X | Rad Y |\n| Prix | 400 € | 400 € |\n| Poids | 14 kg | 10 kg |\n| Âge | 3 ans | 1 an |\n| Vitesse | 25 km/h | 30 km/h |\n\n1. Écris **quatre phrases** de comparaison : une sur le prix, une sur le poids, une sur l'âge, une sur la vitesse.\n2. Noah préfère le Rad Y : écris-le avec *lieber*.\n3. Les vélos coûtent de plus en plus cher : dis-le en allemand.\n\n*Aide : teuer → teurer (cher) ; schwer (lourd) ; leicht (léger) ; alt (vieux) ; schnell (rapide) ; fahren = rouler ; kosten = coûter.*","bareme":[{"critere":"Comparatifs de supériorité justes avec als (poids, âge, vitesse)","points":6},{"critere":"Égalité exprimée par so… wie pour le prix","points":4},{"critere":"Préférence exprimée avec lieber","points":4},{"critere":"immer + comparatif : immer teurer","points":3},{"critere":"Formes justes : Umlaut d'älter, orthographe de teurer","points":3}],"dureeMin":10,"corrige":"**1. Exemples de réponses**\n- Prix : *Rad X ist **so teuer wie** Rad Y.* — même prix → égalité.\n- Poids : *Rad X ist **schwerer als** Rad Y.* (ou *Rad Y ist leichter als Rad X.*)\n- Âge : *Rad X ist **älter als** Rad Y.* — Umlaut : *alt → älter*.\n- Vitesse : *Rad Y ist **schneller als** Rad X.*\n\n**2.** *Noah fährt **lieber** mit Rad Y.* (ou *Noah mag Rad Y lieber.*) — *gern → lieber* = préférer.\n\n**3.** *Die Fahrräder werden **immer teurer**.* — *immer* + comparatif = de plus en plus.\n\nToute formulation correcte est acceptée ; *als* après le comparatif et *wie* après *so* sont exigés."}$exo$::jsonb),
  ('767d36b0-23c9-5d5a-a234-49c83e6b76a9'::uuid, 3, 'traduction', $exo${"titre":"Comparer sans se tromper","consigne":"Corrige le texte de Hugo en justifiant, traduis les trois phrases, puis compare deux saisons en trois phrases.","enonce":"**Document — Le texte de Hugo**\n\n> Mein Bruder ist mehr groß als ich. Er hat ein größer Zimmer. Er ist so alt als mein Cousin. Je mehr er trainiert, desto er wird stärker.\n\n1. Le texte contient **quatre fautes**. Corrige chaque phrase et justifie.\n2. Traduis en allemand :\n   - a. Plus je lis, mieux je comprends.\n   - b. Mon frère aîné a un plus grand vélo.\n   - c. Il fait de plus en plus froid.\n3. Compare l'été et l'hiver en **trois phrases** : une avec *als*, une avec *so… wie* ou *nicht so… wie*, une avec *lieber*.\n\n*Aide : lesen, verstehen ; das Fahrrad ; kalt ; der Sommer, der Winter ; lang (long) ; die Tage.*","bareme":[{"critere":"Les quatre fautes corrigées : größer, größeres, so alt wie, desto stärker wird er","points":8},{"critere":"Traductions justes : je… desto, älterer / größeres déclinés, immer kälter","points":6},{"critere":"Trois phrases de comparaison correctes (als, so… wie, lieber)","points":6}],"dureeMin":16,"corrige":"**1. Corrections**\n- *mehr groß* → **größer** : *mehr* traduit une quantité, jamais le comparatif d'un adjectif.\n- *ein größer Zimmer* → **ein größeres Zimmer** : le comparatif épithète se décline ; neutre après *ein* → *-es*.\n- *so alt als* → **so alt wie** : égalité = *so… wie*.\n- *desto er wird stärker* → **desto stärker wird er** : après *desto*, le comparatif vient d'abord, puis le verbe, puis le sujet (*Je mehr er trainiert, desto stärker wird er.*).\n\n**2.**\n- a. *Je mehr ich lese, desto (umso) besser verstehe ich.*\n- b. *Mein **älterer** Bruder hat ein **größeres** Fahrrad.* — deux terminaisons : celle du comparatif, puis celle de la déclinaison.\n- c. *Es wird **immer kälter**.*\n\n**3. Exemple de réponse**\n- *Im Sommer sind die Tage länger als im Winter.*\n- *Der Winter ist nicht so warm wie der Sommer.*\n- *Ich mag den Sommer lieber als den Winter.*"}$exo$::jsonb),
  ('d6ae8e29-9651-5f5d-afb2-b22204f0127d'::uuid, 1, 'traduction', $exo${"titre":"Les superlatifs à connaître","consigne":"Donne le superlatif en am … -sten de chaque adjectif, puis choisis la bonne forme dans les deux phrases de la question 2.","enonce":"**1. Donne la forme en *am … -sten*.**\n\nschnell · alt · kurz · groß · gut · viel · gern · hoch\n\n**2. Choisis la bonne forme et justifie en une phrase.**\n\n1. Der ICE ist *am schnellsten / der schnellste*.\n2. Das ist *am schnellsten / der schnellste* Zug.","bareme":[{"critere":"Superlatifs réguliers justes, avec le e de liaison et l'exception groß : schnellsten, ältesten, kürzesten, größten","points":8},{"critere":"Irréguliers justes : besten, meisten, liebsten, höchsten","points":8},{"critere":"Choix justifié : am -sten en attribut, der -ste devant un nom","points":4}],"dureeMin":6,"corrige":"**1.**\n- schnell → **am schnellsten**\n- alt → **am ältesten** (e de liaison après *t*, et Umlaut)\n- kurz → **am kürzesten** (e de liaison après *z*)\n- groß → **am größten** (exception : pas de e)\n- gut → **am besten**\n- viel → **am meisten**\n- gern → **am liebsten**\n- hoch → **am höchsten**\n\n**2.**\n1. *Der ICE ist **am schnellsten**.* — l'adjectif est attribut (après *sein*) : forme figée *am … -sten*.\n2. *Das ist **der schnellste** Zug.* — l'adjectif est épithète, devant le nom : *der … -ste*, qui se décline."}$exo$::jsonb),
  ('d6ae8e29-9651-5f5d-afb2-b22204f0127d'::uuid, 2, 'traduction', $exo${"titre":"Le sondage de la classe","consigne":"Lis le tableau du cours de sport, puis réponds en allemand par des phrases complètes.","enonce":"**Document — 100 mètres, classe 3eB**\n\n| Élève | Temps | Âge |\n| Tim | 12,4 s | 15 ans |\n| Mia | 13,1 s | 14 ans |\n| Jonas | 14,0 s | 16 ans |\n\n1. *Wer läuft am schnellsten?*\n2. *Wer ist am ältesten? Wer ist am jüngsten?*\n3. Écris une phrase qui dit que Tim est **le coureur le plus rapide de tous**, avec l'adjectif devant le nom. *(der Läufer = le coureur)*\n4. Écris deux phrases qui disent ce que tu préfères faire par-dessus tout, en sport et le week-end.\n\n*Aide : jung = jeune.*","bareme":[{"critere":"Forme am … -sten juste en attribut et en adverbe (schnellsten, ältesten, jüngsten)","points":6},{"critere":"Superlatif épithète décliné : der schnellste Läufer","points":6},{"critere":"Complément du superlatif juste : von allen + datif","points":4},{"critere":"Deux phrases correctes avec am liebsten et l'inversion","points":4}],"dureeMin":10,"corrige":"**1.** *Tim läuft **am schnellsten**.* — adverbe : forme figée.\n\n**2.** *Jonas ist **am ältesten**.* (e de liaison après *t*, Umlaut) — *Mia ist **am jüngsten**.*\n\n**3.** *Tim ist **der schnellste Läufer von allen**.* — épithète devant le nom → *der schnellste* ; complément introduit par *von* + datif. (*Tim ist der Schnellste von allen* est aussi accepté.)\n\n**4. Exemple de réponse**\n- *Am liebsten spiele ich Basketball.*\n- *Am Wochenende schlafe ich am liebsten lange.*\n\n*am liebsten* = ce que je préfère par-dessus tout ; placé en tête, il entraîne l'inversion verbe-sujet."}$exo$::jsonb),
  ('d6ae8e29-9651-5f5d-afb2-b22204f0127d'::uuid, 3, 'traduction', $exo${"titre":"Le meilleur et le plus haut","consigne":"Traduis les phrases, corrige les deux erreurs du document, puis explique la règle des deux formes du superlatif.","enonce":"**1. Traduis en allemand.**\n\n1. Berlin est la plus grande ville d'Allemagne. *(deux façons)*\n2. Ce que je préfère par-dessus tout, c'est lire des romans policiers.\n3. Je joue avec mon meilleur ami.\n4. La Zugspitze est la montagne la plus haute d'Allemagne.\n5. C'est lui qui a le plus d'argent.\n\n**Document — deux phrases d'un élève**\n\n> a. Das ist der Zug am schnellsten.\n> b. Paula ist am altsten.\n\n**2.** Corrige les deux phrases du document.\n**3.** Explique en quelques lignes, en français, comment on choisit entre les deux formes du superlatif.\n\n*Aide : die Stadt ; der Krimi, die Krimis ; der Freund ; der Berg ; das Geld.*","bareme":[{"critere":"Phrases 1 et 4 : superlatif épithète décliné et complément de lieu (in + datif ou génitif)","points":5},{"critere":"Phrases 2, 3 et 5 : am liebsten avec inversion, meinem besten Freund, am meisten","points":5},{"critere":"Les deux phrases du document corrigées : der schnellste Zug, am ältesten","points":5},{"critere":"Explication : attribut ou adverbe → am -sten figé ; épithète → der -ste décliné","points":5}],"dureeMin":16,"corrige":"**1.**\n1. *Berlin ist **die größte Stadt in Deutschland**.* / *Berlin ist **Deutschlands größte Stadt**.* — épithète féminine ; complément avec *in* + datif ou génitif.\n2. ***Am liebsten** lese ich Krimis.* — *am liebsten* n'est pas « le plus aimé » mais « ce que je préfère » ; inversion après l'adverbe.\n3. *Ich spiele mit **meinem besten** Freund.* — *mit* + datif, superlatif épithète décliné.\n4. *Die Zugspitze ist **der höchste Berg** Deutschlands* (ou *in Deutschland*). — *hoch → höchste*, *Berg* masculin.\n5. *Er hat **am meisten** Geld.* — *viel → am meisten*.\n\n**2.**\n- a. *Das ist **der schnellste Zug**.* — devant un nom, on emploie la forme déclinée.\n- b. *Paula ist **am ältesten**.* — après *t*, on intercale un *e* ; *alt* prend aussi l'Umlaut.\n\n**3.** Le superlatif a deux formes selon la **place** de l'adjectif. Quand il est **attribut** (après *sein*) ou **adverbe** (*er läuft…*), on emploie *am* + *-sten*, forme figée qui ne se décline pas. Quand il est **épithète**, devant un nom, on emploie *der / die / das* + *-ste*, qui se décline comme un adjectif (*mit dem besten Freund*). Dans les deux cas, on ajoute un *e* de liaison après *d, t, s, ß, z, sch* (sauf *groß → größten*)."}$exo$::jsonb),
  ('8cb594f7-69cf-5649-aae3-a6b786833efe'::uuid, 1, 'traduction', $exo${"titre":"Durch, für, gegen, ohne, um","consigne":"Complète chaque phrase avec la préposition qui convient et, s'il le faut, la terminaison de l'article ou du possessif.","enonce":"**1. Complète avec *durch, für, gegen, ohne* ou *um*.**\n\n1. Wir gehen ___ d__ Park. *(à travers — der Park)*\n2. Das Geschenk ist ___ mein__ Schwester. *(pour)*\n3. Ich trinke den Kaffee ___ Zucker. *(sans)*\n4. Wir sitzen ___ d__ Tisch. *(autour de — der Tisch)*\n5. Ich bin ___ dies__ Idee. *(contre — die Idee)*\n6. Der Film beginnt ___ acht Uhr. *(à huit heures pile)*\n\n**2.** Quel cas suit ces cinq prépositions ? Explique pourquoi on écrit *den Park* et non *der Park* dans la phrase 1.","bareme":[{"critere":"Prépositions justes : durch, für, ohne, um, gegen, um","points":8},{"critere":"Terminaisons de l'accusatif justes : den Park, meine Schwester, den Tisch, diese Idee","points":8},{"critere":"Explication : ces prépositions imposent toujours l'accusatif, masculin der → den","points":4}],"dureeMin":6,"corrige":"**1.**\n1. Wir gehen **durch den** Park.\n2. Das Geschenk ist **für meine** Schwester.\n3. Ich trinke den Kaffee **ohne** Zucker. — *ohne* se passe souvent d'article.\n4. Wir sitzen **um den** Tisch.\n5. Ich bin **gegen diese** Idee.\n6. Der Film beginnt **um** acht Uhr. — heure précise → *um* (*gegen acht Uhr* = vers huit heures).\n\n**2.** *durch, für, gegen, ohne, um* imposent **toujours l'accusatif**, quel que soit le sens. Au masculin, l'article *der* devient *den* à l'accusatif : *durch den Park*. Au féminin et au neutre, la forme ne change pas (*meine Schwester*, *diese Idee*)."}$exo$::jsonb),
  ('8cb594f7-69cf-5649-aae3-a6b786833efe'::uuid, 2, 'traduction', $exo${"titre":"Le message d'Emma","consigne":"Emma répond à une invitation. Traduis son message en allemand, puis réponds à la question 2.","enonce":"**Le message d'Emma, en français**\n\n1. J'arrive vers huit heures.\n2. Le cadeau est pour ton frère.\n3. Nous marchons le long de la rivière.\n4. Je vais jusqu'à la gare en bus.\n5. Je viens sans mon vélo.\n\n*Aide : kommen ; das Geschenk ; der Bruder ; laufen ; der Fluss ; fahren ; der Bahnhof ; mit dem Bus ; das Fahrrad.*\n\n**2.** Emma hésite entre *gegen acht Uhr* et *um acht Uhr*. Explique la différence.","bareme":[{"critere":"Prépositions justes : gegen, für, entlang, bis zum, ohne","points":7},{"critere":"Accusatif juste après les prépositions : deinen Bruder, den Fluss, mein Fahrrad","points":6},{"critere":"Place d'entlang après le nom et bis suivi de zum","points":3},{"critere":"Différence gegen (vers) / um (heure précise) expliquée","points":4}],"dureeMin":10,"corrige":"**Traduction modèle**\n1. *Ich komme **gegen** acht Uhr.* — heure approximative.\n2. *Das Geschenk ist **für deinen** Bruder.* — *für* + accusatif ; masculin → *deinen*.\n3. *Wir laufen **den Fluss entlang**.* — *entlang* se place **après** le nom, qui est à l'accusatif.\n4. *Ich fahre mit dem Bus **bis zum** Bahnhof.* — *bis* est souvent suivi d'une seconde préposition (*zum* = *zu dem*).\n5. *Ich komme **ohne mein** Fahrrad.* — *Fahrrad* neutre : *mein* à l'accusatif.\n\n**2.** *gegen acht Uhr* = **vers** huit heures (approximatif) ; *um acht Uhr* = **à** huit heures pile. Une seule préposition d'écart change l'heure du rendez-vous."}$exo$::jsonb),
  ('8cb594f7-69cf-5649-aae3-a6b786833efe'::uuid, 3, 'traduction', $exo${"titre":"Pour apprendre, pas für lernen","consigne":"Corrige le texte de Jules en justifiant chaque correction, puis rédige une invitation de quatre phrases.","enonce":"**Document — Le texte de Jules**\n\n> Ich lerne Deutsch für in Berlin studieren. Jeden Morgen gehe ich durch dem Wald. Das Buch ist für mein Vater. Am Sonntag laufen wir entlang die Straße.\n\n1. Chaque phrase contient **une faute**. Recopie les phrases corrigées.\n2. Justifie chaque correction en une phrase.\n3. Rédige en allemand une **invitation de quatre phrases** à une fête d'anniversaire, avec **quatre prépositions différentes** parmi *durch, für, gegen, ohne, um, bis, entlang*.\n\n*Aide : die Party ; der Geburtstag ; der Garten ; der Kuchen.*","bareme":[{"critere":"Quatre corrections justes : um… zu studieren, durch den Wald, für meinen Vater, die Straße entlang","points":8},{"critere":"Justifications : für devant un nom seulement, accusatif obligatoire, place d'entlang","points":4},{"critere":"Invitation : quatre prépositions différentes suivies de l'accusatif correct","points":6},{"critere":"Invitation compréhensible, verbes conjugués et ordre des mots corrects","points":2}],"dureeMin":16,"corrige":"**1. Texte corrigé**\n\n> *Ich lerne Deutsch, **um in Berlin zu studieren**. Jeden Morgen gehe ich **durch den** Wald. Das Buch ist **für meinen** Vater. Am Sonntag laufen wir **die Straße entlang**.*\n\n**2. Justifications**\n- « Pour + verbe » ne se dit pas *für* : *für* introduit un groupe nominal, jamais un verbe. Le but se dit **um… zu** + infinitif.\n- *durch* impose l'**accusatif** : *der Wald* → *den Wald* (et non le datif *dem*).\n- *für* impose l'accusatif : *Vater* masculin → *meinen Vater*.\n- *entlang* se place **après** le nom : *die Straße entlang*.\n\n**3. Exemple de réponse**\n\n> *Hallo Tim! Ich mache am Samstag eine Party für meinen Geburtstag. Die Party beginnt um drei Uhr. Wir essen Kuchen und spielen im Garten bis zum Abend. Komm nicht ohne deinen Bruder!*\n\nToute invitation correcte employant quatre prépositions différentes avec l'accusatif juste est acceptée."}$exo$::jsonb),
  ('fd09c791-70ea-5173-911b-70d1064fb715'::uuid, 1, 'traduction', $exo${"titre":"Aus, bei, mit, nach, seit, von, zu","consigne":"Complète chaque phrase avec la préposition entre parenthèses et la terminaison du datif, en contractant quand c'est l'usage.","enonce":"**1. Complète.**\n\n1. Ich fahre ___ d__ Bus in die Stadt. *(avec)*\n2. Er kommt ___ d__ Schweiz. *(de — die Schweiz)*\n3. Ich wohne ___ mein__ Eltern. *(chez)*\n4. Ich gehe heute ___ Arzt. *(chez — contracté)*\n5. ___ d__ Film essen wir Pizza. *(après — der Film)*\n6. Ich lerne ___ ein__ Jahr Deutsch. *(depuis — das Jahr)*\n\n**2.** Dans la phrase 6, pourquoi le verbe est-il au présent alors que le français pourrait hésiter ? Explique en une phrase.","bareme":[{"critere":"Prépositions justes : mit, aus, bei, zum, nach, seit","points":6},{"critere":"Terminaisons du datif justes : dem Bus, der Schweiz, meinen Eltern, dem Film, einem Jahr","points":8},{"critere":"Contraction zum employée","points":2},{"critere":"Explication : seit + présent","points":4}],"dureeMin":6,"corrige":"**1.**\n1. Ich fahre **mit dem** Bus in die Stadt.\n2. Er kommt **aus der** Schweiz. — féminin au datif → *der*.\n3. Ich wohne **bei meinen** Eltern. — datif pluriel → *-en*.\n4. Ich gehe heute **zum** Arzt. — *zu dem* → *zum*, contraction obligatoire dans l'usage.\n5. **Nach dem** Film essen wir Pizza. — masculin datif → *dem* ; inversion après le complément.\n6. Ich lerne **seit einem** Jahr Deutsch. — neutre datif → *einem*.\n\n**2.** Avec *seit*, l'action a commencé dans le passé et **dure encore** : l'allemand emploie le **présent**, comme le français (« j'apprends l'allemand depuis un an »)."}$exo$::jsonb),
  ('fd09c791-70ea-5173-911b-70d1064fb715'::uuid, 2, 'traduction', $exo${"titre":"Le voyage de Noah","consigne":"Noah raconte ses projets de voyage. Traduis ses phrases en allemand, puis explique tes choix de préposition.","enonce":"**1. Traduis en allemand.**\n\n1. Cet été, je vais en Autriche.\n2. Ensuite, je vais en Suisse.\n3. Je vais chez ma tante.\n4. Le soir, je rentre à la maison.\n5. Le dimanche, je suis à la maison.\n6. J'habite à Munich depuis deux ans.\n\n*Aide : Österreich (sans article) ; die Schweiz ; die Tante ; fahren, gehen ; wohnen ; München ; das Jahr, die Jahre ; im Sommer ; dann ; abends ; sonntags.*\n\n**2.** Explique quand on emploie *nach*, *in* + accusatif et *zu* pour dire où l'on va.","bareme":[{"critere":"Choix juste de nach, in die et zu selon le lieu (phrases 1 à 3)","points":7},{"critere":"Datif et contractions justes : zu meiner Tante, seit zwei Jahren","points":5},{"critere":"Expressions figées nach Hause / zu Hause bien employées","points":4},{"critere":"seit + présent, et règle nach / in / zu expliquée","points":4}],"dureeMin":10,"corrige":"**1. Traduction modèle**\n1. *Im Sommer fahre ich **nach Österreich**.* — pays sans article → *nach*.\n2. *Dann fahre ich **in die Schweiz**.* — pays avec article → *in* + accusatif.\n3. *Ich fahre **zu meiner** Tante.* — personne → *zu* + datif.\n4. *Abends gehe ich **nach Hause**.* — avec mouvement.\n5. *Sonntags bin ich **zu Hause**.* — sans mouvement.\n6. *Ich wohne **seit zwei Jahren** in München.* — *seit* + datif pluriel (*Jahren*) et verbe au **présent**.\n\n**2.** Pour dire où l'on va : **nach** devant un pays ou une ville **sans article** (*nach Wien*) ; **in** + accusatif devant un pays **avec article** (*in die Schweiz, in die Türkei*) ; **zu** + datif devant une **personne** ou un bâtiment vu comme un but (*zum Arzt, zur Post*). *nach Hause* / *zu Hause* sont des expressions figées."}$exo$::jsonb),
  ('fd09c791-70ea-5173-911b-70d1064fb715'::uuid, 3, 'traduction', $exo${"titre":"Une journée à Hambourg","consigne":"Corrige le texte d'Hugo en justifiant, puis décris ta propre journée en quatre phrases.","enonce":"**Document — Le texte d'Hugo**\n\n> Seit drei Jahren habe ich in Hamburg gewohnt. Jeden Tag fahre ich mit meinem Fahrrad zu die Schule. Nach der Schule gehe ich bei meinem Freund Max. Im Juli fahren wir nach die Türkei. Meine Mutter kommt aus Frankreich.\n\n1. Le texte contient **quatre fautes**. Recopie les phrases fautives corrigées.\n2. Justifie chaque correction.\n3. Une phrase du texte est entièrement correcte : laquelle ? Explique pourquoi.\n4. Décris ta journée en **quatre phrases** en employant au moins quatre prépositions différentes parmi *aus, bei, mit, nach, seit, von, zu*.","bareme":[{"critere":"Quatre corrections : Seit… wohne ich, zur Schule, zu meinem Freund, in die Türkei","points":8},{"critere":"Justifications : seit + présent, contraction, zu pour une destination, pays avec article","points":4},{"critere":"Phrase correcte identifiée : aus Frankreich, pays sans article, aus + origine","points":2},{"critere":"Quatre phrases personnelles avec quatre prépositions à datif bien construites","points":6}],"dureeMin":16,"corrige":"**1. Corrections**\n- *Seit drei Jahren **wohne ich** in Hamburg.*\n- *Jeden Tag fahre ich mit meinem Fahrrad **zur** Schule.*\n- *Nach der Schule gehe ich **zu meinem** Freund Max.*\n- *Im Juli fahren wir **in die** Türkei.*\n\n**2. Justifications**\n- Avec *seit*, l'action dure encore : **présent**, pas parfait.\n- *zu* impose le datif : *zu der* → contraction **zur** (obligatoire dans l'usage).\n- On **va** chez quelqu'un : *zu* + datif ; *bei* indique qu'on **est** chez lui (sans mouvement).\n- *die Türkei* a un article : on emploie **in** + accusatif, pas *nach*.\n\n**3.** *Meine Mutter kommt aus Frankreich* est correct : *aus* + datif marque l'origine, et *Frankreich* s'emploie sans article.\n\n**4. Exemple de réponse**\n- *Ich fahre mit dem Bus zur Schule.*\n- *Nach dem Unterricht esse ich bei meiner Oma.*\n- *Ich lerne seit vier Jahren Deutsch.*\n- *Am Abend bekomme ich eine Nachricht von meinem Freund.*"}$exo$::jsonb),
  ('cc00a503-7d91-51e2-8703-5e8a4e2089c1'::uuid, 1, 'traduction', $exo${"titre":"Wo ou wohin ?","consigne":"Complète chaque phrase avec l'article au bon cas, puis explique ton choix pour les phrases 1 et 2.","enonce":"**1. Complète avec l'article.**\n\n1. Ich gehe in ___ Schule. *(die Schule)*\n2. Ich bin in ___ Schule.\n3. Das Bild hängt an ___ Wand. *(die Wand)*\n4. Die Katze liegt unter ___ Tisch. *(der Tisch)*\n5. Die Katze läuft unter ___ Tisch. *(elle s'y glisse)*\n6. Das Heft liegt neben ___ Buch. *(das Buch)*\n\n**2.** Explique pourquoi l'article n'est pas le même dans les phrases 1 et 2.","bareme":[{"critere":"Accusatif juste en cas de déplacement (wohin) : die Schule, den Tisch","points":8},{"critere":"Datif juste en cas de localisation (wo) : der Schule, der Wand, dem Tisch, dem Buch","points":8},{"critere":"Explication avec les questions wo ? / wohin ?","points":4}],"dureeMin":6,"corrige":"**1.**\n1. Ich gehe in **die** Schule. — *wohin?* déplacement → accusatif.\n2. Ich bin in **der** Schule. — *wo?* localisation → datif.\n3. Das Bild hängt an **der** Wand. — état → datif.\n4. Die Katze liegt unter **dem** Tisch. — *wo?* → datif.\n5. Die Katze läuft unter **den** Tisch. — elle change de lieu (*wohin?*) → accusatif.\n6. Das Heft liegt neben **dem** Buch. — *wo?* → datif.\n\n**2.** Les neuf prépositions mixtes changent de cas selon le sens. Dans la phrase 1, il y a un **changement de lieu** (question *wohin?*) → **accusatif** ; dans la phrase 2, une **localisation** (question *wo?*) → **datif**."}$exo$::jsonb),
  ('cc00a503-7d91-51e2-8703-5e8a4e2089c1'::uuid, 2, 'traduction', $exo${"titre":"Clara range sa chambre","consigne":"Complète chaque paire de phrases avec le verbe conjugué et l'article au bon cas, puis réponds à la question 2.","enonce":"**1. Complète.** Dans chaque paire, la phrase **a** décrit l'action, la phrase **b** le résultat.\n\n1. a. Clara ___ die Lampe auf ___ Schreibtisch. *(stellen / stehen)* — b. Die Lampe ___ auf ___ Schreibtisch.\n2. a. Sie ___ das Buch auf ___ Bett. *(legen / liegen)* — b. Das Buch ___ auf ___ Bett.\n3. a. Sie ___ das Poster an ___ Wand. *(hängen)* — b. Das Poster ___ an ___ Wand.\n\n*der Schreibtisch, das Bett, die Wand*\n\n**2.** Contracte : *in das Zimmer* ; *an dem Fenster* ; *auf das Bett*.","bareme":[{"critere":"Couples de verbes justes et conjugués : stellt / steht, legt / liegt, hängt / hängt","points":8},{"critere":"Accusatif pour l'action, datif pour l'état : den / dem Schreibtisch, das / dem Bett, die / der Wand","points":8},{"critere":"Contractions justes : ins, am, aufs","points":4}],"dureeMin":10,"corrige":"**1.**\n1. a. Clara **stellt** die Lampe auf **den** Schreibtisch. — action → accusatif. b. Die Lampe **steht** auf **dem** Schreibtisch. — état → datif.\n2. a. Sie **legt** das Buch auf **das** (*aufs*) Bett. b. Das Buch **liegt** auf **dem** Bett.\n3. a. Sie **hängt** das Poster an **die** Wand. — *hängen* faible = accrocher. b. Das Poster **hängt** an **der** Wand. — *hängen* fort = être accroché.\n\nLes verbes d'action (*stellen, legen, setzen, hängen* faible) appellent l'accusatif ; les verbes d'état (*stehen, liegen, sitzen, hängen* fort) le datif.\n\n**2.** *in das Zimmer* → **ins Zimmer** ; *an dem Fenster* → **am Fenster** ; *auf das Bett* → **aufs Bett**."}$exo$::jsonb),
  ('cc00a503-7d91-51e2-8703-5e8a4e2089c1'::uuid, 3, 'traduction', $exo${"titre":"Même verbe, deux cas","consigne":"Traduis les phrases en allemand, puis explique en français la méthode qui permet de choisir le cas.","enonce":"**1. Traduis en allemand.**\n\n1. Je cours dans le parc (à l'intérieur du parc).\n2. J'entre en courant dans le parc.\n3. Je pose la bouteille sur la table.\n4. La bouteille est sur la table.\n5. Je me réjouis des vacances.\n6. En janvier, nous allons au cinéma.\n\n*Aide : laufen ; der Park ; die Flasche ; der Tisch ; sich freuen auf ; die Ferien (pluriel) ; der Januar ; das Kino.*\n\n**2.** En quelques lignes, explique pourquoi les phrases 1 et 2 n'ont pas le même cas alors que le verbe est le même, et donne la méthode à suivre pour choisir l'article.","bareme":[{"critere":"Phrases 1 et 2 : im Park (datif) / in den Park (accusatif)","points":5},{"critere":"Phrases 3 et 4 : stellen + accusatif, stehen + datif","points":4},{"critere":"Emplois figés justes : auf die Ferien (accusatif), im Januar, ins Kino avec inversion","points":5},{"critere":"Explication : c'est le changement de lieu, pas le verbe, qui décide ; méthode wo ? / wohin ?","points":6}],"dureeMin":15,"corrige":"**1. Traduction modèle**\n1. *Ich laufe **im Park**.* — je cours à l'intérieur : pas de changement de lieu → datif (*in dem* → *im*).\n2. *Ich laufe **in den Park**.* — j'y entre : changement de lieu → accusatif.\n3. *Ich **stelle** die Flasche auf **den** Tisch.* — action → accusatif.\n4. *Die Flasche **steht** auf **dem** Tisch.* — état → datif.\n5. *Ich freue mich **auf die** Ferien.* — emploi figé : *sich freuen auf* + accusatif.\n6. ***Im** Januar gehen wir **ins** Kino.* — *im Januar* figé ; *ins Kino* = déplacement ; inversion après le complément de temps.\n\n**2.** Ce n'est pas le verbe de mouvement qui décide, mais le **changement de lieu** : dans la phrase 1, on court en restant dans le parc (*wo?* → datif) ; dans la phrase 2, on passe de l'extérieur à l'intérieur (*wohin?* → accusatif). Méthode : trouver le **verbe**, se demander **wo?** ou **wohin?**, et n'écrire l'article qu'**ensuite**. Certaines expressions ne relèvent plus du lieu et s'apprennent telles quelles (*im Januar, sich freuen auf* + accusatif)."}$exo$::jsonb),
  ('cefc03ac-43b5-5bc8-9ad9-cb5eaae10195'::uuid, 1, 'traduction', $exo${"titre":"Relier deux phrases","consigne":"Relie chaque paire de phrases avec la conjonction indiquée, en respectant la virgule et l'ordre des mots.","enonce":"**1. Relie les deux phrases.**\n\n1. Ich bleibe zu Hause. Ich bin krank. *(denn)*\n2. Er ist arm. Er ist glücklich. *(aber)*\n3. Das ist nicht mein Buch. Es ist deins. *(sondern)*\n4. Trinkst du Tee? Trinkst du Kaffee? *(oder)*\n5. Ich spiele Fußball. Mein Bruder spielt Tennis. *(und)*\n\n**2.** Dans la phrase 3, pourquoi faut-il *sondern* et non *aber* ?","bareme":[{"critere":"Phrases reliées sans changer l'ordre des mots après la conjonction (verbe en 2e position)","points":10},{"critere":"Virgule devant denn, aber et sondern, pas devant und ni oder","points":5},{"critere":"Explication : sondern après une négation","points":5}],"dureeMin":6,"corrige":"**1.**\n1. *Ich bleibe zu Hause, **denn** ich bin krank.* — après *denn*, rien ne bouge : sujet puis verbe.\n2. *Er ist arm, **aber** glücklich.* (ou *…, aber er ist glücklich.*)\n3. *Das ist nicht mein Buch, **sondern** deins.*\n4. *Trinkst du Tee **oder** Kaffee?*\n5. *Ich spiele Fußball **und** mein Bruder spielt Tennis.*\n\nLes conjonctions de coordination occupent la **position zéro** : elles ne comptent pas dans l'ordre des mots.\n\n**2.** *sondern* (« mais au contraire ») s'emploie après une **négation** pour rectifier : *nicht mein Buch, sondern deins*. *aber* s'emploie sans négation, pour une opposition simple."}$exo$::jsonb),
  ('cefc03ac-43b5-5bc8-9ad9-cb5eaae10195'::uuid, 2, 'traduction', $exo${"titre":"Trois syntaxes pour une même idée","consigne":"Réécris chaque idée avec les mots de liaison demandés, puis explique où se place le verbe dans chaque cas.","enonce":"**1. Idée : nous restons à la maison parce qu'il pleut.**\n\nÉcris la phrase de trois façons :\na. avec *denn* ;\nb. avec *weil* ;\nc. avec *deshalb*.\n\n*(Wir bleiben zu Hause. — Es regnet.)*\n\n**2. Idée : je suis fatigué, pourtant je continue à travailler.**\n\nÉcris la phrase de deux façons :\na. avec *aber* ;\nb. avec *trotzdem*.\n\n*(Ich bin müde. — Ich lerne weiter.)*\n\n**3.** Explique en français, pour *denn*, *weil* et *deshalb*, où se place le verbe conjugué.","bareme":[{"critere":"Phrase avec denn : ordre normal, virgule","points":4},{"critere":"Phrase avec weil : verbe conjugué à la fin","points":4},{"critere":"Phrases avec deshalb et trotzdem : inversion verbe-sujet","points":6},{"critere":"Explication des trois places du verbe (coordination, subordination, adverbe)","points":6}],"dureeMin":10,"corrige":"**1.**\na. *Wir bleiben zu Hause, **denn** es regnet.*\nb. *Wir bleiben zu Hause, **weil** es **regnet**.*\nc. *Es regnet, **deshalb bleiben wir** zu Hause.*\n\n**2.**\na. *Ich bin müde, **aber** ich lerne weiter.*\nb. *Ich bin müde, **trotzdem lerne ich** weiter.*\n\n**3.**\n- Après **denn** (coordination) : la conjonction est en position zéro, rien ne bouge — sujet puis verbe en **2e position**.\n- Après **weil** (subordination) : le verbe conjugué part **à la fin** de la subordonnée.\n- Après **deshalb** (adverbe de liaison, comme *trotzdem*) : l'adverbe occupe la **1re position**, le verbe reste en 2e position, donc le sujet passe derrière : **inversion**.\n\nTrois syntaxes pour un même lien logique : les confondre est l'erreur la plus fréquente en expression écrite."}$exo$::jsonb),
  ('cefc03ac-43b5-5bc8-9ad9-cb5eaae10195'::uuid, 3, 'traduction', $exo${"titre":"Donner son avis en nuances","consigne":"Traduis les phrases, corrige les deux erreurs du document, puis donne ton avis en quatre phrases.","enonce":"**1. Traduis en allemand.**\n\n1. Ni mon frère ni ma sœur ne parlent allemand.\n2. Il joue non seulement au football, mais aussi au tennis.\n3. Ou bien nous allons au cinéma, ou bien nous restons à la maison.\n4. Certes, le voyage est cher, mais il est intéressant.\n\n**Document — deux phrases d'élève**\n\n> a. Ich spiele nicht Tennis, aber Fußball.\n> b. Weder Tom noch Lisa kommt nicht.\n\n**2.** Corrige les deux phrases et justifie.\n\n**3.** Donne ton avis sur le téléphone portable au collège en **quatre phrases**, en utilisant *zwar… aber*, *denn* et *deshalb*.\n\n*Aide : die Reise ; teuer ; das Handy ; nützlich (utile) ; stören (déranger) ; im Unterricht.*","bareme":[{"critere":"Traductions justes des corrélatifs : weder… noch, nicht nur… sondern auch, entweder… oder, zwar… aber","points":8},{"critere":"Corrections justifiées : sondern après négation, pas de nicht après weder… noch","points":4},{"critere":"Avis : zwar… aber, denn (sans inversion) et deshalb (avec inversion) bien construits","points":6},{"critere":"Avis cohérent et compréhensible","points":2}],"dureeMin":18,"corrige":"**1. Traduction modèle**\n1. *Weder mein Bruder noch meine Schwester spricht Deutsch.* (*sprechen* au pluriel est aussi accepté) — la phrase est déjà négative : pas de *nicht*.\n2. *Er spielt nicht nur Fußball, sondern auch Tennis.*\n3. *Entweder gehen wir ins Kino, oder wir bleiben zu Hause.* (*Entweder wir gehen…* est aussi accepté.)\n4. *Die Reise ist zwar teuer, aber (sie ist) interessant.*\n\n**2.**\n- a. *Ich spiele nicht Tennis, **sondern** Fußball.* — après une négation, on rectifie avec *sondern*.\n- b. *Weder Tom noch Lisa **kommt**.* — *weder… noch* porte déjà la négation : ajouter *nicht* est une faute.\n\n**3. Exemple de réponse**\n\n> *Das Handy ist zwar nützlich, aber es stört im Unterricht. Viele Schüler spielen im Unterricht, denn sie sind nicht konzentriert. Deshalb bin ich für ein Handyverbot in der Klasse. Nach der Schule ist das Handy aber okay.*\n\nSont vérifiés : *zwar* après le verbe et *aber* en tête de la seconde partie, *denn* sans changement d'ordre, *deshalb* suivi de l'inversion."}$exo$::jsonb),
  ('3fbce238-20b2-58e6-8151-86349b454de2'::uuid, 1, 'traduction', $exo${"titre":"Wo, wohin, woher ?","consigne":"Complète chaque phrase avec la préposition (et l'article contracté si besoin), puis indique la question à laquelle elle répond.","enonce":"**1. Complète, puis écris à côté *wo?*, *wohin?* ou *woher?*.**\n\n1. Ich fahre ___ Deutschland.\n2. Ich komme ___ Frankreich.\n3. Im Sommer fahren wir ___ Meer. *(das Meer)*\n4. Heute Abend gehe ich ___ Kino. *(das Kino)*\n5. Ich bin gerade ___ Arzt. *(der Arzt)*\n6. Mama kommt um sechs Uhr ___ der Arbeit.","bareme":[{"critere":"Prépositions justes : nach, aus, ans, ins, beim, von","points":12},{"critere":"Contractions correctes : ans, ins, beim","points":4},{"critere":"Question juste pour chaque phrase","points":4}],"dureeMin":6,"corrige":"1. Ich fahre **nach** Deutschland. — *wohin?* pays sans article.\n2. Ich komme **aus** Frankreich. — *woher?* venir d'un pays.\n3. Im Sommer fahren wir **ans** Meer. — *wohin?* un bord : *an* + accusatif (*an das* → *ans*).\n4. Heute Abend gehe ich **ins** Kino. — *wohin?* nom avec article : *in* + accusatif (*in das* → *ins*).\n5. Ich bin gerade **beim** Arzt. — *wo?* chez une personne sans mouvement : *bei dem* → *beim*.\n6. Mama kommt um sechs Uhr **von** der Arbeit. — *woher?* point de départ : *von* + datif."}$exo$::jsonb),
  ('3fbce238-20b2-58e6-8151-86349b454de2'::uuid, 2, 'traduction', $exo${"titre":"Dialogue avant les vacances","consigne":"Complète le dialogue entre Ben et Aylin, puis traduis les deux paires de phrases de la question 2.","enonce":"**1. Complète le dialogue.**\n\n> Ben: Wohin fährst du in den Ferien?\n> Aylin: Ich fahre ___ Land zu meiner Oma. *(à la campagne)*\n> Ben: Wo wohnt sie genau?\n> Aylin: Sie wohnt ___ Land, in einem kleinen Dorf.\n> Ben: Und dein Vater? Woher kommt er?\n> Aylin: Er kommt ___ Türkei. Im August fahren wir alle ___ Türkei.\n\n**2. Traduis en allemand.**\na. Je vais chez le médecin. / Je suis chez le médecin.\nb. Il part à l'étranger. / Il vit à l'étranger.\n\n*Aide : das Ausland = l'étranger ; der Arzt.*","bareme":[{"critere":"Paire aufs Land / auf dem Land juste","points":4},{"critere":"aus der Türkei (origine) et in die Türkei (destination) justes","points":4},{"critere":"zum Arzt / beim Arzt justes","points":6},{"critere":"ins Ausland / im Ausland justes","points":6}],"dureeMin":10,"corrige":"**1.**\n- Ich fahre **aufs** Land zu meiner Oma. — mouvement : *auf* + accusatif (*auf das* → *aufs*).\n- Sie wohnt **auf dem** Land. — sans mouvement : datif.\n- Er kommt **aus der** Türkei. — origine : *aus* + datif ; pays avec article féminin → *der*.\n- Im August fahren wir alle **in die** Türkei. — destination, pays avec article → *in* + accusatif (jamais *nach*).\n\n**2.**\na. *Ich gehe **zum** Arzt.* (mouvement vers une personne) / *Ich bin **beim** Arzt.* (sans mouvement). Le français dit « chez » dans les deux cas ; l'allemand oblige à choisir.\nb. *Er geht (fährt) **ins** Ausland.* / *Er lebt **im** Ausland.* — expressions figées par paires : une avec mouvement (accusatif), une sans (datif)."}$exo$::jsonb),
  ('3fbce238-20b2-58e6-8151-86349b454de2'::uuid, 3, 'traduction', $exo${"titre":"Hin, her et le récit d'un voyage","consigne":"Traduis les phrases de la question 1, rédige le récit demandé, puis réponds à la question 3 en français.","enonce":"**1. Traduis en allemand.**\na. Viens ici !\nb. Vas-y !\nc. Où vas-tu ? *(deux façons)*\nd. D'où viens-tu ? *(deux façons)*\n\n**2.** Raconte en **six phrases** un voyage imaginaire : d'où tu pars, où tu vas, chez qui, où tu dors, ce que tu visites. Emploie au moins **cinq** constructions différentes parmi : *nach, in* + accusatif, *zu, an* + accusatif, *aus, von, bei*.\n\n**3.** Explique la différence entre *hineingehen* et *herauskommen* en t'appuyant sur le sens de *hin* et *her*.","bareme":[{"critere":"Impératifs justes : Komm her!, Geh hin!","points":3},{"critere":"Questions justes : Wohin / Wo… hin, Woher / Wo… her","points":4},{"critere":"Récit : cinq constructions de lieu différentes avec le bon cas","points":7},{"critere":"Récit compréhensible, verbes conjugués correctement","points":2},{"critere":"Explication : hin = éloignement du locuteur, her = rapprochement","points":4}],"dureeMin":18,"corrige":"**1.**\na. *Komm **her**!* — rapprochement vers celui qui parle.\nb. *Geh **hin**!* — éloignement.\nc. *Wohin gehst du?* / *Wo gehst du **hin**?*\nd. *Woher kommst du?* / *Wo kommst du **her**?* — la particule peut se détacher et partir en fin de phrase.\n\n**2. Exemple de réponse**\n\n> *Ich komme aus Lyon. Im Juli fahre ich mit dem Zug nach Berlin. Dort gehe ich zu meinem Brieffreund Jonas. Ich schlafe bei seiner Familie. Am Montag gehen wir ins Museum. Am Wochenende fahren wir ans Meer.*\n\nConstructions attendues : *aus* (origine), *nach* (ville sans article), *zu* + datif (personne), *bei* + datif (sans mouvement), *in* + accusatif (*ins Museum*), *an* + accusatif (*ans Meer*).\n\n**3.** *hin* marque l'**éloignement** du locuteur, *her* le **rapprochement**. *hineingehen* = entrer, vu de **dehors** (on s'éloigne de celui qui parle) ; *herauskommen* = sortir, vu de **dedans** (on vient vers celui qui parle). Ces particules se soudent aux prépositions pour former des préverbes."}$exo$::jsonb),
  ('69c4595a-9fe5-5a40-b550-9ebe8fb5cfec'::uuid, 1, 'traduction', $exo${"titre":"Am, im ou um ?","consigne":"Complète chaque complément de temps, puis traduis les trois expressions de la question 2.","enonce":"**1. Complète avec *am*, *im*, *um* ou *in der*.**\n\n1. ___ Montag\n2. ___ Sommer\n3. ___ acht Uhr\n4. ___ Januar\n5. ___ Abend\n6. ___ Jahr 2026\n7. ___ Nacht\n8. ___ Mitternacht\n\n**2.** Traduis et explique la différence : *morgen* ; *morgens* ; *am Morgen*.","bareme":[{"critere":"am devant les jours et parties de la journée : am Montag, am Abend","points":4},{"critere":"im devant mois, saisons, années : im Sommer, im Januar, im Jahr 2026","points":4},{"critere":"um devant l'heure précise et exception in der Nacht","points":4},{"critere":"Sens juste de morgen, morgens, am Morgen","points":8}],"dureeMin":6,"corrige":"**1.**\n1. **am** Montag — jour\n2. **im** Sommer — saison\n3. **um** acht Uhr — heure précise\n4. **im** Januar — mois\n5. **am** Abend — partie de la journée\n6. **im** Jahr 2026 — année\n7. **in der** Nacht — exception (et non *am*)\n8. **um** Mitternacht — heure précise\n\n**2.**\n- *morgen* = **demain**.\n- *morgens* = **le matin, en général**, habituellement (adverbe).\n- *am Morgen* = **ce matin-là**, un matin précis.\n\nUn seul *s* d'écart suffit à changer le sens."}$exo$::jsonb),
  ('69c4595a-9fe5-5a40-b550-9ebe8fb5cfec'::uuid, 2, 'traduction', $exo${"titre":"L'agenda de Lina","consigne":"Traduis les phrases de l'agenda de Lina en commençant chaque phrase par le complément de temps.","enonce":"**L'agenda de Lina, en français**\n\n1. Chaque jour, je vais au collège.\n2. Il y a deux semaines, j'étais à Vienne.\n3. Dans une heure, le film commence.\n4. J'apprends l'allemand depuis trois ans. *(commence par « Seit… »)*\n5. Pendant les vacances, je lis beaucoup.\n6. Du lundi au vendredi, je me lève tôt.\n\n*Aide : in die Schule gehen ; die Woche ; Wien ; die Stunde ; beginnen ; die Ferien (pluriel) ; lesen ; früh aufstehen (ich stehe … auf).*","bareme":[{"critere":"Prépositions et cas justes : vor zwei Wochen, in einer Stunde, seit drei Jahren, während der Ferien, von… bis","points":8},{"critere":"Accusatif sans préposition : jeden Tag","points":3},{"critere":"Inversion verbe-sujet après le complément de temps en tête","points":5},{"critere":"seit + présent","points":4}],"dureeMin":10,"corrige":"**Traduction modèle**\n1. ***Jeden Tag** gehe ich in die Schule.* — durée ou date entière : accusatif sans préposition.\n2. ***Vor zwei Wochen** war ich in Wien.* — *vor* + datif = il y a.\n3. ***In einer Stunde** beginnt der Film.* — *in* + datif = dans (futur).\n4. ***Seit drei Jahren** lerne ich Deutsch.* — *seit* + datif pluriel, verbe au **présent**.\n5. ***Während der Ferien** lese ich viel.* — *während* + génitif ; *Ferien* pluriel → *der*.\n6. ***Von Montag bis Freitag** stehe ich früh auf.*\n\nDans chaque phrase, le complément de temps ouvre la phrase : le verbe reste en 2e position et le sujet passe **derrière** (inversion)."}$exo$::jsonb),
  ('69c4595a-9fe5-5a40-b550-9ebe8fb5cfec'::uuid, 3, 'traduction', $exo${"titre":"Des vacances en Italie","consigne":"Corrige le texte d'Inès en justifiant, puis raconte ta journée type en cinq phrases.","enonce":"**Document — La carte postale d'Inès**\n\n> Am Sommer fahre ich nach Italien. Ich bin dort seit zwei Wochen gewesen. Um Abend esse ich Pizza. Morgens stehe ich um neun Uhr auf. Nächsten Woche ich fahre nach Hause.\n\n1. Le texte contient **quatre phrases fautives** (une phrase est correcte). Corrige-les.\n2. Justifie chaque correction.\n3. Raconte ta journée type en **cinq phrases**, avec **cinq compléments de temps différents** ; au moins deux phrases commencent par le complément de temps.","bareme":[{"critere":"Corrections : Im Sommer, Ich bin seit zwei Wochen dort, Am Abend, Nächste Woche fahre ich","points":8},{"critere":"Justifications : im / am, seit + présent, accusatif sans préposition, inversion","points":4},{"critere":"Journée type : cinq compléments de temps différents et justes","points":5},{"critere":"Inversion correcte quand le complément ouvre la phrase","points":3}],"dureeMin":16,"corrige":"**1. Texte corrigé**\n\n> ***Im** Sommer fahre ich nach Italien. Ich **bin** seit zwei Wochen dort. **Am** Abend esse ich Pizza. Morgens stehe ich um neun Uhr auf. **Nächste Woche fahre ich** nach Hause.*\n\n**2. Justifications**\n- Saisons → **im** (*im Sommer*), pas *am*.\n- Avec *seit*, l'action dure encore : **présent** (*ich bin*), pas parfait.\n- Parties de la journée → **am** (*am Abend*) ; *um* est réservé à l'heure précise.\n- *nächste Woche* : accusatif sans préposition, **féminin** → *nächste* ; en tête de phrase, le verbe reste en 2e position → **inversion** (*fahre ich*).\n- La phrase *Morgens stehe ich um neun Uhr auf* est correcte (*morgens* = le matin, habituellement).\n\n**3. Exemple de réponse**\n\n> *Morgens stehe ich um sieben Uhr auf. Um acht Uhr beginnt der Unterricht. Am Mittag esse ich in der Kantine. Nach der Schule spiele ich Fußball. Am Abend lese ich ein Buch.*"}$exo$::jsonb),
  ('23b027cc-b04e-572e-b286-76f0ae9bd02d'::uuid, 1, 'traduction', $exo${"titre":"Sein, haben, werden","consigne":"Complète avec la bonne forme de sein, haben ou werden au temps indiqué, puis donne les trois participes.","enonce":"**1. Complète.**\n\n1. Ihr ___ müde. *(sein, présent)*\n2. Du ___ einen Hund. *(haben, présent)*\n3. Mein Bruder ___ Arzt. *(werden, présent : il devient)*\n4. Gestern ___ ich krank. *(sein, prétérit)*\n5. Wir ___ keine Zeit. *(haben, prétérit)*\n6. Es ___ kalt. *(werden, prétérit)*\n\n**2.** Donne le participe passé de *sein*, *haben* et *werden* (verbe plein).","bareme":[{"critere":"Présents justes : seid, hast, wird","points":8},{"critere":"Prétérits justes : war, hatten, wurde","points":6},{"critere":"Participes justes : gewesen, gehabt, geworden","points":6}],"dureeMin":6,"corrige":"**1.**\n1. Ihr **seid** müde. (attention : *seid* avec d, le verbe ; *seit* avec t est la préposition « depuis »)\n2. Du **hast** einen Hund.\n3. Mein Bruder **wird** Arzt. — *werden* verbe plein = devenir.\n4. Gestern **war** ich krank.\n5. Wir **hatten** keine Zeit.\n6. Es **wurde** kalt.\n\n**2.** *sein → **gewesen*** ; *haben → **gehabt*** ; *werden → **geworden*** (et *worden* seulement quand *werden* est auxiliaire du passif)."}$exo$::jsonb),
  ('23b027cc-b04e-572e-b286-76f0ae9bd02d'::uuid, 2, 'traduction', $exo${"titre":"Haben ou sein au parfait ?","consigne":"Complète chaque phrase au parfait avec haben ou sein conjugué, puis explique la différence entre les phrases 1 et 2.","enonce":"**1. Complète avec *haben* ou *sein*.**\n\n1. Ich ___ nach Berlin gefahren.\n2. Ich ___ das Auto meines Vaters gefahren.\n3. Er ___ um sieben Uhr aufgestanden.\n4. Wir ___ den ganzen Tag zu Hause geblieben.\n5. Sie ___ ein Buch gelesen.\n6. Was ___ passiert?\n7. Das Kind ___ schnell eingeschlafen.\n8. Ich ___ eine Pizza gegessen.\n\n**2.** Les phrases 1 et 2 ont le même verbe, mais pas le même auxiliaire. Explique pourquoi.","bareme":[{"critere":"sein pour les verbes de mouvement et de changement d'état : bin, ist aufgestanden, ist eingeschlafen","points":6},{"critere":"sein pour bleiben et passieren : sind geblieben, ist passiert","points":4},{"critere":"haben pour les autres verbes : habe gefahren (avec COD), hat gelesen, habe gegessen","points":4},{"critere":"Explication : fahren avec un COD prend haben, c'est le sens qui tranche","points":6}],"dureeMin":10,"corrige":"**1.**\n1. Ich **bin** nach Berlin gefahren. — déplacement.\n2. Ich **habe** das Auto meines Vaters gefahren. — *fahren* avec un COD (*das Auto*).\n3. Er **ist** um sieben Uhr aufgestanden. — changement d'état.\n4. Wir **sind** den ganzen Tag zu Hause geblieben. — *bleiben* prend toujours *sein*.\n5. Sie **hat** ein Buch gelesen.\n6. Was **ist** passiert? — *passieren* prend *sein*.\n7. Das Kind **ist** schnell eingeschlafen. — changement d'état.\n8. Ich **habe** eine Pizza gegessen.\n\n**2.** Dans la phrase 1, *fahren* exprime un **déplacement** d'un point à un autre : auxiliaire **sein** (je me suis déplacé). Dans la phrase 2, *fahren* a un **COD** (*das Auto*) : il signifie « conduire » et prend **haben**. C'est le sens de la phrase qui tranche, pas le verbe lui-même."}$exo$::jsonb),
  ('23b027cc-b04e-572e-b286-76f0ae9bd02d'::uuid, 3, 'traduction', $exo${"titre":"Les trois vies de werden","consigne":"Traduis les phrases, corrige la phrase du document, puis explique les emplois de werden.","enonce":"**1. Traduis en allemand.**\n\n1. Je deviens nerveux.\n2. Je reçois une lettre.\n3. Demain, il fera beau.\n4. La maison est en train d'être construite.\n5. Il est devenu médecin.\n6. La maison a été construite en 1990.\n\n*Aide : nervös ; der Brief ; das Wetter ; schön ; bauen (construire) ; der Arzt.*\n\n**Document — phrase d'un élève**\n\n> Ich habe gestern nach Paris gegangen.\n\n**2.** Corrige cette phrase et justifie.\n**3.** Explique en français les trois emplois de *werden* et pourquoi *bekommen* est un piège.","bareme":[{"critere":"werden verbe plein, futur et passif justes (phrases 1, 3, 4)","points":6},{"critere":"bekommen = recevoir (phrase 2)","points":2},{"critere":"Participes justes : ist… geworden, ist… gebaut worden","points":5},{"critere":"Phrase du document corrigée : bin gegangen, verbe de mouvement","points":3},{"critere":"Explication des trois emplois de werden et du faux ami bekommen","points":4}],"dureeMin":16,"corrige":"**1. Traduction modèle**\n1. *Ich **werde** nervös.* — verbe plein : devenir.\n2. *Ich **bekomme** einen Brief.* — *bekommen* = recevoir.\n3. *Morgen **wird** das Wetter schön (**sein**).* — auxiliaire du futur.\n4. *Das Haus **wird gebaut**.* — passif d'action : *werden* + participe.\n5. *Er **ist** Arzt **geworden**.* — parfait de *werden* verbe plein : *sein* + *geworden*.\n6. *Das Haus **ist** 1990 **gebaut worden**.* — parfait du passif : participe *worden*.\n\n**2.** *Ich **bin** gestern nach Paris **gegangen**.* — *gehen* est un verbe de mouvement d'un point à un autre : il forme son parfait avec **sein**.\n\n**3.** *werden* a trois emplois : **verbe plein** « devenir » (*Er wird Arzt*) ; **auxiliaire du futur** (*Es wird regnen*) ; **auxiliaire du passif** d'action (*Das Haus wird gebaut*). Au participe, il fait *geworden* comme verbe plein, *worden* dans un passif. *bekommen* ressemble à « become » ou « devenir », mais il signifie **recevoir** : « je deviens » se dit *ich werde*. La confusion produit un contresens complet."}$exo$::jsonb),
  ('a9623262-cdfd-5fed-9dfe-c6df75188108'::uuid, 1, 'traduction', $exo${"titre":"Les temps primitifs","consigne":"Donne les trois temps primitifs (infinitif, prétérit, participe II) de chaque verbe et classe-le.","enonce":"**1. Recopie et complète le tableau.**\n\n| Infinitif | Prétérit (er) | Participe II | Famille |\n| machen | | | |\n| spielen | | | |\n| fahren | | | |\n| schreiben | | | |\n| nehmen | | | |\n| gehen | | | |\n| studieren | | | |\n| bringen | | | |\n\n*Familles : faible, fort, mixte, verbe en -ieren.*\n\n**2.** Quelle différence vois-tu entre le participe d'un verbe faible et celui d'un verbe fort ?","bareme":[{"critere":"Verbes faibles justes : machte / gemacht, spielte / gespielt","points":4},{"critere":"Verbes forts justes : fuhr / gefahren, schrieb / geschrieben, nahm / genommen, ging / gegangen","points":8},{"critere":"Cas particuliers : studierte / studiert sans ge-, brachte / gebracht (mixte)","points":4},{"critere":"Différence ge-…-t / ge-…-en expliquée","points":4}],"dureeMin":8,"corrige":"**1.**\n| Infinitif | Prétérit | Participe II | Famille |\n| machen | machte | gemacht | faible |\n| spielen | spielte | gespielt | faible |\n| fahren | fuhr | gefahren | fort |\n| schreiben | schrieb | geschrieben | fort |\n| nehmen | nahm | genommen | fort |\n| gehen | ging | gegangen | fort |\n| studieren | studierte | studiert | en -ieren (faible, sans ge-) |\n| bringen | brachte | gebracht | mixte |\n\n**2.** Le participe d'un verbe **faible** se forme en *ge-… **-t*** et garde son radical (*gemacht*). Celui d'un verbe **fort** se forme en *ge-… **-en*** et change souvent de voyelle (*gesprochen, genommen*). Le mixte a un radical modifié mais des terminaisons faibles (*gebracht*)."}$exo$::jsonb),
  ('a9623262-cdfd-5fed-9dfe-c6df75188108'::uuid, 2, 'traduction', $exo${"titre":"Le samedi de Max","consigne":"Complète les phrases au présent, puis mets le récit de Max au prétérit.","enonce":"**1. Conjugue au présent.**\n\n1. Du ___ gut Deutsch. *(sprechen)*\n2. Er ___ mir das Buch. *(geben)*\n3. ___ du den Film heute Abend? *(sehen)*\n4. Sie ___ einen Roman. *(lesen)*\n5. Du ___ zu schnell! *(fahren)*\n6. Wir ___ ihm ein Geschenk. *(geben)*\n\n**2. Réécris le récit au prétérit.**\n\n> Am Samstag fahre ich nach Köln. Ich nehme den Zug. Im Zug schreibe ich eine Karte. In Köln kaufe ich ein T-Shirt und spiele mit meinem Cousin Fußball.","bareme":[{"critere":"Changement de voyelle aux 2e et 3e personnes du singulier : sprichst, gibt, siehst, liest, fährst","points":8},{"critere":"Pas de changement au pluriel : wir geben","points":2},{"critere":"Prétérits forts justes : fuhr, nahm, schrieb","points":6},{"critere":"Prétérits faibles justes : kaufte, spielte","points":4}],"dureeMin":10,"corrige":"**1.**\n1. Du **sprichst** gut Deutsch. — *e → i*.\n2. Er **gibt** mir das Buch. — *e → i*.\n3. **Siehst** du den Film heute Abend? — *e → ie*.\n4. Sie **liest** einen Roman. — *e → ie*.\n5. Du **fährst** zu schnell! — *a → ä*.\n6. Wir **geben** ihm ein Geschenk. — au pluriel, pas de changement.\n\n**2. Récit au prétérit**\n\n> *Am Samstag **fuhr** ich nach Köln. Ich **nahm** den Zug. Im Zug **schrieb** ich eine Karte. In Köln **kaufte** ich ein T-Shirt und **spielte** mit meinem Cousin Fußball.*\n\n- Verbes forts : la voyelle change et il n'y a pas de terminaison à la 1re personne (*fuhr, nahm, schrieb*).\n- Verbes faibles : radical inchangé + *-te* (*kaufte, spielte*)."}$exo$::jsonb),
  ('a9623262-cdfd-5fed-9dfe-c6df75188108'::uuid, 3, 'traduction', $exo${"titre":"Lire un récit au prétérit","consigne":"Analyse les verbes du récit, réécris-en une partie au parfait, puis traduis la dernière phrase.","enonce":"**Document — Le voyage de Paul**\n\n> Letzten Sommer **fuhr** Paul nach Hamburg. Er **nahm** den Zug und **schrieb** seiner Mutter eine Karte. Er **kaufte** ein Souvenir und **telefonierte** mit seinem Freund. Am Abend **dachte** er an seine Familie.\n\n1. Pour chaque verbe en gras, donne l'**infinitif** et la **famille** (fort, faible, mixte, en -ieren).\n2. Réécris les deux premières phrases du récit au **parfait**. *(Aide : fahren se conjugue avec sein au parfait, les autres avec haben.)*\n3. Traduis en allemand : **Il parle allemand et elle lit un livre.**","bareme":[{"critere":"Infinitifs justes : fahren, nehmen, schreiben, kaufen, telefonieren, denken","points":5},{"critere":"Familles justes : trois forts, un faible, un en -ieren, un mixte","points":4},{"critere":"Parfait juste : ist gefahren, hat genommen, geschrieben, gekauft, telefoniert (sans ge-)","points":7},{"critere":"Traduction avec les changements de voyelle : spricht, liest","points":4}],"dureeMin":16,"corrige":"**1.**\n| Forme | Infinitif | Famille |\n| fuhr | fahren | fort |\n| nahm | nehmen | fort |\n| schrieb | schreiben | fort |\n| kaufte | kaufen | faible (-te) |\n| telefonierte | telefonieren | en -ieren (faible) |\n| dachte | denken | mixte (radical modifié, terminaison faible) |\n\n**2. Au parfait**\n\n> *Letzten Sommer **ist** Paul nach Hamburg **gefahren**. Er **hat** den Zug **genommen** und seiner Mutter eine Karte **geschrieben**.*\n\n(La suite, si l'élève la réécrit : *Er hat ein Souvenir **gekauft** und mit seinem Freund **telefoniert**.* — pas de *ge-* pour les verbes en *-ieren* ; *Am Abend hat er an seine Familie **gedacht**.*)\n\n**3.** *Er **spricht** Deutsch und sie **liest** ein Buch.* — verbes forts : *e → i* (*sprechen*) et *e → ie* (*lesen*) à la 3e personne du singulier."}$exo$::jsonb),
  ('cad5c6bf-e3a1-5759-a79e-8ac9b48b24b2'::uuid, 1, 'traduction', $exo${"titre":"Le bon modal","consigne":"Complète chaque phrase avec le verbe de modalité qui convient, conjugué au présent, puis réponds à la question 2.","enonce":"**1. Complète.**\n\n1. Ich ___ gut schwimmen. *(capacité)*\n2. ___ ich reinkommen? *(autorisation)*\n3. Du ___ heute lernen, morgen ist der Test. *(nécessité)*\n4. Wir ___ im Sommer nach Berlin fahren. *(volonté)*\n5. Ich ___ einen Kaffee, bitte. *(demande polie)*\n6. Der Arzt sagt, er ___ im Bett bleiben. *(consigne venue d'autrui)*\n\n**2.** Dans la phrase 3, où se place l'infinitif *lernen* ? Énonce la règle.","bareme":[{"critere":"Modal juste selon le sens : kann, darf, musst, wollen, möchte, soll","points":8},{"critere":"Conjugaison juste, sans terminaison aux 1re et 3e personnes du singulier","points":8},{"critere":"Règle : modal en 2e position, infinitif à la fin","points":4}],"dureeMin":6,"corrige":"**1.**\n1. Ich **kann** gut schwimmen. — *können* : capacité.\n2. **Darf** ich reinkommen? — *dürfen* : permission.\n3. Du **musst** heute lernen, morgen ist der Test. — *müssen* : nécessité.\n4. Wir **wollen** im Sommer nach Berlin fahren. — *wollen* : volonté.\n5. Ich **möchte** einen Kaffee, bitte. — forme polie de *mögen*.\n6. Der Arzt sagt, er **soll** im Bett bleiben. — *sollen* : consigne venue d'autrui.\n\n**2.** Dans une principale, le modal conjugué est en **2e position** et l'infinitif part **à la fin** de la phrase : *Du musst heute **lernen**.*"}$exo$::jsonb),
  ('cad5c6bf-e3a1-5759-a79e-8ac9b48b24b2'::uuid, 2, 'traduction', $exo${"titre":"Le règlement de l'auberge","consigne":"Lis le règlement de l'auberge de jeunesse, puis réponds aux questions en allemand.","enonce":"**Document — Jugendherberge Bremen**\n\n> Rauchen verboten! — Frühstück von 7 bis 9 Uhr. — Die Zimmer sind um 10 Uhr frei. — Fahrräder: 8 Euro pro Tag. — Die Küche ist für alle offen.\n\n1. Écris **quatre phrases** avec *man* + un modal pour résumer le règlement : une interdiction, une obligation, une possibilité, une autorisation.\n2. Traduis et explique la différence : *Du musst nicht kommen.* / *Du darfst nicht rauchen.*\n3. Relie les deux phrases avec *weil* : *Ich kann heute nicht kommen. Ich muss lernen.*\n\n*Aide : rauchen ; frühstücken ; das Zimmer verlassen (quitter la chambre) ; mieten (louer) ; kochen.*","bareme":[{"critere":"Quatre phrases avec man + modal adapté au sens (darf nicht, muss, kann, darf)","points":8},{"critere":"Négation : muss nicht = pas obligé, darf nicht = interdiction","points":6},{"critere":"Subordonnée avec weil : infinitif puis modal à la fin","points":6}],"dureeMin":10,"corrige":"**1. Exemples de réponses**\n- Interdiction : *Man **darf** hier nicht **rauchen**.*\n- Obligation : *Man **muss** das Zimmer um 10 Uhr **verlassen**.*\n- Possibilité : *Man **kann** Fahrräder **mieten**.* (ou *Man kann von 7 bis 9 Uhr frühstücken.*)\n- Autorisation : *Man **darf** in der Küche **kochen**.*\n\n**2.**\n- *Du musst nicht kommen* = **tu n'es pas obligé** de venir.\n- *Du darfst nicht rauchen* = **tu n'as pas le droit** de fumer (interdiction).\n*müssen* + négation supprime l'obligation ; l'interdiction se dit avec *nicht dürfen*.\n\n**3.** *Ich kann heute nicht kommen, **weil** ich **lernen muss**.* — en subordonnée, tout part à la fin : l'infinitif, puis le modal conjugué."}$exo$::jsonb),
  ('cad5c6bf-e3a1-5759-a79e-8ac9b48b24b2'::uuid, 3, 'traduction', $exo${"titre":"Ce qu'on a dû faire","consigne":"Transforme les phrases au passé, traduis la phrase rapportée, puis écris un court texte sur tes projets.","enonce":"**1. Mets au parfait.**\na. Ich muss arbeiten.\nb. Er kann nicht kommen.\nc. Ich will es. *(sans infinitif)*\n\n**2. Mets au prétérit.**\na. Wir können nicht schwimmen.\nb. Sie muss lernen.\n\n**3.** Traduis en allemand, avec *sollen* : « Le médecin m'a dit de rester au lit. » (Commence par *Ich…*)\n\n**4.** Écris **quatre phrases** sur tes projets pour l'été, avec **quatre modaux différents**.\n\n*Aide : im Bett bleiben ; im Sommer ; arbeiten, reisen, schlafen.*","bareme":[{"critere":"Parfait avec double infinitif : habe arbeiten müssen, hat nicht kommen können ; participe gewollt sans infinitif","points":6},{"critere":"Prétérits justes sans Umlaut : konnten, musste","points":4},{"critere":"sollen employé pour rapporter une consigne : Ich soll im Bett bleiben","points":3},{"critere":"Quatre phrases avec quatre modaux différents, bien conjugués, infinitif à la fin","points":7}],"dureeMin":16,"corrige":"**1.**\na. *Ich **habe arbeiten müssen**.* — avec un infinitif dépendant : **double infinitif**, pas de participe.\nb. *Er **hat nicht kommen können**.*\nc. *Ich **habe es gewollt**.* — sans infinitif, le participe existe.\n\n**2.**\na. *Wir **konnten** nicht schwimmen.*\nb. *Sie **musste** lernen.* — prétérit régulier, **sans inflexion**.\n\n**3.** *Ich **soll** im Bett bleiben.* — *sollen* rapporte une consigne extérieure (on m'a dit de…).\n\n**4. Exemple de réponse**\n\n> *Im Sommer will ich nach Österreich reisen. Dort kann ich wandern. Ich darf zum ersten Mal allein fahren. Aber ich muss vorher etwas Geld verdienen.*\n\nSont vérifiés : un modal différent par phrase, conjugué, et l'infinitif en fin de phrase."}$exo$::jsonb),
  ('162e7a35-e97d-546e-bef9-b6784356df19'::uuid, 1, 'traduction', $exo${"titre":"Le préverbe à sa place","consigne":"Construis chaque phrase au présent, puis donne le participe passé de chaque verbe.","enonce":"**1. Construis la phrase au présent.**\n\n1. aufstehen — ich — um sieben Uhr\n2. einkaufen — wir — am Samstag\n3. anrufen — er — seine Mutter\n4. besuchen — ich — meine Tante\n5. verstehen — du — den Text\n\n**2.** Donne le participe passé de : *aufstehen, einkaufen, anrufen, besuchen, verstehen*.","bareme":[{"critere":"Préverbe séparable en fin de phrase : stehe… auf, kaufen… ein, ruft… an","points":8},{"critere":"Verbes inséparables non coupés : besuche, verstehst","points":4},{"critere":"Participes justes : aufgestanden, eingekauft, angerufen (ge- intercalé), besucht, verstanden (sans ge-)","points":8}],"dureeMin":6,"corrige":"**1.**\n1. *Ich **stehe** um sieben Uhr **auf**.* — le préverbe ferme la phrase.\n2. *Wir **kaufen** am Samstag **ein**.*\n3. *Er **ruft** seine Mutter **an**.*\n4. *Ich **besuche** meine Tante.* — *be-* est inséparable : rien ne bouge.\n5. *Du **verstehst** den Text.* — *ver-* inséparable.\n\n**2.**\n- *aufstehen → **aufgestanden*** ; *einkaufen → **eingekauft*** ; *anrufen → **angerufen*** — le *ge-* s'intercale entre le préverbe et le radical.\n- *besuchen → **besucht*** ; *verstehen → **verstanden*** — inséparables : **pas de ge-**."}$exo$::jsonb),
  ('162e7a35-e97d-546e-bef9-b6784356df19'::uuid, 2, 'traduction', $exo${"titre":"La journée de Lukas","consigne":"À partir des notes de Lukas, rédige sa journée en allemand, puis transforme deux phrases comme demandé.","enonce":"**Document — Les notes de Lukas**\n\n| Heure | Action |\n| 7 h | aufstehen |\n| 8 h | mit dem Bus abfahren |\n| 17 h | im Supermarkt einkaufen |\n| 19 h | fernsehen |\n| 22 h | einschlafen |\n\n1. Écris **cinq phrases** au présent sur la journée de Lukas (3e personne). Commence au moins deux phrases par l'heure.\n2. Relie avec *weil* : *Lukas ist müde. Er steht um sieben Uhr auf.*\n3. Complète avec *zu* : *Lukas hat keine Lust, ___ (einkaufen).*","bareme":[{"critere":"Préverbe en fin de phrase dans les principales : steht… auf, fährt… ab, kauft… ein, sieht… fern, schläft… ein","points":8},{"critere":"Inversion quand l'heure ouvre la phrase et verbes forts bien conjugués (fährt, sieht, schläft)","points":4},{"critere":"Subordonnée : préverbe recollé en fin (aufsteht)","points":4},{"critere":"zu intercalé : einzukaufen","points":4}],"dureeMin":10,"corrige":"**1. Exemple de réponse**\n- *Um sieben Uhr **steht** Lukas **auf**.*\n- *Um acht Uhr **fährt** er mit dem Bus **ab**.*\n- *Um siebzehn Uhr **kauft** er im Supermarkt **ein**.*\n- *Um neunzehn Uhr **sieht** er **fern**.*\n- *Um zweiundzwanzig Uhr **schläft** er **ein**.*\n\nLe préverbe séparable ferme la phrase ; l'heure en tête entraîne l'inversion ; *fahren, sehen, schlafen* changent de voyelle à la 3e personne.\n\n**2.** *Lukas ist müde, **weil** er um sieben Uhr **aufsteht**.* — en subordonnée, le préverbe se **recolle** au verbe, à la fin.\n\n**3.** *Lukas hat keine Lust, **einzukaufen**.* — le *zu* s'intercale entre le préverbe et le radical."}$exo$::jsonb),
  ('162e7a35-e97d-546e-bef9-b6784356df19'::uuid, 3, 'traduction', $exo${"titre":"Kommen et sa famille","consigne":"Donne le sens des verbes, traduis les phrases, puis explique comment reconnaître un préverbe séparable.","enonce":"**1.** Donne le sens de : *kommen, ankommen, bekommen, mitkommen, umkommen*.\n\n**2. Traduis en allemand.**\na. Le train arrive à huit heures.\nb. Je reçois un cadeau.\nc. Tu viens avec nous ?\nd. Elle traduit le texte.\ne. Le train est arrivé. *(parfait avec sein)*\nf. J'ai reçu un cadeau. *(parfait avec haben)*\n\n*Aide : der Zug ; das Geschenk ; übersetzen ; der Text.*\n\n**3.** Explique en français le test qui permet de savoir si un préverbe est séparable, et pourquoi *übersetzen* peut être les deux.","bareme":[{"critere":"Sens justes des cinq verbes","points":4},{"critere":"Phrases au présent : kommt… an, bekomme, Kommst du mit?, übersetzt (non coupé)","points":6},{"critere":"Participes : ist angekommen (ge- intercalé), habe bekommen (sans ge-)","points":4},{"critere":"Explication : test de l'accent et double statut selon le sens concret ou figuré","points":6}],"dureeMin":16,"corrige":"**1.** *kommen* = venir ; *ankommen* = arriver ; *bekommen* = recevoir ; *mitkommen* = accompagner, venir avec ; *umkommen* = périr. Le sens dépend entièrement du préverbe.\n\n**2.**\na. *Der Zug **kommt** um acht Uhr **an**.*\nb. *Ich **bekomme** ein Geschenk.* — *be-* inséparable.\nc. ***Kommst** du **mit**?*\nd. *Sie **übersetzt** den Text.* — sens figuré (traduire) → inséparable.\ne. *Der Zug **ist angekommen**.* — *ge-* intercalé.\nf. *Ich **habe** ein Geschenk **bekommen**.* — inséparable : pas de *ge-*.\n\n**3.** Le seul critère fiable est l'**accent** : un préverbe **séparable** est accentué (*ÁN-kommen*), un préverbe **inséparable** ne l'est pas, l'accent tombe sur le radical (*be-KÓMMEN*). *über-* fait partie des préverbes à double statut : au sens **concret**, il est séparable (*Ich setze über* = je traverse en bateau) ; au sens **figuré**, il est inséparable (*Ich übersetze den Text* = je traduis)."}$exo$::jsonb),
  ('0a3658f3-c285-528d-b4cb-fcc46efab45e'::uuid, 1, 'traduction', $exo${"titre":"Mich ou mir ?","consigne":"Complète chaque phrase avec le pronom réfléchi qui convient, puis explique la différence entre les phrases 1 et 2.","enonce":"**1. Complète avec le pronom réfléchi.**\n\n1. Ich wasche ___.\n2. Ich wasche ___ die Hände.\n3. Du kaufst ___ ein Buch.\n4. Er freut ___ auf die Ferien.\n5. Wir interessieren ___ für Musik.\n6. Setzen Sie ___ bitte!\n\n**2.** Pourquoi écrit-on *mich* dans la phrase 1 et *mir* dans la phrase 2 ?","bareme":[{"critere":"Réfléchis à l'accusatif sans COD : mich, sich, uns","points":6},{"critere":"Réfléchis au datif en présence d'un COD : mir, dir","points":6},{"critere":"sich en minuscule dans le vouvoiement","points":3},{"critere":"Explication : un COD dans la phrase fait passer le réfléchi au datif","points":5}],"dureeMin":6,"corrige":"**1.**\n1. Ich wasche **mich**. — pas de COD → accusatif.\n2. Ich wasche **mir** die Hände. — *die Hände* est COD → datif.\n3. Du kaufst **dir** ein Buch. — COD *ein Buch* → datif.\n4. Er freut **sich** auf die Ferien.\n5. Wir interessieren **uns** für Musik.\n6. Setzen Sie **sich** bitte! — *sich* ne prend **jamais** de majuscule, même dans le vouvoiement.\n\n**2.** Dans la phrase 1, il n'y a pas d'autre complément : le réfléchi est le COD → **accusatif** (*mich*). Dans la phrase 2, il y a déjà un COD (*die Hände*) : le réfléchi passe au **datif** (*mir*). Les deux séries ne diffèrent qu'aux deux premières personnes du singulier."}$exo$::jsonb),
  ('0a3658f3-c285-528d-b4cb-fcc46efab45e'::uuid, 2, 'traduction', $exo${"titre":"Le message d'Ambre","consigne":"Ambre écrit à sa correspondante. Traduis ses phrases en allemand, puis réponds à la question 2.","enonce":"**1. Traduis en allemand.**\n\n1. Je me souviens de mes vacances.\n2. Je m'intéresse au sport.\n3. Je me réjouis de ton cadeau (je l'ai reçu).\n4. Je me réjouis du week-end (il n'est pas encore là).\n5. Je me lève à sept heures.\n6. Je suis souvent en retard.\n\n*Aide : sich erinnern ; der Sport ; das Geschenk ; das Wochenende ; aufstehen ; sich verspäten ; oft.*\n\n**2.** Explique pourquoi la phrase 5 n'a pas de pronom réfléchi en allemand et pourquoi la phrase 6 en a un.","bareme":[{"critere":"Prépositions justes suivies de l'accusatif : an meine Ferien, für Sport","points":6},{"critere":"auf (à venir) et über (déjà arrivé) bien distingués","points":6},{"critere":"Faux pronominaux : stehe… auf sans réfléchi, verspäte mich","points":4},{"critere":"Explication juste des faux pronominaux","points":4}],"dureeMin":10,"corrige":"**1. Traduction modèle**\n1. *Ich erinnere mich **an** meine Ferien.* — *sich erinnern an* + accusatif.\n2. *Ich interessiere mich **für** Sport.* — *sich interessieren für* + accusatif.\n3. *Ich freue mich **über** dein Geschenk.* — ce qui est déjà arrivé → *über*.\n4. *Ich freue mich **auf** das Wochenende.* — ce qui vient → *auf*.\n5. *Ich **stehe** um sieben Uhr **auf**.* — pas de pronom.\n6. *Ich **verspäte mich** oft.*\n\n**2.** Certains verbes pronominaux en français ne le sont pas en allemand : *aufstehen* (se lever) n'a pas de réfléchi. À l'inverse, *sich verspäten* (être en retard) est pronominal en allemand mais pas en français. Il faut apprendre chaque verbe avec sa construction."}$exo$::jsonb),
  ('0a3658f3-c285-528d-b4cb-fcc46efab45e'::uuid, 3, 'traduction', $exo${"titre":"Le pronom au bon endroit","consigne":"Place les pronoms, corrige le texte de Malo en justifiant, puis écris quatre phrases sur toi.","enonce":"**1. Place le pronom réfléchi au bon endroit.**\na. Gestern hat mein Bruder verletzt. *(sich)*\nb. Ich bin glücklich, weil ich freue. *(mich)*\nc. Heute Abend sehe ich den Film an. *(mir)*\n\n**Document — Le texte de Malo**\n\n> Jeden Morgen wasche ich mich die Haare. Mein Freund interessiert sich an Fußball. Nächste Woche beginnen die Ferien: wir freuen uns schon über die Ferien. Am Sonntag spaziere ich mich im Park.\n\n**2.** Chaque phrase contient une faute. Corrige-les et justifie.\n\n**3.** Écris **quatre phrases** sur toi avec quatre verbes pronominaux différents du cours (dont un au datif avec COD).","bareme":[{"critere":"Place juste du pronom : hat sich mein Bruder, weil ich mich freue, sehe mir… an","points":5},{"critere":"Corrections : mir die Haare, für Fußball, auf die Ferien, gehe… spazieren","points":6},{"critere":"Justifications : datif avec COD, bonne préposition, auf / über, faux pronominal","points":3},{"critere":"Quatre phrases personnelles correctes, dont un réfléchi au datif avec COD","points":6}],"dureeMin":16,"corrige":"**1.**\na. *Gestern hat **sich** mein Bruder verletzt.* — inversion : le pronom vient après le verbe, **avant** un sujet nominal.\nb. *Ich bin glücklich, weil ich **mich** freue.* — subordonnée : après le sujet.\nc. *Heute Abend sehe ich **mir** den Film an.* — COD *den Film* → datif, juste après le verbe et le sujet inversé.\n\n**2. Texte corrigé**\n- *Jeden Morgen wasche ich **mir** die Haare.* — il y a un COD (*die Haare*) → réfléchi au datif.\n- *Mein Freund interessiert sich **für** Fußball.* — *sich interessieren für* + accusatif.\n- *Wir freuen uns schon **auf** die Ferien.* — les vacances sont à venir → *auf* ; *über* pour ce qui est déjà arrivé.\n- *Am Sonntag **gehe** ich im Park **spazieren**.* — « se promener » n'est pas pronominal en allemand.\n\n**3. Exemple de réponse**\n- *Ich interessiere mich für Geschichte.*\n- *Ich erinnere mich gern an meine Kindheit.*\n- *Ich freue mich auf die Sommerferien.*\n- *Am Wochenende kaufe ich mir ein neues Buch.* — réfléchi au datif avec le COD *ein neues Buch*."}$exo$::jsonb),
  ('b531b475-2e30-50e9-8969-740d7561a192'::uuid, 1, 'traduction', $exo${"titre":"Les pays de langue allemande","consigne":"Réponds en français, sauf quand on te demande un mot allemand.","enonce":"**1.** Cite les **cinq pays** où l’allemand est langue officielle ou nationale, et donne la capitale de chacun.\n\n**2.** En Suisse, l’allemand est l’une des quatre langues nationales. Quelles sont les trois autres ?\n\n**3.** Qu’est-ce que le *Hochdeutsch* ? Où l’entend-on ou le lit-on ?\n\n**4.** Traduis en français : a) *die Muttersprache* b) *die Fremdsprache* c) *zweisprachig* d) *der Wortschatz*\n\n**5.** Comment dit-on « bonjour » en Allemagne, en Autriche et en Suisse ?","bareme":[{"critere":"Les cinq pays et leurs capitales justes (Berlin, Vienne, Berne, Vaduz, Luxembourg)","points":7},{"critere":"Les trois autres langues suisses et la définition du Hochdeutsch","points":5},{"critere":"Les quatre mots traduits et les trois salutations justes","points":8}],"dureeMin":7,"corrige":"**1.** L’**Allemagne** (capitale **Berlin**), l’**Autriche** (**Vienne**, *Wien*), la **Suisse** (**Berne**, *Bern*), le **Liechtenstein** (**Vaduz**) et le **Luxembourg** (**Luxembourg**). On parle aussi allemand dans l’est de la Belgique et dans le Tyrol du Sud, en Italie (réponse acceptée en plus, pas exigée).\n\n**2.** Le **français**, l’**italien** et le **romanche**.\n\n**3.** Le *Hochdeutsch* est l’allemand **standard** : celui de l’**école**, des **journaux** et de la **télévision**. En Suisse, c’est surtout la langue de l’écrit.\n\n**4.** a) la **langue maternelle** b) la **langue étrangère** c) **bilingue** d) le **vocabulaire**\n\n**5.** En Allemagne : *Guten Tag* ; en Autriche : *Grüß Gott* ou *Servus* ; en Suisse : *Grüezi*."}$exo$::jsonb),
  ('b531b475-2e30-50e9-8969-740d7561a192'::uuid, 2, 'traduction', $exo${"titre":"Nina, Suissesse et bilingue","consigne":"Lis le message de Nina, puis réponds aux questions 1 à 4 en français et à la question 5 en allemand.","enonce":"> *Hallo! Ich heiße Nina und ich wohne in Bern, in der Schweiz. Zu Hause spreche ich Schwiizerdütsch: das ist meine Muttersprache. In der Schule schreiben wir Hochdeutsch. Meine Mutter kommt aus Genf und spricht Französisch mit mir. Ich bin also zweisprachig! Mein Cousin Lukas wohnt in Wien. Er sagt „Servus“ und isst jeden Morgen eine Semmel. Und du? Welche Sprachen sprichst du?*\n\n*Genf* = Genève · *jeden Morgen* = chaque matin · *also* = donc\n\n1. Dans quelle ville et dans quel pays vit Nina ? Quel est le rôle de cette ville dans son pays ?\n2. Quelle langue parle-t-elle à la maison ? Laquelle écrit-elle à l’école ? Explique pourquoi c’est normal en Suisse.\n3. Pourquoi Nina dit-elle qu’elle est *zweisprachig* ? Traduis ce mot.\n4. Où vit Lukas ? Par quels mots un Allemand remplacerait-il *Servus* (pour dire bonjour) et *Semmel* ?\n5. Réponds à la question de Nina par une phrase en allemand.","bareme":[{"critere":"Berne, en Suisse, capitale du pays","points":4},{"critere":"Schwiizerdütsch à la maison, Hochdeutsch à l’écrit, avec l’explication de cet usage suisse","points":6},{"critere":"Zweisprachig traduit et justifié ; Lukas à Vienne, Guten Tag et das Brötchen","points":6},{"critere":"Une phrase allemande correcte qui répond à la question","points":4}],"dureeMin":10,"corrige":"1. Nina vit à **Berne** (*Bern*), en **Suisse**. Berne est la **capitale** de la Suisse.\n\n2. À la maison, elle parle **Schwiizerdütsch**, sa langue maternelle ; à l’école, elle écrit en **Hochdeutsch**. C’est normal : en Suisse alémanique, le *Schwiizerdütsch* est la **langue de tous les jours** et le *Hochdeutsch* la **langue de l’écrit**.\n\n3. *Zweisprachig* veut dire **bilingue**. Nina parle deux langues : l’allemand (le *Schwiizerdütsch*) et le **français**, que sa mère, originaire de Genève, lui parle.\n\n4. Lukas vit à **Vienne** (*Wien*), en **Autriche**. Un Allemand dirait *Guten Tag* à la place de *Servus*, et *das Brötchen* (le petit pain) à la place de *die Semmel*.\n\n5. Exemples : *Ich spreche Französisch und ein bisschen Deutsch.* / *Ich spreche Französisch, Englisch und ein bisschen Deutsch.* On attend le verbe *spreche* à la 1re personne et des noms de langues avec majuscule."}$exo$::jsonb),
  ('b531b475-2e30-50e9-8969-740d7561a192'::uuid, 3, 'traduction', $exo${"titre":"Une langue, mille façons de la parler","consigne":"Partie A en français (8 à 10 lignes), partie B en allemand (5 phrases au moins).","enonce":"**Situation.** En cours, ton camarade Théo affirme :\n\n> « L’allemand, c’est la langue de l’Allemagne, point. Et ceux qui parlent un dialecte parlent mal allemand. »\n\n**Partie A (français).** Réponds à Théo en un paragraphe argumenté. Tu montreras :\n- que l’allemand n’est pas la langue d’un seul pays (cite au moins **trois** pays et le statut de l’allemand) ;\n- qu’il existe un allemand standard et des dialectes (donne **deux exemples** de mots ou de salutations qui changent d’un pays à l’autre) ;\n- pourquoi parler un dialecte n’est pas « mal parler ».\n\n**Partie B (allemand).** Tu te présentes à un correspondant comme élève qui apprend l’allemand. Écris **au moins cinq phrases**. Utilise au moins **quatre** mots parmi : *die Muttersprache, die Fremdsprache, sprechen, verstehen, zweisprachig, der Wortschatz*, et au moins **une** expression du cours pour demander de l’aide.","bareme":[{"critere":"Au moins trois pays germanophones cités avec le statut de l’allemand (langue officielle, langue nationale en Suisse)","points":5},{"critere":"Distinction Hochdeutsch / dialectes illustrée par deux exemples justes","points":4},{"critere":"Argument : le dialecte est une identité régionale, pas une faute","points":3},{"critere":"Partie B : cinq phrases, quatre mots imposés et une expression d’aide bien employés","points":5},{"critere":"Correction de la langue allemande (verbe conjugué en 2e position, majuscules des noms)","points":3}],"dureeMin":16,"corrige":"**Partie A (exemple de réponse).** Théo se trompe. L’allemand est la langue officielle de l’**Allemagne**, mais aussi de l’**Autriche**, du **Liechtenstein** et du **Luxembourg** (avec le français et le luxembourgeois) ; en **Suisse**, c’est l’une des **quatre langues nationales**, avec le français, l’italien et le romanche. On le parle aussi dans l’est de la Belgique et au Tyrol du Sud. C’est même la langue maternelle la plus parlée de l’Union européenne, pour environ 100 millions de personnes.\nIl existe un allemand standard, le **Hochdeutsch**, celui de l’école, des journaux et de la télévision, et de nombreux **dialectes** : le bavarois, le souabe, le *Plattdeutsch*, le *Schwiizerdütsch*… Les mots changent : on dit *Guten Tag* en Allemagne, *Grüß Gott* en Autriche, *Grüezi* en Suisse ; le petit pain est *das Brötchen* en Allemagne, *die Semmel* en Autriche, *das Brötli* en Suisse (ou : la tomate, *der Paradeiser* en Autriche).\nParler un dialecte n’est donc pas mal parler : c’est une **identité régionale**, dont beaucoup sont fiers. En Suisse, tout le monde parle *Schwiizerdütsch* au quotidien et écrit en *Hochdeutsch*.\n\n**Partie B (exemple).**\n*Hallo! Ich heiße Hugo und ich wohne in Lyon. Meine Muttersprache ist Französisch. Deutsch ist meine Fremdsprache: Ich spreche ein bisschen Deutsch. Ich verstehe schon viele Wörter, aber mein Wortschatz ist noch klein. Mein Freund Paul ist zweisprachig: Er spricht Französisch und Deutsch. Im Unterricht frage ich oft: „Wie sagt man das auf Deutsch?“ oder „Kannst du das bitte wiederholen?“*\n\nOn valorise : les noms avec majuscule, le verbe conjugué en 2e position, l’emploi juste des mots imposés et d’une expression du cours."}$exo$::jsonb),
  ('0f6859ec-d31c-51bc-98f7-3666e6a6c7c6'::uuid, 1, 'traduction', $exo${"titre":"Les notes et les mots de l’école","consigne":"Réponds en français, avec des phrases courtes.","enonce":"**1.** Traduis en français :\na) *das Fach* b) *der Stundenplan* c) *die Pause* d) *die Hausaufgaben* e) *die Klassenarbeit* f) *das Zeugnis* g) *sitzen bleiben*\n\n**2.** Les notes allemandes.\na) Quelle est la meilleure note en Allemagne ? Et la plus mauvaise ?\nb) Que signifie *eine Vier* ?\nc) Tom annonce : *Ich habe eine Fünf in Mathe.* Est-il content ? Explique.\n\n**3.** Comment s’appelle le bac allemand ? Quel est son surnom familier ?","bareme":[{"critere":"Les sept mots de l’école traduits justement","points":8},{"critere":"Échelle des notes comprise : 1 meilleure, 6 plus mauvaise, 4 passable, 5 insuffisant","points":8},{"critere":"Abitur et son surnom das Abi","points":4}],"dureeMin":6,"corrige":"**1.** a) la **matière** b) l’**emploi du temps** c) la **récréation** d) les **devoirs** e) le **contrôle** f) le **bulletin** g) **redoubler**\n\n**2.** a) La meilleure note est **1** (*sehr gut*, très bien) ; la plus mauvaise est **6** (*ungenügend*, très insuffisant).\nb) *Eine Vier* = un 4, *ausreichend* : **passable**.\nc) **Non** : un 5 (*mangelhaft*) signifie **insuffisant**. En Allemagne, plus la note est haute, moins elle est bonne ; ce n’est pas une note sur 20.\n\n**3.** Le bac allemand s’appelle l’**Abitur**, familièrement **das Abi**."}$exo$::jsonb),
  ('0f6859ec-d31c-51bc-98f7-3666e6a6c7c6'::uuid, 2, 'traduction', $exo${"titre":"Une journée de Jonas à Munich","consigne":"Lis le texte de Jonas, puis réponds en français aux questions.","enonce":"> *Hallo, ich bin Jonas, ich bin 15 und ich gehe aufs Gymnasium in München. Die Schule beginnt um 7.45 Uhr und endet um 13 Uhr. Heute haben wir sechs Stunden: zwei Stunden Mathe, eine Doppelstunde Deutsch, Englisch und Sport. Mein Lieblingsfach ist Mathe. In Deutsch habe ich eine Eins, aber in Physik habe ich eine Vier. Am Nachmittag spiele ich Fußball in meinem Verein. Am Abend mache ich meine Hausaufgaben.*\n\n*beginnt* = commence · *endet* = finit · *am Nachmittag* = l’après-midi\n\n1. Quel âge a Jonas, dans quelle ville vit-il, dans quel type d’école va-t-il ? À quel examen cette école mène-t-elle ?\n2. À quelle heure commencent et finissent ses cours ? Qu’est-ce qui est différent d’une journée de collège en France ?\n3. Combien a-t-il d’heures de cours aujourd’hui ? Qu’est-ce qu’une *Doppelstunde*, et combien de minutes dure-t-elle ?\n4. Que valent ses notes en allemand et en physique ? Dans quelle matière réussit-il le mieux ?\n5. Qu’est-ce qu’un *Verein* ? Que fait Jonas l’après-midi ?","bareme":[{"critere":"Identité de Jonas, Gymnasium et Abitur","points":4},{"critere":"Horaires relevés et comparaison avec la France (journée courte, fin en début d’après-midi)","points":5},{"critere":"Six heures de cours, Doppelstunde de 2 × 45 = 90 minutes","points":5},{"critere":"Notes interprétées (Eins = très bien, Vier = passable) et Verein expliqué","points":6}],"dureeMin":10,"corrige":"1. Jonas a **15 ans**, il vit à **Munich** (*München*) et va au **Gymnasium**, l’établissement qui regroupe collège et lycée général et mène à l’**Abitur** (le bac allemand).\n\n2. Ses cours commencent à **7 h 45** et finissent à **13 h**. En France, la journée de collège finit souvent vers 16 h ou 17 h ; en Allemagne, traditionnellement, les cours commencent tôt et s’arrêtent en **début d’après-midi** (sauf dans les *Ganztagsschulen*, écoles à la journée, réponse acceptée en complément).\n\n3. Il a **six heures** de cours (*sechs Stunden*) : 2 h de maths, 2 h d’allemand, 1 h d’anglais, 1 h de sport. Une *Doppelstunde* est une **double heure** : deux heures de 45 minutes groupées, soit **90 minutes**.\n\n4. En allemand, il a un **1** (*eine Eins*) : **très bien**, la meilleure note. En physique, il a un **4** (*eine Vier*) : **passable**. Il réussit donc le mieux en **allemand** (même si sa matière préférée est les maths).\n\n5. Un *Verein* est un **club**, une **association**. L’après-midi, Jonas joue au **football dans son club** ; le soir, il fait ses devoirs."}$exo$::jsonb),
  ('0f6859ec-d31c-51bc-98f7-3666e6a6c7c6'::uuid, 3, 'traduction', $exo${"titre":"L’école allemande : un autre rythme","consigne":"Partie A en français (10 lignes environ), partie B en allemand (4 phrases au moins).","enonce":"**Situation.** Tu prépares un exposé pour ta classe : « L’école en Allemagne, un autre rythme ».\n\n**Partie A (français).** Explique **trois différences** entre l’école allemande et l’école française. Pour chacune, donne un fait précis tiré du cours et un mot allemand. Tu dois traiter :\n- le rythme de la journée ;\n- le parcours scolaire (âge de l’orientation, qui organise l’école) ;\n- les notes, le bac ou l’apprentissage.\n\n**Partie B (allemand).** Présente ta propre journée à un correspondant en **quatre phrases au moins** : le nombre d’heures de cours, ta matière préférée, une note obtenue (dans le système allemand) et tes devoirs.","bareme":[{"critere":"Rythme de la journée : début tôt, fin en début d’après-midi, Ganztagsschule, heures de 45 min","points":4},{"critere":"Parcours : Grundschule, orientation vers 10 ans, école organisée par les 16 Länder","points":4},{"critere":"Notes de 1 à 6, Abitur ou système dual expliqués","points":4},{"critere":"Partie B : quatre phrases qui traitent les quatre éléments demandés","points":5},{"critere":"Correction de l’allemand (verbe en 2e position, noms avec majuscule)","points":3}],"dureeMin":15,"corrige":"**Partie A (exemple).** Première différence, le **rythme** : en Allemagne, les cours commencent tôt, vers 7 h 45 ou 8 h, et finissent traditionnellement en début d’après-midi. Les heures durent 45 minutes, souvent groupées par deux (*Doppelstunde*). Mais de plus en plus d’écoles deviennent des *Ganztagsschulen*, avec cantine et activités l’après-midi.\nDeuxième différence, le **parcours** : après quatre ans de *Grundschule* (6-10 ans), les élèves sont orientés très tôt, **vers 10 ans**, vers le *Gymnasium* ou d’autres filières (*Realschule*, *Gesamtschule*). L’éducation relève des **Länder**, les 16 États fédérés : chaque Land a son système et ses vacances.\nTroisième différence, les **notes** : elles vont de **1** (*sehr gut*) à **6** (*ungenügend*), le 1 étant la meilleure. Le bac s’appelle l’**Abitur** (*das Abi*), et l’**apprentissage** (*die Ausbildung*), qui alterne entreprise et école professionnelle, est très respecté : c’est le **système dual**.\n\n**Partie B (exemple).**\n*Heute haben wir sieben Stunden. Mein Lieblingsfach ist Deutsch. Ich habe eine Eins in Deutsch! Am Abend mache ich meine Hausaufgaben.*\n\nOn accepte toute journée cohérente ; on vérifie *Wir haben heute … Stunden*, *Mein Lieblingsfach ist …*, *Ich habe eine … in …* avec une note de 1 à 6, *die Hausaufgaben*."}$exo$::jsonb),
  ('bb861351-4ac3-5866-8486-4bc55bf77cfa'::uuid, 1, 'traduction', $exo${"titre":"Voyager et migrer : les mots","consigne":"Réponds à chaque question.","enonce":"**1.** Traduis en français :\na) *reisen* b) *die Reise* c) *auswandern* d) *einwandern* e) *der Flüchtling* f) *die Heimat* g) *der Koffer* h) *das Heimweh*\n\n**2.** Complète avec *nach* ou *in die* :\na) Ich fahre … Hamburg.\nb) Wir fahren … Schweiz.\nc) Lena fährt … Österreich.\nd) Fahrt ihr … Wien?\n\n**3.** Qui étaient les *Gastarbeiter* ? Que signifie ce mot, et qu’est-ce qu’il montre ?","bareme":[{"critere":"Les huit mots traduits justement","points":8},{"critere":"Les quatre prépositions justes : nach, in die, nach, nach","points":6},{"critere":"Gastarbeiter : travailleurs recrutés dans les années 1950-1970, sens « travailleur invité », idée qu’ils devaient repartir","points":6}],"dureeMin":7,"corrige":"**1.** a) **voyager** b) le **voyage** c) **émigrer** d) **immigrer** e) le **réfugié** f) le **pays natal**, le « chez-soi » g) la **valise** h) le **mal du pays**\n\n**2.** a) Ich fahre **nach** Hamburg. (ville)\nb) Wir fahren **in die** Schweiz. (pays avec article : *in* + accusatif)\nc) Lena fährt **nach** Österreich. (pays sans article)\nd) Fahrt ihr **nach** Wien? (ville)\n\n**3.** Les *Gastarbeiter* sont les **travailleurs étrangers** (Italie, Turquie, Grèce…) recrutés par l’Allemagne dans les **années 1950-1970** comme main-d’œuvre pour le « miracle économique ». Le mot signifie « **travailleur invité** » : il montre qu’on pensait qu’ils **repartiraient**. Beaucoup sont restés, et leurs enfants et petits-enfants sont Allemands."}$exo$::jsonb),
  ('bb861351-4ac3-5866-8486-4bc55bf77cfa'::uuid, 2, 'traduction', $exo${"titre":"La Klassenfahrt de la 9b","consigne":"Lis la lettre de Frau Schmidt. Réponds aux questions 1 à 4 en français et à la question 5 en allemand.","enonce":"> *Liebe Klasse 9b,*\n> *im Mai machen wir eine Klassenfahrt! Wir fahren mit dem ICE nach Hamburg. Dort schlafen wir in einer Jugendherberge. Wir besuchen den Hafen und die Speicherstadt. Dann fahren wir nach Berlin: Dort sehen wir das Brandenburger Tor und die Reste der Mauer. Vergesst eure Koffer nicht!*\n> *Gute Reise!*\n> *Frau Schmidt*\n\n*dort* = là-bas · *der Hafen* = le port · *die Mauer* = le mur · *vergesst … nicht* = n’oubliez pas\n\n1. Qui écrit, à qui, et pour annoncer quoi ? Traduis le mot *Klassenfahrt*.\n2. Comment la classe voyage-t-elle ? Qu’est-ce que l’ICE ?\n3. Où les élèves dorment-ils ? Explique ce lieu et donne un fait du cours à son sujet.\n4. Quelles sont les deux villes visitées, et que verra-t-on dans chacune ?\n5. Écris en allemand : a) Je vais à Munich. b) Je vais en Suisse. c) Bon voyage !","bareme":[{"critere":"Expéditeur, destinataires et objet de la lettre, Klassenfahrt = voyage de classe","points":4},{"critere":"Train ICE de la Deutsche Bahn ; Jugendherberge = auberge de jeunesse, invention allemande de 1909","points":6},{"critere":"Hambourg (port, Speicherstadt) et Berlin (porte de Brandebourg, restes du Mur)","points":5},{"critere":"Trois phrases allemandes justes : nach München, in die Schweiz, Gute Reise","points":5}],"dureeMin":10,"corrige":"1. C’est **Frau Schmidt**, la professeure, qui écrit à sa **classe de 9b** pour annoncer un **voyage de classe** (*Klassenfahrt*) au mois de **mai**.\n\n2. La classe voyage **en train**, avec l’**ICE**, le train rapide de la **Deutsche Bahn**.\n\n3. Les élèves dorment dans une ***Jugendherberge*** : une **auberge de jeunesse**. C’est une **invention allemande de 1909**.\n\n4. À **Hambourg**, ils visitent le **port** et la **Speicherstadt** (le quartier des entrepôts). À **Berlin**, ils voient la **porte de Brandebourg** et les **restes du Mur**.\n\n5. a) *Ich fahre **nach** München.* (ville : *nach*)\nb) *Ich fahre **in die** Schweiz.* (pays avec article : *in* + accusatif)\nc) *Gute Reise!*"}$exo$::jsonb),
  ('bb861351-4ac3-5866-8486-4bc55bf77cfa'::uuid, 3, 'traduction', $exo${"titre":"D’un pays d’émigration à un pays d’immigration","consigne":"Traite les trois questions. La question 3 est un paragraphe rédigé en français (8 à 10 lignes).","enonce":"**Document 1 – Quatre arrivées en Allemagne (dans le désordre)**\n- A. Plus d’un million de réfugiés, surtout de Syrie\n- B. Des réfugiés d’Ukraine\n- C. Les *Gastarbeiter*, venus d’Italie, de Turquie, de Grèce\n- D. Des Allemands d’Europe de l’Est (*Spätaussiedler*)\n\nPériodes : **années 1950-1970 · après 1989 · 2015-2016 · depuis 2022**\n\n**Document 2 – Le témoignage d’Emre, 15 ans, à Cologne**\n> *Mein Großvater ist 1965 aus der Türkei nach Deutschland gekommen. Er war Gastarbeiter in einer Fabrik in Köln. Er wollte in die Türkei zurückfahren, aber er ist geblieben. Meine Mutter ist in Köln geboren. Heute ist Deutschland meine Heimat.*\n\n*der Großvater* = le grand-père · *die Fabrik* = l’usine · *Köln* = Cologne · *er wollte* = il voulait · *geboren* = né(e)\n\n1. Associe chaque arrivée (A à D) à sa période et donne sa cause.\n2. Traduis le témoignage d’Emre en français.\n3. Explique comment l’Allemagne, pays d’**émigration** au XIXe siècle, est devenue un pays d’**immigration**. Appuie-toi sur les deux documents et sur le cours.","bareme":[{"critere":"Les quatre arrivées associées à leur période et à leur cause","points":5},{"critere":"Traduction fidèle et correcte du témoignage (temps du passé, Heimat)","points":6},{"critere":"Émigration du XIXe siècle expliquée : vers les États-Unis, pour fuir la pauvreté","points":3},{"critere":"Immigration expliquée avec l’exemple d’Emre, le sens de Gastarbeiter et la part d’une personne sur quatre","points":4},{"critere":"Paragraphe organisé et rédigé","points":2}],"dureeMin":18,"corrige":"**1.**\n- C → **années 1950-1970** : main-d’œuvre pour le « miracle économique ».\n- D → **après 1989** : chute du rideau de fer.\n- A → **2015-2016** : la guerre ; c’est l’époque du « *Wir schaffen das* » d’Angela Merkel.\n- B → **depuis 2022** : la guerre en Ukraine.\n\n**2.** « Mon grand-père est venu de Turquie en Allemagne en 1965. Il était travailleur immigré (*Gastarbeiter*) dans une usine à Cologne. Il voulait retourner en Turquie, mais il est resté. Ma mère est née à Cologne. Aujourd’hui, l’Allemagne est mon pays (mon chez-moi). »\n\n**3. (exemple)** Au XIXe siècle, des millions d’Allemands ont **émigré** (*auswandern*), surtout vers les **États-Unis**, pour fuir la **pauvreté** ; le musée de l’émigration de Bremerhaven, port d’où partaient les bateaux, le rappelle. Après 1950, le mouvement s’inverse : l’Allemagne recrute des **Gastarbeiter** pour son miracle économique. Le mot, « travailleur invité », montre qu’on pensait qu’ils repartiraient ; mais beaucoup sont restés, comme le grand-père d’Emre, arrivé de Turquie en 1965. Ses enfants sont nés en Allemagne, et pour Emre, l’Allemagne est sa *Heimat*. D’autres arrivées ont suivi : les *Spätaussiedler* après 1989, les réfugiés de Syrie en 2015-2016, ceux d’Ukraine depuis 2022. Aujourd’hui, environ **une personne sur quatre** en Allemagne a une histoire migratoire (*Migrationshintergrund*) : l’Allemagne est devenue un pays d’immigration."}$exo$::jsonb),
  ('c2279946-a10a-5bb9-98f1-ff5026801e98'::uuid, 1, 'traduction', $exo${"titre":"Les dates de l’amitié franco-allemande","consigne":"Réponds à chaque question.","enonce":"**1.** Associe chaque date à son événement.\n\nDates : **1963 · 1984 · 1992 · 2003 · 2019**\n\n- a) Création d’Arte, chaîne franco-allemande\n- b) Traité d’Aix-la-Chapelle\n- c) Traité de l’Élysée, création de l’OFAJ\n- d) Le 22 janvier devient la Journée franco-allemande\n- e) Mitterrand et Kohl, main dans la main à Verdun\n\n**2.** Qui a signé le traité de l’Élysée ? Que signifie le sigle OFAJ, et à quoi sert cet office ?\n\n**3.** Traduis : a) *der Austausch* b) *die Gastfamilie* c) *die Brieffreundin* d) *die Freundschaft* e) *das Nachbarland* f) *die Städtepartnerschaft*","bareme":[{"critere":"Les cinq dates associées justement","points":7},{"critere":"De Gaulle et Adenauer ; OFAJ = Office franco-allemand pour la Jeunesse, rencontres de jeunes","points":6},{"critere":"Les six mots traduits justement","points":7}],"dureeMin":7,"corrige":"**1.** 1963 → c) ; 1984 → e) ; 1992 → a) ; 2003 → d) ; 2019 → b).\n\n**2.** Le traité de l’Élysée a été signé le **22 janvier 1963** par le général **de Gaulle** et le chancelier **Konrad Adenauer**. L’OFAJ est l’**Office franco-allemand pour la Jeunesse** (en allemand *DFJW*) : il organise et finance des **rencontres et des séjours de jeunes** ; il a permis à près de dix millions de jeunes de se rencontrer.\n\n**3.** a) l’**échange** b) la **famille d’accueil** c) la **correspondante** d) l’**amitié** e) le **pays voisin** f) le **jumelage**"}$exo$::jsonb),
  ('c2279946-a10a-5bb9-98f1-ff5026801e98'::uuid, 2, 'traduction', $exo${"titre":"Le message de Mia","consigne":"Lis le message que Léa reçoit avant son échange, puis réponds en français aux questions 1 à 3 et en allemand à la question 4.","enonce":"> *Liebe Léa,*\n> *ich freue mich auf deinen Besuch! Du wohnst bei meiner Familie in Freiburg. Bei uns isst man früh, um 18 Uhr, und oft kalt: das ist das Abendbrot. Wir machen keine Bise, wir geben uns die Hand. Mein Vater findet Pünktlichkeit sehr wichtig! Und wir bringen die Flaschen in den Supermarkt zurück: das ist das Pfand.*\n> *Bis bald!*\n> *Mia*\n\n*früh* = tôt · *die Hand geben* = serrer la main · *die Pünktlichkeit* = la ponctualité · *die Flasche* = la bouteille\n\n1. Qui est Mia pour Léa ? Où Léa va-t-elle loger ? Donne le mot allemand qui désigne ce lieu d’accueil.\n2. Relève **quatre habitudes** allemandes décrites par Mia et compare chacune à l’habitude française.\n3. Donne deux conseils à Léa pour que son séjour se passe bien.\n4. Traduis en allemand : a) C’est différent de chez nous. b) Chez nous, en France, on mange plus tard.","bareme":[{"critere":"Mia = correspondante ; Léa loge dans sa famille, die Gastfamilie","points":4},{"critere":"Quatre habitudes relevées et comparées à la France","points":8},{"critere":"Deux conseils cohérents avec le message","points":4},{"critere":"Les deux phrases allemandes justes","points":4}],"dureeMin":11,"corrige":"1. Mia est la **correspondante** de Léa (*die Brieffreundin*). Léa va loger **chez Mia**, dans sa famille à Fribourg-en-Brisgau (*Freiburg*) : c’est sa **famille d’accueil**, *die Gastfamilie*.\n\n2.\n- **Le dîner** : en Allemagne, on dîne **tôt** (18 h), souvent un **repas froid**, l’*Abendbrot* ; en France, on dîne plus tard et chaud.\n- **Se saluer** : en Allemagne, on **se serre la main**, sans bise ; en France, on fait la bise.\n- **La ponctualité** est très importante ; en France, un petit retard est souvent toléré.\n- **Le tri** : on **rapporte les bouteilles** au supermarché (la consigne, *Pfand*) ; en France, le tri progresse.\n\n3. Exemples : être **à l’heure** aux repas et aux rendez-vous ; **serrer la main** au lieu de faire la bise ; ne pas jeter les bouteilles mais les rapporter ; ne pas juger ces habitudes mais chercher à les comprendre.\n\n4. a) *Das ist anders als bei uns.*\nb) *Bei uns in Frankreich isst man später.*"}$exo$::jsonb),
  ('c2279946-a10a-5bb9-98f1-ff5026801e98'::uuid, 3, 'traduction', $exo${"titre":"D’ennemis héréditaires à partenaires","consigne":"Questions 1 et 2 en français (paragraphes rédigés), question 3 en allemand (4 phrases au moins).","enonce":"**Document 1 – Quelques dates**\n\n| Date | Événement |\n| 1963 | Traité de l’Élysée, création de l’OFAJ |\n| 1984 | Mitterrand et Kohl, main dans la main à Verdun |\n| 1992 | Création d’Arte |\n| 2019 | Traité d’Aix-la-Chapelle |\n\n**Document 2**\n> « Rencontrer une autre culture, ce n’est pas juger ses habitudes, c’est les comprendre — et regarder les siennes autrement. »\n\nDevise de l’Union européenne : *In Vielfalt geeint* (« Unie dans la diversité »).\n\n1. Montre comment la France et l’Allemagne, qui se sont fait la guerre, sont devenues des partenaires. Utilise **au moins trois dates** et **deux moyens de rencontre** d’aujourd’hui.\n2. Explique la phrase du document 2 à l’aide d’un exemple d’habitude différente entre les deux pays.\n3. De retour chez toi après un échange, tu écris à ta correspondante Mia. En **quatre phrases au moins**, en allemand, compare une habitude allemande et une habitude française et dis ce que tu penses de l’échange. Utilise au moins **deux** de ces expressions : *bei meiner Gastfamilie, Bei uns in Frankreich …, Das ist anders als bei uns, der Austausch, die Freundschaft*.","bareme":[{"critere":"Rapprochement expliqué avec trois dates justes (traité de l’Élysée, Verdun, Arte ou Aix-la-Chapelle)","points":5},{"critere":"Deux moyens de rencontre cités : OFAJ, échanges scolaires, jumelages, lycées franco-allemands","points":3},{"critere":"Document 2 expliqué avec un exemple d’habitude comparée","points":4},{"critere":"Question 3 : quatre phrases, comparaison et avis, deux expressions imposées","points":5},{"critere":"Correction de l’allemand (ordre des mots, majuscules, appel du message)","points":3}],"dureeMin":18,"corrige":"**1. (exemple)** La France et l’Allemagne se sont fait la guerre à plusieurs reprises. Pourtant, le **22 janvier 1963**, de Gaulle et Adenauer signent le **traité de l’Élysée** : les deux pays promettent de se consulter et de rapprocher leurs jeunesses, et l’**OFAJ** est créé la même année ; près de dix millions de jeunes se sont rencontrés grâce à lui. En **1984**, Mitterrand et Kohl se tiennent la main à **Verdun** : c’est un symbole de la réconciliation. En **1992** naît **Arte**, une chaîne franco-allemande, et en **2019** le **traité d’Aix-la-Chapelle** renouvelle celui de l’Élysée. Aujourd’hui, les **échanges scolaires**, les **jumelages** (plus de 2 000 villes), le programme Voltaire ou les lycées franco-allemands permettent de vivre chez l’autre.\n\n**2.** Rencontrer l’autre, ce n’est pas dire que ses habitudes sont bizarres, mais comprendre pourquoi elles existent, et découvrir que les nôtres ne sont pas les seules possibles. Exemple : en Allemagne, on dîne tôt, souvent un repas froid (*Abendbrot*), alors qu’en France on dîne plus tard et chaud ; aucun des deux n’a tort. C’est l’esprit de la devise européenne *In Vielfalt geeint* : unis dans la diversité.\n\n**3. (exemple)**\n*Liebe Mia,*\n*ich bin wieder in Lyon. Bei meiner Gastfamilie in Freiburg isst man um 18 Uhr. Bei uns in Frankreich isst man später, um 20 Uhr. Bei euch gibt man sich die Hand: Das ist anders als bei uns! Ich finde den Austausch toll. Die Freundschaft ist wichtig.*\n*Viele Grüße*\n*Chloé*"}$exo$::jsonb),
  ('71d80455-6e64-5fbc-b319-ebb0f0119420'::uuid, 1, 'traduction', $exo${"titre":"Compter et lire l’heure","consigne":"Écris les nombres en lettres allemandes et les heures en chiffres.","enonce":"**1.** Écris en toutes lettres, en allemand :\n16 · 17 · 30 · 47 · 58 · 76 · 99\n\n**2.** Écris en chiffres :\na) *dreiundsechzig* b) *einundachtzig* c) *zweiundzwanzig*\n\n**3.** Donne l’heure en chiffres (heure du matin) :\na) *halb neun* b) *Viertel nach sieben* c) *Viertel vor drei* d) *halb zwölf*\n\n**4.** Comment demande-t-on l’heure en allemand ?","bareme":[{"critere":"Les sept nombres écrits sans faute (sechzehn, siebzehn, dreißig, unités avant dizaines)","points":8},{"critere":"Les trois nombres écrits en chiffres","points":3},{"critere":"Les quatre heures justes, halb compris comme « la demie vers » l’heure suivante, et la question pour demander l’heure","points":9}],"dureeMin":7,"corrige":"**1.** 16 = *sechzehn* (pas *sechszehn*) · 17 = *siebzehn* · 30 = *dreißig* (avec ß) · 47 = *siebenundvierzig* · 58 = *achtundfünfzig* · 76 = *sechsundsiebzig* · 99 = *neunundneunzig*. Entre 21 et 99, on dit l’unité, puis *und*, puis la dizaine, en un seul mot.\n\n**2.** a) **63** b) **81** c) **22**\n\n**3.** a) *halb neun* = **8 h 30** (la demie vers neuf : il manque une demi-heure pour arriver à 9 h)\nb) *Viertel nach sieben* = **7 h 15**\nc) *Viertel vor drei* = **2 h 45**\nd) *halb zwölf* = **11 h 30**\n\n**4.** *Wie spät ist es?* ou *Wie viel Uhr ist es?*"}$exo$::jsonb),
  ('71d80455-6e64-5fbc-b319-ebb0f0119420'::uuid, 2, 'traduction', $exo${"titre":"Jonas arrive le 3 octobre","consigne":"Lis le message de Jonas, réponds en français aux questions 1 et 2, puis en allemand à la question 3.","enonce":"> *Hallo Léo! Ich komme am 3. Oktober nach Paris. Mein Zug fährt um halb sieben in Hamburg ab und kommt um Viertel vor sechs am Abend in Paris an. Die Reise dauert elf Stunden und fünfzehn Minuten. Am 14. Oktober habe ich Geburtstag: Ich werde sechzehn! Bis bald, Jonas*\n\n*ankommen* = arriver · *dauern* = durer · *am Abend* = le soir · *ich werde* = je vais avoir\n\n1. a) Écris en lettres la date d’arrivée telle qu’on la lit : *am … Oktober*.\nb) À quelle heure le train part-il de Hambourg ? À quelle heure arrive-t-il à Paris ? Donne les deux heures en chiffres.\nc) Vérifie par un calcul la durée annoncée par Jonas.\n2. Quand est l’anniversaire de Jonas et quel âge va-t-il avoir ?\n3. Écris en allemand, avec les nombres en lettres :\na) Mon anniversaire est le 21 mars.\nb) Aujourd’hui, c’est le 20 septembre.","bareme":[{"critere":"Date lue au datif : am dritten Oktober","points":3},{"critere":"Départ 6 h 30, arrivée 17 h 45, durée de 11 h 15 vérifiée","points":7},{"critere":"Anniversaire le 14 octobre, 16 ans","points":3},{"critere":"Deux phrases justes : am einundzwanzigsten März, der zwanzigste September","points":7}],"dureeMin":11,"corrige":"1. a) *am **dritten** Oktober* : après *am*, l’ordinal prend la terminaison *-en* ; *dritte* est irrégulier.\nb) Départ : *halb sieben* = **6 h 30** (la demie vers sept). Arrivée : *Viertel vor sechs am Abend* = **17 h 45**.\nc) De 6 h 30 à 17 h 30, il y a 11 h ; de 17 h 30 à 17 h 45, 15 min. Durée : **11 h 15 min**, soit *elf Stunden und fünfzehn Minuten* : Jonas a raison.\n\n2. L’anniversaire de Jonas est le **14 octobre** (*am vierzehnten Oktober*) ; il va avoir **16 ans** (*sechzehn*).\n\n3. a) *Ich habe am **einundzwanzigsten** März Geburtstag.* (21 = *einundzwanzig*, ordinal en *-ste* à partir de 20, *-en* après *am*)\nb) *Heute ist **der zwanzigste** September.* (nominatif : *der zwanzigste*)"}$exo$::jsonb),
  ('71d80455-6e64-5fbc-b319-ebb0f0119420'::uuid, 3, 'traduction', $exo${"titre":"Le programme de l’échange","consigne":"Traite les trois parties. Écris tous les nombres en lettres dans tes phrases allemandes.","enonce":"**Partie A – Traduis en allemand.**\na) Mon bus part le 2 avril à 8 h 30. (*abfahren*)\nb) Aujourd’hui, c’est le 3 octobre.\nc) Le film commence à 20 h 10. (*beginnen*) Donne l’heure officielle et l’heure familière.\nd) Écris en tête de lettre : Munich, le 7 mai 2026 (en chiffres, à l’allemande).\n\n**Partie B – Écris en lettres** : 365 et 2026.\n\n**Partie C – Un élève a écrit :**\n1. *Ich komme am halb acht.*\n2. *Ich bin sechszehn.*\n3. *Heute ist der dreite Juni.*\n4. *Ich habe am vierzehnte Mai Geburtstag.*\n\nCorrige chaque phrase et explique la faute. Puis explique en français les **deux pièges** des nombres et de l’heure allemands pour un francophone, avec un exemple chacun.","bareme":[{"critere":"Partie A : les quatre traductions justes (ordinal au datif, halb neun, heures officielle et familière, date de lettre)","points":8},{"critere":"Partie B : 365 et 2026 écrits en un seul mot, sans faute","points":3},{"critere":"Partie C : les quatre phrases corrigées et la faute expliquée","points":6},{"critere":"Les deux pièges expliqués avec un exemple (unités avant dizaines, halb)","points":3}],"dureeMin":16,"corrige":"**Partie A.**\na) *Mein Bus fährt am **zweiten** April um **halb neun** ab.* (date : *am* + ordinal + *-en* ; 8 h 30 = *halb neun* ; préverbe *ab* en fin de phrase)\nb) *Heute ist **der dritte** Oktober.*\nc) *Der Film beginnt um **zwanzig Uhr zehn*** (officielle) ou *um **zehn nach acht*** (familière).\nd) *München, den 7.05.2026* (ou *München, den 7. Mai 2026*).\n\n**Partie B.** 365 = *dreihundertfünfundsechzig* ; 2026 = *zweitausendsechsundzwanzig*.\n\n**Partie C.**\n1. *Ich komme **um** halb acht.* Pour dire « à » devant une heure, on emploie *um* (*am* sert pour les dates).\n2. *Ich bin **sechzehn**.* Le *s* de *sechs* tombe dans *sechzehn*.\n3. *Heute ist der **dritte** Juni.* L’ordinal de 3 est irrégulier : *der dritte*.\n4. *Ich habe am **vierzehnten** Mai Geburtstag.* Après *am* (datif), l’ordinal prend *-en*.\n\n**Les deux pièges.** 1) L’allemand dit l’**unité avant la dizaine**, en un seul mot : 47 = *siebenundvierzig* (« sept et quarante ») ; sous la dictée, on note l’unité à droite, puis la dizaine. 2) ***halb*** désigne la demie **vers** l’heure suivante : *halb acht* = **7 h 30**, pas 8 h 30."}$exo$::jsonb),
  ('95825f97-d947-59a3-9e53-393efcc3226d'::uuid, 1, 'traduction', $exo${"titre":"Découper un mot composé","consigne":"Réponds à chaque question en t’appuyant sur la règle du cours.","enonce":"**1.** Pour chacun de ces mots composés, donne le **découpage** (avec l’article de chaque nom), le **genre** du composé et son **sens** :\na) *Klassenzimmer* b) *Handschuh* c) *Haustür* d) *Schulhof* e) *Großstadt* f) *Schwimmbad*\n\n**2.** Quelle règle donne le genre d’un mot composé ? Explique pourquoi on dit *die Haustür* alors qu’on dit *das Haus*.\n\n**3.** Quelle est la différence entre *der Apfelbaum* et *der Baumapfel* ?","bareme":[{"critere":"Les six mots découpés, avec genre et sens justes","points":12},{"critere":"Règle : le dernier mot est le mot de base et donne le genre, appliquée à die Haustür","points":4},{"critere":"Lecture de droite à gauche : un arbre qui porte des pommes / une pomme d’arbre","points":4}],"dureeMin":8,"corrige":"**1.**\na) *die Klasse* + *das Zimmer* → **das** Klassenzimmer : la **salle de classe**.\nb) *die Hand* + *der Schuh* → **der** Handschuh : le **gant** (« chaussure de main »).\nc) *das Haus* + *die Tür* → **die** Haustür : la **porte d’entrée**.\nd) *die Schule* + *der Hof* → **der** Schulhof : la **cour de récréation**.\ne) *groß* (adjectif) + *die Stadt* → **die** Großstadt : la **grande ville**.\nf) *schwimmen* (radical du verbe) + *das Bad* → **das** Schwimmbad : la **piscine**.\n\n**2.** Dans un composé, **le dernier mot est le mot de base** : il donne le **sens principal** et le **genre**. Dans *Haustür*, le mot de base est *die Tür* (la porte) : le composé est donc féminin. *Haus* ne fait que préciser de quelle porte il s’agit.\n\n**3.** On lit un composé **de droite à gauche**. *Der Apfelbaum* est un **arbre** (*Baum*) qui porte des pommes : un pommier. *Der Baumapfel* serait une **pomme** (*Apfel*)… d’arbre."}$exo$::jsonb),
  ('95825f97-d947-59a3-9e53-393efcc3226d'::uuid, 2, 'traduction', $exo${"titre":"Bienvenue à l’auberge de jeunesse","consigne":"Lis l’affiche, puis réponds aux questions en t’aidant du lexique.","enonce":"> *Willkommen in der Jugendherberge Hamburg! Sie liegt direkt neben dem Bahnhof. In jedem Schlafzimmer gibt es einen Kühlschrank. Der Speisesaal ist von 7 bis 9 Uhr offen. Vor dem Haus fährt die Straßenbahn ins Stadtzentrum.*\n\n**Lexique** : *die Jugend* (la jeunesse) · *die Herberge* (l’auberge) · *die Bahn* (le train, la voie) · *der Hof* (la cour) · *schlafen* (dormir) · *das Zimmer* (la pièce, la chambre) · *kühl* (frais) · *der Schrank* (l’armoire) · *die Speise* (le plat) · *der Saal* (la salle) · *die Straße* (la rue) · *die Stadt* (la ville) · *das Zentrum* (le centre) · *neben* (à côté de) · *es gibt* (il y a)\n\n1. Relève les **sept mots composés** du texte et découpe-les.\n2. Pour chacun, indique ce qui est collé (nom + nom, adjectif + nom, verbe + nom) et donne son **genre** avec l’article.\n3. Lequel contient une **lettre de liaison** ? Laquelle ?\n4. Traduis en français les phrases 2 et 3 (*Sie liegt… / In jedem Schlafzimmer…*).","bareme":[{"critere":"Les sept composés relevés et découpés justement","points":7},{"critere":"Nature des éléments et genre juste de chaque composé, tiré du dernier mot","points":6},{"critere":"Straßenbahn identifié, lettre de liaison -n-","points":2},{"critere":"Traduction juste des deux phrases","points":5}],"dureeMin":12,"corrige":"**1 et 2.**\n- *Jugendherberge* = *die Jugend* + *die Herberge* : nom + nom → **die** Jugendherberge (l’auberge de jeunesse).\n- *Bahnhof* = *die Bahn* + *der Hof* : nom + nom → **der** Bahnhof (la gare).\n- *Schlafzimmer* = *schlafen* + *das Zimmer* : verbe (radical *schlaf-*) + nom → **das** Schlafzimmer (la chambre à coucher).\n- *Kühlschrank* = *kühl* + *der Schrank* : adjectif + nom → **der** Kühlschrank (le réfrigérateur).\n- *Speisesaal* = *die Speise* + *der Saal* : nom + nom → **der** Speisesaal (la salle à manger).\n- *Straßenbahn* = *die Straße* + *n* + *die Bahn* : nom + nom → **die** Straßenbahn (le tramway).\n- *Stadtzentrum* = *die Stadt* + *das Zentrum* : nom + nom → **das** Stadtzentrum (le centre-ville).\n\nDans chaque cas, le genre est celui du **dernier mot**, le mot de base.\n\n**3.** *Straßenbahn* : *die Straße* + **-n-** + *die Bahn*.\n\n**4.** « Elle est située juste à côté de la gare. Dans chaque chambre, il y a un réfrigérateur. »"}$exo$::jsonb),
  ('95825f97-d947-59a3-9e53-393efcc3226d'::uuid, 3, 'traduction', $exo${"titre":"Des mots en trois morceaux","consigne":"Réponds à chaque question en justifiant par la règle du mot de base.","enonce":"**Lexique** : *die Klasse, das Zimmer, die Tür, das Haus, der Schlüssel* (la clé), *die Tasche* (le sac), *die Hand, das Buch, der Laden* (le magasin), *der Fußball, das Spiel* (le match), *der Garten* (le jardin)\n\n**1.** Analyse *die Klassenzimmertür* et *der Haustürschlüssel* : découpe chaque mot, repère le mot de base et la lettre de liaison éventuelle, explique le genre et donne le sens.\n\n**2.** Forme le composé allemand, avec son article :\na) le cartable (un sac pour l’école ; *die Schule* devient *Schul-*)\nb) le sac à main\nc) la librairie (un magasin de livres)\nd) le match de football\n\n**3.** *Das Gartenhaus* et *der Hausgarten* sont deux vrais mots. Explique la différence de sens et de genre entre eux.","bareme":[{"critere":"Les deux mots en trois morceaux découpés, mot de base, liaison -n- et genre justifiés","points":7},{"critere":"Sens juste des deux mots, construit de droite à gauche","points":3},{"critere":"Les quatre composés formés avec le bon article","points":6},{"critere":"Gartenhaus / Hausgarten : sens et genre expliqués par le mot de base","points":4}],"dureeMin":15,"corrige":"**1.**\n- *die Klassenzimmertür* = *die Klasse* + **-n-** + *das Zimmer* + *die Tür*. Mot de base : ***die Tür*** → le composé est **féminin**. On lit de droite à gauche : une porte → de la salle → de classe : **la porte de la salle de classe**.\n- *der Haustürschlüssel* = *das Haus* + *die Tür* + *der Schlüssel*. Mot de base : ***der Schlüssel*** → **masculin**. Une clé → de la porte → de la maison : **la clé de la porte d’entrée**. Pas de lettre de liaison.\n\n**2.**\na) **die Schultasche** (mot de base *die Tasche*)\nb) **die Handtasche**\nc) **der Buchladen** (mot de base *der Laden*)\nd) **das Fußballspiel** (mot de base *das Spiel*)\n\n**3.** *Das Gartenhaus* a pour mot de base *das Haus* : c’est une **maison** (une cabane) **de jardin** ; il est **neutre**. *Der Hausgarten* a pour mot de base *der Garten* : c’est un **jardin** de maison ; il est **masculin**. Les mêmes éléments, dans un ordre différent, désignent deux choses différentes : c’est toujours le dernier mot qui dit ce qu’est l’objet, les mots placés devant le précisent."}$exo$::jsonb),
  ('f73a4020-1993-5caf-8d34-8b00d2acd947'::uuid, 1, 'traduction', $exo${"titre":"Connecteur en tête, verbe en deuxième","consigne":"Réponds à chaque question.","enonce":"**1.** Traduis : *zuerst · dann · danach · später · plötzlich · schließlich · am Anfang · am Ende*\n\n**2.** Réécris chaque phrase en plaçant le connecteur entre parenthèses **en tête** :\na) *Ich frühstücke.* (zuerst)\nb) *Wir fahren in die Stadt.* (dann)\nc) *Es regnet.* (plötzlich)\nd) *Wir gehen nach Hause.* (schließlich)\ne) *Ich spiele Fußball.* (danach)\n\n**3.** Pourquoi *und* ne change-t-il pas l’ordre des mots, alors que *dann* le change ?","bareme":[{"critere":"Les huit connecteurs traduits","points":6},{"critere":"Les cinq phrases réécrites avec l’inversion verbe-sujet","points":10},{"critere":"Und, conjonction en position zéro ; dann, adverbe en première position","points":4}],"dureeMin":7,"corrige":"**1.** *zuerst* = d’abord · *dann* = ensuite, puis · *danach* = après ça · *später* = plus tard · *plötzlich* = soudain · *schließlich* = finalement · *am Anfang* = au début · *am Ende* = à la fin\n\n**2.** Le connecteur occupe la 1re position, le verbe conjugué reste en 2e position, le sujet passe derrière :\na) *Zuerst **frühstücke ich**.*\nb) *Dann **fahren wir** in die Stadt.*\nc) *Plötzlich **regnet es**.*\nd) *Schließlich **gehen wir** nach Hause.*\ne) *Danach **spiele ich** Fußball.*\n\n**3.** *Und* est une **conjonction de coordination** : il se place en **position zéro** et ne compte pas. *Dann* est un **adverbe** : placé en tête, il occupe la **première position**, donc le verbe vient juste après et le sujet passe derrière. Exemple : *Ich esse und dann gehe ich* : c’est *dann* qui provoque l’inversion."}$exo$::jsonb),
  ('f73a4020-1993-5caf-8d34-8b00d2acd947'::uuid, 2, 'traduction', $exo${"titre":"Le samedi de Paul, à corriger","consigne":"Lis le récit de Paul, puis réponds aux questions.","enonce":"> *(1) Am Samstag bin ich früh aufgestanden. (2) Zuerst ich habe gefrühstückt. (3) Dann bin ich mit meiner Schwester in die Stadt gegangen. (4) Danach wir haben ein Eis gegessen. (5) Plötzlich hat es geregnet! (6) Später wir sind ins Kino gegangen. (7) Schließlich ich bin mit dem Bus nach Hause gefahren.*\n\n*das Eis* = la glace · *das Kino* = le cinéma\n\n1. **Quatre phrases** contiennent la même faute. Repère-les et récris-les correctement.\n2. Explique la règle qui a été oubliée.\n3. Traduis le récit corrigé en français.\n4. À quel temps Paul raconte-t-il ? Explique comment ce temps se construit dans la phrase.","bareme":[{"critere":"Les phrases 2, 4, 6 et 7 repérées et corrigées","points":8},{"critere":"Règle : connecteur en 1re position, verbe conjugué en 2e, sujet derrière","points":4},{"critere":"Traduction juste du récit","points":5},{"critere":"Parfait identifié : auxiliaire en 2e position, participe passé à la fin","points":3}],"dureeMin":11,"corrige":"1. Phrases fautives et corrections :\n- (2) *Zuerst **habe ich** gefrühstückt.*\n- (4) *Danach **haben wir** ein Eis gegessen.*\n- (6) *Später **sind wir** ins Kino gegangen.*\n- (7) *Schließlich **bin ich** mit dem Bus nach Hause gefahren.*\nLes phrases 1, 3 et 5 sont justes.\n\n2. Les connecteurs *zuerst, danach, später, schließlich* sont des adverbes : en tête de phrase, ils occupent la **première position**. Le **verbe conjugué** (ici l’auxiliaire) reste en **deuxième position** et le **sujet passe derrière**. *Zuerst ich habe* est la faute typique du francophone.\n\n3. « Samedi, je me suis levé tôt. D’abord, j’ai pris mon petit-déjeuner. Ensuite, je suis allé en ville avec ma sœur. Après ça, nous avons mangé une glace. Soudain, il a plu ! Plus tard, nous sommes allés au cinéma. Finalement, je suis rentré à la maison en bus. »\n\n4. Paul raconte au **parfait**, le temps du récit à l’oral et dans un message : l’**auxiliaire** (*haben* ou *sein*) est conjugué en 2e position, et le **participe passé** ferme la phrase (*gefrühstückt, gegangen, gegessen…*)."}$exo$::jsonb),
  ('f73a4020-1993-5caf-8d34-8b00d2acd947'::uuid, 3, 'traduction', $exo${"titre":"Raconte ton dimanche","consigne":"Rédige le récit en allemand, puis réponds à la question 2 en français.","enonce":"**Tes notes (dimanche dernier)** : se lever tard → prendre le petit-déjeuner → aller au stade avec Tom → jouer au foot → soudain, la pluie → manger une pizza chez Tom → finalement, rentrer à la maison en bus.\n\n**Lexique** : *aufstehen* → *ich bin aufgestanden* · *frühstücken* → *ich habe gefrühstückt* · *gehen* → *ich bin gegangen* · *spielen* → *wir haben gespielt* · *regnen* → *es hat geregnet* · *essen* → *wir haben gegessen* · *fahren* → *ich bin gefahren* · *spät* (tard) · *ins Stadion* (au stade) · *bei Tom* (chez Tom) · *am Sonntag* (dimanche)\n\n1. Raconte ce dimanche en **sept phrases au parfait**, dans l’ordre des notes. Utilise au moins **cinq connecteurs différents** du cours.\n2. Un camarade demande : « Pourquoi dit-on *Danach haben wir gegessen* mais *Nachdem ich gegessen hatte, …* ? Et pourquoi *und* ne change-t-il rien ? » Réponds-lui.","bareme":[{"critere":"Les sept étapes racontées dans l’ordre avec au moins cinq connecteurs différents","points":5},{"critere":"Inversion juste après chaque connecteur (auxiliaire puis sujet)","points":6},{"critere":"Parfait juste : bon auxiliaire, participe passé en fin de phrase","points":5},{"critere":"Explication : danach adverbe, nachdem subordonnant (verbe à la fin), und en position zéro","points":4}],"dureeMin":16,"corrige":"**1. (exemple)**\n*Am Sonntag bin ich spät aufgestanden. Zuerst habe ich gefrühstückt. Dann bin ich mit Tom ins Stadion gegangen. Danach haben wir Fußball gespielt. Plötzlich hat es geregnet! Später haben wir bei Tom eine Pizza gegessen. Schließlich bin ich mit dem Bus nach Hause gefahren.*\n\nPoints vérifiés : chaque phrase commence par un repère (*Am Sonntag*, puis un connecteur : *zuerst, dann, danach, plötzlich, später, schließlich*) ; derrière, l’**auxiliaire** puis le **sujet** (*habe ich, bin ich, haben wir, hat es*) ; le **participe passé** ferme la phrase. Auxiliaire *sein* pour *aufstehen, gehen, fahren* ; *haben* pour les autres. On accepte *zum Schluss* ou *am Ende* à la place de *schließlich*.\n\n**2.** *Danach* est un **adverbe** : en tête, il occupe la première position, le verbe conjugué reste en deuxième et le sujet passe derrière (*Danach haben wir…*). *Nachdem* est un **subordonnant** : il ouvre une subordonnée et envoie le **verbe conjugué à la fin** (*Nachdem ich gegessen hatte*). *Und* est une **conjonction de coordination** : il se place en **position zéro** et ne change pas l’ordre des mots (*und dann gehe ich* : c’est *dann* qui provoque l’inversion)."}$exo$::jsonb),
  ('c058efac-b2a6-52b4-be8c-bf97f1224882'::uuid, 1, 'traduction', $exo${"titre":"Les codes d’un message allemand","consigne":"Réponds à chaque question.","enonce":"**1.** Range dans l’ordre les cinq parties d’une lettre : la formule finale · le lieu et la date · la signature · l’appel · le corps du message.\n\n**2.** Complète l’appel :\na) … Anna, (une amie)\nb) … Paul, (un ami)\nc) … Frau Weber, (une adulte inconnue)\nd) … Herr Klein, (un adulte inconnu)\n\n**3.** Quelle formule finale écris-tu à un ami ? À un adulte que tu ne connais pas ?\n\n**4.** Traduis en allemand :\na) Merci beaucoup pour ton message !\nb) Je vais bien.\nc) Écris-moi vite !","bareme":[{"critere":"Ordre des cinq parties juste","points":4},{"critere":"Les quatre appels accordés : Liebe, Lieber, Sehr geehrte, Sehr geehrter","points":6},{"critere":"Formules finales : Viele Grüße (ou Liebe Grüße) / Mit freundlichen Grüßen","points":4},{"critere":"Les trois phrases traduites justement","points":6}],"dureeMin":7,"corrige":"**1.** 1) le **lieu et la date** (*Paris, den 5. März 2026*) ; 2) l’**appel**, suivi d’une virgule ; 3) le **corps** du message, qui commence par une minuscule ; 4) la **formule finale**, sur sa ligne, sans virgule ; 5) la **signature**.\n\n**2.** a) ***Liebe*** Anna, b) ***Lieber*** Paul, c) ***Sehr geehrte*** Frau Weber, d) ***Sehr geehrter*** Herr Klein, — l’adjectif s’accorde : *Liebe* / *Sehr geehrte* pour une femme, *Lieber* / *Sehr geehrter* pour un homme.\n\n**3.** À un ami : *Viele Grüße*, *Liebe Grüße* ou *Bis bald!* À un adulte inconnu : *Mit freundlichen Grüßen*.\n\n**4.** a) *Vielen Dank für deine Nachricht!* b) *Mir geht es gut.* c) *Schreib mir bald!*"}$exo$::jsonb),
  ('c058efac-b2a6-52b4-be8c-bf97f1224882'::uuid, 2, 'traduction', $exo${"titre":"Réponds à Tom","consigne":"Écris ta réponse en allemand (6 à 8 lignes), en respectant la présentation d’un message.","enonce":"**Situation.** Ton correspondant Tom, qui habite à Hambourg, t’a écrit :\n\n> *Hallo! Wie geht es dir? Im Sommer komme ich nach Paris, am 12. Juli! Hast du Zeit? Viele Grüße, Tom*\n\nRéponds-lui. Ton message doit contenir :\n- un **appel** correct et la **présentation** d’un message (minuscule au début du corps, formule finale, signature) ;\n- un **remerciement** pour son message ;\n- des **nouvelles** : comment tu vas ;\n- ta **joie** de le recevoir ;\n- une **question** pour appeler une réponse ;\n- une phrase pour qu’il t’écrive vite.","bareme":[{"critere":"Présentation : Lieber Tom suivi d’une virgule, minuscule au début du corps, formule finale sans virgule, signature","points":6},{"critere":"Les contenus demandés présents : remerciement, nouvelles, joie, question, appel à répondre","points":8},{"critere":"Correction de la langue : formules du cours justes, verbe bien placé, tutoiement cohérent (du, dir, dein)","points":6}],"dureeMin":11,"corrige":"**Exemple de réponse :**\n\n*Lieber Tom,*\n*vielen Dank für deine Nachricht! Mir geht es gut. Ich freue mich auf deinen Besuch! Am 12. Juli habe ich Zeit. Wie geht es dir? Magst du Paris?*\n*Schreib mir bald!*\n*Viele Grüße*\n*Inès*\n\nCe que le correcteur vérifie :\n- ***Lieber*** (Tom est un garçon), suivi d’une **virgule** ;\n- ***vielen*** avec une **minuscule** : le corps commence par une minuscule, sauf nom ou *Sie* ;\n- les formules du cours : *Vielen Dank für deine Nachricht!*, *Mir geht es gut.*, *Ich freue mich auf deinen Besuch!*, *Schreib mir bald!* ;\n- une **question** (*Wie geht es dir?*, *Hast du …?*) ;\n- la formule finale ***Viele Grüße*** (ou *Liebe Grüße*, *Bis bald!*) sur sa ligne, sans virgule, puis la **signature** ;\n- le tutoiement cohérent : *du, dir, dein* ; pas de *Mit freundlichen Grüßen* pour un ami."}$exo$::jsonb),
  ('c058efac-b2a6-52b4-be8c-bf97f1224882'::uuid, 3, 'traduction', $exo${"titre":"Deux messages, deux registres","consigne":"Écris les deux messages en allemand, puis réponds à la question 3 en français.","enonce":"**Situation.** Tu pars en échange à Cologne. Ta future famille d’accueil, **Mme Weber**, que tu ne connais pas encore, t’a écrit pour te recevoir **du 3 au 10 août**. Mais tu ne peux arriver que **le 4 août**.\n\n1. **Message à Mme Weber** (6 lignes environ) : présente-toi, remercie-la, explique que tu ne peux malheureusement pas venir le 3 août mais que tu arrives le 4, et pose-lui une question.\n2. **Message à Max**, son fils de ton âge (3 ou 4 lignes) : annonce-lui ta date d’arrivée et dis-lui que tu te réjouis.\n3. Cite **quatre différences** de forme entre les deux messages.\n\n**Aide** : *Ich möchte mich vorstellen* (je voudrais me présenter) · *Leider kann ich nicht … kommen* · *Haben Sie …?* · *nach Köln* (à Cologne)","bareme":[{"critere":"Message formel : Sehr geehrte Frau Weber, vouvoiement avec Sie / Ihnen / Ihre en majuscule, Mit freundlichen Grüßen","points":6},{"critere":"Message formel : présentation, remerciement, leider avec les deux dates, question","points":5},{"critere":"Message à Max : appel, tutoiement, date d’arrivée, joie, formule amicale","points":5},{"critere":"Quatre différences de forme justes entre les deux registres","points":4}],"dureeMin":18,"corrige":"**1. (exemple)**\n*Sehr geehrte Frau Weber,*\n*vielen Dank für Ihre Nachricht! Ich möchte mich vorstellen: Ich heiße Camille, ich bin 15 und ich wohne in Nantes. Leider kann ich nicht am 3. August kommen. Ich komme am 4. August nach Köln. Haben Sie am 4. August Zeit?*\n*Mit freundlichen Grüßen*\n*Camille Martin*\n\n**2. (exemple)**\n*Lieber Max,*\n*ich komme am 4. August nach Köln. Ich freue mich schon sehr! Schreib mir bald!*\n*Viele Grüße*\n*Camille*\n\n**3.** Différences attendues (quatre parmi) :\n- l’**appel** : *Sehr geehrte Frau Weber* / *Lieber Max* ;\n- le **pronom** : vouvoiement *Sie, Ihnen, Ihre* avec **majuscule** / tutoiement *du, dir, dein* ;\n- la **formule finale** : *Mit freundlichen Grüßen* / *Viele Grüße* ou *Bis bald!* ;\n- la **signature** : prénom et nom / prénom seul ;\n- le **ton** : on se présente et on reste poli, sans exclamation familière, avec Mme Weber ; on exprime sa joie librement avec Max.\n\nFautes qui coûtent des points : *Sehr geehrter Frau Weber*, *ihnen* en minuscule, *Tschüss* à la fin du message formel."}$exo$::jsonb),
  ('28aaec6a-048f-5192-b135-72ff223afcfb'::uuid, 1, 'traduction', $exo${"titre":"Ich finde, dass… : placer le verbe","consigne":"Réécris les phrases comme demandé, puis réponds à la question 4.","enonce":"**1.** Commence par *Ich finde, dass …* :\na) *Das Buch ist spannend.*\nb) *Sport ist wichtig.*\nc) *Der Film ist langweilig.*\n\n**2.** Commence par *Meiner Meinung nach …* :\na) *Das Handy ist nützlich.*\nb) *Mathe ist toll.*\n\n**3.** Relie les deux phrases, d’abord avec *weil*, puis avec *denn* :\n*Ich mag Sport. Er ist gesund.*\n\n**4.** Classe ces adjectifs en positifs et négatifs : *spannend, langweilig, nützlich, gefährlich, lustig, schrecklich*.","bareme":[{"critere":"Trois subordonnées avec dass et le verbe à la fin","points":6},{"critere":"Deux phrases avec Meiner Meinung nach suivi du verbe puis du sujet","points":4},{"critere":"Weil avec le verbe à la fin, denn avec l’ordre normal","points":6},{"critere":"Les six adjectifs bien classés","points":4}],"dureeMin":7,"corrige":"**1.** Après *dass*, le verbe conjugué va **à la fin** :\na) *Ich finde, dass das Buch spannend **ist**.*\nb) *Ich finde, dass Sport wichtig **ist**.*\nc) *Ich finde, dass der Film langweilig **ist**.*\n\n**2.** *Meiner Meinung nach* compte pour une seule position : derrière, le verbe, puis le sujet.\na) *Meiner Meinung nach **ist das Handy** nützlich.*\nb) *Meiner Meinung nach **ist Mathe** toll.*\n\n**3.** *Ich mag Sport, **weil** er gesund **ist**.* (verbe à la fin)\n*Ich mag Sport, **denn** er **ist** gesund.* (ordre normal)\n\n**4.** Positifs : *spannend, nützlich, lustig*. Négatifs : *langweilig, gefährlich, schrecklich*."}$exo$::jsonb),
  ('28aaec6a-048f-5192-b135-72ff223afcfb'::uuid, 2, 'traduction', $exo${"titre":"Des devoirs le week-end ?","consigne":"Lis les deux messages du forum. Réponds en français aux questions 1 et 2, en allemand à la question 3.","enonce":"> **Tim :** *Meiner Meinung nach sind Hausaufgaben am Wochenende nützlich, weil man mehr Zeit hat. Der Vorteil ist, dass man ruhig arbeiten kann.*\n>\n> **Sara :** *Ich bin nicht einverstanden! Ich finde, dass das Wochenende für die Familie und den Sport ist. Hausaufgaben am Wochenende sind langweilig, denn wir arbeiten schon die ganze Woche.*\n\n*das Wochenende* = le week-end · *man* = on · *ruhig* = au calme · *die ganze Woche* = toute la semaine\n\n1. Qui est pour les devoirs le week-end, qui est contre ? Donne les arguments de chacun en français.\n2. Relève dans les messages :\na) une phrase avec **inversion** du verbe et du sujet ;\nb) **deux** verbes conjugués rejetés **à la fin** d’une subordonnée ;\nc) une justification avec **l’ordre normal** des mots.\n3. Réponds à Tim ou à Sara en **quatre phrases au moins** : dis si tu es d’accord, donne ton avis avec *Ich finde, dass …* et justifie-le avec *weil* ou *denn*.","bareme":[{"critere":"Positions et arguments de Tim et de Sara bien compris","points":6},{"critere":"Relevés justes : inversion, deux verbes en fin de subordonnée, ordre normal après denn","points":5},{"critere":"Réponse : accord ou désaccord, avis avec dass, justification","points":5},{"critere":"Correction de l’allemand, verbes bien placés","points":4}],"dureeMin":12,"corrige":"1. **Tim est pour** : il trouve les devoirs du week-end **utiles**, parce qu’on a **plus de temps**, et l’avantage est qu’on peut **travailler au calme**. **Sara est contre** : pour elle, le week-end est fait pour la **famille** et le **sport** ; les devoirs du week-end sont **ennuyeux**, car on **travaille déjà toute la semaine**.\n\n2. a) *Meiner Meinung nach **sind Hausaufgaben** am Wochenende nützlich.* (le verbe, puis le sujet)\nb) *weil man mehr Zeit **hat*** ; *dass man ruhig arbeiten **kann*** ; *dass das Wochenende für die Familie und den Sport **ist*** (deux parmi les trois).\nc) *denn wir **arbeiten** schon die ganze Woche* : après *denn*, l’ordre est normal.\n\n3. Exemple (réponse à Sara) :\n*Da hast du recht! Ich bin deiner Meinung. Ich finde, dass das Wochenende für den Sport ist. Hausaufgaben am Wochenende sind langweilig, weil wir schon viel arbeiten. Aber der Vorteil ist, dass man ruhig lesen kann.*\nOu (désaccord) : *Ich sehe das anders. Ich finde, dass Hausaufgaben am Wochenende nützlich sind, denn man hat mehr Zeit.*"}$exo$::jsonb),
  ('28aaec6a-048f-5192-b135-72ff223afcfb'::uuid, 3, 'traduction', $exo${"titre":"Un jour sans écran par semaine ?","consigne":"Rédige en allemand un texte argumenté de 8 à 10 phrases.","enonce":"**Sujet.** Ton collège propose : « Un jour par semaine sans écran pour tous les élèves. » Qu’en penses-tu ?\n\nTon texte doit contenir :\n- ton **avis** dès le début (*Ich finde, dass …* ou *Meiner Meinung nach …*) ;\n- le **pour et le contre** avec *einerseits … andererseits* ;\n- *Der Vorteil ist, dass …* et *Der Nachteil ist, dass …* ;\n- au moins une justification avec ***weil*** et une avec ***denn*** ;\n- une **conclusion** qui reprend ton avis.\n\n**Lexique** : *der Bildschirm* (l’écran) · *ohne* (sans) · *ein Tag ohne Bildschirm* · *die Woche* · *draußen* (dehors) · *zu viel Zeit online verbringen* (passer trop de temps en ligne) · *mit den Eltern telefonieren* · *mit den Freunden chatten* · *deshalb* (c’est pourquoi)","bareme":[{"critere":"Organisation : avis annoncé, pour et contre, conclusion","points":5},{"critere":"Justifications : weil avec le verbe à la fin, denn avec l’ordre normal","points":5},{"critere":"Ordre des mots juste après les formules (inversion après Meiner Meinung nach, einerseits, andererseits ; verbe final après dass)","points":6},{"critere":"Vocabulaire du jugement et correction de la langue","points":4}],"dureeMin":18,"corrige":"**Exemple de texte :**\n*Meiner Meinung nach ist ein Tag ohne Bildschirm eine gute Idee. Einerseits ist das Handy nützlich, denn man kann mit den Freunden chatten. Andererseits verbringen viele Schüler zu viel Zeit online. Der Vorteil ist, dass man mehr liest und draußen spielt. Der Nachteil ist, dass man nicht mit den Eltern telefonieren kann. Ich finde, dass ein Tag ohne Bildschirm nicht langweilig ist, weil man mit der Familie spielen kann. Aber ein Tag ist genug! Deshalb bin ich für einen Tag ohne Bildschirm pro Woche.*\n\nCe que le correcteur vérifie :\n- l’**avis** annoncé et repris en conclusion ;\n- l’**inversion** après *Meiner Meinung nach* (*ist ein Tag*), *Einerseits* (*ist das Handy*), *Andererseits* (*verbringen viele Schüler*), *Deshalb* (*bin ich*) ;\n- le **verbe à la fin** après *dass* (*liest … spielt*, *telefonieren kann*, *nicht langweilig ist*) et après *weil* (*spielen kann*) ;\n- l’**ordre normal** après *denn* (*denn man kann …*) ;\n- des **adjectifs de jugement** (*nützlich, langweilig, gefährlich, toll…*).\n\nUn avis contraire (*Ich bin nicht einverstanden …*) est tout aussi valable s’il est justifié."}$exo$::jsonb),
  ('5e047d4a-274b-5df5-a753-eeb28d43c615'::uuid, 1, 'traduction', $exo${"titre":"Who, which, whose, where","consigne":"Complète chaque phrase avec le bon pronom relatif, puis justifie ton choix en quelques mots en français.","enonce":"**Complète avec who, which, whose, where ou when.**\n\n1. The girl … sits next to me is from Dublin.\n2. This is the book … I told you about.\n3. I have a friend … mother is a pilot.\n4. Brighton is the town … my grandparents live.\n5. I remember the day … we met.\n6. The dog … lives next door barks all night.\n\n**7.** Dans laquelle de ces phrases le pronom relatif peut-il être **omis** ? Explique pourquoi.","bareme":[{"critere":"Les six pronoms relatifs justes","points":12},{"critere":"Justification du choix (personne, chose, possession, lieu, temps)","points":4},{"critere":"Phrase 2 identifiée : relatif complément dans une relative déterminative","points":4}],"dureeMin":7,"corrige":"1. The girl **who** sits next to me… (personne ; *that* accepté).\n2. This is the book **which** I told you about. (chose ; *that* ou rien acceptés)\n3. I have a friend **whose** mother is a pilot. (possession)\n4. Brighton is the town **where** my grandparents live. (lieu)\n5. I remember the day **when** we met. (temps)\n6. The dog **which** lives next door… (animal ; *that* accepté)\n\n7. Dans la **phrase 2** : *This is the book I told you about.* Le relatif est **complément** (le sujet de la relative est *I*) dans une relative **déterminative** : il peut sauter. Dans les phrases 1 et 6, il est **sujet** de la relative : il est obligatoire."}$exo$::jsonb),
  ('5e047d4a-274b-5df5-a753-eeb28d43c615'::uuid, 2, 'traduction', $exo${"titre":"Une lettre de Londres","consigne":"Relie chaque paire de phrases par un pronom relatif, en respectant la ponctuation des relatives, puis traduis les deux dernières phrases.","enonce":"**A. Relie les deux phrases en une seule.**\n\n1. My cousin Emma lives in London. She is a nurse. *(relative explicative : ajoute une information)*\n2. I bought a jacket. It was too small.\n3. We visited a museum. Its collection is famous.\n4. That's the café. We had breakfast there.\n\n**B. Traduis en anglais.**\n\n5. Le garçon que j'ai rencontré hier s'appelle Sam.\n6. Mon frère, qui habite à Leeds, vient ce week-end.","bareme":[{"critere":"Phrase 1 : relative explicative entre virgules avec who, sans that","points":5},{"critere":"Phrases 2 à 4 correctement reliées (which ou that, whose, where)","points":7},{"critere":"Traduction 5 : relatif complément, omission possible","points":4},{"critere":"Traduction 6 : relative explicative, virgules et who","points":4}],"dureeMin":10,"corrige":"**A.**\n1. *My cousin Emma, **who** lives in London, is a nurse.* — relative **explicative** : entre **virgules**, *that* impossible.\n2. *The jacket **which / that** I bought was too small.* (ou *I bought a jacket which was too small.*)\n3. *We visited a museum **whose** collection is famous.*\n4. *That's the café **where** we had breakfast.*\n\n**B.**\n5. *The boy (**who / that**) I met yesterday is called Sam.* Le relatif est **complément** dans une relative déterminative : il peut être omis — *The boy I met yesterday is called Sam.* « que » ne se traduit pas mot à mot.\n6. *My brother, **who** lives in Leeds, is coming this weekend.* Relative **explicative** : virgules, *who*, jamais *that*, jamais omis."}$exo$::jsonb),
  ('5e047d4a-274b-5df5-a753-eeb28d43c615'::uuid, 3, 'traduction', $exo${"titre":"Portrait d'une ville anglaise","consigne":"Corrige les phrases fautives en justifiant, puis rédige un court paragraphe en anglais selon les contraintes données.","enonce":"**A. Chaque phrase contient une erreur. Corrige-la et explique la règle en français.**\n\n1. The man which lives next door is a doctor.\n2. My sister, that is 18, studies in Oxford.\n3. The girl to who I spoke was very kind.\n4. The teacher explained the lesson I didn't understand it.\n\n**B. Production.** Présente en anglais une ville que tu aimes (6 à 8 phrases). Tu dois employer au moins :\n- une relative avec **whose** ;\n- une relative avec **where** ;\n- une relative **explicative** entre virgules ;\n- une relative où le pronom est **omis**.\n\nSouligne (ou mets en gras) les quatre relatives.","bareme":[{"critere":"Les quatre erreurs corrigées","points":6},{"critere":"Règle expliquée pour chaque correction","points":4},{"critere":"Les quatre relatives imposées présentes et correctes","points":6},{"critere":"Paragraphe cohérent, correct, de 6 à 8 phrases","points":4}],"dureeMin":18,"corrige":"**A.**\n1. *The man **who** lives next door is a doctor.* — antécédent **personne** : *who* (ou *that*), pas *which*.\n2. *My sister, **who** is 18, studies in Oxford.* — relative **explicative** (virgules) : *that* est **impossible**.\n3. *The girl **to whom** I spoke* (soutenu) ou *The girl **who** I spoke **to*** (courant, préposition à la fin). Après une préposition, on ne met pas *who*.\n4. *The teacher explained the lesson **(that / which)** I didn't understand.* — le relatif **remplace** le complément : on ne répète pas *it*.\n\n**B. Exemple attendu :**\n*I love York, **where** my aunt lives. It is a small city **whose** walls are very old. The cathedral, **which** is huge, is my favourite place. There is a tea room **I always go to** with my cousins. The streets are narrow and full of shops. It is the city **where** I feel happiest.*\n\nLe correcteur vérifie : *whose* suivi d'un nom sans article ; *where* pour un lieu ; relative explicative entre virgules avec *who* ou *which* ; une relative déterminative à relatif complément omis (*the tea room I always go to*)."}$exo$::jsonb),
  ('1b264862-f8ce-5efb-8d05-d96a023aab9a'::uuid, 1, 'traduction', $exo${"titre":"Poser les bonnes questions","consigne":"Transforme chaque phrase en question fermée, puis complète les questions ouvertes avec le bon mot interrogatif.","enonce":"**A. Transforme en question fermée (yes / no).**\n\n1. You are ready.\n2. She can swim.\n3. They like pizza.\n4. He went to the cinema.\n\n**B. Complète avec le bon mot interrogatif.**\n\n5. … do you live? — In Manchester.\n6. … did you arrive? — Yesterday.\n7. … do you go to the gym? — Twice a week.\n8. … is this bag? — It's Tom's.","bareme":[{"critere":"Les quatre questions fermées correctes (auxiliaire devant le sujet, do / does / did)","points":10},{"critere":"Les quatre mots interrogatifs justes","points":10}],"dureeMin":6,"corrige":"**A.**\n1. ***Are** you ready?* (avec *be* : inversion)\n2. ***Can** she swim?* (auxiliaire déjà présent)\n3. ***Do** they like pizza?* (temps simple : on introduit *do*)\n4. ***Did** he go to the cinema?* (prétérit : *did* + base verbale, *go* et non *went*)\n\n**B.**\n5. ***Where** do you live?*\n6. ***When** did you arrive?*\n7. ***How often** do you go to the gym?* (fréquence)\n8. ***Whose** bag is this?* / ***Whose** is this bag?* (à qui)"}$exo$::jsonb),
  ('1b264862-f8ce-5efb-8d05-d96a023aab9a'::uuid, 2, 'traduction', $exo${"titre":"L'interview d'une chanteuse","consigne":"Retrouve les questions qui correspondent aux réponses soulignées, puis corrige les questions indirectes fautives.","enonce":"**A. Pose la question qui porte sur la partie en gras.**\n\n1. I started singing **when I was eight**.\n2. **My father** taught me the guitar.\n3. I have lived in Liverpool **for ten years**.\n4. I wrote this song **because I missed my family**.\n5. My brother plays **the drums**.\n\n**B. Corrige ces questions indirectes.**\n\n6. Do you know where does she live?\n7. Could you tell me what time is it?","bareme":[{"critere":"Questions 1, 3, 4 et 5 : mot interrogatif, auxiliaire et ordre justes","points":8},{"critere":"Question 2 : who sujet, sans do","points":4},{"critere":"Deux questions indirectes corrigées avec l'ordre de l'affirmative","points":6},{"critere":"Orthographe et ponctuation","points":2}],"dureeMin":11,"corrige":"**A.**\n1. ***When did you start** singing?*\n2. ***Who taught** you the guitar?* — *who* est **sujet** : pas de *do*, ordre de l'affirmative (pas *Who did teach you*).\n3. ***How long have you lived** in Liverpool?*\n4. ***Why did you write** this song?*\n5. ***What does your brother play**?*\n\n**B.**\n6. *Do you know where **she lives**?* — la question enchâssée reprend l'ordre de l'**affirmative**, sans *does*.\n7. *Could you tell me what time **it is**?* — même règle : sujet puis verbe."}$exo$::jsonb),
  ('1b264862-f8ce-5efb-8d05-d96a023aab9a'::uuid, 3, 'traduction', $exo${"titre":"Enquête au collège","consigne":"Distingue les questions sur le sujet et sur le complément, puis rédige un questionnaire en anglais selon les contraintes.","enonce":"**Situation.** Quelqu'un a cassé la fenêtre de la salle de musique. Le principal mène l'enquête.\n\n**A.** Pour chaque phrase, pose une question avec **who** portant sur le mot en gras. Explique en français pourquoi l'une prend *did* et l'autre non.\n1. **Jake** broke the window.\n2. Jake saw **Mia** near the window.\n\n**B.** Traduis : « Est-ce que tu sais qui a cassé la fenêtre ? »\n\n**C. Production.** Rédige en anglais les **six questions** que le principal pose à un témoin. Tu dois utiliser : une question fermée avec *be*, une question fermée au prétérit, *where*, *what time*, *which* (choix entre deux portes), et une question indirecte commençant par *Can you tell me*.","bareme":[{"critere":"Les deux questions avec who justes","points":4},{"critere":"Explication : who sujet sans do, who complément avec did","points":4},{"critere":"Traduction de la question indirecte avec l'ordre affirmatif","points":3},{"critere":"Six questions correctes respectant chacune la contrainte imposée","points":9}],"dureeMin":17,"corrige":"**A.**\n1. ***Who broke** the window?* — *who* est **sujet** : pas de *do*, l'ordre reste celui de l'affirmative.\n2. ***Who did** Jake **see** near the window?* — *who* est **complément** : on introduit *did* et on inverse ; le verbe revient à la base verbale.\n\n**B.** *Do you know who broke the window?* — question indirecte : ordre de l'affirmative (ici *who* sujet, donc pas de *did* de toute façon).\n\n**C. Exemple attendu :**\n1. ***Were** you in the corridor at lunchtime?* (fermée avec *be*)\n2. ***Did** you **hear** a noise?* (fermée au prétérit : *did* + base verbale)\n3. ***Where were** you exactly?*\n4. ***What time did** you **leave** the canteen?*\n5. ***Which** door **did** you **take**, the red one or the blue one?*\n6. *Can you tell me **who you saw** near the music room?* (question indirecte : ordre de l'affirmative)\n\nLe correcteur vérifie la place de l'auxiliaire, la base verbale après *did*, et l'absence d'inversion dans la question indirecte."}$exo$::jsonb),
  ('932d2c69-b0a2-523b-af62-eafb0fdd8913'::uuid, 1, 'traduction', $exo${"titre":"N'est-ce pas ?","consigne":"Ajoute le question tag qui convient à chaque phrase.","enonce":"**Complète avec le bon question tag.**\n\n1. She is a teacher, …?\n2. You can swim, …?\n3. They didn't come, …?\n4. He has finished, …?\n5. You like coffee, …?\n6. Your brother lives in Cardiff, …?\n7. We aren't late, …?\n8. It was a great film, …?\n\n**9.** Rappelle en français les trois règles qui permettent de former un tag.","bareme":[{"critere":"Les huit tags justes","points":16},{"critere":"Les trois règles : auxiliaire (ou do), polarité inverse, pronom sujet","points":4}],"dureeMin":6,"corrige":"1. *isn't she?*\n2. *can't you?*\n3. *did they?*\n4. *hasn't he?*\n5. *don't you?* (pas d'auxiliaire : *do*)\n6. *doesn't he?* (présent, 3e personne : *does* ; *your brother* → *he*)\n7. *are we?*\n8. *wasn't it?*\n\n9. Les trois règles : le tag reprend l'**auxiliaire** de la phrase (sinon **do / does / did**) ; il est de **polarité inverse** (affirmative → tag négatif, négative → tag affirmatif) ; le sujet est repris par un **pronom**."}$exo$::jsonb),
  ('932d2c69-b0a2-523b-af62-eafb0fdd8913'::uuid, 2, 'traduction', $exo${"titre":"Les cas particuliers","consigne":"Ajoute les question tags, puis explique en français les cas qui échappent à la règle générale.","enonce":"**A. Complète avec le bon tag.**\n\n1. I am right, …?\n2. Let's go to the beach, …?\n3. Close the window, …?\n4. There is a bus at six, …?\n5. Somebody called me, …?\n6. Nobody saw the accident, …?\n\n**B.** Pour les phrases 1, 2, 4 et 5, explique en français pourquoi le tag n'est pas celui qu'on attendrait en appliquant seulement la règle générale.\n\n**C.** « You're coming tomorrow, aren't you? » : dis quel sens a la phrase si l'intonation du tag est descendante, puis montante.","bareme":[{"critere":"Les six tags justes","points":9},{"critere":"Explications des cas particuliers (aren't I, shall we, there, they)","points":7},{"critere":"Intonation : descendante = on cherche l'accord, montante = vraie question","points":4}],"dureeMin":11,"corrige":"**A.**\n1. *aren't I?*\n2. *shall we?*\n3. *will you?*\n4. *isn't there?*\n5. *didn't they?*\n6. *did they?* (*nobody* est négatif : tag affirmatif)\n\n**B.**\n1. *I am* donnerait « amn't I », qui n'existe pas : la forme consacrée est ***aren't I?***\n2. Après *Let's*, le tag est toujours ***shall we?***\n4. Avec *there is / there are*, le tag reprend ***there*** et non *it*.\n5. Avec un sujet indéfini (*somebody, nobody, everyone*), le pronom du tag est ***they***.\n\n**C.** Intonation **descendante** : on est sûr qu'il vient, on cherche seulement l'**accord**. Intonation **montante** : on **doute** vraiment, c'est une **vraie question**."}$exo$::jsonb),
  ('932d2c69-b0a2-523b-af62-eafb0fdd8913'::uuid, 3, 'traduction', $exo${"titre":"Un dialogue plein de tags","consigne":"Complète le dialogue avec les tags, corrige les erreurs, puis écris la suite du dialogue en anglais.","enonce":"**Dialogue.** Olivia and Ben are waiting for the school trip bus.\n\n> **Olivia**: The bus leaves at eight, (1) …?\n> **Ben**: Yes. You haven't forgotten your passport, (2) …?\n> **Olivia**: No! I'm not stupid, (3) …? Everyone has their ticket, don't they?\n> **Ben**: I think so. Let's check the list, (4) …?\n> **Olivia**: Mr Hill said we could sit together, didn't it?\n> **Ben**: Pass me the list, will you? There aren't many students, isn't it?\n\n**A.** Complète les tags (1) à (4).\n\n**B.** Deux tags du dialogue sont faux (en dehors des blancs). Retrouve-les, corrige-les et explique.\n\n**C.** Écris la suite du dialogue (6 répliques) : au moins **quatre** tags différents, dont un après un **impératif** et un après une phrase **négative**.","bareme":[{"critere":"Les quatre tags à compléter justes","points":6},{"critere":"Deux erreurs trouvées, corrigées et expliquées","points":5},{"critere":"Quatre tags corrects dans la suite, dont impératif et négative","points":6},{"critere":"Dialogue cohérent et correct","points":3}],"dureeMin":18,"corrige":"**A.**\n(1) *doesn't it?* (*the bus* → *it*, présent 3e personne)\n(2) *have you?* (phrase négative → tag affirmatif, auxiliaire *have*)\n(3) *am I?* (négative → affirmatif ; *I'm not…, am I?*)\n(4) *shall we?* (après *Let's*)\n\n**B.**\n- *Mr Hill said we could sit together, **didn't he?*** — le pronom reprend le sujet *Mr Hill* : *he*, pas *it*.\n- *There aren't many students, **are there?*** — phrase négative : tag affirmatif, et avec *there are* le tag reprend *there*.\n(*Everyone has their ticket, don't they?* est correct : sujet indéfini → *they*.)\n\n**C. Exemple attendu :**\n> **Olivia**: You didn't bring any food, **did you?**\n> **Ben**: Just a sandwich. It's a long trip, **isn't it?**\n> **Olivia**: Five hours. Don't sit on my bag, **will you?**\n> **Ben**: Sorry! You can speak French, **can't you?**\n> **Olivia**: A little. Nobody likes the ferry, **do they?**\n> **Ben**: I do!\n\nLe correcteur vérifie la polarité inverse, l'auxiliaire et le pronom de chaque tag."}$exo$::jsonb),
  ('bd43e615-93e1-54e7-ba98-9eee2c7d1881'::uuid, 1, 'traduction', $exo${"titre":"What ou how ?","consigne":"Complète chaque exclamation avec what, what a / an ou how.","enonce":"**Complète avec what, what a, what an ou how.**\n\n1. … beautiful day!\n2. … terrible weather!\n3. … strange!\n4. … fast he runs!\n5. … interesting idea!\n6. … nice people!\n7. … pity!\n\n**8.** Rappelle en français la règle qui permet de choisir entre *what* et *how*.","bareme":[{"critere":"Les sept exclamations justes (dont article a / an et absence d'article)","points":14},{"critere":"Règle : what + nom, how + adjectif ou adverbe","points":6}],"dureeMin":6,"corrige":"1. ***What a** beautiful day!* (nom singulier dénombrable : *a*)\n2. ***What** terrible weather!* (indénombrable : sans article)\n3. ***How** strange!* (adjectif)\n4. ***How** fast he runs!* (adverbe)\n5. ***What an** interesting idea!* (*an* devant une voyelle)\n6. ***What** nice people!* (pluriel : sans article)\n7. ***What a** pity!*\n\n8. ***What*** est suivi d'un **nom** (groupe nominal) ; ***how*** est suivi d'un **adjectif** ou d'un **adverbe**."}$exo$::jsonb),
  ('bd43e615-93e1-54e7-ba98-9eee2c7d1881'::uuid, 2, 'traduction', $exo${"titre":"So, such et l'ordre des mots","consigne":"Transforme les phrases selon les consignes, puis traduis les exclamations en anglais.","enonce":"**A. Transforme avec so, such ou such a.**\n\n1. She is very kind. → She is …\n2. It was a very good film. → It was …\n3. They are very nice people. → They are …\n\n**B. Corrige l'ordre des mots.**\n\n4. How beautiful is this place!\n5. How is it expensive!\n\n**C. Traduis en anglais.**\n\n6. Quel dommage !\n7. Comme ta sœur chante bien !\n8. Quelle belle maison !","bareme":[{"critere":"Transformations justes avec so, such a, such","points":6},{"critere":"Deux phrases corrigées sans inversion","points":6},{"critere":"Trois traductions justes","points":8}],"dureeMin":10,"corrige":"**A.**\n1. *She is **so** kind!* (*so* + adjectif)\n2. *It was **such a** good film!* (*such a* + adjectif + nom singulier)\n3. *They are **such** nice people!* (*such* + adjectif + nom pluriel)\n\n**B.** L'anglais ne fait **pas d'inversion** dans l'exclamation : le sujet reste devant le verbe.\n4. *How beautiful **this place is**!*\n5. *How expensive **it is**!*\n\n**C.**\n6. ***What a pity!*** (ou *What a shame!*)\n7. ***How well** your sister sings!* (adverbe → *how*, sans inversion)\n8. ***What a beautiful house!***"}$exo$::jsonb),
  ('bd43e615-93e1-54e7-ba98-9eee2c7d1881'::uuid, 3, 'traduction', $exo${"titre":"Carte postale d'Édimbourg","consigne":"Corrige le texte, puis rédige ta propre carte postale en anglais selon les contraintes.","enonce":"**A.** Ce message contient **cinq** erreurs sur l'exclamation. Recopie les phrases fautives corrigées et explique chaque correction en français.\n\n> Dear Grandma,\n> We are in Edinburgh! How a beautiful city! What old the castle is! Yesterday it rained all day: what a terrible weather! The people are so nice people. How is delicious the food here!\n> Love, Zoé\n\n**B. Production.** Écris une carte postale de 6 à 8 phrases racontant un voyage. Tu dois employer : *what a* + nom singulier, *what* + nom pluriel ou indénombrable, *how* + adjectif + sujet + verbe, *such a*, *so*, et une exclamation toute faite (*No way!*, *Well done!*, *How come?*…).","bareme":[{"critere":"Les cinq erreurs corrigées","points":7},{"critere":"Règle expliquée pour chaque correction","points":3},{"critere":"Les six structures imposées présentes et correctes","points":7},{"critere":"Carte postale cohérente et correcte","points":3}],"dureeMin":17,"corrige":"**A.**\n1. ***What a** beautiful city!* — devant un nom (*city*), c'est *what (a)*, pas *how*.\n2. ***How old** the castle is!* — devant un adjectif seul, c'est *how*.\n3. *What terrible weather!* — *weather* est **indénombrable** : **pas d'article**.\n4. *The people are **so nice**!* ou *They are **such nice people**!* — *so* + adjectif, *such* + adjectif + nom.\n5. *How delicious **the food is** here!* — **pas d'inversion** : sujet puis verbe.\n\n**B. Exemple attendu :**\n*Dear Tom,*\n*We're in Cornwall. **What a** lovely place! **What** beautiful beaches! **How** blue the sea is! We had **such a** good time at the surf school. I was **so** tired after the lesson. I stood up on the board: **Well done!** said the teacher.*\n\nLe correcteur vérifie : article *a* devant un singulier, pas d'article devant un pluriel ou un indénombrable, pas d'inversion après *how*, *such a* devant un nom singulier, *so* devant un adjectif seul."}$exo$::jsonb),
  ('bd1ddb34-e55d-5d2a-a85f-c0615a300c30'::uuid, 1, 'traduction', $exo${"titre":"Former le passif","consigne":"Mets chaque phrase à la voix passive en gardant le même temps.","enonce":"**Mets à la voix passive.** Garde le complément d'agent (*by…*) seulement quand il est utile.\n\n1. They build houses. *(présent)*\n2. Shakespeare wrote Hamlet. *(prétérit)*\n3. They have repaired the car. *(present perfect)*\n4. They will open the new pool next year. *(futur)*\n5. You can recycle this bottle. *(modal)*\n\n**6.** Rappelle en français comment se forme la voix passive.","bareme":[{"critere":"Les cinq phrases passives justes, au bon temps","points":15},{"critere":"Formation : be au temps voulu + participe passé, complément devenu sujet, by","points":5}],"dureeMin":7,"corrige":"1. *Houses **are built**.*\n2. *Hamlet **was written by** Shakespeare.* (l'auteur est intéressant : on garde *by*)\n3. *The car **has been repaired**.*\n4. *The new pool **will be opened** next year.*\n5. *This bottle **can be recycled**.*\n\n6. Voix passive : **be** conjugué au **temps** de la phrase active + **participe passé**. Le **complément d'objet** de l'actif devient **sujet** ; l'ancien sujet, si on le garde, est introduit par ***by***."}$exo$::jsonb),
  ('bd1ddb34-e55d-5d2a-a85f-c0615a300c30'::uuid, 2, 'traduction', $exo${"titre":"Un article de journal","consigne":"Transforme les phrases de l'article à la voix passive, puis justifie l'emploi du passif.","enonce":"**Article.**\n\n> Last night, someone stole a famous painting from the city museum. The police have arrested two men. Experts are examining the frame. The museum will reopen the gallery on Monday.\n\n1. Réécris les **quatre** phrases à la voix passive, sans complément d'agent quand l'auteur est inconnu ou évident.\n2. Pourquoi le passif est-il fréquent dans les articles de journaux ? Donne deux raisons en français.\n3. Traduis : « On m'a donné un prix. » Donne les deux passifs possibles et indique le plus courant.","bareme":[{"critere":"Quatre phrases passives justes, au bon temps","points":10},{"critere":"Complément d'agent omis quand il est inconnu ou évident","points":3},{"critere":"Deux raisons de l'emploi du passif","points":3},{"critere":"Double passif : I was given a prize (le plus courant) et A prize was given to me","points":4}],"dureeMin":11,"corrige":"1.\n- *Last night, a famous painting **was stolen** from the city museum.* (auteur inconnu : pas de *by someone*)\n- *Two men **have been arrested**.* (*by the police* est évident, on peut l'omettre)\n- *The frame **is being examined** by experts.* (présent en BE + -ING → *is being* + participe passé ; *by experts* accepté ou omis)\n- *The gallery **will be reopened** on Monday.*\n\n2. Le passif permet de **mettre en avant ce qui a été fait** plutôt que qui l'a fait ; l'auteur est souvent **inconnu** (le voleur) ou **évident** (la police). C'est pourquoi le complément d'agent est omis dans la grande majorité des phrases passives.\n\n3. ***I was given a prize.*** (le plus courant) ou ***A prize was given to me.***"}$exo$::jsonb),
  ('bd1ddb34-e55d-5d2a-a85f-c0615a300c30'::uuid, 3, 'traduction', $exo${"titre":"La construction du pont","consigne":"Corrige les erreurs, puis rédige un court texte informatif en anglais en employant le passif selon les contraintes.","enonce":"**A.** Chaque phrase contient une erreur sur le passif. Corrige-la et explique en français.\n\n1. The window broken by the storm.\n2. The bridge was build in 1894.\n3. English is speak in many countries.\n4. The letter has sent yesterday.\n\n**B. Production.** Rédige un texte informatif de 6 à 8 phrases sur un monument (réel ou inventé). Tu dois employer le passif à **quatre temps différents** (présent, prétérit, present perfect, futur ou modal), au moins un complément d'agent avec *by* justifié, et au moins un passif **sans** complément d'agent.\n\n**C.** Explique en français pourquoi tu as gardé *by* dans une phrase et pas dans une autre.","bareme":[{"critere":"Les quatre erreurs corrigées et expliquées","points":6},{"critere":"Passif à quatre temps différents, correctement formé","points":7},{"critere":"Usage justifié du complément d'agent (C)","points":4},{"critere":"Texte cohérent et correct","points":3}],"dureeMin":18,"corrige":"**A.**\n1. *The window **was** broken by the storm.* — il manque **be** : sans lui, pas de verbe conjugué.\n2. *The bridge was **built** in 1894.* — il faut le **participe passé** (*built*), pas la base verbale.\n3. *English is **spoken** in many countries.* — participe passé de *speak* : *spoken*.\n4. *The letter **was sent** yesterday.* — avec *yesterday* (moment passé précis), le **prétérit** : *was sent* ; et le passif demande *be* (*has been sent* serait incompatible avec *yesterday*).\n\n**B. Exemple attendu :**\n*Tower Bridge **was built** between 1886 and 1894. It **was designed by** Horace Jones. Today, it **is crossed** by thousands of cars every day. The bridge **has been painted** blue and white. It **can be visited** all year round. A new exhibition **will be opened** next spring.*\n\n**C.** On garde *by* quand l'auteur est **intéressant** ou nouveau (l'architecte) ; on l'omet quand il est **inconnu, évident ou sans intérêt** (ceux qui ont peint le pont) : s'il était important, on aurait gardé l'actif."}$exo$::jsonb),
  ('ff6ca0a5-a3dd-5cb1-836a-ad0b3941a5f6'::uuid, 1, 'traduction', $exo${"titre":"Plus, moins, aussi","consigne":"Complète chaque phrase avec le comparatif demandé.","enonce":"**Complète avec le comparatif indiqué.**\n\n1. My brother is … (tall, supériorité) me.\n2. This phone is … (expensive, supériorité) that one.\n3. Today is … (hot, supériorité) yesterday.\n4. My marks are … (good, supériorité) last term.\n5. This film is … (interesting, infériorité) the book.\n6. Leo is … (old, égalité) Sam.\n7. The weather is … (bad, supériorité) last week.\n\n**8.** Explique en français quand on emploie *-er* et quand on emploie *more*.","bareme":[{"critere":"Les sept comparatifs justes (formes régulières, doublement, irréguliers)","points":14},{"critere":"Règle : adjectif court + -er, adjectif long more","points":6}],"dureeMin":7,"corrige":"1. ***taller than***\n2. ***more expensive than***\n3. ***hotter than*** (consonne finale doublée)\n4. ***better than*** (irrégulier)\n5. ***less interesting than***\n6. ***as old as***\n7. ***worse than*** (irrégulier)\n\n8. Un adjectif **court** (une syllabe, ou deux syllabes en *-y*) prend **-er** + *than* (*tall → taller*, *happy → happier*). Un adjectif **long** (deux syllabes ou plus) prend **more** + adjectif + *than*. On ne cumule jamais les deux."}$exo$::jsonb),
  ('ff6ca0a5-a3dd-5cb1-836a-ad0b3941a5f6'::uuid, 2, 'traduction', $exo${"titre":"Londres ou Paris ?","consigne":"Exploite le tableau pour écrire des comparaisons en anglais, puis traduis les phrases.","enonce":"**Document – Deux villes** (données simplifiées pour l'exercice)\n\n| | City A | City B |\n|---|---|---|\n| Population | 9 million | 2 million |\n| Price of a coffee | £3 | £3 |\n| Parks | 40 | 25 |\n| Rainy days a year | 150 | 110 |\n\n**A.** Écris **quatre** phrases comparant les deux villes : une avec *bigger*, une d'**égalité**, une avec *fewer*, une avec *less* ou *more* + nom indénombrable.\n\n**B. Traduis.**\n\n1. Il y a de plus en plus de touristes.\n2. Plus tu voyages, plus tu apprends.\n3. Ma ville est moins polluée que la tienne.","bareme":[{"critere":"Quatre comparaisons justes et conformes aux données","points":8},{"critere":"fewer avec un dénombrable, less ou more avec un indénombrable","points":3},{"critere":"Traductions 1 et 2 : structures de plus en plus et plus… plus","points":6},{"critere":"Traduction 3 : less + adjectif + than","points":3}],"dureeMin":11,"corrige":"**A. Exemples attendus :**\n- *City A is **bigger than** City B.*\n- *A coffee is **as expensive** in City B **as** in City A.* (égalité)\n- *City B has **fewer** parks **than** City A.* (*parks* dénombrable → *fewer*)\n- *City B gets **less** rain **than** City A.* ou *City A has **more** rain.* (*rain* indénombrable ; accepter aussi *fewer rainy days*)\n\n**B.**\n1. *There are **more and more** tourists.*\n2. ***The more** you travel, **the more** you learn.*\n3. *My town is **less polluted than** yours.*"}$exo$::jsonb),
  ('ff6ca0a5-a3dd-5cb1-836a-ad0b3941a5f6'::uuid, 3, 'traduction', $exo${"titre":"Avant et après le déménagement","consigne":"Corrige les erreurs, puis rédige un paragraphe argumenté en anglais selon les contraintes.","enonce":"**A.** Corrige chaque phrase et explique la règle en français.\n\n1. My new school is more bigger than the old one.\n2. The teachers are more nice.\n3. I have less friends than before.\n4. The bus is more far than the train station.\n5. He is not as fast than you.\n\n**B. Production.** Maya a déménagé de Londres à un petit village écossais. Écris en anglais son message (7 à 9 phrases) où elle compare sa vie d'avant et sa vie d'aujourd'hui. Tu dois employer : un comparatif en *-er*, un avec *more*, un avec *less* + adjectif, une **égalité négative**, *fewer*, un **irrégulier**, et la structure *The more…, the more…*.","bareme":[{"critere":"Les cinq erreurs corrigées","points":5},{"critere":"Règle expliquée pour chaque correction","points":3},{"critere":"Les sept structures imposées présentes et correctes","points":9},{"critere":"Message cohérent et correct","points":3}],"dureeMin":18,"corrige":"**A.**\n1. *My new school is **bigger than** the old one.* — on ne cumule jamais *more* et *-er*.\n2. *The teachers are **nicer**.* — *nice* est court : *-er*.\n3. *I have **fewer** friends than before.* — *friends* est **dénombrable** : *fewer*, pas *less*.\n4. *The bus is **farther / further** than the train station.* — *far* est irrégulier.\n5. *He is not as fast **as** you.* — égalité : *as… as*, jamais *as… than*.\n\n**B. Exemple attendu :**\n*My new village is **smaller than** London. Life is **more peaceful** here. The shops are **less crowded**, but there are **fewer** buses. The weather is **worse** than in London: it rains all the time! My new school is **not as big as** my old one. I miss my friends, but **the more** I meet people, **the more** I like it here.*\n\nLe correcteur vérifie chaque structure imposée, *than* après le comparatif, *as… as* pour l'égalité, et l'absence de double marque."}$exo$::jsonb),
  ('be329785-d058-536d-ae70-5d1193400cf2'::uuid, 1, 'traduction', $exo${"titre":"Le plus, le moins","consigne":"Complète chaque phrase avec le superlatif de l'adjectif entre parenthèses.","enonce":"**Complète avec le superlatif.**\n\n1. Tom is … (tall) boy in the class.\n2. This is … (expensive) hotel in the city.\n3. It was … (good) day of my life.\n4. January is … (cold) month of the year.\n5. This is … (bad) film I have ever seen.\n6. She is … (happy) girl in the world.\n7. This is … (interesting, infériorité) book of the series.\n\n**8.** Explique en français l'emploi de *in* et de *of* après un superlatif.","bareme":[{"critere":"Les sept superlatifs justes, avec the","points":14},{"critere":"in pour un lieu ou un groupe, of pour un ensemble ou une période","points":6}],"dureeMin":7,"corrige":"1. ***the tallest***\n2. ***the most expensive***\n3. ***the best*** (irrégulier)\n4. ***the coldest***\n5. ***the worst*** (irrégulier)\n6. ***the happiest*** (y → i)\n7. ***the least interesting***\n\nL'article ***the*** est obligatoire devant un superlatif.\n\n8. ***in*** introduit un **lieu** ou un **groupe** (*in the class, in the city, in the world*) ; ***of*** introduit un **ensemble** ou une **période** (*of the year, of my life, of the series*)."}$exo$::jsonb),
  ('be329785-d058-536d-ae70-5d1193400cf2'::uuid, 2, 'traduction', $exo${"titre":"Les records de la classe","consigne":"Exploite le tableau pour écrire des phrases en anglais, en choisissant entre comparatif et superlatif.","enonce":"**Document – Les résultats du cross**\n\n| Élève | Temps | Âge |\n|---|---|---|\n| Ella | 12 min | 14 |\n| Noah | 10 min | 15 |\n| Ruby | 15 min | 14 |\n\n**A.** Écris **quatre** phrases : qui est **le plus rapide**, **le plus lent**, **le plus âgé** des trois, et compare Ella et Ruby (deux élèves seulement).\n\n**B.** Choisis la bonne forme et justifie en français.\n\n1. Of the two brothers, Jack is (the taller / the tallest).\n2. Of the three sisters, Amy is (the younger / the youngest).\n\n**C. Traduis.** C'est le meilleur livre que j'aie jamais lu.","bareme":[{"critere":"Quatre phrases justes et conformes au tableau","points":8},{"critere":"Comparatif pour deux éléments, superlatif pour trois ou plus, justifié","points":6},{"critere":"Traduction avec the best et le present perfect (have ever read)","points":6}],"dureeMin":10,"corrige":"**A. Exemples attendus :**\n- *Noah is **the fastest** runner of the three.*\n- *Ruby is **the slowest**.*\n- *Noah is **the oldest** of the three.*\n- *Ella is **faster than** Ruby.* (deux élèves : **comparatif**)\n\n**B.**\n1. ***the taller*** — on ne compare que **deux** éléments : comparatif (*the taller of the two*).\n2. ***the youngest*** — **trois** éléments ou plus : superlatif.\n\n**C.** *It is **the best** book I **have ever read**.* — la relative d'expérience après un superlatif est au **present perfect**."}$exo$::jsonb),
  ('be329785-d058-536d-ae70-5d1193400cf2'::uuid, 3, 'traduction', $exo${"titre":"Le guide du meilleur week-end","consigne":"Corrige les erreurs, puis rédige un court guide touristique en anglais selon les contraintes.","enonce":"**A.** Corrige chaque phrase et explique la règle en français.\n\n1. This is most beautiful beach in Wales.\n2. It's the most tallest building of the city.\n3. It was the coldest day in the year.\n4. This is the better restaurant I have ever been to.\n5. She is the smartest of the two girls.\n\n**B. Production.** Rédige un guide de 6 à 8 phrases pour un visiteur de ta ville ou d'une ville imaginaire. Tu dois employer : un superlatif en *-est*, un avec *the most*, un avec *the least*, deux **irréguliers**, une construction avec *in* et une avec *of*, et une relative au **present perfect** (*… I have ever …*).","bareme":[{"critere":"Les cinq erreurs corrigées","points":5},{"critere":"Règle expliquée pour chaque correction","points":3},{"critere":"Les structures imposées présentes et correctes","points":9},{"critere":"Guide cohérent et correct","points":3}],"dureeMin":17,"corrige":"**A.**\n1. *This is **the** most beautiful beach in Wales.* — l'article ***the*** est obligatoire devant un superlatif.\n2. *It's **the tallest** building **in** the city.* — pas de double marque (*most* + *-est*) ; *in* pour un lieu.\n3. *It was the coldest day **of** the year.* — *of* pour une période.\n4. *This is **the best** restaurant I have ever been to.* — superlatif de *good* : *the best* (*better* est le comparatif).\n5. *She is **the smarter** of the two girls.* — deux éléments seulement : **comparatif**.\n\n**B. Exemple attendu :**\n*Welcome to Bath! The Roman Baths are **the most famous** place **in** the city. Try the Pump Room: it serves **the best** tea I **have ever tasted**. The **cheapest** way to visit is on foot. Avoid Saturday: it is **the worst** day **of** the week for crowds. The **least** expensive museum is free!*\n\nLe correcteur vérifie *the* devant chaque superlatif, les irréguliers (*best, worst*), *in* / *of*, et le present perfect après *ever*."}$exo$::jsonb),
  ('81702cf4-4a06-58c0-984a-eb0526cffd17'::uuid, 1, 'traduction', $exo${"titre":"Used to ou be used to ?","consigne":"Complète chaque phrase avec la bonne forme, puis traduis-la en français.","enonce":"**Complète avec used to, am / is used to ou is getting used to, et mets le verbe à la bonne forme.**\n\n1. When I was a child, I … (play) with dolls. *(ce n'est plus le cas)*\n2. I … (get up) early: I do it every day, it's easy for me.\n3. She has just moved to Canada. She … (live) in the cold.\n4. My grandfather … (smoke), but he stopped ten years ago.\n\n**5.** Explique en français la différence de forme du verbe après *used to* et après *be used to*.","bareme":[{"critere":"Les quatre formes justes","points":10},{"critere":"Traductions françaises justes","points":4},{"critere":"Règle : used to + base verbale, be used to + -ING","points":6}],"dureeMin":7,"corrige":"1. *I **used to play** with dolls.* — « Je jouais à la poupée (autrefois). »\n2. *I **am used to getting up** early.* — « J'ai l'habitude de me lever tôt. »\n3. *She **is getting used to living** in the cold.* — « Elle s'habitue à vivre dans le froid. »\n4. *My grandfather **used to smoke**.* — « Mon grand-père fumait (autrefois). »\n\n5. Après ***used to*** (habitude passée révolue) : **base verbale**. Après ***be / get used to*** (être habitué, s'habituer) : verbe en **-ING** ou nom."}$exo$::jsonb),
  ('81702cf4-4a06-58c0-984a-eb0526cffd17'::uuid, 2, 'traduction', $exo${"titre":"La vie d'avant de Grandpa Joe","consigne":"Exploite le document pour écrire des phrases avec used to, would et le présent simple.","enonce":"**Document – Grandpa Joe, 80 ans, raconte**\n\n| Autrefois | Aujourd'hui |\n|---|---|\n| went to school on foot | takes the bus to town |\n| was very shy | is very talkative |\n| every Sunday, went fishing with his father | watches football on TV |\n| didn't have a phone | calls his grandchildren every day |\n\n1. Écris **quatre** phrases sur la vie d'autrefois de Joe avec *used to* (dont une à la forme **négative**).\n2. Réécris la phrase sur la pêche avec *would*. Peut-on faire de même pour « was very shy » ? Justifie.\n3. Écris deux phrases sur sa vie d'aujourd'hui avec un adverbe de fréquence bien placé.\n4. Pose une question à Joe avec *used to*.","bareme":[{"critere":"Quatre phrases avec used to justes, dont la négative didn't use to","points":8},{"critere":"Would pour l'action répétée, impossible pour un état, justifié","points":5},{"critere":"Deux phrases au présent simple avec adverbe bien placé","points":4},{"critere":"Question Did you use to… ?","points":3}],"dureeMin":11,"corrige":"1. Exemples attendus :\n- *Joe **used to go** to school on foot.*\n- *He **used to be** very shy.*\n- *He **used to go** fishing with his father every Sunday.*\n- *He **didn't use to have** a phone.* (sans *-d* après *did*)\n\n2. *Every Sunday, he **would go** fishing with his father.* — *would* convient pour une **action répétée**. Pour « was very shy », **non** : c'est un **état** ; seul *used to* convient (*He used to be shy*, jamais *he would be shy*).\n\n3. Exemples : *He **usually takes** the bus to town.* / *He **always calls** his grandchildren.* / *He **is often** very talkative.* — l'adverbe se place **avant** le verbe lexical, **après** *be*.\n\n4. ***Did** you **use to** play football, Grandpa?*"}$exo$::jsonb),
  ('81702cf4-4a06-58c0-984a-eb0526cffd17'::uuid, 3, 'traduction', $exo${"titre":"Une nouvelle vie à Toronto","consigne":"Corrige les erreurs, puis rédige un texte en anglais qui oppose passé, présent et adaptation.","enonce":"**A.** Corrige chaque phrase et explique la règle en français.\n\n1. I am used to swim every morning.\n2. I didn't used to like vegetables.\n3. When I was young, I would be very shy.\n4. She is getting used to speak English.\n\n**B. Production.** Nadia vient de quitter Lyon pour Toronto. Rédige son journal intime (8 à 10 phrases) : ce qu'elle faisait autrefois, ce qu'elle fait maintenant, ce à quoi elle est déjà habituée et ce à quoi elle s'habitue peu à peu. Tu dois employer : *used to* (affirmatif et négatif), *would*, *be used to*, *get used to*, et le présent simple avec deux adverbes de fréquence.","bareme":[{"critere":"Les quatre erreurs corrigées et expliquées","points":6},{"critere":"Used to affirmatif et négatif, would pour une action répétée","points":5},{"critere":"Be used to et get used to suivis de -ING ou d'un nom","points":5},{"critere":"Présent simple et adverbes bien placés, texte cohérent","points":4}],"dureeMin":18,"corrige":"**A.**\n1. *I am used to **swimming** every morning.* — après *be used to* : **-ING**.\n2. *I didn't **use** to like vegetables.* — après *did*, pas de *-d* : *didn't use to*.\n3. *When I was young, I **used to be** very shy.* — *shy* est un **état** : *would* est impossible.\n4. *She is getting used to **speaking** English.* — après *get used to* : **-ING**.\n\n**B. Exemple attendu :**\n*In Lyon, I **used to walk** to school with my friends. Every Friday, we **would eat** crêpes together. I **didn't use to wear** a hat! Now I **always wear** one, because it's minus ten. I **usually take** the subway. I **am** already **used to speaking** English at school. But I **am** still **getting used to** the snow and to having dinner at six.*\n\nLe correcteur vérifie : base verbale après *used to*, *didn't use to*, *would* seulement pour une action, **-ING** ou nom après *be / get used to*, adverbes avant le verbe lexical."}$exo$::jsonb),
  ('deb67f74-a4ca-5a01-8448-aec0c5e63008'::uuid, 1, 'traduction', $exo${"titre":"Pourquoi fais-tu cela ?","consigne":"Complète chaque phrase pour exprimer le but, puis justifie ton choix en quelques mots.","enonce":"**Complète avec to, in order to, so as not to, so that ou for.**\n\n1. I went to the shop … buy bread.\n2. I wrote it down … forget.\n3. I'll speak slowly … you can understand.\n4. This knife is … cutting bread.\n5. He left early … catch the train. *(registre formel)*\n6. I went to the bakery … some croissants.\n\n**7.** Explique en français pourquoi « I went to the shop for buying bread » est faux.","bareme":[{"critere":"Les six compléments justes","points":12},{"critere":"Justifications (même sujet, autre sujet, but négatif, for + nom ou -ING)","points":4},{"critere":"Explication : but d'une action = to + base verbale, jamais for + verbe","points":4}],"dureeMin":7,"corrige":"1. ***to*** — but, même sujet.\n2. ***so as not to*** (ou *in order not to*) — but **négatif**.\n3. ***so that*** — le but concerne **un autre sujet** (*you*).\n4. ***for*** — *for* + **-ING** : à quoi sert un objet.\n5. ***in order to*** — registre formel.\n6. ***for*** — *for* + **nom** : aller chercher.\n\n7. Pour exprimer le **but d'une action**, l'anglais emploie ***to* + base verbale** : *I went to the shop **to buy** bread.* *For* ne s'emploie que devant un **nom** ou pour dire à quoi sert un objet (*for* + -ING)."}$exo$::jsonb),
  ('deb67f74-a4ca-5a01-8448-aec0c5e63008'::uuid, 2, 'traduction', $exo${"titre":"Préparer un voyage à Dublin","consigne":"Relie les phrases pour exprimer le but, puis traduis.","enonce":"**A. Relie les deux phrases pour exprimer le but.**\n\n1. Tom saves money. He wants to go to Dublin. *(même sujet)*\n2. His mother gives him a map. She wants him to find his way. *(autre sujet)*\n3. Tom takes an umbrella. He doesn't want to get wet. *(but négatif)*\n4. He learns some Irish words. He wants to impress his host family. *(registre formel)*\n\n**B. Traduis.**\n\n5. Je t'appelle pour te poser une question.\n6. Elle a acheté un ordinateur pour que son fils puisse travailler.\n7. — Pourquoi es-tu venu ? — Pour te voir.","bareme":[{"critere":"Quatre phrases reliées avec la bonne structure (to, so that, so as not to, in order to)","points":10},{"critere":"Traduction 5 avec to","points":3},{"critere":"Traduction 6 avec so that et un modal","points":4},{"critere":"Traduction 7 : question Why… ? et réponse To…","points":3}],"dureeMin":10,"corrige":"**A.**\n1. *Tom saves money **to go** to Dublin.*\n2. *His mother gives him a map **so that he can find** his way.* (autre sujet : *so that* + proposition, souvent avec un modal)\n3. *Tom takes an umbrella **so as not to get** wet.* (ou *in order not to get wet*)\n4. *He learns some Irish words **in order to impress** his host family.*\n\n**B.**\n5. *I'm calling you **to ask** you a question.*\n6. *She bought a computer **so that her son could work**.* (passé : *could*)\n7. — ***Why** did you come?* (ou *What did you come for?*) — ***To see** you.*"}$exo$::jsonb),
  ('deb67f74-a4ca-5a01-8448-aec0c5e63008'::uuid, 3, 'traduction', $exo${"titre":"Une campagne pour le climat","consigne":"Corrige les erreurs, puis rédige un court texte argumentatif en anglais selon les contraintes.","enonce":"**A.** Corrige chaque phrase et explique la règle en français.\n\n1. We cycle to school for reducing pollution.\n2. I turned off the light for not waste energy.\n3. The teacher explained it twice to we understand.\n4. We recycle for protect the planet.\n\n**B. Production.** Les élèves de ton collège lancent une campagne pour le climat. Rédige en anglais un texte de 7 à 9 phrases qui présente les actions et leur but. Tu dois employer : *to*, *in order to*, *so as not to* (ou *in order not to*), *so that* avec un modal, *for* + nom, *for* + -ING (objet), et une question sur le but avec *What… for?*","bareme":[{"critere":"Les quatre erreurs corrigées","points":5},{"critere":"Règle expliquée pour chaque correction","points":3},{"critere":"Les structures imposées présentes et correctes","points":9},{"critere":"Texte cohérent et correct","points":3}],"dureeMin":18,"corrige":"**A.**\n1. *We cycle to school **to reduce** pollution.* — but d'une action : **to + base verbale**, jamais *for* + -ING.\n2. *I turned off the light **so as not to waste** energy.* — but négatif : *so as not to / in order not to*.\n3. *The teacher explained it twice **so that we could understand**.* — autre sujet : *so that* + proposition complète (sujet *we*, modal).\n4. *We recycle **to protect** the planet.* — *for* ne se met jamais devant une base verbale.\n\n**B. Exemple attendu :**\n*Our school wants to act **to protect** the climate. We will walk or cycle **in order to reduce** pollution. We will switch off computers **so as not to waste** energy. We will plant trees **so that** future students **can** enjoy shade. Each class has a box **for** used paper and a bin **for collecting** plastic bottles. **What** are we doing this **for**? For our future!*\n\nLe correcteur vérifie : *to* + base verbale, but négatif, *so that* + sujet + modal, *for* seulement devant un nom ou pour un objet (-ING), *What… for?*"}$exo$::jsonb),
  ('cba4b326-06a2-5c51-904f-c9e56fc2dc6f'::uuid, 1, 'traduction', $exo${"titre":"For, since ou ago ?","consigne":"Complète avec for, since ou ago, puis justifie en quelques mots.","enonce":"**Complète avec for, since ou ago.**\n\n1. I have lived here … five years.\n2. She has worked here … 2020.\n3. I met him three years … .\n4. We have been friends … we were ten.\n5. I waited … two hours.\n6. They moved to Bristol a month … .\n\n**7.** Avec quel temps s'emploient *since* et *ago* ? Donne la règle en français.","bareme":[{"critere":"Les six mots justes","points":12},{"critere":"Justification : durée, point de départ, distance dans le passé","points":4},{"critere":"since + present perfect, ago + prétérit","points":4}],"dureeMin":6,"corrige":"1. ***for*** — durée.\n2. ***since*** — point de départ.\n3. ***ago*** — distance dans le passé, placé **après** la durée.\n4. ***since*** — point de départ (proposition).\n5. ***for*** — durée (jamais *during two hours*).\n6. ***ago***\n\n7. ***Since*** s'emploie presque toujours avec le **present perfect** (il relie un point du passé au présent). ***Ago*** s'emploie toujours avec le **prétérit**."}$exo$::jsonb),
  ('cba4b326-06a2-5c51-904f-c9e56fc2dc6f'::uuid, 2, 'traduction', $exo${"titre":"La fiche de Priya","consigne":"Exploite la fiche pour écrire des phrases en anglais avec for, since et ago, puis traduis.","enonce":"**Document – Priya, en septembre 2026**\n\n- arrived in Leeds: **September 2021**\n- started playing the violin: **when she was seven**\n- has had her dog Max: **three years**\n- last saw her cousin in India: **two years before now**\n\n**A.** Écris **quatre** phrases sur Priya : une avec *for*, une avec *since*, une avec *ago*, une avec *It's been … since*.\n\n**B.** Pose à Priya une question sur la **durée** de sa vie à Leeds, puis une sur le **moment** de son arrivée.\n\n**C. Traduis.** J'habite ici depuis six mois.","bareme":[{"critere":"Quatre phrases justes avec le bon temps","points":10},{"critere":"Deux questions : How long have you… ? et When did you… ?","points":5},{"critere":"Traduction avec le present perfect et for","points":5}],"dureeMin":11,"corrige":"**A. Exemples attendus :**\n- *She **has had** her dog Max **for** three years.*\n- *She **has lived** in Leeds **since** 2021.* (ou *has played the violin since she was seven*)\n- *She **saw** her cousin two years **ago**.* (prétérit)\n- ***It's been** five years **since** she arrived in Leeds.* (ou *It's been two years since she saw her cousin*)\n\n**B.**\n- ***How long have you lived** in Leeds?* (durée d'une situation en cours)\n- ***When did you arrive** in Leeds?* (moment précis : prétérit)\n\n**C.** *I **have lived** here **for** six months.* — « depuis » + durée en cours : **present perfect** + ***for*** (pas de présent simple, pas de *since six months*)."}$exo$::jsonb),
  ('cba4b326-06a2-5c51-904f-c9e56fc2dc6f'::uuid, 3, 'traduction', $exo${"titre":"Mon parcours de musicien","consigne":"Corrige les erreurs, puis rédige un texte en anglais sur ton parcours selon les contraintes.","enonce":"**A.** Corrige chaque phrase et explique la règle en français.\n\n1. I have met him three years ago.\n2. I live here since 2019.\n3. We stayed in London during two weeks.\n4. She has been ill since three days.\n5. How long are you here?\n\n**B. Production.** Rédige un texte de 7 à 9 phrases sur une activité que tu pratiques (sport, musique…) : quand tu as commencé, depuis combien de temps tu la pratiques, ce que tu as fait pendant les vacances. Tu dois employer : *for* avec le present perfect, *for* avec le prétérit, *since*, *ago*, *during* + nom, *It's been … since*, et une question avec *How long*.","bareme":[{"critere":"Les cinq erreurs corrigées","points":5},{"critere":"Règle expliquée pour chaque correction","points":3},{"critere":"Les structures imposées présentes, avec le bon temps","points":9},{"critere":"Texte cohérent et correct","points":3}],"dureeMin":18,"corrige":"**A.**\n1. *I **met** him three years ago.* — *ago* s'emploie **toujours avec le prétérit**.\n2. *I **have lived** here since 2019.* — situation qui dure jusqu'à aujourd'hui avec *since* : **present perfect**.\n3. *We stayed in London **for** two weeks.* — *during* + nom (*during the holidays*), jamais + durée chiffrée.\n4. *She has been ill **for** three days.* — *three days* est une **durée** : *for*.\n5. *How long **have you been** here?* — durée d'une situation en cours : present perfect.\n\n**B. Exemple attendu :**\n*I play the guitar. I started six years **ago**, when I was eight. I **have played** in a band **for** two years. My teacher **has taught** me **since** 2022. Last summer, I went to a music camp: I practised **for** five hours a day **during** the holidays. **It's been** a year **since** I **gave** my first concert. And you, **how long have you played** an instrument?*\n\nLe correcteur vérifie : *ago* + prétérit, *since* + present perfect, *for* + durée à tous les temps, *during* + nom."}$exo$::jsonb),
  ('c1557564-7e17-53d2-a2db-a5b58af7e4c0'::uuid, 1, 'traduction', $exo${"titre":"Rapporter des paroles","consigne":"Mets chaque phrase au discours indirect après « He said » ou « She said ».","enonce":"**Mets au discours indirect.**\n\n1. « I am tired. » → He said …\n2. « I saw her. » → He said …\n3. « I will call you. » → She said …\n4. « I can swim. » → He said …\n5. « I have finished. » → She said …\n\n**6.** Explique en français ce qu'est le **recul des temps** et quand il ne s'applique pas.","bareme":[{"critere":"Les cinq phrases justes (temps reculé, pronoms adaptés)","points":15},{"critere":"Recul des temps défini, avec ses exceptions (verbe introducteur au présent, vérité générale)","points":5}],"dureeMin":7,"corrige":"1. *He said (that) he **was** tired.* (présent → prétérit)\n2. *He said (that) he **had seen** her.* (prétérit → past perfect)\n3. *She said (that) she **would** call me.* (*will* → *would* ; *you* → *me*)\n4. *He said (that) he **could** swim.* (*can* → *could*)\n5. *She said (that) she **had finished**.* (present perfect → past perfect)\n\n6. Quand le verbe introducteur est au **passé** (*said, told*), chaque temps **recule d'un cran**. Le recul ne s'applique **pas** quand le verbe introducteur est au **présent** (*He says he is tired*), ni quand le fait rapporté est **toujours vrai**."}$exo$::jsonb),
  ('c1557564-7e17-53d2-a2db-a5b58af7e4c0'::uuid, 2, 'traduction', $exo${"titre":"Ce que le prof a dit","consigne":"Rapporte les paroles au discours indirect en adaptant temps, pronoms et repères.","enonce":"**Situation.** Hier, Mrs Cole a parlé à la classe. Aujourd'hui, Lucas raconte ce qu'elle a dit à Jade, qui était absente.\n\n1. « The test is tomorrow. »\n2. « I corrected your essays yesterday. »\n3. « Are you ready? »\n4. « Where do you usually revise? »\n5. « Close your books. »\n6. « Don't be late. »\n\nCommence chaque phrase par *She said*, *She told us* ou *She asked us*. Choisis bien entre *say* et *tell*.","bareme":[{"critere":"Phrases 1 et 2 : temps reculés et repères adaptés (the next day, the day before)","points":6},{"critere":"Questions 3 et 4 : if, ordre de l'affirmative","points":6},{"critere":"Ordres 5 et 6 : told us to / not to + base verbale","points":5},{"critere":"say et tell bien employés, pronoms adaptés","points":3}],"dureeMin":11,"corrige":"1. *She said (that) the test **was the next day**.* (*is* → *was* ; *tomorrow* → *the next day*)\n2. *She told us (that) she **had corrected our** essays **the day before**.* (prétérit → past perfect ; *your* → *our* ; *yesterday* → *the day before*)\n3. *She asked us **if / whether we were** ready.* (question fermée : *if / whether*, ordre de l'affirmative)\n4. *She asked us **where we usually revised**.* (question ouverte : pas de *do*, ordre de l'affirmative)\n5. *She told us **to close** our books.*\n6. *She told us **not to be** late.*\n\n***Say*** ne prend pas de complément de personne (*She said…*) ; ***tell*** en exige un (*She told **us**…*)."}$exo$::jsonb),
  ('c1557564-7e17-53d2-a2db-a5b58af7e4c0'::uuid, 3, 'traduction', $exo${"titre":"Le témoin de l'accident","consigne":"Corrige les erreurs, puis réécris un dialogue entier au discours indirect.","enonce":"**A.** Corrige chaque phrase et explique la règle en français.\n\n1. He said me that he was tired.\n2. She asked me where did I live.\n3. He told that he would come.\n4. She asked me are you ready.\n\n**B. Dialogue.** Un policier interroge Ryan, témoin d'un accident.\n\n> **Policeman**: Where were you at 5 pm?\n> **Ryan**: I was waiting for the bus here.\n> **Policeman**: Did you see the car?\n> **Ryan**: Yes, it was going very fast. I have never seen that car before.\n> **Policeman**: Can you describe the driver?\n> **Ryan**: He was wearing a red cap. I will help you if I can.\n> **Policeman**: Don't leave the town.\n\nRéécris tout le dialogue au **discours indirect** dans un récit au passé (*The policeman asked Ryan…*, *Ryan said…*).","bareme":[{"critere":"Les quatre erreurs corrigées et expliquées","points":6},{"critere":"Recul des temps juste dans tout le dialogue","points":6},{"critere":"Questions rapportées (if, mot interrogatif, ordre affirmatif) et ordre rapporté","points":5},{"critere":"Pronoms, repères (here → there) et say / tell corrects","points":3}],"dureeMin":18,"corrige":"**A.**\n1. *He **told me** / He **said** that he was tired.* — *say* ne prend pas de complément de personne.\n2. *She asked me where **I lived**.* — la question rapportée reprend l'**ordre de l'affirmative**, sans *did*.\n3. *He **said** that he would come.* — *tell* exige un complément de personne (*He told me…*).\n4. *She asked me **if I was** ready.* — question fermée : *if / whether*, ordre affirmatif, temps reculé.\n\n**B. Réponse attendue :**\n*The policeman asked Ryan **where he had been** at 5 pm. Ryan said (that) **he had been waiting** for the bus **there**. The policeman asked him **if / whether he had seen** the car. Ryan said that **it had been going** very fast and that **he had never seen** that car before. The policeman asked him **if he could** describe the driver. Ryan said that the driver **had been wearing** a red cap and that **he would help** him if **he could**. Finally, the policeman **told him not to leave** the town.*\n\nLe correcteur vérifie : prétérit → past perfect (*were* → *had been*, *saw* → *had seen*), present perfect → past perfect, *will* → *would*, *can* → *could* ; *here* → *there* ; questions sans inversion ; ordre avec *told him not to*. Tolérer *he was waiting* / *it was going* (prétérit en BE + -ING non reculé), fréquent à l'oral, mais valoriser le past perfect."}$exo$::jsonb),
  ('950a43bb-b76f-563d-98a4-dfb135154777'::uuid, 1, 'traduction', $exo${"titre":"Remettre les mots à leur place","consigne":"Remets les mots dans l'ordre pour écrire des phrases correctes, puis corrige les phrases fausses.","enonce":"**1. Remets les mots dans l'ordre** (n'oublie pas la majuscule et le point) :\n\na) bought / a new bike / Tom / yesterday\nb) often / to the cinema / go / we\nc) is / it / raining\nd) sang / at the party / beautifully / she / last night\n\n**2. Chaque phrase contient une erreur.** Recopie-la corrigée :\n\na) I didn't see nobody.\nb) He speaks well Spanish.\nc) Is cold today.","bareme":[{"critere":"Les quatre phrases remises dans l'ordre S-V-O, compléments dans l'ordre manière, lieu, temps, adverbe de fréquence avant le verbe","points":12},{"critere":"Trois corrections justes : anybody, speaks Spanish well, sujet It ajouté","points":8}],"dureeMin":7,"corrige":"**1.**\na) *Tom bought a new bike yesterday.* (ou *Yesterday, Tom bought a new bike.* : le complément de temps peut ouvrir la phrase)\nb) *We often go to the cinema.* — l'adverbe de fréquence **often** se place **avant** le verbe lexical.\nc) *It is raining.* — le sujet est obligatoire, même « vide ».\nd) *She sang beautifully at the party last night.* — ordre des compléments : **manière** (beautifully) → **lieu** (at the party) → **temps** (last night).\n\n**2.**\na) *I didn't see **anybody**.* — pas de double négation en anglais : *didn't* suffit.\nb) *He speaks Spanish **well**.* — on ne sépare jamais le verbe de son complément d'objet par un adverbe.\nc) ***It** is cold today.* — le sujet est obligatoire : *it* sert de sujet vide pour le temps qu'il fait."}$exo$::jsonb),
  ('950a43bb-b76f-563d-98a4-dfb135154777'::uuid, 2, 'traduction', $exo${"titre":"Le message de Maya","consigne":"Relie les phrases avec le mot demandé, puis traduis en anglais en respectant les règles du cours.","enonce":"**Situation.** Maya, élève de 3e, prépare un message pour sa correspondante de Leeds, Olivia.\n\n**1. Relie chaque paire de phrases** en une seule phrase avec le mot entre parenthèses :\n\na) I like London. I prefer Edinburgh. (but)\nb) I stayed at home. I was ill. (because)\nc) This is the book. I told you about it. (that)\nd) I'm tired. I'm going to bed. (so)\n\n**2. Traduis en anglais :**\n\na) Je t'appellerai quand j'arriverai à Leeds.\nb) Je pense que tu as raison.\nc) Si tu viens en France, nous irons à Paris.\nd) Je fais souvent mes devoirs le soir.","bareme":[{"critere":"Quatre phrases reliées correctement avec but, because, that et so, sans répétition inutile","points":8},{"critere":"Présent après when et if pour parler de l'avenir (when I arrive, if you come)","points":6},{"critere":"Complétive avec that (ou sans), adverbe often avant le verbe, ordre S-V-O respecté","points":6}],"dureeMin":11,"corrige":"**1.**\na) *I like London **but** I prefer Edinburgh.* — coordination : deux propositions de même rang.\nb) *I stayed at home **because** I was ill.* — subordonnée de cause.\nc) *This is the book **that** I told you about.* — subordonnée relative ; le pronom *it* disparaît, la préposition *about* reste à la fin.\nd) *I'm tired **so** I'm going to bed.* — coordination de conséquence.\n\n**2.**\na) *I'll call you **when I arrive** in Leeds.* — après *when*, on met le **présent**, jamais *will*.\nb) *I think (**that**) you are right.* — complétive, *that* souvent omis.\nc) ***If you come** to France, we'll go to Paris.* — présent après *if* pour l'avenir, *will* dans la principale.\nd) *I **often do** my homework in the evening.* — adverbe de fréquence avant le verbe lexical ; complément de temps en fin de phrase."}$exo$::jsonb),
  ('950a43bb-b76f-563d-98a4-dfb135154777'::uuid, 3, 'traduction', $exo${"titre":"Le blog de Hugo à corriger","consigne":"Corrige le texte en justifiant chaque correction, puis rédige un court paragraphe en anglais qui respecte les consignes.","enonce":"**Document.** Hugo a écrit ce paragraphe pour le blog de son collège. Il contient **six erreurs** étudiées dans le chapitre.\n\n> Last summer I visited with my family Scotland. Was very cold but we loved it. We went often to the beach. I didn't meet nobody from France. I will send you photos when I will get the pictures from my dad. I speak now well English!\n\n1. Recopie le paragraphe corrigé.\n2. Pour **quatre** erreurs de ton choix, nomme la règle du cours qui n'était pas respectée (une phrase par règle).\n3. Rédige un paragraphe de 50 mots environ sur tes prochaines vacances. Tu dois employer : une coordination (**and**, **but** ou **so**), une subordonnée de cause (**because**), une subordonnée de temps ou de condition au **présent** pour parler de l'avenir (**when** ou **if**), un adverbe de fréquence bien placé et une phrase avec les compléments dans l'ordre manière → lieu → temps.","bareme":[{"critere":"Les six erreurs corrigées : ordre S-V-O, sujet It, place de often, double négation, présent après when, place de well","points":6},{"critere":"Quatre règles nommées avec justesse","points":4},{"critere":"Paragraphe : coordination, because, when ou if suivi du présent employés correctement","points":6},{"critere":"Paragraphe : adverbe de fréquence et ordre des compléments respectés, texte compréhensible","points":4}],"dureeMin":18,"corrige":"**1.** *Last summer I visited **Scotland with my family**. **It was** very cold but we loved it. We **often went** to the beach. I didn't meet **anybody** from France. I will send you photos when I **get** the pictures from my dad. I speak English **well** now!*\n\n**2.** Règles attendues (quatre parmi) :\n- Ordre **S-V-O** : le complément d'objet (*Scotland*) suit directement le verbe, avant les autres compléments.\n- Le **sujet est obligatoire** : *It was very cold*.\n- L'adverbe de **fréquence** se place **avant** le verbe lexical : *We often went*.\n- Pas de **double négation** : *didn't meet anybody*.\n- Après **when** (et *if*), le **présent** pour parler de l'avenir : *when I get*.\n- Jamais d'adverbe entre le verbe et son objet : *speak English well*.\n\n**3.** Exemple de production :\n*Next summer I'm going to Spain with my cousins because they live in Madrid. We usually swim every day. If it is too hot, we will stay at home. We will play football happily in the park every evening, and we will visit the Prado so I can see Goya's paintings.*\nOn vérifie : *and / so* (coordination), *because* (cause), *If it is* (présent après *if*), *usually* avant le verbe, *happily* (manière) → *in the park* (lieu) → *every evening* (temps)."}$exo$::jsonb),
  ('a75442fe-af8e-5d13-b77d-f97abe6c463d'::uuid, 1, 'traduction', $exo${"titre":"Le bon pronom","consigne":"Complète chaque phrase avec le pronom qui convient, puis traduis les phrases demandées.","enonce":"**1. Complète** avec le pronom qui convient (sujet, complément ou réfléchi) :\n\na) I know Emma. I see … every day at school.\nb) My parents are nice. I often help … .\nc) Tom cut … with a knife.\nd) Can you come with … ? We are going to the park.\ne) … is five o'clock.\nf) We did the cake … — nobody helped us.\n\n**2. Traduis en anglais :**\n\na) Je me lève à sept heures.\nb) Elle vit toute seule.","bareme":[{"critere":"Six pronoms justes : her, them, himself, us, It, ourselves","points":12},{"critere":"Traductions justes : I get up sans pronom réfléchi, by herself","points":8}],"dureeMin":7,"corrige":"**1.**\na) I see **her** — pronom complément de *she*, après le verbe.\nb) I often help **them** — complément de *they*.\nc) Tom cut **himself** — l'action revient sur le sujet : pronom réfléchi.\nd) come with **us** — complément après une préposition.\ne) **It** is five o'clock — *it*, sujet vide pour l'heure.\nf) We did the cake **ourselves** — réfléchi d'insistance.\n\n**2.**\na) *I get up at seven.* — *se lever* n'est **pas** pronominal en anglais : jamais « I get up myself ».\nb) *She lives by herself.* — **by + réfléchi** = tout seul."}$exo$::jsonb),
  ('a75442fe-af8e-5d13-b77d-f97abe6c463d'::uuid, 2, 'traduction', $exo${"titre":"Le texte qui se répète","consigne":"Réécris le texte en remplaçant les répétitions par les pronoms qui conviennent, puis réponds aux questions.","enonce":"**Situation.** Nadia raconte sa journée, mais elle répète tout.\n\n> Nadia has a brother, Sam. Nadia and Sam go to school together. Sam's bag is blue and Nadia's bag is red. At lunch, Nadia gives Sam a sandwich. In the afternoon, Sam hurts Sam during PE. The teacher helps Sam. In the evening, Nadia and Sam's parents ask Nadia and Sam about the day.\n\n1. Réécris le texte en remplaçant les noms répétés par le mot qui convient : pronom sujet, complément, adjectif possessif ou réfléchi (*She, he, they, him, himself, her, his, their, them…*).\n2. Traduis : « Je préfère le rouge » (en parlant d'un sac), en évitant de répéter le mot *bag*.\n3. Complète et explique : *Someone left a message — … said … would call back.* Quel pronom emploie-t-on quand on ne connaît pas le genre de la personne ?","bareme":[{"critere":"Pronoms sujets et compléments justes (they, he, him, them)","points":7},{"critere":"Adjectifs possessifs et réfléchi justes (his, her, their, himself)","points":5},{"critere":"Traduction avec one : I prefer the red one","points":4},{"critere":"They singulier neutre employé et expliqué","points":4}],"dureeMin":11,"corrige":"**1.** Réécriture attendue :\n*Nadia has a brother, Sam. **They** go to school together. **His** bag is blue and **her** bag is red. At lunch, **she** gives **him** a sandwich. In the afternoon, **he** hurts **himself** during PE. The teacher helps **him**. In the evening, **their** parents ask **them** about the day.*\n- *They* : sujet pluriel ; *him*, *them* : compléments après le verbe.\n- *his* (le sac de Sam), *her* (le sac de Nadia), *their* (leurs parents) : adjectifs possessifs, qui s'accordent avec le **possesseur**.\n- *himself* : l'action revient sur le sujet.\n\n**2.** *I prefer the red **one**.* — *one* évite de répéter un nom déjà cité.\n\n**3.** *Someone left a message — **they** said **they** would call back.* On emploie **they**, pronom singulier neutre, quand le genre est inconnu ou non pertinent ; c'est une tournure standard, y compris à l'écrit."}$exo$::jsonb),
  ('a75442fe-af8e-5d13-b77d-f97abe6c463d'::uuid, 3, 'traduction', $exo${"titre":"Le carnet de colonie","consigne":"Traduis le texte en anglais, justifie trois choix de pronoms, puis rédige un court texte.","enonce":"**Document.** Extrait du carnet de Léo pendant une colonie de vacances :\n\n> « Le matin, je me lève tôt et je me lave vite. Mon ami Jules s'est coupé hier ; l'animatrice l'a soigné. Elle nous a dit : \"Faites-le vous-mêmes, sans moi !\" Il faut une heure pour aller au lac. Quelqu'un a perdu son sac : ils l'ont cherché partout. »\n\n1. Traduis le texte en anglais (le vouvoiement « vous-mêmes » s'adresse au groupe).\n2. Justifie en une phrase chacun de ces choix : la traduction de « je me lève », celle de « s'est coupé », celle de « Il faut une heure ».\n3. Rédige 5 phrases en anglais (45 mots environ) sur un camarade de ta classe dont tu tais le prénom. Tu dois employer au moins : un pronom complément après une préposition, un adjectif possessif, un pronom possessif (*mine, yours…*), un réfléchi et *they* au sens singulier neutre.","bareme":[{"critere":"Traduction : pronoms sujets et compléments justes (him, us, it, me)","points":5},{"critere":"Traduction : get up et wash sans réfléchi, cut himself, yourselves, It takes an hour","points":5},{"critere":"Trois justifications exactes appuyées sur les règles du cours","points":4},{"critere":"Production : les cinq formes demandées employées correctement","points":6}],"dureeMin":18,"corrige":"**1.** *In the morning, I get up early and I wash quickly. My friend Jules cut **himself** yesterday; the leader looked after **him**. She told **us**: \"Do **it yourselves**, without **me**!\" **It takes an hour** to go to the lake. Someone lost **their** bag: they looked for **it** everywhere.*\n(*their bag* : possessif singulier neutre, puisque le genre de « quelqu'un » est inconnu ; *his or her bag* est accepté.)\n\n**2.**\n- « Je me lève » → *I get up* : certains verbes pronominaux français **ne le sont pas** en anglais (*get up, wash, feel*), pas de réfléchi.\n- « s'est coupé » → *cut himself* : l'action revient sur le sujet, on emploie le **réfléchi**.\n- « Il faut une heure » → *It takes an hour* : **it** sert de sujet vide (temps, heure, durée).\n\n**3.** Exemple de production :\n*This person sits next to me in class. Their favourite subject is maths. My pencil case is blue and theirs is green. They always do their homework by themselves. I often go to the library with them.*\nOn vérifie : *next to me / with them* (complément après préposition), *their* (possessif), *theirs* (pronom possessif), *by themselves* (réfléchi), *they* singulier neutre. Toute production qui emploie correctement les cinq formes est acceptée."}$exo$::jsonb),
  ('a87e8d79-456a-56fe-9c4c-29ce2316a257'::uuid, 1, 'traduction', $exo${"titre":"Pluriels et indénombrables","consigne":"Réponds aux deux exercices. Écris chaque mot ou chaque phrase en entier.","enonce":"**1. Donne le pluriel de chaque nom.**\n\nchild · city · knife · tooth · box · boy · sheep · woman\n\n**2. Chaque phrase contient une faute. Recopie-la corrigée.**\n\na. *I need an advice.*\nb. *The news are good today.*\nc. *We bought two furnitures.*","bareme":[{"critere":"Les huit pluriels sont justes (1,5 point par pluriel)","points":12},{"critere":"Les trois phrases sont corrigées : advice, news et furniture traités comme indénombrables","points":8}],"dureeMin":7,"corrige":"**1. Pluriels**\n- child → **children** (irrégulier)\n- city → **cities** (consonne + y → -ies)\n- knife → **knives** (-fe → -ves)\n- tooth → **teeth** (irrégulier)\n- box → **boxes** (-x → -es)\n- boy → **boys** (voyelle + y : simple -s)\n- sheep → **sheep** (inchangé)\n- woman → **women** (irrégulier)\n\n**2. Corrections**\na. *I need some advice.* ou *I need a piece of advice.* — advice est indénombrable : ni a, ni -s.\nb. *The news is good today.* — news est indénombrable : verbe au singulier malgré le -s.\nc. *We bought two pieces of furniture.* — furniture est indénombrable : on le compte avec le partitif *a piece of*."}$exo$::jsonb),
  ('a87e8d79-456a-56fe-9c4c-29ce2316a257'::uuid, 2, 'traduction', $exo${"titre":"La chambre des filles","consigne":"Traduis les cinq phrases en anglais (thème). Fais attention aux pluriels, aux indénombrables et au génitif.","enonce":"**Thème : traduis en anglais.**\n\n1. Les enfants de ma sœur ont deux souris.\n2. Il y a trois meubles dans la chambre des filles.\n3. Peux-tu me donner un conseil ?\n4. Les informations sont mauvaises aujourd'hui.\n5. Les pieds de l'homme sont froids.\n\n*Aide : mouse = souris ; cold = froid ; bad = mauvais.*","bareme":[{"critere":"Pluriels irréguliers justes (children, mice, feet)","points":6},{"critere":"Indénombrables traités correctement (furniture, advice, news avec verbe au singulier)","points":7},{"critere":"Génitif bien formé ('s au singulier, apostrophe seule après un pluriel en -s)","points":5},{"critere":"Orthographe et construction des phrases","points":2}],"dureeMin":10,"corrige":"**Traduction modèle**\n1. *My sister's children have two mice.* — génitif 's (possesseur singulier), children et mice irréguliers.\n2. *There are three pieces of furniture in the girls' room.* — furniture est indénombrable : on compte avec *pieces of* ; « des filles » : pluriel en -s → apostrophe seule, *the girls' room*.\n3. *Can you give me a piece of advice?* (ou *some advice*) — jamais *an advice*.\n4. *The news is bad today.* — news est indénombrable, verbe au **singulier** (*is*, pas *are*). *The information is bad* est accepté seulement si le sens « renseignements » est visé ; « les informations » (journal) = *the news*.\n5. *The man's feet are cold.* — possesseur animé au singulier → 's ; foot → **feet** ; verbe *are* car feet est pluriel.\n\nFautes à pénaliser : *childs*, *mouses*, *furnitures*, *an advice*, *the news are*, *the girl's room* (une seule fille), *the feet of the man*."}$exo$::jsonb),
  ('a87e8d79-456a-56fe-9c4c-29ce2316a257'::uuid, 3, 'traduction', $exo${"titre":"Le courriel de Mr Brown","consigne":"Lis le texte, puis réponds aux trois questions. Justifie chaque correction par la règle du cours.","enonce":"> Last week, my two childs went to the shop with my wife. They wanted to buy some furnitures for their bedroom. The shop assistant gave us a useful advice: buy two beds and a desk. The news were good: everything was cheap! Now the boys room is beautiful, and the three sheeps on the wallpaper make everybody laugh.\n\n1. Le texte contient **six fautes** sur les noms. Relève-les et corrige-les, en justifiant chaque correction en une ligne.\n2. Explique en deux ou trois phrases pourquoi un élève français se trompe souvent avec *advice*, *information* et *news*.\n3. Écris trois phrases en anglais qui comptent un nom indénombrable avec un partitif différent à chaque fois.","bareme":[{"critere":"Six fautes relevées et corrigées (childs, furnitures, a useful advice, news were, boys room, sheeps)","points":8},{"critere":"Chaque correction justifiée par la bonne règle (pluriel irrégulier, indénombrable, génitif)","points":5},{"critere":"Explication du piège des indénombrables par rapport au français","points":3},{"critere":"Trois phrases correctes avec trois partitifs différents","points":4}],"dureeMin":16,"corrige":"**1. Les six fautes**\n- *childs* → **children** : pluriel irrégulier.\n- *furnitures* → **furniture** : indénombrable, jamais de -s (*some furniture*).\n- *a useful advice* → **a useful piece of advice** ou **some useful advice** : indénombrable, pas d'article a.\n- *The news were* → **The news was** : news est indénombrable, verbe au singulier.\n- *the boys room* → **the boys' room** : génitif ; possesseur pluriel en -s → apostrophe seule.\n- *three sheeps* → **three sheep** : sheep est invariable.\n\n**2. Le piège**\nEn français, on dit « des informations », « des conseils », « les nouvelles », « des meubles » : ces noms se mettent au pluriel. En anglais, *information*, *advice*, *news* et *furniture* sont **indénombrables** : pas de pluriel, pas de *a / an*, verbe au singulier. Ce sont des faux amis grammaticaux.\n\n**3. Exemples attendus** (toute phrase juste est acceptée)\n- *Can I have a glass of water, please?*\n- *She gave me a piece of information.*\n- *We need two pieces of furniture.*\nLe partitif porte le pluriel (*two pieces*), jamais le nom indénombrable."}$exo$::jsonb),
  ('e0e2f5da-8883-5dbf-b8a3-7b614d010424'::uuid, 1, 'traduction', $exo${"titre":"A, an, the ou rien ?","consigne":"Complète chaque blanc avec a, an, the ou Ø (pas d'article), puis réponds à la question 2.","enonce":"**1. Complète.**\n\n1. She is ___ nurse.\n2. I eat ___ apple every day.\n3. ___ sun is very hot today.\n4. I like ___ cats.\n5. We waited for ___ hour.\n6. He plays ___ guitar.\n7. They play ___ tennis twice ___ week.\n8. ___ Thames flows through London.\n\n**2.** Explique pourquoi on dit *an hour* mais *a university*.","bareme":[{"critere":"Les neuf blancs correctement complétés","points":14},{"critere":"Explication : c'est le son, pas la lettre, qui décide entre a et an","points":6}],"dureeMin":7,"corrige":"**1. Réponses**\n1. She is **a** nurse. — le métier prend a.\n2. I eat **an** apple every day. — son de voyelle.\n3. **The** sun is very hot today. — objet unique.\n4. I like **Ø** cats. — pluriel au sens général.\n5. We waited for **an** hour. — le h ne se prononce pas.\n6. He plays **the** guitar. — un instrument prend the.\n7. They play **Ø** tennis twice **a** week. — pas d'article devant un sport ; a pour la fréquence.\n8. **The** Thames flows through London. — nom de fleuve.\n\n**2. Explication**\nLe choix entre a et an dépend du **son** qui suit, pas de la lettre. *Hour* commence par la lettre h, mais le h est muet : on entend un son de voyelle, donc **an**. *University* commence par la lettre u, mais on prononce [ju] : c'est un son de consonne, donc **a**."}$exo$::jsonb),
  ('e0e2f5da-8883-5dbf-b8a3-7b614d010424'::uuid, 2, 'traduction', $exo${"titre":"La famille de Nora","consigne":"Traduis ce petit texte en anglais (thème). Attention aux articles.","enonce":"**Thème : traduis en anglais.**\n\n> Ma mère est médecin. Elle va à l'hôpital trois fois par semaine. Après le dîner, elle joue du piano. Mon frère, lui, préfère le football. Il aime la musique et les chiens. L'an prochain, il ira à l'université, en Écosse.\n\n*Aide : next year = l'an prochain ; Scotland = l'Écosse ; he will go = il ira.*","bareme":[{"critere":"Métier et fréquence avec a (a doctor, three times a week)","points":6},{"critere":"Article zéro bien employé (repas, sport, sens général, pays)","points":6},{"critere":"The devant l'instrument, a devant university","points":5},{"critere":"Sens général et correction de la langue","points":3}],"dureeMin":10,"corrige":"**Traduction modèle**\n> *My mother is a doctor. She goes to the hospital three times a week. After dinner, she plays the piano. My brother prefers football. He likes music and dogs. Next year, he will go to university, in Scotland.*\n\n**Points attendus**\n- *a doctor* : le métier prend l'article indéfini (jamais *She is doctor*).\n- *three times a week* : a pour la fréquence.\n- *After dinner* : pas d'article devant un repas.\n- *plays the piano* : un instrument prend the ; *prefers football* : un sport n'en prend pas.\n- *music*, *dogs* : indénombrable et pluriel au sens général → article zéro.\n- *go to university* : pour étudier, sans article (comme *go to school*) ; *a university* serait correct avec a (son [ju]), jamais *an university*.\n- *Scotland* : nom de pays au singulier, sans article.\n- *to the hospital* : ici le bâtiment où elle travaille, the accepté."}$exo$::jsonb),
  ('e0e2f5da-8883-5dbf-b8a3-7b614d010424'::uuid, 3, 'traduction', $exo${"titre":"Voyage en Europe : choisir et justifier l'article","consigne":"Traduis les cinq phrases en anglais, puis justifie trois de tes choix d'articles à la question 2.","enonce":"**1. Thème : traduis en anglais.**\n\n1. L'eau est essentielle à la vie.\n2. J'ai acheté un parapluie et un uniforme. Le parapluie est bleu.\n3. Les Alpes et le Rhin sont en Europe, comme les Pays-Bas.\n4. Mon frère va à l'école à pied ; ce matin, mon père est allé à l'école pour parler au directeur.\n5. C'est la meilleure élève de la classe.\n\n*Aide : umbrella = parapluie ; uniform = uniforme ; the Rhine = le Rhin ; headteacher = directeur ; on foot = à pied.*\n\n**2.** Justifie en une phrase chacun : a) *an umbrella / a uniform* ; b) *the Alps* mais *Europe* ; c) *go to school* / *go to the school*.","bareme":[{"critere":"Article zéro au sens général et devant continent (water, life, Europe)","points":4},{"critere":"A / an selon le son et reprise par the (an umbrella, a uniform, the umbrella)","points":4},{"critere":"The devant chaînes, fleuves, pays au pluriel et superlatif","points":4},{"critere":"Distinction school / the school correctement traduite","points":3},{"critere":"Trois justifications exactes","points":5}],"dureeMin":16,"corrige":"**1. Traduction modèle**\n1. *Water is essential to life.*\n2. *I bought an umbrella and a uniform. The umbrella is blue.*\n3. *The Alps and the Rhine are in Europe, like the Netherlands.*\n4. *My brother goes to school on foot; this morning, my father went to the school to talk to the headteacher.*\n5. *She is the best pupil in the class.* (*student* accepté)\n\n**2. Justifications**\na) *Umbrella* commence par un **son** de voyelle → *an* ; *uniform* se prononce [ju] → son de consonne → *a*. Ensuite, *the umbrella* : il est **déjà mentionné**.\nb) On met *the* devant les chaînes de montagnes, les fleuves et les pays au pluriel (*the Alps*, *the Rhine*, *the Netherlands*) ; un continent, comme un pays au singulier, n'a pas d'article (*Europe*).\nc) *go to school* (sans article) = aller en classe, pour **étudier** ; *go to the school* = aller au **bâtiment** précis sans y étudier, comme le père qui va parler au directeur.\n\nAutres points : *Water*, *life* sans article (sens général) ; *the best* : superlatif avec the."}$exo$::jsonb),
  ('74fdc744-c0cf-55c9-a45b-ad63c136cd18'::uuid, 1, 'traduction', $exo${"titre":"This, that, these, those","consigne":"Complète chaque phrase avec this, that, these ou those en t'aidant des indices, puis corrige la phrase fautive.","enonce":"**1. Complète.**\n\n1. ___ book in my hand is great.\n2. Look at ___ birds over there in the sky!\n3. ___ shoes I'm wearing are new.\n4. Can you see ___ house over there? It's old.\n5. I'm very busy ___ week.\n6. I remember ___ summer in 2015: it was so hot!\n\n**2. Corrige :** *I don't like thoses shoes over there.*","bareme":[{"critere":"Six démonstratifs justes selon le nombre et la distance","points":14},{"critere":"Correction de thoses en those, avec la raison","points":6}],"dureeMin":6,"corrige":"**1. Réponses**\n1. **This** book — singulier, proche (dans ma main).\n2. **those** birds — pluriel, éloigné (over there).\n3. **These** shoes — pluriel, proche (je les porte).\n4. **that** house — singulier, éloigné.\n5. **this** week — distance dans le temps : le présent.\n6. **that** summer — passé révolu.\n\n**2. Correction**\n*I don't like **those** shoes over there.* — *those* est déjà le pluriel de *that* : les démonstratifs ne prennent jamais de -s supplémentaire, « thoses » n'existe pas."}$exo$::jsonb),
  ('74fdc744-c0cf-55c9-a45b-ad63c136cd18'::uuid, 2, 'traduction', $exo${"titre":"Au magasin de chaussures","consigne":"Traduis ce dialogue en anglais (thème). Fais attention au nombre et à la distance.","enonce":"**Thème : traduis en anglais.**\n\n> **Chloé** (au téléphone) : Allô, c'est Chloé. Je suis au magasin avec ma cousine.\n> **Chloé** (à la vendeuse) : Voici ma cousine, Inès. Ces chaussures-ci sont trop petites. Je préfère celles-là, là-bas.\n> **Inès** : Et ce sac-là, sur l'étagère ? Il est joli !\n> **Chloé** : Cet été-là, en Écosse, j'avais le même.\n\n*Aide : shelf = étagère ; the same one = le même ; I had = j'avais.*","bareme":[{"critere":"This au téléphone et pour présenter quelqu'un","points":5},{"critere":"These / those justes pour les chaussures proches et éloignées","points":6},{"critere":"That pour l'objet éloigné et pour le passé (that bag, that summer)","points":5},{"critere":"Adjectif et pronom démonstratifs bien distingués, langue correcte","points":4}],"dureeMin":10,"corrige":"**Traduction modèle**\n> **Chloé:** *Hello, this is Chloé (speaking). I'm at the shop with my cousin.*\n> **Chloé:** *This is my cousin, Inès. These shoes are too small. I prefer those (over there).*\n> **Inès:** *And that bag on the shelf? It's nice!* (*pretty* accepté)\n> **Chloé:** *That summer, in Scotland, I had the same one.*\n\n**Points attendus**\n- *this is Chloé* : au téléphone, l'anglais dit *this*, pas *it is* ni *here is*.\n- *This is my cousin* : pour présenter quelqu'un.\n- *These shoes* (adjectif, pluriel, proche) / *those* (pronom, pluriel, éloigné, employé seul).\n- *that bag* : singulier, éloigné.\n- *That summer* : that pour le passé révolu.\n- Accord en nombre avec le nom : *these shoes*, jamais *this shoes*."}$exo$::jsonb),
  ('74fdc744-c0cf-55c9-a45b-ad63c136cd18'::uuid, 3, 'traduction', $exo${"titre":"Le vieil album de photos","consigne":"Lis le texte, complète-le, puis réponds aux questions 2 et 3 en justifiant.","enonce":"> Grandpa opens an old photo album. « Look! (1) ___ is me in 1970. And (2) ___ people behind me are my parents. (3) ___ were the days! » Then he takes a new photo from his pocket: « And (4) ___ is you, (5) ___ morning, with your friends. (6) ___ children are always laughing! »\n\n1. Complète les six blancs avec this, that, these ou those.\n2. Pour les blancs 1, 2 et 6, dis s'il s'agit d'un **adjectif** ou d'un **pronom** démonstratif, et justifie.\n3. Explique pourquoi le grand-père emploie *those* au blanc 3, alors que les photos sont dans ses mains.","bareme":[{"critere":"Six blancs complétés correctement","points":7},{"critere":"Nature adjectif / pronom juste et justifiée pour les trois blancs","points":6},{"critere":"Explication de la distance dans le temps (those pour un passé lointain)","points":5},{"critere":"Qualité de la rédaction","points":2}],"dureeMin":15,"corrige":"**1. Réponses attendues**\n(1) **This** is me in 1970 — la photo est dans sa main (*That* accepté si l'élève justifie par l'éloignement dans le temps).\n(2) **those** people — pluriel, personnes d'une époque lointaine (*these* accepté pour la proximité physique de la photo).\n(3) **Those** were the days! — expression figée, le passé lointain.\n(4) **this** is you — la photo récente qu'il tient.\n(5) **this** morning — le présent.\n(6) **These** children — pluriel, proche et présent.\n\n**2. Nature**\n- (1) **pronom** : *this* est employé seul, sans nom derrière.\n- (2) **adjectif** : il est suivi du nom *people*.\n- (6) **adjectif** : il est suivi du nom *children*, et s'accorde avec lui au pluriel (*these*, pas *this*).\n\n**3. La distance dans le temps**\nLa distance peut être dans le **temps**, pas seulement dans l'espace. *That / those* renvoient à ce qui est passé ou s'éloigne : le grand-père parle d'une époque révolue, les années 1970, d'où *those* même si l'album est dans ses mains. *This* sert au présent (*this morning*)."}$exo$::jsonb),
  ('7ae64b9c-f15f-580e-b6c8-46f6d313763e'::uuid, 1, 'traduction', $exo${"titre":"Le génitif et les possessifs","consigne":"Réécris chaque groupe avec le génitif quand c'est possible, puis complète avec his, her ou its.","enonce":"**1. Réécris avec le génitif ’s (ou garde of si le génitif ne convient pas).**\n\na. the bike of my brother\nb. the room of the girls\nc. the toys of the children\nd. the roof of the house\ne. the newspaper of today\n\n**2. Complète avec his, her ou its.**\n\na. Kate loves ___ brother.\nb. Paul phones ___ sister every day.\nc. The dog is playing with ___ ball.","bareme":[{"critere":"Cinq groupes justes (génitif bien formé, of gardé pour la maison)","points":12},{"critere":"Trois possessifs accordés avec le possesseur","points":8}],"dureeMin":7,"corrige":"**1. Réécriture**\na. **my brother's bike** — possesseur singulier + 's.\nb. **the girls' room** — pluriel en -s : apostrophe seule.\nc. **the children's toys** — pluriel irrégulier : 's.\nd. **the roof of the house** — objet inanimé : on garde *of*.\ne. **today's newspaper** — expression de temps : génitif possible.\n\nL'ordre est l'inverse du français : possesseur + 's + objet possédé.\n\n**2. Possessifs**\na. Kate loves **her** brother. — le possesseur est Kate (féminin).\nb. Paul phones **his** sister every day. — le possesseur est Paul (masculin), peu importe que la sœur soit féminine.\nc. The dog is playing with **its** ball. — animal / chose : *its*, sans apostrophe."}$exo$::jsonb),
  ('7ae64b9c-f15f-580e-b6c8-46f6d313763e'::uuid, 2, 'traduction', $exo${"titre":"À qui est ce sac ?","consigne":"Traduis le dialogue et les phrases en anglais (thème).","enonce":"**Thème : traduis en anglais.**\n\n> **Maël** : À qui est ce sac ?\n> **Lisa** : C'est celui de Kate. Le mien est rouge, et le sien est vert.\n> **Maël** : Et ce téléphone, c'est le tien ?\n> **Lisa** : Non, c'est celui de mes parents.\n\n**Puis :**\n1. Paul et sa sœur vont au cinéma.\n2. La fin du film est triste.\n3. Le chat mange dans son bol.\n\n*Aide : bowl = bol ; sad = triste.*","bareme":[{"critere":"Whose et génitif justes (Kate's, my parents')","points":6},{"critere":"Pronoms possessifs employés seuls (mine, hers, yours)","points":6},{"critere":"Adjectifs possessifs accordés au possesseur (his, its) et of pour l'objet","points":5},{"critere":"Construction des phrases et orthographe","points":3}],"dureeMin":11,"corrige":"**Traduction modèle**\n> **Maël:** *Whose bag is this?*\n> **Lisa:** *It's Kate's. Mine is red, and hers is green.*\n> **Maël:** *And this phone, is it yours?*\n> **Lisa:** *No, it's my parents'.*\n\n1. *Paul and his sister are going to the cinema.* (*go to the cinema* accepté)\n2. *The end of the film is sad.*\n3. *The cat is eating from its bowl.* (*eats from its bowl* accepté)\n\n**Points attendus**\n- *Whose* pour demander le possesseur.\n- *Kate's* : le génitif s'emploie seul (« celui de Kate »), sans répéter *bag*.\n- *my parents'* : pluriel en -s → apostrophe seule.\n- *Mine*, *hers*, *yours* : pronoms, jamais suivis d'un nom (pas *mine bag*).\n- *his sister* : accord avec Paul, le possesseur.\n- *the end of the film* : notion abstraite, of.\n- *its* sans apostrophe (*it's* = it is)."}$exo$::jsonb),
  ('7ae64b9c-f15f-580e-b6c8-46f6d313763e'::uuid, 3, 'traduction', $exo${"titre":"Le message de Jade","consigne":"Lis le message, corrige les fautes en justifiant, puis écris toi-même un court paragraphe.","enonce":"> Hi! Yesterday I went to my cousins house. My cousin Tom showed me he's new bike. The bike of Tom is amazing! Then his sister Emma showed me her room. It's walls are pink. She said: « This computer is mine computer. » In the evening, we read the childrens' books of my aunt.\n\n1. Le message contient **six fautes** sur la possession. Relève-les, corrige-les et justifie chaque correction.\n2. En trois ou quatre phrases en anglais, présente les affaires d'un ami et les tiennes, en employant au moins un génitif, un adjectif possessif, un pronom possessif et *whose*.","bareme":[{"critere":"Six fautes relevées et corrigées","points":7},{"critere":"Justifications exactes (génitif, its / it's, pronom sans nom, accord au possesseur)","points":5},{"critere":"Paragraphe avec les quatre outils demandés, bien employés","points":6},{"critere":"Correction de la langue dans le paragraphe","points":2}],"dureeMin":16,"corrige":"**1. Les six fautes**\n- *my cousins house* → **my cousin's house** (un seul cousin) : génitif 's.\n- *he's new bike* → **his new bike** : *he's* = he is / he has ; le possessif est *his*.\n- *The bike of Tom* → **Tom's bike** : possesseur animé → génitif, pas *of*.\n- *It's walls* → **Its walls** : possessif sans apostrophe ; *it's* = it is.\n- *mine computer* → **This computer is mine.** : un pronom possessif ne se fait jamais suivre d'un nom (ou *This is my computer.*).\n- *the childrens' books of my aunt* → **my aunt's children's books** : children est un pluriel irrégulier → *children's* ; et l'aunt est animée → génitif (*my aunt's*). *the children's books* seul est accepté si l'élève explique la faute sur l'apostrophe.\n\n**2. Exemple de paragraphe**\n> *This is my friend Hugo's bag. His bag is blue, mine is black. Whose pencil case is this? It's his, not mine. Our teacher's desk is next to the window.*\n\nOn vérifie : un génitif (*Hugo's*, *teacher's*), un adjectif possessif (*his*, *our*), un pronom possessif (*mine*, *his*), une question en *whose*."}$exo$::jsonb),
  ('ee9faea6-63b0-58c0-a2a8-4c00cd3b1c53'::uuid, 1, 'traduction', $exo${"titre":"Some, any, much, many","consigne":"Complète chaque phrase avec le quantifieur qui convient, puis réponds à la question 2.","enonce":"**1. Complète avec some, any, much ou many.**\n\n1. I have ___ money in my pocket.\n2. We don't have ___ bread.\n3. How ___ books have you got?\n4. How ___ water do you drink a day?\n5. Would you like ___ tea?\n6. Is there ___ milk in the fridge?\n\n**2.** Explique la différence de sens entre *I have a few friends* et *I have few friends*.","bareme":[{"critere":"Six quantifieurs justes","points":12},{"critere":"Différence a few (assez, rassurant) / few (trop peu) expliquée","points":8}],"dureeMin":7,"corrige":"**1. Réponses**\n1. **some** money — affirmative.\n2. **any** bread — négative.\n3. How **many** books — dénombrable pluriel.\n4. How **much** water — indénombrable.\n5. Would you like **some** tea? — offre polie : *some* même dans une question.\n6. Is there **any** milk — interrogative.\n\n**2. A few / few**\n*I have a few friends* : j'ai quelques amis, un nombre **suffisant** — le sens est positif, il rassure.\n*I have few friends* : j'ai **peu** d'amis, trop peu — le sens est négatif, il inquiète. L'article *a* change le sens."}$exo$::jsonb),
  ('ee9faea6-63b0-58c0-a2a8-4c00cd3b1c53'::uuid, 2, 'traduction', $exo${"titre":"La fête de Yanis","consigne":"Complète le dialogue, puis justifie trois de tes choix.","enonce":"> **Yanis**: I'm organising a party. Have we got (1) ___ crisps?\n> **Mum**: No, we haven't got (2) ___ crisps, but we've got (3) ___ lemonade.\n> **Yanis**: How (4) ___ bottles?\n> **Mum**: Only two. That's not (5) ___ for twenty people!\n> **Yanis**: And how (6) ___ cake is left?\n> **Mum**: Just (7) ___ cake, but we've got (8) ___ biscuits.\n\n*Mots possibles : any, some, many, much, enough, a little, a lot of.*\n\n1. Complète les huit blancs.\n2. Justifie tes choix pour les blancs 2, 4 et 6.","bareme":[{"critere":"Huit blancs corrects","points":10},{"critere":"Justifications : forme de la phrase (négative / interrogative)","points":4},{"critere":"Justifications : dénombrable / indénombrable (many / much)","points":4},{"critere":"Clarté des explications","points":2}],"dureeMin":10,"corrige":"**1. Réponses**\n(1) **any** — question.\n(2) **any** — négative.\n(3) **some** — affirmative.\n(4) How **many** bottles — dénombrable pluriel.\n(5) not **enough** — pas assez.\n(6) How **much** cake — *cake* est ici indénombrable (de la matière).\n(7) **a little** cake — un peu de, indénombrable.\n(8) **a lot of** biscuits (ou *some*) — affirmative, dénombrable.\n\n**2. Justifications**\n- Blanc 2 : la phrase est **négative** (*haven't got*) → *any*.\n- Blanc 4 : *bottles* est **dénombrable** pluriel → *how many*.\n- Blanc 6 : *cake* au singulier, sans article, désigne une quantité de gâteau : **indénombrable** → *how much*.\n\nAccepter (8) *some* ; refuser *much biscuits* ou *many cake*."}$exo$::jsonb),
  ('ee9faea6-63b0-58c0-a2a8-4c00cd3b1c53'::uuid, 3, 'traduction', $exo${"titre":"Le camp de vacances","consigne":"Traduis les six phrases en anglais, puis réponds à la question 2 en justifiant.","enonce":"**1. Thème : traduis en anglais.**\n\n1. Il n'y a pas de lait dans le frigo.\n2. Tu veux du jus d'orange ?\n3. Prends n'importe quel livre.\n4. Nous avons trop de devoirs et pas assez de temps.\n5. Peu d'élèves sont venus : c'était triste.\n6. J'ai quelques amis au camp, alors je suis content.\n\n*Aide : came = sont venus ; at the camp = au camp.*\n\n**2.** Les phrases 5 et 6 parlent toutes deux d'une petite quantité. Explique en quoi leur sens diffère, et comment l'anglais le marque.","bareme":[{"critere":"No / any, some pour l'offre, any au sens de n'importe quel","points":6},{"critere":"Too much / enough avec les bons noms (homework indénombrable)","points":4},{"critere":"Few / a few correctement choisis","points":4},{"critere":"Explication de la nuance few / a few","points":4},{"critere":"Correction de la langue","points":2}],"dureeMin":16,"corrige":"**1. Traduction modèle**\n1. *There is no milk in the fridge.* (ou *There isn't any milk…*)\n2. *Would you like some orange juice?* — offre polie : *some*.\n3. *Take any book (you like).* — *any* en affirmative = n'importe quel.\n4. *We have too much homework and not enough time.* — *homework* est indénombrable → *too much* (pas *too many homeworks*) ; *enough* devant le nom.\n5. *Few students came: it was sad.* (*pupils* accepté)\n6. *I have a few friends at the camp, so I'm happy.*\n\n**2. La nuance**\nLes deux phrases parlent d'un petit nombre (*students*, *friends* sont dénombrables), mais :\n- *few* (sans article) = **trop peu**, sens négatif : on le regrette (« c'était triste ») ;\n- *a few* = **quelques-uns, assez**, sens positif : on s'en contente (« je suis content »).\nL'anglais marque cette différence par la seule présence de l'article *a*. Pour un indénombrable, on aurait *little* / *a little*."}$exo$::jsonb),
  ('06027d0d-685d-5e8c-bce8-f1f5556ae6d8'::uuid, 1, 'traduction', $exo${"titre":"Bored ou boring ?","consigne":"Choisis la bonne forme de l'adjectif, puis traduis les deux groupes.","enonce":"**1. Entoure la bonne forme et recopie la phrase.**\n\n1. The film was very (bored / boring).\n2. I am (interested / interesting) in history.\n3. After the match, the players were (tired / tiring).\n4. The news was (surprised / surprising).\n5. The children were (frightened / frightening) by the storm.\n6. This book is really (interested / interesting).\n\n**2. Traduis :** une voiture rouge — deux voitures rouges.","bareme":[{"critere":"Six choix -ed / -ing justes","points":14},{"critere":"Traduction avec adjectif invariable placé avant le nom","points":6}],"dureeMin":6,"corrige":"**1. Réponses**\n1. The film was very **boring**. — le film provoque l'ennui.\n2. I am **interested** in history. — ce que je ressens.\n3. The players were **tired**. — ce qu'ils ressentent.\n4. The news was **surprising**. — la nouvelle provoque la surprise.\n5. The children were **frightened**. — ce qu'ils ressentent.\n6. This book is really **interesting**. — le livre provoque l'intérêt.\n\nRègle : **-ed** = ce que ressent la personne ; **-ing** = ce qui provoque le sentiment.\n\n**2. Traduction**\n*a red car* — *two red cars*. L'adjectif se place **avant** le nom et reste **invariable** : jamais *reds*."}$exo$::jsonb),
  ('06027d0d-685d-5e8c-bce8-f1f5556ae6d8'::uuid, 2, 'traduction', $exo${"titre":"La brocante de Léon","consigne":"Remets les adjectifs dans l'ordre, puis traduis les groupes avec un adjectif composé.","enonce":"Léon vend des objets à une brocante. Aide-le à écrire ses étiquettes.\n\n**1. Remets les adjectifs dans le bon ordre.**\n\na. a (wooden / small / old) box\nb. a (French / beautiful / blue) vase\nc. (leather / black / big) boots\n\n**2. Traduis en anglais.**\n\na. une fille de dix ans\nb. un film de deux heures\nc. un trajet de trois kilomètres\n\n**3.** Complète : *Léon seems ___ (happy / happily).* Explique ton choix.","bareme":[{"critere":"Ordre des adjectifs juste dans les trois groupes","points":9},{"critere":"Adjectifs composés avec trait d'union et nom au singulier","points":7},{"critere":"Adjectif après le verbe d'état seem, choix expliqué","points":4}],"dureeMin":10,"corrige":"**1. Ordre** (opinion → taille → âge → forme → couleur → origine → matière)\na. *a small old wooden box* — taille, âge, matière.\nb. *a beautiful blue French vase* — opinion, couleur, origine.\nc. *big black leather boots* — taille, couleur, matière.\n\n**2. Adjectifs composés**\na. *a ten-year-old girl*\nb. *a two-hour film*\nc. *a three-kilometre journey* (ou *trip* ; *kilometer* accepté)\nTrait d'union, et le nom reste au **singulier** : jamais *ten-years-old* ni *two-hours*.\n\n**3.** *Léon seems **happy**.* — *seem* est un verbe d'état (comme be, look, feel) : il est suivi d'un **adjectif**, pas d'un adverbe."}$exo$::jsonb),
  ('06027d0d-685d-5e8c-bce8-f1f5556ae6d8'::uuid, 3, 'traduction', $exo${"titre":"Une journée au musée","consigne":"Traduis le texte en anglais, puis justifie trois choix grammaticaux.","enonce":"**1. Thème : traduis en anglais.**\n\n> Hier, notre classe a visité un grand musée moderne. Le guide était intéressant, mais la visite de trois heures était fatigante. À la fin, nous étions fatigués. Dans une salle, il y avait une jolie petite table ronde en bois. Le musée aide les pauvres : l'entrée est gratuite pour eux.\n\n*Aide : visited = a visité ; room = salle ; free = gratuit ; entry = l'entrée ; to help = aider.*\n\n**2.** Justifie en une phrase chacun :\na) *interesting* / *tiring* / *tired* ;\nb) l'ordre des adjectifs devant *table* ;\nc) le verbe employé avec *the poor*.","bareme":[{"critere":"Adjectifs placés avant le nom, invariables, bon ordre","points":5},{"critere":"Choix -ed / -ing justes","points":4},{"critere":"Adjectif composé three-hour et adjectif substantivé the poor avec verbe au pluriel","points":4},{"critere":"Trois justifications exactes","points":5},{"critere":"Correction générale de la langue","points":2}],"dureeMin":16,"corrige":"**1. Traduction modèle**\n> *Yesterday, our class visited a big modern museum. The guide was interesting, but the three-hour visit was tiring. At the end, we were tired. In one room, there was a lovely little round wooden table. The museum helps the poor: entry is free for them.*\n(*nice* ou *pretty little round wooden table* acceptés ; *large* accepté.)\n\n**2. Justifications**\na) *interesting* et *tiring* décrivent ce qui **provoque** le sentiment (le guide, la visite) → **-ing** ; *tired* décrit ce que **ressentent** les élèves → **-ed**. *We were tiring* voudrait dire « nous étions fatigants ».\nb) Ordre : opinion (*lovely*) → taille (*little*) → forme (*round*) → matière (*wooden*).\nc) *the poor* désigne un **groupe entier** de personnes : l'adjectif substantivé prend **the** et un sens pluriel (on le reprend par *them*, et un verbe dont il serait sujet serait au pluriel : *the poor are…*).\n\nAutres points : *three-hour* avec trait d'union et sans -s ; adjectifs jamais au pluriel."}$exo$::jsonb),
  ('e1cfdb3f-f3d3-5cd4-8e9d-7598c0b19c4e'::uuid, 1, 'traduction', $exo${"titre":"Repérer l'auxiliaire","consigne":"Pour chaque phrase, relève l'auxiliaire et le verbe lexical, puis donne une réponse courte.","enonce":"**1. Relève l'auxiliaire et le verbe lexical.**\n\na. She is working.\nb. I have finished.\nc. They don't know.\nd. You can go.\n\n**2. Réponds par une réponse courte (reprise).**\n\na. Do you like tea? — Yes, …\nb. Is she ready? — No, …\nc. Have you finished? — Yes, …\nd. Can he swim? — No, …","bareme":[{"critere":"Auxiliaire et verbe lexical correctement relevés dans les quatre phrases","points":10},{"critere":"Quatre réponses courtes avec le bon auxiliaire repris","points":10}],"dureeMin":7,"corrige":"**1. Repérage**\na. auxiliaire **is** (be, forme en -ING) — verbe lexical **working** (work).\nb. auxiliaire **have** (temps composé) — verbe lexical **finished** (finish).\nc. auxiliaire **do** (dans *don't*, négation) — verbe lexical **know**.\nd. auxiliaire **can** (modal) — verbe lexical **go**.\n\n**2. Réponses courtes**\na. Yes, **I do**.\nb. No, **she isn't**.\nc. Yes, **I have**.\nd. No, **he can't**.\n\nLa reprise courte répète l'**auxiliaire** de la question, jamais le verbe lexical (*Yes, I like* est faux)."}$exo$::jsonb),
  ('e1cfdb3f-f3d3-5cd4-8e9d-7598c0b19c4e'::uuid, 2, 'traduction', $exo${"titre":"Questions et négations","consigne":"Mets chaque phrase à la forme interrogative, puis à la forme négative.","enonce":"Mets chaque phrase **à la forme interrogative**, puis **à la forme négative**.\n\n1. You are ready.\n2. She has finished her homework.\n3. He works in London.\n4. They can speak Spanish.\n5. You have a car.\n\n**Question finale :** pourquoi les phrases 3 et 5 ne se construisent-elles pas comme les autres ?","bareme":[{"critere":"Questions avec l'auxiliaire placé devant le sujet","points":7},{"critere":"Négations avec not juste après l'auxiliaire","points":7},{"critere":"Do employé pour work et pour have lexical","points":4},{"critere":"Explication : verbe lexical seul, il faut un auxiliaire","points":2}],"dureeMin":10,"corrige":"**Réponses**\n1. *Are you ready?* — *You aren't ready.* (*You are not ready.*)\n2. *Has she finished her homework?* — *She hasn't finished her homework.*\n3. *Does he work in London?* — *He doesn't work in London.*\n4. *Can they speak Spanish?* — *They can't speak Spanish.* (*cannot*)\n5. *Do you have a car?* — *You don't have a car.*\n\n**Explication**\nDans les phrases 1, 2 et 4, il y a déjà un auxiliaire (*are*, *has*, *can*) : il passe devant le sujet pour la question et reçoit *not* pour la négation. Dans les phrases 3 et 5, il n'y a qu'un **verbe lexical** (*works*, *have* au sens de posséder) : seul, il ne sait former ni question ni négation, il faut donc l'auxiliaire **do** (*does* à la 3e personne, et le verbe revient à la base verbale : *does he work*)."}$exo$::jsonb),
  ('e1cfdb3f-f3d3-5cd4-8e9d-7598c0b19c4e'::uuid, 3, 'traduction', $exo${"titre":"L'interview d'une chanteuse","consigne":"Retrouve les questions de la journaliste, puis réponds aux questions 2 et 3.","enonce":"Une journaliste interroge la chanteuse Maya. Voici les réponses de Maya.\n\n1. (…?) — *Yes, I am. I'm very tired tonight.*\n2. (…?) — *Yes, I do. I love my fans.*\n3. (…?) — *No, I haven't. I haven't finished my new album yet.*\n4. (…?) — *Yes, I can. I can play the piano.*\n5. (…?) — *No, I don't. I don't have a dog.*\n\n**1.** Écris les cinq questions de la journaliste.\n**2.** Dans la réponse 1, *be* est-il auxiliaire ou verbe lexical ? Et *have* dans la réponse 5 ? Justifie.\n**3.** Explique pourquoi l'auxiliaire est « la clé de toute la grammaire anglaise ».","bareme":[{"critere":"Cinq questions correctes, auxiliaire devant le sujet","points":8},{"critere":"Auxiliaire de la question cohérent avec la reprise courte","points":4},{"critere":"Statut de be et de have justifié","points":5},{"critere":"Explication du rôle de l'auxiliaire (question, négation, reprise)","points":3}],"dureeMin":15,"corrige":"**1. Questions attendues**\n1. *Are you tired (tonight)?*\n2. *Do you love your fans?* (*Do you like your fans?* accepté)\n3. *Have you finished your new album (yet)?*\n4. *Can you play the piano?* (*Can you play an instrument?* accepté)\n5. *Do you have a dog?*\nLa reprise courte donne l'auxiliaire : *I am* → *Are you…?* ; *I do* → *Do you…?*, etc.\n\n**2. Statut**\n- Réponse 1 : *be* est **lexical** (verbe d'état, *I'm tired*), mais il **garde ses pouvoirs** d'auxiliaire : il passe lui-même devant le sujet (*Are you tired?*), sans *do*.\n- Réponse 5 : *have* est **lexical** (posséder) : il n'a pas ces pouvoirs, il faut **do** (*Do you have a dog?* / *I don't have a dog*).\n\n**3. La clé**\nL'auxiliaire construit la phrase : il passe **devant le sujet** pour la question, reçoit **not** pour la négation et sert à la **reprise courte**. Une fois l'auxiliaire repéré, question, négation et réponse courte se construisent toutes seules."}$exo$::jsonb),
  ('19797220-1153-5e07-8bba-ad4697faa9eb'::uuid, 1, 'traduction', $exo${"titre":"Am, is, are, was, were, has, have, had","consigne":"Complète chaque phrase avec la bonne forme de be ou de have.","enonce":"**Complète avec la bonne forme de be ou have.**\n\n1. I ___ 14 years old.\n2. My sister ___ two cats.\n3. Yesterday we ___ at the beach.\n4. They ___ hungry, so they ate a sandwich.\n5. He ___ reading a book right now.\n6. Last year, I ___ a bad cold.\n7. ___ you got a pen?\n8. The window ___ broken by the wind last night.\n\n**Question :** quelle est l'erreur la plus fréquente avec l'âge ?","bareme":[{"critere":"Huit formes justes (temps et personne)","points":16},{"critere":"Erreur sur l'âge identifiée (I am 15 et non I have 15)","points":4}],"dureeMin":7,"corrige":"**Réponses**\n1. I **am** 14 years old. — l'âge se dit avec *be*.\n2. My sister **has** two cats. — *has* à la 3e personne.\n3. Yesterday we **were** at the beach. — prétérit, pluriel.\n4. They **were** hungry — « avoir faim » = *be hungry* ; prétérit.\n5. He **is** reading — auxiliaire des formes en -ING.\n6. Last year, I **had** a bad cold. — prétérit de *have*.\n7. **Have** you got a pen? — *have got* : question sans *do*.\n8. The window **was** broken — auxiliaire du passif, prétérit.\n\n**L'erreur sur l'âge**\n« J'ai 15 ans » se dit *I am 15* (ou *I am 15 years old*), jamais *I have 15*. De même : *be cold, hungry, thirsty, right, afraid*."}$exo$::jsonb),
  ('19797220-1153-5e07-8bba-ad4697faa9eb'::uuid, 2, 'traduction', $exo${"titre":"Le carnet de voyage de Samir","consigne":"Traduis le texte en anglais (thème), puis réponds à la question 2.","enonce":"**1. Thème : traduis en anglais.**\n\n> J'ai 15 ans et j'ai deux frères. Aujourd'hui, nous avons froid et nous avons soif. Hier, nous étions à Londres et nous avons pris un bon petit-déjeuner. Mon frère a toujours raison !\n\n*Aide : we had breakfast = nous avons pris le petit-déjeuner.*\n\n**2.** Dans chaque phrase, dis si *he's* vaut *he is* ou *he has*, et explique comment tu le sais.\n\na. *He's tired.*\nb. *He's finished his lunch.*\nc. *He's reading.*","bareme":[{"critere":"Be employé là où le français dit « avoir » (âge, froid, soif, raison)","points":8},{"critere":"Have pour la possession et l'action (brothers, breakfast), prétérit juste","points":5},{"critere":"Les trois contractions he's correctement analysées","points":5},{"critere":"Correction de la langue","points":2}],"dureeMin":10,"corrige":"**1. Traduction modèle**\n> *I am 15 and I have two brothers. Today, we are cold and we are thirsty. Yesterday, we were in London and we had a good breakfast. My brother is always right!*\n(*I have got two brothers* accepté.)\n\nPoints attendus : *I am 15*, *we are cold*, *we are thirsty*, *is right* — le français dit « avoir », l'anglais dit *be* ; *were* au prétérit pluriel ; *had breakfast* : *have* dans une expression d'action.\n\n**2. Contractions**\na. *He's tired* = **he is** : suivi d'un adjectif.\nb. *He's finished* = **he has** : suivi d'un participe passé, c'est un temps composé.\nc. *He's reading* = **he is** : suivi d'un verbe en -ING.\nC'est ce qui **suit** la contraction qui tranche."}$exo$::jsonb),
  ('19797220-1153-5e07-8bba-ad4697faa9eb'::uuid, 3, 'traduction', $exo${"titre":"Le château hanté","consigne":"Lis le texte, puis réponds aux trois questions en justifiant.","enonce":"> Tom is 16. He's got a camera and he's always curious. Last summer, he was on holiday in Scotland with his parents. The old castle had been closed for years. « I'm afraid », said his mother. But Tom was right: the castle was built in 1450 and it's full of history. They had a great time.\n\n1. Relève dans le texte **un emploi de be** comme verbe d'état, **un** comme auxiliaire du passif, et **deux** expressions où l'anglais dit *be* là où le français dit « avoir ».\n2. Dis ce que vaut chaque *'s* du texte (*he's got*, *he's always*, *it's full*), et justifie.\n3. Pose trois questions sur le texte : une avec *be*, une avec *have got*, une avec *have* au sens d'une action (*have a great time*). Explique pourquoi seule la dernière demande *do*.","bareme":[{"critere":"Emplois de be correctement relevés (état, passif, deux expressions en « avoir »)","points":5},{"critere":"Trois contractions correctement analysées","points":4},{"critere":"Trois questions correctes","points":6},{"critere":"Explication : have got sans do, have lexical avec do","points":3},{"critere":"Qualité de la rédaction","points":2}],"dureeMin":17,"corrige":"**1. Emplois de be**\n- Verbe d'état : *he was on holiday*, *it's full of history*.\n- Auxiliaire du passif : *the castle was built in 1450*.\n- Là où le français dit « avoir » : *Tom is 16* (« avoir 16 ans »), *I'm afraid* (« avoir peur »), *Tom was right* (« avoir raison »). Deux exemples suffisent.\n\n**2. Les 's**\n- *he's got* = **he has** got : suivi de *got*, c'est *have got* (posséder).\n- *he's always curious* = **he is** : suivi d'un adverbe et d'un adjectif.\n- *it's full* = **it is** : suivi d'un adjectif.\n\n**3. Questions attendues** (formulations proches acceptées)\n- *Where was Tom last summer?* / *Was Tom in Scotland?* (be)\n- *Has Tom got a camera?* (have got)\n- *Did they have a great time?* (have d'action)\nAvec *have got*, *have* est auxiliaire : il passe devant le sujet, **sans do**. Dans *have a great time*, *have* est un verbe **lexical** (une action) : il faut **do** (*did* au prétérit), et *have* revient à la base verbale."}$exo$::jsonb),
  ('0dd7056c-a464-5f53-a030-b4358f4517dc'::uuid, 1, 'traduction', $exo${"titre":"Une seule marque de temps","consigne":"Mets chaque phrase à la forme négative.","enonce":"**Mets chaque phrase à la forme négative.**\n\n1. I like coffee.\n2. She works here.\n3. He went to the cinema.\n4. They play football.\n5. My dad watches TV every evening.\n6. We saw the film.\n\n**Question :** énonce la « règle d'or » de l'auxiliaire DO.","bareme":[{"critere":"Six négations justes (don't, doesn't, didn't selon le temps et la personne)","points":14},{"critere":"Règle d'or énoncée : do porte le temps, le verbe revient à la base verbale","points":6}],"dureeMin":6,"corrige":"**Réponses**\n1. *I don't like coffee.*\n2. *She doesn't work here.*\n3. *He didn't go to the cinema.*\n4. *They don't play football.*\n5. *My dad doesn't watch TV every evening.*\n6. *We didn't see the film.*\n\n**La règle d'or**\nDès que *do* apparaît, c'est lui qui prend la marque du **temps** et de la **personne** (*doesn't*, *didn't*) ; le verbe lexical revient à la **base verbale**. Une phrase ne porte qu'une seule marque de temps : *doesn't works* et *didn't went* sont faux."}$exo$::jsonb),
  ('0dd7056c-a464-5f53-a030-b4358f4517dc'::uuid, 2, 'traduction', $exo${"titre":"Le quiz d'Eliott","consigne":"Corrige les phrases fautives et justifie chaque correction. Attention : deux phrases sont justes.","enonce":"Eliott a préparé un quiz pour sa classe, mais il a fait des fautes.\n\n1. Did you went to London last year?\n2. Does she likes pizza?\n3. Do you are happy?\n4. Who did break the window?\n5. Can you swim?\n6. He don't play tennis.\n7. What do you do on Sundays?\n8. Do you can help me?\n\nPour chaque phrase, écris « juste » ou recopie-la corrigée, puis justifie en une ligne.","bareme":[{"critere":"Les six phrases fautives corrigées","points":10},{"critere":"Les deux phrases justes reconnues (5 et 7)","points":4},{"critere":"Justifications exactes (double marque, be, modal, who sujet)","points":6}],"dureeMin":10,"corrige":"1. *Did you **go** to London last year?* — *did* porte le passé, le verbe revient à la base verbale.\n2. *Does she **like** pizza?* — *does* porte le -s, pas le verbe.\n3. ***Are you** happy?* — avec *be*, jamais *do*.\n4. *Who **broke** the window?* — *who* est sujet : pas de *do*.\n5. **Juste** — avec un modal, pas de *do*.\n6. *He **doesn't** play tennis.* — 3e personne : *doesn't*.\n7. **Juste** — *do* lexical (faire), il faut un second *do* pour interroger.\n8. ***Can you** help me?* — avec un modal, pas de *do*."}$exo$::jsonb),
  ('0dd7056c-a464-5f53-a030-b4358f4517dc'::uuid, 3, 'traduction', $exo${"titre":"Rencontre avec un champion","consigne":"Écris les questions demandées, puis réponds aux questions 2 et 3 en justifiant.","enonce":"Tu interviewes Karim, champion de natation. Voici ce que tu sais de lui :\n\n> Karim trains every morning. He won a gold medal in 2024. He is 19. He can swim 100 metres in 50 seconds. He doesn't like cold water. Someone called him « the fish ».\n\n1. Écris **six questions** à lui poser : une sur chaque phrase du document (pour la dernière, commence par *Who*).\n2. Dans lesquelles de tes questions *do* n'apparaît-il pas ? Explique pourquoi pour chacune.\n3. Karim répond : *« I do like cold water in summer! »* Explique le rôle de *do* dans cette phrase.","bareme":[{"critere":"Questions avec do / does / did correctes, verbe à la base verbale","points":6},{"critere":"Questions sans do correctes (be, can, who sujet)","points":5},{"critere":"Explication des cas où do n'apparaît pas","points":5},{"critere":"Rôle d'insistance de do expliqué","points":4}],"dureeMin":16,"corrige":"**1. Questions attendues** (formulations proches acceptées)\n1. *When do you train?* / *Do you train every morning?*\n2. *Did you win a gold medal in 2024?* / *When did you win a gold medal?*\n3. *How old are you?*\n4. *How fast can you swim?* / *Can you swim 100 metres in 50 seconds?*\n5. *Do you like cold water?*\n6. *Who called you « the fish »?*\n\n**2. Sans do**\n- Question 3 : avec **be**, qui passe lui-même devant le sujet.\n- Question 4 : avec un **modal** (*can*), qui construit seul la question.\n- Question 6 : *who* est le **sujet** du verbe : l'ordre reste celui de l'affirmative (*Who called…?*), sans *did*.\n\n**3. L'insistance**\n*I do like* : *do* accentué sert à l'**insistance**, il contredit ce que l'on croyait (« si, j'aime vraiment l'eau froide… en été »). Le verbe lexical reste à la base verbale (*like*)."}$exo$::jsonb),
  ('fa89beed-736a-5a2f-bff1-1f10c089282b'::uuid, 1, 'traduction', $exo${"titre":"Must, mustn't ou don't have to ?","consigne":"Choisis la forme qui convient et recopie la phrase, puis réponds à la question 2.","enonce":"**1. Choisis : must, mustn't, don't have to ou had to.**\n\n1. You ___ smoke in the school: it's forbidden.\n2. It's Saturday: I ___ get up early.\n3. I ___ stop eating sweets, I've decided it.\n4. Yesterday, I ___ stay home because I was ill.\n5. You ___ run in the corridors: it's dangerous.\n6. We ___ wear a uniform: it's not compulsory.\n\n**2.** Explique la différence entre *You mustn't come* et *You don't have to come*.","bareme":[{"critere":"Six formes justes","points":12},{"critere":"Différence interdiction / absence d'obligation expliquée","points":8}],"dureeMin":7,"corrige":"**1. Réponses**\n1. **mustn't** — interdiction.\n2. **don't have to** — pas d'obligation le samedi.\n3. **must** — obligation qui vient de celui qui parle.\n4. **had to** — obligation au passé (*must* n'a pas de passé).\n5. **mustn't** — interdiction.\n6. **don't have to** — ce n'est pas obligatoire.\n\n**2. La différence**\n*You mustn't come* = **tu ne dois pas venir**, c'est interdit. *You don't have to come* = **tu n'es pas obligé de venir**, tu peux venir si tu veux. La négation de *must* n'est donc pas *don't have to* : l'une interdit, l'autre dispense."}$exo$::jsonb),
  ('fa89beed-736a-5a2f-bff1-1f10c089282b'::uuid, 2, 'traduction', $exo${"titre":"Le règlement du club de foot","consigne":"Traduis le règlement en anglais, puis réponds à la question 2.","enonce":"**1. Thème : traduis ce règlement.**\n\n> 1. Les joueurs doivent arriver à 17 h (c'est le règlement).\n> 2. Il est interdit de manger sur le terrain.\n> 3. Vous n'êtes pas obligés d'apporter un ballon.\n> 4. L'an dernier, les joueurs devaient payer 50 euros.\n> 5. Vous devriez boire beaucoup d'eau.\n\n*Aide : pitch = terrain ; to bring = apporter ; to pay = payer.*\n\n**2.** Pour la règle 1, pourquoi *have to* convient-il mieux que *must* ?","bareme":[{"critere":"Have to pour l'obligation extérieure, had to au passé","points":6},{"critere":"Mustn't pour l'interdiction, don't have to / needn't pour l'absence d'obligation","points":6},{"critere":"Should pour le conseil","points":3},{"critere":"Justification must / have to","points":5}],"dureeMin":10,"corrige":"**1. Traduction modèle**\n1. *Players have to arrive at 5 p.m.* (*must* accepté pour un règlement écrit)\n2. *You mustn't eat on the pitch.* (*Players mustn't eat…*)\n3. *You don't have to bring a ball.* (*You needn't bring a ball.*)\n4. *Last year, players had to pay 50 euros.* — *must* n'a pas de passé.\n5. *You should drink a lot of water.* — conseil, pas obligation.\n\n**2. Justification**\n*Have to* exprime une obligation qui vient de l'**extérieur** : ici, le règlement du club. *Must* exprime plutôt une obligation qui vient de **celui qui parle**, une conviction personnelle (*I must stop smoking* : je l'ai décidé)."}$exo$::jsonb),
  ('fa89beed-736a-5a2f-bff1-1f10c089282b'::uuid, 3, 'traduction', $exo${"titre":"Mail à une correspondante anglaise","consigne":"Rédige en anglais le courriel demandé (60 à 80 mots), puis réponds à la question 2.","enonce":"Ta correspondante anglaise, Ellie, te demande comment se passent les règles dans ton collège.\n\n**1.** Écris-lui un courriel de **60 à 80 mots** en anglais. Tu dois employer au moins une fois : *have to*, *must*, *mustn't*, *don't have to* et *had to* (pour parler de l'école primaire), et un conseil avec *should*.\n\n**2.** En français, explique en deux ou trois phrases pourquoi on ne peut pas dire *musted* ni *I will must*, et ce qu'on emploie à la place.","bareme":[{"critere":"Les six formes imposées présentes et employées dans le bon sens","points":8},{"critere":"Distinction mustn't / don't have to respectée","points":3},{"critere":"Courriel cohérent, de la bonne longueur, en anglais correct","points":5},{"critere":"Explication : must invariable, remplacé par had to / will have to","points":4}],"dureeMin":18,"corrige":"**1. Exemple de courriel**\n> *Hi Ellie,*\n> *In my school, we have to arrive at 8 a.m. We mustn't use our phones in class, it's forbidden. But we don't have to wear a uniform! In primary school, we had to line up in the playground every morning. I must work harder this year, because I have an exam in June. You should come to France to see my school!*\n> *Love, Lina*\n\nOn vérifie le sens de chaque forme : *have to* = règle extérieure ; *must* = décision personnelle ; *mustn't* = interdiction ; *don't have to* = pas d'obligation ; *had to* = obligation passée ; *should* = conseil. Pénaliser *musted*, *must to*, *has must*.\n\n**2. Explication**\n*Must* est **invariable** et n'a **ni passé ni futur** : il ne prend ni -ed ni -s, et ne se place pas après un autre modal comme *will*. On emploie donc *have to*, qui se conjugue : *had to* au passé (*I had to stay home*), *will have to* au futur (*I will have to work*)."}$exo$::jsonb),
  ('91e30bde-808a-5d7a-a1c9-4fa7af35a772'::uuid, 1, 'traduction', $exo${"titre":"Can, could ou be able to ?","consigne":"Complète chaque phrase avec can, could, was able to ou will be able to.","enonce":"**Complète.**\n\n1. My brother ___ speak three languages.\n2. When I was five, I ___ swim.\n3. The door was locked, but he ___ open it with a knife.\n4. Next year, I ___ drive a car.\n5. ___ you help me, please? (demande polie)\n6. I ___ see the sea from my window.\n\n**Question :** corrige la phrase *I will can swim next summer* et explique.","bareme":[{"critere":"Six formes justes selon la situation","points":14},{"critere":"Correction en will be able to, avec l'explication","points":6}],"dureeMin":6,"corrige":"**Réponses**\n1. **can** — capacité présente.\n2. **could** — capacité passée générale.\n3. **was able to** — réussite ponctuelle au passé (*managed to* accepté).\n4. **will be able to** — capacité future.\n5. **Could** — demande polie.\n6. **can** — perception (see) : « je vois la mer ».\n\n**Correction**\n*I will be able to swim next summer.* — *can* est un modal : il ne se met pas après un autre modal comme *will* et n'a pas de futur. On emploie la forme de remplacement *be able to*, qui se conjugue à tous les temps."}$exo$::jsonb),
  ('91e30bde-808a-5d7a-a1c9-4fa7af35a772'::uuid, 2, 'traduction', $exo${"titre":"Le défi d'escalade","consigne":"Traduis les phrases en anglais (thème).","enonce":"Zoé raconte sa journée d'escalade.\n\n**Thème : traduis en anglais.**\n\n1. Je sais nager, mais je ne sais pas grimper.\n2. Quand j'avais huit ans, je savais faire du vélo.\n3. Le mur était difficile, mais j'ai réussi à atteindre le sommet.\n4. D'en haut, j'entendais la rivière.\n5. Pourrais-tu m'aider à porter mon sac, s'il te plaît ?\n6. Bientôt, je serai capable de grimper seule.\n\n*Aide : to climb = grimper ; to reach the top = atteindre le sommet ; to carry = porter ; on my own = seule.*","bareme":[{"critere":"Can / can't pour la capacité présente, could pour le passé général","points":6},{"critere":"Was able to (ou managed to) pour la réussite ponctuelle","points":5},{"critere":"Could pour la perception passée et la demande polie","points":4},{"critere":"Will be able to au futur, construction sans to après les modaux","points":5}],"dureeMin":10,"corrige":"**Traduction modèle**\n1. *I can swim, but I can't climb.* (*cannot*)\n2. *When I was eight, I could ride a bike.*\n3. *The wall was difficult, but I was able to reach the top.* (*I managed to reach the top.*) — réussite ponctuelle : pas *could*.\n4. *From the top, I could hear the river.* — perception : *can / could* + hear.\n5. *Could you help me carry my bag, please?* (*to carry* accepté) — plus poli que *can*.\n6. *Soon, I will be able to climb on my own.* (*alone* accepté)\n\nFautes à pénaliser : *I can to swim*, *she cans*, *I will can*, *I could reach the top* (réussite ponctuelle)."}$exo$::jsonb),
  ('91e30bde-808a-5d7a-a1c9-4fa7af35a772'::uuid, 3, 'traduction', $exo${"titre":"Le robot de Hugo","consigne":"Lis le texte, corrige les fautes en justifiant, puis rédige un court paragraphe.","enonce":"> When Hugo was ten, he could build small robots. Last month, his robot, Rob, could win the school contest after three hours of work! Now Rob cans walk and talk. « Next year, Rob will can cook », says Hugo. « From my room I can to hear him when he moves. »\n\n1. Le texte contient **quatre fautes** sur l'expression de la capacité. Relève-les, corrige-les et justifie.\n2. Dans la phrase 1, *could* est-il juste ? Explique la différence avec la phrase 2.\n3. En 4 ou 5 phrases en anglais, présente une chose que tu savais faire enfant, une réussite précise, une capacité actuelle et une capacité future.","bareme":[{"critere":"Quatre fautes relevées et corrigées","points":6},{"critere":"Justifications exactes (réussite ponctuelle, invariabilité, futur)","points":4},{"critere":"Différence capacité générale / réussite ponctuelle expliquée","points":4},{"critere":"Paragraphe avec could, was able to, can, will be able to bien employés","points":6}],"dureeMin":16,"corrige":"**1. Les quatre fautes**\n- *could win* → **was able to win** (ou *managed to win*) : réussite **ponctuelle** au passé.\n- *cans walk* → **can walk** : *can* est invariable, jamais de -s.\n- *will can cook* → **will be able to cook** : pas de modal après *will* ; on prend *be able to*.\n- *can to hear* → **can hear** : jamais de *to* après *can*.\n\n**2. Could, phrase 1**\nOui : *could* exprime une **capacité passée générale** (quand il avait dix ans, il savait construire des robots). En phrase 2, il s'agit d'une **réussite ponctuelle**, un jour précis (le concours) : on emploie *was able to*.\n\n**3. Exemple de paragraphe**\n> *When I was six, I could ride a bike. Last year, I was able to finish a 10 km race. Now I can play the guitar. Next year, I will be able to play in a band.*\n\nOn vérifie les quatre formes et l'absence de *to* après *can / could*."}$exo$::jsonb),
  ('430cdc11-f62d-5256-ae2e-c8ed4caa4d71'::uuid, 1, 'traduction', $exo${"titre":"Demander et donner la permission","consigne":"Complète chaque phrase, puis classe les trois demandes du plus familier au plus formel.","enonce":"**1. Complète avec can, can't, may ou was allowed to.**\n\n1. ___ I come in, Mrs Smith? (formel)\n2. You ___ use my phone if you want. (familier)\n3. Yesterday, I ___ stay up late.\n4. You ___ park here: look at the sign!\n5. Students ___ not use their phones in class. (règlement écrit)\n\n**2. Classe ces demandes du plus familier au plus formel :**\n*Could I open the window? — May I open the window? — Can I open the window?*","bareme":[{"critere":"Cinq formes justes","points":12},{"critere":"Classement correct : can, could, may","points":8}],"dureeMin":7,"corrige":"**1. Réponses**\n1. **May** I come in, Mrs Smith? — formel, avec un adulte.\n2. You **can** use my phone — permission familière.\n3. Yesterday, I **was allowed to** stay up late. — permission au passé : pas *could*.\n4. You **can't** park here — interdiction.\n5. Students **may** not use their phones — règlement écrit.\n\n**2. Classement**\n1) *Can I open the window?* — familier ;\n2) *Could I open the window?* — poli ;\n3) *May I open the window?* — le plus formel."}$exo$::jsonb),
  ('430cdc11-f62d-5256-ae2e-c8ed4caa4d71'::uuid, 2, 'traduction', $exo${"titre":"La sortie scolaire à Londres","consigne":"Traduis ces phrases en anglais (thème), en choisissant le registre qui convient.","enonce":"Pendant un voyage scolaire à Londres, voici ce qu'on entend.\n\n**Thème : traduis en anglais.**\n\n1. (Élève à son professeur) Puis-je aller aux toilettes, s'il vous plaît ?\n2. (Élève à son ami) Je peux prendre ton stylo ?\n3. (Panneau du musée) Les visiteurs ne sont pas autorisés à toucher les tableaux.\n4. (Le professeur) Vous aurez le droit d'acheter des souvenirs à 15 h.\n5. (Un élève, le lendemain) Hier, nous n'avions pas le droit de sortir seuls.\n6. (L'ami) Tu ne dois absolument pas toucher ça !\n\n*Aide : paintings = tableaux ; to go out on our own = sortir seuls.*","bareme":[{"critere":"May pour la demande formelle, can pour la demande familière","points":5},{"critere":"Be allowed to conjugué au présent, au futur et au passé","points":8},{"critere":"Mustn't pour l'interdiction forte","points":3},{"critere":"Correction de la langue","points":4}],"dureeMin":10,"corrige":"**Traduction modèle**\n1. *May I go to the toilet, please?* (*Could I…?* accepté) — formel, à un adulte.\n2. *Can I borrow your pen?* — familier, entre amis.\n3. *Visitors are not allowed to touch the paintings.* (*Visitors may not touch the paintings.* accepté : règlement écrit)\n4. *You will be allowed to buy souvenirs at 3 p.m.* — futur : *be allowed to* se conjugue à tous les temps.\n5. *Yesterday, we weren't allowed to go out on our own.*\n6. *You mustn't touch that!* — interdiction forte.\n\nFautes à pénaliser : *You could buy* pour accorder une permission (c'est une suggestion), *we couldn't to go*, *will can*."}$exo$::jsonb),
  ('430cdc11-f62d-5256-ae2e-c8ed4caa4d71'::uuid, 3, 'traduction', $exo${"titre":"Le nouveau règlement de l'internat","consigne":"Lis le document, puis réponds aux trois questions en justifiant.","enonce":"> **Boarding school rules**\n> - Students may use their phones after 6 p.m.\n> - Students may not leave the building after 8 p.m.\n> - Last year, students were not allowed to have visitors. From next month, they will be allowed to receive their parents on Sundays.\n\nNathan écrit à sa sœur : *« You could come on Sunday! »*\n\n1. Réécris les deux premières règles dans un registre **familier**, comme Nathan les expliquerait à un ami.\n2. Pourquoi le règlement emploie-t-il *be allowed to* dans la troisième règle ? Pourquoi ne pourrait-on pas dire *students could not have visitors* avec le sens de « n'avaient pas le droit » ?\n3. Que signifie *You could come on Sunday!* : une permission ou autre chose ? Justifie, puis écris la phrase avec laquelle Nathan demanderait poliment à la directrice si sa sœur peut venir.","bareme":[{"critere":"Deux règles réécrites en registre familier (can / can't)","points":4},{"critere":"Be allowed to justifié : conjugaison à tous les temps, règle extérieure","points":5},{"critere":"Could au sens de suggestion identifié et justifié","points":5},{"critere":"Demande formelle correcte (May / Could my sister…?)","points":4},{"critere":"Qualité de la rédaction","points":2}],"dureeMin":16,"corrige":"**1. Registre familier**\n- *We can use our phones after 6 p.m.*\n- *We can't leave the building after 8 p.m.*\n*May* / *may not* est le registre formel des règlements écrits ; à l'oral entre amis, on dit *can* / *can't*.\n\n**2. Be allowed to**\nLes modaux n'ont ni futur ni vraie forme passée pour une permission : *be allowed to* se **conjugue à tous les temps** (*were not allowed to* au passé, *will be allowed to* au futur) et insiste sur une **règle extérieure**, ce qui convient à un règlement. Pour une permission passée, on n'emploie pas *could* : on dit *was / were allowed to*.\n\n**3. You could come**\nCe n'est pas une permission : *could* ne sert jamais à **accorder** une permission. *You could come* signifie « tu pourrais venir » : c'est une **suggestion**.\nDemande polie à la directrice : *May my sister come on Sunday, please?* (*Could my sister come…?* accepté ; *Is my sister allowed to come…?* accepté)."}$exo$::jsonb),
  ('00d8c78f-6f58-5ba8-969a-cf590c09a65b'::uuid, 1, 'traduction', $exo${"titre":"Should, ought to, had better","consigne":"Complète chaque phrase, puis corrige les deux phrases fautives.","enonce":"**1. Complète avec should, shouldn't, ought ou 'd better.**\n\n1. You look tired. You ___ go to bed early.\n2. You ___ eat so many sweets.\n3. You ___ to see a doctor.\n4. Hurry up! You ___ run or you'll miss the bus.\n\n**2. Corrige.**\n\na. *You should to revise for the test.*\nb. *You had better to take an umbrella.*","bareme":[{"critere":"Quatre blancs justes, avec la construction de chaque forme","points":12},{"critere":"Deux phrases corrigées : pas de to après should et had better","points":8}],"dureeMin":6,"corrige":"**1. Réponses**\n1. You **should** go to bed early. — conseil ordinaire.\n2. You **shouldn't** eat so many sweets. — conseil à la forme négative.\n3. You **ought** to see a doctor. — *ought* est la seule forme suivie de *to*.\n4. You**'d better** run or you'll miss the bus. — conseil pressant, avec une menace.\n\n**2. Corrections**\na. *You should revise for the test.* — *should* est suivi de la base verbale, sans *to*.\nb. *You had better take an umbrella.* (*You'd better…*) — malgré le *had*, *had better* est suivi de la base verbale, sans *to*."}$exo$::jsonb),
  ('00d8c78f-6f58-5ba8-969a-cf590c09a65b'::uuid, 2, 'traduction', $exo${"titre":"Le problème de Léna","consigne":"Lis le message de Léna, puis réponds-lui en anglais en suivant les consignes.","enonce":"> *Hi! I'm so stressed. I have an important test on Monday but I haven't started revising. I spend my evenings on my phone and I go to bed at midnight. I had a fight with my best friend yesterday. What can I do? — Léna*\n\n1. Donne à Léna **quatre conseils** en anglais, en employant une fois chacune : *should*, *shouldn't*, *had better* et *Why don't you…?*\n2. Écris une phrase commençant par *If I were you, …*\n3. Classe ces trois phrases du conseil le plus doux à l'ordre : *You must sleep more. — You should sleep more. — You'd better sleep more.*","bareme":[{"critere":"Quatre conseils corrects, chaque forme bien construite","points":8},{"critere":"Conseils adaptés à la situation de Léna","points":4},{"critere":"Phrase en If I were you, I would… correcte","points":4},{"critere":"Classement should, had better, must","points":4}],"dureeMin":10,"corrige":"**1. Exemples de conseils**\n- *You should start revising this weekend.*\n- *You shouldn't use your phone so late.*\n- *You'd better go to bed earlier, or you'll be tired on Monday.*\n- *Why don't you call your best friend?*\nConstruction : *should / had better* + base verbale sans *to* ; *Why don't you* + base verbale.\n\n**2.** *If I were you, I would apologise to my friend.* (*I'd talk to her* accepté) — *were* à toutes les personnes, *would* + base verbale.\n\n**3. Classement**\n1) *You should sleep more.* — conseil ordinaire ;\n2) *You'd better sleep more.* — conseil pressant, avec menace implicite ;\n3) *You must sleep more.* — obligation."}$exo$::jsonb),
  ('00d8c78f-6f58-5ba8-969a-cf590c09a65b'::uuid, 3, 'traduction', $exo${"titre":"Le courrier des lecteurs","consigne":"Traduis la lettre, puis réponds aux questions 2 et 3 en justifiant.","enonce":"**1. Thème : traduis cette lettre au courrier des lecteurs.**\n\n> Chère Jenny, la semaine dernière, j'ai menti à mes parents. Je n'aurais pas dû. Mon frère dit que j'aurais dû leur dire la vérité. Est-ce que je devrais m'excuser ? Mon amie pense que je ferais mieux de me taire. — Adam\n\n*Aide : to lie (lied) = mentir ; to apologise = s'excuser ; to keep quiet = se taire.*\n\n**2.** Explique la construction et le sens de *should have* + participe passé. Pourquoi ne peut-on pas dire *I had better have told them* pour parler du passé ?\n\n**3.** Écris la réponse de Jenny en trois phrases, avec *should*, *ought to* et une tournure en *If I were you*.","bareme":[{"critere":"Should have + participe passé correct (shouldn't have, should have told)","points":5},{"critere":"Should en question et 'd better pour le conseil pressant","points":4},{"critere":"Explication du regret au passé et du caractère figé de had better","points":5},{"critere":"Réponse de Jenny avec les trois formes bien construites","points":4},{"critere":"Correction de la langue","points":2}],"dureeMin":17,"corrige":"**1. Traduction modèle**\n> *Dear Jenny, last week I lied to my parents. I shouldn't have (done it / lied). My brother says I should have told them the truth. Should I apologise? My friend thinks I'd better keep quiet. — Adam*\n\n**2. Should have + participe passé**\nC'est le conseil **au passé, avec un regret** : on dit ce qu'on aurait dû faire et qu'on n'a pas fait (*I should have told them* = « j'aurais dû leur dire »), ou ce qu'on n'aurait pas dû faire (*I shouldn't have lied*). *Had better* est une **expression figée** : elle ne se conjugue pas et ne vaut que pour le présent et le futur ; elle ne peut donc pas exprimer un regret sur le passé.\n\n**3. Exemple de réponse**\n> *You should talk to your parents tonight. You ought to tell them why you lied. If I were you, I would apologise.*\nOn vérifie : *should* + base verbale ; *ought to* + verbe ; *If I were you, I would* + base verbale."}$exo$::jsonb),
  ('a56bc172-9f53-5505-9a97-579af1e8b32b'::uuid, 1, 'traduction', $exo${"titre":"Let's, how about, why don't we","consigne":"Mets le verbe entre parenthèses à la bonne forme, puis réponds à la question 2.","enonce":"**1. Mets le verbe à la bonne forme (base verbale ou -ING).**\n\n1. Let's (go) to the cinema.\n2. How about (play) tennis?\n3. Why don't we (meet) at six?\n4. What about (have) a picnic?\n5. Shall we (start)?\n6. Let's not (waste) time.\n\n**2.** Donne deux façons d'accepter et deux façons de refuser poliment une suggestion.","bareme":[{"critere":"Six verbes à la bonne forme","points":12},{"critere":"Deux formules d'acceptation et deux de refus poli","points":8}],"dureeMin":6,"corrige":"**1. Réponses**\n1. Let's **go** — base verbale.\n2. How about **playing** — -ING après *how about*.\n3. Why don't we **meet** — base verbale.\n4. What about **having** — -ING.\n5. Shall we **start** — base verbale.\n6. Let's not **waste** — base verbale.\n\nPiège : *How / What about* + -ING ; *Let's*, *Shall we*, *Why don't we* + base verbale.\n\n**2. Réponses possibles**\n- Accepter : *Good idea!* / *That sounds great!* / *Why not!*\n- Refuser poliment : *I'd rather not.* / *I'm afraid I can't.* / *Sorry, I'm busy.*"}$exo$::jsonb),
  ('a56bc172-9f53-5505-9a97-579af1e8b32b'::uuid, 2, 'traduction', $exo${"titre":"Que faire samedi ?","consigne":"Complète le dialogue, puis réponds à la question 2.","enonce":"> **Jade**: It's Saturday! (1) ___ go to the beach!\n> **Omar**: Hmm, it's raining. How about (2) ___ (watch) a film instead?\n> **Jade**: (3) ___. I saw a film yesterday. Why don't we (4) ___ (visit) the museum?\n> **Omar**: (5) ___! And after that, (6) ___ we have lunch at the pizzeria?\n> **Jade**: Great! But I'd rather (7) ___ (eat) at home than (8) ___ (spend) all my money.\n\n1. Complète les blancs : mets le verbe à la bonne forme ou ajoute le mot qui manque (formule de suggestion, d'acceptation ou de refus).\n2. Traduis la dernière réplique de Jade en français et explique la construction de *would rather*.","bareme":[{"critere":"Formules de suggestion justes (Let's, shall)","points":4},{"critere":"Verbes à la bonne forme après how about, why don't we, would rather","points":7},{"critere":"Formules d'acceptation et de refus adaptées","points":4},{"critere":"Traduction et construction de would rather … than","points":5}],"dureeMin":10,"corrige":"**1. Réponses**\n(1) **Let's** go to the beach!\n(2) How about **watching** — -ING.\n(3) **I'd rather not.** (ou *Sorry, I'm not in the mood* ; toute formule de refus poli acceptée)\n(4) Why don't we **visit** — base verbale.\n(5) **Good idea!** (*That sounds great!*, *Why not!*)\n(6) **shall** we have lunch — *Shall we* + base verbale.\n(7) I'd rather **eat** — base verbale.\n(8) than **spend** — base verbale aussi.\n\n**2. Traduction**\n« Super ! Mais je préférerais manger à la maison plutôt que de dépenser tout mon argent. »\n*Would rather* (*'d rather*) + **base verbale** exprime une préférence ; pour comparer deux actions, on ajoute **than** + base verbale : *I'd rather eat at home than spend…*"}$exo$::jsonb),
  ('a56bc172-9f53-5505-9a97-579af1e8b32b'::uuid, 3, 'traduction', $exo${"titre":"Organiser l'anniversaire de Mia","consigne":"Écris le dialogue demandé en anglais, puis réponds à la question 2.","enonce":"Tom et Sara veulent organiser l'anniversaire surprise de leur amie Mia, samedi prochain.\n\n**1.** Écris leur dialogue en **8 à 10 répliques**. Tu dois employer :\n- *Let's* et *Let's not* ;\n- *Shall we…?* (une fois en tag : *…, shall we?*) ;\n- *How about* ou *What about* ;\n- *Why don't we…?* ;\n- une acceptation et un refus poli ;\n- une préférence avec *I'd rather … than …*\n\n**2.** Un camarade a écrit : *« How about go to the park? Why don't we going together? »* Corrige ses deux phrases et explique la règle en français.","bareme":[{"critere":"Toutes les formes imposées présentes","points":6},{"critere":"Constructions justes (base verbale ou -ING selon la forme)","points":6},{"critere":"Dialogue cohérent et naturel, avec acceptation et refus","points":3},{"critere":"Correction des deux phrases et règle expliquée","points":5}],"dureeMin":16,"corrige":"**1. Exemple de dialogue**\n> **Tom:** *Let's organise a surprise party for Mia!*\n> **Sara:** *Good idea! Shall we have it at my house?*\n> **Tom:** *Yes. How about inviting the whole class?*\n> **Sara:** *I'd rather not. I'd rather invite ten friends than thirty people.*\n> **Tom:** *OK. Why don't we make a cake ourselves?*\n> **Sara:** *That sounds great! And let's not tell her brother, he can't keep a secret.*\n> **Tom:** *Let's buy the decorations tomorrow, shall we?*\n> **Sara:** *Sorry, I'm busy tomorrow. What about Friday?*\n> **Tom:** *Why not!*\n\nOn vérifie : *Let's / Let's not / Shall we / Why don't we* + base verbale ; *How / What about* + -ING ou nom ; *I'd rather* + base verbale + *than* + base verbale.\n\n**2. Corrections**\n- *How about **going** to the park?* — après *how about*, verbe en -ING (ou un nom).\n- *Why don't we **go** together?* — après *why don't we*, base verbale.\nRègle : seuls *How about* et *What about* sont suivis de -ING ; *Let's*, *Shall we*, *Why don't we*, *Why not* sont suivis de la base verbale."}$exo$::jsonb),
  ('24756952-efd1-5e38-97a5-fc481f3547e1'::uuid, 1, 'traduction', $exo${"titre":"Would like ou wish ?","consigne":"Mets le verbe entre parenthèses à la bonne forme, puis réponds à la question 2.","enonce":"**1. Mets le verbe à la bonne forme.**\n\n1. I'd like (travel) to Canada.\n2. I wish I (have) more time. (maintenant)\n3. I wish I (be) taller.\n4. I wish I (study) harder last year.\n5. I wish it (stop) raining!\n6. Would you like (drink) something?\n\n**2.** Énonce la règle du « recul d'un temps » après *wish*.","bareme":[{"critere":"Six formes justes","points":14},{"critere":"Règle du recul d'un temps énoncée (présent → prétérit, passé → past perfect)","points":6}],"dureeMin":7,"corrige":"**1. Réponses**\n1. I'd like **to travel** — *would like* + to + verbe.\n2. I wish I **had** more time — regret sur le présent → prétérit.\n3. I wish I **were** taller — avec *be*, *were* à toutes les personnes.\n4. I wish I **had studied** harder — regret sur le passé → past perfect.\n5. I wish it **would stop** raining — souhait qu'une situation change → *would*.\n6. Would you like **to drink** something?\n\n**2. La règle**\nAprès *wish* (et *if only*), **on recule d'un temps** : un regret sur le **présent** se dit au **prétérit** (*I wish I had*), un regret sur le **passé** au **past perfect** (*I wish I had studied*). Seul *I wish you a happy birthday* ne suit pas cette règle."}$exo$::jsonb),
  ('24756952-efd1-5e38-97a5-fc481f3547e1'::uuid, 2, 'traduction', $exo${"titre":"Les regrets de Clément","consigne":"Transforme chaque situation en regret avec wish, puis réponds à la question 2.","enonce":"Clément n'est pas content de sa situation. Exprime ses regrets en commençant par *I wish…*\n\n1. I don't have a dog.\n2. I live far from my school.\n3. I am not good at maths.\n4. I didn't go to the concert last night.\n5. I ate too much cake yesterday.\n6. My neighbours make too much noise. (il voudrait que ça change)\n\n**2.** Réécris la phrase 4 avec *If only*. Qu'est-ce que cette tournure ajoute ?","bareme":[{"critere":"Regrets sur le présent au prétérit (phrases 1 à 3)","points":6},{"critere":"Regrets sur le passé au past perfect (phrases 4 et 5)","points":6},{"critere":"Wish + would pour un changement souhaité","points":4},{"critere":"Phrase en If only correcte et nuance expliquée","points":4}],"dureeMin":10,"corrige":"**1. Réponses**\n1. *I wish I had a dog.*\n2. *I wish I lived near my school.* (*closer to my school* accepté)\n3. *I wish I were good at maths.* (*was* toléré à l'oral, *were* attendu)\n4. *I wish I had gone to the concert last night.*\n5. *I wish I hadn't eaten so much cake yesterday.*\n6. *I wish my neighbours would make less noise.* (*would stop making so much noise* accepté)\n\nPrésent → prétérit ; passé → past perfect ; changement souhaité → *would*. La forme devient positive quand la situation est négative, et inversement.\n\n**2. If only**\n*If only I had gone to the concert!* — même construction que *wish*, mais avec une **charge émotionnelle plus forte** : le regret est plus vif, presque une exclamation."}$exo$::jsonb),
  ('24756952-efd1-5e38-97a5-fc481f3547e1'::uuid, 3, 'traduction', $exo${"titre":"Le journal intime d'Anna","consigne":"Traduis l'extrait en anglais, puis réponds aux questions 2 et 3 en justifiant.","enonce":"**1. Thème : traduis en anglais.**\n\n> Aujourd'hui, j'aimerais rester à la maison. Si seulement je connaissais la réponse à ce problème ! Je regrette d'avoir dit ça à Léo hier. J'aurais dû me taire. Je voudrais tellement qu'il me pardonne…\n\n*Aide : to forgive = pardonner ; to keep quiet = se taire ; so much = tellement.*\n\n**2.** Pour chaque phrase traduite, indique la forme choisie et le moment visé (présent, passé, changement souhaité).\n\n**3.** Pourquoi dit-on *I'd like to stay* et non *I would want to stay* ? Pourquoi *I wish you a happy birthday* ne recule-t-il pas d'un temps ?","bareme":[{"critere":"Would like + to, If only + prétérit, regret + -ING justes","points":5},{"critere":"Should have + participe passé et wish + would justes","points":5},{"critere":"Forme et moment visé identifiés pour chaque phrase","points":5},{"critere":"Explications sur would like et sur wish you","points":3},{"critere":"Correction de la langue","points":2}],"dureeMin":16,"corrige":"**1. Traduction modèle**\n> *Today, I'd like to stay at home. If only I knew the answer to this problem! I regret saying that to Léo yesterday. I should have kept quiet. I wish so much he would forgive me…* (*I really wish he would forgive me* accepté)\n\n**2. Analyse**\n- *I'd like to stay* : **souhait ordinaire**, présent ; *would like* + to.\n- *If only I knew* : regret sur le **présent** → prétérit.\n- *I regret saying* : regret sur le **passé** → *regret* + -ING.\n- *I should have kept quiet* : regret sur le **passé** → *should have* + participe passé.\n- *I wish he would forgive me* : **changement souhaité** → *wish* + *would*.\n\n**3. Explications**\n- *I'd like* est la forme polie attendue du souhait ordinaire ; *I would want* est un calque du français, à éviter.\n- *I wish you a happy birthday* n'exprime pas un **souhait irréel** ni un regret : c'est une formule de vœu (*wish* + personne + nom), la seule construction de *wish* qui ne recule pas d'un temps."}$exo$::jsonb),
  ('db1ec1a7-7bb3-5ae1-a909-0cae5c46516b'::uuid, 1, 'traduction', $exo${"titre":"Du certain à l'impossible","consigne":"Complète chaque phrase avec must, can't ou might, puis corrige la phrase fautive.","enonce":"**1. Complète avec must, can't ou might.**\n\n1. He has worked for ten hours. He ___ be tired. (j'en suis sûr)\n2. Take an umbrella: it ___ rain later. (c'est possible)\n3. She's in Paris today, so she ___ be at home in London. (impossible)\n4. The lights are on: they ___ be at home. (j'en suis sûr)\n5. I don't know where Tom is. He ___ be at the library. (je n'en suis pas sûr)\n\n**2. Corrige :** *He mustn't be serious, it's a joke!* (sens : ça ne peut pas être sérieux)","bareme":[{"critere":"Cinq modaux justes selon le degré de certitude","points":12},{"critere":"Correction en can't, avec la raison (mustn't = interdiction)","points":8}],"dureeMin":7,"corrige":"**1. Réponses**\n1. He **must** be tired — certitude positive.\n2. It **might** rain later — possibilité (*may* ou *could* acceptés).\n3. She **can't** be at home — certitude négative.\n4. They **must** be at home — certitude positive.\n5. He **might** be at the library — doute (*may* accepté).\n\n**2. Correction**\n*He **can't** be serious, it's a joke!* — la négation de la certitude n'est pas *mustn't* mais **can't** (« ce n'est pas possible »). *Mustn't* garde le sens d'**interdiction** : *You mustn't smoke*."}$exo$::jsonb),
  ('db1ec1a7-7bb3-5ae1-a909-0cae5c46516b'::uuid, 2, 'traduction', $exo${"titre":"Qui a mangé le gâteau ?","consigne":"Lis la situation, puis réponds en anglais aux questions en employant un modal de probabilité.","enonce":"Le gâteau d'anniversaire a disparu de la cuisine. Voici les indices :\n\n- Le chien, Max, a de la crème sur le museau.\n- Lily était à l'école toute la journée.\n- Papa aime beaucoup le chocolat, mais il est au travail depuis ce matin… peut-être est-il rentré à midi ?\n- La fenêtre est ouverte.\n\n1. Fais une déduction en anglais sur **chaque** personnage (Max, Lily, Papa), en choisissant entre *must*, *might* et *can't* + *have* + participe passé.\n2. Reformule ta déduction sur Papa avec *probably*, en plaçant correctement l'adverbe.\n3. Traduis : *It's likely to rain, so the window should be closed.*","bareme":[{"critere":"Trois déductions au passé bien construites (modal + have + participe passé)","points":8},{"critere":"Degré de certitude adapté aux indices","points":5},{"critere":"Probably placé après l'auxiliaire, avant le verbe lexical","points":4},{"critere":"Traduction de be likely to et should (forte probabilité)","points":3}],"dureeMin":10,"corrige":"**1. Déductions attendues**\n- Max : *Max must have eaten the cake.* — indice fort (la crème) → certitude positive.\n- Lily : *Lily can't have eaten the cake.* — elle était à l'école → certitude négative.\n- Papa : *Dad might have eaten the cake.* (*may / could have* acceptés) — simple possibilité.\n\n**2. Avec probably**\n*Dad has probably eaten the cake.* ou *Dad probably ate the cake.* — *probably* se place **après l'auxiliaire**, **avant le verbe lexical**. Accepter aussi une déduction contraire justifiée (*Dad probably didn't eat it*).\n\n**3. Traduction**\n« Il va probablement pleuvoir, donc la fenêtre devrait être fermée. » — *be likely to* = probabilité ; *should* = forte probabilité, ce qui est attendu."}$exo$::jsonb),
  ('db1ec1a7-7bb3-5ae1-a909-0cae5c46516b'::uuid, 3, 'traduction', $exo${"titre":"L'enquête de l'inspectrice Wood","consigne":"Lis le texte, puis réponds aux trois questions en justifiant.","enonce":"> The museum was closed at 6 p.m. At 8 p.m., the famous painting had disappeared. The window was broken from the inside. The guard, Mr Hill, says he was asleep. His car was seen near the museum at 7 p.m. The cleaner, Mrs Grey, left at 5 p.m. and took the train to Oxford.\n\n1. Écris **quatre déductions** en anglais de l'inspectrice Wood : deux sur le présent (*He must be…*, *She can't be…*) et deux sur le passé (modal + *have* + participe passé), avec des degrés de certitude différents.\n2. Explique pourquoi on ne peut pas dire *Mrs Grey mustn't have stolen the painting*.\n3. Classe *may*, *must*, *might*, *should*, *can't* du plus sûr au moins sûr, et dis où se trouve *can't* sur cette échelle.","bareme":[{"critere":"Deux déductions au présent correctes et fondées sur le texte","points":4},{"critere":"Deux déductions au passé correctes (modal + have + participe passé)","points":6},{"critere":"Explication can't / mustn't","points":4},{"critere":"Échelle de certitude correcte","points":4},{"critere":"Correction de la langue","points":2}],"dureeMin":17,"corrige":"**1. Exemples de déductions**\n- Présent : *Mr Hill must be the thief.* / *He must be lying.* (sa voiture a été vue) ; *Mrs Grey can't be the thief.* (elle était dans le train).\n- Passé : *The thief must have been inside the museum.* (vitre cassée de l'intérieur) ; *Mrs Grey can't have stolen the painting.* ; *Mr Hill may / might have helped the thief.*\nOn vérifie : modal + *be* ou + *have* + participe passé, et un degré adapté aux indices.\n\n**2. Can't et non mustn't**\n*Mustn't* exprime l'**interdiction** : *Mrs Grey mustn't have stolen* n'a pas de sens de déduction. La négation de la certitude est **can't** : *Mrs Grey can't have stolen the painting* = elle ne peut pas l'avoir volé.\n\n**3. L'échelle**\n*must* (certitude positive) → *should* (forte probabilité) → *may* (possibilité) → *might* (doute plus grand). *Can't* est à l'autre bout : c'est la **certitude négative**, l'impossible."}$exo$::jsonb),
  ('185c647e-17fa-55c6-a661-b4f9b1ac3e97'::uuid, 1, 'traduction', $exo${"titre":"Make ou let ?","consigne":"Complète avec make, made, let ou lets, puis corrige la phrase fautive.","enonce":"**1. Complète.**\n\n1. My parents ___ me do my homework every evening. (ils m'obligent)\n2. My sister ___ me borrow her bike yesterday. (elle m'a autorisé)\n3. The film ___ me cry. (il m'a fait pleurer)\n4. Our teacher ___ us use a calculator. (il nous autorise)\n\n**2. Corrige :** *My mum made me to tidy my room.*","bareme":[{"critere":"Quatre formes justes (sens et temps)","points":12},{"critere":"Correction : make + complément + base verbale, sans to","points":8}],"dureeMin":6,"corrige":"**1. Réponses**\n1. My parents **make** me do — obliger, présent.\n2. My sister **let** me borrow — autoriser ; *let* a la même forme au prétérit.\n3. The film **made** me cry — make = faire (provoquer), prétérit.\n4. Our teacher **lets** us use — autoriser, 3e personne du présent.\n\n**2. Correction**\n*My mum made me tidy my room.* — *make* + complément + **base verbale**, sans *to*. Le *to* ne réapparaît qu'au passif : *I was made to tidy my room*."}$exo$::jsonb),
  ('185c647e-17fa-55c6-a661-b4f9b1ac3e97'::uuid, 2, 'traduction', $exo${"titre":"Les courses de Mme Leroy","consigne":"Réécris chaque phrase avec la structure causative have (ou get), puis traduis les deux phrases de la question 2.","enonce":"Mme Leroy ne fait rien elle-même : elle fait tout faire par des professionnels.\n\n**1. Réécris avec have + complément + participe passé.**\n\na. A hairdresser cut her hair.\nb. A mechanic repaired her car.\nc. A painter painted her kitchen.\nd. Someone fixed her phone. (avec *get*)\n\n**2. Traduis en anglais.**\n\na. J'ai convaincu mon frère de m'aider.\nb. Je me suis fait couper les cheveux samedi.\n\n**3.** Pourquoi *I cut my hair* ne traduit-il pas « je me suis fait couper les cheveux » ?","bareme":[{"critere":"Quatre phrases causatives correctes (have / get + complément + participe passé)","points":8},{"critere":"Get + to pour convaincre, had my hair cut","points":6},{"critere":"Explication du piège I cut my hair","points":4},{"critere":"Correction de la langue","points":2}],"dureeMin":10,"corrige":"**1. Réponses**\na. *She had her hair cut.*\nb. *She had her car repaired.*\nc. *She had her kitchen painted.*\nd. *She got her phone fixed.*\nConstruction : *have / get* + complément + **participe passé**. Le sujet ne fait pas l'action : il la **commande**.\n\n**2. Traduction**\na. *I got my brother to help me.* — *get* + complément + **to** + verbe = convaincre.\nb. *I had my hair cut on Saturday.* (*I got my hair cut* accepté)\n\n**3. Le piège**\n*I cut my hair* signifie que je les ai coupés **moi-même**. « Se faire couper les cheveux » par un coiffeur se dit avec la structure causative : *I had my hair cut*."}$exo$::jsonb),
  ('185c647e-17fa-55c6-a661-b4f9b1ac3e97'::uuid, 3, 'traduction', $exo${"titre":"Le stage de voile","consigne":"Traduis le texte en anglais, puis réponds aux questions 2 et 3 en justifiant.","enonce":"**1. Thème : traduis en anglais.**\n\n> Au stage de voile, le moniteur nous faisait nager tous les matins, mais il nous laissait choisir notre bateau. Un jour, j'ai convaincu mon ami d'essayer le kayak. Ma planche était cassée, alors je l'ai fait réparer.\n\n*Aide : sailing camp = stage de voile ; instructor = moniteur ; board = planche ; to try = essayer.*\n\n**2.** Mets ces deux phrases au passif et explique ce qui change :\na. *The instructor made us swim.*\nb. *The instructor let us choose our boat.*\n\n**3.** Classe *make*, *let*, *have*, *get* selon leur sens (obliger, autoriser, faire faire, convaincre) et indique ce qui suit le complément pour chacun.","bareme":[{"critere":"Make et let + complément + base verbale au prétérit","points":5},{"critere":"Get + to (convaincre) et have + participe passé (faire réparer)","points":5},{"critere":"Passif de make avec to ; let remplacé par be allowed to","points":5},{"critere":"Tableau des quatre verbes juste","points":3},{"critere":"Correction de la langue","points":2}],"dureeMin":16,"corrige":"**1. Traduction modèle**\n> *At the sailing camp, the instructor made us swim every morning, but he let us choose our boat. One day, I got my friend to try the kayak. My board was broken, so I had it repaired.* (*got it repaired* accepté)\n\n**2. Passif**\na. *We were made to swim.* — au passif, **to** réapparaît après *make*.\nb. *We were allowed to choose our boat.* — *let* n'a **pas de passif** : on emploie *be allowed to*.\n\n**3. Tableau**\n- **make** = obliger → complément + **base verbale** ;\n- **let** = autoriser → complément + **base verbale** ;\n- **have** = faire faire par un professionnel → complément + **participe passé** ;\n- **get** = convaincre → complément + **to** + verbe ; ou faire faire (familier) → complément + **participe passé**."}$exo$::jsonb),
  ('80f5d97d-9236-53c0-87eb-9703a7383003'::uuid, 1, 'traduction', $exo${"titre":"Les verbes à particule du brevet","consigne":"Complète chaque phrase avec le verbe qui convient, à la bonne forme.","enonce":"**Complète avec : give up, look after, look for, put on, find out, get up, run out of, grow up.**\n\n1. I ___ at 7 every morning.\n2. It's cold: ___ your coat!\n3. My grandma ___ my little sister on Wednesdays.\n4. I'm ___ my keys. Have you seen them?\n5. Don't ___! You can do it!\n6. We have ___ milk: can you buy some?\n7. I want to ___ the truth.\n8. She wants to be a vet when she ___.\n\n**Question :** pourquoi *look after* ne se traduit-il pas par « regarder après » ?","bareme":[{"critere":"Huit verbes justes et bien conjugués","points":16},{"critere":"Explication : le sens n'est pas la somme des deux mots","points":4}],"dureeMin":7,"corrige":"**Réponses**\n1. I **get up** at 7.\n2. **Put on** your coat! (*Put your coat on!*)\n3. My grandma **looks after** my little sister — 3e personne : -s.\n4. I'm **looking for** my keys.\n5. Don't **give up**!\n6. We have **run out of** milk.\n7. I want to **find out** the truth.\n8. when she **grows up**.\n\n**Explication**\nLe sens d'un verbe à particule ou prépositionnel n'est presque jamais la somme de ses deux mots : *look after* signifie « s'occuper de ». Ces verbes s'apprennent comme des **mots de vocabulaire entiers**."}$exo$::jsonb),
  ('80f5d97d-9236-53c0-87eb-9703a7383003'::uuid, 2, 'traduction', $exo${"titre":"La place du pronom","consigne":"Remplace le nom souligné par un pronom et réécris la phrase, puis réponds à la question 2.","enonce":"**1. Remplace le complément en gras par un pronom (it, them, her…).**\n\n1. Turn on **the light**.\n2. Take off **your shoes**.\n3. Look after **your sister**.\n4. Put on **your jacket**.\n5. Listen to **the teacher**. (*him*)\n6. Look up **these words** in the dictionary.\n\n**2.** Pour les phrases 1 et 3, dis s'il s'agit d'un verbe **à particule** ou d'un verbe **prépositionnel**, et explique le test qui permet de le savoir.","bareme":[{"critere":"Pronom placé avant la particule pour les verbes à particule","points":8},{"critere":"Pronom placé après la préposition pour les verbes prépositionnels","points":5},{"critere":"Nature des verbes 1 et 3 identifiée","points":3},{"critere":"Test de séparation expliqué","points":4}],"dureeMin":10,"corrige":"**1. Réponses**\n1. *Turn **it** on.* — jamais *turn on it*.\n2. *Take **them** off.*\n3. *Look after **her**.* — préposition : le pronom reste après.\n4. *Put **it** on.*\n5. *Listen to **him**.*\n6. *Look **them** up in the dictionary.*\n\nAvec un verbe **à particule**, un pronom se place **obligatoirement avant** la particule. Avec un verbe **prépositionnel**, le complément (nom ou pronom) est **toujours après** la préposition.\n\n**2. Le test**\n- *Turn on* : verbe **à particule** — on peut dire *turn the light on*.\n- *Look after* : verbe **prépositionnel** — on ne peut pas dire *look your sister after*.\nSi le complément peut se glisser entre le verbe et le petit mot, c'est une particule ; sinon, c'est une préposition."}$exo$::jsonb),
  ('80f5d97d-9236-53c0-87eb-9703a7383003'::uuid, 3, 'traduction', $exo${"titre":"Le premier voyage de Jules","consigne":"Lis le texte, traduis-le, puis réponds aux questions 2 et 3.","enonce":"> Jules got up at 5 a.m. He put on his jacket and looked for his passport. At the airport, he waited for his friends. The plane took off at 8. Jules was looking forward to seeing London. When he arrived, his phone had run out of battery, so he couldn't find out where his hotel was. But he didn't give up!\n\n1. Traduis le texte en français.\n2. Relève **deux verbes à particule** et **deux verbes prépositionnels**, et justifie ton classement avec le test du cours.\n3. Réécris deux phrases du texte en remplaçant le complément du verbe à particule par un pronom. Explique la règle de position.","bareme":[{"critere":"Traduction juste du sens de chaque verbe composé","points":7},{"critere":"Deux verbes à particule et deux prépositionnels bien classés","points":4},{"critere":"Classement justifié par le test de séparation","points":3},{"critere":"Deux réécritures avec pronom avant la particule, règle expliquée","points":4},{"critere":"Qualité du français","points":2}],"dureeMin":17,"corrige":"**1. Traduction modèle**\n> Jules s'est levé à 5 h. Il a mis sa veste et a cherché son passeport. À l'aéroport, il a attendu ses amis. L'avion a décollé à 8 h. Jules avait hâte de voir Londres. Quand il est arrivé, son téléphone n'avait plus de batterie, alors il n'a pas pu découvrir où était son hôtel. Mais il n'a pas abandonné !\n\nPoints de sens : *got up* = s'est levé ; *put on* = a mis (vêtement) ; *looked for* = a cherché ; *waited for* = a attendu ; *took off* = a décollé ; *looking forward to* = avait hâte de (suivi de -ING) ; *run out of* = être à court de ; *find out* = découvrir ; *give up* = abandonner.\n\n**2. Classement**\n- À particule : *put on*, *find out* (aussi *get up*, *take off*, *give up*) — on peut dire *put his jacket on*.\n- Prépositionnels : *look for*, *wait for* — impossible de dire *waited his friends for*.\n\n**3. Réécritures**\n- *He put it on.* — jamais *put on it*.\n- *He couldn't find it out.* (phrase possible, même si l'on garde plutôt le nom ici).\nRègle : avec un verbe à particule, un **pronom** se place **obligatoirement avant** la particule ; un nom peut se placer avant ou après."}$exo$::jsonb),
  ('7e69bddd-5a2b-5660-9cce-dfac7a3f143f'::uuid, 1, 'traduction', $exo${"titre":"To + verbe ou -ING ?","consigne":"Mets le verbe entre parenthèses à la bonne forme (to + verbe, -ING ou base verbale).","enonce":"**Mets le verbe à la bonne forme.**\n\n1. I enjoy (read) comics.\n2. She decided (leave) early.\n3. You must (go) now.\n4. He left without (say) goodbye.\n5. I hope (see) you soon.\n6. We finished (work) at six.\n7. I avoid (eat) sugar.\n8. I'm looking forward to (meet) you.\n\n**Question :** pourquoi *look forward to* est-il suivi de -ING malgré son « to » ?","bareme":[{"critere":"Huit verbes à la bonne forme","points":16},{"critere":"Explication : to est ici une préposition","points":4}],"dureeMin":7,"corrige":"**Réponses**\n1. I enjoy **reading** — *enjoy* + -ING.\n2. She decided **to leave** — *decide* + to.\n3. You must **go** — après un modal : base verbale.\n4. without **saying** — après une préposition : -ING.\n5. I hope **to see** — *hope* + to.\n6. We finished **working** — *finish* + -ING.\n7. I avoid **eating** — *avoid* + -ING.\n8. looking forward to **meeting** — -ING.\n\n**Explication**\nDans *look forward to*, *to* n'est pas la marque de l'infinitif mais une **préposition** (comme dans *I look forward to the holidays*). Or, après une préposition, le verbe se met toujours en **-ING**."}$exo$::jsonb),
  ('7e69bddd-5a2b-5660-9cce-dfac7a3f143f'::uuid, 2, 'traduction', $exo${"titre":"Stop, remember, try","consigne":"Traduis chaque paire de phrases en français, puis complète les phrases de la question 2.","enonce":"**1. Traduis en français et explique la différence de sens.**\n\na. *He stopped to smoke.* / *He stopped smoking.*\nb. *Remember to lock the door.* / *I remember locking the door.*\nc. *Try to open the window.* / *Try opening the window.*\n\n**2. Complète avec la bonne forme.**\n\n1. Grandpa is healthier since he stopped (drink) coffee.\n2. Did you remember (buy) bread?\n3. I went to the library (study).\n4. It's too hot. Try (open) the window, it might help.","bareme":[{"critere":"Trois paires traduites avec la bonne nuance","points":9},{"critere":"Quatre blancs justes","points":8},{"critere":"Infinitif de but avec to (et non for)","points":3}],"dureeMin":10,"corrige":"**1. Traductions**\na. « Il s'est arrêté **pour** fumer. » / « Il a **arrêté de** fumer. »\nb. « **Pense à** fermer la porte à clé. » (action à faire) / « Je **me souviens d'avoir** fermé la porte à clé. » (action déjà faite)\nc. « **Essaie d'**ouvrir la fenêtre. » (effort, peut-être difficile) / « Essaie **en** ouvrant la fenêtre, pour voir. » (tester une solution)\n\n**2. Réponses**\n1. since he stopped **drinking** coffee — il a arrêté d'en boire.\n2. Did you remember **to buy** bread? — penser à faire.\n3. I went to the library **to study** — infinitif de but ; jamais *for studying*.\n4. Try **opening** the window — essayer pour voir si ça aide."}$exo$::jsonb),
  ('7e69bddd-5a2b-5660-9cce-dfac7a3f143f'::uuid, 3, 'traduction', $exo${"titre":"Le projet de Nina","consigne":"Traduis le texte en anglais, puis justifie quatre de tes choix.","enonce":"**1. Thème : traduis en anglais.**\n\n> Nina veut devenir pilote. Elle adore voyager et elle a appris à piloter l'an dernier. Elle est douée pour parler aux gens, mais elle déteste attendre. La semaine dernière, elle est allée à l'aéroport pour rencontrer un vrai pilote. Il lui a promis de l'aider. Elle a hâte de voler seule !\n\n*Aide : to fly = piloter / voler ; to become = devenir ; alone = seule ; she is good at = elle est douée pour.*\n\n**2.** Justifie la forme du verbe après : *want*, *good at*, *to meet* (pour rencontrer), *look forward to*.","bareme":[{"critere":"Verbes + to justes (want, learn, promise)","points":5},{"critere":"Verbes + -ING justes (love, hate, look forward to)","points":5},{"critere":"-ING après préposition et infinitif de but","points":3},{"critere":"Quatre justifications exactes","points":5},{"critere":"Correction générale de la langue","points":2}],"dureeMin":16,"corrige":"**1. Traduction modèle**\n> *Nina wants to become a pilot. She loves travelling and she learnt to fly last year. She is good at talking to people, but she hates waiting. Last week, she went to the airport to meet a real pilot. He promised to help her. She is looking forward to flying alone!*\n(*learned* et *traveling* acceptés ; *loves to travel* accepté car *love* admet les deux, mais -ING est la forme du cours.)\n\n**2. Justifications**\n- *want* + **to** + verbe : *want* fait partie des verbes suivis de l'infinitif (comme decide, hope, promise, learn).\n- *good at* + **-ING** : *at* est une **préposition** ; après une préposition, toujours -ING.\n- *to meet* : **infinitif de but** (« pour rencontrer ») → *to* ou *in order to* ; jamais *for meeting*.\n- *look forward to* + **-ING** : *to* y est une préposition, pas la marque de l'infinitif."}$exo$::jsonb),
  ('7be97ad8-b4f5-5493-8d98-e0f8ac226e31'::uuid, 1, 'traduction', $exo${"titre":"Former les adverbes","consigne":"Donne l'adverbe correspondant à chaque adjectif, puis corrige la phrase fautive.","enonce":"**1. Donne l'adverbe.**\n\nslow · careful · happy · simple · good · fast · hard · late\n\n**2. Corrige :** *She speaks very good English and she sings good.*\n\n**3.** Que signifient *hardly* et *lately* ?","bareme":[{"critere":"Huit adverbes justes, irréguliers compris","points":12},{"critere":"Phrase corrigée (sings well)","points":4},{"critere":"Sens de hardly et lately","points":4}],"dureeMin":6,"corrige":"**1. Adverbes**\n- slow → **slowly**\n- careful → **carefully**\n- happy → **happily** (-y → -ily)\n- simple → **simply** (-le → -ly)\n- good → **well** (irrégulier)\n- fast → **fast** (identique)\n- hard → **hard** (identique)\n- late → **late** (identique)\n\n**2. Correction**\n*She speaks very good English and she sings **well**.* — *good English* est juste (adjectif devant un nom) ; mais pour modifier le verbe *sings*, il faut l'adverbe **well**.\n\n**3. Pièges**\n- *hardly* = **à peine** (pas « durement ») ;\n- *lately* = **récemment** (pas « tardivement »)."}$exo$::jsonb),
  ('7be97ad8-b4f5-5493-8d98-e0f8ac226e31'::uuid, 2, 'traduction', $exo${"titre":"Les habitudes de Farah","consigne":"Place l'adverbe entre parenthèses au bon endroit, puis réponds à la question 2.","enonce":"**1. Réécris chaque phrase avec l'adverbe à sa place.**\n\n1. Farah gets up early. (always)\n2. She is late. (never)\n3. She has been to Spain. (never)\n4. She plays tennis on Saturdays. (usually)\n5. She doesn't run fast. (enough → après l'adjectif / adverbe)\n6. She is tired after school. (very)\n\n**2.** Remets les compléments dans l'ordre habituel : *She sang (last night / at the concert / beautifully).* Donne la règle.","bareme":[{"critere":"Adverbes de fréquence placés avant le verbe lexical, après be ou l'auxiliaire","points":10},{"critere":"Enough après, very devant l'adjectif","points":4},{"critere":"Ordre manière, lieu, temps rétabli et règle donnée","points":6}],"dureeMin":10,"corrige":"**1. Réponses**\n1. *Farah always gets up early.* — avant le verbe lexical.\n2. *She is never late.* — après *be*.\n3. *She has never been to Spain.* — après l'auxiliaire.\n4. *She usually plays tennis on Saturdays.* — avant le verbe lexical.\n5. *She doesn't run fast enough.* — *enough* après l'adverbe / l'adjectif.\n6. *She is very tired after school.* — adverbe de degré devant l'adjectif.\n\n**2. Ordre**\n*She sang beautifully at the concert last night.* — ordre habituel en fin de phrase : **manière → lieu → temps**."}$exo$::jsonb),
  ('7be97ad8-b4f5-5493-8d98-e0f8ac226e31'::uuid, 3, 'traduction', $exo${"titre":"La critique de concert","consigne":"Lis le texte, corrige les fautes en justifiant, puis traduis les deux phrases de la question 3.","enonce":"> Last night, the band played very good. The singer sang loud the songs and the guitarist always was smiling. I could hard hear the drums, because I was at the back. The concert finished lately, at midnight. I have been to concerts often, but this one was really amazing!\n\n1. Le texte contient **six fautes** sur les adverbes. Relève-les et corrige-les.\n2. Justifie chaque correction par la règle du cours.\n3. Traduis : a) *I have hardly slept lately.* b) *She works hard and she is never late.*","bareme":[{"critere":"Six fautes relevées et corrigées","points":7},{"critere":"Justifications (irréguliers, place, sens de hardly / lately)","points":6},{"critere":"Traductions justes de hardly, lately, hard, late","points":5},{"critere":"Qualité de la rédaction","points":2}],"dureeMin":16,"corrige":"**1 et 2. Les six fautes**\n- *played very good* → **played very well** : l'adverbe de *good* est *well*.\n- *sang loud the songs* → **sang the songs loudly** (ou *loud*) : on n'intercale jamais un adverbe entre le verbe et son complément d'objet.\n- *always was smiling* → **was always smiling** : l'adverbe de fréquence se place **après** *be* / l'auxiliaire.\n- *could hard hear* → **could hardly hear** : « à peine » = *hardly* ; *hard* = dur.\n- *finished lately* → **finished late** : *late* reste identique ; *lately* signifie « récemment ».\n- *I have been to concerts often* → **I have often been to concerts** : fréquence entre l'auxiliaire et le participe passé.\n\n**3. Traductions**\na) « J'ai **à peine** dormi **ces derniers temps**. » (récemment)\nb) « Elle travaille **dur** et elle n'est **jamais en retard**. » — *hard* et *late* adverbes identiques à l'adjectif."}$exo$::jsonb),
  ('791a8ecf-17f0-593e-a963-c5f318cff75b'::uuid, 1, 'traduction', $exo${"titre":"Habituel ou en cours ?","consigne":"Mets le verbe au présent simple ou au présent en BE + -ING.","enonce":"**Mets le verbe à la bonne forme.**\n\n1. Look! It (rain).\n2. My brother (study) English every day.\n3. Water (boil) at 100 °C.\n4. Be quiet, I (do) my homework.\n5. She (not / like) fish.\n6. I (know) the answer.\n7. We (meet) Tom tonight at 8. (c'est organisé)\n8. He (watch) TV every evening.\n\n**Question :** pourquoi ne peut-on pas dire *I am knowing* ?","bareme":[{"critere":"Huit formes justes (temps, 3e personne, orthographe)","points":16},{"critere":"Explication des verbes d'état","points":4}],"dureeMin":7,"corrige":"**Réponses**\n1. It **is raining** — action en cours (*Look!*).\n2. My brother **studies** — habitude ; consonne + y → -ies.\n3. Water **boils** — vérité générale.\n4. I **am doing** — en cours.\n5. She **doesn't like** — présent simple, négation avec *doesn't*.\n6. I **know** — verbe d'état.\n7. We **are meeting** — projet organisé.\n8. He **watches** — habitude ; -ch → -es.\n\n**Explication**\n*Know* est un **verbe d'état** (comme like, love, want, need, understand, believe) : il n'accepte pas la forme en -ING. On dit *I know*, jamais *I am knowing*."}$exo$::jsonb),
  ('791a8ecf-17f0-593e-a963-c5f318cff75b'::uuid, 2, 'traduction', $exo${"titre":"La carte postale d'Ilan","consigne":"Conjugue les verbes entre parenthèses, puis justifie trois choix.","enonce":"> Dear Grandma,\n> I (1. write) to you from Edinburgh! I (2. stay) with my aunt this week. Every morning, she (3. go) to work by bike and I (4. visit) the city. Right now, it (5. rain) and my cousin (6. play) the piano. He (7. play) every day! Tonight we (8. have) dinner at a restaurant: my aunt booked a table. I (9. love) this city!\n> Ilan\n\n1. Conjugue les neuf verbes.\n2. Justifie les formes 2, 3 et 9.","bareme":[{"critere":"Formes en BE + -ING justes (en cours, temporaire, projet)","points":7},{"critere":"Présents simples justes, orthographe de la 3e personne","points":6},{"critere":"Verbe d'état love au présent simple","points":2},{"critere":"Trois justifications exactes","points":5}],"dureeMin":10,"corrige":"**1. Réponses**\n(1) **am writing** — en cours.\n(2) **am staying** — situation temporaire.\n(3) **goes** — habitude ; -o → -es.\n(4) **visit** — habitude.\n(5) **is raining** — en cours (*right now*).\n(6) **is playing** — en cours.\n(7) **plays** — habitude (*every day*).\n(8) **are having** — projet organisé.\n(9) **love** — verbe d'état.\n\n**2. Justifications**\n- (2) *this week* : une situation **temporaire** → BE + -ING.\n- (3) *every morning* : une **habitude** → présent simple, -es à la 3e personne.\n- (9) *love* est un **verbe d'état** : jamais à la forme en -ING."}$exo$::jsonb),
  ('791a8ecf-17f0-593e-a963-c5f318cff75b'::uuid, 3, 'traduction', $exo${"titre":"Le colocataire agaçant","consigne":"Traduis le texte en anglais, puis réponds à la question 2.","enonce":"**1. Thème : traduis en anglais.**\n\n> Mon frère aîné vit à Manchester. Il travaille dans une banque, mais ce mois-ci il travaille à Londres. D'habitude, il se lève à 7 h. En ce moment, il cherche un appartement. Son colocataire perd toujours ses clés, c'est énervant ! Samedi, nous prenons le train pour aller le voir : les billets sont achetés. Le train part à 9 h 15.\n\n*Aide : flatmate = colocataire ; flat = appartement ; to look for = chercher.*\n\n**2.** Pour cinq verbes de ta traduction, nomme le temps choisi et l'emploi du cours qui le justifie (habitude, état permanent, temporaire, en cours, projet organisé, programme fixe, agacement).","bareme":[{"critere":"Présent simple pour l'état permanent, l'habitude et l'horaire","points":5},{"critere":"BE + -ING pour le temporaire, l'action en cours et le projet organisé","points":5},{"critere":"Always + BE + -ING pour l'agacement","points":3},{"critere":"Cinq justifications exactes","points":5},{"critere":"Correction de la langue","points":2}],"dureeMin":17,"corrige":"**1. Traduction modèle**\n> *My older brother lives in Manchester. He works in a bank, but this month he is working in London. He usually gets up at 7. At the moment, he is looking for a flat. His flatmate is always losing his keys, it's annoying! On Saturday, we are taking the train to see him: the tickets are bought. The train leaves at 9.15.*\n\n**2. Justifications attendues**\n- *lives*, *works in a bank* : **état permanent** → présent simple.\n- *is working in London* (*this month*) : situation **temporaire** → BE + -ING.\n- *usually gets up* : **habitude** → présent simple.\n- *is looking for* (*at the moment*) : action **en cours** → BE + -ING.\n- *is always losing* : *always* + BE + -ING → **agacement**.\n- *are taking the train* : **projet organisé** (billets achetés) → BE + -ING.\n- *leaves at 9.15* : **programme fixe**, horaire → présent simple.\nCinq justifications suffisent."}$exo$::jsonb),
  ('2fef5a53-98ef-5244-8993-d4d712f5c6bc'::uuid, 1, 'traduction', $exo${"titre":"Le prétérit : formes et négation","consigne":"Donne le prétérit de chaque verbe, puis mets les deux phrases à la forme négative.","enonce":"**1. Donne le prétérit.**\n\nwork · live · study · stop · go · see · take · play\n\n**2. Mets à la forme négative.**\n\na. I went to school yesterday.\nb. She saw the film last week.\n\n**3.** Corrige : *I have seen him yesterday.*","bareme":[{"critere":"Huit prétérits justes (réguliers, orthographe, irréguliers)","points":10},{"critere":"Deux négations avec didn't + base verbale","points":6},{"critere":"Correction avec prétérit à cause du repère passé","points":4}],"dureeMin":7,"corrige":"**1. Prétérits**\n- work → **worked** ; live → **lived** (-e → -d) ; study → **studied** (consonne + y → -ied) ; stop → **stopped** (consonne doublée) ; play → **played** (voyelle + y).\n- Irréguliers : go → **went** ; see → **saw** ; take → **took**.\n\n**2. Négations**\na. *I didn't go to school yesterday.*\nb. *She didn't see the film last week.*\n*Did* porte le passé : le verbe revient à la base verbale.\n\n**3. Correction**\n*I saw him yesterday.* — un repère passé précis (*yesterday*) impose le **prétérit**, jamais le present perfect."}$exo$::jsonb),
  ('2fef5a53-98ef-5244-8993-d4d712f5c6bc'::uuid, 2, 'traduction', $exo${"titre":"Le week-end de Chloé","consigne":"Conjugue les verbes au prétérit simple, puis pose deux questions sur le texte.","enonce":"> Last Saturday, Chloé (1. wake up) at 8. She (2. have) breakfast, (3. take) her bike and (4. ride) to the lake. She (5. meet) her friends there. They (6. swim) and (7. play) volleyball. At 6, they (8. not / want) to go home! When she (9. get) home, she (10. be) very tired.\n\n1. Conjugue les dix verbes.\n2. Pose deux questions sur le texte (au prétérit, avec *did* ou avec *be*).","bareme":[{"critere":"Prétérits irréguliers justes","points":9},{"critere":"Prétérits réguliers et négation justes","points":5},{"critere":"Deux questions correctes (did + base verbale, ou was / were)","points":6}],"dureeMin":10,"corrige":"**1. Réponses**\n(1) **woke up** · (2) **had** · (3) **took** · (4) **rode** · (5) **met** · (6) **swam** · (7) **played** · (8) **didn't want** · (9) **got** · (10) **was**.\nUne suite d'actions passées, datées (*Last Saturday*), se raconte au prétérit simple ; même forme à toutes les personnes, sauf *be* (*was / were*).\n\n**2. Exemples de questions**\n- *What time did Chloé wake up?* — *did* + base verbale.\n- *Where did she ride to?* / *Did they swim in the lake?*\n- *Was she tired when she got home?* — avec *be*, sans *did*.\nPénaliser *Did she took…?* ou *Did she was…?*"}$exo$::jsonb),
  ('2fef5a53-98ef-5244-8993-d4d712f5c6bc'::uuid, 3, 'traduction', $exo${"titre":"Quand grand-père était jeune","consigne":"Traduis le texte, corrige les fautes du document 2, puis réponds à la question 3.","enonce":"**1. Thème : traduis en anglais.**\n\n> Quand il était jeune, mon grand-père habitait à la campagne. Autrefois, il allait à l'école à pied, mais aujourd'hui il ne marche plus beaucoup. Il y a soixante ans, il a rencontré ma grand-mère. Ils se sont mariés en 1968.\n\n*Aide : countryside = campagne ; to get married = se marier.*\n\n**2. Corrige ces phrases d'un élève et justifie.**\n\n> a. My grandpa has met my grandma in 1966.\n> b. Did they lived on a farm?\n> c. He use to play football.\n\n**3.** Classe ces verbes selon la prononciation de -ed ([t], [d] ou [ɪd]) : *worked, played, wanted, needed, walked, lived*.","bareme":[{"critere":"Prétérits justes avec repères passés (ago, in 1968)","points":5},{"critere":"Used to + base verbale pour l'habitude révolue","points":4},{"critere":"Trois corrections justes et justifiées","points":6},{"critere":"Classement de la prononciation de -ed","points":3},{"critere":"Correction de la langue","points":2}],"dureeMin":16,"corrige":"**1. Traduction modèle**\n> *When he was young, my grandfather lived in the countryside. He used to walk to school, but today he doesn't walk much. Sixty years ago, he met my grandmother. They got married in 1968.*\n(*He used to go to school on foot* accepté.)\n\n**2. Corrections**\na. *My grandpa **met** my grandma in 1966.* — date précise (*in 1966*) → prétérit, jamais present perfect.\nb. *Did they **live** on a farm?* — *did* porte le passé : base verbale.\nc. *He **used** to play football.* — *used to* + base verbale ; au négatif ou en question : *didn't use to*.\n\n**3. Prononciation de -ed**\n- [t] (son final sourd) : *worked*, *walked*.\n- [d] (son final sonore) : *played*, *lived*.\n- [ɪd] (après t ou d) : *wanted*, *needed*."}$exo$::jsonb),
  ('3055a332-e131-5e86-9f5c-31f982d631fc'::uuid, 1, 'traduction', $exo${"titre":"Was / were + -ING","consigne":"Mets le verbe au prétérit en BE + -ING, puis mets la phrase 5 à la forme négative et interrogative.","enonce":"**1. Mets au prétérit en BE + -ING.**\n\n1. At 8 o'clock last night, I (watch) TV.\n2. They (play) football in the park.\n3. She (read) when the phone rang.\n4. We (walk) home when it started to rain.\n5. You (work) at 10 a.m.\n\n**2.** Phrase 5 : forme négative, puis forme interrogative.","bareme":[{"critere":"Cinq formes justes (was / were accordé au sujet + -ING)","points":12},{"critere":"Négation et question correctes","points":8}],"dureeMin":6,"corrige":"**1. Réponses**\n1. I **was watching** TV — action en cours à un moment précis.\n2. They **were playing** football.\n3. She **was reading** when the phone rang — le décor, interrompu.\n4. We **were walking** home when it started to rain.\n5. You **were working** at 10 a.m.\n\n*Was* avec I / he / she / it ; *were* avec you / we / they.\n\n**2. Phrase 5**\n- Négative : *You weren't working at 10 a.m.* (*were not*)\n- Interrogative : *Were you working at 10 a.m.?*\nPas de *did* : l'auxiliaire *be* construit seul la question et la négation."}$exo$::jsonb),
  ('3055a332-e131-5e86-9f5c-31f982d631fc'::uuid, 2, 'traduction', $exo${"titre":"When ou while ?","consigne":"Relie les deux actions en une seule phrase avec when ou while, en choisissant le bon temps pour chaque verbe.","enonce":"**1. Relie les deux actions en une phrase.**\n\n1. I / have a shower — the phone / ring (when)\n2. She / cook — he / do his homework (while)\n3. We / sleep — the storm / start (when)\n4. The children / play — their parents / talk (while)\n5. Tom / cross the street — he / see an accident (when)\n\n**2.** Explique la différence entre *I watched a film last night* et *I was watching a film last night*.","bareme":[{"critere":"Décor au prétérit en BE + -ING","points":6},{"critere":"Événement au prétérit simple avec when","points":5},{"critere":"Deux actions simultanées en -ING avec while","points":4},{"critere":"Différence film fini / non fini expliquée","points":5}],"dureeMin":10,"corrige":"**1. Réponses**\n1. *I was having a shower when the phone rang.*\n2. *She was cooking while he was doing his homework.*\n3. *We were sleeping when the storm started.*\n4. *The children were playing while their parents were talking.*\n5. *Tom was crossing the street when he saw an accident.*\n\nCe qui **encadre** (le décor, action longue) est en BE + -ING ; ce qui **survient** (l'événement, action courte) est au prétérit simple, introduit par **when**. Deux actions **simultanées** sont toutes deux en -ING, reliées par **while**.\n\n**2. La différence**\n*I watched a film* : le film est **fini**, je l'ai vu jusqu'au bout. *I was watching a film* : je décris une action **en cours** ; on ne sait pas si je suis allé au bout."}$exo$::jsonb),
  ('3055a332-e131-5e86-9f5c-31f982d631fc'::uuid, 3, 'traduction', $exo${"titre":"La panne de courant","consigne":"Traduis le récit en anglais, puis réponds à la question 2 en justifiant.","enonce":"**1. Thème : traduis en anglais.**\n\n> Il était 21 h. Mon père lisait le journal pendant que ma mère préparait le dîner. Ma sœur et moi, nous jouions aux cartes. Soudain, la lumière s'est éteinte. Nous ne savions pas quoi faire. Pendant que je cherchais une lampe de poche, mon chat a sauté sur la table.\n\n*Aide : suddenly = soudain ; the lights went out = la lumière s'est éteinte ; torch = lampe de poche ; to jump = sauter.*\n\n**2.** Relève dans ta traduction : a) deux actions de décor ; b) deux événements ; c) le verbe que tu n'as pas pu mettre en -ING, et explique pourquoi.","bareme":[{"critere":"Décor et actions simultanées en was / were + -ING","points":6},{"critere":"Événements au prétérit simple (went out, jumped)","points":4},{"critere":"Verbe d'état know au prétérit simple","points":2},{"critere":"Repérage décor / événement / verbe d'état justifié","points":6},{"critere":"Correction de la langue","points":2}],"dureeMin":16,"corrige":"**1. Traduction modèle**\n> *It was 9 p.m. My father was reading the newspaper while my mother was cooking dinner. My sister and I were playing cards. Suddenly, the lights went out. We didn't know what to do. While I was looking for a torch, my cat jumped on the table.*\n(*preparing dinner* et *flashlight* acceptés.)\n\n**2. Repérage**\na) Décor : *was reading*, *was cooking*, *were playing*, *was looking for* — actions longues qui **encadrent** la scène, en BE + -ING ; *while* relie les actions simultanées.\nb) Événements : *went out*, *jumped* — actions courtes qui **surviennent**, au prétérit simple.\nc) *didn't know* : *know* est un **verbe d'état**, il n'accepte pas -ING (*we were knowing* est faux)."}$exo$::jsonb),
  ('9d02a039-f2ca-5e68-affe-5f4f34deabb6'::uuid, 1, 'traduction', $exo${"titre":"For ou since ?","consigne":"Complète avec for ou since, puis mets les verbes au present perfect.","enonce":"**1. Complète avec for ou since.**\n\n1. I have lived here ___ five years.\n2. She has worked here ___ 2020.\n3. We have waited ___ two hours.\n4. He has known her ___ Monday.\n5. They have been friends ___ they were ten.\n\n**2. Mets au present perfect.**\n\na. I (lose) my keys.\nb. She (never / be) to Japan.\nc. (you / finish) your homework yet?","bareme":[{"critere":"Cinq choix for / since justes","points":10},{"critere":"Trois present perfect bien formés, marqueurs bien placés","points":10}],"dureeMin":7,"corrige":"**1. Réponses**\n1. **for** five years — durée.\n2. **since** 2020 — point de départ.\n3. **for** two hours — durée.\n4. **since** Monday — point de départ.\n5. **since** they were ten — point de départ.\n\n**2. Present perfect** (*have / has* + participe passé)\na. *I have lost my keys.* — résultat présent : je ne les ai toujours pas.\nb. *She has never been to Japan.* — *never* entre l'auxiliaire et le participe passé.\nc. *Have you finished your homework yet?* — *yet* en fin de phrase, dans une question."}$exo$::jsonb),
  ('9d02a039-f2ca-5e68-affe-5f4f34deabb6'::uuid, 2, 'traduction', $exo${"titre":"Le blog de Lucie","consigne":"Conjugue chaque verbe au present perfect ou au prétérit, puis justifie trois choix.","enonce":"> I (1. live) in Dublin since 2023. I love it! I (2. visit) the castle last weekend. I (3. never / see) such a beautiful city. Two days ago, I (4. meet) a famous singer in a café. I (5. just / finish) my first book in English. My parents (6. come) to see me in May. I (7. not / find) a job yet.\n\n1. Conjugue les sept verbes.\n2. Justifie tes choix pour les verbes 1, 2 et 3.","bareme":[{"critere":"Present perfect justes (since, never, just, yet)","points":7},{"critere":"Prétérits justes avec repères passés précis","points":6},{"critere":"Place des marqueurs just, never, yet","points":2},{"critere":"Trois justifications exactes","points":5}],"dureeMin":10,"corrige":"**1. Réponses**\n(1) **have lived** — action commencée dans le passé qui continue (*since 2023*).\n(2) **visited** — repère précis (*last weekend*).\n(3) **have never seen** — expérience de vie.\n(4) **met** — *two days ago*.\n(5) **have just finished** — *just* entre auxiliaire et participe.\n(6) **came** — *in May* (date passée).\n(7) **haven't found** — *yet* en fin de phrase négative.\n\n**2. Justifications**\n- (1) *since 2023* : l'action dure encore → present perfect (le français dit « j'habite depuis »).\n- (2) *last weekend* est un repère passé **précis** → prétérit obligatoire.\n- (3) expérience de vie, **sans date**, avec *never* → present perfect."}$exo$::jsonb),
  ('9d02a039-f2ca-5e68-affe-5f4f34deabb6'::uuid, 3, 'traduction', $exo${"titre":"Entretien pour un job d'été","consigne":"Traduis l'entretien en anglais, puis réponds à la question 2.","enonce":"**1. Thème : traduis en anglais.**\n\n> **Le recruteur** : Avez-vous déjà travaillé dans un restaurant ?\n> **Maxime** : Oui. L'été dernier, j'ai travaillé dans un café à Nice. J'apprends l'anglais depuis quatre ans et je suis allé en Irlande deux fois.\n> **Le recruteur** : Avez-vous déjà rempli le formulaire ?\n> **Maxime** : Je viens de le terminer, mais je n'ai pas encore envoyé mon CV.\n\n*Aide : form = formulaire ; to fill in = remplir ; to send (sent) = envoyer ; CV = CV.*\n\n**2.** Justifie le temps de quatre verbes et la place de trois marqueurs (*ever*, *just*, *yet*).","bareme":[{"critere":"Present perfect justes (ever, for, twice, just, yet)","points":6},{"critere":"Prétérit avec last summer","points":3},{"critere":"Marqueurs bien placés","points":3},{"critere":"Justifications des temps et des places","points":6},{"critere":"Correction de la langue","points":2}],"dureeMin":17,"corrige":"**1. Traduction modèle**\n> **Recruiter:** *Have you ever worked in a restaurant?*\n> **Maxime:** *Yes. Last summer, I worked in a café in Nice. I have learnt English for four years and I have been to Ireland twice.*\n> **Recruiter:** *Have you filled in the form yet?* (*already* accepté)\n> **Maxime:** *I have just finished it, but I haven't sent my CV yet.*\n(*I have been learning English for four years* accepté.)\n\n**2. Justifications**\n- *Have you ever worked* : **expérience de vie**, sans date → present perfect.\n- *worked last summer* : repère passé **précis** → prétérit.\n- *have learnt… for four years* : action commencée dans le passé qui **continue** ; *for* + durée. Le français dit « depuis » au présent, l'anglais emploie le present perfect.\n- *have been to Ireland twice* : expérience, sans date.\n- *have just finished* : passé récent, résultat présent.\nPlaces : *ever* et *just* entre l'auxiliaire et le participe passé ; *yet* en **fin de phrase**, dans les questions et les négations."}$exo$::jsonb),
  ('bfd40b71-74c1-5bb4-9270-f8341862c0ca'::uuid, 1, 'traduction', $exo${"titre":"Le passé du passé","consigne":"Mets le verbe entre parenthèses au past perfect, puis réponds à la question 2.","enonce":"**1. Mets au past perfect.**\n\n1. When I arrived, the train (already / leave).\n2. She was upset because she (fail) the test.\n3. They (not / eat) before the match.\n4. (you / see) the film before?\n5. After he (finish) his homework, he went out.\n\n**2.** Que signifie *When I arrived, the train left* ? En quoi est-ce différent de la phrase 1 ?","bareme":[{"critere":"Cinq past perfect bien formés (had + participe passé)","points":12},{"critere":"Différence d'ordre chronologique expliquée","points":8}],"dureeMin":6,"corrige":"**1. Réponses**\n1. the train **had already left**.\n2. she **had failed** the test.\n3. They **hadn't eaten** before the match.\n4. **Had you seen** the film before?\n5. After he **had finished** his homework, he went out.\n\nForme : *had* + participe passé, à toutes les personnes.\n\n**2. La différence**\n*When I arrived, the train left* signifie que le train est parti **après** mon arrivée (au moment où j'arrivais). Dans la phrase 1, *had already left* montre que le départ du train est **antérieur** à mon arrivée : je l'ai raté. Sans past perfect, l'ordre se perd."}$exo$::jsonb),
  ('bfd40b71-74c1-5bb4-9270-f8341862c0ca'::uuid, 2, 'traduction', $exo${"titre":"Une soirée ratée","consigne":"Relie chaque paire de phrases avec le mot indiqué, en mettant l'action la plus ancienne au past perfect.","enonce":"**1. Relie les deux phrases.**\n\n1. I got to the cinema. The film started. (when… already)\n2. She ate. She went to bed. (after)\n3. We lost our tickets. We couldn't go in. (because)\n4. The guests left. I arrived at the party. (when… already)\n5. Nobody told me. I didn't know. (because)\n\n**2.** Dans le récit *She opened the door, took her coat and left*, faut-il un past perfect ? Explique.","bareme":[{"critere":"Action la plus ancienne au past perfect dans chaque phrase","points":8},{"critere":"Action récente au prétérit simple, connecteurs bien employés","points":6},{"critere":"Explication : pas de past perfect quand l'ordre est déjà clair","points":6}],"dureeMin":10,"corrige":"**1. Réponses**\n1. *When I got to the cinema, the film had already started.*\n2. *After she had eaten, she went to bed.*\n3. *We couldn't go in because we had lost our tickets.*\n4. *When I arrived at the party, the guests had already left.*\n5. *I didn't know because nobody had told me.*\n\nL'action la plus **ancienne** est au past perfect, la plus **récente** au prétérit simple.\n\n**2. Le récit**\nNon : les trois actions sont racontées **dans l'ordre chronologique**. Trois prétérits simples suffisent ; le past perfect ne sert que lorsqu'on revient en arrière."}$exo$::jsonb),
  ('bfd40b71-74c1-5bb4-9270-f8341862c0ca'::uuid, 3, 'traduction', $exo${"titre":"Ce qu'a dit Emma","consigne":"Réponds aux trois exercices en justifiant l'emploi du past perfect.","enonce":"**1. Discours indirect.** Rapporte les paroles d'Emma en commençant par *Emma said (that)…*\n\na. « I saw the accident. »\nb. « I lost my phone. »\n\n**2. Regret.** Exprime le regret d'Emma avec *I wish* ou *If only* :\na. Emma didn't study for the test.\nb. Emma told her secret to everyone.\n\n**3. Troisième condition.** Écris une phrase en *If* :\na. Emma didn't know about the party, so she didn't come.\n\n**4.** Explique en quoi ces trois emplois (discours indirect, regret, troisième condition) ont un point commun. Attention : dans *Emma'd come*, que peut valoir *'d* ?","bareme":[{"critere":"Discours indirect au past perfect","points":5},{"critere":"Regrets avec wish / if only + past perfect","points":5},{"critere":"Troisième condition correcte (if + past perfect, would have + participe passé)","points":4},{"critere":"Point commun expliqué et contraction 'd analysée","points":4},{"critere":"Correction de la langue","points":2}],"dureeMin":16,"corrige":"**1. Discours indirect**\na. *Emma said (that) she had seen the accident.*\nb. *Emma said (that) she had lost her phone.*\nAu discours indirect, un prétérit devient un **past perfect** (et *I* → *she*, *my* → *her*).\n\n**2. Regrets**\na. *Emma wishes she had studied for the test.* / *If only I had studied!*\nb. *Emma wishes she hadn't told her secret to everyone.* / *If only I hadn't told…!*\nRegret sur le passé → **past perfect** après *wish* / *if only*.\n\n**3. Troisième condition**\n*If Emma had known about the party, she would have come.*\n*if* + past perfect, *would have* + participe passé : l'irréel du passé.\n\n**4. Point commun**\nDans les trois cas, le past perfect marque un fait **antérieur à un autre moment passé**, ou **irréel dans le passé**. *'d* peut valoir **had** (*Emma'd come* = *Emma had come*, suivi d'un participe passé) ou **would** (*Emma'd come* = *Emma would come*, suivi d'une base verbale) : ici, *come* est à la fois base verbale et participe passé, seul le contexte tranche."}$exo$::jsonb),
  ('5f715fe1-08d3-5632-adbb-436ee655a8cd'::uuid, 1, 'traduction', $exo${"titre":"Will, going to ou BE + -ING ?","consigne":"Choisis la forme du futur qui convient et recopie la phrase.","enonce":"**Choisis la bonne forme.**\n\n1. The phone's ringing — I (will get / am going to get) it!\n2. Look at those clouds! It (will rain / is going to rain).\n3. I (am meeting / will meet) Sarah at 6 at the station. (c'est organisé)\n4. The train (leaves / will leave) at 7.15. (horaire)\n5. I (will call / call) you when I (will arrive / arrive).\n6. I think it (will be / is being) sunny tomorrow.\n\n**Question :** qu'est-ce qui distingue *will*, *be going to* et BE + -ING ?","bareme":[{"critere":"Six choix justes","points":14},{"critere":"Degré de préparation expliqué (décision immédiate, intention, rendez-vous)","points":6}],"dureeMin":7,"corrige":"**Réponses**\n1. **will get** — décision prise au moment de parler.\n2. **is going to rain** — prédiction fondée sur un indice présent.\n3. **am meeting** — rendez-vous organisé.\n4. **leaves** — horaire officiel : présent simple.\n5. I **will call** you when I **arrive** — après *when*, présent.\n6. **will be** — prédiction, opinion (*I think*).\n\n**La différence**\nCes trois formes se distinguent par le **degré de préparation** : *will* = décision **immédiate** ; *be going to* = **intention** déjà formée ; BE + -ING = **rendez-vous fixé**, avec date et lieu."}$exo$::jsonb),
  ('5f715fe1-08d3-5632-adbb-436ee655a8cd'::uuid, 2, 'traduction', $exo${"titre":"Les vacances de Rayan","consigne":"Complète le dialogue avec la forme du futur qui convient, puis justifie trois choix.","enonce":"> **Mia**: What (1. you / do) this summer?\n> **Rayan**: I (2. visit) my cousins in Canada. I decided it last month. My plane (3. leave) on July 3rd at 10 a.m.\n> **Mia**: Wow! And I (4. start) a summer job on Monday: I signed the contract yesterday.\n> **Rayan**: Great! I (5. send) you a postcard as soon as I (6. arrive).\n> **Mia**: Oh, you forgot your bag! — Oh no! I (7. come) back to get it!\n\n1. Complète les sept blancs.\n2. Justifie tes choix pour les blancs 2, 3 et 6.","bareme":[{"critere":"Going to / BE + -ING justes pour l'intention et le rendez-vous","points":6},{"critere":"Présent simple pour l'horaire et après as soon as","points":5},{"critere":"Will pour la promesse et la décision immédiate","points":4},{"critere":"Trois justifications exactes","points":5}],"dureeMin":10,"corrige":"**1. Réponses**\n(1) **are you going to do** (ou *are you doing*) — question sur les projets.\n(2) **am going to visit** — intention déjà formée (*I decided it last month*) ; *am visiting* accepté.\n(3) **leaves** — horaire officiel.\n(4) **am starting** — rendez-vous organisé (contrat signé).\n(5) **will send** — promesse.\n(6) **arrive** — après *as soon as* : présent.\n(7) **'ll come** — décision prise au moment de parler.\n\n**2. Justifications**\n- (2) La décision est déjà prise : c'est une **intention** → *be going to*.\n- (3) Un **horaire officiel** (avion) → présent simple.\n- (6) Après une conjonction de temps (*when, as soon as, before, after, until*), l'anglais emploie le **présent**, jamais *will*."}$exo$::jsonb),
  ('5f715fe1-08d3-5632-adbb-436ee655a8cd'::uuid, 3, 'traduction', $exo${"titre":"Le voyage scolaire à Édimbourg","consigne":"Traduis le texte en anglais, puis justifie chaque forme du futur que tu as employée.","enonce":"**1. Thème : traduis en anglais.**\n\n> Le bus part demain à 6 h. Nous visitons le château mardi : le professeur a réservé les billets. Je vais acheter un kilt, je l'ai décidé. Je pense qu'il fera froid. Je t'enverrai un message dès que j'arriverai. — Tu as oublié ton passeport ! — Ah oui, je vais le chercher tout de suite ! J'allais le mettre dans mon sac, mais j'ai oublié.\n\n*Aide : to book = réserver ; to fetch = aller chercher ; right now = tout de suite.*\n\n**2.** Justifie chaque forme du futur de ta traduction.","bareme":[{"critere":"Présent simple pour l'horaire, BE + -ING pour le rendez-vous organisé","points":4},{"critere":"Going to pour l'intention, will pour la prédiction, la promesse et la décision immédiate","points":5},{"critere":"Présent après as soon as, was going to pour l'intention passée","points":4},{"critere":"Justifications exactes","points":5},{"critere":"Correction de la langue","points":2}],"dureeMin":17,"corrige":"**1. Traduction modèle**\n> *The bus leaves tomorrow at 6 a.m. We are visiting the castle on Tuesday: the teacher has booked the tickets. I'm going to buy a kilt, I've decided. I think it will be cold. I'll send you a message as soon as I arrive. — You've forgotten your passport! — Oh yes, I'll fetch it right now! I was going to put it in my bag, but I forgot.*\n\n**2. Justifications**\n- *leaves* : **horaire** officiel → présent simple.\n- *are visiting* : **rendez-vous organisé** (billets réservés) → BE + -ING.\n- *am going to buy* : **intention** déjà formée → *be going to*.\n- *will be cold* : **prédiction**, opinion (*I think*) → *will*.\n- *I'll send* : **promesse** → *will* ; *as soon as I arrive* : **présent** après une conjonction de temps.\n- *I'll fetch it* : **décision prise au moment de parler** → *will*.\n- *was going to put* : intention passée non réalisée → *was going to* (« j'allais »)."}$exo$::jsonb),
  ('863ebe89-2a1a-53d5-8e0c-551fe22d9df9'::uuid, 1, 'traduction', $exo${"titre":"Si… : le type 1","consigne":"Conjugue les verbes pour former des conditions de type 1, puis corrige la phrase fautive.","enonce":"**1. Conjugue les verbes (type 1 : le possible).**\n\n1. If it (rain), I (stay) home.\n2. If you (study), you (pass) the exam.\n3. She (be) angry if you (not / call) her.\n4. If we (hurry), we (catch) the bus.\n\n**2. Corrige :** *If I will have time, I will come.*\n\n**3.** Quand met-on une virgule dans une phrase en *if* ?","bareme":[{"critere":"Quatre phrases justes : if + présent, will + base verbale","points":12},{"critere":"Correction : jamais will après if","points":5},{"critere":"Règle de la virgule","points":3}],"dureeMin":7,"corrige":"**1. Réponses**\n1. If it **rains**, I **will stay** home.\n2. If you **study**, you **will pass** the exam.\n3. She **will be** angry if you **don't call** her.\n4. If we **hurry**, we **will catch** the bus.\nType 1 : *if* + **présent simple**, principale en **will** + base verbale. Ce qui est envisagé peut réellement arriver.\n\n**2. Correction**\n*If I **have** time, I will come.* — **jamais de will ni de would après if**.\n\n**3. La virgule**\nQuand la proposition en *if* **ouvre** la phrase, une virgule la sépare de la principale (*If it rains, I will stay home*). Quand la principale vient en premier, pas de virgule (*I will stay home if it rains*)."}$exo$::jsonb),
  ('863ebe89-2a1a-53d5-8e0c-551fe22d9df9'::uuid, 2, 'traduction', $exo${"titre":"Si j'étais millionnaire","consigne":"Transforme chaque situation en phrase de type 2, puis réponds à la question 2.","enonce":"**1. Écris une phrase de type 2 (l'irréel du présent).**\n\nExemple : *I don't have time, so I don't travel.* → *If I had time, I would travel.*\n\n1. I don't have a car, so I don't drive to school.\n2. She doesn't speak English, so she doesn't understand the film.\n3. We live in a small flat, so we can't have a dog.\n4. I am not you, but I advise you to apologise. (commence par *If I were you*)\n\n**2.** Complète en anglais : *If I were a millionaire, …* (deux phrases). Pourquoi emploie-t-on *were* et non *was* ?","bareme":[{"critere":"If + prétérit correct, forme inversée (positif / négatif)","points":6},{"critere":"Would + base verbale dans la principale","points":6},{"critere":"Deux phrases personnelles correctes","points":4},{"critere":"Explication de were","points":4}],"dureeMin":10,"corrige":"**1. Réponses**\n1. *If I had a car, I would drive to school.*\n2. *If she spoke English, she would understand the film.*\n3. *If we didn't live in a small flat, we could have a dog.* (*If we lived in a big house, we could / would have a dog* accepté)\n4. *If I were you, I would apologise.*\nType 2 : *if* + **prétérit**, principale en **would** + base verbale. La situation est **irréelle** : elle n'est pas vraie aujourd'hui.\n\n**2. Exemple**\n*If I were a millionaire, I would buy a house by the sea. I would travel around the world.*\n*Were* s'emploie à **toutes les personnes** dans cette structure : il marque l'irréel (*If I were you*). *Was* se rencontre à l'oral, mais *were* est la forme attendue."}$exo$::jsonb),
  ('863ebe89-2a1a-53d5-8e0c-551fe22d9df9'::uuid, 3, 'traduction', $exo${"titre":"Trois conditions, trois degrés de réalité","consigne":"Traduis les phrases, identifie leur type, puis réponds à la question 3.","enonce":"**1. Thème : traduis en anglais.**\n\n1. S'il fait beau samedi, nous irons à la plage.\n2. Si j'avais un chien, je le promènerais tous les jours.\n3. Si tu m'avais écouté, tu n'aurais pas raté le bus.\n4. Si j'étais toi, je lui dirais la vérité.\n5. Je t'appellerai si j'ai le temps.\n\n*Aide : to walk a dog = promener un chien ; to miss = rater.*\n\n**2.** Pour chaque phrase, donne le **type** (1, 2 ou 3) et ce qu'il exprime (possible, irréel du présent, irréel du passé).\n\n**3.** Que s'est-il réellement passé dans la phrase 3 ? Explique comment l'anglais marque l'irréel sans employer *would* après *if*.","bareme":[{"critere":"Type 1 correct (if + présent, will), virgule bien placée","points":4},{"critere":"Type 2 correct (if + prétérit / were, would + base verbale)","points":4},{"critere":"Type 3 correct (if + past perfect, would have + participe passé)","points":4},{"critere":"Types identifiés et sens expliqué","points":5},{"critere":"Explication du décalage de temps","points":3}],"dureeMin":17,"corrige":"**1. Traduction modèle**\n1. *If the weather is nice on Saturday, we will go to the beach.* (*If it is sunny…*)\n2. *If I had a dog, I would walk it every day.*\n3. *If you had listened to me, you wouldn't have missed the bus.*\n4. *If I were you, I would tell him / her the truth.*\n5. *I will call you if I have time.* — pas de virgule : la principale ouvre la phrase.\n\n**2. Types**\n1. Type 1 — le **possible** : il peut faire beau.\n2. Type 2 — l'**irréel du présent** : je n'ai pas de chien.\n3. Type 3 — l'**irréel du passé**, un regret.\n4. Type 2 — l'irréel du présent (je ne suis pas toi) ; *were* à toutes les personnes.\n5. Type 1 — le possible.\n\n**3. La réalité**\nPhrase 3 : en réalité, tu **ne m'as pas écouté** et tu **as raté** le bus. L'anglais marque l'irréel par le **décalage de temps** : on recule d'un temps après *if* (prétérit pour le présent, past perfect pour le passé). *Will* et *would* ne s'emploient jamais après *if* : ils ne vont que dans la principale."}$exo$::jsonb),
  ('3e2c5cac-a5c2-5940-9bc8-059f362dc2f9'::uuid, 1, 'traduction', $exo${"titre":"Les trois colonnes","consigne":"Complète le tableau des verbes irréguliers.","enonce":"**Complète les trois colonnes (base verbale – prétérit – participe passé).**\n\n1. go – ___ – ___\n2. ___ – saw – ___\n3. take – ___ – taken\n4. ___ – ___ – written\n5. buy – ___ – ___\n6. come – ___ – ___\n7. cut – ___ – ___\n8. be – ___ – ___\n9. eat – ___ – ___\n10. think – ___ – ___\n\n**Question :** à quoi sert la troisième colonne ?","bareme":[{"critere":"Dix verbes complets et justes (1,5 point par verbe)","points":15},{"critere":"Emplois de la troisième colonne","points":5}],"dureeMin":7,"corrige":"**Réponses**\n1. go – **went** – **gone**\n2. **see** – saw – **seen**\n3. take – **took** – taken\n4. **write** – **wrote** – written\n5. buy – **bought** – **bought**\n6. come – **came** – **come**\n7. cut – **cut** – **cut**\n8. be – **was / were** – **been**\n9. eat – **ate** – **eaten**\n10. think – **thought** – **thought**\n\n**La troisième colonne** (participe passé) sert au **present perfect** (*I have seen*), au **past perfect** (*I had seen*) et à la **voix passive** (*It was written*)."}$exo$::jsonb),
  ('3e2c5cac-a5c2-5940-9bc8-059f362dc2f9'::uuid, 2, 'traduction', $exo${"titre":"Choisir la bonne colonne","consigne":"Mets chaque verbe entre parenthèses à la bonne forme, en choisissant la bonne colonne.","enonce":"> Last year, I (1. go) to London with my class. We (2. see) Big Ben and we (3. eat) fish and chips. I (4. buy) a red bus for my brother. I didn't (5. take) many photos because I (6. forget) my phone at the hotel! I have (7. speak) English every day since then, and I have (8. read) three books in English. The book I liked best was (9. write) by a young author.\n\n1. Conjugue les neuf verbes.\n2. Pour les verbes 5, 6 et 7, dis de quelle colonne tu t'es servi et pourquoi.","bareme":[{"critere":"Prétérits affirmatifs justes (colonne 2)","points":6},{"critere":"Base verbale après didn't (colonne 1)","points":3},{"critere":"Participes passés justes (present perfect et passif, colonne 3)","points":6},{"critere":"Trois justifications exactes","points":5}],"dureeMin":10,"corrige":"**1. Réponses**\n(1) **went** · (2) **saw** · (3) **ate** · (4) **bought** · (5) **take** · (6) **had forgotten** (ou **forgot**) · (7) **spoken** · (8) **read** · (9) **written**.\n\n**2. Justifications**\n- (5) *didn't take* : **colonne 1** (base verbale), car *did* porte déjà le passé.\n- (6) *forgot* : **colonne 2**, prétérit affirmatif ; *had forgotten* (colonne 3, past perfect) est aussi juste : l'oubli est antérieur.\n- (7) *have spoken* : **colonne 3**, present perfect (*have* + participe passé).\n\nPour (8), *read* a ses trois formes identiques à l'écrit (la prononciation change) ; (9) *was written* : voix passive → colonne 3."}$exo$::jsonb),
  ('3e2c5cac-a5c2-5940-9bc8-059f362dc2f9'::uuid, 3, 'traduction', $exo${"titre":"La copie de Théo","consigne":"Corrige les fautes du texte en justifiant, puis réponds à la question 3.","enonce":"> Yesterday, I goed to the zoo with my family. We seen a lot of animals. My sister drinked a big lemonade and my dad has taken photos yesterday. Did you ever went to a zoo? I have ate an ice cream there. The zoo was build in 1950. I have never forgot this day!\n\n1. Le texte contient **huit fautes** sur les verbes irréguliers. Relève-les et corrige-les.\n2. Pour chaque correction, indique la colonne employée et la raison.\n3. Range ces verbes dans leur famille (trois formes identiques ; 1 = 3 ; 2 = 3 ; trois formes différentes) : *put, become, bring, know, let, run, teach, give*.","bareme":[{"critere":"Huit fautes relevées et corrigées","points":7},{"critere":"Colonne et raison données pour chaque correction","points":6},{"critere":"Huit verbes rangés dans la bonne famille","points":5},{"critere":"Qualité de la rédaction","points":2}],"dureeMin":16,"corrige":"**1 et 2. Les huit fautes**\n- *goed* → **went** : colonne 2, prétérit affirmatif.\n- *We seen* → **We saw** : colonne 2 (*seen* est le participe, il faudrait *have*).\n- *drinked* → **drank** : colonne 2, prétérit irrégulier.\n- *has taken photos yesterday* → **took photos yesterday** : repère passé précis → prétérit, colonne 2.\n- *Did you ever went* → **Have you ever been to a zoo?** (ou *Did you ever go*) : après *did*, colonne 1 ; avec *ever*, le present perfect (colonne 3) est préférable.\n- *I have ate* → **I ate** (repère : là-bas, hier) ou **I have eaten** : après *have*, colonne 3.\n- *was build* → **was built** : voix passive, colonne 3.\n- *have never forgot* → **have never forgotten** : present perfect, colonne 3.\n\n**3. Familles**\n- Trois formes identiques : *put*, *let*.\n- 1 = 3 : *become* (became – become), *run* (ran – run).\n- 2 = 3 : *bring* (brought – brought), *teach* (taught – taught).\n- Trois formes différentes : *know* (knew – known), *give* (gave – given)."}$exo$::jsonb),
  ('3deb6025-4f2c-5f45-b3ee-20d8c8ae16ee'::uuid, 1, 'redaction', $exo${"titre":"Le cadre, le lieu, le titre","consigne":"Réponds à chaque question par une ou deux phrases complètes, en utilisant le vocabulaire du cours.","enonce":"1. Explique ce qu'est le **hors-champ** et ce qu'il fait travailler chez le spectateur.\n2. Que désigne une œuvre **in situ** ?\n3. Le titre d'une œuvre est-il une simple étiquette ? Justifie en disant ce que peut faire un titre précis et ce que fait un titre *Sans titre*.","bareme":[{"critere":"Définition du hors-champ (ce qui est hors du cadre mais reste présent) et rôle de l'imagination du spectateur","points":7},{"critere":"Définition de l'in situ : œuvre conçue pour un lieu précis, indissociable de lui","points":6},{"critere":"Le titre comme élément de l'œuvre : il ferme ou déplace le sens, ou laisse libre (Sans titre)","points":7}],"dureeMin":6,"corrige":"1. Le **hors-champ**, c'est ce qui se trouve **en dehors du cadre** : on ne le voit pas, mais il reste présent. En choisissant ce qu'il montre, le cadre choisit aussi ce qu'il **cache** ; le hors-champ fait alors travailler l'**imagination** du spectateur, qui complète mentalement ce qui manque. Ce qu'on ne voit pas peut être plus présent que ce qu'on voit.\n2. Une œuvre **in situ** est une œuvre **conçue pour un lieu précis** : elle en est **indissociable**, la déplacer la priverait d'une partie de son sens.\n3. Non. Le titre est un **élément de l'œuvre**, pas une étiquette. Un titre **précis** oriente la lecture : il **ferme** le sens (il dit quoi regarder) ou le **déplace** (il fait voir autre chose que ce qu'on croyait voir). Un titre *Sans titre* laisse **volontairement** le spectateur libre de son interprétation."}$exo$::jsonb),
  ('3deb6025-4f2c-5f45-b3ee-20d8c8ae16ee'::uuid, 2, 'redaction', $exo${"titre":"La même sculpture en trois lieux","consigne":"Lis la situation et réponds aux questions en justifiant avec les notions du cours.","enonce":"**Situation.** Une artiste, Inès, a réalisé une grande sphère en acier poli. Elle est d'abord exposée dans la **vitrine** d'un grand magasin, puis achetée par un **musée**, enfin installée au milieu d'une **place publique**, où les passants peuvent tourner autour et s'y voir déformés comme dans un miroir.\n\n1. Pour chacun des trois lieux, explique ce que devient l'œuvre aux yeux du public.\n2. Sur la place, quel rôle joue le spectateur ? Utilise le vocabulaire du cours sur le spectateur actif.\n3. Inès hésite à appeler son œuvre *Sans titre* ou *Nous*. Explique l'effet de chacun de ces deux choix.","bareme":[{"critere":"Effet des trois lieux : marchandise (vitrine), patrimoine (musée), affaire de tous (place publique)","points":8},{"critere":"Spectateur actif : il se déplace, tourne autour, se voit dans l'œuvre et la complète","points":6},{"critere":"Effet des deux titres : laisser libre ou orienter/déplacer le sens vers le public","points":6}],"dureeMin":10,"corrige":"1. Une même forme n'a pas le même effet selon l'endroit :\n- dans la **vitrine**, la sphère devient une **marchandise** : on la regarde comme un objet à vendre ;\n- au **musée**, elle devient **patrimoine** : elle est désignée comme œuvre à conserver et à étudier ;\n- sur la **place publique**, elle devient **affaire de tous** : chacun la croise sans l'avoir choisie, elle appartient à l'espace commun.\n2. Le spectateur est **actif** : il doit **se déplacer** et **tourner autour** pour voir l'œuvre, et son propre reflet déformé en fait partie. L'œuvre change avec son mouvement (comme dans l'art cinétique, qui joue du mouvement du regardeur) : sans lui, elle n'existe pas pleinement. Une œuvre n'existe pleinement que regardée.\n3. *Sans titre* laisse **volontairement libre** le spectateur : chacun y voit ce qu'il veut (un miroir, une planète, une bulle). *Nous* **déplace** le sens : il oriente la lecture vers les passants reflétés, et fait de la foule le vrai sujet de l'œuvre. Le titre est un élément de l'œuvre, pas une étiquette."}$exo$::jsonb),
  ('3deb6025-4f2c-5f45-b3ee-20d8c8ae16ee'::uuid, 3, 'redaction', $exo${"titre":"Où s'arrête l'œuvre ?","consigne":"Analyse le document puis rédige tes réponses. La dernière question attend un paragraphe argumenté d'une dizaine de lignes.","enonce":"**Document – Description d'une installation imaginaire**\n\n> Dans une ancienne chapelle, l'artiste Malo a tendu une toile blanche qui ferme le chœur. Une fente étroite laisse voir seulement un morceau de vitrail éclairé. Au sol, des galets sont posés : le cartel invite chaque visiteur à en déplacer un. L'œuvre s'intitule *Ce qui reste derrière*. Elle a été pensée pour cette chapelle et ne sera jamais montrée ailleurs.\n\n1. Relève dans le document un exemple de **cadre** et de **hors-champ**, et explique leur effet.\n2. Montre que l'œuvre est **in situ**.\n3. Quelles actions l'œuvre demande-t-elle au spectateur ? Classe-les avec le vocabulaire du cours.\n4. Paragraphe argumenté : « Cette œuvre commence-t-elle et s'arrête-t-elle à la toile tendue ? » Réponds en mobilisant le cadre, le lieu, le spectateur et le titre.","bareme":[{"critere":"Cadre (la fente) et hors-champ (le chœur caché) identifiés, effet sur l'imagination expliqué","points":5},{"critere":"Caractère in situ justifié : conçue pour la chapelle, indissociable du lieu","points":3},{"critere":"Actions du spectateur classées : entrer/se déplacer, toucher-participer, compléter mentalement","points":4},{"critere":"Paragraphe argumenté mobilisant cadre, lieu, spectateur et titre","points":6},{"critere":"Rédaction claire et vocabulaire précis","points":2}],"dureeMin":18,"corrige":"1. La **fente** dans la toile joue le rôle d'un **cadre** : elle choisit de montrer seulement un morceau de vitrail et donc de **cacher** tout le reste du chœur. Ce chœur invisible est le **hors-champ** : on ne le voit pas, mais on sait qu'il est là, et l'imagination du spectateur le reconstruit. Ce qu'on ne voit pas devient plus présent que ce qu'on voit.\n2. L'œuvre est **in situ** : elle a été **conçue pour cette chapelle précise** (la toile ferme son chœur, la fente vise son vitrail) et ne sera **jamais montrée ailleurs** : elle est indissociable du lieu.\n3. Le spectateur doit **se déplacer** et **entrer** dans l'installation (il circule dans la chapelle, cherche l'angle de la fente) ; il doit **toucher / participer** (déplacer un galet : œuvre participative) ; il doit **compléter mentalement** ce que la toile cache.\n4. Paragraphe attendu (exemple) : l'œuvre ne se limite pas à la toile. Elle commence avec le **lieu** : sans la chapelle, sans son chœur et son vitrail, la toile n'aurait rien à cacher ; c'est une œuvre in situ. Elle se prolonge dans le **hors-champ** : le cadre de la fente montre peu pour faire imaginer beaucoup, et ce qui est caché fait partie de l'œuvre. Elle dépend aussi du **spectateur actif**, qui se déplace, regarde par la fente et modifie la disposition des galets : l'œuvre change à chaque visite, elle n'est jamais finie. Enfin le **titre**, *Ce qui reste derrière*, n'est pas une étiquette : il **oriente** le regard vers ce qui est caché et fait du hors-champ le vrai sujet. L'œuvre s'étend donc à tout ce que la toile met en jeu : le lieu, le caché, le visiteur et les mots.\n\nLe correcteur valorise toute réponse qui relie au moins trois de ces notions à des éléments précis du document."}$exo$::jsonb),
  ('2dd8c27b-b51b-523a-b385-a474242ad68b'::uuid, 1, 'redaction', $exo${"titre":"Dénotation et connotation","consigne":"Réponds en phrases complètes en utilisant le vocabulaire du cours.","enonce":"**Image décrite.** Une affiche montre un flacon de parfum posé sur un rocher, face à l'océan au coucher du soleil. En bas, une accroche : « Sois libre. »\n\n1. Définis la **dénotation** et la **connotation**.\n2. Donne la dénotation de cette affiche, puis une connotation.\n3. À quoi sert l'accroche « Sois libre » ?","bareme":[{"critere":"Définitions correctes : dénotation = ce que l'image montre littéralement, connotation = ce qu'elle suggère","points":8},{"critere":"Dénotation et connotation de l'affiche correctement distinguées","points":7},{"critere":"Rôle de l'accroche : ancrer le sens que l'image laissait flottant","points":5}],"dureeMin":7,"corrige":"1. La **dénotation**, c'est ce que l'image **montre littéralement**, ce qu'on peut décrire sans interpréter. La **connotation**, c'est ce que l'image **suggère** au-delà : des valeurs, des émotions, une appartenance.\n2. **Dénotation** : un flacon de parfum sur un rocher, l'océan, un coucher de soleil, une phrase. **Connotation** (une suffit) : la liberté, l'évasion, la nature sauvage, la sérénité, la beauté, un moment rare et précieux.\n3. L'accroche **ancre le sens** : l'image seule pouvait évoquer beaucoup de choses (le calme, les vacances, la solitude) ; le texte « Sois libre » fixe la connotation voulue par l'annonceur et associe le parfum à l'idée de liberté."}$exo$::jsonb),
  ('2dd8c27b-b51b-523a-b385-a474242ad68b'::uuid, 2, 'redaction', $exo${"titre":"Décoder une publicité de baskets","consigne":"Lis la description de la publicité et réponds aux questions en justifiant avec les procédés du cours.","enonce":"**Publicité décrite.** Gros plan en contre-jour sur les jambes d'une athlète qui s'élance au-dessus d'une piste. Ses baskets blanches brillent dans une lumière dorée ; la peau est lisse, sans aucun défaut. Le reste de l'image est flou. En haut : « Plus haut que tout. » Le logo de la marque est en bas à droite.\n\n1. Relève **trois procédés** de l'image publicitaire et donne l'effet de chacun.\n2. Applique les **quatre questions du regard critique** à cette publicité.\n3. Que cherche-t-on à transférer sur le produit ?","bareme":[{"critere":"Trois procédés identifiés (cadrage serré, lumière valorisante, retouche, mise en scène du corps, accroche) avec leur effet","points":9},{"critere":"Les quatre questions (qui parle, à qui, pour vendre quoi, que montre/cache-t-on) appliquées","points":7},{"critere":"Transfert du désir ou des valeurs (performance, dépassement) sur le produit","points":4}],"dureeMin":11,"corrige":"1. Procédés (trois attendus) :\n- le **cadrage serré** sur les jambes et les baskets : il **isole et magnifie** le produit, le reste est flou ;\n- la **lumière valorisante** dorée : elle **embellit** les chaussures et l'athlète ;\n- la **retouche** : la peau sans défaut **efface le défaut**, l'image est parfaite ;\n- la **mise en scène du corps** : l'élan de l'athlète **transfère le désir** sur le produit ;\n- l'**accroche** « Plus haut que tout » **ancre** le sens : le saut devient dépassement de soi.\n2. **Qui parle ?** La marque de baskets (son logo), qui a intérêt à vendre. **À qui ?** Surtout des jeunes, sportifs ou qui veulent le paraître. **Pour vendre quoi ?** Une paire de baskets. **Que montre-t-on / que cache-t-on ?** On montre un corps parfait en plein exploit ; on cache l'entraînement, la retouche, le prix, le fait qu'une chaussure ne fait pas sauter plus haut.\n3. On cherche à transférer sur les baskets la **performance**, la **réussite**, le **dépassement** et la beauté de l'athlète : acheter les chaussures, ce serait acheter un peu de cet exploit. L'image publicitaire n'est jamais neutre."}$exo$::jsonb),
  ('2dd8c27b-b51b-523a-b385-a474242ad68b'::uuid, 3, 'redaction', $exo${"titre":"Une affiche détournée","consigne":"Compare les deux images décrites, puis réponds. La dernière question attend un paragraphe argumenté.","enonce":"**Image A – Publicité.** Une famille souriante autour d'une table couverte de hamburgers d'une chaîne de restauration rapide. Lumière chaude, couleurs vives, produits retouchés et brillants. Accroche : « Le bonheur se partage. »\n\n**Image B – Œuvre d'un artiste.** La même composition, reprise à l'identique : même table, mêmes couleurs, même typographie. Mais les personnages ont le visage fatigué, la table est couverte d'emballages vides, et l'accroche devient : « Le bonheur s'emballe. »\n\n1. Donne la dénotation et la connotation de l'image A.\n2. Relève deux procédés publicitaires de l'image A.\n3. Quel est le principe utilisé dans l'image B ? Nomme-le, dis d'où il vient et à partir de quand des artistes l'utilisent.\n4. Paragraphe argumenté : comment l'image B transforme-t-elle le spectateur en « lecteur d'images » ? Appuie-toi sur le rôle de l'accroche et sur les questions du regard critique.","bareme":[{"critere":"Dénotation et connotation de l'image A correctement distinguées","points":4},{"critere":"Deux procédés de l'image A identifiés avec leur effet","points":4},{"critere":"Détournement nommé, hérité des situationnistes, pratiqué depuis les années 1960","points":4},{"critere":"Paragraphe : codes retournés contre eux-mêmes, accroche qui change le sens, questions du regard critique","points":6},{"critere":"Rédaction organisée et vocabulaire précis","points":2}],"dureeMin":18,"corrige":"1. **Dénotation** : une famille assise à une table avec des hamburgers et une phrase. **Connotation** : le bonheur familial, la convivialité, la chaleur, l'abondance.\n2. Procédés (deux attendus) : **lumière valorisante** et couleurs chaudes qui embellissent ; **retouche** des produits brillants qui efface le défaut ; **association d'idées** (produit + famille heureuse) ; **accroche** qui ancre le sens (« le bonheur » = le produit).\n3. C'est le **détournement** (ou parodie) : on **réutilise les codes existants** de la publicité pour les **retourner contre eux-mêmes**. Le principe est hérité des **situationnistes** et de nombreux artistes l'utilisent **depuis les années 1960**.\n4. Paragraphe attendu (exemple) : l'image B garde exactement la composition, les couleurs et la typographie de la publicité : le spectateur la reconnaît d'abord comme une publicité ordinaire. Puis les détails le surprennent (visages fatigués, emballages vides) et l'**accroche** modifiée, « Le bonheur s'emballe », **ancre un autre sens** : le mot « emballe » évoque à la fois l'emballage jeté et l'emballement de la consommation. L'artiste montre ainsi ce que la publicité **cache** (les déchets, la lassitude) derrière ce qu'elle **montre**. L'image oblige à se poser les questions du regard critique : **qui parle** (une marque qui a intérêt à vendre), **à qui** (les familles), **pour vendre quoi** (des repas rapides, pas du bonheur). Le spectateur, qui recevait passivement l'image, apprend à la **lire** : il devient lecteur d'images.\n\nLe correcteur accepte toute analyse cohérente qui explique le retournement des codes et le rôle de l'accroche."}$exo$::jsonb),
  ('b179c6ac-9414-59bb-b36a-8933cae48929'::uuid, 1, 'redaction', $exo${"titre":"Les quatre techniques du volume","consigne":"Réponds à chaque question en une ou deux phrases.","enonce":"1. Complète : **tailler**, c'est … de la matière ; **modeler**, c'est … de la matière. Donne un matériau pour chacune.\n2. Explique ce que signifient **assembler** et **mouler**, avec un matériau pour chacune.\n3. Qu'est-ce qu'un **ready-made** ? Donne l'exemple célèbre : l'artiste, l'année, le titre.","bareme":[{"critere":"Tailler = retirer (pierre, bois) ; modeler = ajouter (argile, plâtre)","points":7},{"critere":"Assembler (souder, coller, visser : métal, objets) et mouler (empreinte : plâtre, bronze, résine)","points":6},{"critere":"Ready-made défini (objet choisi et déplacé) + Duchamp, 1917, Fontaine","points":7}],"dureeMin":6,"corrige":"1. **Tailler**, c'est **retirer** de la matière (dans la **pierre** ou le **bois**). **Modeler**, c'est **ajouter** de la matière (**argile**, **plâtre**).\n2. **Assembler**, c'est réunir des éléments en les **soudant, collant ou vissant** (du **métal**, des **objets**). **Mouler**, c'est **reproduire une forme par empreinte** (en **plâtre**, **bronze** ou **résine**).\n3. Un **ready-made** est un objet déjà fabriqué que l'artiste ne fabrique pas : il le **choisit** et le **déplace** dans le lieu de l'art. Exemple : **Marcel Duchamp**, en **1917**, présente un urinoir renversé et signé, intitulé ***Fontaine***. Ce qui fait l'œuvre n'est pas la fabrication mais le choix et le déplacement."}$exo$::jsonb),
  ('b179c6ac-9414-59bb-b36a-8933cae48929'::uuid, 2, 'redaction', $exo${"titre":"Le projet de sculpture de Yanis","consigne":"Lis la situation et réponds en justifiant avec les notions du cours.","enonce":"**Situation.** Pour un concours, Yanis veut réaliser une sculpture d'animal. Il hésite entre trois idées :\n- A : une forme dans un bloc de bois, dont il enlèvera des copeaux ;\n- B : un animal en argile, qu'il fera ensuite reproduire en bronze ;\n- C : un animal fait de vieilles fourchettes et de clés soudées.\n\nIl compte percer le corps de l'animal de plusieurs trous et se demande s'il faut le poser sur un socle.\n\n1. Nomme la ou les techniques de chaque idée.\n2. Que produisent les trous percés dans la sculpture ? Cite l'artiste du cours qui procède ainsi.\n3. Explique à Yanis ce que change le choix d'un socle ou de l'absence de socle.","bareme":[{"critere":"Techniques : A taille, B modelage puis moulage, C assemblage","points":7},{"critere":"Plein et vide : l'espace traverse la sculpture et en fait partie ; Henry Moore","points":6},{"critere":"Socle qui isole et désigne comme art / absence de socle qui fait entrer l'œuvre dans notre espace (Brancusi)","points":7}],"dureeMin":10,"corrige":"1. **A** : la **taille** (on retire de la matière dans le bois). **B** : le **modelage** (on ajoute de l'argile) puis le **moulage** (reproduction par empreinte, en bronze). **C** : l'**assemblage** (objets de métal soudés).\n2. Les trous créent des **vides** : un volume se lit autant par ses **creux** que par ses **pleins**. L'espace **traverse** la sculpture et devient **partie de l'œuvre** ; la lumière et le regard passent à travers. C'est ce que fait **Henry Moore**, qui perce ses figures.\n3. **Avec un socle**, l'œuvre est **isolée** de l'espace du spectateur et **désignée comme art** : on comprend qu'on regarde une sculpture. **Sans socle** (comme chez Brancusi et dans l'art contemporain), la sculpture **descend dans notre espace**, au même niveau que nous : l'animal semblerait partager le sol du visiteur. Dans les deux cas, la sculpture a un dos et se regarde en tournant autour."}$exo$::jsonb),
  ('b179c6ac-9414-59bb-b36a-8933cae48929'::uuid, 3, 'redaction', $exo${"titre":"Un vélo au musée","consigne":"Lis le document, puis réponds. La dernière question attend un paragraphe argumenté.","enonce":"**Document – Deux œuvres imaginaires dans la même salle**\n\n> Œuvre 1 : une tête en marbre, taillée pendant six mois, posée sur un haut socle de pierre.\n> Œuvre 2 : une roue de vélo ordinaire, achetée en magasin, fixée à l'envers sur un tabouret, posée à même le sol. L'artiste l'a signée et intitulée *Tourner en rond*.\n\nUn visiteur s'agace : « La première, c'est de l'art : il y a du travail. La seconde, n'importe qui peut la faire ! »\n\n1. Quelle technique a produit l'œuvre 1 ? Quel geste suppose-t-elle ?\n2. À quelle catégorie appartient l'œuvre 2 ? Rattache-la à l'œuvre fondatrice du cours (artiste, date, titre).\n3. Compare le rôle du socle dans les deux œuvres.\n4. Paragraphe argumenté : réponds au visiteur. Explique ce qui fait l'œuvre dans chaque cas et pourquoi on parle d'une « bascule » de l'art du XXe siècle.","bareme":[{"critere":"Œuvre 1 : taille, geste de retirer de la matière (pierre)","points":3},{"critere":"Œuvre 2 : ready-made, rattaché à Duchamp, Fontaine, 1917","points":4},{"critere":"Socle comparé : isole et désigne comme art / absence : œuvre dans notre espace","points":4},{"critere":"Paragraphe : l'œuvre tient au choix et au déplacement, pas à la fabrication ; bascule du XXe siècle","points":7},{"critere":"Argumentation nuancée et rédaction claire","points":2}],"dureeMin":18,"corrige":"1. L'œuvre 1 est obtenue par la **taille** : l'artiste a **retiré de la matière** dans un bloc de marbre (pierre).\n2. L'œuvre 2 est un **ready-made** : un objet déjà fabriqué, que l'artiste n'a pas produit, mais qu'il a choisi, retourné, signé et titré. Elle se rattache à ***Fontaine*** de **Marcel Duchamp** (**1917**), un urinoir renversé et signé.\n3. Pour l'œuvre 1, le haut **socle** **isole** la tête et la **désigne comme art** : elle est mise à part, au-dessus de nous. L'œuvre 2, posée **à même le sol**, **descend dans notre espace**, au même niveau que le visiteur — comme chez Brancusi et dans l'art contemporain. Ironie : le tabouret joue un peu le rôle d'un socle détourné.\n4. Paragraphe attendu (exemple) : le visiteur a raison sur un point, l'œuvre 1 repose sur un savoir-faire et six mois de taille. Mais avec le ready-made, ce qui fait l'œuvre n'est plus la **fabrication** : c'est le **choix** de l'objet et son **déplacement** dans le lieu de l'art, avec la signature et le titre qui en changent le sens (*Tourner en rond* fait penser à la roue qui tourne sans avancer). « N'importe qui » peut acheter une roue, mais c'est la décision de la présenter comme œuvre qui oblige à se demander ce qu'est l'art. Depuis *Fontaine* en 1917, l'art n'est plus défini seulement par le travail de la main mais aussi par l'idée : c'est la **bascule** dont l'art du XXe siècle ne s'est jamais remis.\n\nLe correcteur valorise une réponse qui reconnaît la valeur du métier tout en expliquant le principe du ready-made."}$exo$::jsonb),
  ('dcaa1027-5f64-57e5-8fb6-111ee36563f1'::uuid, 1, 'redaction', $exo${"titre":"Qu’est-ce qu’une discrimination ?","consigne":"Réponds à chaque question en phrases complètes, avec le vocabulaire du cours.","enonce":"1. Donne la définition d’une **discrimination** au sens de la loi.\n2. Cite les **trois conditions** qui doivent être réunies pour qu’il y ait discrimination.\n3. Cite **quatre critères interdits** par la loi.\n4. Quelle autorité indépendante peut être saisie **gratuitement** par une victime ?","bareme":[{"critere":"Définition exacte : traitement défavorable, critère interdit, domaine protégé","points":6},{"critere":"Les trois conditions citées (défavorable, critère interdit, domaine protégé)","points":6},{"critere":"Quatre critères interdits corrects et le Défenseur des droits","points":8}],"dureeMin":7,"corrige":"1. Une discrimination est une **différence de traitement défavorable**, fondée sur un **critère interdit** par la loi, dans un **domaine que la loi protège**.\n\n2. Les trois conditions :\n- un traitement **défavorable** (refus, exclusion, désavantage) ;\n- un **critère interdit** (parmi la vingtaine que la loi énumère) ;\n- un **domaine protégé** : emploi, logement, école, santé, accès à un service.\n\n3. Quatre critères parmi : l’origine, le sexe, l’âge, l’apparence physique, le handicap, l’état de santé, la religion, les opinions politiques, l’appartenance syndicale, l’orientation sexuelle, la situation de famille, le lieu de résidence.\n\n4. Le **Défenseur des droits**, autorité indépendante que toute personne peut saisir gratuitement."}$exo$::jsonb),
  ('dcaa1027-5f64-57e5-8fb6-111ee36563f1'::uuid, 2, 'redaction', $exo${"titre":"Discrimination ou différence légitime ?","consigne":"Pour chaque situation, dis s’il s’agit d’une discrimination et justifie avec les conditions du cours.","enonce":"**Situations.**\n\n- **A.** Une agence refuse de louer un appartement à Karim en lui disant : « Avec ce nom, le propriétaire ne voudra pas. »\n- **B.** Un restaurant refuse d’embaucher Chloé comme cuisinière parce qu’elle n’a aucune formation ni expérience en cuisine.\n- **C.** Une entreprise de logistique exige pour un poste de bureau une taille minimale de 1,75 m ; presque toutes les candidates sont écartées.\n\n1. Pour chaque situation, indique si c’est une discrimination et justifie.\n2. Pour la situation C, précise de quelle **forme** de discrimination il s’agit et explique pourquoi.\n3. Quelle peine l’auteur de la situation A encourt-il ?","bareme":[{"critere":"Situation A identifiée comme discrimination, critère interdit (origine/nom) nommé","points":5},{"critere":"Situation B identifiée comme légitime : critère pertinent pour le poste","points":5},{"critere":"Situation C : discrimination indirecte expliquée (règle neutre, effet sur les femmes)","points":6},{"critere":"Peine exacte : jusqu’à 3 ans de prison et 45 000 € d’amende","points":4}],"dureeMin":10,"corrige":"1.\n- **A** : **discrimination**. Le traitement est défavorable (refus de louer), fondé sur un **critère interdit** (l’origine supposée d’après le nom), dans un **domaine protégé** (le logement). Les trois conditions sont réunies.\n- **B** : **pas une discrimination**, c’est une différence légitime. Le critère (les compétences en cuisine) est **pertinent** pour le poste ; il n’est pas interdit.\n- **C** : **discrimination**. La règle écarte surtout les femmes (critère du sexe), dans l’emploi, sans lien avec un poste de bureau.\n\n2. C’est une **discrimination indirecte** : la règle paraît **neutre** (elle vise une taille, pas un sexe), mais en fait elle **défavorise un groupe**, les femmes, et elle n’a **aucun lien avec le poste**.\n\n3. Un particulier ou une entreprise encourt **jusqu’à 3 ans de prison et 45 000 € d’amende**."}$exo$::jsonb),
  ('dcaa1027-5f64-57e5-8fb6-111ee36563f1'::uuid, 3, 'redaction', $exo${"titre":"L’enquête par testing","consigne":"Lis le document, réponds aux questions puis rédige un paragraphe argumenté d’une dizaine de lignes.","enonce":"**Document — Une association fait un test**\n\n> L’association « Égaux au travail » envoie à 50 offres de stage deux candidatures **identiques** (mêmes notes, même collège, même lettre). Seul le prénom et le nom changent : « Lucas Martin » et « Youssef Benali ». Résultat : Lucas obtient 21 réponses positives, Youssef 9. Le directeur d’une des entreprises se défend : « Je ne suis pas raciste, je n’ai jamais voulu écarter qui que ce soit. »\n\n1. Comment s’appelle cette méthode ? Explique en quoi elle consiste.\n2. Quel **critère interdit** ce test met-il en évidence ? Dans quel domaine protégé ?\n3. L’argument du directeur (« je n’ai jamais voulu ») le protège-t-il ? Justifie avec le cours.\n4. **Paragraphe argumenté** : explique pourquoi la loi s’intéresse à ce que les personnes **font** plutôt qu’à ce qu’elles **veulent**, et présente les recours dont dispose un élève victime d’une telle discrimination pour un stage.","bareme":[{"critere":"Testing nommé et défini : candidatures identiques sauf un critère, preuve admise en justice","points":4},{"critere":"Critère de l’origine (nom) et domaine de l’emploi/stage identifiés","points":3},{"critere":"Réfutation de l’argument : le résultat suffit, l’intention n’est pas exigée","points":4},{"critere":"Paragraphe : pourquoi juger les actes (discrimination souvent non consciente, protection des victimes)","points":5},{"critere":"Recours cités : Défenseur des droits gratuit, testing, associations, plainte","points":4}],"dureeMin":18,"corrige":"1. C’est le **testing** : on compare deux candidatures **identiques sauf sur un critère** (ici le nom). Si les réponses diffèrent, seul ce critère peut expliquer l’écart. C’est une **preuve admise en justice**.\n\n2. Le critère est l’**origine** (supposée d’après le nom et le prénom). Le domaine protégé est l’**emploi** (ici l’accès à un stage). 21 réponses contre 9 : la candidature de Youssef reçoit moins de la moitié des réponses de celle de Lucas.\n\n3. Non. Le droit ne demande pas ce que la personne a **voulu** faire mais ce qu’elle a **fait**. On peut discriminer sans se penser raciste : **le résultat suffit** à qualifier l’acte. L’intention n’est pas une condition.\n\n4. Paragraphe attendu (éléments) :\n- beaucoup de discriminations ne sont **pas conscientes** ou ne s’avouent pas : si la loi exigeait de prouver l’intention, presque aucune ne serait sanctionnée ;\n- pour la victime, le **préjudice est le même** (un stage perdu) que l’auteur l’ait voulu ou non ;\n- juger les actes permet de faire changer les **pratiques** (tri des candidatures) ;\n- recours : saisir **gratuitement le Défenseur des droits** ; s’appuyer sur un **testing** ; se faire aider par une **association** ; porter **plainte** ; l’**inspection du travail**. À l’école aussi, refuser un stage à cause de l’origine est une discrimination : le droit s’y applique comme ailleurs.\n- Sanction encourue : jusqu’à **3 ans de prison et 45 000 €** d’amende."}$exo$::jsonb),
  ('b2c56dae-8863-5ab9-a39d-3e650eb92870'::uuid, 1, 'redaction', $exo${"titre":"Les fondements et les limites","consigne":"Réponds à chaque question en phrases complètes.","enonce":"1. Quels sont les **deux textes** qui fondent la liberté d’expression en France ? Donne leur date.\n2. Définis l’**injure** et la **diffamation** ; montre ce qui les distingue.\n3. Cite **deux autres délits** qui limitent la liberté d’expression.\n4. Complète la phrase : « La frontière n’est pas entre le poli et l’impoli : elle est entre … et … ».","bareme":[{"critere":"Déclaration de 1789 (article 11) et loi du 29 juillet 1881","points":5},{"critere":"Injure et diffamation définies et distinguées (fait précis faux ou non)","points":6},{"critere":"Deux autres délits exacts","points":4},{"critere":"Phrase complétée : l’idée et la personne","points":5}],"dureeMin":7,"corrige":"1. La **Déclaration des droits de l’homme et du citoyen de 1789**, article 11 (libre communication des pensées et des opinions), et la **loi du 29 juillet 1881** sur la liberté de la presse et ses limites.\n\n2. L’**injure** est une expression outrageante **sans fait précis** (une insulte). La **diffamation** consiste à affirmer un **fait faux** qui porte atteinte à l’**honneur** d’une personne. La différence : la diffamation repose sur l’affirmation d’un fait, l’injure non.\n\n3. Deux délits parmi : la **provocation à la haine** ou à la violence (en raison de l’origine, la religion, le sexe, l’orientation sexuelle, le handicap) ; l’**apologie du terrorisme** ; la **négation de crimes contre l’humanité** ; le **harcèlement** ; les **menaces**.\n\n4. « … entre l’**idée** et la **personne**. » On peut critiquer une idée, une religion, un parti ; on ne peut pas appeler à s’en prendre à des personnes."}$exo$::jsonb),
  ('b2c56dae-8863-5ab9-a39d-3e650eb92870'::uuid, 2, 'redaction', $exo${"titre":"Sur le groupe de la classe","consigne":"Analyse chaque message et dis s’il est protégé ou puni par la loi, en justifiant.","enonce":"**Situation.** Sur le groupe de discussion de la 3e B, plusieurs messages sont publiés dans la soirée.\n\n- **Message 1** (Inès) : « Je trouve que cette religion a des règles absurdes, je ne la comprends pas. »\n- **Message 2** (compte « Anonyme_75 ») : « Mme Duval a volé l’argent du voyage scolaire. » (C’est faux.)\n- **Message 3** (Théo) partage, sans commentaire, une vidéo appelant à frapper les élèves d’une certaine origine.\n- **Message 4** (Sarah) publie une photo de Noé endormi dans le bus, sans lui demander, avec « trop mignon ».\n\n1. Pour chaque message, dis s’il est **protégé** ou **puni** et justifie en nommant, le cas échéant, le délit.\n2. « Anonyme_75 » pense ne rien risquer grâce à son pseudonyme. A-t-il raison ?\n3. Théo répond : « Je n’ai rien écrit, j’ai juste partagé. » Que lui répond la loi ?","bareme":[{"critere":"Message 1 protégé : critique d’une idée ou religion, pas des personnes","points":4},{"critere":"Message 2 : diffamation (fait faux portant atteinte à l’honneur)","points":4},{"critere":"Message 3 : provocation à la haine/violence et responsabilité du partage","points":5},{"critere":"Message 4 : atteinte au droit à l’image même sans insulte","points":4},{"critere":"Pseudonyme : traçable par l’adresse IP, loi identique en ligne","points":3}],"dureeMin":12,"corrige":"1.\n- **Message 1** : **protégé**. Inès critique une religion, c’est-à-dire une **idée** ; critiquer une religion n’est pas un délit en France. Elle ne vise aucune personne.\n- **Message 2** : **puni**. C’est une **diffamation** : l’affirmation d’un **fait précis et faux** qui porte atteinte à l’**honneur** de Mme Duval.\n- **Message 3** : **puni**. La vidéo est une **provocation à la violence** (et à la haine) en raison de l’**origine** : elle appelle à s’en prendre à des **personnes**.\n- **Message 4** : **interdit**. Diffuser l’image de quelqu’un **sans son accord** porte atteinte à son **droit à l’image**, même si la photo n’est pas insultante.\n\n2. Non. La loi s’applique **exactement de la même façon** sur internet, et le message est **traçable par l’adresse IP** : le pseudonyme ne protège pas.\n\n3. Publier, partager, retweeter, c’est **diffuser**. Le partage d’un contenu illicite **engage aussi celui qui partage** : Théo est responsable d’avoir diffusé cette vidéo."}$exo$::jsonb),
  ('b2c56dae-8863-5ab9-a39d-3e650eb92870'::uuid, 3, 'redaction', $exo${"titre":"Protéger ce qui dérange","consigne":"Lis le document, réponds aux questions puis rédige un paragraphe argumenté.","enonce":"**Document — Débat en classe**\n\n> **Maël** : « La liberté d’expression, c’est simple : il faut interdire tout ce qui choque quelqu’un. Si une caricature d’une religion blesse des croyants, on devrait la retirer. »\n> **Lou** : « Non, si on interdit tout ce qui choque, il ne reste que ce qui plaît à tout le monde. Mais ça ne veut pas dire qu’on peut tout dire. »\n\n1. Quel texte et quel article posent la libre communication des pensées et des opinions ?\n2. Selon le cours, pourquoi « une opinion consensuelle n’a besoin d’aucune protection » ? Qui, de Maël ou de Lou, s’en rapproche ?\n3. Une caricature d’une religion est-elle punie par la loi française ? Et un dessin qui appelle à frapper les croyants de cette religion ? Justifie.\n4. **Paragraphe argumenté** (une dizaine de lignes) : « La liberté d’expression, c’est pouvoir tout dire. » Discute cette affirmation en t’appuyant sur la frontière entre l’idée et la personne, et sur au moins deux délits précis.","bareme":[{"critere":"Déclaration de 1789, article 11","points":3},{"critere":"Explication : la liberté protège surtout ce qui dérange ; Lou identifiée","points":4},{"critere":"Caricature protégée / appel à la violence puni, distinction justifiée","points":4},{"critere":"Paragraphe : thèse nuancée, frontière idée/personne expliquée","points":5},{"critere":"Au moins deux délits précis correctement utilisés comme limites","points":4}],"dureeMin":18,"corrige":"1. La **Déclaration des droits de l’homme et du citoyen de 1789**, **article 11**.\n\n2. Une opinion que tout le monde partage ne risque pas d’être interdite : personne ne veut la faire taire. La liberté d’expression existe donc précisément pour **ce qui dérange**. **Lou** s’en rapproche : interdire ce qui choque ne laisserait que ce qui plaît à tous.\n\n3. La **caricature d’une religion** n’est **pas punie** : elle critique une **idée** ; critiquer une religion n’est pas un délit en France. En revanche, un dessin qui **appelle à frapper les croyants** vise des **personnes** : c’est une **provocation à la violence** (ou à la haine) en raison de la religion, un délit.\n\n4. Paragraphe attendu :\n- l’affirmation est **fausse** telle quelle : la liberté d’expression est large (penser, dire, écrire, publier, **critiquer**), elle protège même ce qui choque ;\n- mais la loi (loi de **1881**) punit certains **actes de parole** : l’**injure**, la **diffamation**, la **provocation à la haine ou à la violence**, l’**apologie du terrorisme**, la **négation de crimes contre l’humanité**, le **harcèlement** et les **menaces** ;\n- la frontière n’est pas entre le poli et l’impoli mais entre l’**idée** (qu’on peut attaquer) et la **personne** (qu’on ne peut ni insulter, ni calomnier, ni désigner à la violence) ;\n- conclusion : on peut tout **critiquer**, mais on ne peut pas tout **faire avec des mots** ; ces règles valent aussi en ligne."}$exo$::jsonb),
  ('c7e7d8da-139b-5834-99ef-74e2e7d5d907'::uuid, 1, 'redaction', $exo${"titre":"Mes traces en ligne","consigne":"Réponds à chaque question en phrases complètes.","enonce":"1. Quel article de loi protège la **vie privée** en France ? Cite deux éléments qu’il protège.\n2. Définis l’**identité numérique** et cite ses **trois couches**.\n3. Cite **deux droits** que le RGPD donne à chacun sur ses données.\n4. À partir de quel âge peut-on, en France, consentir **seul** au traitement de ses données ? Et avant ?","bareme":[{"critere":"Article 9 du Code civil et deux éléments protégés","points":5},{"critere":"Identité numérique définie et trois couches citées","points":7},{"critere":"Deux droits du RGPD exacts","points":4},{"critere":"15 ans ; en dessous, accord d’un parent","points":4}],"dureeMin":7,"corrige":"1. L’**article 9 du Code civil**. Il protège notamment le domicile, la santé, la vie sentimentale, les convictions, l’image (deux attendus).\n\n2. L’identité numérique est l’**ensemble des traces laissées en ligne, volontaires ou non**. Ses trois couches :\n- ce qu’on **publie** soi-même (photos, messages, profils) ;\n- ce que **d’autres publient** sur nous ;\n- ce que les services **enregistrent** sans qu’on le voie (recherches, position, temps passé, achats).\n\n3. Deux droits parmi : l’**accès** (savoir quelles données sont détenues), la **rectification** (les corriger), l’**effacement** (« droit à l’oubli »), l’**opposition** (refuser un usage).\n\n4. À **15 ans**. En dessous, il faut l’**accord d’un parent**."}$exo$::jsonb),
  ('c7e7d8da-139b-5834-99ef-74e2e7d5d907'::uuid, 2, 'redaction', $exo${"titre":"L’application gratuite de Jade","consigne":"Lis la situation puis réponds aux questions en justifiant avec le cours.","enonce":"**Situation.** Jade, 14 ans, installe « PhotoFun », une application gratuite de retouche. Elle accepte tout sans lire. Quelques jours plus tard, elle reçoit des publicités pour des baskets qu’elle avait seulement cherchées sur un autre site. Par ailleurs, elle a supprimé une photo gênante publiée l’an dernier, mais une amie lui montre une capture d’écran qui circule encore.\n\n1. Comment les publicités peuvent-elles connaître les recherches de Jade ? Nomme l’outil utilisé et ce qu’il sert à construire.\n2. « L’application est gratuite, donc elle ne me coûte rien », dit Jade. Explique pourquoi c’est faux.\n3. Jade a-t-elle pu accepter seule les conditions de l’application ? Justifie.\n4. Pourquoi la suppression de sa photo n’a-t-elle pas suffi ? Donne deux réflexes qu’elle aurait pu avoir.","bareme":[{"critere":"Cookies expliqués : suivi d’un site à l’autre, profil publicitaire","points":5},{"critere":"Gratuité : ce qui est vendu, c’est l’attention et le profil","points":5},{"critere":"Moins de 15 ans : accord d’un parent nécessaire","points":4},{"critere":"Permanence (copie, capture, archive) et deux réflexes pertinents","points":6}],"dureeMin":11,"corrige":"1. Grâce aux **cookies** publicitaires : ils **suivent la navigation d’un site à l’autre** pour construire un **profil publicitaire**. D’autres traces s’y ajoutent (adresse IP, appareil, heure, page d’où l’on vient).\n\n2. Quand un service est gratuit, ce n’est pas un cadeau : **ce qui est vendu, c’est l’attention et le profil de l’utilisateur**. Jade « paie » avec ses données.\n\n3. Non. En France, l’âge du consentement autonome au traitement des données est **15 ans** ; à 14 ans, il faut l’**accord d’un parent**.\n\n4. Un contenu publié est **copiable** et **archivé** : supprimer ne supprime pas les **captures d’écran** déjà faites. Une publication peut ressortir des années plus tard.\nRéflexes (deux) : **réfléchir avant de publier** ; régler la **confidentialité** de ses comptes ; utiliser des **mots de passe distincts** ; lire ce qu’on accepte. Elle peut aussi demander l’**effacement** (RGPD) et saisir la **CNIL**."}$exo$::jsonb),
  ('c7e7d8da-139b-5834-99ef-74e2e7d5d907'::uuid, 3, 'redaction', $exo${"titre":"Dix ans plus tard","consigne":"Lis le document, réponds aux questions puis rédige un paragraphe argumenté.","enonce":"**Document — Témoignage imaginé**\n\n> « J’ai 25 ans et je postule dans une agence. Au deuxième entretien, le recruteur me montre une vidéo de moi en 4e, filmée par un camarade pendant une fête et publiée sans me demander. Je l’avais oubliée. Je ne l’avais même jamais publiée moi-même. » — Nathan\n\n1. À quelle **couche** de l’identité numérique appartient cette vidéo ? Justifie.\n2. Le camarade avait-il le droit de diffuser cette vidéo ? Quel texte protège Nathan ?\n3. Quels **droits du RGPD** Nathan peut-il faire valoir, et auprès de quelle autorité peut-il se plaindre ? Depuis quand ce règlement s’applique-t-il ?\n4. **Paragraphe argumenté** (une dizaine de lignes) : « Ce que je publie ne regarde que moi. » Montre les limites de cette phrase en t’appuyant sur les trois couches de l’identité numérique, la permanence des contenus et la responsabilité envers les autres.","bareme":[{"critere":"Couche « ce que d’autres publient » identifiée et justifiée","points":3},{"critere":"Diffusion sans accord interdite, article 9 du Code civil / droit à l’image","points":4},{"critere":"Droits (effacement, opposition…), CNIL, RGPD en 2018","points":4},{"critere":"Paragraphe : trois couches et permanence mobilisées","points":5},{"critere":"Paragraphe : responsabilité envers autrui (image d’autrui, image intime)","points":4}],"dureeMin":18,"corrige":"1. C’est la couche de **ce que d’autres publient sur nous**, sans qu’on l’ait choisi : Nathan n’a jamais publié cette vidéo, c’est un camarade qui l’a fait.\n\n2. Non. Filmer quelqu’un et **diffuser l’image sans son accord est interdit**. L’**article 9 du Code civil** protège la vie privée, dont l’**image**.\n\n3. Il peut exercer son **droit à l’effacement** (« droit à l’oubli ») et son **droit d’opposition**, ainsi que son droit d’**accès** pour savoir ce qui est détenu. Il peut saisir la **CNIL**. Le **RGPD** est entré en application en **2018**.\n\n4. Paragraphe attendu :\n- la phrase oublie que notre identité numérique a **trois couches** : ce que je publie, mais aussi **ce que d’autres publient sur moi** et **ce que les services enregistrent** sans que je le voie ;\n- un contenu est **copiable et archivé** : une publication de collège peut ressortir **dix ans plus tard**, devant un employeur ; supprimer n’efface pas les captures ;\n- ce que je publie concerne aussi **les autres** : publier une photo d’autrui touche à **sa** vie privée ; il faut réfléchir avant de publier l’image de quelqu’un ; diffuser une **image intime** est un **délit** lourdement puni ;\n- conclusion : publier engage soi-même et autrui, d’où les réflexes (confidentialité, mots de passe distincts, réflexion avant de publier)."}$exo$::jsonb),
  ('4e512c0e-ff95-5285-96dc-155942cda412'::uuid, 1, 'redaction', $exo${"titre":"Les piliers de la laïcité","consigne":"Réponds à chaque question en phrases complètes.","enonce":"1. La laïcité est-elle une croyance ? Définis-la en une phrase.\n2. Cite et explique les **trois piliers** de la laïcité.\n3. Quelles sont les **deux faces** de la loi de 1905 ?\n4. Qui est tenu à la **neutralité religieuse** : les agents publics ou les usagers ? Précise dans quel cadre.","bareme":[{"critere":"Principe d’organisation de l’État, pas une croyance","points":4},{"critere":"Trois piliers cités et expliqués","points":6},{"critere":"Libre exercice des cultes et neutralité de l’État","points":5},{"critere":"Agents publics dans l’exercice de leurs fonctions ; usagers libres","points":5}],"dureeMin":7,"corrige":"1. Non. La laïcité n’est pas une croyance : c’est un **principe d’organisation de l’État**.\n\n2. Les trois piliers :\n- la **liberté de conscience** : croire, ne pas croire, changer, pratiquer ou non ;\n- la **séparation** : l’État ne reconnaît, ne salarie ni ne subventionne aucun culte ;\n- l’**égalité** : tous les citoyens sont égaux devant la loi, quelle que soit leur croyance.\n\n3. La loi de 1905 garantit à la fois le **libre exercice des cultes** et la **neutralité de l’État** : ce sont les deux faces du même texte.\n\n4. Ce sont les **agents publics** (enseignants, policiers, employés de mairie) qui doivent la neutralité, **dans l’exercice de leurs fonctions** (pas dans leur vie privée). Les **usagers** d’un service public sont **libres**, sauf exception prévue par la loi."}$exo$::jsonb),
  ('4e512c0e-ff95-5285-96dc-155942cda412'::uuid, 2, 'redaction', $exo${"titre":"Qui peut porter quoi, et où ?","consigne":"Pour chaque situation, dis si le port du signe religieux est autorisé et justifie avec le cours.","enonce":"**Situations.**\n\n- **A.** Amira, élève de 3e dans un collège public, veut venir en cours avec un grand voile.\n- **B.** Sa sœur Leïla, étudiante à l’université, porte le même voile en amphithéâtre.\n- **C.** M. Levy, professeur de mathématiques au collège public, souhaite porter une kippa pendant ses cours.\n- **D.** Paul porte une grande croix en pendentif dans la rue et à la mairie, où il vient chercher un papier.\n- **E.** Élise est élève dans un lycée privé sous contrat et porte une croix visible.\n\n1. Pour chaque situation, indique si c’est autorisé et pourquoi.\n2. Quelle loi s’applique dans la situation A ? Donne sa date exacte.","bareme":[{"critere":"A interdit (élève d’établissement public, signe ostensible)","points":4},{"critere":"B et E autorisés (université, privé sous contrat hors loi de 2004)","points":4},{"critere":"C interdit : agent public neutre dans ses fonctions","points":4},{"critere":"D autorisé : usager et espace public libres","points":4},{"critere":"Loi du 15 mars 2004 citée","points":4}],"dureeMin":10,"corrige":"1.\n- **A** : **interdit**. Dans les écoles, collèges et lycées **publics**, les signes religieux **ostensibles** sont interdits **aux élèves**.\n- **B** : **autorisé**. La loi de 2004 ne s’applique **pas à l’université**.\n- **C** : **interdit**. M. Levy est un **agent public** : il doit être **neutre dans l’exercice de ses fonctions** (il reste libre dans sa vie privée).\n- **D** : **autorisé**. On peut porter un signe religieux **dans la rue** ; à la mairie, Paul est un **usager**, et les usagers sont libres.\n- **E** : **autorisé**. La loi de 2004 ne s’applique pas aux **établissements privés sous contrat**.\n\n2. La **loi du 15 mars 2004**, qui interdit les signes religieux ostensibles aux élèves des écoles, collèges et lycées publics."}$exo$::jsonb),
  ('4e512c0e-ff95-5285-96dc-155942cda412'::uuid, 3, 'redaction', $exo${"titre":"La laïcité, contre les religions ?","consigne":"Lis le document, réponds aux questions puis rédige un paragraphe argumenté.","enonce":"**Document — Un commentaire lu sur un forum**\n\n> « La laïcité, c’est l’athéisme officiel de la France : l’État veut faire disparaître les religions de l’espace public. D’ailleurs, c’est pareil partout en France. »\n\n1. Relève dans ce commentaire **trois affirmations fausses** et corrige chacune avec le cours.\n2. Quelle est la première face de la loi de 1905, souvent oubliée ?\n3. Explique l’exception de l’**Alsace-Moselle** : pourquoi existe-t-elle et que permet-elle ?\n4. **Paragraphe argumenté** (une dizaine de lignes) : explique la phrase du cours « La laïcité ne protège pas la République contre les religions. Elle protège chaque croyant du pouvoir des autres croyances — et l’incroyant de toutes. »","bareme":[{"critere":"Trois affirmations fausses corrigées (athéisme, effacement, uniformité)","points":6},{"critere":"Libre exercice des cultes cité","points":2},{"critere":"Alsace-Moselle : allemande en 1905, Concordat, cultes reconnus","points":4},{"critere":"Paragraphe : liberté de conscience et égalité reliées à la protection de chacun","points":5},{"critere":"Paragraphe : rôle de la séparation et de la neutralité de l’État","points":3}],"dureeMin":17,"corrige":"1.\n- « L’athéisme officiel » : faux. **L’État n’a pas d’opinion sur Dieu** ; la laïcité n’est pas l’athéisme d’État.\n- « Faire disparaître les religions de l’espace public » : faux. On peut **porter un signe religieux dans la rue**, exprimer sa foi, se réunir. Seuls les agents publics (dans leurs fonctions) et, par la loi de 2004, les élèves des établissements publics ont des obligations.\n- « Pareil partout en France » : faux. En **Alsace-Moselle**, le **Concordat** est toujours en vigueur.\n\n2. Le **libre exercice des cultes** (l’autre face étant la neutralité de l’État).\n\n3. En 1905, l’Alsace-Moselle était **allemande** : la loi de séparation ne s’y est pas appliquée. Le **Concordat** y est toujours en vigueur : **certains cultes sont reconnus** et des **enseignements religieux** sont organisés. La laïcité française n’est donc pas parfaitement uniforme.\n\n4. Paragraphe attendu :\n- la laïcité garantit la **liberté de conscience** : chacun peut croire, ne pas croire, changer de religion ;\n- par la **séparation**, l’État ne soutient aucun culte : aucune religion ne peut se servir de l’État pour s’imposer aux autres ; c’est ce qui protège **chaque croyant du pouvoir des autres croyances** ;\n- l’incroyant est protégé lui aussi : aucune croyance ne peut lui être imposée ;\n- l’**égalité** devant la loi, quelle que soit la croyance, et la **neutralité** des agents publics assurent que chacun est traité de la même façon ;\n- conclusion : la laïcité n’est pas une arme contre les religions mais un **mode d’organisation** qui vise l’égalité et la liberté de tous."}$exo$::jsonb),
  ('bae0d5e3-108c-5633-9670-f956d75f0efb'::uuid, 1, 'redaction', $exo${"titre":"L’organisation de la justice","consigne":"Réponds à chaque question en phrases complètes ; recopie et complète le tableau.","enonce":"1. Quels sont les **deux ordres de juridiction** ? Que juge chacun ?\n2. Recopie et complète le tableau :\n\n| Infraction | Tribunal | Exemple |\n|---|---|---|\n| Contravention | … | … |\n| Délit | … | … |\n| Crime | … | … |\n\n3. Que signifie la **présomption d’innocence** ?","bareme":[{"critere":"Ordres judiciaire et administratif et leur rôle","points":6},{"critere":"Tableau : trois tribunaux justes et trois exemples pertinents","points":9},{"critere":"Présomption d’innocence correctement définie","points":5}],"dureeMin":7,"corrige":"1. L’ordre **judiciaire** juge les litiges entre personnes et les infractions. L’ordre **administratif** juge les litiges entre les citoyens et l’**administration** (tribunal administratif, Conseil d’État).\n\n2.\n| Infraction | Tribunal | Exemple |\n|---|---|---|\n| Contravention | Tribunal de police | Excès de vitesse |\n| Délit | Tribunal correctionnel | Vol, discrimination |\n| Crime | Cour d’assises / cour criminelle | Meurtre, viol |\n\n3. Toute personne est **innocente jusqu’à sa condamnation définitive**. C’est à l’accusation de prouver la culpabilité, pas à l’accusé de prouver son innocence."}$exo$::jsonb),
  ('bae0d5e3-108c-5633-9670-f956d75f0efb'::uuid, 2, 'redaction', $exo${"titre":"Trois affaires, trois tribunaux","consigne":"Lis les situations et réponds aux questions en justifiant avec le cours.","enonce":"**Situations.**\n\n- **A.** Mme Roux et son voisin se disputent depuis des mois au sujet d’une haie trop haute.\n- **B.** Sofiane, 19 ans, est arrêté pour avoir volé un scooter.\n- **C.** La famille Morel conteste la décision de la mairie qui refuse l’inscription de leur fille à la cantine.\n\n1. Pour chaque affaire, dis si elle relève de la justice **civile**, **pénale** ou **administrative**, et devant quel tribunal elle sera jugée (pour A, contente-toi de l’ordre et de la nature).\n2. Dans l’affaire A, y a-t-il un « coupable » ? Explique.\n3. Dans l’affaire B, qui engage les poursuites contre Sofiane ? Qui le défend ? Qui consigne les débats ?\n4. Sofiane est condamné mais estime le jugement injuste. Quel principe lui permet de le contester ?","bareme":[{"critere":"A civil (judiciaire), B pénal au tribunal correctionnel, C tribunal administratif","points":6},{"critere":"Pas de coupable au civil : un litige à régler","points":4},{"critere":"Procureur, avocat, greffier correctement attribués","points":6},{"critere":"Double degré de juridiction : droit de faire appel","points":4}],"dureeMin":11,"corrige":"1.\n- **A** : justice **civile** (ordre judiciaire) : un conflit entre particuliers, de voisinage.\n- **B** : justice **pénale** : le vol est un **délit**, jugé par le **tribunal correctionnel**.\n- **C** : justice **administrative** : litige entre des citoyens et l’**administration** (la mairie), jugé par le **tribunal administratif**.\n\n2. Non. Le civil tranche un conflit entre particuliers : il n’y a **pas de coupable**, mais un **litige à régler**.\n\n3. Le **procureur** représente la société et engage les poursuites ; l’**avocat** défend Sofiane ; le **greffier** consigne les débats (le juge tranche).\n\n4. Le **double degré de juridiction** : il a le **droit de faire appel**, pour être rejugé."}$exo$::jsonb),
  ('bae0d5e3-108c-5633-9670-f956d75f0efb'::uuid, 3, 'redaction', $exo${"titre":"Juger un mineur","consigne":"Lis le document, réponds aux questions puis rédige un paragraphe argumenté.","enonce":"**Document — Réaction sur un réseau social**\n\n> « Un garçon de 14 ans a été arrêté après une bagarre qui a gravement blessé un autre élève. On connaît déjà le coupable, pas besoin de procès. Et il devrait être puni exactement comme un adulte, en audience publique, pour servir d’exemple. »\n\n1. Quel principe de la justice cette réaction ignore-t-elle quand elle dit « on connaît déjà le coupable » ? Explique pourquoi ce principe n’est pas une simple politesse.\n2. Cite **trois droits de la défense**.\n3. Quel juge est compétent pour ce garçon ? Que privilégie-t-il ?\n4. Une peine est-elle possible à 14 ans ? Explique l’**excuse de minorité**. L’audience sera-t-elle publique ?\n5. **Paragraphe argumenté** (une dizaine de lignes) : pourquoi la justice juge-t-elle les mineurs autrement que les adultes ? Appuie-toi sur les notions de discernement, d’éducatif et de garanties du procès.","bareme":[{"critere":"Présomption d’innocence : l’accusation doit prouver","points":4},{"critere":"Trois droits de la défense (informé, avocat, se taire)","points":3},{"critere":"Juge des enfants, priorité à l’éducatif","points":3},{"critere":"Peine possible dès 13 ans, atténuée (excuse de minorité), débats non publics","points":4},{"critere":"Paragraphe argumenté mobilisant discernement, éducatif et garanties","points":6}],"dureeMin":18,"corrige":"1. La **présomption d’innocence** : on est innocent **jusqu’à condamnation définitive**. Ce n’est pas une politesse : c’est ce qui **oblige l’accusation à prouver**, plutôt que l’accusé à se disculper. Sans procès, on risque de condamner sans preuve.\n\n2. Être **informé** (des faits reprochés), être **assisté d’un avocat**, **se taire**.\n\n3. Le **juge des enfants**. Il privilégie l’**éducatif** sur le répressif.\n\n4. Oui : à partir de **13 ans**, une peine est possible, mais elle est **atténuée** : c’est l’**excuse de minorité**. L’audience n’est **pas publique** : pour les mineurs, les débats ne sont pas publics.\n\n5. Paragraphe attendu :\n- la responsabilité pénale suppose le **discernement**, qui se construit avec l’âge : un mineur n’est pas jugé comme un adulte ;\n- la justice des mineurs est **spécifique** : le juge des enfants cherche d’abord à **éduquer**, pour éviter la récidive et permettre au jeune de se reconstruire ;\n- la peine reste possible dès 13 ans, mais atténuée (excuse de minorité) : la sanction existe, la victime est reconnue ;\n- les **garanties** du procès valent pour tous : présomption d’innocence, droits de la défense, contradictoire, appel ; la **non-publicité** protège l’avenir du mineur ;\n- conclusion : « servir d’exemple » en public irait contre ces principes."}$exo$::jsonb),
  ('cfacad16-529e-5ff4-9e23-ad46c335a483'::uuid, 1, 'redaction', $exo${"titre":"Nationalité et citoyenneté","consigne":"Réponds à chaque question en phrases complètes.","enonce":"1. Quelle est la différence entre la **nationalité** et la **citoyenneté** ?\n2. Cite **trois voies** pour devenir français.\n3. Cite **deux droits** et **deux devoirs** du citoyen.\n4. Que doit faire un jeune à **16 ans** ?","bareme":[{"critere":"Distinction : lien juridique / participation à la vie politique","points":5},{"critere":"Trois voies d’accès à la nationalité exactes","points":6},{"critere":"Deux droits et deux devoirs corrects","points":5},{"critere":"Recensement obligatoire à 16 ans (et JDC)","points":4}],"dureeMin":7,"corrige":"1. La **nationalité** est le **lien juridique** avec un État. La **citoyenneté** y ajoute la **participation à la vie politique** : voter, être élu, exercer certaines fonctions.\n\n2. Trois voies parmi : la **filiation** (au moins un parent français) ; la **naissance et la résidence** en France (droit du sol, français à 18 ans sous condition de résidence) ; la **naturalisation** ; le **mariage** (sous conditions).\n\n3. Droits : voter, être élu, adhérer à un parti, s’exprimer, circuler, être propriétaire, se réunir, droit à l’éducation, à la santé, à la protection sociale.\nDevoirs : respecter la **loi**, **payer l’impôt**, être **juré** si l’on est tiré au sort, se faire **recenser** et suivre la **JDC**.\n\n4. Se faire **recenser** (en mairie ou en ligne) : c’est obligatoire. Vient ensuite la **Journée défense et citoyenneté**."}$exo$::jsonb),
  ('cfacad16-529e-5ff4-9e23-ad46c335a483'::uuid, 2, 'redaction', $exo${"titre":"Une famille européenne","consigne":"Lis la situation et réponds aux questions en justifiant avec le cours.","enonce":"**Situation.** Marco est italien et vit à Lyon depuis six ans. Sa fille Giulia est née à Lyon ; ses deux parents sont italiens. Elle a aujourd’hui 16 ans et vit en France depuis sa naissance.\n\n1. Marco peut-il voter aux élections **municipales** de Lyon ? À l’élection **présidentielle** ? Justifie.\n2. Lors d’un voyage en Thaïlande, Marco perd son passeport ; il n’y a pas de consulat italien dans la ville. Quel droit lié à la citoyenneté européenne peut l’aider ?\n3. Giulia peut-elle devenir française ? Par quelle voie et à quel âge ?\n4. La citoyenneté européenne de Marco remplace-t-elle sa citoyenneté italienne ?","bareme":[{"critere":"Municipales oui (citoyen de l’UE résident), présidentielle non","points":6},{"critere":"Protection consulaire de n’importe quel État membre","points":4},{"critere":"Droit du sol : française à 18 ans sous condition de résidence","points":6},{"critere":"La citoyenneté européenne s’ajoute, ne remplace pas","points":4}],"dureeMin":10,"corrige":"1. **Municipales : oui.** Un citoyen de l’Union européenne peut voter aux élections **municipales** et **européennes** dans son pays de résidence. **Présidentielle : non**, elle est réservée aux citoyens français.\n\n2. La **protection consulaire** : hors d’Europe, un citoyen européen peut obtenir la protection du consulat de **n’importe quel État membre** (par exemple celui de la France).\n\n3. Oui, par la voie de la **naissance et de la résidence** (le **droit du sol**) : née en France de parents étrangers, elle deviendra française à **18 ans**, sous condition de résidence.\n\n4. Non. La citoyenneté européenne **s’ajoute** à la citoyenneté nationale, elle ne la remplace pas."}$exo$::jsonb),
  ('cfacad16-529e-5ff4-9e23-ad46c335a483'::uuid, 3, 'redaction', $exo${"titre":"Des droits en échange de devoirs ?","consigne":"Lis le document, réponds aux questions puis rédige un paragraphe argumenté.","enonce":"**Document — Discussion entre deux élèves**\n\n> **Hugo** : « Moi, je ne veux pas faire la JDC, ça ne sert à rien. Et les impôts, c’est de l’argent perdu. »\n> **Awa** : « Tu sais qu’on te demandera l’attestation pour le bac ? Et puis ton collège, qui le paie d’après toi ? »\n> **Hugo** : « De toute façon, si je ne remplis pas mes devoirs, on n’a qu’à me retirer mes droits, c’est l’échange. »\n\n1. Qu’est-ce que la JDC ? À quel âge a-t-elle lieu, et pourquoi Hugo aura-t-il besoin de son attestation ?\n2. Classe les droits du citoyen en trois familles et donne un exemple pour chacune.\n3. Hugo dit que les droits sont « l’échange » des devoirs. Que répond le cours ?\n4. **Paragraphe argumenté** (une dizaine de lignes) : montre, à partir de l’exemple de l’impôt, pourquoi les droits du citoyen dépendent de ce que chacun remplit ses devoirs, sans en être la contrepartie.","bareme":[{"critere":"JDC définie, après le recensement, attestation exigée pour bac et permis","points":4},{"critere":"Trois familles de droits (politiques, civils, sociaux) avec exemples","points":5},{"critere":"Les droits existent d’abord, ne sont pas une contrepartie","points":4},{"critere":"Paragraphe : l’impôt finance école, hôpital, justice ; lien droits/devoirs nuancé","points":7}],"dureeMin":17,"corrige":"1. La **Journée défense et citoyenneté**, qui suit le **recensement obligatoire à 16 ans** (elle a lieu entre 16 et 18 ans). Son **attestation** est exigée pour s’inscrire au **baccalauréat** et au **permis de conduire**.\n\n2.\n- Droits **politiques** : voter, être élu, adhérer à un parti.\n- Droits **civils** : liberté d’expression, de circulation, de réunion, droit de propriété.\n- Droits **sociaux** : éducation, santé, protection sociale.\n\n3. Les droits **ne sont pas la contrepartie des devoirs** : ils **existent d’abord**. On ne les « retire » pas à celui qui ne remplit pas ses devoirs comme dans un échange.\n\n4. Paragraphe attendu :\n- les droits appartiennent à chaque citoyen sans condition d’« échange » ;\n- mais **aucun ne tiendrait si personne ne remplissait les devoirs** : l’**école** qu’Hugo fréquente, l’**hôpital** et la **justice** sont **payés par l’impôt** ; le droit à l’éducation ou à la santé suppose que les citoyens paient l’impôt ;\n- de même, la justice suppose des **jurés** tirés au sort, et la loi n’a de force que si chacun la **respecte** ;\n- conclusion : l’impôt n’est pas de l’argent perdu, il rend possibles les droits de tous ; droits et devoirs sont liés, sans être un marché."}$exo$::jsonb),
  ('a49cc1af-5705-5dc4-98f8-09f053b051a0'::uuid, 1, 'redaction', $exo${"titre":"Le suffrage et ses conquêtes","consigne":"Réponds à chaque question en phrases complètes.","enonce":"1. Cite et explique les **quatre caractères** du suffrage en France.\n2. Donne la date de chacune de ces étapes :\n   - suffrage universel masculin ;\n   - droit de vote des femmes ;\n   - majorité abaissée à 18 ans.\n3. Cite **deux conditions** pour pouvoir voter.","bareme":[{"critere":"Quatre caractères cités et expliqués","points":8},{"critere":"Trois dates exactes (1848, 1944, 1974)","points":8},{"critere":"Deux conditions exactes","points":4}],"dureeMin":7,"corrige":"1.\n- **Universel** : tous les citoyens majeurs votent.\n- **Égal** : une personne, une voix.\n- **Secret** : l’isoloir et l’enveloppe (depuis 1913).\n- **Libre** : aucune pression.\n\n2.\n- Suffrage universel masculin : **1848**.\n- Droit de vote des femmes : **1944** (exercé pour la première fois en 1945).\n- Majorité abaissée de 21 à 18 ans : **1974**.\n\n3. Deux conditions parmi : être **français** (sauf municipales et européennes, ouvertes aux citoyens de l’UE résidents), avoir **18 ans**, être **inscrit** sur les listes électorales, jouir de ses **droits civiques**."}$exo$::jsonb),
  ('a49cc1af-5705-5dc4-98f8-09f053b051a0'::uuid, 2, 'redaction', $exo${"titre":"Le dépouillement de Villeneuve","consigne":"Lis les résultats, fais les calculs et réponds en justifiant avec le cours.","enonce":"**Situation.** Dans la commune imaginaire de Villeneuve, 2 000 électeurs sont inscrits. Voici le dépouillement d’un scrutin :\n\n| Donnée | Nombre |\n|---|---|\n| Votants | 1 200 |\n| Bulletins blancs | 60 |\n| Bulletins nuls | 40 |\n| Liste A | 550 |\n| Liste B | 330 |\n| Liste C | 220 |\n\n1. Combien d’électeurs se sont **abstenus** ? Quel est le taux d’abstention ?\n2. Calcule le nombre de **suffrages exprimés**. Explique pourquoi les blancs et les nuls n’y entrent pas, et distingue vote blanc et vote nul.\n3. Calcule le pourcentage de la liste A parmi les exprimés.\n4. Aux municipales, qui les habitants élisent-ils directement, et pour combien de temps ?","bareme":[{"critere":"Abstention : 800 électeurs, 40 %","points":4},{"critere":"Exprimés : 1 100, avec blanc/nul distingués et exclus","points":6},{"critere":"Liste A : 50 % des exprimés, calcul posé","points":4},{"critere":"Conseil municipal élu pour 6 ans, qui élit le maire","points":6}],"dureeMin":12,"corrige":"1. Abstentionnistes : 2 000 − 1 200 = **800**. Taux d’abstention : 800 / 2 000 = **40 %**.\n\n2. Exprimés = votants − blancs − nuls = 1 200 − 60 − 40 = **1 100** (on vérifie : 550 + 330 + 220 = 1 100). Le résultat est calculé sur les **suffrages exprimés**. Le **vote blanc** (enveloppe vide) est **décompté séparément depuis 2014**, sans entrer dans les exprimés ; le **vote nul** est un bulletin abîmé ou raturé.\n\n3. 550 / 1 100 × 100 = **50 %** des suffrages exprimés.\n\n4. Les habitants élisent le **conseil municipal**, pour **6 ans** ; c’est le conseil municipal qui **élit ensuite le maire**."}$exo$::jsonb),
  ('a49cc1af-5705-5dc4-98f8-09f053b051a0'::uuid, 3, 'redaction', $exo${"titre":"Le mode de scrutin fabrique le résultat","consigne":"Fais les calculs demandés, puis rédige un paragraphe argumenté.","enonce":"**Situation.** Une assemblée imaginaire compte **10 sièges**. Quatre partis obtiennent : Parti Vert 40 %, Parti Bleu 30 %, Parti Rouge 20 %, Parti Jaune 10 % des suffrages exprimés.\n\n1. Avec un scrutin **majoritaire** où celui qui a le plus de voix emporte tous les sièges, combien de sièges obtient chaque parti ?\n2. Avec un scrutin **proportionnel** (sièges répartis selon les scores), combien de sièges obtient chaque parti ?\n3. Quels sont les avantages et les inconvénients de chaque mode de scrutin ?\n4. Dans cette ville, 55 % des inscrits se sont abstenus. Un habitant dit : « Je n’ai pas voté, comme ça je bloque le système. » A-t-il raison ?\n5. **Paragraphe argumenté** (une dizaine de lignes) : « Le mode de scrutin est un simple détail technique. » Discute cette affirmation.","bareme":[{"critere":"Majoritaire : Vert 10 sièges, les trois autres 0","points":3},{"critere":"Proportionnel : Vert 4, Bleu 3, Rouge 2, Jaune 1","points":3},{"critere":"Avantages et inconvénients des deux modes","points":5},{"critere":"Abstention : ne bloque rien, résultat sur les exprimés, poids des autres accru","points":4},{"critere":"Paragraphe : le mode de scrutin fabrique une part du résultat","points":5}],"dureeMin":18,"corrige":"1. Majoritaire : **Parti Vert 10 sièges**, Bleu, Rouge et Jaune 0. Avec 40 % des voix, il obtient 100 % des sièges.\n\n2. Proportionnel : 40 % de 10 = **4 sièges** pour le Vert ; 30 % de 10 = **3** pour le Bleu ; 20 % de 10 = **2** pour le Rouge ; 10 % de 10 = **1** pour le Jaune. Total : 10 sièges, chaque parti est représenté selon son score.\n\n3.\n- **Majoritaire** : dégage des **majorités nettes** (gouverner est plus facile), mais **laisse des voix sans représentation** (60 % des électeurs ici, qui n’ont aucun élu).\n- **Proportionnel** : **représente mieux la diversité** des opinions, mais rend les **majorités plus difficiles** à former.\n\n4. Non. Ne pas voter est un droit mais **ce n’est pas un vote** : le résultat est calculé sur les **suffrages exprimés**. S’abstenir **ne bloque rien** : cela laisse d’autres décider à sa place, avec un **poids relatif plus grand**.\n\n5. Paragraphe attendu : l’affirmation est fausse. Avec les **mêmes voix**, le Parti Vert obtient 10 sièges ou 4 selon le mode de scrutin : **aucun mode n’est neutre**, il **fabrique une part du résultat**. Le choix oppose deux objectifs : la **stabilité** (majoritaire) et la **représentation** (proportionnel). C’est donc un choix politique, qui concerne tous les citoyens."}$exo$::jsonb),
  ('2c182b11-baeb-5575-8a2c-21eebf445d1b'::uuid, 1, 'redaction', $exo${"titre":"Information, opinion, rumeur","consigne":"Réponds à chaque question en phrases complètes.","enonce":"1. Donne les **quatre caractéristiques** d’une information au sens journalistique.\n2. Classe ces quatre contenus en **information**, **opinion**, **rumeur** ou **publicité** :\n   - a. « Il paraît que le collège va fermer, un copain l’a entendu. »\n   - b. « Ce film est le meilleur de l’année. »\n   - c. « Le conseil municipal a voté hier le budget 2027, selon le compte rendu publié sur le site de la mairie. » (article signé)\n   - d. « Avec la crème Luxa, adieu les boutons ! »\n3. Qu’est-ce qu’une **infox** ?","bareme":[{"critere":"Vérifié, sourcé, daté, signé","points":6},{"critere":"Quatre classements justes","points":8},{"critere":"Infox : fausse information diffusée volontairement","points":6}],"dureeMin":7,"corrige":"1. Une information est un fait **vérifié**, **sourcé**, **daté** et **signé** (publié par quelqu’un qui en assume la responsabilité).\n\n2.\n- a. **Rumeur** : aucune source identifiable.\n- b. **Opinion** : un jugement, qui n’a pas à être vrai.\n- c. **Information** : fait daté, sourcé (le compte rendu), signé.\n- d. **Publicité** : un message payé pour convaincre.\n\n3. Une **infox** est une **fausse information diffusée volontairement**."}$exo$::jsonb),
  ('2c182b11-baeb-5575-8a2c-21eebf445d1b'::uuid, 2, 'redaction', $exo${"titre":"La photo du requin","consigne":"Lis le document et réponds aux questions avec la méthode du cours.","enonce":"**Document — Publication sur un réseau social**\n\n> Compte « InfoChoc_24 » (aucune mention légale, créé il y a trois semaines) : « URGENT !!! Un requin géant nage dans les rues inondées de Marseille ce matin ! Les autorités vous cachent la vérité ! Partagez avant que ce soit censuré ! » — Photo d’un requin dans une rue inondée. 45 000 partages.\n\n1. Repère **deux indices** qui montrent que cette publication cherche à provoquer une émotion. Pourquoi une infox vise-t-elle l’émotion ?\n2. Applique les **cinq questions** du cours à ce document.\n3. Quel outil permettrait de vérifier si la photo est ancienne ou prise ailleurs ?\n4. « 45 000 partages, c’est forcément vrai », dit Enzo. Que lui réponds-tu ?","bareme":[{"critere":"Deux indices d’émotion et rôle de l’émotion dans le partage","points":5},{"critere":"Cinq questions appliquées au document","points":7},{"critere":"Recherche d’image inversée (et fact-checking)","points":4},{"critere":"Réfutation : nombre de partages n’est pas une preuve","points":4}],"dureeMin":12,"corrige":"1. Indices : « URGENT !!! », les points d’exclamation, « les autorités vous cachent la vérité », « partagez avant que ce soit censuré », le mot « choc » dans le nom du compte. Une infox vise l’**émotion** (peur, colère, indignation) parce que **l’émotion fait partager avant de réfléchir**.\n\n2.\n- **Qui** publie ? Un compte récent, **sans mentions légales** : non identifiable.\n- **Quand** ? « Ce matin » : mais la photo peut être **ancienne** (une vraie photo peut illustrer un faux propos).\n- **D’où** vient l’info ? Aucune **source première** (ni témoin nommé, ni autorité).\n- **D’autres médias sérieux** la reprennent-ils ? Il faut **recouper** : si aucun ne la reprend, c’est suspect.\n- **Pourquoi** me la montre-t-on ? Pour attirer l’attention, créer de la défiance envers les autorités, gagner des abonnés.\n\n3. La **recherche d’image inversée** ; on peut aussi consulter des sites de **fact-checking**.\n\n4. Le nombre de partages **n’est pas un gage de fiabilité** : une infox est faite pour circuler vite. Partager, même de bonne foi, c’est **diffuser** ; le premier réflexe utile est de **ne pas relayer**."}$exo$::jsonb),
  ('2c182b11-baeb-5575-8a2c-21eebf445d1b'::uuid, 3, 'redaction', $exo${"titre":"Sortir de sa bulle","consigne":"Lis le document, réponds aux questions puis rédige un paragraphe argumenté.","enonce":"**Document — Témoignage imaginé**\n\n> « Au début, je regardais quelques vidéos sur les régimes alimentaires. Maintenant, mon fil ne me montre plus que des vidéos qui disent que les médecins mentent. Tout le monde autour de moi pense pareil, alors ça doit être vrai. » — Clara, 15 ans\n\n1. Comment s’appelle le phénomène décrit par Clara ? Explique ses **trois étapes**.\n2. Pourquoi l’algorithme montre-t-il ces vidéos à Clara ?\n3. En quoi le travail d’un **journaliste** diffère-t-il de celui d’un compte qui relaie des vidéos ? Cite deux différences.\n4. **Paragraphe argumenté** (une dizaine de lignes) : quels moyens concrets Clara peut-elle utiliser pour exercer son esprit critique et sortir de sa bulle ? Pourquoi est-ce aussi une question de **responsabilité** envers les autres ?","bareme":[{"critere":"Bulle de filtre nommée, trois étapes expliquées","points":5},{"critere":"L’algorithme montre ce qui retient l’attention, ce qu’on a déjà aimé","points":3},{"critere":"Journaliste : enquête, recoupe deux sources, signe ; média responsable","points":4},{"critere":"Paragraphe : outils et démarche (cinq questions, sources variées, recoupement)","points":5},{"critere":"Paragraphe : responsabilité, ne pas relayer","points":3}],"dureeMin":18,"corrige":"1. C’est la **bulle de filtre** :\n- l’algorithme montre ce qui **retient l’attention** ;\n- donc ce qui **ressemble à ce qu’on a déjà aimé** ;\n- on finit par ne voir que ce qui **confirme ses idées**.\n\n2. Parce que Clara a regardé ce type de vidéos : l’algorithme lui propose ce qui la **retient**, pas ce qui est vrai. Le fait que « tout le monde pense pareil » autour d’elle est un effet de la bulle, pas une preuve.\n\n3. Le **journaliste** **enquête**, **recoupe au moins deux sources indépendantes** et **signe** ; son **média engage sa responsabilité**. Un compte anonyme qui relaie ne fait **rien de tout cela**.\n\n4. Paragraphe attendu :\n- **aller chercher volontairement d’autres sources** : c’est la seule façon de sortir de la bulle ;\n- se poser les **cinq questions** (qui publie, quand, d’où vient l’info, d’autres médias sérieux la reprennent-ils, pourquoi me la montre-t-on) ;\n- **comparer plusieurs médias**, consulter des sites de **fact-checking**, vérifier les **mentions légales** ;\n- se méfier d’un contenu qui provoque une émotion forte : c’est l’effet recherché ;\n- **responsabilité** : partager une infox, même de bonne foi, c’est la **diffuser** ; sur la santé, elle peut mettre d’autres personnes en danger ; le premier réflexe utile est de **ne pas relayer**."}$exo$::jsonb),
  ('75e32bd1-a0a6-553b-93d1-c36f4984ed96'::uuid, 1, 'redaction', $exo${"titre":"Les formes de l’engagement","consigne":"Réponds à chaque question en phrases complètes.","enonce":"1. Cite **quatre formes** d’engagement et donne un exemple pour chacune.\n2. Qu’est-ce qu’une **association loi 1901** ?\n3. Qu’est-ce que le **service civique** ? Dès quel âge est-il possible, et pour quelle durée ?\n4. Combien de personnes sont **bénévoles** en France, environ ?","bareme":[{"critere":"Quatre formes d’engagement avec exemples pertinents","points":8},{"critere":"Association loi 1901 : groupement à but non lucratif","points":4},{"critere":"Service civique : dès 16 ans, 6 à 12 mois, indemnisé, intérêt général","points":5},{"critere":"Environ 20 millions","points":3}],"dureeMin":7,"corrige":"1. Quatre formes parmi :\n- **associatif** : bénévolat dans une association sportive, culturelle, humanitaire ;\n- **syndical** : défendre des droits collectifs au travail ;\n- **politique** : parti, campagne, mandat ;\n- **citoyen** : pétition, manifestation, boycott, conseil de quartier ;\n- **scolaire** : délégué, éco-délégué, CVC, association sportive, journal du collège ;\n- **service civique**.\n\n2. Un **groupement à but non lucratif** : des personnes s’associent pour une cause sans chercher à faire des bénéfices.\n\n3. Une **mission d’intérêt général indemnisée**, possible **dès 16 ans**, de **6 à 12 mois**.\n\n4. Environ **20 millions** de personnes."}$exo$::jsonb),
  ('75e32bd1-a0a6-553b-93d1-c36f4984ed96'::uuid, 2, 'redaction', $exo${"titre":"Le projet de la classe de Nour","consigne":"Lis la situation et réponds aux questions en justifiant avec le cours.","enonce":"**Situation.** Nour, élève de 3e, est éco-déléguée. Avec sa classe, elle veut organiser une collecte pour l’épicerie solidaire de sa ville. Son camarade Tom trouve ça inutile : « L’État s’occupe déjà des pauvres avec la Sécu. Et puis moi, je n’ai jamais été remercié quand j’ai aidé. »\n\n1. Quelle forme d’engagement Nour exerce-t-elle au collège ? Cite deux autres formes d’engagement accessibles avant 18 ans.\n2. Explique le principe de la **solidarité organisée** et cite **trois dispositifs**. Depuis quand existe la Sécurité sociale ?\n3. Réponds à Tom : pourquoi la collecte reste-t-elle utile malgré la solidarité organisée ?\n4. Que répond le cours à la remarque de Tom sur les remerciements ?","bareme":[{"critere":"Engagement scolaire identifié et deux autres formes accessibles","points":4},{"critere":"Principe (selon ses moyens / ses besoins, un droit) et trois dispositifs, 1945","points":7},{"critere":"Solidarité de proximité : complète le système là où il n’atteint pas","points":5},{"critere":"On ne s’engage pas pour être remercié ; temps et régularité","points":4}],"dureeMin":11,"corrige":"1. Un engagement **scolaire** (éco-déléguée). Autres formes accessibles avant 18 ans : délégué, CVC, association sportive, journal du collège, **bénévolat associatif** (la forme la plus ouverte avant 18 ans), **service civique** dès 16 ans.\n\n2. Dans la solidarité organisée, chacun **cotise selon ses moyens** et **reçoit selon ses besoins**. Ce n’est pas de la charité : c’est un **droit**, financé par les **cotisations et l’impôt**. Dispositifs : la **Sécurité sociale** (maladie, famille, accidents du travail), l’**assurance chômage**, les **retraites**, les **aides au logement**. La Sécurité sociale est créée en **1945**.\n\n3. La **solidarité de proximité** (aide alimentaire, maraudes, aide aux devoirs, visites aux personnes isolées) **complète le système public là où il n’atteint pas**. La collecte pour l’épicerie solidaire en fait partie.\n\n4. **On ne s’engage pas pour être remercié.** L’engagement demande du **temps**, de la **régularité**, et d’accepter que les résultats soient **lents et partagés**."}$exo$::jsonb),
  ('75e32bd1-a0a6-553b-93d1-c36f4984ed96'::uuid, 3, 'redaction', $exo${"titre":"L’impôt, un acte de solidarité ?","consigne":"Lis le document, réponds aux questions puis rédige un paragraphe argumenté.","enonce":"**Document — Deux points de vue**\n\n> **Point de vue 1** : « La solidarité, c’est quand on donne de son plein gré. L’impôt et les cotisations, c’est une obligation, donc ça n’a rien à voir. »\n> **Point de vue 2** : « Payer l’impôt est un acte de solidarité, même quand on ne le vit pas ainsi : c’est ce qui paie l’école qu’on fréquente et l’hôpital qu’on espère ne pas fréquenter. »\n\n1. Distingue la **solidarité organisée** et la **solidarité de proximité** en donnant deux exemples de chacune.\n2. Pourquoi le cours affirme-t-il que la solidarité organisée n’est « pas de la charité » ?\n3. Donne deux exemples d’engagement à l’**échelle du monde** et précise ce que sont les objectifs de développement durable (nombre, date, horizon).\n4. **Paragraphe argumenté** (une dizaine de lignes) : lequel des deux points de vue te paraît le plus juste ? Argumente en t’appuyant sur le cours, et montre comment les deux formes de solidarité se complètent.","bareme":[{"critere":"Deux formes de solidarité distinguées avec deux exemples chacune","points":4},{"critere":"Un droit financé par cotisations et impôt, pas une charité","points":3},{"critere":"Engagement mondial et 17 ODD, 2015, horizon 2030","points":4},{"critere":"Paragraphe : position argumentée sur l’impôt (moyens/besoins, services payés)","points":5},{"critere":"Paragraphe : complémentarité des deux solidarités","points":4}],"dureeMin":18,"corrige":"1.\n- **Solidarité organisée** : Sécurité sociale (1945), assurance chômage, retraites, aides au logement.\n- **Solidarité de proximité** : aide alimentaire, maraudes, aide aux devoirs, visites aux personnes isolées, don du sang.\n\n2. Parce que chacun **cotise selon ses moyens** et **reçoit selon ses besoins** : ce qu’on reçoit est un **droit**, financé par les **cotisations et l’impôt**, et non un don qu’on accorde ou refuse selon sa bonne volonté.\n\n3. Exemples : les **ONG**, l’**aide au développement**, l’**action humanitaire**. Les **17 objectifs de développement durable** de l’ONU ont été fixés en **2015** pour l’horizon **2030** : un cap commun.\n\n4. Paragraphe attendu (position libre mais argumentée ; le cours soutient le point de vue 2) :\n- l’impôt est obligatoire, mais il réalise une solidarité : il **paie l’école, l’hôpital**, la justice pour tous, y compris pour ceux qui ne pourraient pas les payer ;\n- il suit le principe **selon ses moyens / selon ses besoins** : ceux qui ont plus contribuent pour ceux qui ont besoin ;\n- la solidarité volontaire garde sa place : la **solidarité de proximité** et le **bénévolat** (environ 20 millions de bénévoles) **complètent le système public là où il n’atteint pas** ;\n- conclusion : les deux formes ne s’opposent pas, elles se complètent."}$exo$::jsonb),
  ('9d3a66a7-4ab4-565b-8db6-6ea81cba30c6'::uuid, 1, 'redaction', $exo${"titre":"Le parcours de citoyenneté","consigne":"Réponds à chaque question en phrases complètes.","enonce":"1. En quelle année le **service militaire** a-t-il été suspendu ? Sur quoi repose depuis la défense ?\n2. Cite les **trois étapes** du parcours de citoyenneté et le moment de chacune.\n3. Pour quoi l’attestation de la **JDC** est-elle exigée ? Donne deux exemples.\n4. Cite les **quatre forces** armées françaises.","bareme":[{"critere":"1997 et armée professionnelle","points":4},{"critere":"Trois étapes avec leur moment","points":6},{"critere":"Bac, permis, concours publics (deux exemples)","points":4},{"critere":"Terre, Marine, Air et espace, Gendarmerie","points":6}],"dureeMin":7,"corrige":"1. En **1997**. Depuis, la défense repose sur une **armée professionnelle**, mais elle reste une affaire nationale.\n\n2.\n- L’**enseignement de défense**, au collège et au lycée ;\n- le **recensement** obligatoire, à **16 ans**, en mairie ou en ligne ;\n- la **Journée défense et citoyenneté**, entre **16 et 18 ans**.\n\n3. L’attestation de JDC est exigée pour s’inscrire au **baccalauréat**, au **permis de conduire** et aux **concours publics**.\n\n4. L’**armée de Terre**, la **Marine nationale**, l’**Armée de l’air et de l’espace**, la **Gendarmerie nationale**."}$exo$::jsonb),
  ('9d3a66a7-4ab4-565b-8db6-6ea81cba30c6'::uuid, 2, 'redaction', $exo${"titre":"L’hôpital attaqué","consigne":"Lis le document et réponds aux questions en justifiant avec le cours.","enonce":"**Document — Brève imaginée**\n\n> « Cette nuit, les ordinateurs de l’hôpital de Saint-Aubin ont été bloqués par un logiciel malveillant. Les rendez-vous ont été reportés et les urgences ont dû fonctionner sur papier. Aucun soldat, aucune arme : l’attaque est venue d’un pays étranger, par internet. »\n\n1. Quel domaine de la **défense élargie** est concerné par cette attaque ? Que protège-t-il ?\n2. Cite **deux autres domaines** de la défense élargie et ce qu’ils protègent.\n3. Explique la phrase du cours : « Une attaque contre un hôpital n’a plus besoin d’une armée : un logiciel suffit. »\n4. Cite **deux missions** des armées françaises.","bareme":[{"critere":"Cyberdéfense : réseaux, hôpitaux, administrations","points":5},{"critere":"Deux autres domaines et leur objet","points":6},{"critere":"Explication : menaces sans frontière, la défense se déplace","points":5},{"critere":"Deux missions des armées","points":4}],"dureeMin":10,"corrige":"1. La **cyberdéfense** : elle protège les **réseaux**, les **hôpitaux** et les **administrations** face aux attaques informatiques.\n\n2. Deux domaines parmi :\n- la **sécurité civile** : pompiers, secours, gestion des crises et catastrophes ;\n- la **sécurité économique** : l’approvisionnement en énergie, santé, alimentation ;\n- la **lutte antiterroriste** : la population face aux attaques.\n\n3. Aujourd’hui, on peut nuire gravement à un pays **sans armée** : un **logiciel** suffit à paralyser un hôpital. Les menaces passent par des **terrains sans frontière** (internet) ; c’est pourquoi la défense s’est **élargie** et déplacée vers ces terrains, au-delà des seuls militaires.\n\n4. Deux missions parmi : **protéger le territoire et la population**, **défendre les intérêts français**, **participer à des opérations internationales**, **secourir en cas de catastrophe**."}$exo$::jsonb),
  ('9d3a66a7-4ab4-565b-8db6-6ea81cba30c6'::uuid, 3, 'redaction', $exo${"titre":"La défense, affaire de tous ?","consigne":"Lis le document, réponds aux questions puis rédige un paragraphe argumenté.","enonce":"**Document — Remarque d’un élève**\n\n> « Depuis qu’il n’y a plus de service militaire, la défense ne concerne que les soldats de métier. Et puis la France est toute seule pour se défendre. »\n\n1. Réfute la première phrase en citant les étapes du **parcours de citoyenneté** et au moins **deux voies d’engagement** ouvertes aux civils.\n2. Réfute la seconde phrase : présente les **trois cadres collectifs** de la défense et le rôle de chacun. Quand l’OTAN a-t-elle été fondée ?\n3. Comment appelle-t-on les soldats des opérations de maintien de la paix de l’ONU ?\n4. **Paragraphe argumenté** (une dizaine de lignes) : « La défense nationale ne concerne que les militaires. » Montre que c’est faux en t’appuyant sur la défense élargie, le parcours de citoyenneté et les cadres collectifs.","bareme":[{"critere":"Parcours de citoyenneté et deux voies d’engagement (réserve, cadets, pompier volontaire…)","points":4},{"critere":"OTAN (1949, défense mutuelle), UE (politique commune), ONU (maintien de la paix)","points":5},{"critere":"Les casques bleus","points":2},{"critere":"Paragraphe : défense élargie (cyber, sécurité civile, économique) mobilisée","points":5},{"critere":"Paragraphe : rôle des citoyens et cadres collectifs, conclusion claire","points":4}],"dureeMin":18,"corrige":"1. Tout citoyen suit le **parcours de citoyenneté** : **enseignement de défense** au collège et au lycée, **recensement** à 16 ans, **Journée défense et citoyenneté** entre 16 et 18 ans. Des voies d’engagement sont ouvertes aux civils, avant et après 18 ans : la **réserve opérationnelle**, les **cadets de la défense**, les **préparations militaires**, le **service civique**, **sapeur-pompier volontaire**.\n\n2. La France agit dans des **cadres collectifs** :\n- l’**OTAN**, fondée en **1949** : une alliance militaire où **une attaque contre un membre engage les autres** ;\n- l’**Union européenne** : une **politique de sécurité et de défense commune** ;\n- l’**ONU** : les **opérations de maintien de la paix**.\n\n3. Les **casques bleus**.\n\n4. Paragraphe attendu :\n- depuis 1997, l’armée est professionnelle, mais la défense **reste une affaire nationale** ;\n- la défense s’est **élargie** : **cyberdéfense** (hôpitaux, administrations), **sécurité civile** (pompiers, secours), **sécurité économique** (énergie, santé, alimentation), **lutte antiterroriste** : ces domaines engagent des civils ;\n- chaque jeune suit le **parcours de citoyenneté** et peut s’engager (réserve, pompier volontaire…) ;\n- la France ne se défend pas seule : **OTAN, UE, ONU** ;\n- conclusion : la défense concerne toute la nation, pas seulement les militaires."}$exo$::jsonb),
  ('27ad789d-d7af-5ee8-8d01-1b402f779640'::uuid, 1, 'traduction', $exo${"titre":"Les formes de l’imparfait","consigne":"Écris chaque forme en entier, avec ses accents. Puis indique l’emploi de l’imparfait dans chaque phrase.","enonce":"**1. Conjugue** à l’imparfait :\n\na) *hablar* (yo)\nb) *comer* (nosotros)\nc) *vivir* (ellos)\nd) *ser* (tú)\ne) *ir* (nosotros)\nf) *ver* (ella)\ng) *jugar* (vosotros)\nh) *tener* (yo)\n\n**2. Indique l’emploi** de l’imparfait (description, habitude, action en cours interrompue ou politesse) :\n\na) *Hacía frío y la calle estaba desierta.*\nb) *Cuando era pequeña, iba a la playa cada verano.*\nc) *Quería pedirle un favor.*","bareme":[{"critere":"Les huit formes justes (hablaba, comíamos, vivían, eras, íbamos, veía, jugabais, tenía)","points":10},{"critere":"Accents écrits présents sur -ía, -íamos, -ían et sur íbamos","points":4},{"critere":"Les trois emplois bien identifiés (description, habitude, politesse)","points":6}],"dureeMin":7,"corrige":"**1.**\na) *hablaba* (verbe en -ar : -aba)\nb) *comíamos* (verbe en -er : -íamos, accent sur le í)\nc) *vivían* (verbe en -ir : -ían)\nd) *eras* (ser est irrégulier : era, eras, era…)\ne) *íbamos* (ir est irrégulier : iba, ibas… ; accent sur íbamos)\nf) *veía* (ver se forme sur l’ancien infinitif *veer*)\ng) *jugabais* (-ar, régulier)\nh) *tenía* (-er, régulier)\n\nSeuls *ser*, *ir* et *ver* sont irréguliers ; l’accent sur toutes les formes en -ía est obligatoire.\n\n**2.**\na) **Description** : le décor, sans début ni fin.\nb) **Habitude** passée (*cada verano*, *cuando era pequeña*).\nc) **Politesse** : « je voudrais vous demander un service »."}$exo$::jsonb),
  ('27ad789d-d7af-5ee8-8d01-1b402f779640'::uuid, 2, 'traduction', $exo${"titre":"Le village de l’abuelo","consigne":"Complète le souvenir de Mateo à l’imparfait, puis traduis et justifie.","enonce":"**Situation.** Mateo raconte à sa classe un souvenir d’enfance.\n\n> Cuando (1. ser) pequeño, (2. vivir) en un pueblo de Asturias. Todos los días, mi abuelo me (3. llevar) al colegio. Nosotros (4. ir) a pie y (5. ver) las montañas. Por la tarde, mi abuela (6. hacer) pan y yo la (7. ayudar).\n\n1. Écris les **sept verbes** à l’imparfait.\n2. **Traduis** en espagnol : *Quand j’étais petite, je jouais au football avec mes cousins.*\n3. Explique en une phrase pourquoi tout ce texte est à l’imparfait.","bareme":[{"critere":"Les sept formes justes : era, vivía, llevaba, íbamos, veíamos, hacía, ayudaba","points":10},{"critere":"Accents écrits justes (vivía, íbamos, veíamos, hacía)","points":3},{"critere":"Traduction juste : Cuando era pequeña, jugaba al fútbol con mis primos","points":4},{"critere":"Justification : habitudes passées et description, sans début ni fin","points":3}],"dureeMin":10,"corrige":"**1.**\n1) *era* (ser, irrégulier)\n2) *vivía*\n3) *llevaba*\n4) *íbamos* (ir, irrégulier, accent)\n5) *veíamos* (ver, sur *veer* ; sujet *nosotros*)\n6) *hacía*\n7) *ayudaba*\n\n**2.** *Cuando era pequeña, jugaba al fútbol con mis primos.* — *era* (ser irrégulier), *jugaba* (-ar), *pequeña* au féminin. On accepte *con mis primas*.\n\n**3.** Le texte ne raconte aucun événement unique : il décrit un **cadre** et des **habitudes passées** (*todos los días*, *por la tarde*), sans début ni fin. C’est exactement l’emploi de l’imparfait."}$exo$::jsonb),
  ('27ad789d-d7af-5ee8-8d01-1b402f779640'::uuid, 3, 'traduction', $exo${"titre":"La nuit de l’orage","consigne":"Choisis le bon temps, justifie tes choix, puis rédige un court souvenir en espagnol.","enonce":"**Document.** Récit de Sara, avec deux formes proposées à chaque fois.\n\n> Aquella noche (a. hacía / hizo) frío. Las calles (b. estaban / estuvieron) desiertas y (c. llovía / llovió). Yo (d. leía / leí) en mi habitación cuando, de repente, (e. sonaba / sonó) el teléfono. (f. Era / Fue) mi hermano.\n\n1. Recopie le récit avec la **bonne forme** à chaque fois.\n2. **Justifie** tes choix pour (c), (d) et (e) : quel temps pose le décor, lequel fait avancer le récit ?\n3. Explique la différence de sens entre *Ayer llovió* et *Ayer llovía*.\n4. **Production** (5 lignes environ) : raconte en espagnol un souvenir de tes vacances. Utilise au moins **trois imparfaits** avec trois emplois différents (description, habitude, action en cours interrompue).","bareme":[{"critere":"Les six choix justes : hacía, estaban, llovía, leía, sonó, Era","points":5},{"critere":"Justification : l’imparfait suspend le temps (décor), le passé simple fait avancer (événement)","points":5},{"critere":"Différence Ayer llovió / Ayer llovía expliquée (fait arrivé / contexte)","points":3},{"critere":"Production : trois imparfaits justes, trois emplois différents, accents corrects","points":7}],"dureeMin":16,"corrige":"**1.** *Aquella noche **hacía** frío. Las calles **estaban** desiertas y **llovía**. Yo **leía** en mi habitación cuando, de repente, **sonó** el teléfono. **Era** mi hermano.*\n\n**2.**\n- (c) *llovía* : la pluie est le **décor**, sans début ni fin → imparfait.\n- (d) *leía* : action **en cours**, qui va être interrompue → imparfait.\n- (e) *sonó* : l’**événement** qui interrompt et fait avancer le récit (*de repente*) → passé simple.\n(*Era mi hermano* : on identifie la personne, c’est une description.)\n\n**3.** *Ayer llovió* : il a plu, c’est un fait arrivé, achevé (événement). *Ayer llovía* : il pleuvait, c’était le contexte d’autre chose (décor).\n\n**4.** Exemple attendu : *Cuando era pequeño, iba a la playa con mis padres cada verano* (habitude). *El agua estaba fría y hacía mucho sol* (description). *Un día, nadaba tranquilamente cuando vi un delfín* (action en cours interrompue). Le correcteur vérifie trois imparfaits justes (formes, accents, irréguliers *ser/ir/ver*) et trois emplois distincts ; une phrase au passé simple pour l’interruption est bienvenue."}$exo$::jsonb),
  ('44aed1b9-e754-5f54-a097-9612a3bcd237'::uuid, 1, 'traduction', $exo${"titre":"Haber et le participe","consigne":"Conjugue au passé composé, puis indique le temps qu’appelle chaque marqueur.","enonce":"**1. Conjugue** au passé composé (*pretérito perfecto*) :\n\na) *comer* (yo)\nb) *hablar* (tú)\nc) *vivir* (ella)\nd) *viajar* (nosotros)\ne) *terminar* (vosotros)\nf) *llegar* (ellos)\n\n**2.** Pour chaque marqueur, indique s’il appelle le **passé composé** ou le **passé simple** :\n\na) *hoy* · b) *ayer* · c) *este año* · d) *en 1990* · e) *nunca* · f) *el año pasado*","bareme":[{"critere":"Formes de haber justes : he, has, ha, hemos, habéis, han","points":6},{"critere":"Participes justes et invariables : comido, hablado, vivido, viajado, terminado, llegado","points":6},{"critere":"Les six marqueurs bien classés","points":8}],"dureeMin":7,"corrige":"**1.**\na) *he comido*\nb) *has hablado*\nc) *ha vivido*\nd) *hemos viajado*\ne) *habéis terminado*\nf) *han llegado*\n\n*haber* au présent + participe passé, qui **ne s’accorde jamais** (pas de « hemos viajados »).\n\n**2.**\na) *hoy* → **passé composé** (période non achevée)\nb) *ayer* → **passé simple**\nc) *este año* → **passé composé** (contient *este*)\nd) *en 1990* → **passé simple** (une date)\ne) *nunca* → **passé composé** (bilan de vie)\nf) *el año pasado* → **passé simple**"}$exo$::jsonb),
  ('44aed1b9-e754-5f54-a097-9612a3bcd237'::uuid, 2, 'traduction', $exo${"titre":"Le message du soir de Pablo","consigne":"Complète le message au passé composé, corrige les fautes, puis traduis.","enonce":"**Situation.** Pablo écrit le soir à sa cousine Inés.\n\n> Hoy me (1. levantar) a las siete. Esta mañana (2. desayunar) con mi padre. Esta semana (3. trabajar) mucho y todavía no (4. terminar) mis deberes. ¿Tú (5. visitar) alguna vez Granada? Yo nunca (6. estar) allí.\n\n1. Écris les **six verbes** au passé composé.\n2. Inés répond : *« Yo he nunca estado en Granada, pero mis padres y yo hemos comidos allí una vez. »* Trouve et **corrige les deux fautes**, en expliquant la règle.\n3. **Traduis** : *Cette année, nous avons beaucoup voyagé.*","bareme":[{"critere":"Les six formes justes : me he levantado, he desayunado, he trabajado, he terminado, has visitado, he estado","points":9},{"critere":"Fautes corrigées : nunca he estado ; hemos comido","points":4},{"critere":"Règles énoncées : rien entre haber et le participe ; participe invariable","points":3},{"critere":"Traduction juste : Este año hemos viajado mucho","points":4}],"dureeMin":10,"corrige":"**1.**\n1) *me he levantado* (le pronom se place devant *haber*)\n2) *he desayunado*\n3) *he trabajado*\n4) *he terminado* (*todavía no* appelle le passé composé)\n5) *has visitado* (*alguna vez* : bilan)\n6) *he estado* (*nunca* : bilan de vie)\n\nTous les marqueurs (*hoy, esta mañana, esta semana, todavía no, alguna vez, nunca*) appellent le passé composé.\n\n**2.**\n- *He nunca estado* → **Nunca he estado** : rien ne s’intercale entre *haber* et le participe.\n- *hemos comidos* → **hemos comido** : le participe ne s’accorde jamais.\n\n**3.** *Este año hemos viajado mucho.* — *este año* est une période non achevée, donc passé composé."}$exo$::jsonb),
  ('44aed1b9-e754-5f54-a097-9612a3bcd237'::uuid, 3, 'traduction', $exo${"titre":"Le journal de bord de Nuria","consigne":"Choisis le bon temps et justifie, réponds à la question sur l’usage, puis rédige ton bilan.","enonce":"**Document.** Journal de Nuria, deux formes proposées.\n\n> Ayer (a. he ido / fui) al cine con Marta. Hoy (b. he estado / estuve) en casa todo el día. El año pasado (c. hemos viajado / viajamos) a Portugal, pero este año no (d. hemos salido / salimos) de España. En 2020 mi hermano (e. se ha roto / se rompió) la pierna ; esta mañana yo (f. me he roto / me rompí) el brazo, y todavía llevo la escayola.\n\n1. Recopie avec la **bonne forme** et **justifie** chaque choix par le marqueur ou le sens.\n2. Ton correspondant mexicain Diego écrit : *« Hoy comí tacos. »* Est-ce une faute ? Explique, et dis ce que tu écrirais, toi, en épreuve.\n3. **Production** (5 lignes environ) : fais le bilan de ta semaine et de ta vie. Utilise au moins **quatre verbes** au passé composé avec trois marqueurs différents (*esta semana, hoy, ya, todavía no, nunca, alguna vez*).","bareme":[{"critere":"Les six choix justes : fui, he estado, viajamos, hemos salido, se rompió, me he roto","points":6},{"critere":"Justifications : marqueur ayer/date → passé simple ; este/hoy ou effets qui durent → passé composé","points":4},{"critere":"Variation géographique expliquée : usage courant en Amérique latine, norme castillane en épreuve","points":3},{"critere":"Production : quatre passés composés justes, trois marqueurs, participe invariable","points":7}],"dureeMin":16,"corrige":"**1.**\na) **fui** — *ayer* coupe le fait du présent → passé simple.\nb) **he estado** — *hoy*, période non achevée → passé composé.\nc) **viajamos** — *el año pasado* → passé simple.\nd) **hemos salido** — *este año*, période non achevée → passé composé.\ne) **se rompió** — une date, *en 2020* → passé simple.\nf) **me he roto** — *esta mañana* (période non achevée) et les **effets durent** (elle a encore le plâtre) → passé composé.\n\n**2.** Ce n’est **pas une faute** au Mexique : en Amérique latine (et dans le nord-ouest de l’Espagne), le passé simple absorbe largement le passé composé. Mais la norme scolaire française suit l’usage **castillan** : en épreuve, on écrit *Hoy he comido tacos*.\n\n**3.** Exemple : *Esta semana he trabajado mucho. Hoy he comido paella con mis amigos. Ya he terminado mis deberes, pero todavía no he preparado el examen. Nunca he estado en México.* Le correcteur vérifie *haber* bien conjugué, participes invariables, rien entre l’auxiliaire et le participe, et des marqueurs cohérents avec le passé composé."}$exo$::jsonb),
  ('466ee2ac-b480-51b9-a980-8d1522a0cf55'::uuid, 1, 'traduction', $exo${"titre":"Réguliers et prétérits forts","consigne":"Conjugue au passé simple, avec les accents, puis réponds à la question.","enonce":"**1. Conjugue** au passé simple (*pretérito indefinido*) :\n\na) *hablar* (yo)\nb) *comer* (él)\nc) *vivir* (ellos)\nd) *tener* (yo)\ne) *hacer* (ella)\nf) *decir* (ellos)\ng) *ir* (nosotros)\nh) *dormir* (él)\n\n**2.** Quelle différence de sens y a-t-il entre *hablo* et *habló* ? Et entre *Fui a Madrid* et *Fui profesor* ?","bareme":[{"critere":"Formes régulières justes avec accent : hablé, comió, vivieron","points":6},{"critere":"Formes irrégulières justes : tuve, hizo, dijeron, fuimos, durmió","points":9},{"critere":"Explications : accent distinctif (présent / passé simple) ; ser et ir ont la même forme","points":5}],"dureeMin":8,"corrige":"**1.**\na) *hablé*\nb) *comió*\nc) *vivieron*\nd) *tuve* (prétérit fort, radical *tuv-*, **sans accent**)\ne) *hizo* (radical *hic-*, mais *hizo* à la 3e personne)\nf) *dijeron* (radical en -j : pas de i, jamais « dijieron »)\ng) *fuimos* (même forme pour *ser* et *ir*)\nh) *durmió* (affaiblissement o → u à la 3e personne)\n\n**2.** *hablo* est un **présent** (je parle) ; *habló* est un **passé simple** (il/elle parla, a parlé) : l’accent change le temps. *Fui a Madrid* = je suis allé à Madrid (*ir*) ; *Fui profesor* = j’ai été professeur (*ser*) : seul le contexte tranche."}$exo$::jsonb),
  ('466ee2ac-b480-51b9-a980-8d1522a0cf55'::uuid, 2, 'traduction', $exo${"titre":"Une semaine à Madrid","consigne":"Mets le récit de Lucía au passé simple, puis réponds aux questions.","enonce":"**Situation.** Lucía raconte ses dernières vacances.\n\n> El verano pasado, mis padres y yo (1. ir) a Madrid. (2. Estar : nosotros) allí una semana. El primer día, (3. visitar : nosotros) el Museo del Prado. Mi padre (4. hacer) muchas fotos y mi madre (5. comprar) un libro. Yo (6. pedir) un helado. Por la noche, mis padres (7. dormir) muy poco.\n\n1. Écris les **sept verbes** au passé simple.\n2. Relève les **deux marqueurs** qui appellent le passé simple dans ce texte.\n3. Pourquoi écrit-on *pedí* (yo) mais *pidió* (él) ? Donne aussi la 3e personne du pluriel de *pedir*.","bareme":[{"critere":"Les sept formes justes : fuimos, Estuvimos, visitamos, hizo, compró, pedí, durmieron","points":11},{"critere":"Accents justes (compró, pedí) et aucun accent sur les formes fortes","points":3},{"critere":"Marqueurs relevés : el verano pasado, el primer día (ou por la noche)","points":2},{"critere":"Affaiblissement expliqué (3es personnes seulement) et pidieron donné","points":4}],"dureeMin":11,"corrige":"**1.**\n1) *fuimos* (ir)\n2) *Estuvimos* (radical fort *estuv-*)\n3) *visitamos*\n4) *hizo*\n5) *compró* (accent obligatoire à la 3e personne)\n6) *pedí* (1re personne : pas de changement de voyelle)\n7) *durmieron* (affaiblissement o → u)\n\n**2.** *El verano pasado* et *el primer día* (ou *por la noche*) : des moments passés et coupés du présent.\n\n**3.** Les verbes en -ir du type *pedir* ne changent de voyelle (e → i) **qu’aux deux troisièmes personnes** : *pedí, pediste, pidió, pedimos, pedisteis, **pidieron***."}$exo$::jsonb),
  ('466ee2ac-b480-51b9-a980-8d1522a0cf55'::uuid, 3, 'traduction', $exo${"titre":"La visite surprise","consigne":"Choisis entre imparfait et passé simple, conjugue, justifie, puis traduis.","enonce":"**Document.** Récit d’Álvaro, verbes à l’infinitif.\n\n> Era de noche y (1. llover). De repente, (2. sonar) el timbre. Yo (3. abrir) la puerta : allí estaban mis tíos. (4. Traer : ellos) una tarta y me (5. decir) : « ¡Feliz cumpleaños! ». Mi tía (6. pedir) un café y mi tío (7. sentir) frío. Aquella noche, mis tíos (8. dormir) en casa.\n\n1. Conjugue les **huit verbes** au temps qui convient (imparfait ou passé simple).\n2. **Justifie** le temps choisi pour (1) et pour (2).\n3. Explique pourquoi on écrit *dijeron* et non « dijieron ».\n4. **Traduis** : *Hier, j’ai eu un problème : je n’ai pas pu venir.*","bareme":[{"critere":"Formes justes : llovía, sonó, abrí, Trajeron, dijeron, pidió, sintió, durmieron","points":8},{"critere":"Justification : imparfait = décor ; passé simple = événement qui fait avancer (de repente)","points":4},{"critere":"Règle du radical en -j expliquée (la 3e personne du pluriel perd son i)","points":3},{"critere":"Traduction juste : Ayer tuve un problema: no pude venir","points":5}],"dureeMin":17,"corrige":"**1.**\n1) *llovía* (imparfait : décor)\n2) *sonó* (passé simple, accent)\n3) *abrí*\n4) *Trajeron* (fort, radical *traj-*, sans i)\n5) *dijeron* (fort, *dij-*, sans i)\n6) *pidió* (affaiblissement e → i)\n7) *sintió* (affaiblissement e → i)\n8) *durmieron* (affaiblissement o → u)\n\n**2.** (1) *llovía* : la pluie pose le **décor** de la scène, sans début ni fin. (2) *sonó* : c’est l’**événement** qui surgit (*de repente*) et fait avancer le récit.\n\n**3.** Après un radical en **-j** (*dij-, traj-, conduj-*), la 3e personne du pluriel perd son i : *dijeron, trajeron, condujeron*.\n\n**4.** *Ayer tuve un problema: no pude venir.* — *ayer* appelle le passé simple ; *tener* → *tuve*, *poder* → *pude*, formes fortes **sans accent**."}$exo$::jsonb),
  ('57880a7f-aafb-52a1-ab76-834c334c865d'::uuid, 1, 'traduction', $exo${"titre":"Futur et conditionnel","consigne":"Conjugue au futur puis au conditionnel, en écrivant les accents.","enonce":"**1. Conjugue** au futur simple :\n\na) *hablar* (yo)\nb) *comer* (nosotros)\nc) *vivir* (ellos)\nd) *tener* (tú)\ne) *hacer* (ella)\nf) *decir* (yo)\ng) *poder* (vosotros)\nh) *salir* (ellos)\n\n**2. Conjugue** au conditionnel : *tener* (yo) · *poder* (ella) · *hacer* (nosotros).","bareme":[{"critere":"Formes régulières justes : hablaré, comeremos, vivirán","points":5},{"critere":"Radicaux irréguliers justes : tendrás, hará, diré, podréis, saldrán","points":8},{"critere":"Accents justes (partout sauf nosotros)","points":2},{"critere":"Conditionnels justes sur le même radical : tendría, podría, haríamos","points":5}],"dureeMin":7,"corrige":"**1.**\na) *hablaré*\nb) *comeremos* (nosotros : pas d’accent)\nc) *vivirán*\nd) *tendrás* (un d remplace la voyelle : *tendr-*)\ne) *hará* (radical raccourci *har-*)\nf) *diré* (radical raccourci *dir-*)\ng) *podréis* (le e de l’infinitif tombe : *podr-*)\nh) *saldrán* (*saldr-*)\n\nLe futur se construit sur l’infinitif entier + *-é, -ás, -á, -emos, -éis, -án*.\n\n**2.** Même radical que le futur + terminaisons *-ía* : *tendría*, *podría*, *haríamos*."}$exo$::jsonb),
  ('57880a7f-aafb-52a1-ab76-834c334c865d'::uuid, 2, 'traduction', $exo${"titre":"L’été de Carmen","consigne":"Complète les projets de Carmen au futur, corrige la phrase piège, puis explique.","enonce":"**Situation.** Carmen écrit à sa correspondante française.\n\n> El verano que viene (1. ir : yo) a México. (2. Tener : yo) mucho tiempo libre. Mis amigos (3. venir) conmigo y (4. hacer : nosotros) muchas excursiones. (5. Poner : yo) fotos en internet y te (6. decir : yo) todo.\n\n1. Écris les **six verbes** au futur simple.\n2. Carmen ajoute : *« Cuando llegaré a México, te llamaré. »* Corrige la faute et énonce la règle.\n3. Explique le sens de *Serán las tres* et de *Voy a estudiar*.","bareme":[{"critere":"Les six futurs justes : iré, Tendré, vendrán, haremos, Pondré, diré","points":9},{"critere":"Correction : Cuando llegue a México, te llamaré","points":3},{"critere":"Règle : après cuando à valeur de futur, subjonctif présent","points":3},{"critere":"Sens : probabilité sur le présent ; intention ou imminence avec ir a","points":5}],"dureeMin":11,"corrige":"**1.**\n1) *iré* (régulier : infinitif *ir* + *-é*)\n2) *Tendré* (*tendr-*)\n3) *vendrán* (*vendr-*)\n4) *haremos* (*har-*, sans accent à nosotros)\n5) *Pondré* (*pondr-*)\n6) *diré* (*dir-*)\n\n**2.** *Cuando **llegue** a México, te llamaré.* Dans une subordonnée de temps à valeur de futur, l’espagnol met le **subjonctif présent**, jamais le futur (le français dit « quand j’arriverai »).\n\n**3.** *Serán las tres* : futur de **probabilité**, une supposition sur le **présent** (« il doit être trois heures »). *Voy a estudiar* : *ir a* + infinitif, l’**intention** ou l’imminence (« je vais étudier »), très fréquent à l’oral."}$exo$::jsonb),
  ('57880a7f-aafb-52a1-ab76-834c334c865d'::uuid, 3, 'traduction', $exo${"titre":"Ma vie dans dix ans","consigne":"Traduis, corrige le message, puis rédige ta projection dans l’avenir.","enonce":"**1. Traduis** en espagnol :\n\na) Demain, il pleuvra.\nb) Quand tu arriveras, appelle-moi.\nc) Il doit être trois heures (supposition).\nd) Pourrais-tu m’aider ?\ne) Nous le saurons demain.\n\n**2. Corrige** les trois fautes du message de Hugo :\n\n> *Cuando llegarás, te diceré la verdad. Mañana poderé salir.*\n\n**3. Production** (5 lignes environ) : comment sera ta vie dans dix ans ? Utilise au moins **quatre futurs irréguliers** différents et **une** phrase avec *cuando* + subjonctif présent.","bareme":[{"critere":"Traductions justes : lloverá, Cuando llegues llámame, Serán las tres, ¿Podrías ayudarme?, Lo sabremos","points":7},{"critere":"Les trois fautes corrigées : llegues, diré, podré","points":4},{"critere":"Production : quatre futurs irréguliers justes avec accents","points":6},{"critere":"Production : cuando suivi du subjonctif présent, sans futur","points":3}],"dureeMin":18,"corrige":"**1.**\na) *Mañana lloverá.*\nb) *Cuando llegues, llámame.* (subjonctif présent après *cuando*)\nc) *Serán las tres.* (futur de probabilité)\nd) *¿Podrías ayudarme?* (conditionnel, même radical *podr-*)\ne) *Lo sabremos mañana.* (*sabr-*, pas d’accent à nosotros)\n\n**2.** *Cuando **llegues**, te **diré** la verdad. Mañana **podré** salir.* — pas de futur après *cuando* ; *decir* → *dir-* ; *poder* → *podr-*.\n\n**3.** Exemple : *Dentro de diez años, tendré veinticinco años. Viviré en Madrid y seré médico. Podré viajar mucho y haré muchos amigos. Cuando tenga tiempo, volveré a ver a mi familia.* Le correcteur vérifie au moins quatre irréguliers justes (*tendré, podré, haré, saldré, vendré, pondré, sabré, querré, diré…*), les accents, et l’absence de futur après *cuando*."}$exo$::jsonb),
  ('17ff294f-2c5c-50d8-acf6-59ab06a050ab'::uuid, 1, 'traduction', $exo${"titre":"Les bons mots pour interroger","consigne":"Recopie chaque question en entier, avec ses deux signes et ses accents. Puis traduis les phrases demandées.","enonce":"**1. Complète** avec le mot interrogatif qui convient, sans oublier les signes ¿ et ? :\n\na) … te llamas? (comment)\nb) … vives? (où)\nc) … años tienes? (combien)\nd) … es tu color favorito? (on choisit dans un ensemble)\ne) … no vienes a la fiesta? (pourquoi)\n\n**2. Traduis** en espagnol :\n\na) Je ne sais pas où il est.\nb) Pourquoi pleures-tu ? — Parce que je suis triste.","bareme":[{"critere":"Les cinq mots interrogatifs justes (cómo, dónde, cuántos, cuál, por qué), avec leur accent","points":10},{"critere":"Les signes ¿ et ? présents à l'ouverture et à la fermeture de chaque question","points":4},{"critere":"Traductions justes : accent gardé dans dónde sans signes, por qué / porque distingués","points":6}],"dureeMin":7,"corrige":"**1.**\na) **¿Cómo** te llamas?\nb) **¿Dónde** vives?\nc) **¿Cuántos** años tienes? (*años* est masculin pluriel, donc *cuántos*)\nd) **¿Cuál** es tu color favorito? (un choix dans un ensemble de couleurs)\ne) **¿Por qué** no vienes a la fiesta? (en deux mots, avec accent)\n\nChaque question s'ouvre par **¿** et se ferme par **?** ; tous les mots interrogatifs portent un accent écrit.\n\n**2.**\na) *No sé dónde está.* — interrogation indirecte : pas de signes ¿ ?, mais l'accent de **dónde** reste.\nb) *¿Por qué lloras? — Porque estoy triste.* — **por qué** (deux mots, accent) pour la question, **porque** (un mot, sans accent) pour la réponse."}$exo$::jsonb),
  ('17ff294f-2c5c-50d8-acf6-59ab06a050ab'::uuid, 2, 'traduction', $exo${"titre":"L'interview du nouvel élève","consigne":"Retrouve les questions à partir des réponses, puis rapporte-les au style indirect.","enonce":"**Situation.** Lucía, journaliste du journal du collège, interroge Diego, un nouvel élève. Voici les réponses de Diego ; les questions ont été effacées.\n\n> — Me llamo Diego.\n> — Tengo catorce años.\n> — Vivo en Sevilla, cerca del río.\n> — Porque mi padre trabaja aquí ahora.\n> — Entre el fútbol y el baloncesto, prefiero el fútbol.\n\n1. Écris les **cinq questions** de Lucía (tutoiement), avec les signes et les accents.\n2. Lucía raconte l'interview à son professeur. Transforme les questions 1 et 3 au style indirect en commençant par *Le pregunté…*\n3. Explique en une phrase pourquoi *dónde* garde son accent dans ta réponse à la question 2.","bareme":[{"critere":"Cinq questions correctes : cómo, cuántos, dónde, por qué, cuál","points":10},{"critere":"Signes ¿ ? et accents des interrogatifs justes partout","points":4},{"critere":"Interrogation indirecte juste : accent gardé, signes supprimés","points":4},{"critere":"Explication : l'accent distingue l'interrogatif du relatif, même sans signes","points":2}],"dureeMin":10,"corrige":"**1.**\n- *¿Cómo te llamas?*\n- *¿Cuántos años tienes?*\n- *¿Dónde vives?*\n- *¿Por qué vives aquí?* (ou *¿Por qué has venido a Sevilla?*) — question en **por qué**, la réponse est en **porque**.\n- *¿Cuál prefieres, el fútbol o el baloncesto?* — **cuál** car on choisit entre deux éléments. (*¿Qué deporte prefieres?* est accepté : devant un nom on emploie *qué*.)\n\n**2.**\n- *Le pregunté cómo se llamaba* (ou *cómo se llama*).\n- *Le pregunté dónde vivía* (ou *dónde vive*).\nPas de signes ¿ ?, mais **cómo** et **dónde** gardent leur accent. On accepte le présent ou l'imparfait, seule la forme interrogative est évaluée.\n\n**3.** *Dónde* reste un mot **interrogatif**, même sans point d'interrogation : l'accent le distingue du relatif *donde* (*la casa donde vivo*)."}$exo$::jsonb),
  ('17ff294f-2c5c-50d8-acf6-59ab06a050ab'::uuid, 3, 'traduction', $exo${"titre":"Le message à la correspondante","consigne":"Corrige les erreurs en les justifiant, puis rédige toi-même un court message en espagnol.","enonce":"**Document.** Tom a écrit ce message à sa correspondante de Salamanca. Il contient **cinq erreurs** liées aux questions.\n\n> Hola Marta, Como estás? Yo estoy bien. Cuál día llegas a París? Porque no me escribes más? No sé cuando vienes. Quieres visitar el Louvre?\n\n1. Recopie le message corrigé.\n2. Pour **trois** des erreurs, explique la règle en une phrase.\n3. Rédige un message de 4 questions à Marta (40 mots environ) sur ses loisirs. Tu dois employer : une question avec **qué** devant un nom, une avec **cuál**, une avec **por qué**, et une **interrogation indirecte** (*Me pregunto…* ou *No sé…*).","bareme":[{"critere":"Message corrigé : signes ¿ ?, cómo, qué día, por qué, cuándo","points":6},{"critere":"Trois règles expliquées avec justesse","points":5},{"critere":"Production : qué + nom, cuál, por qué et interrogation indirecte employés correctement","points":7},{"critere":"Message compréhensible, orthographe et accents soignés","points":2}],"dureeMin":15,"corrige":"**1.** *Hola Marta, **¿Cómo** estás? Yo estoy bien. **¿Qué día** llegas a París? **¿Por qué** no me escribes más? No sé **cuándo** vienes. **¿**Quieres visitar el Louvre?*\n\n**2.** Règles attendues (trois parmi) :\n- Toute question s'ouvre par **¿** et se ferme par **?** (oubli dans toutes les questions).\n- Les mots interrogatifs portent **tous un accent** : *cómo*, *cuándo*.\n- Devant un **nom**, on emploie **qué** et non *cuál* : *¿Qué día…?*\n- La question se pose avec **por qué** (deux mots, accent) ; *porque* sert à répondre.\n- Dans l'interrogation indirecte, l'accent **reste** même sans signes : *No sé cuándo vienes*.\n\n**3.** Exemple de production :\n*Hola Marta: ¿Qué deporte practicas? ¿Cuál es tu película favorita? ¿Por qué te gusta tanto la música? Me pregunto qué haces los domingos. ¡Escríbeme pronto!*\nOn vérifie : *qué* + nom, *cuál* + verbe *ser*, *por qué* en deux mots, interrogation indirecte sans signes mais avec accent (*qué*)."}$exo$::jsonb),
  ('e5cdbed2-3256-5d1c-9354-c3f93e9894cc'::uuid, 1, 'traduction', $exo${"titre":"Tout mettre à la forme négative","consigne":"Transforme chaque phrase à la forme négative, puis réécris-la de la seconde façon possible quand on te le demande.","enonce":"**1. Mets à la forme négative** en employant le mot négatif qui convient :\n\na) Veo algo en la calle.\nb) Alguien llama a la puerta.\nc) Siempre como carne.\nd) Tengo algún problema.\ne) Hablo español.\n\n**2.** Pour les phrases b) et c), écris la **deuxième** construction possible (mot négatif avant ou après le verbe).\n\n**3.** Traduis : *Moi non plus, je n'aime pas le thé.*","bareme":[{"critere":"Cinq négations justes (nada, nadie, nunca, ningún, no) avec la double négation quand le mot suit le verbe","points":10},{"critere":"Deuxième construction juste pour b) et c) : le no disparaît quand le mot négatif passe devant","points":6},{"critere":"Traduction avec tampoco juste","points":4}],"dureeMin":7,"corrige":"**1.**\na) *No veo nada en la calle.* (double négation obligatoire)\nb) *No llama nadie a la puerta.* ou *Nadie llama a la puerta.*\nc) *No como carne nunca.* ou *Nunca como carne.*\nd) *No tengo ningún problema.* (*ninguno* s'apocope en **ningún** devant un masculin singulier)\ne) *No hablo español.* (*no* juste devant le verbe)\n\n**2.**\nb) *Nadie llama a la puerta.* / *No llama nadie a la puerta.*\nc) *Nunca como carne.* / *No como carne nunca.*\nQuand le mot négatif passe **devant** le verbe, le *no* disparaît ; s'il est **après**, le *no* est obligatoire.\n\n**3.** *A mí tampoco me gusta el té.* ou *Tampoco me gusta el té.*"}$exo$::jsonb),
  ('e5cdbed2-3256-5d1c-9354-c3f93e9894cc'::uuid, 2, 'traduction', $exo${"titre":"Sino, pero et ne… plus","consigne":"Complète, puis traduis les phrases en respectant les règles de la négation espagnole.","enonce":"**1. Complète** avec *sino*, *sino que* ou *pero* :\n\na) No es francés … español.\nb) No es rico … es feliz.\nc) No canta … grita.\nd) No quiero té … café.\n\n**2. Situation.** Álvaro a changé depuis le début de l'année. Traduis ce que dit sa sœur :\n\na) Il ne joue plus au football.\nb) Il n'a pas encore fini ses devoirs.\nc) Il ne voit personne et ne dit rien.\nd) Il n'aime ni la musique ni le cinéma.","bareme":[{"critere":"Sino, sino que et pero justement choisis dans les quatre phrases","points":8},{"critere":"Ya no et todavía no (ou aún no) employés correctement","points":6},{"critere":"Double négation (no… nadie, no… nada) et ni… ni justes","points":6}],"dureeMin":10,"corrige":"**1.**\na) *No es francés **sino** español.* — on rectifie après une négation.\nb) *No es rico **pero** es feliz.* — on oppose sans rectifier.\nc) *No canta **sino que** grita.* — rectification devant un verbe conjugué.\nd) *No quiero té **sino** café.* — rectification.\n\n**2.**\na) *Ya no juega al fútbol.* (*ya no* = ne… plus)\nb) *Todavía no ha terminado sus deberes.* (ou *Aún no…* ; accepté aussi *Todavía no termina…*)\nc) *No ve a nadie y no dice nada.* — double négation : le *no* est obligatoire devant le verbe quand *nadie* et *nada* suivent ; *a* devant *nadie* COD de personne.\nd) *No le gusta ni la música ni el cine.* (ou *No le gustan ni la música ni el cine*)"}$exo$::jsonb),
  ('e5cdbed2-3256-5d1c-9354-c3f93e9894cc'::uuid, 3, 'traduction', $exo${"titre":"Le journal d'un jour sans","consigne":"Traduis le texte en espagnol, puis justifie trois de tes choix grammaticaux.","enonce":"**Texte à traduire.**\n\n> Aujourd'hui, rien ne va. Personne ne m'a appelé et je n'ai reçu aucun message. Je ne sors plus le soir et je ne vais jamais au cinéma. Mon frère non plus. Ce n'est pas de la tristesse, c'est de la fatigue. Je n'ai pas encore mangé et je ne veux rien.\n\n1. Traduis le texte (tu peux employer le présent pour *ne m'a appelé* et *n'ai reçu* : *nadie me llama*, *no recibo*).\n2. Pour **trois** phrases de ta traduction, explique la règle appliquée : double négation, place du mot négatif, apocope de *ninguno*, *sino*, *tampoco*…\n3. Réécris la phrase *Je ne vais jamais au cinéma* des **deux** façons possibles.","bareme":[{"critere":"Nada, nadie, ningún, ya no, nunca, tampoco, todavía no employés correctement","points":8},{"critere":"Double négation respectée partout où le mot négatif suit le verbe","points":4},{"critere":"No es… sino… pour la rectification","points":2},{"critere":"Trois justifications exactes","points":4},{"critere":"Les deux constructions de nunca justes","points":2}],"dureeMin":15,"corrige":"**1.** Traduction attendue :\n*Hoy nada va bien (No va bien nada). Nadie me ha llamado (Nadie me llama) y no he recibido ningún mensaje. Ya no salgo por la noche y no voy nunca al cine (nunca voy al cine). Mi hermano tampoco. No es tristeza sino cansancio. Todavía no he comido y no quiero nada.*\n\n**2.** Justifications possibles :\n- *Nadie me ha llamado* : le mot négatif est **avant** le verbe, donc pas de *no*.\n- *No quiero nada* : *nada* suit le verbe, donc le *no* est **obligatoire** (les deux négations se renforcent).\n- *ningún mensaje* : *ninguno* s'apocope devant un masculin singulier.\n- *No es tristeza sino cansancio* : **sino** rectifie après une négation.\n- *Mi hermano tampoco* : *tampoco* = non plus.\n- *Ya no* = ne… plus ; *todavía no* = pas encore.\n\n**3.** *No voy nunca al cine.* / *Nunca voy al cine.*"}$exo$::jsonb),
  ('fa15f657-c8ef-54e2-971d-28eaa348ee00'::uuid, 1, 'traduction', $exo${"titre":"La virgule qui change tout","consigne":"Réponds en une ou deux phrases, puis traduis.","enonce":"**1.** Compare ces deux phrases :\n\n> A. Los alumnos que estudian aprueban.\n> B. Los alumnos, que estudian, aprueban.\n\na) Dans quelle phrase **tous** les élèves réussissent-ils ?\nb) Comment s'appellent les deux types de relatives ?\n\n**2. Traduis :**\na) la maison dans laquelle je vis\nb) le garçon dont je parle\nc) Il est arrivé en retard, ce qui m'a dérangé.","bareme":[{"critere":"Différence de sens expliquée : B = tous les élèves, A = seulement ceux qui étudient","points":6},{"critere":"Types nommés : déterminative sans virgules, explicative entre virgules","points":4},{"critere":"Traductions justes : préposition devant le relatif et lo que pour une idée entière","points":10}],"dureeMin":7,"corrige":"**1.**\na) Dans la phrase **B** : la relative entre virgules ajoute une information sur **tous** les élèves (ils étudient tous, et ils réussissent tous). Dans A, seuls **ceux qui étudient** réussissent.\nb) A contient une relative **déterminative** (elle restreint l'antécédent, sans virgules) ; B une relative **explicative** (elle ajoute une information, entre virgules).\n\n**2.**\na) *la casa en la que vivo* — la préposition se place **devant** le relatif, jamais à la fin (« la casa que vivo en » est faux).\nb) *el chico del que hablo* (de + el que).\nc) *Llegó tarde, lo que me molestó.* — une idée entière se reprend par le neutre **lo que**, jamais par *el que*."}$exo$::jsonb),
  ('fa15f657-c8ef-54e2-971d-28eaa348ee00'::uuid, 2, 'traduction', $exo${"titre":"Indicatif ou subjonctif dans la relative","consigne":"Conjugue le verbe entre parenthèses au présent de l'indicatif ou du subjonctif, et justifie chaque choix.","enonce":"**Situation.** Nerea cherche un appartement et un colocataire à Valencia.\n\na) Busco un piso que (tener) terraza.\nb) Vivo en un piso que (tener) terraza.\nc) No conozco a nadie que (saber) cocinar paella.\nd) Tengo un amigo que (hablar) valenciano.\ne) Necesito un compañero que (poder) pagar la mitad.\n\n1. Conjugue les cinq verbes.\n2. Pour chaque phrase, écris si l'antécédent est **connu**, **indéfini** ou **nié**.\n3. Traduis : *Je cherche la secrétaire qui parle anglais* (tu la connais).","bareme":[{"critere":"Cinq formes justes : tenga, tiene, sepa, habla, pueda","points":10},{"critere":"Nature de l'antécédent correctement identifiée pour chaque phrase","points":6},{"critere":"Traduction à l'indicatif avec la préposition a : Busco a la secretaria que habla inglés","points":4}],"dureeMin":10,"corrige":"**1 et 2.**\na) *Busco un piso que **tenga** terraza.* — antécédent **indéfini** (n'importe quel appartement, encore à trouver) : subjonctif.\nb) *Vivo en un piso que **tiene** terraza.* — antécédent **connu**, réel : indicatif.\nc) *No conozco a nadie que **sepa** cocinar paella.* — antécédent **nié** : subjonctif.\nd) *Tengo un amigo que **habla** valenciano.* — antécédent **connu** : indicatif.\ne) *Necesito un compañero que **pueda** pagar la mitad.* — antécédent **indéfini** : subjonctif (*poder* diphtongue : *pueda*).\n\n**3.** *Busco a la secretaria que habla inglés.* — la secrétaire est connue, donc **indicatif** ; *a* devant un COD de personne déterminée. À comparer avec *Busco una secretaria que hable inglés* (n'importe laquelle)."}$exo$::jsonb),
  ('fa15f657-c8ef-54e2-971d-28eaa348ee00'::uuid, 3, 'traduction', $exo${"titre":"L'annonce du club de théâtre","consigne":"Corrige les phrases fautives en justifiant, puis rédige une petite annonce en espagnol.","enonce":"**1. Chaque phrase contient une erreur.** Corrige-la et explique la règle.\n\na) El chico que hablo de es mi primo.\nb) Buscamos actores que tienen experiencia.\nc) No vino a clase, el que me sorprendió.\n\n**2. Production (50 mots environ).** Le club de théâtre du collège de Toledo cherche de nouveaux membres. Rédige l'annonce, qui commence par *Buscamos chicos y chicas que…*. Tu dois employer :\n- deux relatives au **subjonctif** (antécédent indéfini) ;\n- une relative avec **préposition** (*en el que*, *con el que*…) ;\n- une relative **explicative** entre virgules ;\n- **lo que**.","bareme":[{"critere":"Trois corrections justes : del que hablo, que tengan, lo que","points":6},{"critere":"Trois règles expliquées (préposition, mode, idée entière)","points":3},{"critere":"Deux relatives au subjonctif correctes dans l'annonce","points":4},{"critere":"Relative avec préposition, relative explicative et lo que correctement employées","points":5},{"critere":"Annonce claire, compréhensible, accords soignés","points":2}],"dureeMin":16,"corrige":"**1.**\na) *El chico **del que** hablo es mi primo.* — la préposition ne se rejette jamais à la fin : elle précède le relatif (*de + el que = del que*).\nb) *Buscamos actores que **tengan** experiencia.* — les acteurs sont encore à trouver (antécédent indéfini) : subjonctif.\nc) *No vino a clase, **lo que** me sorprendió.* — une phrase entière se reprend par le neutre *lo que*.\n\n**2.** Exemple d'annonce :\n*Buscamos chicos y chicas que quieran hacer teatro y que no tengan miedo al público. Los ensayos, que son los miércoles, tienen lugar en la sala en la que trabajamos desde hace diez años. Lo que buscamos es gente motivada. ¡Te esperamos!*\nOn vérifie : *quieran*, *tengan* (subjonctif, antécédent indéfini) ; *en la que* (préposition devant le relatif) ; *, que son los miércoles,* (explicative entre virgules) ; *lo que* (idée) ."}$exo$::jsonb),
  ('04abd754-2bcd-5280-9de8-ff69f1334b60'::uuid, 1, 'traduction', $exo${"titre":"Indicatif ou subjonctif après que","consigne":"Conjugue le verbe entre parenthèses au présent de l'indicatif ou du subjonctif.","enonce":"**1. Complète :**\n\na) Creo que Pablo (venir) mañana.\nb) No creo que Pablo (venir) mañana.\nc) Quiero que tú (estudiar) más.\nd) Veo que (estar, él) cansado.\ne) Es necesario que vosotros (llegar) a las ocho.\nf) Ojalá (hacer) buen tiempo el sábado.\n\n**2. Traduis** en faisant attention au sujet :\na) Je veux venir.\nb) Je veux que tu viennes.","bareme":[{"critere":"Six formes justes : viene, venga, estudies, está, lleguéis, haga","points":12},{"critere":"Infinitif quand le sujet est le même, que + subjonctif quand il change","points":8}],"dureeMin":7,"corrige":"**1.**\na) *Creo que Pablo **viene** mañana.* — opinion affirmée : indicatif.\nb) *No creo que Pablo **venga** mañana.* — certitude niée : subjonctif.\nc) *Quiero que **estudies** más.* — volonté : subjonctif.\nd) *Veo que **está** cansado.* — perception : indicatif.\ne) *Es necesario que **lleguéis** a las ocho.* — jugement impersonnel : subjonctif (*llegar* : g devient **gu** devant e).\nf) *Ojalá **haga** buen tiempo el sábado.* — souhait : *ojalá* est toujours suivi du subjonctif.\n\n**2.**\na) *Quiero venir.* — même sujet : infinitif, sans *que*.\nb) *Quiero que vengas.* — sujets différents : *que* + subjonctif."}$exo$::jsonb),
  ('04abd754-2bcd-5280-9de8-ff69f1334b60'::uuid, 2, 'traduction', $exo${"titre":"Les conseils de la mère de Carmen","consigne":"Transforme les phrases comme demandé et justifie le mode choisi.","enonce":"**Situation.** Carmen part en voyage scolaire à Granada. Sa mère lui parle.\n\n> «Estudias mucho, lo sé. Pero tienes que descansar. Llevas el móvil. Me llamas cada noche. Estás contenta.»\n\n1. Réécris ces phrases en commençant par le verbe indiqué :\na) *Quiero que…* (tienes que descansar → descansar)\nb) *Espero que…* (me llamas cada noche)\nc) *Me alegro de que…* (estás contenta)\nd) *Es importante que…* (llevas el móvil)\n\n2. Transforme à la forme négative : *Creo que el viaje es caro.* Quel changement de mode se produit ?\n\n3. Complète la phrase de Carmen : *Sé que mi madre…* (preocuparse). Justifie le mode.","bareme":[{"critere":"Quatre subjonctifs justes : descanses, me llames, estés, lleves","points":10},{"critere":"Bascule juste : No creo que el viaje sea caro, avec explication","points":6},{"critere":"Sé que mi madre se preocupa, indicatif justifié par la certitude","points":4}],"dureeMin":10,"corrige":"**1.**\na) *Quiero que descanses.* — volonté : subjonctif.\nb) *Espero que me llames cada noche.* — souhait : subjonctif ; le *que* ne se supprime jamais.\nc) *Me alegro de que estés contenta.* — sentiment : subjonctif (*estar* : *esté, estés*…).\nd) *Es importante que lleves el móvil.* — jugement impersonnel : subjonctif.\n\n**2.** *No creo que el viaje **sea** caro.* — l'opinion affirmée (*creo que* + indicatif) devient une certitude **niée** : on passe au **subjonctif**. Le verbe principal n'a pas changé, sa polarité si.\n\n**3.** *Sé que mi madre **se preocupa**.* — *saber* exprime une **certitude** : indicatif."}$exo$::jsonb),
  ('04abd754-2bcd-5280-9de8-ff69f1334b60'::uuid, 3, 'traduction', $exo${"titre":"Ce que voulait le professeur","consigne":"Traduis, transpose au passé et justifie tes choix de mode.","enonce":"**1. Traduis** ces phrases d'un professeur à sa classe :\n\na) Je veux que vous lisiez ce livre.\nb) Je pense que c'est un bon roman.\nc) Je ne pense pas qu'il soit difficile.\nd) Il faut que vous travailliez en groupe.\n\n**2. Transpose au passé** les phrases a) et d) : *Quería que…*, *Era necesario que…* (imparfait du subjonctif en *-ra*).\n\n**3.** En deux ou trois phrases, explique pourquoi b) et c) n'emploient pas le même mode alors que le verbe principal est le même.\n\n**4.** Écris une phrase de ton choix avec *ojalá* et une autre avec *dudo que*.","bareme":[{"critere":"Quatre traductions justes : leáis, es, sea, trabajéis","points":8},{"critere":"Concordance au passé juste : leyerais, trabajarais (ou -seis)","points":4},{"critere":"Explication de la bascule opinion affirmée / niée","points":4},{"critere":"Phrases avec ojalá et dudo que au subjonctif correct","points":4}],"dureeMin":16,"corrige":"**1.**\na) *Quiero que leáis este libro.* — volonté, sujets différents : subjonctif.\nb) *Creo (pienso) que es una buena novela.* — opinion affirmée : indicatif.\nc) *No creo que sea difícil.* — opinion niée : subjonctif.\nd) *Es necesario que trabajéis en grupo.* (ou *Hace falta que…*) — jugement impersonnel : subjonctif.\n\n**2.**\na) *Quería que leyerais (leyeseis) este libro.*\nd) *Era necesario que trabajarais (trabajaseis) en grupo.*\nQuand le verbe principal passe au passé, le subjonctif présent devient **imparfait du subjonctif** ; les formes en *-ra* et *-se* sont équivalentes.\n\n**3.** Dans b), le professeur **affirme** une opinion : indicatif. Dans c), il **nie** cette opinion : ce n'est plus une certitude, on passe au **subjonctif**. Le verbe *creer* est le même, seule la négation change le mode.\n\n**4.** Exemples : *Ojalá apruebe el examen.* / *Dudo que venga esta tarde.* — *ojalá* et le doute exigent le subjonctif."}$exo$::jsonb),
  ('e53f3417-d8f0-5545-b138-6bed8c732bab'::uuid, 1, 'traduction', $exo${"titre":"Le bon article, le bon pluriel","consigne":"Écris chaque nom avec son article défini au singulier, puis au pluriel.","enonce":"**1.** Écris l'article défini (*el* ou *la*) devant chaque nom, puis le groupe au **pluriel** :\n\na) … problema\nb) … canción\nc) … ciudad\nd) … leche\ne) … color\nf) … lápiz\ng) … examen\nh) … lunes\n\n**2.** Donne le féminin de : *el profesor*, *el francés*, *el estudiante*.","bareme":[{"critere":"Genre juste pour les huit noms, notamment el problema, la leche, el color","points":8},{"critere":"Pluriels justes : -s, -es, z en -ces, invariable, accent de exámenes","points":8},{"critere":"Trois féminins justes : la profesora, la francesa, la estudiante","points":4}],"dureeMin":7,"corrige":"**1.**\na) *el problema* → *los problemas* (masculin : -ma d'origine grecque)\nb) *la canción* → *las canciones* (féminin en -ción ; l'accent disparaît au pluriel)\nc) *la ciudad* → *las ciudades* (féminin en -dad ; consonne : -es)\nd) *la leche* → *las leches* (féminin en espagnol, masculin en français)\ne) *el color* → *los colores* (masculin en espagnol)\nf) *el lápiz* → *los lápices* (z devient **-ces**)\ng) *el examen* → *los exámenes* (l'accent écrit apparaît pour garder la prononciation)\nh) *el lunes* → *los lunes* (-s non accentué : invariable)\n\n**2.** *la profesora* (on ajoute -a), *la francesa* (on ajoute -a, l'accent disparaît), *la estudiante* (invariable : seul l'article change)."}$exo$::jsonb),
  ('e53f3417-d8f0-5545-b138-6bed8c732bab'::uuid, 2, 'traduction', $exo${"titre":"Les fautes de genre de Hugo","consigne":"Corrige le texte, puis classe les noms corrigés et explique ce qui a trompé Hugo.","enonce":"**Document.** Hugo a écrit ce texte sur son voyage. Il contient **six erreurs** de genre ou de pluriel.\n\n> En el viaje a Madrid tuve una problema: me dolía el nariz. Compré el leche y la sal en una tienda. Visité dos ciudads y tres museos. Me gustó mucho la color del cielo. Los examenes empiezan el lunes.\n\n1. Recopie le texte corrigé.\n2. Explique pourquoi Hugo s'est trompé sur *problema*, *nariz* et *color*.\n3. Donne une règle de pluriel pour *ciudad* et une pour *examen*.","bareme":[{"critere":"Six corrections justes : un problema, la nariz, la leche, ciudades, el color, exámenes","points":10},{"critere":"Explication : calque du genre français, -ma grec masculin","points":6},{"critere":"Règles de pluriel justes : consonne + -es, accent qui suit la prononciation","points":4}],"dureeMin":10,"corrige":"**1.** *En el viaje a Madrid tuve **un** problema: me dolía **la** nariz. Compré **la** leche y la sal en una tienda. Visité dos **ciudades** y tres museos. Me gustó mucho **el** color del cielo. Los **exámenes** empiezan el lunes.*\n\n**2.**\n- *problema* finit par -a mais est **masculin** : c'est un nom en **-ma d'origine grecque** (*el problema, el tema, el idioma*).\n- *nariz* et *leche* sont **féminins** en espagnol alors que « nez » et « lait » sont masculins en français : Hugo a recopié le genre français.\n- *color* est **masculin** en espagnol, « couleur » féminin en français. Ces noms s'apprennent avec leur article.\n\n**3.**\n- *ciudad* finit par une consonne : on ajoute **-es** → *ciudades*.\n- *examen* → *exámenes* : l'accent écrit **apparaît** au pluriel pour garder l'accent tonique sur la même syllabe (l'accent suit la prononciation)."}$exo$::jsonb),
  ('e53f3417-d8f0-5545-b138-6bed8c732bab'::uuid, 3, 'traduction', $exo${"titre":"La fête du village","consigne":"Traduis le texte, puis justifie le genre et le pluriel de cinq noms de ta traduction.","enonce":"**Texte à traduire.**\n\n> Dans mon village, la tradition est ancienne. Chaque été, les jeunes chantent des chansons sur la place. Les artistes arrivent le vendredi avec leurs crayons pour dessiner les arbres et les ponts. Le voyage coûte peu et le climat est doux. C'est une coutume que j'adore.\n\nVocabulaire : *village* = pueblo, *place* = plaza, *dessiner* = dibujar, *doux* = suave, *coûter peu* = costar poco.\n\n1. Traduis le texte.\n2. Choisis **cinq** noms de ta traduction et justifie leur genre ou leur pluriel par une règle du cours (terminaison, piège du francophone, pluriel en -ces, nom invariable…).","bareme":[{"critere":"Genres justes : la tradición, la canción, el árbol, el puente, el viaje, el clima, la costumbre","points":8},{"critere":"Pluriels justes : canciones, lápices, árboles, puentes ; los artistas","points":5},{"critere":"Cinq justifications exactes","points":5},{"critere":"Traduction compréhensible et accords soignés","points":2}],"dureeMin":16,"corrige":"**1.** *En mi pueblo, la tradición es antigua. Cada verano, los jóvenes cantan canciones en la plaza. Los artistas llegan el viernes con sus lápices para dibujar los árboles y los puentes. El viaje cuesta poco y el clima es suave. Es una costumbre que me encanta (que adoro).*\n\n**2.** Justifications possibles :\n- *la tradición* : féminin en **-ción**.\n- *las canciones* : féminin en -ción ; au pluriel on ajoute **-es** et l'accent écrit **disparaît**.\n- *los artistas* : nom **invariable en genre**, seul l'article change (*el / la artista*).\n- *los lápices* : **z** devient **-ces** au pluriel.\n- *el árbol, el puente, el viaje* : **masculins** en espagnol, féminins en français (pièges du francophone) ; *el viaje* : terminaison **-aje** masculine.\n- *el clima* : **-ma** d'origine grecque, masculin.\n- *la costumbre* : féminin en **-umbre**.\n- *los jóvenes* : consonne → -es, l'accent apparaît."}$exo$::jsonb),
  ('061b2b11-3cf4-5b03-b713-4530b5e40449'::uuid, 1, 'traduction', $exo${"titre":"El, al, del ou lo ?","consigne":"Complète avec l'article qui convient et justifie en quelques mots.","enonce":"**1. Complète** avec *el, la, un, una, al, del* ou *lo* :\n\na) … agua está fría.\nb) Voy … cine con mis amigos.\nc) Es la casa … profesor.\nd) Vi … águila en la montaña.\ne) … importante es participar.\nf) Vivo en … avenida principal.\n\n**2. Traduis :** a) Je suis professeur. b) un autre jour.","bareme":[{"critere":"Six articles justes : el, al, del, un, lo, la","points":12},{"critere":"Deux traductions justes : Soy profesor, otro día","points":8}],"dureeMin":7,"corrige":"**1.**\na) ***El** agua está fría.* — nom féminin commençant par un **a- tonique** : *el*, mais l'adjectif reste au féminin (*fría*).\nb) *Voy **al** cine.* — contraction *a + el = al*.\nc) *La casa **del** profesor.* — contraction *de + el = del*.\nd) *Vi **un** águila.* — a- tonique : *un*, pas *una*.\ne) ***Lo** importante es participar.* — neutre *lo* + adjectif = une qualité abstraite.\nf) *Vivo en **la** avenida principal.* — l'accent tonique de *avenida* ne tombe pas sur le *a* initial : article normal.\n\n**2.**\na) *Soy profesor.* — pas d'article devant une profession en attribut.\nb) *otro día* — jamais d'article indéfini devant *otro*."}$exo$::jsonb),
  ('061b2b11-3cf4-5b03-b713-4530b5e40449'::uuid, 2, 'traduction', $exo${"titre":"Le carnet de voyage de Salomé","consigne":"Traduis les phrases, puis explique trois de tes choix d'article.","enonce":"**Situation.** Salomé tient un carnet pendant son séjour en Andalousie. Traduis ses notes :\n\na) Nous allons au marché avec quelques amis.\nb) L'eau de la fontaine est froide.\nc) Les salles de classe du collège sont grandes.\nd) Ma correspondante est espagnole ; son père est médecin.\ne) Je ne comprends pas ce que dit le guide.\nf) Le plus difficile, c'est la chaleur.\n\nExplique ensuite **trois** de tes choix d'article.","bareme":[{"critere":"Al, unos amigos et del justement employés","points":5},{"critere":"El agua fría et las aulas : règle du a tonique et pluriel","points":5},{"critere":"Absence d'article devant la profession et la nationalité en attribut","points":3},{"critere":"Lo que et lo + adjectif justes","points":4},{"critere":"Trois explications exactes","points":3}],"dureeMin":10,"corrige":"a) *Vamos al mercado con unos amigos.* — *a + el = al* ; *unos* = quelques.\nb) *El agua de la fuente está fría.* — *agua* est féminin mais commence par un a- tonique : **el** ; l'adjectif reste féminin.\nc) *Las aulas del colegio son grandes.* — au **pluriel**, l'article féminin revient : *las aulas*.\nd) *Mi correspondiente (amiga por correspondencia) es española; su padre es médico.* — pas d'article devant une nationalité ou une profession en attribut.\ne) *No entiendo lo que dice el guía.* — *lo que* = « ce que ».\nf) *Lo más difícil es el calor.* — *lo* + adjectif = qualité abstraite ; *el calor* est masculin.\n\nExplications attendues : trois parmi les justifications ci-dessus (contraction, a tonique, pluriel *las*, absence d'article en attribut, neutre *lo*)."}$exo$::jsonb),
  ('061b2b11-3cf4-5b03-b713-4530b5e40449'::uuid, 3, 'traduction', $exo${"titre":"Tu ne sais pas comme je suis fatigué","consigne":"Corrige les erreurs en justifiant, puis rédige un court texte en espagnol.","enonce":"**1. Chaque phrase contient une erreur d'article.** Corrige-la et explique la règle.\n\na) La agua del mar está fría.\nb) Voy a el colegio en bici.\nc) Mi hermano es un médico.\nd) Quiero un otro helado.\ne) No sabes el cansado que estoy.\n\n**2. Production (40 à 50 mots).** Raconte la fin d'une journée de randonnée difficile. Tu dois employer : *el* devant un nom féminin à a- tonique (*el agua*, *el hambre*…), une contraction, **lo** + adjectif, **lo** + adjectif + **que** (intensité) et **otro**.","bareme":[{"critere":"Cinq corrections justes","points":6},{"critere":"Cinq règles expliquées","points":5},{"critere":"Production : a tonique, contraction et otro sans article justes","points":4},{"critere":"Production : lo + adjectif et lo + adjectif + que justes","points":4},{"critere":"Texte compréhensible et accords soignés","points":1}],"dureeMin":16,"corrige":"**1.**\na) ***El** agua del mar está fría.* — féminin singulier à a- tonique : *el*, l'adjectif reste féminin.\nb) *Voy **al** colegio.* — *a + el* se contracte toujours en *al* (sauf devant un nom propre).\nc) *Mi hermano es médico.* — pas d'article devant une profession en attribut (sauf si elle est qualifiée : *un médico excelente*).\nd) *Quiero **otro** helado.* — jamais d'article indéfini devant *otro*.\ne) *No sabes **lo** cansado que estoy.* — *lo* + adjectif + *que* exprime l'intensité (le neutre, jamais *el*).\n\n**2.** Exemple :\n*Después de ocho horas de marcha, llegamos al refugio. Tenía un hambre terrible y bebí toda el agua de mi botella. Lo peor fue la bajada. ¡No sabes lo cansada que estaba! Mañana haremos otra ruta, más corta.*\nOn vérifie : *un hambre, el agua* (a tonique), *al* (contraction), *lo peor* (lo + adjectif), *lo cansada que* (intensité), *otra* sans article."}$exo$::jsonb),
  ('9cb347d4-135a-5229-9cc8-941ee5e25e61'::uuid, 1, 'traduction', $exo${"titre":"Ici, là, là-bas","consigne":"Complète avec le démonstratif qui convient selon la distance indiquée.","enonce":"**1. Complète :**\n\na) … libro (près de moi) es muy interesante.\nb) ¿Me das … revista (près de toi)?\nc) … montañas (loin de nous deux) son los Pirineos.\nd) … chicos (près de moi) son mis primos.\ne) … casa (loin de nous deux) es de mi abuela.\n\n**2.** Traduis : *Qu'est-ce que c'est ?* et *Ce n'est pas vrai.*\n\n**3.** Quelle est la particularité du masculin singulier de la troisième série ?","bareme":[{"critere":"Cinq démonstratifs justes, accordés en genre et en nombre","points":12},{"critere":"Neutres justes : ¿Qué es esto? et Eso no es verdad","points":5},{"critere":"Aquel sans -o","points":3}],"dureeMin":7,"corrige":"**1.**\na) ***Este** libro es muy interesante.* (près de moi, masculin singulier)\nb) *¿Me das **esa** revista?* (près de toi, féminin singulier)\nc) ***Aquellas** montañas son los Pirineos.* (loin, féminin pluriel)\nd) ***Estos** chicos son mis primos.* (près de moi, masculin pluriel)\ne) ***Aquella** casa es de mi abuela.* (loin, féminin singulier)\n\n**2.** *¿Qué es esto?* (chose non identifiée, proche : neutre **esto**) — *Eso no es verdad.* (reprend ce qui vient d'être dit : **eso**). Les neutres sont invariables, sans accent, jamais suivis d'un nom.\n\n**3.** Le masculin singulier est **aquel**, sans -o (et non « aquelo »)."}$exo$::jsonb),
  ('9cb347d4-135a-5229-9cc8-941ee5e25e61'::uuid, 2, 'traduction', $exo${"titre":"Au marché de Valencia","consigne":"Complète le dialogue avec les démonstratifs et les adverbes de lieu, puis réponds aux questions.","enonce":"**Situation.** Iker fait les courses au marché avec sa grand-mère. La marchande est derrière son étal, Iker tient un panier.\n\n> **Iker:** Quiero … naranjas que tiene usted ahí, al lado de su mano.\n> **Vendedora:** ¿… ? Muy bien. ¿Y … melón que tiene en su cesta? ¿Es de aquí?\n> **Iker:** Sí, … melón lo compré aquí el sábado.\n> **Abuela:** ¿Y … tomates, al fondo del mercado, allí?\n> **Vendedora:** … son de otra tienda. ¡… no es asunto mío!\n\n1. Complète les six trous.\n2. Pour trois trous, explique la distance (près de qui ?).\n3. Associe chaque série à son adverbe : *aquí, ahí, allí*.","bareme":[{"critere":"Six démonstratifs justes et accordés","points":10},{"critere":"Trois distances expliquées correctement","points":5},{"critere":"Adverbes associés : este-aquí, ese-ahí, aquel-allí ; neutre eso pour une idée","points":5}],"dureeMin":10,"corrige":"**1.**\n> Iker: Quiero **esas** naranjas que tiene usted ahí. (près de la marchande = de l'interlocuteur)\n> Vendedora: ¿**Estas**? (près d'elle-même, qui parle) Muy bien. ¿Y **ese** melón que tiene en su cesta? (près d'Iker, son interlocuteur)\n> Iker: Sí, **este** melón… (près de lui, qui parle)\n> Abuela: ¿Y **aquellos** tomates, al fondo del mercado, allí? (loin des deux)\n> Vendedora: **Aquellos** son de otra tienda. ¡**Eso** no es asunto mío! (neutre : reprend une idée)\n\n**2.** Trois explications parmi celles données entre parenthèses : la distance se mesure par rapport à **celui qui parle** (*este*), à **celui qui écoute** (*ese*), ou **loin des deux** (*aquel*).\n\n**3.** *este* → **aquí** ; *ese* → **ahí** ; *aquel* → **allí**."}$exo$::jsonb),
  ('9cb347d4-135a-5229-9cc8-941ee5e25e61'::uuid, 3, 'traduction', $exo${"titre":"Les souvenirs du grand-père","consigne":"Traduis le texte, puis justifie le choix de chaque démonstratif.","enonce":"**Texte à traduire.** Le grand-père de Lola lui montre une vieille photo.\n\n> — Tu vois cette maison, là-bas, au fond de la photo ? C'était notre maison. À cette époque-là, nous n'avions pas d'argent. Ces années-là furent difficiles, mais tout cela m'a rendu fort.\n> — Et ce garçon, à côté de toi sur la photo ?\n> — Celui-là, c'est mon frère. Ce livre que tu tiens, c'est lui qui l'a écrit.\n\n1. Traduis le dialogue.\n2. Justifie chaque démonstratif employé (distance dans l'espace, dans le temps ou dans le discours ; neutre).\n3. Pourquoi écrit-on aujourd'hui *este* et *aquel* sans accent, même quand ils sont pronoms ?","bareme":[{"critere":"Aquella casa, en aquel entonces, aquellos años justes : distance temporelle","points":6},{"critere":"Neutre aquello ou eso pour reprendre une idée (tout cela)","points":3},{"critere":"Ese chico et ese libro justes : près de l'interlocuteur","points":4},{"critere":"Justifications exactes pour chaque démonstratif","points":5},{"critere":"Règle de la RAE de 2010 sur l'accent des pronoms","points":2}],"dureeMin":15,"corrige":"**1.** Traduction attendue :\n> — ¿Ves aquella casa, allí, al fondo de la foto? Era nuestra casa. En aquel entonces, no teníamos dinero. Aquellos años fueron difíciles, pero todo aquello me hizo fuerte.\n> — ¿Y ese chico, a tu lado en la foto?\n> — Ese es mi hermano. Ese libro que tienes, lo escribió él.\n\n**2.**\n- *aquella casa* : loin des deux, au fond de la photo (espace).\n- *en aquel entonces*, *aquellos años* : un passé lointain (temps) : c'est le domaine de *aquel*.\n- *todo aquello* : neutre qui reprend un ensemble de souvenirs lointains (*todo eso* accepté).\n- *ese chico* : Lola en parle, désigné sur la photo proche d'elle (accepté aussi *este* si le grand-père tient la photo) ; *ese* reprend aussi ce dont on parle.\n- *ese libro que tienes* : près de l'interlocuteur (Lola le tient).\n- *Ese es mi hermano* : pronom démonstratif.\n\n**3.** Depuis la réforme de la **RAE en 2010**, le pronom démonstratif ne prend **plus d'accent écrit** : on écrit *este*, *ese*, *aquel* comme l'adjectif. L'ancienne graphie *éste* n'est plus la norme."}$exo$::jsonb),
  ('77a6d50e-0c79-5f14-b633-4d1e55a71db7'::uuid, 1, 'traduction', $exo${"titre":"Accorder et placer l'adjectif","consigne":"Accorde l'adjectif entre parenthèses et place-le correctement.","enonce":"**1. Accorde** l'adjectif :\n\na) una chica (alto)\nb) unos chicos (inteligente)\nc) una profesora (español)\nd) una mujer (trabajador)\ne) un chico y una chica (simpático)\n\n**2. Place** l'adjectif avant ou après le nom et accorde-le :\na) un coche (rojo)\nb) un día (bueno)\nc) la lengua (francés)\n\n**3.** Quelle est la place de l'adjectif par défaut ?","bareme":[{"critere":"Cinq accords justes : alta, inteligentes, española, trabajadora, simpáticos","points":10},{"critere":"Trois places justes : coche rojo, buen día, lengua francesa","points":6},{"critere":"Règle : après le nom par défaut","points":4}],"dureeMin":7,"corrige":"**1.**\na) *una chica **alta*** — adjectif en -o : quatre formes.\nb) *unos chicos **inteligentes*** — adjectif en -e : invariable en genre, pluriel en -s.\nc) *una profesora **española*** — adjectif de nationalité : il forme un féminin.\nd) *una mujer **trabajadora*** — adjectif en -or : il forme un féminin.\ne) *un chico y una chica **simpáticos*** — plusieurs noms dont un masculin : masculin pluriel.\n\n**2.**\na) *un coche rojo* — la couleur reste toujours après le nom.\nb) *un buen día* — appréciation, avant le nom, avec apocope (*bueno* → *buen*). *Un día bueno* est possible mais moins courant.\nc) *la lengua francesa* — nationalité : toujours après.\n\n**3.** Par défaut, l'adjectif se place **après** le nom : il classe, il distingue objectivement."}$exo$::jsonb),
  ('77a6d50e-0c79-5f14-b633-4d1e55a71db7'::uuid, 2, 'traduction', $exo${"titre":"Grand homme ou homme grand ?","consigne":"Traduis chaque expression en choisissant la bonne place de l'adjectif, puis explique la différence de sens.","enonce":"**Situation.** Pour un exposé, Maëlys traduit des phrases sur des personnages.\n\n**1. Traduis :**\na) Cervantes est un grand homme.\nb) Mon oncle est un homme grand (de grande taille).\nc) Ce pauvre homme a perdu son chien.\nd) C'est un homme pauvre : il n'a pas d'argent.\ne) Lucas est un vieil ami (je le connais depuis longtemps).\nf) J'ai lu différents livres sur ce sujet.\n\n**2.** Explique en deux phrases pourquoi la place de l'adjectif compte autant en espagnol.","bareme":[{"critere":"Gran hombre / hombre grande et pobre hombre / hombre pobre justes","points":8},{"critere":"Viejo amigo et diferentes libros justes","points":6},{"critere":"Explication : devant = regard du locuteur, derrière = classement ; le sens change","points":6}],"dureeMin":10,"corrige":"**1.**\na) *Cervantes es un gran hombre.* — devant : important (avec apocope *gran*).\nb) *Mi tío es un hombre grande.* — derrière : de grande taille.\nc) *Este pobre hombre ha perdido a su perro.* — devant : à plaindre.\nd) *Es un hombre pobre: no tiene dinero.* — derrière : sans argent.\ne) *Lucas es un viejo amigo.* — devant : de longue date (*un amigo viejo* = un ami âgé).\nf) *He leído diferentes libros sobre este tema.* — devant : plusieurs (*libros diferentes* = dissemblables).\n\n**2.** Placé **après** le nom, l'adjectif classe objectivement ; placé **avant**, il exprime le regard de celui qui parle. Pour certains adjectifs (*gran, pobre, viejo, diferente, cierto*), la place **change le sens** du mot : ce n'est pas une nuance de style mais une information."}$exo$::jsonb),
  ('77a6d50e-0c79-5f14-b633-4d1e55a71db7'::uuid, 3, 'traduction', $exo${"titre":"Le portrait d'une idole","consigne":"Corrige les erreurs en justifiant, puis rédige un portrait en espagnol.","enonce":"**1. Chaque phrase contient une erreur.** Corrige-la et explique.\n\na) Tengo una amiga inglés.\nb) Mis padres y mi hermana son simpáticas.\nc) Es un grande actor.\nd) Tiene los ojos azul.\n\n**2. Production (50 à 60 mots).** Fais le portrait d'une personne que tu admires (réelle ou inventée). Tu dois employer :\n- au moins quatre adjectifs accordés, dont un de nationalité ;\n- un adjectif **avant** le nom qui exprime une appréciation ;\n- un adjectif dont le **sens change** selon la place (*gran, pobre, viejo…*), en expliquant son sens entre parenthèses en français ;\n- une apocope (*buen, gran, mal*).","bareme":[{"critere":"Quatre corrections justes : inglesa, simpáticos, gran actor, azules","points":6},{"critere":"Quatre explications exactes","points":4},{"critere":"Production : adjectifs accordés, dont un de nationalité","points":4},{"critere":"Production : adjectif antéposé, adjectif à sens changeant et apocope corrects","points":5},{"critere":"Portrait cohérent et compréhensible","points":1}],"dureeMin":16,"corrige":"**1.**\na) *una amiga **inglesa*** — les adjectifs de nationalité forment un féminin.\nb) *son **simpáticos*** — plusieurs noms dont l'un est masculin : accord au masculin pluriel.\nc) *un **gran** actor* — *grande* s'apocope en *gran* devant un nom singulier ; devant, il signifie « important ».\nd) *los ojos **azules*** — l'adjectif s'accorde en nombre (consonne → -es) ; la couleur reste après le nom.\n\n**2.** Exemple :\n*Mi abuela Carmen es una mujer argentina, alegre y muy trabajadora. Es una gran persona (importante, admirable) y una buena cocinera. Tiene los ojos verdes y el pelo blanco. Es mi querida abuela y también mi vieja amiga (amie de longue date).*\nOn vérifie : accords (*argentina, alegre, trabajadora, verdes, blanco*), nationalité, antéposition affective (*querida*), sens changeant (*gran persona*, *vieja amiga*), apocope (*gran*, *buena* non apocopé au féminin)."}$exo$::jsonb),
  ('6e5dcd29-7d4a-5d48-bc8c-50d10c744f1f'::uuid, 1, 'traduction', $exo${"titre":"Le pronom sujet : utile ou lourd ?","consigne":"Réponds aux questions et corrige les phrases.","enonce":"**1.** Dans ces phrases, supprime le pronom sujet s'il est inutile :\n\na) Yo hablo español y yo estudio inglés.\nb) Nosotros vivimos en Bilbao.\nc) Tú trabajas y él duerme.\n\n**2.** Conjugue au présent :\na) ¿Usted (hablar) francés?\nb) ¿Ustedes (querer) café?\n\n**3.** Traduis : *pour moi*, *avec toi*, *entre toi et moi*.","bareme":[{"critere":"Pronoms inutiles supprimés en a et b, gardés en c pour l'opposition","points":7},{"critere":"Usted et ustedes conjugués à la 3e personne : habla, quieren","points":6},{"critere":"Para mí, contigo, entre tú y yo justes","points":7}],"dureeMin":7,"corrige":"**1.**\na) *Hablo español y estudio inglés.* — la terminaison suffit à identifier la personne.\nb) *Vivimos en Bilbao.*\nc) *Tú trabajas y él duerme.* — on **garde** les pronoms : ils servent à **opposer** deux personnes.\n\n**2.**\na) *¿Usted **habla** francés?*\nb) *¿Ustedes **quieren** café?* (*querer* diphtongue)\n*Usted* et *ustedes* se conjuguent à la **3e personne** (ils viennent de *vuestra merced*, « votre grâce »).\n\n**3.** *para mí* (accent sur *mí*, pronom après préposition) ; *contigo* (forme soudée avec *con*) ; *entre tú y yo* (après *entre*, on garde *tú* et *yo*)."}$exo$::jsonb),
  ('6e5dcd29-7d4a-5d48-bc8c-50d10c744f1f'::uuid, 2, 'traduction', $exo${"titre":"Du tu au vous à la réception","consigne":"Transforme le dialogue comme demandé, puis réponds aux questions.","enonce":"**Situation.** Julia travaille à l'accueil d'un hôtel de Cádiz. Elle parle d'abord à son collègue, puis doit dire la même chose à un client.\n\n> ¿Tienes tu pasaporte? ¿Quieres una habitación con vistas al mar? Puedes dejar tu maleta aquí. ¿Necesitas ayuda?\n\n1. Réécris ces phrases en **vouvoyant** un client (*usted*).\n2. Réécris-les pour **un groupe de clients** (*ustedes*).\n3. Pourquoi un Mexicain dirait-il *ustedes* même à un groupe d'amis ?\n4. Un Argentin dit : *¿Vos tenés hambre?* Comment s'appelle cet usage ? Est-ce une faute ?","bareme":[{"critere":"Vouvoiement singulier juste : tiene, quiere, puede, necesita, su maleta","points":8},{"critere":"Vouvoiement pluriel juste : tienen, quieren, pueden, necesitan, sus maletas","points":6},{"critere":"Vosotros n'existe pas en Amérique latine","points":3},{"critere":"Voseo identifié comme norme régionale, pas une faute","points":3}],"dureeMin":10,"corrige":"**1.** *¿Tiene (usted) su pasaporte? ¿Quiere una habitación con vistas al mar? Puede dejar su maleta aquí. ¿Necesita ayuda?* — verbe à la **3e personne du singulier** ; le possessif devient *su*.\n\n**2.** *¿Tienen (ustedes) sus pasaportes? ¿Quieren una habitación (unas habitaciones) con vistas al mar? Pueden dejar sus maletas aquí. ¿Necesitan ayuda?* — **3e personne du pluriel**.\n\n**3.** En **Amérique latine**, *vosotros* n'existe pas : le pluriel familier est *ustedes*, même entre amis.\n\n**4.** C'est le **voseo** : *vos* remplace *tú*, avec ses formes propres (*vos tenés*, *vos sos*). Ce n'est **pas une faute**, c'est une norme régionale (Argentine, Uruguay, Paraguay, Amérique centrale)."}$exo$::jsonb),
  ('6e5dcd29-7d4a-5d48-bc8c-50d10c744f1f'::uuid, 3, 'traduction', $exo${"titre":"Moi, je ne l'ai pas dit","consigne":"Traduis le dialogue en choisissant quand exprimer le pronom sujet, puis justifie tes choix.","enonce":"**Texte à traduire.** Deux frères se disputent devant leur mère.\n\n> — Maman, c'est lui qui a cassé le vase ! Moi, je ne l'ai pas touché.\n> — Ce n'est pas vrai ! Toi, tu joues au ballon dans le salon, et moi, je lis.\n> — Madame, vous voulez un café ? demande la voisine, qui entre.\n> — Oui, merci. Viens avec moi, Pablo. Et toi, reste avec ton frère : entre toi et moi, ce n'est pas grave.\n\n1. Traduis le dialogue.\n2. Relève **trois** pronoms sujets que tu as exprimés et donne la raison (insister, opposer, lever une ambiguïté).\n3. Justifie la forme de *vous* (voisine → la mère) et celle de *avec moi*.","bareme":[{"critere":"Pronoms sujets exprimés seulement pour insister ou opposer, omis ailleurs","points":6},{"critere":"Usted avec verbe à la 3e personne : ¿Quiere usted un café?","points":4},{"critere":"Conmigo et entre tú y yo justes","points":4},{"critere":"Trois justifications exactes","points":4},{"critere":"Traduction compréhensible","points":2}],"dureeMin":15,"corrige":"**1.** Traduction attendue :\n> — Mamá, ¡él ha roto el jarrón! Yo no lo he tocado.\n> — ¡No es verdad! Tú juegas al balón en el salón y yo leo.\n> — Señora, ¿quiere (usted) un café? —pregunta la vecina, que entra.\n> — Sí, gracias. Ven conmigo, Pablo. Y tú, quédate con tu hermano: entre tú y yo, no es grave.\n\n**2.** Justifications :\n- *él ha roto* : **insister** sur le coupable (et lever l'ambiguïté).\n- *Yo no lo he tocado* : **insister** (« moi, je… »).\n- *Tú juegas… y yo leo* : **opposer** deux personnes.\n- *Y tú, quédate* : opposition avec Pablo.\nAilleurs (*entra*, *quiere*), le pronom est omis : la terminaison suffit.\n\n**3.** *¿Quiere usted…?* : le vouvoiement d'une personne se fait avec *usted* et le verbe à la **3e personne**. *Conmigo* : avec *con*, le pronom se soude de façon irrégulière. *Entre tú y yo* : après *entre*, on garde *tú* et *yo*."}$exo$::jsonb),
  ('c849b29a-f8c6-5b01-8670-e2899dc3891d'::uuid, 1, 'traduction', $exo${"titre":"Remplacer par un pronom","consigne":"Remplace les mots soulignés (en gras) par le pronom complément qui convient.","enonce":"**1. Remplace** le complément en gras par un pronom :\n\na) Veo **a María** cada día.\nb) Hablo **a Juan** por teléfono.\nc) Compro **los libros**.\nd) Escribo **a mis abuelos**.\n\n**2. Remplace les deux compléments** :\na) Doy **el libro a Juan**.\nb) Digo **la verdad a mis padres**.\n\n**3.** Dans quel ordre se placent le COI et le COD ?","bareme":[{"critere":"COD et COI simples justes : la veo, le hablo, los compro, les escribo","points":8},{"critere":"Double pronom juste avec le changement de le en se : se lo doy, se la digo","points":8},{"critere":"Ordre COI puis COD","points":4}],"dureeMin":7,"corrige":"**1.**\na) ***La** veo cada día.* — COD féminin : *la*.\nb) ***Le** hablo por teléfono.* — COI : *le*.\nc) ***Los** compro.* — COD masculin pluriel.\nd) ***Les** escribo.* — COI pluriel.\nLe pronom se place **devant** le verbe conjugué.\n\n**2.**\na) ***Se lo** doy.* — *le* devant *lo* devient **se** (« le lo doy » est impossible).\nb) ***Se la** digo.* — *les* devant *la* devient **se**.\n\n**3.** Toujours le **COI avant le COD** : *me lo da*, *te la doy*, *se lo doy*."}$exo$::jsonb),
  ('c849b29a-f8c6-5b01-8670-e2899dc3891d'::uuid, 2, 'traduction', $exo${"titre":"Donne-le-moi, ne me le donne pas","consigne":"Réécris les phrases en remplaçant les compléments par des pronoms placés correctement.","enonce":"**Situation.** Chez Andrea, on prépare le repas de dimanche.\n\n1. Remplace les compléments en gras par des pronoms :\na) ¡Da **la sal a tu hermano**! (impératif affirmatif)\nb) ¡No des **la sal a tu hermano**! (impératif négatif)\nc) Voy a preparar **la tortilla**. (donne les deux constructions)\nd) Estoy cortando **las cebollas**. (gérondif)\ne) Quiero decir **la noticia a vosotros**.\n\n2. Pourquoi écrit-on *dásela* et *cortándolas* avec un accent ?","bareme":[{"critere":"Impératif affirmatif et négatif justes : dásela, no se la des","points":6},{"critere":"Deux constructions avec semi-auxiliaire : la voy a preparar / voy a prepararla","points":4},{"critere":"Gérondif et infinitif avec enclise justes : cortándolas, decírosla","points":6},{"critere":"Accent expliqué : garder la syllabe tonique d'origine","points":4}],"dureeMin":10,"corrige":"**1.**\na) *¡**Dásela**!* — impératif affirmatif : pronoms **soudés** derrière ; COI avant COD ; *le* devant *la* devient *se*.\nb) *¡No **se la** des!* — impératif négatif : pronoms **devant** le verbe.\nc) *La voy a preparar.* = *Voy a prepararla.* — avec un verbe conjugué + infinitif, les deux places sont admises.\nd) *Estoy **cortándolas**.* (ou *Las estoy cortando.*) — gérondif : pronom soudé derrière.\ne) *Quiero **decírosla**.* (ou *Os la quiero decir.*) — infinitif : pronoms soudés, COI *os* avant COD *la*.\n\n**2.** L'enclise allonge le mot : on ajoute un **accent écrit** pour garder la **syllabe tonique** du verbe d'origine (*da* → *dásela*, *cortando* → *cortándolas*)."}$exo$::jsonb),
  ('c849b29a-f8c6-5b01-8670-e2899dc3891d'::uuid, 3, 'traduction', $exo${"titre":"Le cadeau d'anniversaire","consigne":"Traduis le dialogue, puis justifie la place et la forme de chaque pronom.","enonce":"**Texte à traduire.** Nora et son père préparent l'anniversaire de la grand-mère.\n\n> — Tu as acheté le cadeau pour mamie ?\n> — Oui, je l'ai acheté hier. Je vais le lui donner ce soir.\n> — Montre-le-moi !\n> — Non, ne le touche pas ! Je suis en train de l'emballer.\n> — Tu lui as dit que nous venons dîner ?\n> — Oui, je le lui ai dit ce matin.\n\n1. Traduis le dialogue (utilise *mamie* = la abuela, *emballer* = envolver).\n2. Pour **quatre** pronoms, justifie la place (proclise ou enclise) et la forme (*se* à la place de *le*, ordre COI-COD).\n3. Explique le rôle de *le* dans : *Le doy el regalo a la abuela.* Est-ce une lourdeur ?","bareme":[{"critere":"Se lo voy a dar / voy a dárselo et se lo he dicho justes","points":5},{"critere":"Impératifs justes : enséñamelo, no lo toques","points":4},{"critere":"Gérondif juste : estoy envolviéndolo ou lo estoy envolviendo","points":3},{"critere":"Quatre justifications exactes","points":5},{"critere":"Redoublement du COI expliqué comme la norme","points":3}],"dureeMin":16,"corrige":"**1.** Traduction attendue :\n> — ¿Has comprado el regalo para la abuela?\n> — Sí, lo compré ayer (lo he comprado ayer). Se lo voy a dar esta noche (Voy a dárselo esta noche).\n> — ¡Enséñamelo! (¡Muéstramelo!)\n> — ¡No, no lo toques! Estoy envolviéndolo (Lo estoy envolviendo).\n> — ¿Le has dicho que venimos a cenar?\n> — Sí, se lo he dicho esta mañana.\n\n**2.** Justifications :\n- *lo compré* : verbe conjugué, pronom **devant**.\n- *se lo voy a dar* / *voy a dárselo* : deux places admises ; *le* devant *lo* devient **se** ; ordre COI puis COD.\n- *enséñamelo* : impératif affirmatif, **soudé** ; accent pour garder la syllabe tonique.\n- *no lo toques* : impératif négatif (subjonctif), pronom **devant**.\n- *envolviéndolo* : gérondif, soudé, accent ajouté.\n- *se lo he dicho* : bloc *haber* + participe, pronoms devant l'auxiliaire.\n\n**3.** *Le* reprend le COI *a la abuela* : c'est le **redoublement** du COI, très fréquent en espagnol. Ce n'est pas une lourdeur, c'est la **norme**."}$exo$::jsonb),
  ('dcb43f90-2741-566c-b27c-ea92c9576e2f'::uuid, 1, 'traduction', $exo${"titre":"Mi, mío, el mío","consigne":"Complète avec le possessif qui convient.","enonce":"**1. Complète avec un possessif atone** (devant le nom) :\n\na) (mes) … libros\nb) (notre) … casa\nc) (ton) … hermano\nd) (leurs) … padres\n\n**2. Complète avec un possessif tonique :**\na) Este libro es … (à moi).\nb) Es un amigo … (à moi).\nc) Tu bici es roja; … (la mienne) es azul.\n\n**3.** Avec quoi s'accorde le possessif espagnol ?","bareme":[{"critere":"Quatre possessifs atones justes : mis, nuestra, tu, sus","points":8},{"critere":"Trois possessifs toniques justes : mío, mío, la mía","points":8},{"critere":"Accord avec l'objet possédé","points":4}],"dureeMin":6,"corrige":"**1.**\na) ***mis** libros*\nb) ***nuestra** casa* — *nuestro* varie en genre : féminin car *casa*.\nc) ***tu** hermano* (sans accent : *tú* est le pronom sujet)\nd) ***sus** padres* — *su(s)* sert aussi pour « leur(s) ».\n\n**2.**\na) *Este libro es **mío**.* — attribut.\nb) *Es un amigo **mío**.* — après le nom, pour insister (« un ami à moi »).\nc) *La **mía** es azul.* — avec l'article, comme pronom ; accordé avec *bici* (féminin).\n\n**3.** Le possessif s'accorde avec **ce qui est possédé**, pas avec le possesseur : *mis libros* (plusieurs livres, un seul possesseur)."}$exo$::jsonb),
  ('dcb43f90-2741-566c-b27c-ea92c9576e2f'::uuid, 2, 'traduction', $exo${"titre":"Le matin chez les García","consigne":"Traduis les phrases en faisant attention à l'emploi de l'article ou du possessif.","enonce":"**Situation.** C'est la course du matin chez les García.\n\n1. Traduis :\na) Je me lave les mains.\nb) Mon petit frère a mal à la tête.\nc) Papa enlève son manteau.\nd) Ma sœur se brosse les dents.\n\n2. La mère dit : *Su mochila está en la cocina.* Donne **trois** sens possibles de *su* ici, et réécris la phrase pour qu'il soit clair que c'est le sac de Clara.\n\n3. La grand-mère s'exclame en voyant son petit-fils : « Mon fils ! » Traduis.","bareme":[{"critere":"Quatre traductions avec l'article défini pour le corps et les vêtements","points":10},{"critere":"Ambiguïté de su expliquée et levée par de ella / de Clara","points":6},{"critere":"Vocatif juste : ¡Hijo mío!","points":4}],"dureeMin":10,"corrige":"**1.**\na) *Me lavo las manos.*\nb) *A mi hermano pequeño le duele la cabeza.*\nc) *Papá se quita el abrigo.*\nd) *Mi hermana se lava los dientes.*\nQuand la possession est évidente (corps, vêtements), l'espagnol emploie **l'article défini** : le pronom réfléchi porte déjà l'information.\n\n**2.** *Su mochila* peut signifier **son** sac (à lui), **son** sac (à elle), **leur** sac ou **votre** sac (de *usted*). Pour lever l'ambiguïté : *La mochila de Clara está en la cocina* (ou *la mochila de ella*).\n\n**3.** *¡Hijo mío!* — au vocatif, le possessif tonique suit le nom."}$exo$::jsonb),
  ('dcb43f90-2741-566c-b27c-ea92c9576e2f'::uuid, 3, 'traduction', $exo${"titre":"Les objets trouvés","consigne":"Corrige les erreurs en justifiant, puis rédige un court dialogue en espagnol.","enonce":"**1. Chaque phrase contient une erreur.** Corrige-la et explique.\n\na) Me lavo mis manos antes de comer.\nb) Nuestro casa está cerca del mar.\nc) Este paraguas es mi.\nd) Es un mi amigo.\n\n**2. Production (6 à 8 répliques).** Au bureau des objets trouvés du collège, deux élèves cherchent leurs affaires. Écris le dialogue en employant :\n- deux possessifs atones, dont *nuestro* ou *vuestro* accordé ;\n- un possessif tonique en attribut (*es mío*) ;\n- un possessif pronom (*el mío, la tuya…*) ;\n- une phrase où l'on emploie l'article et non le possessif (corps ou vêtement) ;\n- *su* suivi d'une précision avec *de*.","bareme":[{"critere":"Quatre corrections justes : las manos, nuestra casa, es mío, un amigo mío","points":6},{"critere":"Quatre explications exactes","points":4},{"critere":"Possessifs atones, toniques et pronoms justes et accordés dans le dialogue","points":6},{"critere":"Article pour le corps ou le vêtement et su précisé par de","points":3},{"critere":"Dialogue cohérent","points":1}],"dureeMin":16,"corrige":"**1.**\na) *Me lavo **las** manos.* — le pronom réfléchi indique déjà la possession : article défini.\nb) ***Nuestra** casa* — *nuestro* s'accorde en genre avec *casa*.\nc) *Este paraguas es **mío**.* — en attribut, on emploie la forme tonique.\nd) *Es **un amigo mío**.* — la forme tonique se place après le nom ; l'atone ne suit jamais un article.\n\n**2.** Exemple :\n> — Buenos días, busco mi mochila y mis guantes.\n> — ¿Es esta mochila azul?\n> — No, la mía es negra. Esta es de Leo, creo.\n> — Y esta chaqueta, ¿es tuya?\n> — ¡Sí, es mía! Me la quité en el patio.\n> — ¿Y este estuche? Es su estuche… el estuche de Marta, tiene su nombre.\n> — Nuestra profesora dice que hay muchas cosas aquí.\nOn vérifie : *mi, mis, nuestra* (atones), *es mía, tuya* (attribut), *la mía* (pronom), *me la quité* (article sous-entendu, pas de possessif), *su estuche… de Marta*."}$exo$::jsonb),
  ('f627bdd0-c585-5aaa-b129-d2d10ebc514f'::uuid, 1, 'traduction', $exo${"titre":"Que, quien, cuyo, lo que","consigne":"Complète avec le pronom relatif qui convient.","enonce":"**1. Complète** avec *que, quien, cuyo / cuya / cuyos / cuyas* ou *lo que* :\n\na) El libro … leo es muy bonito.\nb) La persona con … hablo es mi tía.\nc) El escritor … novela leí es colombiano.\nd) Llegó tarde, … me molestó.\ne) La casa … muros son blancos es de mis abuelos.\n\n**2.** Comment demande-t-on « À qui est-ce ? » en espagnol ?","bareme":[{"critere":"Cinq relatifs justes : que, quien, cuya, lo que, cuyos","points":14},{"critere":"¿De quién es? et non cuyo en question","points":6}],"dureeMin":7,"corrige":"**1.**\na) *El libro **que** leo* — cas général : *que*.\nb) *La persona con **quien** hablo* — personne, après une préposition : *quien* (*con la que* accepté).\nc) *El escritor **cuya** novela leí* — *cuyo* s'accorde avec ce qui est possédé : *novela*, féminin singulier.\nd) *Llegó tarde, **lo que** me molestó.* — reprend une idée entière.\ne) *La casa **cuyos** muros son blancos* — accordé avec *muros*, masculin pluriel ; jamais d'article après *cuyo*.\n\n**2.** *¿De quién es?* — *cuyo* ne s'emploie **jamais** en question (« ¿Cuyo es? » est faux)."}$exo$::jsonb),
  ('f627bdd0-c585-5aaa-b129-d2d10ebc514f'::uuid, 2, 'traduction', $exo${"titre":"Deux phrases en une","consigne":"Relie chaque paire de phrases avec un pronom relatif, puis justifie ton choix.","enonce":"**Situation.** Pour la page « Découvertes » du journal du collège, Inès présente des lieux et des personnes de Barcelone.\n\n1. Relie les deux phrases avec un relatif :\na) Visité un museo. El museo tiene obras de Picasso.\nb) Conocí a un artista. Los cuadros del artista están en el museo.\nc) Esta es la plaza. Paseé por la plaza.\nd) Mi guía se llama Jordi. Jordi vive en Barcelona. (relative explicative, personne)\ne) El museo cerró temprano. Eso nos sorprendió.\n\n2. Pour chaque phrase obtenue, nomme le relatif employé et dis pourquoi.","bareme":[{"critere":"Que et cuyos justes en a et b, cuyos accordé avec cuadros","points":6},{"critere":"Préposition devant le relatif en c : por la que","points":4},{"critere":"Quien en relative explicative en d et lo que en e","points":5},{"critere":"Justifications exactes","points":5}],"dureeMin":10,"corrige":"**1.**\na) *Visité un museo **que** tiene obras de Picasso.* — cas général.\nb) *Conocí a un artista **cuyos** cuadros están en el museo.* — « dont » possessif ; accord avec *cuadros* (masculin pluriel), sans article.\nc) *Esta es la plaza **por la que** paseé.* — la préposition précède toujours le relatif ; on ajoute l'article (*por donde* accepté).\nd) *Mi guía, **quien** vive en Barcelona, se llama Jordi.* — personne, relative explicative entre virgules (*que* accepté).\ne) *El museo cerró temprano, **lo que** nos sorprendió.* — reprise d'une idée entière (*lo cual* accepté).\n\n**2.** Justifications : celles données après chaque phrase."}$exo$::jsonb),
  ('f627bdd0-c585-5aaa-b129-d2d10ebc514f'::uuid, 3, 'traduction', $exo${"titre":"Le village dont je rêve","consigne":"Traduis le texte, puis justifie chaque relatif employé.","enonce":"**Texte à traduire.**\n\n> Le village dont je rêve est un village dont les maisons sont blanches. Les gens qui y vivent sont accueillants. Mon ami Marcos, qui est né là-bas, m'a montré la rue dans laquelle il jouait enfant. Celui qui veut connaître l'Espagne doit visiter ces villages, ce que je fais chaque été.\n\nVocabulaire : *rêver de* = soñar con, *accueillant* = acogedor.\n\n1. Traduis le texte.\n2. Justifie **chaque** relatif (que, quien, cuyo, el que avec préposition, lo que).\n3. Pourquoi ne peut-on pas écrire *cuyas las casas* ?","bareme":[{"critere":"Con el que sueño et cuyas casas justes","points":5},{"critere":"Que, quien (ou que) et en la que justes","points":5},{"critere":"El que (ou quien) sans antécédent et lo que justes","points":4},{"critere":"Justifications exactes","points":4},{"critere":"Règle : cuyo jamais suivi d'un article","points":2}],"dureeMin":16,"corrige":"**1.** Traduction attendue :\n*El pueblo con el que sueño es un pueblo cuyas casas son blancas. La gente que vive allí es acogedora. Mi amigo Marcos, quien (que) nació allí, me enseñó la calle en la que jugaba de niño. El que (Quien) quiere conocer España debe visitar estos pueblos, lo que hago cada verano.*\n\n**2.**\n- *con el que sueño* : le verbe se construit avec *con* ; la préposition précède le relatif, avec l'article.\n- *cuyas casas* : « dont » possessif, accordé avec *casas* (féminin pluriel).\n- *que vive allí* : cas général, relative déterminative.\n- *, quien nació allí,* : personne, relative explicative.\n- *en la que jugaba* : préposition devant le relatif.\n- *El que quiere* : antécédent implicite (« celui qui »).\n- *lo que hago* : reprend une idée entière (visiter ces villages).\n\n**3.** *Cuyo* n'est **jamais** suivi d'un article : il joue lui-même le rôle de déterminant."}$exo$::jsonb),
  ('c655d4ac-de2f-5b80-8e3a-bb5d77169737'::uuid, 1, 'traduction', $exo${"titre":"Quelqu'un, personne, quelque chose, rien","consigne":"Complète avec l'indéfini qui convient.","enonce":"**1. Complète** avec *alguien, nadie, algo, nada, algún, ningún* :\n\na) ¿Hay … en casa? — No, no hay …\nb) ¿Quieres … de beber? — No, no quiero …\nc) ¿Tienes … libro de Borges? — No, no tengo … libro de él.\n\n**2. Traduis :**\na) Je ne vois personne.\nb) tous les élèves\nc) chaque jour","bareme":[{"critere":"Six indéfinis justes : alguien, nadie, algo, nada, algún, ningún","points":12},{"critere":"No veo a nadie avec la préposition a","points":4},{"critere":"Todos los alumnos et cada día justes","points":4}],"dureeMin":7,"corrige":"**1.**\na) *¿Hay **alguien** en casa? — No, no hay **nadie**.* (personne)\nb) *¿Quieres **algo** de beber? — No, no quiero **nada**.* (chose)\nc) *¿Tienes **algún** libro de Borges? — No, no tengo **ningún** libro de él.* — *alguno* et *ninguno* s'apocopent devant un masculin singulier.\n\n**2.**\na) *No veo a nadie.* — avec un COD de personne, la préposition *a* est obligatoire ; double négation.\nb) *todos los alumnos* — *todo* exige l'article.\nc) *cada día* — *cada* est invariable."}$exo$::jsonb),
  ('c655d4ac-de2f-5b80-8e3a-bb5d77169737'::uuid, 2, 'traduction', $exo${"titre":"Le règlement de la colonie","consigne":"Corrige les erreurs du règlement, puis traduis les phrases demandées.","enonce":"**Document.** Voici le règlement d'une colonie de vacances à Asturias. Il contient **cinq erreurs** d'indéfinis.\n\n> Todos días, cada uno hace su cama. Cadas dos horas, hay una pausa. Ningunos chicos pueden salir solos. Cualquiera día puedes llamar a tus padres. Un otro monitor vigila la piscina.\n\n1. Recopie le règlement corrigé.\n2. Traduis :\na) N'importe qui peut participer.\nb) Les autres sont à la plage.\nc) Je n'ai aucun doute (en plaçant l'indéfini après le nom).","bareme":[{"critere":"Cinq corrections justes : todos los días, cada, ningún chico, cualquier, otro","points":10},{"critere":"Cualquiera puede participar et los demás justes","points":5},{"critere":"No tengo duda alguna, sens négatif de alguno postposé","points":5}],"dureeMin":10,"corrige":"**1.** *Todos **los** días, cada uno hace su cama. **Cada** dos horas, hay una pausa. **Ningún chico puede** salir solo. **Cualquier** día puedes llamar a tus padres. **Otro** monitor vigila la piscina.*\n- *todo* exige l'article ;\n- *cada* est invariable, jamais de pluriel ;\n- *ninguno* s'emploie presque toujours au **singulier** et s'apocope devant un masculin ;\n- *cualquiera* s'apocope en *cualquier* devant un nom ;\n- jamais d'article indéfini devant *otro*.\n\n**2.**\na) *Cualquiera puede participar.* — seul, *cualquiera* garde le -a.\nb) *Los demás están en la playa.*\nc) *No tengo duda alguna.* — placé **après** le nom, *alguno* prend un sens **négatif renforcé**."}$exo$::jsonb),
  ('c655d4ac-de2f-5b80-8e3a-bb5d77169737'::uuid, 3, 'traduction', $exo${"titre":"Un jour de pluie à la maison","consigne":"Traduis le texte, puis justifie cinq indéfinis de ta traduction.","enonce":"**Texte à traduire.**\n\n> Il pleut toute la journée. Personne ne sort. Quelqu'un frappe à la porte, mais ce n'est personne d'important : c'est un voisin qui cherche quelque chose. Chacun lit un livre. Mes deux sœurs jouent aux cartes ; les autres regardent un film. N'importe quel film nous va. Je n'ai aucune envie de travailler.\n\nVocabulaire : *frapper* = llamar, *envie* = ganas (féminin pluriel : *tener ganas de*).\n\n1. Traduis le texte.\n2. Justifie **cinq** indéfinis (accord, apocope, préposition, double négation, place).\n3. Quelle différence de sens y a-t-il entre *cada día* et *todos los días* ?","bareme":[{"critere":"Todo el día, nadie, alguien, algo, cada uno justes","points":6},{"critere":"Ambas (las dos), los demás, cualquier película justes","points":4},{"critere":"Double négation avec ningunas ganas ou ninguna gana (no tengo…)","points":3},{"critere":"Cinq justifications exactes","points":5},{"critere":"Nuance cada día / todos los días","points":2}],"dureeMin":16,"corrige":"**1.** Traduction attendue :\n*Llueve todo el día. Nadie sale (No sale nadie). Alguien llama a la puerta, pero no es nadie importante: es un vecino que busca algo. Cada uno lee un libro. Mis dos hermanas (ambas) juegan a las cartas; los demás ven una película. Cualquier película nos vale. No tengo ningunas ganas de trabajar (No tengo ninguna gana de trabajar).*\n\n**2.** Justifications possibles :\n- *todo el día* : *todo* s'accorde et exige l'article.\n- *Nadie sale* : mot négatif avant le verbe, pas de *no* ; *no es nadie* : double négation.\n- *alguien*, *algo* : invariables.\n- *cada uno* : « chacun », *cada* invariable.\n- *los demás* : les autres, le reste.\n- *cualquier película* : apocope devant un nom, même féminin.\n- *ningunas ganas* : accord avec *ganas* (féminin pluriel, nom toujours pluriel), double négation.\n\n**3.** *Cada día* **détaille** jour après jour ; *todos los días* insiste sur **l'ensemble** des jours."}$exo$::jsonb),
  ('8168886d-51d3-5687-922a-b5f508344ee4'::uuid, 1, 'traduction', $exo${"titre":"Plus, moins, aussi, autant","consigne":"Complète avec la structure de comparaison qui convient.","enonce":"**1. Complète :**\n\na) Pablo es … alto … Luis. (plus… que)\nb) Tengo … dinero … tú. (moins… que)\nc) Marta es … simpática … su hermana. (aussi… que)\nd) Tengo … libros … tú. (autant de… que)\ne) Trabaja … yo. (autant que)\n\n**2.** Donne le comparatif irrégulier de : *bueno*, *malo*.\n\n**3.** Corrige : *Este helado es más mejor.*","bareme":[{"critere":"Cinq comparaisons justes : más que, menos que, tan como, tantos como, tanto como","points":12},{"critere":"Mejor et peor","points":4},{"critere":"Correction : es mejor, jamais más mejor","points":4}],"dureeMin":7,"corrige":"**1.**\na) *Pablo es **más** alto **que** Luis.*\nb) *Tengo **menos** dinero **que** tú.*\nc) *Marta es **tan** simpática **como** su hermana.* — *tan* devant un adjectif.\nd) *Tengo **tantos** libros **como** tú.* — *tanto* devant un nom, accordé (*libros*, masculin pluriel).\ne) *Trabaja **tanto como** yo.* — après un verbe, *tanto como* invariable.\n\n**2.** *bueno* → **mejor** ; *malo* → **peor**.\n\n**3.** *Este helado es **mejor**.* — les comparatifs irréguliers ne s'emploient **jamais** avec *más*."}$exo$::jsonb),
  ('8168886d-51d3-5687-922a-b5f508344ee4'::uuid, 2, 'traduction', $exo${"titre":"Pablo contre Inés","consigne":"Lis le tableau et rédige les comparaisons demandées en espagnol.","enonce":"**Document.** Deux élèves de 3e comparent leur semaine.\n\n| | Pablo | Inés |\n| Âge | 15 ans | 14 ans |\n| Heures de sport | 6 h | 6 h |\n| Livres lus ce mois-ci | 2 | 5 |\n| Taille | 1,70 m | 1,70 m |\n| Note en maths | 12 | 16 |\n\n1. Écris **cinq phrases** de comparaison, une par ligne du tableau. Emploie au moins : *más… que*, *menos… que*, *tan… como*, *tanto(s)… como* et *mayor* ou *menor*.\n2. Traduis : *Inés a lu plus de quatre livres.*","bareme":[{"critere":"Supériorité et infériorité justes avec que","points":5},{"critere":"Égalité juste : tan alto como et tanto deporte ou tantas horas como","points":6},{"critere":"Mayor ou menor pour l'âge","points":4},{"critere":"Más de devant un nombre","points":5}],"dureeMin":10,"corrige":"**1.** Exemples de phrases attendues :\n- Âge : *Pablo es **mayor que** Inés.* / *Inés es menor que Pablo.* — *mayor* et *menor* pour l'âge.\n- Sport : *Pablo hace **tantas horas** de deporte **como** Inés.* (ou *Pablo hace deporte **tanto como** Inés*) — égalité avec un nom : *tanto* accordé ; avec un verbe : *tanto como*.\n- Livres : *Pablo lee **menos** libros **que** Inés.* / *Inés lee más libros que Pablo.*\n- Taille : *Pablo es **tan** alto **como** Inés.* — égalité avec un adjectif : *tan… como*.\n- Maths : *Inés tiene una nota **mejor que** Pablo.* (ou *más alta que*) — jamais « más mejor ».\n\n**2.** *Inés ha leído **más de** cuatro libros.* — devant un nombre, on emploie **de** et non *que*."}$exo$::jsonb),
  ('8168886d-51d3-5687-922a-b5f508344ee4'::uuid, 3, 'traduction', $exo${"titre":"Plus difficile qu'il n'y paraît","consigne":"Traduis, puis explique les pièges de chaque phrase.","enonce":"**1. Traduis** ces phrases d'un article sur le brevet :\n\na) L'examen est plus difficile qu'il n'y paraît.\nb) Je n'ai que dix euros pour acheter les livres.\nc) Je n'ai pas plus de dix euros.\nd) Il fait de plus en plus chaud en juin.\ne) Les élèves ont plus de temps qu'ils ne le disent.\nf) Mon frère aîné travaille autant que moi, mais il a de moins bonnes notes.\n\n**2.** Explique la différence de sens entre b) et c) et la construction qui les distingue.\n\n**3.** Explique pourquoi on écrit *de lo que* en a) et *del que* en e).","bareme":[{"critere":"Más difícil de lo que parece et más tiempo del que dicen justes","points":5},{"critere":"No tengo más que diez euros et no tengo más de diez euros justes","points":5},{"critere":"Cada vez más calor, hermano mayor, tanto como, peores notas justes","points":5},{"critere":"Différence de sens b / c expliquée","points":3},{"critere":"De lo que (idée) / del que (nom masculin) expliqué","points":2}],"dureeMin":16,"corrige":"**1.**\na) *El examen es más difícil **de lo que** parece.*\nb) *No tengo **más que** diez euros para comprar los libros.*\nc) *No tengo **más de** diez euros.*\nd) *Hace **cada vez más** calor en junio.*\ne) *Los alumnos tienen más tiempo **del que** dicen.*\nf) *Mi hermano **mayor** trabaja **tanto como** yo, pero tiene **peores** notas.*\n\n**2.** b) *no… más que* + nombre = **seulement** (« je n'ai que dix euros ») ; c) *no… más de* + nombre = **pas plus de** (plafond). La seule différence, *que* ou *de*, change le sens.\n\n**3.** Quand le second terme de la comparaison est une **proposition**, on emploie *de lo que*, *del que*, *de la que* : *de lo que* reprend une idée ou un adjectif (a : *difícil*) ; *del que* s'accorde avec un nom masculin exprimé (e : *tiempo*)."}$exo$::jsonb),
  ('de48f430-1dbf-57c9-9e52-d9d1c2489da7'::uuid, 1, 'traduction', $exo${"titre":"Le suffixe -ísimo","consigne":"Forme le superlatif absolu en -ísimo, puis traduis.","enonce":"**1. Forme le superlatif absolu** en *-ísimo* :\n\na) guapo\nb) rico\nc) largo\nd) feliz\ne) blanco\nf) fácil\n\n**2. Traduis :** *C'est le plus grand pays d'Amérique du Sud.* (le pays = el país)\n\n**3.** Corrige : *Es muy guapísimo.*","bareme":[{"critere":"Six formes justes avec les changements orthographiques (qu, gu, c)","points":12},{"critere":"Superlatif relatif avec de : el país más grande de","points":5},{"critere":"Correction : muy et -ísimo ne se cumulent pas","points":3}],"dureeMin":7,"corrige":"**1.**\na) *guapísimo*\nb) *riquísimo* — c devient **qu** pour garder le son.\nc) *larguísimo* — g devient **gu**.\nd) *felicísimo* — z devient **c**.\ne) *blanquísimo* — c devient **qu**.\nf) *facilísimo* — l'accent se déplace sur *-ísimo*.\n\n**2.** *Es el país más grande **de** América del Sur.* — le superlatif relatif se construit avec **de**, jamais avec *en*.\n\n**3.** *Es guapísimo.* ou *Es muy guapo.* — les deux formes de l'absolu ne se cumulent jamais."}$exo$::jsonb),
  ('de48f430-1dbf-57c9-9e52-d9d1c2489da7'::uuid, 2, 'traduction', $exo${"titre":"Les records de la classe","consigne":"Lis le document, puis rédige les phrases demandées en espagnol.","enonce":"**Document.** Résultats du cross du collège, classe de 3e B.\n\n| Élève | Temps | Âge |\n| Adrián | 12 min | 14 ans |\n| Sofía | 10 min | 15 ans |\n| Leo | 15 min | 14 ans |\n\n1. Écris **trois phrases** au superlatif relatif : l'élève le plus rapide de la classe, le plus lent, la plus âgée. (*rápido*, *lento*)\n2. Sofía dit que la course était *muy larga* et *muy difícil*. Réécris ces deux adjectifs avec *-ísimo*.\n3. Donne le superlatif savant de *bueno* et de *malo*, puis écris une phrase avec l'un d'eux.","bareme":[{"critere":"Trois superlatifs relatifs justes avec de la clase","points":9},{"critere":"Larguísima et dificilísima justes","points":6},{"critere":"Óptimo et pésimo avec une phrase correcte","points":5}],"dureeMin":10,"corrige":"**1.**\n- *Sofía es la alumna más rápida de la clase.*\n- *Leo es el alumno más lento de la clase.*\n- *Sofía es la (alumna) mayor de la clase.* ou *la más mayor* (courant). On attend **de la clase**, jamais *en la clase*.\n\n**2.** *larguísima* (g devient **gu**, accord au féminin) ; *dificilísima* (accord au féminin).\n\n**3.** *bueno* → **óptimo** ; *malo* → **pésimo**. Exemple : *El tiempo fue pésimo: llovió todo el día.* — registre soutenu."}$exo$::jsonb),
  ('de48f430-1dbf-57c9-9e52-d9d1c2489da7'::uuid, 3, 'traduction', $exo${"titre":"La critique gastronomique","consigne":"Corrige les erreurs en justifiant, puis rédige une courte critique en espagnol.","enonce":"**1. Chaque phrase contient une erreur.** Corrige-la et explique.\n\na) Es el restaurante más caro en la ciudad.\nb) La paella estaba muy riquísima.\nc) El postre era ricísimo.\nd) Es el plato más bueno del menú. (utilise le comparatif irrégulier)\n\n**2. Production (50 mots environ).** Tu as mangé dans un restaurant de Madrid. Rédige une critique en employant :\n- deux superlatifs relatifs avec **de** ;\n- trois superlatifs absolus en **-ísimo**, dont un avec changement orthographique ;\n- un superlatif savant (*óptimo*, *pésimo*, *máximo*, *mínimo*).","bareme":[{"critere":"Quatre corrections justes : de la ciudad, riquísima, riquísimo, el mejor plato","points":6},{"critere":"Quatre explications exactes","points":4},{"critere":"Deux superlatifs relatifs avec de","points":4},{"critere":"Trois -ísimo justes, dont un changement orthographique, et un superlatif savant","points":5},{"critere":"Critique compréhensible","points":1}],"dureeMin":15,"corrige":"**1.**\na) *Es el restaurante más caro **de** la ciudad.* — le complément du superlatif relatif se construit avec *de*, jamais *en*.\nb) *La paella estaba **riquísima**.* — *muy* et *-ísimo* ne se cumulent pas.\nc) *El postre era **riquísimo**.* — c devient *qu* pour garder le son [k].\nd) *Es **el mejor** plato del menú.* — *bueno* a un comparatif irrégulier : *mejor* ; « más bueno » est évité.\n\n**2.** Exemple :\n*Ayer cené en el restaurante más famoso del barrio. La tortilla estaba riquísima y el pan, blanquísimo, era buenísimo. Es el mejor restaurante de Madrid, pero el servicio fue lentísimo. Precio: el mínimo para un sitio así. Calidad: óptima.*\nOn vérifie : *más famoso del barrio*, *el mejor… de Madrid* (relatif + de) ; *riquísima*, *blanquísimo* (changements c → qu), *lentísimo* ; superlatif savant *mínimo* / *óptima*."}$exo$::jsonb),
  ('3c96162d-3fc9-5ef4-b61f-a0b0a4a2c1db'::uuid, 1, 'traduction', $exo${"titre":"Le mot qui perd sa fin","consigne":"Complète chaque groupe avec la forme qui convient du mot entre parenthèses. Attention : l'apocope n'est pas toujours possible.","enonce":"**Complète** avec la bonne forme :\n\na) (bueno) un … amigo\nb) (primero) el … día del mes\nc) (grande) una … ciudad\nd) (ciento) … euros\ne) (santo) … Pedro\nf) (ninguno) … problema\ng) (tercero) la … vez\nh) (cualquiera) … día\ni) (alguno) … día\nj) (malo) … tiempo","bareme":[{"critere":"Apocopes devant un nom masculin singulier justes : buen, primer, ningún, algún, mal","points":10},{"critere":"Apocopes particulières justes : gran (devant un féminin), cien, San, cualquier","points":7},{"critere":"Tercera gardée entière devant un féminin, accents de ningún et algún écrits","points":3}],"dureeMin":6,"corrige":"a) un **buen** amigo — *bueno* s'apocope devant un nom masculin singulier.\nb) el **primer** día del mes — même règle.\nc) una **gran** ciudad — *grande* devient *gran* devant un nom singulier, **masculin ou féminin**.\nd) **cien** euros — *ciento* devient *cien* devant un nom.\ne) **San** Pedro — *santo* devient *san* devant un prénom masculin.\nf) **ningún** problema — avec l'accent écrit.\ng) la **tercera** vez — devant un **féminin**, rien ne change : pas d'apocope.\nh) **cualquier** día — *cualquiera* devient *cualquier* devant tout nom.\ni) **algún** día — avec l'accent écrit.\nj) **mal** tiempo — *malo* s'apocope devant un nom masculin singulier."}$exo$::jsonb),
  ('3c96162d-3fc9-5ef4-b61f-a0b0a4a2c1db'::uuid, 2, 'traduction', $exo${"titre":"Le guide de voyage de Clara","consigne":"Traduis les phrases en espagnol en appliquant les règles de l'apocope, puis réponds à la question.","enonce":"**Situation.** Clara prépare un petit guide pour un voyage de classe en République dominicaine.\n\n**1. Traduis en espagnol :**\n\na) Le premier jour, nous visitons Saint-Domingue (*Santo Domingo*).\nb) Un bon guide coûte cent euros.\nc) Cent vingt élèves participent au voyage.\nd) Lucas est le premier de la classe.\ne) C'est une grande femme (= une femme importante).\nf) Il y a de grands musées (*museos*).\n\n**2.** Explique la différence de sens entre *un gran hombre* et *un hombre grande*.","bareme":[{"critere":"Apocopes justes : primer día, buen guía, cien euros, gran mujer","points":8},{"critere":"Exceptions respectées : Santo Domingo, ciento veinte, el primero sans nom, grandes au pluriel","points":8},{"critere":"Différence de sens gran devant / grande derrière expliquée","points":4}],"dureeMin":10,"corrige":"**1.**\na) *El **primer** día visitamos **Santo** Domingo.* — *primer* devant un masculin singulier ; *Santo* garde sa forme devant **Do-** (exception).\nb) *Un **buen** guía cuesta **cien** euros.* — *buen* devant un masculin ; *cien* devant un nom.\nc) ***Ciento** veinte alumnos participan en el viaje.* — *ciento* reste entier devant un autre nombre.\nd) *Lucas es **el primero** de la clase.* — pas de nom juste derrière : forme pleine.\ne) *Es una **gran** mujer.* — *gran* devant un nom singulier, même féminin.\nf) *Hay **grandes** museos.* — au **pluriel**, la forme entière revient.\n\n**2.** Le sens change avec la place : ***gran*** placé **devant** le nom signifie « important, remarquable » (*un gran hombre* = un grand homme) ; ***grande*** placé **derrière** signifie « de grande taille » (*un hombre grande* = un homme grand)."}$exo$::jsonb),
  ('3c96162d-3fc9-5ef4-b61f-a0b0a4a2c1db'::uuid, 3, 'traduction', $exo${"titre":"Le blog de voyage à corriger","consigne":"Corrige le texte en justifiant chaque correction, puis rédige un court paragraphe en espagnol.","enonce":"**Document.** Théo a écrit ce paragraphe en espagnol sur son blog de voyage. Il contient **sept erreurs** liées à l'apocope.\n\n> El primero día de mi viaje, visité la iglesia de San Tomás en Santo Domingo. Es una grande ciudad de más de ciento mil habitantes. Mis amigos dominicanos son grans personas. Cualquiera día es bueno para ir a la playa. Nuestro guía es un hombre buen y simpático.\n\n1. Recopie le texte corrigé.\n2. Pour **cinq** erreurs, explique la règle en une phrase.\n3. Rédige un paragraphe de 40 mots environ sur ta ville ou ton village. Tu dois employer : *buen* ou *mal*, *gran*, *primer* ou *tercer*, *cien* et un adjectif placé **après** le nom qui garde donc sa forme pleine.","bareme":[{"critere":"Les sept erreurs corrigées : primer, Santo Tomás, gran ciudad, cien mil, grandes, cualquier, hombre bueno","points":7},{"critere":"Cinq règles expliquées avec justesse","points":5},{"critere":"Production : buen ou mal, gran, primer ou tercer et cien employés correctement","points":6},{"critere":"Production : adjectif placé après le nom sans apocope, texte compréhensible","points":2}],"dureeMin":16,"corrige":"**1.** *El **primer** día de mi viaje, visité la iglesia de **Santo** Tomás en Santo Domingo. Es una **gran** ciudad de más de **cien** mil habitantes. Mis amigos dominicanos son **grandes** personas. **Cualquier** día es bueno para ir a la playa. Nuestro guía es un hombre **bueno** y simpático.*\n\n**2.** Règles attendues (cinq parmi) :\n- *primero* devient *primer* devant un nom masculin singulier : *el primer día*.\n- *santo* devient *san* devant un prénom masculin, **sauf** devant To- et Do- : *Santo Tomás*.\n- *grande* devient *gran* devant un nom singulier, masculin ou féminin : *una gran ciudad*.\n- *ciento* devient *cien* devant *mil* et *millones* : *cien mil*.\n- Au **pluriel**, la forme entière revient : *grandes personas* (« grans » n'existe pas).\n- *cualquiera* devient *cualquier* devant tout nom : *cualquier día*.\n- L'apocope ne joue que si l'adjectif est **immédiatement devant** le nom : *un hombre bueno*.\n\n**3.** Exemple de production :\n*Vivo en un pueblo pequeño. Hay un buen mercado los sábados y una gran plaza con una iglesia antigua. Mi casa está en el primer piso de un edificio de cien años. Hoy hace mal tiempo, pero es un pueblo bonito.*\nOn vérifie : *buen mercado*, *mal tiempo*, *gran plaza*, *primer piso*, *cien años*, et un adjectif après le nom (*una iglesia antigua*, *un pueblo bonito*)."}$exo$::jsonb),
  ('67af6235-f1c9-593f-bf49-94929dc34947'::uuid, 1, 'traduction', $exo${"titre":"Haber, hay ou está ?","consigne":"Conjugue les verbes au passé composé (pretérito perfecto), puis complète avec hay ou está.","enonce":"**1. Conjugue au pretérito perfecto** (haber au présent + participe passé) :\n\na) yo (comer)\nb) tú (hablar)\nc) ella (llegar)\nd) nosotros (vivir)\ne) ellos (terminar)\n\n**2. Complète avec *hay* ou *está* :**\n\na) En mi calle … una panadería.\nb) La panadería … al lado del cine.\nc) … muchos alumnos en el patio.\nd) ¿Dónde … el libro de Ana?\ne) … dos parques en el barrio.","bareme":[{"critere":"Cinq formes du pretérito perfecto justes (he comido, has hablado, ha llegado, hemos vivido, han terminado)","points":10},{"critere":"Hay pour l'existence, invariable même au pluriel ; está pour la localisation d'une chose connue","points":10}],"dureeMin":6,"corrige":"**1.**\na) **he comido**\nb) **has hablado**\nc) **ha llegado** — pas d'auxiliaire « être » en espagnol : *haber* partout.\nd) **hemos vivido**\ne) **han terminado**\nLe participe ne s'accorde jamais avec *haber*.\n\n**2.**\na) En mi calle **hay** una panadería. — existence d'une chose non encore identifiée.\nb) La panadería **está** al lado del cine. — localisation d'une chose déjà connue (*la* panadería).\nc) **Hay** muchos alumnos en el patio. — *hay* est **invariable**, même devant un pluriel.\nd) ¿Dónde **está** el libro de Ana? — on cherche où se trouve un objet précis.\ne) **Hay** dos parques en el barrio."}$exo$::jsonb),
  ('67af6235-f1c9-593f-bf49-94929dc34947'::uuid, 2, 'traduction', $exo${"titre":"Le journal de Sofía","consigne":"Transforme les phrases puis traduis en espagnol, en respectant les deux règles de l'auxiliaire unique.","enonce":"**Situation.** Sofía, 14 ans, raconte sa semaine dans son journal.\n\n**1. Mets au pretérito perfecto** (participes donnés quand ils sont irréguliers) :\n\na) Nunca visito Madrid.\nb) Mis amigas llegan tarde.\nc) No lo veo (*visto*).\nd) La carta que escribo (*escrito*) es larga.\n\n**2. Traduis en espagnol :**\n\na) Il y avait beaucoup d'élèves à la fête.\nb) Il y aura un concert samedi.\nc) Il faut étudier pour réussir.\nd) Quand je suis arrivée, il était déjà sorti (*salir*).","bareme":[{"critere":"Pretérito perfecto juste, sans accord du participe (han llegado, he escrito)","points":6},{"critere":"Bloc haber + participe soudé : négation, pronom et nunca placés devant","points":4},{"critere":"Formes de hay justes : había, habrá, et hay que + infinitif","points":6},{"critere":"Plus-que-parfait juste : había salido","points":4}],"dureeMin":11,"corrige":"**1.**\na) ***Nunca he visitado** Madrid* (ou *No he visitado nunca Madrid*) — jamais « he nunca visitado » : le bloc est soudé.\nb) *Mis amigas **han llegado** tarde.* — le participe ne s'accorde pas : jamais « llegadas ».\nc) ***No lo he visto.*** — la négation et le pronom se placent **devant** l'auxiliaire.\nd) *La carta que **he escrito** es larga.* — aucun accord, même avec un complément placé avant : jamais « escrita ».\n\n**2.**\na) ***Había** muchos alumnos en la fiesta.* — imparfait de *hay*, invariable.\nb) ***Habrá** un concierto el sábado.* — futur de *hay*.\nc) ***Hay que** estudiar para aprobar.* — obligation impersonnelle.\nd) *Cuando llegué, ya **había salido**.* — plus-que-parfait : *había* + participe."}$exo$::jsonb),
  ('67af6235-f1c9-593f-bf49-94929dc34947'::uuid, 3, 'traduction', $exo${"titre":"Le déménagement à Séville","consigne":"Corrige le texte en justifiant tes corrections, puis rédige un court texte en espagnol.","enonce":"**Document.** Inès raconte son déménagement à Séville. Son texte contient **six erreurs** liées à *haber*.\n\n> Este año, hemos nos mudado a Sevilla. Mi madre ha encontrada un trabajo en un hospital. En nuestro barrio hay dos parques y está un cine. Han habido muchos cambios en mi vida. Mis hermanas han llegadas en septiembre. He nunca visto una ciudad tan bonita.\n\n1. Recopie le texte corrigé.\n2. Pour **quatre** erreurs, explique la règle en une phrase.\n3. Rédige 5 phrases en espagnol (45 mots environ) sur un changement dans ta vie (nouvelle école, nouveau sport…). Tu dois employer : un pretérito perfecto à la forme négative, un plus-que-parfait (*había* + participe), *hay* ou *había* pour l'existence, *habrá* et *hay que* + infinitif.","bareme":[{"critere":"Six erreurs corrigées : nos hemos mudado, encontrado, hay un cine, ha habido, llegado, nunca he visto","points":6},{"critere":"Quatre règles expliquées avec justesse (auxiliaire unique, pas d'accord, bloc soudé, hay invariable, hay / está)","points":4},{"critere":"Production : pretérito perfecto négatif et plus-que-parfait justes","points":5},{"critere":"Production : hay ou había, habrá et hay que employés correctement","points":5}],"dureeMin":17,"corrige":"**1.** *Este año, **nos hemos mudado** a Sevilla. Mi madre ha **encontrado** un trabajo en un hospital. En nuestro barrio hay dos parques y **hay** un cine. **Ha habido** muchos cambios en mi vida. Mis hermanas han **llegado** en septiembre. **Nunca he visto** (ou *No he visto nunca*) una ciudad tan bonita.*\n\n**2.** Règles attendues (quatre parmi) :\n- Le bloc *haber* + participe est **soudé** : le pronom se place devant (*nos hemos mudado*), l'adverbe aussi (*nunca he visto*).\n- Le participe **ne s'accorde jamais** avec *haber* : *encontrado*, *llegado*.\n- *Hay* (et ses formes, *ha habido*) est **invariable** : jamais « han habido ».\n- *Hay* pose l'**existence** d'une chose non identifiée (*un cine*) ; *está* donne la localisation d'une chose connue.\n\n**3.** Exemple de production :\n*Este año he cambiado de instituto. Todavía no he hecho muchos amigos. Antes de llegar, nunca había visto un instituto tan grande: hay mil alumnos. El próximo mes habrá una excursión. Hay que estudiar mucho, pero me gusta.*\nOn vérifie : *no he hecho* (négatif), *había visto* (plus-que-parfait), *hay mil alumnos*, *habrá*, *hay que estudiar*, sans accord du participe."}$exo$::jsonb),
  ('ffe82ba9-f248-599e-a1df-622773d1bbd1'::uuid, 1, 'traduction', $exo${"titre":"Le pronom à sa place","consigne":"Complète avec le verbe pronominal à la forme demandée, en plaçant correctement le pronom, puis traduis.","enonce":"**1. Complète :**\n\na) (levantarse, yo, présent) … a las siete.\nb) (ducharse) Voy a … ahora.\nc) (levantarse, tú, impératif) ¡… ya!\nd) (peinarse) Mi hermana está … .\ne) (lavarse, nosotros, présent) … las manos antes de comer.\n\n**2. Traduis en espagnol :**\n\na) Je m'en vais.\nb) Tu te souviens de Marta ? (*acordarse de*)\nc) Ils s'écrivent tous les jours.","bareme":[{"critere":"Pronom devant le verbe conjugué : me levanto, nos lavamos","points":6},{"critere":"Pronom soudé derrière l'infinitif, le gérondif et l'impératif : ducharme, peinándose, levántate","points":8},{"critere":"Traductions justes : me voy, te acuerdas de, se escriben","points":6}],"dureeMin":7,"corrige":"**1.**\na) **Me levanto** a las siete. — verbe conjugué : pronom **devant**.\nb) Voy a **ducharme** ahora. — infinitif : pronom **soudé derrière** (on accepte aussi *Me voy a duchar*, avec un semi-auxiliaire).\nc) ¡**Levántate** ya! — impératif affirmatif : pronom soudé, accent écrit ajouté.\nd) Mi hermana está **peinándose**. — gérondif : pronom soudé (ou *se está peinando*).\ne) **Nos lavamos** las manos antes de comer.\n\n**2.**\na) ***Me voy.*** — *irse* = partir.\nb) *¿**Te acuerdas de** Marta?* — *acordarse de* = se souvenir de.\nc) ***Se escriben** todos los días.* — valeur **réciproque**."}$exo$::jsonb),
  ('ffe82ba9-f248-599e-a1df-622773d1bbd1'::uuid, 2, 'traduction', $exo${"titre":"Les cinq visages de se","consigne":"Identifie la valeur de se dans chaque phrase et traduis-la, puis écris les phrases demandées.","enonce":"**Situation.** En se promenant dans Salamanque, Yanis note des phrases entendues ou lues sur les murs.\n\n**1. Pour chaque phrase**, donne la valeur de *se* (réfléchie, réciproque, lexicale, passive, impersonnelle) et traduis :\n\na) Se venden pisos.\nb) Aquí se habla inglés.\nc) Pablo y Lucía se quieren mucho.\nd) El niño se lava la cara.\ne) Mi abuela se queja siempre.\n\n**2. Écris en espagnol**, avec une tournure en *se* :\n\na) On vend des vélos (*bicicletas*).\nb) Ici on mange bien.\nc) Il s'est enfilé toute la pizza (passé simple : *comió*).","bareme":[{"critere":"Cinq valeurs de se identifiées correctement","points":7},{"critere":"Cinq traductions justes","points":5},{"critere":"Passive accordée au pluriel (se venden) et impersonnelle au singulier (se come)","points":6},{"critere":"Pronominal d'intensité juste : se comió toda la pizza","points":2}],"dureeMin":11,"corrige":"**1.**\na) *Se venden pisos* — **passive** : le verbe s'accorde avec *pisos* → « Appartements à vendre ».\nb) *Aquí se habla inglés* — **impersonnelle** : verbe au singulier → « Ici, on parle anglais ».\nc) *Pablo y Lucía se quieren mucho* — **réciproque** → « Pablo et Lucía s'aiment beaucoup ».\nd) *El niño se lava la cara* — **réfléchie** : l'action revient sur le sujet → « L'enfant se lave le visage ».\ne) *Mi abuela se queja siempre* — **lexicale** : *quejarse* n'existe qu'à la forme pronominale → « Ma grand-mère se plaint toujours ».\n\n**2.**\na) ***Se venden** bicicletas.* — passive : accord au pluriel avec *bicicletas*.\nb) *Aquí **se come** bien.* — impersonnelle : singulier.\nc) ***Se comió** toda la pizza.* — pronominal d'intensité : nuance d'appropriation, sans valeur réfléchie."}$exo$::jsonb),
  ('ffe82ba9-f248-599e-a1df-622773d1bbd1'::uuid, 3, 'traduction', $exo${"titre":"Le matin de Léna","consigne":"Traduis le texte en espagnol, justifie trois choix, puis rédige un court texte.","enonce":"**Document.** Léna raconte ses matins.\n\n> « Tous les matins, je me réveille à sept heures, mais je reste au lit dix minutes. Ensuite, je me douche et je m'habille. Mon frère et moi, nous nous disputons souvent. Hier, il s'est enfilé tout le gâteau ! Dans mon quartier, on vend des maisons anciennes. Je m'en vais à huit heures. »\n\nAide : *despertarse* (e → ie), *quedarse*, *ducharse*, *vestirse* (me visto), *pelearse*, *venderse*, *irse* ; « il s'est enfilé » au passé simple : *comió*.\n\n1. Traduis le texte en espagnol.\n2. Justifie en une phrase chacun de ces choix : la traduction de « je reste », celle de « on vend des maisons », celle de « Je m'en vais ».\n3. Rédige 5 phrases en espagnol (45 mots environ) sur ta routine du week-end. Tu dois employer : un verbe pronominal conjugué, un pronom soudé à un infinitif, un emploi réciproque, un *se* impersonnel ou passif, et un verbe dont le sens change avec le pronom (*irse, dormirse, quedarse, ponerse*…).","bareme":[{"critere":"Traduction : pronoms réfléchis justes et bien placés (me despierto, me ducho, me visto, nos peleamos)","points":6},{"critere":"Traduction : me quedo, se comió, se venden accordé, me voy","points":4},{"critere":"Trois justifications exactes appuyées sur le cours","points":4},{"critere":"Production : les cinq emplois demandés, pronoms bien placés","points":6}],"dureeMin":18,"corrige":"**1.** *Todas las mañanas **me despierto** a las siete, pero **me quedo** en la cama diez minutos. Luego **me ducho** y **me visto**. Mi hermano y yo **nos peleamos** a menudo. Ayer ¡**se comió** toda la tarta! En mi barrio **se venden** casas antiguas. **Me voy** a las ocho.*\n\n**2.**\n- « je reste » → *me quedo* : *quedar* seul veut dire « convenir » ; **quedarse** signifie « rester sur place » — le pronom change le sens.\n- « on vend des maisons » → *se venden casas* : *se* **passif**, le verbe s'accorde avec *casas*, au pluriel.\n- « Je m'en vais » → *me voy* : *ir* = aller, **irse** = partir.\n\n**3.** Exemple de production :\n*El sábado me levanto tarde. Después voy a ducharme y a desayunar. Mis amigos y yo nos llamamos para quedar. En mi pueblo se come muy bien los domingos. Por la noche, me duermo delante de la tele.*\nOn vérifie : *me levanto* (conjugué), *ducharme* (soudé à l'infinitif), *nos llamamos* (réciproque), *se come* (impersonnel, singulier), *me duermo* (s'endormir). Toute production qui contient les cinq emplois correctement est acceptée."}$exo$::jsonb),
  ('a3ac594b-3593-5b3e-ae07-fe0d99b78801'::uuid, 1, 'traduction', $exo${"titre":"La conjugaison en botte","consigne":"Conjugue les verbes au présent de l'indicatif.","enonce":"**1. Conjugue au présent, à toutes les personnes :**\n\na) *pensar*\nb) *poder*\n\n**2. Conjugue à la personne demandée :**\n\na) yo (jugar)\nb) nosotros (volver)\nc) ellos (querer)\nd) tú (dormir)\ne) vosotros (empezar)\nf) él (oler)","bareme":[{"critere":"Pensar et poder justes aux six personnes, sans diphtongue à nosotros et vosotros","points":10},{"critere":"Six formes isolées justes : juego, volvemos, quieren, duermes, empezáis, huele","points":10}],"dureeMin":7,"corrige":"**1.**\na) *pienso, piensas, piensa, **pensamos, pensáis**, piensan*\nb) *puedo, puedes, puede, **podemos, podéis**, pueden*\nLes quatre formes qui diphtonguent dessinent une **botte** : *nosotros* et *vosotros* restent réguliers, car l'accent tonique tombe sur la terminaison.\n\n**2.**\na) yo **juego** — *jugar* est le seul verbe en u → ue.\nb) nosotros **volvemos** — pas de diphtongue.\nc) ellos **quieren** — e → ie.\nd) tú **duermes** — o → ue.\ne) vosotros **empezáis** — pas de diphtongue.\nf) él **huele** — *oler* prend un **h** quand il diphtongue."}$exo$::jsonb),
  ('a3ac594b-3593-5b3e-ae07-fe0d99b78801'::uuid, 2, 'traduction', $exo${"titre":"La lettre de Paula","consigne":"Complète la lettre avec les verbes au présent, puis réponds aux questions.","enonce":"**Situation.** Paula écrit à sa correspondante française.\n\n> Hola Camille: Por la mañana, (despertarse, yo) … a las siete, pero mi hermano (dormir) … hasta las nueve. Nosotros (empezar) … las clases a las ocho y media. Los sábados, mis amigos y yo (jugar) … al fútbol, pero mis primos (preferir) … el baloncesto. Mi madre (cerrar) … la tienda a las ocho. En la cocina, siempre (oler) … a café. ¿(Querer, tú) … venir en verano? Yo no (poder) … ir a Francia este año.\n\n1. Recopie les verbes conjugués.\n2. Explique pourquoi *empezar* et *jugar* ne diphtonguent pas dans cette lettre.\n3. Mets au passé simple : *yo pensé* ou *yo piensé* ? Justifie.","bareme":[{"critere":"Neuf verbes justes : me despierto, duerme, empezamos, jugamos, prefieren, cierra, huele, Quieres, puedo","points":12},{"critere":"Explication : à nosotros, l'accent tonique tombe sur la terminaison, donc pas de diphtongue","points":4},{"critere":"Passé simple pensé, sans diphtongue, justifié","points":4}],"dureeMin":11,"corrige":"**1.** *me despierto* — *duerme* — *empezamos* — *jugamos* — *prefieren* — *cierra* — *huele* — *¿Quieres* — *puedo*.\n\n**2.** *Empezar* et *jugar* sont conjugués à **nosotros** (*empezamos*, *jugamos*) : à cette personne, l'accent tonique tombe sur la **terminaison** et non sur la voyelle du radical, donc la voyelle reste simple. C'est l'une des deux personnes hors de la « botte ».\n\n**3.** ***Pensé*** : la diphtongue n'apparaît qu'au présent de l'indicatif, au présent du subjonctif et à l'impératif ; **jamais** au passé simple, à l'imparfait ni au futur (*pensé, pensaba, pensaré*). De plus, l'accent tonique de *pensé* est sur la terminaison."}$exo$::jsonb),
  ('a3ac594b-3593-5b3e-ae07-fe0d99b78801'::uuid, 3, 'traduction', $exo${"titre":"Les fautes de Hugo","consigne":"Corrige le texte en justifiant tes corrections, puis rédige un court texte en espagnol.","enonce":"**Document.** Hugo a écrit ce texte sur sa famille. Il contient **sept erreurs** de conjugaison.\n\n> Normalmente, yo me desperto a las siete. Mis padres piensan que nosotros duermemos poco. Mi hermana y yo juegamos al tenis los domingos. Ayer, yo piensé en mis abuelos. Mi perro olé todo el jardín. Tú no podes venir hoy, pero mis amigos queren verte.\n\n1. Recopie le texte corrigé.\n2. Explique la règle de la **botte** et pourquoi elle existe (3 lignes au plus).\n3. Pour **trois** autres erreurs, explique la correction en une phrase.\n4. Rédige 5 phrases en espagnol (45 mots environ) sur tes loisirs. Tu dois employer **quatre** verbes à diphtongue différents, dont un à la personne *nosotros* et *jugar*.","bareme":[{"critere":"Sept erreurs corrigées : despierto, dormimos, jugamos, pensé, huele, puedes, quieren","points":7},{"critere":"Règle de la botte expliquée par la place de l'accent tonique","points":4},{"critere":"Trois autres corrections justifiées (h de huele, jugar u → ue, pas de diphtongue au passé simple…)","points":3},{"critere":"Production : quatre verbes à diphtongue justes, nosotros sans diphtongue, jugar juste","points":6}],"dureeMin":17,"corrige":"**1.** *Normalmente, yo me **despierto** a las siete. Mis padres piensan que nosotros **dormimos** poco. Mi hermana y yo **jugamos** al tenis los domingos. Ayer, yo **pensé** en mis abuelos. Mi perro **huele** todo el jardín. Tú no **puedes** venir hoy, pero mis amigos **quieren** verte.*\n\n**2.** Quand l'accent tonique tombe sur la voyelle du radical, elle **diphtongue** (e → ie, o → ue). À *nosotros* et *vosotros*, l'accent tombe sur la **terminaison** : la voyelle reste simple. Les quatre formes qui diphtonguent (yo, tú, él, ellos) dessinent une botte autour de ces deux personnes.\n\n**3.** Corrections attendues (trois parmi) :\n- *despierto* : *despertar* diphtongue e → ie à la personne *yo*.\n- *jugamos* : *jugar* (u → ue) ne diphtongue pas à *nosotros*.\n- *pensé* : pas de diphtongue au **passé simple**.\n- *huele* : *oler* prend un **h** à l'écrit quand il diphtongue.\n- *puedes*, *quieren* : diphtongue obligatoire à *tú* et *ellos*.\n\n**4.** Exemple de production :\n*Los miércoles juego al baloncesto. Mis amigos y yo volvemos a casa a las seis. Prefiero los deportes de equipo. A veces mi hermano no puede venir y yo cuento los puntos. Los domingos empiezo a leer un libro.*\nOn vérifie : *juego*, *volvemos* (nosotros sans diphtongue), *prefiero*, *puede*, *cuento*, *empiezo*."}$exo$::jsonb),
  ('6a6528a1-d827-55f1-90bc-00b061ea806b'::uuid, 1, 'traduction', $exo${"titre":"La famille de pedir","consigne":"Conjugue les verbes à la forme demandée.","enonce":"**1. Conjugue *pedir* au présent de l'indicatif**, à toutes les personnes.\n\n**2. Donne la forme demandée :**\n\na) yo (seguir), présent\nb) yo (elegir), présent\nc) él (pedir), passé simple\nd) yo (pedir), passé simple\ne) le gérondif de *servir*\nf) le gérondif de *decir*","bareme":[{"critere":"Pedir juste aux six personnes, sans affaiblissement à nosotros et vosotros","points":8},{"critere":"Pièges orthographiques justes : sigo, elijo","points":4},{"critere":"Passé simple pidió / pedí et gérondifs sirviendo, diciendo justes","points":8}],"dureeMin":7,"corrige":"**1.** *pido, pides, pide, **pedimos, pedís**, piden* — le e devient i sous l'accent tonique, avec la même botte que la diphtongue.\n\n**2.**\na) **sigo** — *seguir* perd son u devant o.\nb) **elijo** — le g devient j devant o.\nc) **pidió** — au passé simple, l'affaiblissement touche les **3es personnes** (terminaison en *ió*).\nd) **pedí** — pas d'affaiblissement à la 1re personne du passé simple.\ne) **sirviendo** — le gérondif s'affaiblit toujours (terminaison en *ie*).\nf) **diciendo**"}$exo$::jsonb),
  ('6a6528a1-d827-55f1-90bc-00b061ea806b'::uuid, 2, 'traduction', $exo${"titre":"Au restaurant de Toledo","consigne":"Complète le texte avec les verbes au temps demandé, puis réponds à la question.","enonce":"**Situation.** Nora raconte un repas avec sa famille à Tolède.\n\n> En este restaurante, yo siempre (pedir, présent) … paella. El camarero nos (servir, présent) … muy rápido. Nosotros (repetir, présent) … el postre porque está muy rico. Ayer, mi padre (pedir, passé simple) … pescado y mis primos (pedir, passé simple) … carne. Yo (pedir, passé simple) … una ensalada. Ahora el camarero está (servir, gérondif) … el café. Espero que tú (pedir, subjonctif présent) … el flan la próxima vez.\n\n1. Recopie les huit verbes conjugués.\n2. Donne le repère du cours qui permet de savoir si *pedir* s'affaiblit au passé simple, et applique-le à *pidió* et *pedí*.","bareme":[{"critere":"Présent juste : pido, sirve, repetimos","points":5},{"critere":"Passé simple juste : pidió, pidieron, pedí","points":6},{"critere":"Gérondif sirviendo et subjonctif pidas justes","points":4},{"critere":"Repère ie / ió énoncé et appliqué","points":5}],"dureeMin":11,"corrige":"**1.** *pido* — *sirve* — *repetimos* (nosotros : pas d'affaiblissement) — *pidió* — *pidieron* — *pedí* — *sirviendo* — *pidas* (au subjonctif présent, l'affaiblissement touche **toutes** les personnes).\n\n**2.** Repère : dès que la **terminaison** contient *ie* ou *ió*, l'affaiblissement s'applique. *Pidió* se termine en *ió* : le e du radical devient i (jamais « pedió »). *Pedí* n'a ni *ie* ni *ió* dans sa terminaison : le radical reste en e. Au passé simple, seules les 3es personnes s'affaiblissent (*pidió, pidieron*)."}$exo$::jsonb),
  ('6a6528a1-d827-55f1-90bc-00b061ea806b'::uuid, 3, 'traduction', $exo${"titre":"La nuit agitée","consigne":"Corrige le texte, explique tes corrections, puis rédige un court récit en espagnol.","enonce":"**Document.** Adam raconte une nuit difficile. Son texte contient **sept erreurs**.\n\n> Anoche, mi hermano dormió mal y se sentió enfermo. Mi madre pedió un médico. Mis padres preferieron llamar a urgencias. Ahora mi hermano está mejor y yo sego sus consejos: estamos pediendo menos comida rápida. Para la cena de mañana, yo eligo el menú.\n\n1. Recopie le texte corrigé.\n2. Qu'est-ce qu'un verbe **mixte** ? Cite les deux verbes mixtes du texte et donne leur forme au présent (yo).\n3. Explique deux autres corrections en une phrase chacune.\n4. Rédige 5 phrases en espagnol (45 mots environ) sur un repas au restaurant, au passé simple et au présent. Tu dois employer *pedir* à la 3e personne du passé simple, un gérondif d'un verbe en *-ir* affaibli et *seguir* ou *elegir* à la 1re personne du présent.","bareme":[{"critere":"Sept erreurs corrigées : durmió, sintió, pidió, prefirieron, sigo, pidiendo, elijo","points":7},{"critere":"Verbe mixte défini, dormir et sentir cités avec duermo et siento","points":4},{"critere":"Deux autres corrections justifiées avec justesse","points":3},{"critere":"Production : pidió ou pidieron, gérondif affaibli, sigo ou elijo corrects","points":6}],"dureeMin":17,"corrige":"**1.** *Anoche, mi hermano **durmió** mal y se **sintió** enfermo. Mi madre **pidió** un médico. Mis padres **prefirieron** llamar a urgencias. Ahora mi hermano está mejor y yo **sigo** sus consejos: estamos **pidiendo** menos comida rápida. Para la cena de mañana, yo **elijo** el menú.*\n\n**2.** Un verbe **mixte** est un verbe en *-ir* qui **diphtongue au présent** et **s'affaiblit ailleurs** (passé simple aux 3es personnes, gérondif). Dans le texte : *dormir* (**duermo** / *durmió*) et *sentir* (**siento** / *sintió*) ; *preferir* aussi (**prefiero** / *prefirieron*).\n\n**3.** Corrections attendues (deux parmi) :\n- *pidió*, *pidiendo* : terminaison en *ió* ou *ie* → affaiblissement.\n- *sigo* : *seguir* perd son u devant o.\n- *elijo* : le g d'*elegir* devient j devant o.\n\n**4.** Exemple de production :\n*El sábado fuimos a un restaurante. Mi hermana pidió una pizza y mis padres pidieron pescado. El camarero estaba sirviendo el postre cuando llegó mi tío. Hoy yo elijo el restaurante. Sigo pensando en esa pizza.*\nOn vérifie : *pidió / pidieron*, *sirviendo*, *elijo*, *sigo*."}$exo$::jsonb),
  ('048b37a6-f40f-56e9-a9a4-88398692b1f9'::uuid, 1, 'traduction', $exo${"titre":"Ser ou estar ?","consigne":"Complète avec ser ou estar au présent, puis traduis.","enonce":"**1. Complète avec *ser* ou *estar* au présent :**\n\na) Madrid … en España.\nb) Mi madre … profesora.\nc) Hoy … lunes.\nd) Yo … cansado.\ne) La mesa … de madera.\nf) … las tres.\ng) Nosotros … estudiando.\nh) La fiesta … en mi casa.\n\n**2. Traduis :**\n\na) Je suis d'accord.\nb) Il est malade.","bareme":[{"critere":"Ser juste pour l'identité, la profession, la date, l'heure, la matière et l'événement (es, es, son, es, es)","points":10},{"critere":"Estar juste pour la localisation, l'état et la forme progressive (está, estoy, estamos)","points":6},{"critere":"Traductions justes : estoy de acuerdo, está enfermo (ou malo)","points":4}],"dureeMin":7,"corrige":"**1.**\na) Madrid **está** en España. — localisation d'un lieu.\nb) Mi madre **es** profesora. — profession.\nc) Hoy **es** lunes. — date.\nd) Yo **estoy** cansado. — état.\ne) La mesa **es** de madera. — matière.\nf) **Son** las tres. — l'heure, avec *ser* au pluriel.\ng) Nosotros **estamos** estudiando. — forme progressive.\nh) La fiesta **es** en mi casa. — un **événement** a lieu quelque part : *ser*.\n\n**2.**\na) ***Estoy de acuerdo.*** — expression figée avec *estar*.\nb) ***Está enfermo*** (ou *Está malo*). — état de santé."}$exo$::jsonb),
  ('048b37a6-f40f-56e9-a9a4-88398692b1f9'::uuid, 2, 'traduction', $exo${"titre":"La carte postale de Valence","consigne":"Complète la carte postale avec ser ou estar, puis traduis les phrases en choisissant le bon verbe.","enonce":"**Situation.** Marco envoie une carte postale à son ami Pablo.\n\n> Hola Pablo: (yo) … en Valencia con mis padres. La ciudad … muy bonita y … cerca del mar. Hoy … sábado y … las diez de la mañana. El hotel … grande, pero hoy nuestra habitación … sucia. El concierto … esta noche en la plaza. ¡(yo) … muy contento!\n\n1. Recopie les neuf verbes.\n2. **Traduis** en espagnol :\na) Il est malin. / Il est prêt.\nb) Ce garçon est ennuyeux. / Ce garçon s'ennuie.\nc) Cette paella est délicieuse.","bareme":[{"critere":"Neuf verbes justes : Estoy, es, está, es, son, es, está, es, Estoy","points":11},{"critere":"Paires listo et aburrido traduites avec le bon verbe","points":6},{"critere":"Estar rico pour délicieux","points":3}],"dureeMin":11,"corrige":"**1.** *Estoy* (localisation) — *es* (caractéristique) — *está* (localisation) — *es* (date) — *son* (heure) — *es* (caractéristique du lieu) — *está* (état constaté aujourd'hui) — *es* (un événement a lieu : *ser*) — *Estoy* (humeur).\n\n**2.**\na) ***Es listo*** (il est malin) / ***Está listo*** (il est prêt).\nb) *Este chico **es aburrido*** (ennuyeux) / *Este chico **está aburrido*** (il s'ennuie).\nc) *Esta paella **está rica**.* — *estar rico* = délicieux ; *ser rico* signifierait « être riche ».\nLes adjectifs qui changent de sens avec *ser* et *estar* sont des mots différents, pas des nuances."}$exo$::jsonb),
  ('048b37a6-f40f-56e9-a9a4-88398692b1f9'::uuid, 3, 'traduction', $exo${"titre":"Les vacances de Julien","consigne":"Corrige le texte en justifiant tes choix, puis rédige un court texte en espagnol.","enonce":"**Document.** Julien raconte ses vacances. Son texte contient **sept erreurs** entre *ser* et *estar*.\n\n> Soy en Sevilla de vacaciones. Mi hermano está alto y moreno, pero hoy es cansado. Hoy está martes. La paella de mi tía es muy rica hoy. El concierto de flamenco está en el estadio. La sopa es fría porque llegamos tarde. Estamos de acuerdo: ¡Sevilla es preciosa!\n\n1. Recopie le texte corrigé.\n2. Pour **quatre** erreurs, justifie la correction en une phrase.\n3. Explique le raccourci du cours qui permet de choisir entre *ser* et *estar*.\n4. Rédige 5 phrases en espagnol (45 mots environ) pour décrire ta ville et ce que tu ressens aujourd'hui. Tu dois employer *ser* trois fois (trois emplois différents) et *estar* trois fois (localisation, état, forme progressive).","bareme":[{"critere":"Sept erreurs corrigées : Estoy, es alto, está cansado, es martes, está rica, es en el estadio, está fría","points":7},{"critere":"Quatre justifications exactes","points":4},{"critere":"Raccourci expliqué : qu'est-ce que c'est ? / comment est-ce maintenant ?","points":3},{"critere":"Production : trois emplois de ser et trois de estar justes","points":6}],"dureeMin":17,"corrige":"**1.** ***Estoy** en Sevilla de vacaciones. Mi hermano **es** alto y moreno, pero hoy **está** cansado. Hoy **es** martes. La paella de mi tía **está** muy rica hoy. El concierto de flamenco **es** en el estadio. La sopa **está** fría porque llegamos tarde. Estamos de acuerdo: ¡Sevilla es preciosa!*\n\n**2.** Justifications (quatre parmi) :\n- *Estoy en Sevilla* : localisation d'une personne → *estar*.\n- *es alto* : caractéristique qui le définit → *ser*.\n- *está cansado* : état passager, constaté → *estar*.\n- *es martes* : la date → *ser*.\n- *está rica* : *estar rico* = délicieux (*ser rico* = riche).\n- *es en el estadio* : un **événement** a lieu quelque part → *ser*.\n- *está fría* : résultat d'un changement (elle a refroidi) → *estar*.\n\n**3.** *Ser* répond à « **qu'est-ce que c'est ?** » (ce qui définit) ; *estar* répond à « **comment est-ce, en ce moment ?** » (ce qui se constate).\n\n**4.** Exemple de production :\n*Mi ciudad es pequeña y es muy antigua. Está en el norte de Francia. Hoy es viernes. Estoy un poco nervioso porque estoy preparando un examen. Mi madre es enfermera y hoy está en el hospital.*\nOn vérifie : *ser* (caractéristique, date, profession) et *estar* (localisation, état, forme progressive)."}$exo$::jsonb),
  ('1b5746cb-4809-56e0-9d93-af42e8c60a46'::uuid, 1, 'traduction', $exo${"titre":"En train de…","consigne":"Donne le gérondif de chaque verbe, puis réponds avec estar + gérondif.","enonce":"**1. Donne le gérondif :**\n\na) *hablar*\nb) *comer*\nc) *vivir*\nd) *leer*\ne) *decir*\nf) *dormir*\ng) *ir*\nh) *oír*\n\n**2. Réponds à la question *¿Qué estás haciendo?*** avec *estar* + gérondif :\n\na) (estudiar)\nb) (escribir un mensaje)\nc) (leer un libro)","bareme":[{"critere":"Gérondifs réguliers justes : hablando, comiendo, viviendo","points":5},{"critere":"Gérondifs irréguliers justes : leyendo, diciendo, durmiendo, yendo, oyendo","points":9},{"critere":"Trois réponses justes avec estoy + gérondif","points":6}],"dureeMin":7,"corrige":"**1.**\na) **hablando** (-ar → -ando)\nb) **comiendo** (-er → -iendo)\nc) **viviendo** (-ir → -iendo)\nd) **leyendo** — *-iendo* devient *-yendo* après une voyelle.\ne) **diciendo**\nf) **durmiendo**\ng) **yendo**\nh) **oyendo**\n\n**2.**\na) ***Estoy estudiando.***\nb) ***Estoy escribiendo** un mensaje.*\nc) ***Estoy leyendo** un libro.*\nLa forme progressive se forme avec *estar* conjugué + gérondif."}$exo$::jsonb),
  ('1b5746cb-4809-56e0-9d93-af42e8c60a46'::uuid, 2, 'traduction', $exo${"titre":"Le message d'Élise","consigne":"Traduis les phrases en espagnol en utilisant les périphrases du cours.","enonce":"**Situation.** Élise écrit à sa correspondante de Grenade pour donner de ses nouvelles.\n\n**Traduis en espagnol :**\n\na) J'étudie l'espagnol depuis trois ans. (*llevar*)\nb) Il pleut toujours à Paris. (*seguir*)\nc) Mon grand-père va mieux petit à petit. (*ir*, *mejorar*)\nd) Hier, mon chien est sorti en courant.\ne) En entrant dans la classe, j'ai vu Juan. (*al*)\nf) Mon frère a fini par accepter. (*acabar*)\n\n**Question.** Pourquoi la périphrase avec *llevar* est-elle, selon le cours, « la plus rentable » ?","bareme":[{"critere":"Llevar + durée + gérondif et seguir + gérondif justes","points":6},{"critere":"Ir + gérondif et acabar + gérondif justes","points":4},{"critere":"Gérondif seul de manière (salió corriendo) et al + infinitif justes","points":6},{"critere":"Intérêt de llevar expliqué : rendre le « depuis » sans subordonnée","points":4}],"dureeMin":11,"corrige":"a) ***Llevo tres años estudiando** español.* — *llevar* + durée + gérondif : la durée écoulée.\nb) ***Sigue lloviendo** en París.* — continuation.\nc) *Mi abuelo **va mejorando**.* — progression lente.\nd) *Ayer mi perro **salió corriendo**.* — gérondif seul : la manière.\ne) ***Al entrar** en clase, vi a Juan.* — « en + participe présent » français se rend par *al* + infinitif ; jamais « en entrando » : après une préposition, l'infinitif.\nf) *Mi hermano **acabó aceptando**.* — le point d'aboutissement.\n\n**Question.** La périphrase avec *llevar* rend le « **depuis** » français en une seule proposition, **sans passer par une subordonnée** (*hace tres años que estudio…*)."}$exo$::jsonb),
  ('1b5746cb-4809-56e0-9d93-af42e8c60a46'::uuid, 3, 'traduction', $exo${"titre":"Le gérondif mal employé","consigne":"Corrige le texte en justifiant tes corrections, puis rédige un court texte en espagnol.","enonce":"**Document.** Léo a traduit mot à mot un texte français. Il contient **six erreurs** liées au gérondif.\n\n> Ayer recibí una caja conteniendo libros. En saliendo del colegio, vi a Marta. Estaba leiendo en un banco. Luego llegó a su casa, encontrando a su hermano dormiendo. Hace dos años que estudio español y sigo estudiar cada día.\n\n1. Recopie le texte corrigé.\n2. Le cours dit ce que le gérondif **ne peut pas** faire. Explique les deux interdits et montre où ils apparaissent dans le texte.\n3. Réécris la phrase *Hace dos años que estudio español* avec la périphrase *llevar*.\n4. Rédige 5 phrases en espagnol (45 mots environ) sur ce que tu fais en ce moment et depuis quand. Tu dois employer *estar* + gérondif, *llevar* + durée + gérondif, *seguir* + gérondif, un gérondif en *-yendo* et un gérondif seul de manière.","bareme":[{"critere":"Six erreurs corrigées : que contenía, al salir, leyendo, y encontró (postériorité), durmiendo, sigo estudiando","points":6},{"critere":"Deux interdits expliqués (qualifier un nom, exprimer la postériorité) et repérés","points":4},{"critere":"Réécriture juste : Llevo dos años estudiando español","points":3},{"critere":"Production : les cinq emplois demandés corrects","points":7}],"dureeMin":18,"corrige":"**1.** *Ayer recibí una caja **que contenía** libros. **Al salir** del colegio, vi a Marta. Estaba **leyendo** en un banco. Luego llegó a su casa **y encontró** a su hermano **durmiendo**. Hace dos años que estudio español y **sigo estudiando** cada día.*\n\n**2.**\n- Le gérondif ne peut pas **qualifier un nom** (calque du français) : *una caja conteniendo libros* → *una caja **que contiene / que contenía** libros*.\n- Il ne peut pas exprimer la **postériorité** : il dit le **simultané**. *Llegó a su casa, encontrando…* (elle trouve son frère **après** être arrivée) → deux propositions reliées par *y* : *llegó a su casa y encontró…*\n(Les autres fautes : *al salir* — après une préposition, l'infinitif ; *leyendo* — -yendo après une voyelle ; *durmiendo* — affaiblissement ; *sigo estudiando* — seguir + gérondif.)\n\n**3.** ***Llevo dos años estudiando español.***\n\n**4.** Exemple de production :\n*Ahora estoy escribiendo este texto. Llevo cuatro años aprendiendo español. Sigo jugando al fútbol los miércoles. Por la noche, estoy leyendo una novela. Esta mañana llegué al colegio corriendo.*\nOn vérifie : *estoy escribiendo*, *llevo… aprendiendo*, *sigo jugando*, *leyendo*, *corriendo* (manière)."}$exo$::jsonb),
  ('92e5a215-9816-58be-96f6-a5a7c5df5165'::uuid, 1, 'traduction', $exo${"titre":"Former et accorder le participe","consigne":"Donne le participe passé de chaque verbe, puis complète les phrases en accordant ou non.","enonce":"**1. Donne le participe passé :**\n\na) *hablar*\nb) *comer*\nc) *abrir*\nd) *decir*\ne) *escribir*\nf) *hacer*\ng) *romper*\nh) *volver*\n\n**2. Complète avec le participe du verbe entre parenthèses** (accordé ou non) :\n\na) La ventana está (abrir) … .\nb) Las chicas han (llegar) … .\nc) Las casas fueron (construir) … en 1920.\nd) Es una carta (escribir) … a mano.","bareme":[{"critere":"Participes réguliers et irréguliers justes : hablado, comido, abierto, dicho, escrito, hecho, roto, vuelto","points":10},{"critere":"Accord juste : abierta, construidas, escrita ; pas d'accord avec haber : llegado","points":10}],"dureeMin":7,"corrige":"**1.**\na) **hablado** b) **comido** c) **abierto** d) **dicho** e) **escrito** f) **hecho** g) **roto** h) **vuelto**\n\n**2.**\na) La ventana está **abierta**. — avec *estar*, accord avec le sujet (*la ventana*, féminin singulier).\nb) Las chicas han **llegado**. — avec *haber*, **jamais** d'accord.\nc) Las casas fueron **construidas** en 1920. — avec *ser*, accord avec le sujet (féminin pluriel).\nd) Es una carta **escrita** a mano. — employé comme adjectif, accord avec le nom."}$exo$::jsonb),
  ('92e5a215-9816-58be-96f6-a5a7c5df5165'::uuid, 2, 'traduction', $exo${"titre":"Le retour de la fête","consigne":"Complète le récit avec les participes, accordés ou non, puis transforme les phrases.","enonce":"**Situation.** Carmen rentre chez elle après une fête.\n\n> Cuando volví a casa, la puerta estaba (abrir) … y dos ventanas estaban (romper) … . Mis hermanas habían (salir) … . Las cartas que había (escribir) … estaban (poner) … en la mesa. Mi padre me dijo: «¡Todo está (hacer) …!»\n\n1. Recopie les six participes.\n2. Explique la différence de sens entre *La casa fue construida en 1920* et *La casa está construida*.\n3. Le cours dit que l'espagnol préfère d'autres tournures à la passive avec *ser*. Réécris *La casa fue construida en 1920* de **deux** autres façons.","bareme":[{"critere":"Participes irréguliers justes et accordés avec estar : abierta, rotas, puestas, hecho","points":8},{"critere":"Pas d'accord avec haber : salido, escrito","points":4},{"critere":"Différence passive d'action / état résultant expliquée","points":4},{"critere":"Deux réécritures justes : se construyó, construyeron","points":4}],"dureeMin":11,"corrige":"**1.** *abierta* (accord avec *la puerta*) — *rotas* (avec *dos ventanas*) — *salido* (avec *haber* : jamais d'accord) — *escrito* (avec *haber*, même si *las cartas* est placé avant) — *puestas* (avec *estar*, accord avec *las cartas*) — *hecho* (*todo*, masculin singulier).\n\n**2.** *Fue construida* (*ser* + participe) est la **passive d'action** : on assiste au fait, la construction a eu lieu en 1920. *Está construida* (*estar* + participe) décrit l'**état résultant** : la maison est finie, le fait est accompli.\n\n**3.**\n- Tournure en *se* : ***Se construyó** la casa en 1920.*\n- Troisième personne du pluriel : ***Construyeron** la casa en 1920.*"}$exo$::jsonb),
  ('92e5a215-9816-58be-96f6-a5a7c5df5165'::uuid, 3, 'traduction', $exo${"titre":"Le compte rendu de Samuel","consigne":"Corrige le texte en justifiant tes corrections, puis rédige un court texte en espagnol.","enonce":"**Document.** Samuel a écrit le compte rendu d'une journée de cuisine au collège. Il contient **sept erreurs** sur le participe passé.\n\n> Hoy hemos freído patatas y las patatas freídas estaban muy ricas. Las recetas que he escritas están en el cuaderno. La puerta de la cocina está abierto. Por desgracia, he rompido un plato. Las profesoras han volvidas a las tres. Nos han dado un texto imprimido. Los menús fueron escrito por los alumnos.\n\n1. Recopie le texte corrigé.\n2. Énonce en une ligne la règle d'accord du participe passé en espagnol.\n3. Qu'est-ce qu'un participe **double** ? Explique avec les deux exemples du texte.\n4. Rédige 5 phrases en espagnol (45 mots environ) sur une sortie scolaire. Tu dois employer : un temps composé avec *haber* et un participe irrégulier, *estar* + participe accordé au féminin, *ser* + participe au pluriel et un participe employé comme adjectif.","bareme":[{"critere":"Sept erreurs corrigées : fritas, escrito, abierta, roto, vuelto, impreso, escritos","points":7},{"critere":"Règle d'accord énoncée : figé avec haber, accordé partout ailleurs","points":3},{"critere":"Participe double expliqué avec freír et imprimir","points":4},{"critere":"Production : les quatre emplois demandés, accords justes","points":6}],"dureeMin":17,"corrige":"**1.** *Hoy hemos freído patatas y las patatas **fritas** estaban muy ricas. Las recetas que he **escrito** están en el cuaderno. La puerta de la cocina está **abierta**. Por desgracia, he **roto** un plato. Las profesoras han **vuelto** a las tres. Nos han dado un texto **impreso**. Los menús fueron **escritos** por los alumnos.*\n\n**2.** Ce qui suit *haber* est **figé** (jamais d'accord) ; avec *ser*, *estar* ou comme adjectif, le participe **s'accorde** (avec le sujet ou le nom).\n\n**3.** Un participe double existe sous deux formes : une **régulière** pour les temps composés, une **irrégulière** employée comme adjectif. *Freír* : *hemos freído* (temps composé, correct dans le texte) mais *patatas fritas* (adjectif). *Imprimir* : *he imprimido* mais *un texto impreso*.\n\n**4.** Exemple de production :\n*Hoy hemos visto un museo muy grande. La sala principal estaba cerrada. Los cuadros fueron pintados por Goya. He escrito un resumen para la clase. Hemos comprado unas postales pintadas a mano.*\nOn vérifie : *hemos visto / he escrito* (haber + irrégulier, sans accord), *estaba cerrada* (estar, féminin), *fueron pintados* (ser, pluriel), *postales pintadas* (adjectif)."}$exo$::jsonb),
  ('1bdc719b-8869-511f-9baf-1e876e63c314'::uuid, 1, 'traduction', $exo${"titre":"Ce qui me plaît","consigne":"Complète avec le verbe et le pronom qui conviennent, puis réponds pour dire « moi aussi » ou « moi non plus ».","enonce":"**1. Complète :**\n\na) A mí … (gustar) el chocolate.\nb) A ella … (gustar) los perros.\nc) A nosotros … (gustar) bailar y cantar.\nd) A ellos … (encantar) las películas de terror.\ne) … (doler, a mí) la cabeza.\nf) ¿A ti … (gustar) el fútbol?\n\n**2. Réponds :**\n\na) — Me gusta el cine. — (moi aussi) …\nb) — No me gustan los lunes. — (moi non plus) …","bareme":[{"critere":"Pronom complément juste à chaque phrase : me, le, nos, les, me, te","points":6},{"critere":"Accord du verbe avec ce qui plaît : gusta, gustan, gusta (deux infinitifs), encantan, duele","points":10},{"critere":"Réponses justes : A mí también, A mí tampoco","points":4}],"dureeMin":6,"corrige":"**1.**\na) A mí **me gusta** el chocolate.\nb) A ella **le gustan** los perros. — le sujet est *los perros*, pluriel.\nc) A nosotros **nos gusta** bailar y cantar. — deux infinitifs : **singulier quand même**.\nd) A ellos **les encantan** las películas de terror.\ne) **Me duele** la cabeza. — le sujet est *la cabeza*.\nf) ¿A ti **te gusta** el fútbol?\nLe verbe s'accorde avec **ce qui plaît**, jamais avec la personne.\n\n**2.**\na) ***A mí también.*** — accord après une affirmation.\nb) ***A mí tampoco.*** — accord après une négation."}$exo$::jsonb),
  ('1bdc719b-8869-511f-9baf-1e876e63c314'::uuid, 2, 'traduction', $exo${"titre":"Le sondage de la classe","consigne":"Rédige les phrases à partir du tableau, puis traduis.","enonce":"**Situation.** Rayan a fait un sondage dans sa classe d'espagnol.\n\n| Élève | Ce qu'il aime | Ce qu'il n'aime pas |\n|---|---|---|\n| Ana | le cinéma (beaucoup) | les maths |\n| Luis | les jeux vidéo (il adore) | lire |\n| Ana et Luis | la musique | se lever tôt |\n\n1. Écris **cinq phrases** en espagnol pour présenter les résultats (commence par *A Ana…*, *A Luis…*, *A Ana y a Luis…*). Emploie *mucho*, *encantar* et *no… nada*.\n2. **Traduis :**\na) Il nous faut deux chaises.\nb) Il me reste peu d'argent.\nc) Je préfère le cinéma au théâtre (*gustar más… que*).","bareme":[{"critere":"Renforcement a + nom avec pronom le ou les conservé","points":5},{"critere":"Accord du verbe avec ce qui plaît dans les cinq phrases","points":6},{"critere":"Degré juste : mucho, encantan, no… nada (jamais muy)","points":3},{"critere":"Traductions justes : nos hacen falta, me queda, me gusta más… que","points":6}],"dureeMin":11,"corrige":"**1.** Phrases attendues :\n- *A Ana **le gusta mucho** el cine.*\n- *A Ana **no le gustan** las matemáticas.* — pluriel.\n- *A Luis **le encantan** los videojuegos.*\n- *A Luis **no le gusta nada** leer.*\n- *A Ana y a Luis **les gusta** la música, pero **no les gusta** levantarse temprano.*\nLe pronom (*le, les*) reste **obligatoire** même quand le nom est exprimé ; le verbe s'accorde avec ce qui plaît.\n\n**2.**\na) ***Nos hacen falta** dos sillas.* — pluriel, accordé avec *dos sillas*.\nb) ***Me queda** poco dinero.*\nc) ***Me gusta más** el cine **que** el teatro.*"}$exo$::jsonb),
  ('1bdc719b-8869-511f-9baf-1e876e63c314'::uuid, 3, 'traduction', $exo${"titre":"Le profil d'Enzo","consigne":"Corrige le texte en justifiant tes corrections, puis rédige un court dialogue en espagnol.","enonce":"**Document.** Enzo se présente sur un site d'échanges linguistiques. Son texte contient **sept erreurs**.\n\n> Hola, me llamo Enzo. Yo gusto el fútbol y me gusta los videojuegos. Mi hermano Juan le gusta el tenis. A mí gusta mucho viajar. Me gusta muy la música. Me gustan leer y escribir. Hoy me duelen la cabeza.\n\n1. Recopie le texte corrigé.\n2. Explique en deux ou trois phrases pourquoi on dit *Me gustan las películas* et non « Me gusta las películas ».\n3. Pour **trois** autres erreurs, explique la correction.\n4. Rédige un dialogue de 6 répliques entre deux élèves qui comparent leurs goûts. Tu dois employer *a mí también*, *a mí tampoco*, *a mí sí*, *a mí no*, un verbe de la famille de *gustar* autre que *gustar* et le renforcement *a* + prénom.","bareme":[{"critere":"Sept erreurs corrigées : me gusta, me gustan, A mi hermano Juan, a mí me gusta, mucho, me gusta leer y escribir, me duele","points":7},{"critere":"Construction inversée expliquée : le sujet est la chose qui plaît","points":4},{"critere":"Trois autres corrections justifiées","points":3},{"critere":"Dialogue : les quatre réponses employées à bon escient, autre verbe et renforcement justes","points":6}],"dureeMin":18,"corrige":"**1.** *Hola, me llamo Enzo. **Me gusta** el fútbol y **me gustan** los videojuegos. **A** mi hermano Juan le gusta el tenis. A mí **me** gusta mucho viajar. Me gusta **mucho** la música. **Me gusta** leer y escribir. Hoy **me duele** la cabeza.*\n\n**2.** Dans la construction de *gustar*, le **sujet** n'est pas la personne mais **la chose qui plaît** ; la personne est un complément (*me, te, le…*). *Las películas* est le sujet, au pluriel : le verbe se met au pluriel, *gustan*.\n\n**3.** Corrections attendues (trois parmi) :\n- « Yo gusto » → *me gusta* : la personne n'est pas le sujet.\n- *A mi hermano Juan le gusta* : le renforcement se fait avec *a* + nom, et *le* reste obligatoire.\n- *A mí me gusta* : le pronom complément est obligatoire même avec *a mí*.\n- *mucho* : on ne dit jamais « me gusta muy ».\n- *Me gusta leer y escribir* : deux infinitifs, verbe au singulier.\n- *Me duele la cabeza* : *la cabeza* est singulier.\n\n**4.** Exemple de dialogue :\n— *Me encanta el baloncesto.* — *A mí también.*\n— *No me gusta nada el invierno.* — *A mí tampoco.*\n— *No me interesan los videojuegos.* — *¡A mí sí!*\n— *Me gusta mucho levantarme tarde.* — *A mí no.*\n— *¿Y a Lucas? — A Lucas le molesta el ruido.*\nOn vérifie : *también* après une affirmation, *tampoco* et *sí* après une négation, *no* après une affirmation, *encantar / interesar / molestar*, *A Lucas le…*"}$exo$::jsonb),
  ('f8b2895f-3aea-562a-9fc3-7f321b927cb1'::uuid, 1, 'traduction', $exo${"titre":"Il faut, je dois","consigne":"Complète avec tener que, hay que ou deber, puis traduis.","enonce":"**1. Complète avec la structure qui convient** (conjuguée au présent si besoin) :\n\na) Para aprobar, … estudiar. (en général)\nb) Yo … ir al médico mañana. (obligation personnelle)\nc) Tú … respetar a tus padres. (devoir moral)\nd) Nosotros … terminar los deberes esta tarde. (obligation personnelle)\n\n**2. Traduis :**\n\na) Il fallait partir tôt.\nb) Il doit être malade. (je suppose)\nc) Ne sors pas ! (tú)","bareme":[{"critere":"Hay que pour l'obligation impersonnelle, tener que conjugué pour l'obligation personnelle","points":8},{"critere":"Deber pour le devoir moral : debes","points":3},{"critere":"Traductions justes : había que, debe de estar, no salgas","points":9}],"dureeMin":7,"corrige":"**1.**\na) Para aprobar, **hay que** estudiar. — obligation impersonnelle, valable pour tous, invariable.\nb) Yo **tengo que** ir al médico mañana. — obligation personnelle.\nc) Tú **debes** respetar a tus padres. — devoir moral.\nd) Nosotros **tenemos que** terminar los deberes esta tarde.\n\n**2.**\na) ***Había que** salir temprano.* — *hay que* à l'imparfait.\nb) ***Debe de estar** enfermo.* — *deber de* + infinitif = probabilité (et non obligation).\nc) *¡**No salgas**!* — ordre direct à l'impératif négatif, au subjonctif."}$exo$::jsonb),
  ('f8b2895f-3aea-562a-9fc3-7f321b927cb1'::uuid, 2, 'traduction', $exo${"titre":"Le règlement de la colonie","consigne":"Traduis les consignes du moniteur en espagnol en choisissant la bonne tournure, puis réponds à la question.","enonce":"**Situation.** Mateo, moniteur d'une colonie de vacances à Cadix, prépare les règles à afficher.\n\n**1. Traduis en espagnol :**\n\na) Il faut arriver à l'heure au repas. (règle générale)\nb) Tu dois ranger ta chambre. (obligation personnelle)\nc) Vous devez respecter les horaires. (*vosotros*, devoir moral)\nd) Il faut que tu viennes à la réunion. (*es necesario que*)\ne) Demain, il faudra partir tôt.\nf) Range ton sac ! (*ordenar*, tú)\n\n**2.** Explique la différence de sens entre :\n*Tenía que estudiar, pero fui al cine.* et *Tuve que estudiar toda la tarde.*","bareme":[{"critere":"Hay que et habrá que pour l'obligation impersonnelle, invariables","points":5},{"critere":"Tener que et deber conjugués justes (tienes que, debéis)","points":5},{"critere":"Es necesario que + subjonctif (vengas) et impératif (ordena) justes","points":5},{"critere":"Nuance imparfait / passé simple expliquée","points":5}],"dureeMin":11,"corrige":"**1.**\na) ***Hay que** llegar a la hora a la comida.*\nb) ***Tienes que** ordenar tu habitación.*\nc) ***Debéis** respetar los horarios.*\nd) ***Es necesario que vengas** a la reunión.* — subjonctif après *es necesario que* (on accepte *Hace falta que vengas*).\ne) *Mañana **habrá que** salir temprano.* — *hay que* au futur, invariable.\nf) *¡**Ordena** tu mochila!* — impératif, ordre direct.\n\n**2.** L'**imparfait** (*tenía que*) dit que l'obligation existait, sans dire si elle a été suivie : ici, elle ne l'a pas été (il est allé au cinéma). Le **passé simple** (*tuve que*) dit que l'obligation a été **exécutée** : il a vraiment étudié tout l'après-midi. L'imparfait laisse ouvert, le passé simple conclut."}$exo$::jsonb),
  ('f8b2895f-3aea-562a-9fc3-7f321b927cb1'::uuid, 3, 'traduction', $exo${"titre":"Conseils à une petite sœur","consigne":"Corrige le texte en justifiant tes corrections, puis rédige une courte lettre en espagnol.","enonce":"**Document.** Lina écrit à sa petite sœur qui entre au collège. Son message contient **six erreurs** sur l'expression de l'obligation.\n\n> Querida Alba: En el colegio, hayan que respetar las normas. Tienes estudiar cada día. Debe de hacer tus deberes antes de cenar (c'est une obligation). Es necesario que vienes puntual. ¡No sales sin tu mochila! Mañana habrán que madrugar.\n\n1. Recopie le message corrigé.\n2. Explique la différence entre *Tengo que trabajar* et *Hay que trabajar*, puis entre *deber* et *deber de*.\n3. Rédige une lettre de 50 mots environ à un ami qui prépare le brevet. Tu dois employer : *tener que*, *hay que*, *deber* (obligation), *deber de* (probabilité), *hace falta que* + subjonctif et un impératif négatif.","bareme":[{"critere":"Six erreurs corrigées : hay que, tienes que, debes, vengas, no salgas, habrá que","points":6},{"critere":"Deux différences expliquées : personnelle / impersonnelle, obligation / probabilité","points":5},{"critere":"Production : tener que, hay que, deber et deber de employés avec le bon sens","points":6},{"critere":"Production : hace falta que + subjonctif et impératif négatif justes","points":3}],"dureeMin":18,"corrige":"**1.** *Querida Alba: En el colegio, **hay que** respetar las normas. **Tienes que** estudiar cada día. **Debes** hacer tus deberes antes de cenar. Es necesario que **vengas** puntual. ¡**No salgas** sin tu mochila! Mañana **habrá que** madrugar.*\nJustifications : *hay que* est invariable ; *tener* est toujours suivi de *que* ; *deber de* dit la probabilité, l'obligation est *deber* ; *es necesario que* + subjonctif ; l'impératif négatif passe au subjonctif ; *habrá que* reste au singulier.\n\n**2.** *Tengo que trabajar* : c'est **moi** qui dois travailler (obligation personnelle). *Hay que trabajar* : il faut travailler **en général**, pour tout le monde (impersonnelle). Le français dit « il faut » dans les deux cas. *Deber* + infinitif exprime l'**obligation** (*Debes estudiar*) ; *deber de* + infinitif exprime la **probabilité** (*Debe de estar enfermo* = je suppose qu'il est malade).\n\n**3.** Exemple de production :\n*Querido Tom: Tienes que repasar cada día. Hay que dormir bien antes de un examen. Debes organizarte. Tu hermano debe de estar orgulloso de ti. Hace falta que descanses el domingo. ¡No estudies toda la noche! Un abrazo.*\nOn vérifie le sens de chaque tournure et le subjonctif après *hace falta que* et à l'impératif négatif."}$exo$::jsonb),
  ('f5569cda-bbdb-5bb1-b176-330b2259d5fe'::uuid, 1, 'traduction', $exo${"titre":"Soler, le verbe de l'habitude","consigne":"Conjugue soler, puis traduis les phrases.","enonce":"**1. Conjugue *soler* au présent**, à toutes les personnes.\n\n**2. Traduis en espagnol :**\n\na) J'ai l'habitude de me lever tôt.\nb) Il pleut d'ordinaire en automne.\nc) Je l'ai rappelé. (*volver a*)\nd) Nous allons de temps en temps à la plage.","bareme":[{"critere":"Soler juste aux six personnes, diphtongue o → ue dans la botte","points":8},{"critere":"Soler + infinitif juste : suelo levantarme, suele llover","points":6},{"critere":"Volver a + infinitif et de vez en cuando justes","points":6}],"dureeMin":7,"corrige":"**1.** *suelo, sueles, suele, **solemos, soléis**, suelen* — *soler* est un verbe à diphtongue (o → ue).\n\n**2.**\na) ***Suelo levantarme** temprano.* — *soler* + infinitif, pronom soudé à l'infinitif.\nb) ***Suele llover** en otoño.*\nc) ***Volví a llamarlo.*** — *volver a* + infinitif remplace le préfixe « re- » français.\nd) *Vamos a la playa **de vez en cuando**.*"}$exo$::jsonb),
  ('f5569cda-bbdb-5bb1-b176-330b2259d5fe'::uuid, 2, 'traduction', $exo${"titre":"L'enfance de la grand-mère","consigne":"Traduis le récit en espagnol en exprimant l'habitude, puis réponds à la question.","enonce":"**Situation.** La grand-mère d'Iris, née à Grenade, raconte son enfance.\n\n**1. Traduis en espagnol :**\n\n> « Quand j'étais petite, j'avais l'habitude d'aller au marché avec ma mère (*soler*). Nous jouions dans la rue. De temps en temps, nous allions à la plage. Presque jamais nous ne mangions au restaurant. Aujourd'hui, je continue à nager tous les étés. »\n\n2. Pourquoi ne peut-on pas écrire « Ayer solí ir al mercado » ?\n3. Quelle est la différence entre *acostumbrar a* et *acostumbrarse a* ?","bareme":[{"critere":"Solía + infinitif et imparfaits d'habitude justes (era, jugábamos, íbamos, comíamos)","points":8},{"critere":"Marqueurs de fréquence justes : de vez en cuando, casi nunca, todos los veranos","points":4},{"critere":"Seguir + gérondif juste : sigo nadando","points":2},{"critere":"Soler impossible au passé simple expliqué ; acostumbrar a / acostumbrarse a distingués","points":6}],"dureeMin":12,"corrige":"**1.** *Cuando **era** pequeña, **solía ir** al mercado con mi madre. **Jugábamos** en la calle. **De vez en cuando**, **íbamos** a la playa. **Casi nunca comíamos** en un restaurante. Hoy **sigo nadando** todos los veranos.*\n- *soler* à l'imparfait (*solía*) + infinitif ; l'**imparfait** seul exprime aussi l'habitude passée.\n- *seguir* + gérondif : l'action qui continue.\n\n**2.** *Soler* ne s'emploie qu'au **présent** et à l'**imparfait**, **jamais** au passé simple ni au futur : une habitude n'est pas un événement ponctuel. On écrit *Ayer fui al mercado* (fait unique) ou *Solía ir al mercado* (habitude).\n\n**3.** *Acostumbrar a* + infinitif = **avoir l'habitude de** (registre soutenu). *Acostumbrarse a* = **s'habituer à** : le sens est différent."}$exo$::jsonb),
  ('f5569cda-bbdb-5bb1-b176-330b2259d5fe'::uuid, 3, 'traduction', $exo${"titre":"Avant et maintenant","consigne":"Corrige le texte en justifiant tes corrections, puis rédige un court texte en espagnol.","enonce":"**Document.** Nathan compare sa vie d'avant et celle d'aujourd'hui. Son texte contient **six erreurs**.\n\n> Cuando era pequeño, solí jugar al fútbol todos los días. Ahora yo solo levantarme tarde los domingos. Mi padre acostumbra de leer el periódico. Ayer rellamé a mi abuela. Sigo estudiar piano. El año que viene soleré ir al gimnasio.\n\n1. Recopie le texte corrigé (pour la dernière phrase, propose une tournure possible au futur).\n2. Pour **quatre** erreurs, explique la règle en une phrase.\n3. Explique la nuance entre *cada día* et *todos los días*.\n4. Rédige 5 phrases en espagnol (50 mots environ) qui comparent ton enfance et ta vie actuelle. Tu dois employer *soler* au présent et à l'imparfait, un imparfait d'habitude, deux marqueurs de fréquence, *volver a* + infinitif et *seguir* + gérondif.","bareme":[{"critere":"Six erreurs corrigées : solía, suelo, acostumbra a, volví a llamar, sigo estudiando, futur sans soler","points":6},{"critere":"Quatre règles expliquées avec justesse","points":4},{"critere":"Nuance cada día / todos los días expliquée","points":2},{"critere":"Production : soler aux deux temps, imparfait d'habitude, volver a et seguir + gérondif justes","points":6},{"critere":"Production : deux marqueurs de fréquence, texte compréhensible","points":2}],"dureeMin":18,"corrige":"**1.** *Cuando era pequeño, **solía** jugar al fútbol todos los días. Ahora **suelo** levantarme tarde los domingos. Mi padre acostumbra **a** leer el periódico. Ayer **volví a llamar** a mi abuela. Sigo **estudiando** piano. El año que viene **iré** (ou *voy a ir*) al gimnasio **a menudo**.*\n\n**2.** Règles attendues (quatre parmi) :\n- *Soler* s'emploie au présent et à l'imparfait (*solía*), jamais au passé simple ni au futur.\n- *Soler* diphtongue : *suelo* (« solo » veut dire « seul »).\n- *Acostumbrar* se construit avec **a** + infinitif.\n- L'espagnol n'a pas de préfixe « re- » productif : *volver a* + infinitif.\n- *Seguir* + **gérondif** exprime l'action qui continue.\n\n**3.** *Cada día* détaille **jour après jour** ; *todos los días* embrasse **l'ensemble** des jours.\n\n**4.** Exemple de production :\n*Cuando era niña, solía pasar las vacaciones en el pueblo. Jugaba siempre con mis primos. Ahora suelo quedarme en la ciudad y a veces vuelvo a visitar el pueblo. Sigo viendo a mis primos en Navidad. Casi nunca me aburro.*\nOn vérifie : *solía / suelo*, *jugaba*, *siempre, a veces, casi nunca*, *vuelvo a visitar*, *sigo viendo*."}$exo$::jsonb),
  ('74393ead-83d3-5ead-bb1e-d23b6f10726e'::uuid, 1, 'traduction', $exo${"titre":"Supposer avec le futur","consigne":"Traduis les phrases en français sans faire de contresens, puis complète avec le mode qui convient.","enonce":"**1. Traduis en français :**\n\na) ¿Qué hora es? — Serán las tres.\nb) Estará enfermo.\nc) Habrá salido.\nd) Tendría veinte años cuando llegó a Madrid.\n\n**2. Conjugue le verbe au mode qui convient :**\n\na) A lo mejor (venir, él) … mañana.\nb) Puede que (llover) … esta tarde.","bareme":[{"critere":"Futur de probabilité traduit par une supposition sur le présent : il doit être trois heures, il doit être malade","points":8},{"critere":"Futur antérieur et conditionnel de probabilité justes : il a dû sortir, il devait avoir vingt ans","points":6},{"critere":"Modes justes : a lo mejor viene (indicatif), puede que llueva (subjonctif)","points":6}],"dureeMin":7,"corrige":"**1.**\na) « Quelle heure est-il ? — **Il doit être** trois heures. » — le futur suppose sur le **présent** (et non « il sera trois heures »).\nb) « **Il doit être** malade (en ce moment). » — contresens fréquent : ce n'est pas « il sera malade ».\nc) « **Il a dû sortir.** » — futur antérieur : supposition sur un fait accompli, vu du présent.\nd) « **Il devait avoir** vingt ans quand il est arrivé à Madrid. » — le conditionnel suppose sur le **passé**.\n\n**2.**\na) A lo mejor **viene** mañana. — *a lo mejor* : **toujours** l'indicatif.\nb) Puede que **llueva** esta tarde. — *puede que* : **toujours** le subjonctif."}$exo$::jsonb),
  ('74393ead-83d3-5ead-bb1e-d23b6f10726e'::uuid, 2, 'traduction', $exo${"titre":"Où est passé Carlos ?","consigne":"Traduis les suppositions en espagnol en utilisant les outils du cours, puis réponds à la question.","enonce":"**Situation.** Carlos devait retrouver ses amis au cinéma à 20 h. Il n'est pas là. Ses amis font des suppositions.\n\n**1. Traduis en espagnol :**\n\na) Il doit être dans le bus. (futur de probabilité)\nb) Il a dû oublier. (futur antérieur : *olvidarse*)\nc) Il devait être huit heures quand il est parti. (conditionnel)\nd) Il doit être fatigué. (*deber de*)\ne) Peut-être qu'il est malade — j'en suis presque sûr. (*quizás*)\nf) Peut-être qu'il vient en taxi — je n'en sais rien. (*quizás*)\n\n**2.** Explique la différence entre *Carlos debe estudiar* et *Carlos debe de estudiar*.","bareme":[{"critere":"Futur et futur antérieur de probabilité justes : estará, se habrá olvidado","points":5},{"critere":"Conditionnel de probabilité sur le passé juste : serían las ocho","points":3},{"critere":"Deber de + infinitif juste : debe de estar cansado","points":3},{"critere":"Quizás + indicatif (forte probabilité) et + subjonctif (faible) justes","points":5},{"critere":"Différence obligation / probabilité expliquée","points":4}],"dureeMin":12,"corrige":"**1.**\na) ***Estará** en el autobús.* — futur pour une supposition sur le présent.\nb) ***Se habrá olvidado.*** — futur antérieur : fait accompli, vu du présent.\nc) ***Serían** las ocho cuando salió.* — conditionnel : supposition sur le passé.\nd) ***Debe de estar** cansado.* — la tournure explicite de probabilité.\ne) ***Quizás está** enfermo.* — indicatif : la probabilité est forte.\nf) ***Quizás venga** en taxi.* — subjonctif : la probabilité est faible.\n\n**2.** *Carlos debe estudiar* : *deber* + infinitif = **obligation** (Carlos doit étudier). *Carlos debe de estudiar* : *deber de* + infinitif = **probabilité** (Carlos doit être en train d'étudier, je suppose)."}$exo$::jsonb),
  ('74393ead-83d3-5ead-bb1e-d23b6f10726e'::uuid, 3, 'traduction', $exo${"titre":"Lucía n'est pas rentrée","consigne":"Traduis le dialogue en français sans contresens, justifie tes choix, puis rédige un court dialogue en espagnol.","enonce":"**Document.** Il est neuf heures du soir. La famille de Lucía l'attend pour dîner.\n\n> — Son las nueve y Lucía no ha llegado.\n> — Estará en el metro, dice su madre.\n> — O habrá perdido el tren.\n> — Debe de estar cansada: ayer serían las doce cuando apagó la luz.\n> — A lo mejor viene en taxi.\n> — Puede que llegue tarde a la cena.\n\n1. Traduis le dialogue en français.\n2. Pour *Estará*, *habrá perdido* et *serían*, explique en une phrase le temps employé et sur quel moment porte la supposition.\n3. Pourquoi *A lo mejor viene* et *Puede que llegue* n'emploient-ils pas le même mode ?\n4. Rédige un dialogue de 6 répliques (50 mots environ) : ton professeur n'est pas arrivé en cours et la classe fait des suppositions. Tu dois employer le futur de probabilité, le futur antérieur, le conditionnel de probabilité, *deber de*, *quizás* (avec le mode de ton choix, justifié) et *puede que*.","bareme":[{"critere":"Traduction sans contresens : il doit être, il a dû perdre, elle doit être, il devait être minuit","points":6},{"critere":"Trois temps de probabilité expliqués avec le moment visé","points":4},{"critere":"Modes après a lo mejor et puede que expliqués","points":3},{"critere":"Production : les six outils employés correctement","points":7}],"dureeMin":18,"corrige":"**1.**\n— Il est neuf heures et Lucía n'est pas arrivée.\n— **Elle doit être** dans le métro, dit sa mère.\n— Ou **elle a dû rater** le train.\n— **Elle doit être** fatiguée : hier, **il devait être** minuit quand elle a éteint la lumière.\n— **Peut-être qu'elle** vient en taxi.\n— **Il se peut qu'elle arrive** en retard au dîner.\n\n**2.**\n- *Estará* : **futur** de probabilité → supposition sur le **présent** (maintenant, elle est sans doute dans le métro).\n- *Habrá perdido* : **futur antérieur** → supposition sur un **fait accompli**, vu du présent.\n- *Serían* : **conditionnel** → supposition sur le **passé** (hier soir).\n\n**3.** Ce sont les deux exceptions absolues : *a lo mejor* est **toujours** suivi de l'**indicatif** ; *puede que* est **toujours** suivi du **subjonctif**.\n\n**4.** Exemple de production :\n— *¿Dónde está el profesor? — Estará en un atasco.*\n— *O se habrá olvidado de la clase.*\n— *Debe de estar enfermo: ayer tosía mucho.*\n— *Serían las ocho cuando salió de casa.*\n— *Quizás venga más tarde* (subjonctif : je n'en sais rien).\n— *Puede que tengamos una hora libre.*\nOn vérifie chaque outil et la justification du mode après *quizás*."}$exo$::jsonb),
  ('5e382289-dd08-546d-99cd-c866e52575ae'::uuid, 1, 'traduction', $exo${"titre":"Donner un ordre","consigne":"Mets les verbes à l'impératif, puis traduis.","enonce":"**1. Donne l'impératif affirmatif à la personne *tú* :**\n\na) *hablar*\nb) *comer*\nc) *vivir*\nd) *hacer*\ne) *decir*\nf) *ir*\ng) *tener*\nh) *salir*\n\n**2. Donne l'impératif négatif (tú) :**\n\na) *hablar*\nb) *comer*\n\n**3. Traduis :** Tu devrais te reposer.","bareme":[{"critere":"Impératifs réguliers justes : habla, come, vive","points":5},{"critere":"Impératifs irréguliers justes : haz, di, ve, ten, sal","points":8},{"critere":"Impératif négatif au subjonctif : no hables, no comas","points":4},{"critere":"Conseil ferme juste : deberías descansar","points":3}],"dureeMin":7,"corrige":"**1.**\na) **habla** b) **come** c) **vive** d) **haz** e) **di** f) **ve** g) **ten** h) **sal**\n\n**2.**\na) **no hables** b) **no comas** — l'impératif négatif passe **toujours** au subjonctif.\n\n**3.** ***Deberías descansar.*** — *deberías* + infinitif : le conseil ferme, plus poli que l'impératif."}$exo$::jsonb),
  ('5e382289-dd08-546d-99cd-c866e52575ae'::uuid, 2, 'traduction', $exo${"titre":"Aider Lola en maths","consigne":"Rédige les conseils demandés en espagnol, du plus direct au plus poli, puis transforme les phrases.","enonce":"**Situation.** Lola a eu 6 sur 20 à son contrôle de maths. Ses amis lui donnent des conseils.\n\n**1. Écris un conseil pour Lola** avec chaque structure :\n\na) l'impératif (*estudiar*)\nb) *deberías* + infinitif (*hacer ejercicios*)\nc) *podrías* + infinitif (*pedir ayuda al profesor*)\nd) *¿Por qué no…?* (*ir a la biblioteca*)\ne) *¿Y si…?* (*estudiar juntas*)\nf) *Te aconsejo que* + subjonctif (*repasar cada día*)\n\n**2. Transforme** à l'impératif négatif, en déplaçant les pronoms :\n\na) ¡Dímelo!\nb) ¡Cómpralo!","bareme":[{"critere":"Impératif, deberías et podrías + infinitif justes","points":6},{"critere":"¿Por qué no…? et ¿Y si…? suivis de l'indicatif","points":4},{"critere":"Te aconsejo que + subjonctif juste : repases","points":4},{"critere":"Impératifs négatifs avec pronoms devant : no me lo digas, no lo compres","points":6}],"dureeMin":11,"corrige":"**1.**\na) *¡**Estudia** más!* — l'ordre.\nb) ***Deberías hacer** ejercicios.* — le conseil ferme.\nc) ***Podrías pedir** ayuda al profesor.* — la suggestion.\nd) *¿**Por qué no vas** a la biblioteca?* — la question, à l'indicatif.\ne) *¿**Y si estudiamos** juntas?* — l'invitation, **indicatif**.\nf) ***Te aconsejo que repases** cada día.* — après un verbe de conseil, subjonctif (le sujet change).\n\n**2.**\na) *¡**No me lo digas**!*\nb) *¡**No lo compres**!*\nL'affirmatif soude les pronoms au verbe ; le négatif passe au subjonctif et place les pronoms **devant**."}$exo$::jsonb),
  ('5e382289-dd08-546d-99cd-c866e52575ae'::uuid, 3, 'traduction', $exo${"titre":"La lettre à un ami inquiet","consigne":"Corrige le texte en justifiant tes corrections, puis rédige une courte lettre en espagnol.","enonce":"**Document.** Malik répond à son correspondant Pedro, qui est stressé avant un examen. Sa lettre contient **sept erreurs**.\n\n> Querido Pedro: ¡No habla tanto de tus nervios! Te aconsejo que descansas este fin de semana. Hace tus deberes con calma. Si tienes un problema, ¡me lo di! Yo que tú, iré al cine. Ojalá puedo ayudarte, pero estoy lejos. ¿Y si salgamos juntos en verano?\n\n1. Recopie la lettre corrigée.\n2. Pour **quatre** erreurs, explique la règle en une phrase.\n3. Quelle nuance sépare *Ojalá apruebes* et *Ojalá pudiera ayudarte* ?\n4. Rédige une lettre de 50 mots environ à un ami qui veut arrêter le sport. Tu dois employer au moins quatre barreaux de l'échelle du conseil (dont l'impératif négatif), *te recomiendo que* + subjonctif et *yo que tú* + conditionnel.","bareme":[{"critere":"Sept erreurs corrigées : no hables, descanses, haz, dímelo, iría, pudiera, salimos","points":7},{"critere":"Quatre règles expliquées avec justesse","points":4},{"critere":"Nuance ojalá + subjonctif présent / imparfait expliquée","points":3},{"critere":"Production : quatre structures de l'échelle, te recomiendo que + subjonctif, yo que tú + conditionnel","points":6}],"dureeMin":18,"corrige":"**1.** *Querido Pedro: ¡**No hables** tanto de tus nervios! Te aconsejo que **descanses** este fin de semana. **Haz** tus deberes con calma. Si tienes un problema, ¡**dímelo**! Yo que tú, **iría** al cine. Ojalá **pudiera** ayudarte, pero estoy lejos. ¿Y si **salimos** juntos en verano?*\n\n**2.** Règles attendues (quatre parmi) :\n- L'impératif **négatif** passe au subjonctif : *no hables*.\n- Après *te aconsejo que*, le **subjonctif** : *descanses*.\n- *Hacer* a un impératif irrégulier : *haz* ; *decir* aussi : *di*.\n- L'impératif affirmatif **soude** les pronoms : *dímelo*.\n- *Yo que tú* se poursuit au **conditionnel** : *iría*.\n- *¿Y si…?* est suivi de l'**indicatif** : *salimos*.\n\n**3.** *Ojalá* + **subjonctif présent** (*apruebes*) : un souhait **possible**. *Ojalá* + **imparfait du subjonctif** (*pudiera*) : un souhait **improbable** — « si seulement je pouvais ».\n\n**4.** Exemple de production :\n*Querida Sara: ¡No dejes el baloncesto! Deberías hablar con tu entrenador. Podrías probar otro equipo. ¿Por qué no vienes a mi club? Te recomiendo que lo pienses bien. Yo que tú, seguiría un año más. ¡Ánimo!*\nOn vérifie : impératif négatif, *deberías*, *podrías*, *¿por qué no…?*, *te recomiendo que* + subjonctif, *yo que tú* + conditionnel."}$exo$::jsonb),
  ('d454d337-de4f-53b3-961e-2709bef04b4a'::uuid, 1, 'traduction', $exo${"titre":"Les trois conjugaisons","consigne":"Conjugue les verbes au présent de l'indicatif.","enonce":"**1. Conjugue au présent**, à toutes les personnes :\n\na) *hablar*\nb) *comer*\nc) *vivir*\n\n**2. Donne la première personne (yo) du présent :**\n\na) *hacer*\nb) *conocer*\nc) *salir*\nd) *saber*\ne) *dar*\nf) *poner*","bareme":[{"critere":"Hablar, comer et vivir justes aux six personnes, accents de habláis et coméis","points":12},{"critere":"Six premières personnes irrégulières justes : hago, conozco, salgo, sé, doy, pongo","points":8}],"dureeMin":7,"corrige":"**1.**\na) *hablo, hablas, habla, hablamos, habláis, hablan*\nb) *como, comes, come, comemos, coméis, comen*\nc) *vivo, vives, vive, vivimos, vivís, viven*\nLes verbes en *-er* et *-ir* ne diffèrent qu'à *nosotros* et *vosotros*.\n\n**2.**\na) **hago** b) **conozco** (comme tous les verbes en *-cer*, *-cir*) c) **salgo** d) **sé** (avec accent) e) **doy** f) **pongo**\nCe sont des verbes « à *yo* irrégulier » : le reste de la conjugaison est régulier."}$exo$::jsonb),
  ('d454d337-de4f-53b3-961e-2709bef04b4a'::uuid, 2, 'traduction', $exo${"titre":"La présentation de Mateo","consigne":"Complète le texte avec les verbes au présent, puis réponds aux questions.","enonce":"**Situation.** Mateo, élève à Tolède, se présente à sa classe d'échange.\n\n> Me llamo Mateo y (tener) … quince años. (Ser) … de Toledo. Todos los días (salir) … de casa a las ocho y (ir) … al instituto en autobús. (Conocer) … a muchos alumnos. Mi hermana y yo (hacer) … los deberes juntos. Mis padres (estar) … muy contentos. (Estudiar) … francés desde hace dos años. Mañana (venir) … mi primo de Madrid. ¿Tú (saber) … dónde (estar) … el museo?\n\n1. Recopie les onze verbes conjugués.\n2. Pourquoi *están* porte-t-il un accent écrit ?\n3. Quels sont les **deux** emplois du présent, autres que l'action en cours, qui apparaissent dans le texte ?","bareme":[{"critere":"Premières personnes irrégulières et cumulards justes : tengo, soy, salgo, voy, conozco, vengo ou viene","points":8},{"critere":"Autres formes justes : hacemos, están, estudio, sabes, está","points":5},{"critere":"Accent de estar expliqué : l'accent tonique tombe sur la terminaison","points":3},{"critere":"Deux emplois repérés : action commencée dans le passé (desde hace), futur proche (mañana)","points":4}],"dureeMin":12,"corrige":"**1.** *tengo* — *Soy* — *salgo* — *voy* — *Conozco* — *hacemos* — *están* — *Estudio* — *viene* — *sabes* — *está*.\n- *tengo* : *tener* cumule un *yo* irrégulier et une diphtongue.\n- *soy*, *voy* : verbes totalement irréguliers.\n- *salgo*, *conozco* : *yo* irrégulier.\n- *viene* : 3e personne de *venir* (diphtongue).\n\n**2.** *Estar* porte un accent écrit sur ses formes *estás, está, estáis, están* car l'accent tonique tombe sur la **terminaison**, contrairement aux autres verbes. L'oublier est une faute d'orthographe.\n\n**3.**\n- *Estudio francés desde hace dos años* : une action **commencée dans le passé** et qui dure.\n- *Mañana viene mi primo* : le présent pour un **futur proche**."}$exo$::jsonb),
  ('d454d337-de4f-53b3-961e-2709bef04b4a'::uuid, 3, 'traduction', $exo${"titre":"Le portrait de Jade","consigne":"Corrige le texte en justifiant tes corrections, puis rédige un court texte en espagnol.","enonce":"**Document.** Jade se présente à sa correspondante de Burgos. Son texte contient **sept erreurs** de conjugaison au présent.\n\n> Hola, me llamo Jade. Tieno catorce años y vivemos en Lyon. Los sábados yo hazo deporte y conoco a muchos chicos del club. Mi padre esta cansado porque trabaja mucho. Yo no sabo cocinar, pero mi madre y yo tienemos un blog de recetas.\n\n1. Recopie le texte corrigé.\n2. Classe les sept erreurs en trois familles : *yo* irrégulier, verbe du radical ou cumulard, autre (orthographe ou terminaison).\n3. Explique pourquoi connaître la première personne du présent « débloque » d'autres temps.\n4. Rédige 5 phrases en espagnol (50 mots environ) pour te présenter. Tu dois employer : trois verbes à *yo* irrégulier différents, un cumulard (*tener, venir, decir*), *estar* avec son accent, un présent de futur proche et *desde hace*.","bareme":[{"critere":"Sept erreurs corrigées : tengo, vivimos, hago, conozco, está, sé, tenemos","points":7},{"critere":"Erreurs classées avec justesse","points":3},{"critere":"Lien avec le subjonctif expliqué (les irrégularités de yo se propagent)","points":3},{"critere":"Production : les cinq éléments demandés corrects","points":7}],"dureeMin":18,"corrige":"**1.** *Hola, me llamo Jade. **Tengo** catorce años y **vivimos** en Lyon. Los sábados yo **hago** deporte y **conozco** a muchos chicos del club. Mi padre **está** cansado porque trabaja mucho. Yo no **sé** cocinar, pero mi madre y yo **tenemos** un blog de recetas.*\n\n**2.**\n- *Yo* irrégulier : **hago**, **conozco**, **sé**.\n- Verbe du radical / cumulard : **tengo** (cumulard : *yo* irrégulier), **tenemos** (pas de diphtongue à *nosotros* — ni « tienemos »).\n- Autre : **vivimos** (terminaison des verbes en *-ir* à *nosotros*) ; **está** (accent écrit obligatoire).\n\n**3.** Le **subjonctif présent** se construit à partir de la première personne du présent : les irrégularités de *yo* se propagent à tout le subjonctif (*hago* → *haga*, *tengo* → *tenga*, *conozco* → *conozca*).\n\n**4.** Exemple de production :\n*Me llamo Noé y vivo en Rennes. Estudio español desde hace tres años. Los lunes salgo del colegio a las cinco, hago los deberes y pongo la mesa. Tengo dos hermanos. Mañana voy a la piscina y mis amigos están muy contentos.*\nOn vérifie : *salgo, hago, pongo* (yo irrégulier), *tengo* (cumulard), *están* (accent), *mañana voy* (futur proche), *desde hace*."}$exo$::jsonb),
  ('ecad9066-b13d-5a01-81ef-89902b7fe6ee'::uuid, 1, 'traduction', $exo${"titre":"La voyelle qui bascule","consigne":"Forme le subjonctif présent des verbes, puis traduis la phrase.","enonce":"**1. Conjugue au subjonctif présent**, à toutes les personnes :\n\na) *hablar*\nb) *comer*\n\n**2. Donne la forme demandée du subjonctif présent :**\n\na) yo (hacer)\nb) él (tener)\nc) yo (ser)\nd) nosotros (ir)\ne) tú (estar)\n\n**3. Traduis :** Quand tu arriveras, appelle-moi.","bareme":[{"critere":"Hablar et comer justes aux six personnes, voyelle inversée (e / a)","points":8},{"critere":"Cinq formes justes : haga, tenga, sea, vayamos, estés","points":7},{"critere":"Traduction avec cuando + subjonctif : Cuando llegues, llámame","points":5}],"dureeMin":8,"corrige":"**1.**\na) *hable, hables, hable, hablemos, habléis, hablen* — verbe en *-ar* : terminaisons en **e**.\nb) *coma, comas, coma, comamos, comáis, coman* — verbe en *-er* : terminaisons en **a**.\n\n**2.**\na) **haga** — on part de *hago*.\nb) **tenga** — on part de *tengo*.\nc) **sea**\nd) **vayamos**\ne) **estés**\n*Ser, ir, estar* font partie des six irréguliers (*sea, vaya, haya, sepa, dé, esté*).\n\n**3.** ***Cuando llegues, llámame.*** — futur dans une subordonnée de temps : **subjonctif présent**, jamais « cuando llegarás »."}$exo$::jsonb),
  ('ecad9066-b13d-5a01-81ef-89902b7fe6ee'::uuid, 2, 'traduction', $exo${"titre":"Les consignes avant le voyage","consigne":"Complète le message avec les verbes au subjonctif présent, puis réponds aux questions.","enonce":"**Situation.** Avant le voyage de classe d'Ana à Madrid, sa mère lui laisse un message.\n\n> Ana: quiero que me (llamar, tú) … cada noche. Es necesario que (hacer, tú) … la maleta hoy. Cuando (llegar, tú) … al hotel, escríbeme. Te lo digo para que lo (saber, tú) … : no creo que (hacer) … frío allí. Me alegro de que (ir, tú) … a Madrid. Antes de que (salir, tú) … , cierra la puerta. Y espero que tus amigas y tú lo (pasar) … muy bien.\n\n1. Recopie les huit verbes au subjonctif.\n2. Pour **quatre** d'entre eux, nomme le déclencheur du subjonctif (volonté, sentiment, doute, jugement impersonnel, futur dans une subordonnée de temps, but, conjonction).\n3. Pourquoi *cuando* est-il suivi du subjonctif dans ce message ?","bareme":[{"critere":"Huit subjonctifs justes : llames, hagas, llegues, sepas, haga, vayas, salgas, paséis","points":10},{"critere":"Quatre déclencheurs identifiés avec justesse","points":6},{"critere":"Cuando + subjonctif expliqué par la valeur de futur","points":4}],"dureeMin":12,"corrige":"**1.** *llames* — *hagas* — *llegues* — *sepas* — *haga* — *vayas* — *salgas* — *paséis*.\n\n**2.** Déclencheurs :\n- *quiero que me llames* : **volonté**.\n- *es necesario que hagas* : **jugement impersonnel**.\n- *cuando llegues* : **futur dans une subordonnée de temps**.\n- *para que lo sepas* : **but**.\n- *no creo que haga* : **doute, négation d'opinion**.\n- *me alegro de que vayas* : **sentiment**.\n- *antes de que salgas* : **conjonction** qui l'exige toujours.\n- *espero que lo paséis* : **souhait**.\n\n**3.** *Cuando llegues* renvoie à un moment **futur** (l'arrivée n'a pas encore eu lieu) : en espagnol, une subordonnée de temps à valeur de futur se met au **subjonctif présent**, là où le français emploie le futur (« quand tu arriveras »)."}$exo$::jsonb),
  ('ecad9066-b13d-5a01-81ef-89902b7fe6ee'::uuid, 3, 'traduction', $exo${"titre":"La lettre de Maxime","consigne":"Corrige le texte en justifiant tes corrections, puis rédige une courte lettre en espagnol.","enonce":"**Document.** Maxime écrit à sa correspondante de Valladolid, qui va venir en France. Sa lettre contient **sept erreurs**.\n\n> Querida Irene: Cuando llegarás a París, te enseñaré la ciudad. Quiero que vienes a mi colegio. Te escribo para que lo sabes todo. No creo que es difícil. Espero que tú pides tu pasaporte pronto. Es necesario que estamos en la estación a las diez. Ojalá hace buen tiempo.\n\n1. Recopie la lettre corrigée.\n2. Pour **quatre** erreurs, nomme le déclencheur du subjonctif.\n3. Explique la formation de *pidas* (verbe à affaiblissement) et celle de *vengas*.\n4. Rédige une lettre de 50 mots environ pour inviter un ami espagnol chez toi. Tu dois employer le subjonctif après cinq déclencheurs différents, dont *cuando* à valeur de futur et une conjonction qui l'exige toujours (*para que, antes de que, sin que…*).","bareme":[{"critere":"Sept erreurs corrigées : llegues, vengas, sepas, sea, pidas, estemos, haga","points":7},{"critere":"Quatre déclencheurs nommés avec justesse","points":4},{"critere":"Formation de pidas et vengas expliquée (première personne du présent, voyelle inversée)","points":3},{"critere":"Production : cinq déclencheurs différents suivis d'un subjonctif juste","points":6}],"dureeMin":18,"corrige":"**1.** *Querida Irene: Cuando **llegues** a París, te enseñaré la ciudad. Quiero que **vengas** a mi colegio. Te escribo para que lo **sepas** todo. No creo que **sea** difícil. Espero que tú **pidas** tu pasaporte pronto. Es necesario que **estemos** en la estación a las diez. Ojalá **haga** buen tiempo.*\n\n**2.** Déclencheurs (quatre parmi) :\n- *cuando llegues* : futur dans une subordonnée de temps (le piège majeur du francophone).\n- *quiero que vengas* : volonté.\n- *para que lo sepas* : but (conjonction qui exige toujours le subjonctif).\n- *no creo que sea* : doute, négation d'opinion.\n- *espero que pidas* : souhait.\n- *es necesario que estemos* : jugement impersonnel.\n- *ojalá haga* : souhait.\n\n**3.**\n- *pidas* : on part de la première personne *pido*, on retire le *-o* et on inverse la voyelle (*-ir* → **a**) ; l'affaiblissement touche **toutes** les personnes du subjonctif (*pidamos*, *pidáis*).\n- *vengas* : on part de *vengo* : l'irrégularité de *yo* se propage à tout le subjonctif.\n\n**4.** Exemple de production :\n*Querido Álex: Quiero que vengas a mi casa en julio. Cuando llegues, iremos a la playa. Te lo digo antes de que compres el billete. Me alegro de que puedas venir. Es importante que traigas un bañador. ¡Ojalá haga sol!*\nOn vérifie : volonté, *cuando* + futur, *antes de que*, sentiment, jugement impersonnel, *ojalá*, avec des subjonctifs justes."}$exo$::jsonb)
